P.entries["npc:maybell-maclure"] = {n="Мейбелл Маклур",s="Мейбелл Маклур — молода жінка, що живе на Виноградниках Маклюрів у Лісі Елвінн. Попри гірку, давню ворожнечу між її родиною та сусідами Стоунфілдами, вона потай закохалася в Томмі Джо Стоунфілда.",h="Мейбелл Маклур — молода жінка, що живе на Виноградниках Маклюрів у Лісі Елвінн.",kw={"мейбелл маклур","томмі джо","виноградники маклюрів","кохання","лікер невидимості","ворожнеча"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що проходять Лісом Елвінн, роман Мейбелл — нагадування, що особисті біди й давні образи живуть навіть у серці королівства."},sec={{t="Нещасливе кохання на виноградниках",b="Життя на Виноградниках Маклюрів — це нескінченна праця й незгасна образа на сусідню родину Стоунфілдів. Між двома вогнями опинилася Мейбелл Маклур, яка глибоко закохалася в Томмі Джо Стоунфілда, молодого спадкоємця ворожої садиби. Розлучена з ним пильною ріднею й давньою родинною неприязню, Мейбелл відчайдушно шукає будь-якої нагоди передати Томмі Джо хоч слово подалі від цікавих очей своїх рідних."},{t="Зілля для справжнього кохання",b="Не маючи змоги відкрито перетнути межу між фермами, Мейбелл покладається на співчутливих подорожніх і настанови Бабусі Стоунфілд. З допомогою ґолдширського алхіміка Вільяма Пестла вариться лікер невидимості. Випивши цей заборонений трунок, Мейбелл може непомітно вислизнути із садиби Маклурів і вкрасти дорогоцінні хвилини з Томмі Джо на березі річки."}},faq={{q="Чому Мейбелл і Томмі Джо не можуть бачитися?",a="Родини Маклурів і Стоунфілдів уже багато років запекло ворогують. Оскільки обидві родини забороняють будь-які стосунки між собою, Мейбелл і Томмі Джо мусять тримати своє кохання в цілковитій таємниці, інакше на них упаде гнів рідні.",al={"чому ворожнеча родин","ворожнеча маклурів і стоунфілдів","чому вони не можуть бути разом"}},{q="What prevents Maybell from leaving the vineyard?",a="Her family watches her closely because of the feud with the Stonefields. She needs help finding a way to meet Tommy Joe without attracting their attention.",al={"як мейбелл утікає","зілля невидимості елвінн","як вона зустрічає томмі"}},{q="Де Мейбелл зустрічається з Томмі Джо?",a="Томмі Джо чекає на березі річки на межі між Виноградниками Маклюрів і Фермою Стоунфілдів, де їх не видно з жодного хутора.",al={"місце зустрічі","де вони зустрічаються","де томмі джо"}},{q="Хто допомагає Мейбелл у її коханні?",a="Бабуся Стоунфілд співчуває закоханим і посилає охочих шукачів пригод до Вільяма Пестла, алхіміка з Ґолдшира, який дає їм змогу таємно зустрітися.",al={"хто допомагає мейбелл","помічники стоунфілдів"}}},fp="15,230,29.425.0,26.383.1,47.236.0,48.155.1,34.152.0,35.189.1"}
P.entries["npc:mebok-mizzyrix"] = {n="Мебок Міззірікс",s="Мебок Міззірікс — заповзятливий гоблін-ділок, що живе в портовому містечку Раджет. Завжди готовий перетворити дивовижні дикі інгредієнти на прибуток, він наймає мандрівних шукачів пригод збирати незвичайні рослини й тварин по всіх Пустках і далі. Найславетніший його задум — комерційний напій для поліпшення розуму з рогів рапторів.",h="Мебок Міззірікс — заповзятливий гоблін-ділок, що живе в портовому містечку Раджет.",kw={"мебок міззірікс","гоблін","раджет","розумні напої","роги рапторів","синьолисті бульби"},ang={["faction:Alliance"]="Зійшовши з корабля з Буті Бей у нейтральному Раджеті, мандрівники Альянсу можуть братися за доручення Мебока, не боячись ворожої варти.",["faction:Horde"]="Для мандрівників Орди, що проходять Раджетом на шляху через Пустки, Мебок — легкий заробіток на винищенні небезпечних звірів поблизу.",["profession:Cooking"]="Кулінари вважатимуть рецепти страв і напоїв Мебока щонайменше сумнівними, адже він наполягає на товченому розі раптора.",["profession:Herbalism"]="Захоплення Мебока дивними зразками на кшталт Синьолистих бульб показує дикішу, комерційну сторону збирання унікальних рослин Калімдору."},sec={{t="Заповзятливий алхімік",b="Мебок Міззірікс, що веде справи в гамірному нейтральному порту Раджет, утілює класичний дух картелю Стімвідл — невтомне вміння скористатися будь-якою нагодою. Раджет обслуговує моряків, піратів і торговців усіх мастей, а Мебок пильно придивляється до дикої природи Калімдору. Замість добувати звичайну руду чи торгувати буденним полотном, він шукає рідкісні біологічні дивовижі, з яких, на його думку, можна виготовити дуже прибуткові зілля й товари."},{t="У пошуках розумних напоїв",b="Головний комерційний задум Мебока — власний «розумний напій», що мав би штучно підсилювати розум того, хто його вип'є. Переконаний, що природна хитрість і лютість місцевих рапторів походять від рогів на їхніх мордах, Мебок наймає мисливців добувати цілі роги по всіх Пустках. Для нього етика й смак відходять на задній план перед ринковими можливостями — аби тільки платні покупці вірили, що напій діє."},{t="Екзотичні інгредієнти й рослини",b="Окрім еліксирів із рапторів, Мебокові постійно потрібні й інші дивовижні зразки. Від збирання неспокійних яєць глибокомохових павуків до пошуків рідкісних Синьолистих бульб, захованих глибоко в терновиках Рейзорфен Краула, — його забаганки раз у раз заводять відчайдушних найманців у небезпечні краї. Якщо в якоїсь істоти є дивні властивості, Мебок певен: її можна розлити в пляшки й продати."}},faq={{q="Хто такий Мебок Міззірікс?",a="Мебок Міззірікс — гоблін-торговець і алхімічний пройдисвіт із нейтрального портового містечка Раджет у Пустках. Він наймає шукачів пригод збирати дивних тварин і частини рослин для своїх торгових задумів.",al={"хто такий мебок","лор мебока міззірікса","гоблін раджета мебок"}},{q="Що таке «Розумні напої»?",a="«Розумні напої» — дослідні тоніки для гостроти розуму, які Мебок Міззірікс сподівається зварити й продавати. Він вірить, що розтерті роги кмітливих ящерів Пусток передадуть тому, хто їх вип'є, їхні гострі інстинкти й хитрість.",al={"розумні напої","завдання розумних напоїв","зілля з рога раптора"}},{q="Де знайти Мебока Міззірікса?",a="Він стоїть серед будівель портового міста Раджет на східному узбережжі Пусток, куди можуть приходити мандрівники і з Орди, і з Альянсу.",al={"місце мебока","де мебок","знайти мебока міззірікса"}},{q="Навіщо Мебокові роги ящерів?",a="Мебок припускає, що хитрий розум ящерів, які блукають Пустками, зосереджений у їхніх рогах. Він збирається розтерти їх на порошок як головну діючу речовину своїх напоїв для розуму.",al={"навіщо роги раптора","призначення рогів раптора","що мебок робить із рогами"}},{q="Чому Мебок посилає людей до Рейзорфен Краулу?",a="Він наймає шукачів пригод спуститися до Рейзорфен Краулу й за допомогою навченого нюхача викопати бульби синьолисту — рідкісної рослини з цінними й незвичайними властивостями.",al={"чому рейзорфен краул","мебок завдання краул","бульби синьолисту краул"}},{q="Мебок працює на Орду чи на Альянс?",a="Мебок — незалежний член картелю Стімвідл у нейтральному Раджеті. Він вірний лише монеті й охоче торгує та укладає угоди з членами обох фракцій.",al={"чи мебок з орди","чи мебок з альянсу","фракція мебока"}}},fp="14,360,25.445.0,26.443.0,25.422.0,22.219.0,22.218.0,34.159.0,33.217.0,45.176.0,46.165.0"}
P.entries["npc:melithar-staghelm"] = {n="Мелітар Стаґгелм",s="Мелітар Стаґгелм — нічний ельф, що перебуває одразу за Алдрассилом у Тінедолі, стартовій долині Тельдрассила. Він допомагає молодим нічним ельфам — шукачам пригод на початку навчання, посилаючи їх до поблизьких учителів і залагоджуючи дрібні місцеві негаразди. Хоч він носить відоме прізвище Стаґгелм, як і Архідруїд Фандрал Стаґгелм, його точний зв'язок із провідним друїдом лишається непідтвердженим.",h="Мелітар Стаґгелм — нічний ельф, що перебуває одразу за Алдрассилом у Тінедолі, стартовій долині Тельдрассила.",kw={"мелітар стаґгелм","стаґгелм","алдрассил","тінедол","тельдрассил","фандрал стаґгелм","провідник"},ang={["race:NightElf"]="Для нічних ельфів, що починають подорож у Тінедолі, Мелітар — одна з найперших постатей, яких вони зустрічають, покинувши прихисток Алдрассила."},sec={{t="Провідник біля Алдрассила",b="Стоячи просто перед входом до великої гілки Алдрассила, Мелітар — одна з перших постатей, з якими стикаються нічні ельфи, виходячи у світ. Він спрямовує щойно пробуджену молодь із різними сигілами до відповідних класових наставників, щоб ті дістали належну науку бойових і містичних мистецтв. Окрім розпорядчих настанов, Мелітар пильнує найближчі угіддя Тінедолу і шукає помічників, щоб упоратися з бешкетливою тутешньою звіриною й дрібними бісуватими вторгненнями, що загрожують спокою святилища."},{t="Ім'я Стаґгелмів",b="Прізвище Стаґгелм неминуче привертає увагу, адже Архідруїд Фандрал Стаґгелм нині очолює Коло Кенарія в Дарнасусі після зникнення Малфуріона Стормрейджа у Смарагдовому Сні. Та Мелітар не вихваляється величним походженням і не говорить про свій рід. Чи він далекий родич шанованої родини Архідруїда, чи просто носить прадавнє калдорейське родове ім'я, Мелітар задовольняється скромними обов'язками біля коріння Алдрассила."}},faq={{q="Хто такий Мелітар Стаґгелм?",a="Мелітар Стаґгелм — нічний ельф, що дає завдання на стежці біля гілки Алдрассила в Тінедолі. Він допомагає новоприбулим нічним ельфам-шукачам пригод зорієнтуватися й направляє їх до наставників.",al={"мелітар","хто такий мелітар","мелітар тінеділ"}},{q="Чи Мелітар родич Архідруїда Фандрала Стаґгелма?",a="Точна спорідненість невідома. Хоча вони носять одне ім'я Стаґгелм, Мелітар ніколи не згадує про родинний зв'язок з Архідруїдом Фандралом Стаґгелмом чи його покійним сином Валстанном. Незрозуміло, чи він далекий родич, чи просто має поширене калдорейське прізвище.",al={"рідня фандрала","брат фандрала","рід стаґгелм"}},{q="Яку роль Мелітар відіграє для новачків?",a="Нічних ельфів-новачків посилають до Мелітара з їхніми вступними знаками. Мелітар приймає ці знаки й вказує кожному новачкові на потрібного наставника в Алдрассилі, щоб той почав справжнє навчання свого класу.",al={"завдання мелітара","завдання сигілів","що робить мелітар"}},{q="Де знайти Мелітара Стаґгелма?",a="Він стоїть просто на дерев'яному пандусі біля входу до Алдрассила, у центрі Тінедолу на Тельдрассилі.",al={"місце мелітара","де мелітар","знайти мелітара стаґгелма"}}},fp="17,406,20.531.0,17.508.0,25.218.0,50.260.0,49.215.0,35.115.0"}
P.entries["npc:melor-stonehoof"] = {n="Мелор Стоунгуф",s="Мелор Стоунгуф — бувалий тауренський мисливець, що несе службу на Узвишші Мисливців у Тандер Блафі. Як наставник у мисливському мистецтві, він перевіряє, як мисливці Орди вміють вистежувати здобич і чи вистачає їм мужності, посилаючи їх за найнебезпечнішими хижаками Пусток і Тисячі Голок.",h="Мелор Стоунгуф — бувалий тауренський мисливець, що несе службу на Узвишші Мисливців у Тандер Блафі.",kw={"мелор стоунгуф","мисливець","узвишшя мисливців","тандер блаф","полювання","мертвобагно"},ang={["class:Hunter"]="Мелор — один із головних провідників, що дають завдання мисливцям Орди: він веде вас крізь обряди вистежування, які втілюють священний шлях мисливця.",["faction:Horde"]="Мелор дбає, щоб воїни й слідопити всієї Орди були загартовані проти диких звірів, що загрожують поселенням від Малгору до Тисячі Голок.",["race:Tauren"]="Мелор, що несе службу високо на Узвишші Мисливців, утілює глибоку шану вашого народу до полювання — і як до випробування сили, і як до рівноваги із Земною Матір'ю."},sec={{t="Наставник дикої природи",b="Зі свого місця на вітряних просторах Узвишшя Мисливців Мелор Стоунгуф досвідченим оком оглядає рівнини внизу. Для тауренів полювання священне: воно переплетене з виживанням, духовною рівновагою й шаною до найбільших хижаків природи. Мелор дбає, щоб ті, хто носить лук і клинок в ім'я Орди, розуміли цю рівновагу, і посилає здібних слідопитів відточувати майстерність у випробуваннях із легендарними звірами."},{t="Мисливські випробування",b="Мелор кидає мисливцям виклик: вистежити легендарних і невловних звірів, що тероризують дикі краї. Він посилає слідопитів рівнинами Пусток — від допомоги мисливиці Серґрі Даркторн на Перехресті до погоні за Стілснепом, хитрою й лютою гієною в Тисячі Голок. У цих випробуваннях мисливці доводять, що здатні перехитрити й здолати найсмертоносніших істот центрального Калімдору."},{t="Чудовиська далеких земель",b="Тим, чия майстерність переросла Пустки, Мелор вказує на далекі краї. Він доручає бувалим мисливцям здолати звірів жахливої сили — серед них Мертвобагно, прадавнього кроколіска, що причаївся в болотах Багна Пилоброду, і лютого єті Морозопащу з Гір Альтерак. Кожне полювання перевіряє, чи справді слідопит опанував Шлях Мисливця."}},faq={{q="Де знайти Мелора Стоунгуфа?",a="Мелор Стоунгуф — на Узвишші Мисливців у місті Тандер Блаф. Узвишшя Мисливців — найсхідніше плато тауренської столиці, куди можна дістатися мотузяними мостами з центрального плато з тотемом.",al={"місце мелора стоунгуфа","де мелор","координати мелора"}},{q="Які завдання дає Мелор Стоунгуф?",a="Мелор пропонує низку мисливських випробувань для шукачів пригод середнього рівня: посилає гравців до Серґри Даркторн у Пустках, на полювання на люту гієну Стілснеп і на вистежування грізних звірів далі від дому — кроколіска Мертвобагно в Багні Пилоброду та єті Морозопащу в Горах Альтерак.",al={"завдання мелора","що робить мелор","ланцюжок завдань мелора"}},{q="Чому Мелор посилає мисливців на Стілснеп?",a="Стілснеп — сумно відома лютістю й хитрістю гієна, що нишпорить Тисячею Голок. Мелор посилає вправних мисливців вистежити й убити її як перевірку майстерності, витривалості й відваги в дикій природі.",al={"чому вбивати стілснепа","лор завдання стілснепа"}},{q="Хто такий Мертвобагно?",a="Мертвобагно — незвично великий і лютий кроколіск, що нишпорить болотами Багна Пилоброду. Мелор кидає мисливцям виклик: убити його, щоб довести свою майстерність.",al={"хто такий мертвобагно","лор мертвобагна","звір мертвобагно"}},{q="Чи треба бути мисливцем за класом, щоб узяти його завдання?",a="Ні. Хоча його випробування втілюють мисливський шлях і пасують саме мисливцям, Мелор пропонує свої мисливські доручення кожному вправному шукачеві пригод, що бореться за Орду.",al={"чи лише мисливець бере завдання мелора","чи інші класи беруть завдання мелора"}},{q="Хто така Серґра Даркторн і чому Мелор посилає до неї?",a="Серґра Даркторн — орчиха-мисливиця на Перехресті в Пустках. Мелор посилає до неї обіцяльних мисливців, щоб ті допомогли приборкати неслухняних хижаків рівнин і повчилися в іще одного ветерана дикої природи.",al={"серґра мелор","завдання серґри даркторн"}}},fp="15,283,21.435.0,18.388.0,29.374.0,33.196.0,39.333.0,44.185.0,17.157.0,52.189.0,60.225.0"}
P.entries["npc:menara-voidrender"] = {n="Менара Войдрендер",s="Менара Войдрендер — чорнокнижниця-людина, що живе в гоблінському порту Раджет. Вона наставляє честолюбних адептів темних мистецтв і з Альянсу, і з Орди, ділячись глибокими знаннями про артефакти для зв'язування демонів і таємне ремесло. Відлюдне життя на Калімдорі тримає її далеко від пильного ока правовірної влади.",h="Менара Войдрендер — чорнокнижниця-людина, що живе в гоблінському порту Раджет.",kw={"менара войдрендер","чорнокнижниця","раджет","зв'язування демонів","табета","сфера орагіла"},ang={["class:Warlock"]="Менара — важлива наставниця на Калімдорі: вона вчить адептів обох фракцій виготовляти їхні особливі зачаровані мантії й ув'язнювати демонів у сферах-фокусах.",["profession:Tailoring"]="Менара поєднує складні кравецькі матеріали з інгредієнтами скверни, щоб ткати міцні, просякнуті чарами шати, здатні спрямовувати демонічну силу.",["race:Human"]="Далеко від катакомб Стормвінда Менара уособлює чорнокнижників-людей, що відкинули вірність королівству, аби безперешкодно займатися темними мистецтвами на нейтральних землях."},sec={{t="Прихисток у Раджеті",b="Більшість чорнокнижників у Східних Королівствах практикують у вогких підвалах чи відлюдних бойнях під рідними містами, але Менара Войдрендер обрала нейтральний гоблінський порт Раджет у Пустках. Далеко від прискіпливого ока Кірін-Тору, варти Стормвінда чи наглядачів Оргріммара, вона вільно віддається своїм окультним студіям у всіх на виду. Готовність працювати з будь-яким здібним учнем, незалежно від фракції, робить її рідкісною спільною точкою для адептів темних мистецтв."},{t="Майстриня зв'язування",b="Серед досвідчених заклиначів Менара відома як знавчиня сфер, що ув'язнюють демонічних духів і підкоряють їхню силу. Вона працює з вигадливими інгредієнтами, проводячи учнів крізь складні ритуали, щоб виготовити зачаровані шати й знаряддя для зв'язування. Слава про її майстерність сягає Айронфорджа й Андерсіті, тож старші чорнокнижники по всьому Азероту посилають своїх найздібніших учнів за море по її пораду."},{t="Зв'язки з болотами",b="Серед давніх знайомих Менари — відлюдна чарівниця Табета, що живе в глибокій самоті серед боліт Багна Пилоброду. Хоч Табета віддається таємній магії, а Менара заглиблюється в зв'язування скверною та демонологію, двох жінок поєднує давня історія. Коли могутні реліквії на кшталт Сфери Орагіла потребують відновлення чи особливих знань, їхнє спільне минуле стає несподіваним містком через нетрі Калімдору."}},faq={{q="Хто така Менара Войдрендер?",a="Менара Войдрендер — людина-чорнокнижниця в нейтральному портовому містечку Раджет у Пустках. Вона наставниця й майстриня артефактів для чорнокнижників, що зростають: проводить їх через ремісничі ритуали й чаклунство з підкорення демонів.",al={"хто така менара","лор менари войдрендер","чорнокнижниця раджета"}},{q="Чому людина-чорнокнижниця живе в Пустках?",a="Раджет дає нейтральність і відстань від пильних очей великих держав. Оселившись у гоблінському порту, Менара може займатися забороненими мистецтвами й навчати учнів і з Альянсу, і з Орди без утручання паладинів, магів чи міської варти.",al={"чому менара в раджеті","чому вона в пустках","чорнокнижниця раджета"}},{q="На якій магії спеціалізується Менара?",a="Менара спеціалізується на демонології, зачаруванні темних тканин і виготовленні посудин, у які можна ув'язнити демонічних істот. Особливо вона славиться майстерністю у створенні й відновленні сфер, що зв'язують демонів, як-от Сфери Орагіла.",al={"чого навчає менара","сили менари войдрендер","у чому менара сильна"}},{q="Що пов'язує Менару з Табетою?",a="Менару й відлюдну чарівницю Табету пов'язує спільне минуле. Хоча Табета живе осторонь, у Багні Пилоброду, і займається звичайним чарівництвом, чорнокнижники, які шукають знань про Сферу Орагіла, дізнаються, що ці дві жінки добре знають хист одна одної.",al={"менара й табета","звідки вона знає табету","зв'язок із табетою"}},{q="Менара на боці Альянсу чи Орди?",a="Менара діє з Раджета нейтрально. Вона пропонує науку й ремісничі завдання кожному чорнокнижникові, що доведе свою вправність і досить честолюбства, щоб упоратися з енергією Скверни, і радо приймає учнів і з Альянсу, і з Орди.",al={"менара альянс чи орда","фракція менари","на кого працює менара"}},{q="Які великі артефакти вона допомагає створити?",a="Менара вчить учнів ткати Зачаровану Золоту Криваву Робу — вбрання, просякнуте демонічною силою, — а досвідченішим допомагає знаходити й збирати складники для Сфери Орагіла.",al={"завдання менари","що вона створює","зачароване золото кривава мантія менари"}}},fp="17,347,19.503.0,19.441.0,17.416.1,25.230.0,45.276.0,45.232.0,39.275.0,44.214.0,42.202.0"}
P.entries["npc:merissa-stilwell"] = {n="Мерісса Стілвелл",s="Мерісса Стілвелл — молода людська містянка, що живе при Абатстві Нортшира в Лісі Елвінн. Стоячи біля абатства, вона привітно зустрічає новачків, що навчаються в Долині Нортширу, і простягає їм руку допомоги.",h="Мерісса Стілвелл — молода людська містянка, що живе при Абатстві Нортшира в Лісі Елвінн.",kw={"мерісса стілвелл","нортшир","абатство нортшира","гостинність","новобранці","стілвелли"},ang={["faction:Alliance"]="Для новобранців Альянсу, що покидають затишну обитель Нортширу, Мерісса втілює теплу гостинність Елвінну, перш ніж дасться взнаки сувора дійсність загрози Дефіас."},sec={{t="Привітне обличчя в Нортширі",b="Стоячи біля Абатства Нортшира, Мерісса Стілвелл вітає новобранців, що прибувають у Долину Нортширу. Мандрівним новачкам вона пропонує просту гостинність і практичні поради щодо відпочинку й того, як тут усе влаштовано. Носячи прізвище, спільне з відомими ремісниками й господарями по всьому королівству — як-от коваль Джордан Стілвелл і захисниця Вестфолу Дафна Стілвелл, — вона лишається мирним тутешнім обличчям серед дедалі більшої напруги в королівстві."}},faq={{q="Хто така Мерісса Стілвелл?",a="Мерісса — привітна мешканка Абатства Нортшира в Лісі Елвінн, що дає поради й тепло зустрічає мандрівників, які туди прибувають.",al={"мерісса стілвелл","хто така мерісса","дівчина стілвелл нортшир"}},{q="Де знайти Меріссу Стілвелл?",a="Вона в Абатстві Нортшира в Долині Нортширу, у Лісі Елвінн.",al={"місце мерісси стілвелл","де мерісса","знайти меріссу"}},{q="Чи Мерісса родичка інших Стілвеллів королівства?",a="Хоча вона має те саме прізвище, що й відомі люди на кшталт коваля Джордана Стілвелла чи Дафни Стілвелл із Вестфолу, вона тихо живе в Абатстві Нортшира й вітає мандрівників, а не воює з бандитами чи кує клинки.",al={"рід стілвелл","дафна стілвелл родичка","джордан стілвелл родич"}},{q="Чи дає Мерісса Стілвелл якісь завдання?",a="Ні. Власних доручень для мандрівників у неї немає: вона просто вітає новачків, що проходять через Нортшир.",al={"завдання мерісси","завдання мерісси стілвелл"}}},fp="16,219,30.449.0,24.144.0,34.74.0,57.222.0,39.106.0"}
P.entries["npc:merrin-rockweaver"] = {n="Меррін Роквівер",s="Меррін Роквівер — дворфійська дослідниця від Ліги Дослідників у Багнокраї. Після того як люта навала рапторів заполонила Місце Розкопок Велґара, вона сховалася разом із Шукачем Велґаром на гребені над розкопом.",h="Меррін Роквівер — дворфійська дослідниця від Ліги Дослідників у Багнокраї.",kw={"меррін роквівер","ліга дослідників","місце розкопок велґара","шукач велґар","таррел роквівер","раптори"},ang={["faction:Alliance"]="Меррін представляє наукову присутність Айронфорджа в Багнокраї, і збереження її досліджень допомагає Альянсу втримувати хиткий плацдарм у диких болотах.",["race:Dwarf"]="Для дворфів-шукачів пригод допомога Меррін — справа національної спадщини: збереження дорогоцінних реліквій титанів та історичних записів, заради яких Ліга Дослідників ризикувала життям."},sec={{t="Вигнані з розкопу",b="Меррін Роквівер прибула в Багнокрай від імені Ліги Дослідників Айронфорджа, щоб відкопати прадавні таємниці титанів, поховані під багнюкою. Експедиція скінчилася катастрофою, коли великі кістки, які вони відкопали, привабили до розкопу рапторів. Люті доісторичні звірі заполонили траншеї, змусивши Меррін і вцілілих робітників покинути спорядження, нотатки й усе, чого досягли. Тепер вона з кількома вцілілими застрягла на кручі над заполоненими руїнами."},{t="Порятунок справи",b="Застрягнувши на кручі, вцілілі не дають експедиції обернутися на цілковитий провал. Поки Ормер Айронбрейд плекає помсту звірам, а Шукач Велґар шукає уламки таблички, що лишилися в траншеях серед рапторів, думки Меррін линуть до чоловіка, Таррела, який тижнями не має від неї звісток. Вона покладається на розвідника, якого Лонґбрейд послав розшукати загін, — щоб той переказав чоловікові про їхню скруту."}},faq={{q="Хто така Меррін Роквівер?",a="Меррін Роквівер — дворфійка-археологиня з Ліги Дослідників Айронфорджа. Вона працювала на Місці Розкопок Велґара в Багнокраї, доки ящери не захопили розкопки.",al={"лор меррін роквівер","хто така меррін","дворфійка мокрих земель"}},{q="Чому вона застрягла над розкопками?",a="Плямисті ящери, яких привабили великі кістки, відкопані дослідниками, захопили розкопки внизу, і чимало дворфів загинуло. Ормер Айронбрейд прикривав Меррін і Шукача Велґара, поки вони втікали на сусідню кручу, де й досі сидять у пастці.",al={"чому вона на сховищі","притулок велґара меррін","що сталося з її табором"}},{q="З чим Меррін потрібна допомога?",a="Меррін потрібен хтось, хто віднесе листа з розповіддю про лихо її чоловікові Таррелу, який місця собі не знаходить, відколи від неї перестали приходити листи.",al={"завдання меррін","доручення меррін роквівер","лор роботи з інструментами"}},{q="Що намагалася знайти експедиція?",a="Як і більшість справ Ліги Дослідників, розкопки в Багнокраї мали знайти стародавні артефакти, пов'язані з походженням дворфів, і загадкові реліквії титанів, приховані по всьому Каз Модану.",al={"навіщо копають","мета розкопок"}}},fp="17,250,20.459.0,23.426.0,25.195.0,38.234.0,32.152.0,39.192.0"}
P.entries["npc:miles-welsh"] = {n="Майлз Велш",s="Майлз Велш — наставник жерців із Відступників, що мешкає глибоко в Ставках Видінь під Тандер Блафом. Він дає духовні настанови й навчає дисципліни тіні жерців, які проходять крізь столицю тауренів.",h="Майлз Велш — наставник жерців із Відступників, що мешкає глибоко в Ставках Видінь під Тандер Блафом.",kw={"майлз велш","жрець","відступники","озера видінь","тандер блаф","тінь"},ang={["class:Priest"]="Для жерців, що мандрують Калімдором, Майлз Велш — одна з небагатьох нагод у центральних володіннях Орди вивчити нові заклинання й просунутися в духовному навчанні.",["race:Undead"]="Майлз — знайоме холодне обличчя з Лордерона в землистій, залитій сонцем столиці тауренів."},sec={{t="Тінь у печерах",b="Майлз Велш перебуває далеко від сплюндрованих чумою руїн Лордерона: його домівка — волога, сповнена духів печера під Тандер Блафом, відома як Ставки Видінь. Як жрець-Відступник, він навчає мандрівників, що спрямовують божественну й тіньову енергію. Його присутність у серці Малгору віддзеркалює хиткі дипломатичні узи, що поєднують Відступників з Ордою: він ділить прихисток із містиками й шаманами тауренів, навчаючи послушників мистецтв тіні й віри."}},faq={{q="Хто такий Майлз Велш?",a="Майлз Велш — нежить, наставник жерців в Ставках Видінь під Тандер Блафом, що допомагає жерцям Орди навчатися й опановувати особливі вміння.",al={"роль майлза велша","хто такий майлз велш","тренер жерців майлз велш"}},{q="Де знайти Майлза Велша?",a="Він в Ставках Видінь — системі підземних печер під Узвишшям Духів у Тандер Блафі, куди веде вхід у печеру на плато.",al={"місце майлза велша","де майлз велш","як знайти майлза велша"}},{q="Чому в Тандер Блафі є наставник жерців — нежить?",a="Відступники й таурени — союзники в Орді. Таурени, особливо Маґата Ґрімтотем, обстоювали прийняття Відступників до фракції, тож посланці й наставники на кшталт Майлза Велша можуть пропонувати свої послуги в Малгорі.",al={"чому нежить у тандер блафі","жрець нежить у місті тауренів"}},{q="Яких умінь він навчає?",a="Майлз Велш навчає загальних жрецьких заклинань і допомагає послушникам-Відступникам і тролям, які шукають особливих расових умінь, як-от Пожирної Чуми, Дотику Слабкості чи Тіньової Варти.",al={"закляття жерців тандер блафф","чого навчає майлз велш"}}},fp="11,200,23.469.0,19.166.0,29.154.0,49.236.0,29.179.0"}
P.entries["npc:milli-featherwhistle"] = {n="Міллі Фезервісл",s="Міллі Фезервісл — гномка, майстриня-інженерка механоступів, що працює на Складі Стілґрила в Дун Мороґу. Після падіння Гномреґану вона ретельно виготовляє власноруч і обслуговує механічних їздових птахів, яких так полюбляють її родичі. Свої дорогоцінні механічні творіння вона продає гномам і довіреним союзникам вигнанців Гномреґану.",h="Міллі Фезервісл — гномка, майстриня-інженерка механоступів, що працює на Складі Стілґрила в Дун Мороґу.",kw={"міллі фезервісл","механоступ","інженерка","гномка","склад стілґрила","меккаторк","вигнанці гномреґану"},ang={["faction:Alliance"]="Герої Альянсу, що здобули найвищу повагу Вигнанців Гномреґану, можуть звернутися до Міллі, щоб осідлати одного з найшвидших механічних скакунів Азероту.",["profession:Engineering"]="Механоступи Міллі — вершина великомасштабного гномського пересування, що поєднує гіроскопічні балансувальні блоки з потужними механічними кінцівками.",["race:Gnome"]="Міллі Фезервісл — провідна інженерка їздових механізмів вашого народу, яка несе далі технологічний геній Великого Тінкера Меккаторка навіть у вигнанні з вашого підземного дому."},sec={{t="Майстриня механоступів",b="Працюючи просто неба на пронизливому холоді Складу Стілґрила на схід від Хараноса, Міллі Фезервісл відповідає за постачання механічних скакунів переселеному люду Гномреґану. На відміну від живих звірів, яких воліють дворфи й нічні ельфи, Міллі збирає весь свій товар сама, особисто калібруючи шестерні, поршні й балансувальні гіроскопи, щоб кожен механічний птах бігав на повну потужність засніженими скелями Дун Мороґу."},{t="Спадок Меккаторка",b="Кожна рама й пружина в майстерні Міллі походить від креслень, які спершу накреслив Великий Тінкер Ґелбін Меккаторк. Хоча з роками Міллі додала сучасні поліпшення — полегшила шасі й удосконалила вихлопні отвори, — вона вірно дотримується основних схем Великого Тінкера. Її механічні дива доводять: навіть у вигнанні гномське технологічне честолюбство лишається геть незламним."}},faq={{q="Хто така Міллі Фезервісл?",a="Міллі Фезервісл — головна творчиня механоступів та інженерка гномів Гномреґана. Вона працює на Складі Стілґрила в Дун Мороґу, власноруч будує й продає механічних механоступів вершникам, які мають на них право.",al={"міллі фезервісл","хто така міллі","торговка механоступами"}},{q="Де знайти Міллі Фезервісл?",a="Вона на Складі Стілґрила — інженерній заставі за кілька кроків на схід по дорозі від містечка Харанос у Дун Мороґу.",al={"місце міллі","де міллі фезервісл","знайти міллі"}},{q="Кому дозволено купувати в неї їздових тварин?",a="Від початку лише гноми-шукачі пригод мають і дозвіл, і хист, щоб купити її витвори. Члени інших народів Альянсу мусять здобути найвищу довіру — звеличення у Вигнанців Гномреґану, — перш ніж вона довірить їм механоступа.",al={"чи можна купити механоступа","вимоги до механоступа","хто їздить на механоступах"}},{q="Як роблять механоступів?",a="Міллі Фезервісл сама збирає кожного механоступа за знаменитими кресленнями Великого Тінкера Ґелбіна Меккаторка, додаючи власні вдосконалення двигуна й рівноваги.",al={"як будують механоступів","хто робить механоступів","походження механоступів"}},{q="Які моделі вона пропонує?",a="Вона пропонує кілька налаштованих моделей — від звичайних нефарбованих, синіх, зелених і червоних корпусів до тонко відлагоджених прудких варіантів у білому, зеленому й жовтому покритті.",al={"кольори їздових міллі","моделі механоступів","які їздові продає міллі"}},{q="Чому вона працює серед снігів на Складі Стілґрила?",a="Коли радіоактивна катастрофа й навала трогів вигнали гномів із Гномреґана, біженці збиралися, де тільки могли. Склад Стілґрила біля Хараноса — природне місце для випробувань машин і механічного обслуговування разом із дворфами-інженерами.",al={"чому міллі в дун мороґу","чому склад стілґрила"}}},fp="20,342,25.441.0,21.432.0,28.220.0,38.147.0,43.262.0,29.206.0,36.178.0,57.271.0"}
P.entries["npc:milton-sheaf"] = {n="Мілтон Шіф",s="Мілтон Шіф — головний бібліотекар Королівської Бібліотеки у Фортеці Стормвінда. Відданий справі збереження історії королівства, він опікується зібранням давніх фоліантів та історичних хронік. Він часто залучає мандрівників Альянсу, щоб ті розшукали загублені томи, зібрали розпорошені записи й відновили занедбані рукописи.",h="Мілтон Шіф — головний бібліотекар Королівської Бібліотеки у Фортеці Стормвінда.",kw={"мілтон шіф","королівська бібліотека","бібліотекар","фортеця стормвінда","історія","рукописи"},ang={["faction:Alliance"]="Як головний бібліотекар королівства, Мілтон Шіф допомагає зберегти писану спадщину людських королівств і всього Альянсу.",["race:Human"]="Мілтон оберігає століття людської історії — хроніки, що пережили падіння й відбудову Стормвінда."},sec={{t="Хранитель історії Стормвінда",b="У тихих залах Королівської Бібліотеки, що сховалася у Фортеці Стормвінда, Мілтон Шіф доглядає спільну пам'ять королівства. Поки нагорі двір вирує політикою, сварками вельмож і військовими турботами, Шіф дбає про збереження писаного слова. Вести правдиві літописи Альянсу й Східних Королівств він вважає священним обов'язком — надто в часи, сповнені війн, утрат і непевності."},{t="Пошуки загублених томів",b="Зберегти бібліотечне зібрання — справа нескінченна. Книжки зношуються, а цінні записи часто розкидані по всьому королівству — в монастирських архівах, на далеких заставах чи в забутих руїнах. Мілтон раз у раз відсилає шукачів пригод у мандри — від Абатства Нортшира до далекого північного поселення Саутшор, — щоб ті повернули загублені томи, дослідили давні тексти й подбали, аби рідкісні рукописи безпечно повернулися на полиці фортеці."}},faq={{q="Хто такий Мілтон Шіф?",a="Мілтон Шіф — учений і головний доглядач Королівської Бібліотеки у Фортеці Стормвінда. Він опікується книжковими зібраннями й літописами королівства.",al={"хто такий мілтон шіф","роль мілтона шіфа","бібліотекар стормвінда"}},{q="Де знайти Мілтона Шіфа?",a="Ви знайдете Мілтона Шіфа в крилі Королівської Бібліотеки у Фортеці Стормвінда, просто біля головних палацових коридорів.",al={"місце мілтона шіфа","де мілтон шіф","бібліотека стормвінда"}},{q="Навіщо Мілтонові Шіфу шукачі пригод?",a="Мілтон часто покладається на мандрівних шукачів пригод Альянсу: вони розшукують історичні рукописи, замінюють пошкоджені книги й зв'язуються з ученими та жерцями по всьому королівству, щоб поповнити архіви Королівської Бібліотеки.",al={"завдання мілтона шіфа","чого хоче мілтон","навіщо дає завдання"}},{q="Чи спілкується Мілтон Шіф з іншими вченими королівства?",a="Так. Він підтримує зв'язки з монастирськими архіваріусами й релігійними вченими, зокрема з Братом Пакстоном у Долині Нортширу, щоб зберігати священні вчення й історичні записи.",al={"мілтон нортшир","мілтон брат пакстон","зв'язки мілтона"}}},fp="12,335,36.437.0,21.461.0,20.184.0,30.119.0,39.214.0,62.171.0"}
P.entries["npc:miner-johnson"] = {n="Шахтар Джонсон",s="Шахтар Джонсон — невловимий бувалий гірник Братства Дефіас, що працює глибоко в Мертвих Копальнях. Сховавшись у бічній ніші поруч зі звичайними робітниками, цей небезпечний рудошукач наглядає за розкопками попереду важких машин, що стоять глибше під землею. Він блукає підземними тунелями без жодного ладу, тож шукачі пригод лише зрідка натрапляють на нього.",h="Шахтар Джонсон — невловимий бувалий гірник Братства Дефіас, що працює глибоко в Мертвих Копальнях.",kw={"шахтар джонсон","гірник","руда","мертві копальні","дефіас"},ang={["faction:Alliance"]="Убивши Джонсона, ви перервете рівний потік руди, що живить воєнну машину Дефіас, приховану під Мунбруком.",["profession:Mining"]="Для рудошукачів Джонсон — суворий і беззаконний бік підземної праці: багаті поклади глибоко під Вестфолом він стереже кров'ю й кайлом."},sec={{t="Рідкісне обличчя в глибинах",b="Поки сотні робітників довбають підземні жили Мертвих Копалень, постачаючи потаємну фортецю Едвіна Венкліфа, Шахтар Джонсон помітно вирізняється серед них грізною вдачею. Він причаївся в затіненій ніші ліворуч, перед незграбними потрощувачами Щоглової Кімнати, і значно міцніший та зліший за звичайних робітників. З'являється він непередбачувано, тож для дослідників тунелів Дефіас Джонсон став легендарною здобиччю."},{t="Паливо для воєнної машини Дефіас",b="Таємна справа Братства Дефіас під Мунбруком потребує безлічі руди, щоб кувати зброю, кріпити шахти й збирати механізми. Гірники на кшталт Джонсона — це м'язи за металом: вони рубають багаті рудні пласти під Вестфолом. Кожен, хто забреде до Джонсонового вибою, швидко переконається, що свою ділянку він обороняє зі смертельним завзяттям."}},faq={{q="Хто такий Шахтар Джонсон?",a="Шахтар Джонсон — рідкісний і особливо небезпечний шахтар-людина, союзник Братства Дефіас. Він працює глибоко в Мертвих Копальнях, у бічній ніші з іншими робітниками, перед гоблінським потрощувачем.",al={"лор шахтаря джонсона","хто такий шахтар джонсон","шахтар джонсон мертві копальні"}},{q="Де саме Шахтар Джонсон?",a="Він у верхніх штольнях Мертвих Копалень, перед залою, де стоїть Снід зі своїм потрощувачем. Шукайте невелику нішу для розкопок ліворуч, де гурт шахтарів завзято довбає скелю.",al={"місце шахтаря джонсона","де шахтар джонсон","як знайти шахтаря джонсона"}},{q="Чому Шахтаря Джонсона не завжди можна знайти?",a="Шахтар Джонсон з'являється рідко, тобто лише час від часу, коли експедиція заходить до Мертвих Копалень. Більшість загонів, що проходять штольнями, натрапить на його місці на звичайного шахтаря.",al={"шахтар джонсон не з'являється","чи шахтар джонсон рідкісний","поява шахтаря джонсона"}},{q="Чи пов'язаний Шахтар Джонсон з якимсь завданням?",a="Шахтар Джонсон не пов'язаний із жодною офіційною винагородою. Це просто щаслива зустріч для загонів, яким пощастить застати його за роботою в жилі.",al={"завдання шахтаря джонсона","чи є в нього завдання"}},{q="Яка роль Шахтаря Джонсона в Мертвих Копальнях?",a="Він досвідчений десятник чи майстер-копач, що допомагає Братству Дефіас добувати дорогоцінний метал, камінь і все потрібне, щоб звести величезну підземну базу й прихований броненосець.",al={"що робить шахтар джонсон","роль шахтаря джонсона"}},{q="Чи Шахтар Джонсон небезпечніший за інших шахтарів?",a="Так. Звичайні копачі в Мертвих Копальнях доволі вразливі, а Шахтар Джонсон — вправний боєць, що має значно більше життєвої сили й б'є значно сильніше, тож здолати його без ризику може лише злагоджений загін.",al={"наскільки складний шахтар джонсон","чи шахтар джонсон елітний"}}},fp="13,379,23.446.0,30.398.0,21.192.0,39.225.0,37.202.0,35.170.0,46.198.0,52.221.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="Малий Прояв Землі",s="Малий Прояв Землі — місцевий дух стихії, прив'язаний до священних каменів у Малгорі й Дуротарі. Невидимий для звичайного зору, він відкривається лише шаманам-початківцям, що випили священну Земляну Сапту, і дає грубий кварц, потрібний, щоб вирізьбити їхній найперший тотем землі.",h="Малий Прояв Землі — місцевий дух стихії, прив'язаний до священних каменів у Малгорі й Дуротарі.",kw={"малий прояв землі","дух землі","земляна сапта","камінь кодо","камінь духів","тотем землі","шаман"},ang={["class:Shaman"]="Кожен молодий шаман Орди мусить поєднатися з Малим Проявом Землі під дією Земляної Сапти, щоб здобути свій найперший тотем.",["race:Tauren"]="Молоді таурени йдуть на схід через Малгор до Каменя Кодо, щоб шукати єднання з цим проявом як частину своїх прабатьківських духовних випробувань."},sec={{t="Голос каменю",b="Духи землі живуть усюди під ґрунтом і камінням, та щоб говорити з ними, потрібен свідомий ритуал. Біля священних місць на кшталт Каменя Кодо в Малгорі й Каменя Духів у Дуротарі Малі Прояви Землі перебувають у незримому світі в оточенні ще менших стихійних присутностей. Лише посвячені, що випили Земляну Сапту — ритуальний напій, зварений шаманськими наставниками, — здатні підняти завісу між тілесним світом і стихіями. Коли його визнано, дух дарує благословення землі та шматок грубого кварцу — духовне осердя, потрібне новачкові, щоб виготовити Тотем Землі."}},faq={{q="Чому я не бачу Малого Прояву Землі?",a="Прояв існує в царстві стихій і неозброєному оку невидимий. Треба випити Земляну Сапту, яку дає ваш наставник шаманів, щоб увійти в змінений стан сприйняття, потрібний, аби бачити духів стихій і говорити з ними.",al={"не бачу прояву","де дух землі","невидимий прояв землі"}},{q="Де шукати цих духів землі?",a="Вони з'являються біля Каменя Кодо на хвилястих рівнинах Малгору й біля Каменя Духів у посушливих каньйонах Дуротару. Обидва місця здавна служать випробувальними полігонами для молодих шаманів — тауренів, орків і тролів.",al={"місце малого прояву землі","де шукати прояв землі"}},{q="Яка мета духа під час обряду?",a="Прояв випробовує й урочисто визнає зв'язок послушника зі стихією землі. Поговоривши із шаманом, він дарує шматок необробленого кварцу, який несуть назад до наставника шаманів, щоб виготовити Тотем Землі.",al={"що робить прояв","мета завдання прояву"}},{q="Що за менші створіння довкола нього?",a="Довкола головного духа — менші прояви землі. Це слабкі відгомони стихії, яких притягли священні місця: вони існують лише як частина природного єднання, і взаємодіяти з ними напряму не можна.",al={"менші прояви","маленькі елементалі землі довкола"}}},fp="28,291,18.638.0,49.247.0,39.198.0,45.234.0,46.221.0"}
P.entries["npc:minor-manifestation-of-water"] = {n="Малий Прояв Води",s="Малий Прояв Води — дух стихії, який можна знайти біля Потоку Північного Припливу на узбережжі Срібнолісся. Для шаманів Орди, що прагнуть порозумітися зі стихією води й опанувати її, це важливе випробування. Перш ніж звернутися до цього мирного духа, учні мають очистити його зіпсованого двійника.",h="Малий Прояв Води — дух стихії, який можна знайти біля Потоку Північного Припливу на узбережжі Срібнолісся.",kw={"малий прояв води","потік північного припливу","шамани","тотем води","елементалі","срібнолісся"},ang={["class:Shaman"]="Очистити цього елементаля від скверни й отримати його благословення — останній рубіж на шляху до злагоди з припливами й створення вашого Тотема Води.",["faction:Horde"]="Шамани-тролі, орки й таурени долають шлях аж із Калімдору до берегів Лордерона, щоб поспілкуватися з цим духом."},sec={{t="Дух західних припливів",b="Малий Прояв Води, що перебуває на оповитих туманом берегах Потоку Північного Припливу на захід від Гробниці в Срібноліссі, — важливий обряд посвяти для шаманів, які набираються досвіду. Водяні елементалі втілюють життя, оновлення й плинність, але легко стають жертвами злісної скверни. Учень мусить зійтися з зіпсованим проявом цього елементаля й здолати його, перш ніж чистий Малий Прояв Води зможе показатися. Очищений дух дає настанови шаманам, що завершують свою священну мандрівку, аби створити Тотем Води."}},faq={{q="Де знайти Малий Прояв Води?",a="Малий Прояв Води з'являється біля Потоку Північного Припливу, на західному узбережжі Срібнолісся, трохи на захід від Гробниці.",al={"місце малого прояву води","де прояв води","елементаль північного припливу"}},{q="Чому елементаль ворожий, коли я вперше підходжу?",a="Шаман мусить спершу викликати й знищити Зіпсований Малий Прояв Води. Лише після того, як зіпсовану сутність переможено, з'являється мирний прояв, щоб поговорити з вами.",al={"зіпсований малий прояв","чому прояв води сердитий","прояв води нападає на мене"}},{q="Яке завдання пов'язане з цим елементалем?",a="Цей дух — важлива ланка в ланцюжку завдань шаманів «Поклик Води», у якому шамани зрештою здобувають уміння ставити Тотем Води.",al={"завдання поклик води","завдання тотема води сільверпайн","для якого це завдання"}},{q="Чи можуть з цим духом спілкуватися ті, хто не шаман?",a="Малий Прояв Води існує саме для того, щоб наставляти шаманів, які проходять духовні випробування. Іншим шукачам пригод немає особливих причин із ним спілкуватися.",al={"чи це лише для шамана","чи хтось може говорити з проявом","хто говорить із малим проявом"}}},fp="28,323,29.559.0,50.134.0,51.182.0,35.152.0,42.167.0"}
P.entries["npc:misha"] = {n="Міша",s="Міша — вірна ведмедиця-супутниця Рекссара, Чемпіона Орди. Він урятував її ще осиротілим ведмежам, і відтоді вона невідступно мандрує Калімдором поруч із цим повелителем звірів з народу мок'натал.",h="Міша — вірна ведмедиця-супутниця Рекссара, Чемпіона Орди.",kw={"міша","рекссар","ведмідь","чемпіон орди","мок'натал","пустограй","фералас"},ang={["class:Hunter"]="Для мисливців Міша — найвищий ідеал тварини-супутника: нерозривне, довічне партнерство, що тримається на взаємній повазі, а не на самому лише пануванні.",["faction:Horde"]="Міша билася поруч із Рекссаром за свободу молодої Орди на Острові Терамор і заслужила мовчазну повагу ветеранів по всьому Дуротару."},sec={{t="Нерозривні узи",b="Рекссар знайшов Мішу осиротілим ведмежам біля тіла вбитої матері в Руїнах Рейвенвінду у Фераласі. Упізнавши в ній таку саму самотню душу, мандрівний мок'натал прихистив її й дав їй ім'я. Разом вони рушили на північ, у посушливу глушину Пустограю, і стали відданими захисниками одне одного — цей союз пережив незліченні дикі краї та криваві битви."},{t="Захисниця Дуротару",b="Міша — аж ніяк не ручна тваринка, а досвідчена воїтелька. Вона билася пліч-о-пліч з Рекссаром у жорстокій війні проти великого адмірала Дейліна Праудмура на Острові Терамор і допомогла молодій Орді вижити. Поза боєм її гострі чуття й сила стають продовженням Рекссарової волі: вона навіть приносила до Оргріммара полеглих союзників, як-от орка Байрока."},{t="Дикі простори Калімдору",b="Нині мандрівники, що йдуть довгими стежками через Гори Кам'яного Кігтя, Пустограй і Фералас, можуть побачити Мішу, яка тихо ступає поруч із Рекссаром. Вона досить люта, щоб розірвати будь-якого хижака, якому стане дурості їм загрожувати, — та для Рекссара вона лишається надійною опорою у світі, якому більше ні в чому не можна довіряти."}},faq={{q="Хто така Міша?",a="Міша — люта бура ведмедиця й незмінна супутниця Рекссара, Чемпіона Орди. Вона мандрує дикими краями центрального Калімдору разом із ним.",al={"ведмідь рекссара","хто ведмідь із рекссаром","ведмідь міша"}},{q="Де Рекссар знайшов Мішу?",a="Рекссар знайшов Мішу ще маленьким ведмежам у Руїнах Рейвенвінду у Фераласі, біля мертвої матері. Побачивши, що вони обоє самотні в дикій природі, Рекссар узяв її до себе.",al={"де рекссар узяв мішу","минуле міші","як рекссар зустрів мішу"}},{q="Де зараз можна знайти Мішу?",a="Міша ходить довгими стежками Гір Кам'яного Кігтя, Пустограю й Фераласу, вірно супроводжуючи Рекссара в його нескінченних мандрах.",al={"місце міші","де міша","знайти мішу"}},{q="Чи брала Міша участь у заснуванні Дуротару?",a="Так. Після Третьої війни Міша разом із Рекссаром билася з військами Великого Адмірала Дейліна Праудмура на Острові Терамор, захищаючи молоду Орду.",al={"міша терамор","чи міша воювала з даеліном","міша третя війна"}},{q="Чи ворожа Міша до гравців Альянсу?",a="Так. Як супутниця Чемпіона Орди, Міша люто захищатиме Рекссара й нападе на кожного чужинця з Альянсу, що підійде надто близько.",al={"чи можна нападати на мішу","чи міша агресивна"}},{q="Чому Рекссар воліє товаришувати зі звірами на кшталт Міші, а не з людьми?",a="Розчарувавшись в обмані й війнах людиноподібних народів, Рекссар обрав самотність дикої природи. Він вірить, що звірі прямі й чесні, і знайшов у Міші супутницю, яка ніколи не зрадить.",al={"чому рекссар тримає звірів","ведмідь-супутник рекссара"}}},fp="5,169,16.366.0,19.372.0,17.310.0,13.157.0,28.170.0,35.154.0,47.164.0,37.141.0,51.194.0"}
P.entries["npc:misha-tor-kren"] = {n="Міша Тор'крен",s="Міша Тор'крен — орчиня-мати, що мешкає на Фермі Тор'крена в західному Дуроторі, на південний схід від Громового Хребта. Змучена тривогою за зниклого сина Крона, вона просить перехожих мандрівників допомогти дізнатися його долю.",h="Міша Тор'крен — орчиня-мати, що мешкає на Фермі Тор'крена в західному Дуроторі, на південний схід від...",kw={"міша тор'крен","крон","ферма тор'крена","кроколіски","південна лють","мати","дуротар"},ang={["class:Hunter"]="Доля сина Міші показує, як небезпечно недооцінювати річкових хижаків, доки мисливець по-справжньому не опанував дику природу.",["race:Orc"]="Безрозсудне бажання Крона довести свою воїнську вправність на звірині Дуротару — сумне нагадування про високу ціну юнацької гордості."},sec={{t="Материнське чекання",b="Сховавшись край Громового Хребта, Міша Тор'крен порається на відлюдному хуторі й переживає найгірший страх кожного з батьків. Її син Крон подався на захід, до Річки Південної Люті, полювати на кроколісків і довести свою вправність — та так і не повернувся. Поки небезпеки прикордоння Дуротару розтягують сторожові вежі орків до межі, Міша лишається сама з надією на звістку про нього й відчайдушно шукає будь-кого, хто погодиться обшукати береги річки в пошуках слідів її хлопчика."},{t="Похмурий знак",b="Річка Південної Люті безжальна до молодих мисливців. Ті, хто прочісує її багнисті береги, неминуче дізнаються, що Крон став жертвою лютих річкових кроколісків. Повернення його врятованого амулета — єдине заспокоєння, яке може отримати Міша: гірке нагадування про жорстокі випробування, через які молоді орки доводять свою силу в суворих нетрях Калімдору."}},faq={{q="Хто така Міша Тор'крен?",a="Міша Тор'крен — орчиха-поселенка, що живе на Фермі Тор'крена на заході Дуротару, трохи на південний схід від Громового Хребта.",al={"міша тор'крен","хто така міша","власниця ферми тор'крен"}},{q="Куди подівся її син Крон?",a="Крон вирушив на захід, до Річки Південної Люті, полювати на річкових кроколісків, прагнучи довести, що він вправний мисливець, але додому не повернувся.",al={"де крон","що сталося з кроном","син міші"}},{q="Що відбувається, коли шукаєш Крона?",a="Міша посилає шукачів пригод шукати Крона вздовж річки. Його зникнення тяжко гнітить її, і їй потрібен хтось, хто обшукає ті місця.",al={"чи крон мертвий","знайти крона","загублений, але не забутий"}},{q="Чи вона пов'язана з Мішею, ведмедицею Рекссара?",a="Ні. Хоча обидві звуться Мішами, вона — орчиха-фермерка з Дуротару, ніяк не пов'язана з вірною супутницею-ведмедицею Рекссара.",al={"ведмідь міша","міша рекссара","чи вона ведмедиця"}}},fp="14,221,16.444.0,12.345.1,22.124.0,26.140.0,36.147.1,38.130.0"}
P.entries["npc:mitsuwa"] = {n="Міцува",s="Міцува — троль Темного Спису, що служить на Заставі Зорам'гар на туманному узбережжі Ашенвалю. Глибоко вражений засідкою на своїх родичів-мандрівників, він кличе звитяжців Орди помститися за полеглих і повернути викрадені духовні талісмани.",h="Міцува — троль Темного Спису, що служить на Заставі Зорам'гар на туманному узбережжі Ашенвалю.",kw={"міцува","тролі","темний спис","тролячі обереги","фурболги","застава зорам'гар"},ang={["faction:Horde"]="Застава Зорам'гар — відрізаний і обложений гарнізон; допомагаючи Міцуві, ви зміцнюєте хитку присутність Орди проти диких звірів і розвідників Альянсу на західних околицях Калімдору.",["race:Troll"]="Заклик Міцуви до зброї глибоко зачіпає серце кожного шукача пригод із Темного Спису: повернувши священні обереги предків від брутальних фурболгів-грабіжників, ви даруєте спокій убитим братам і сестрам."},sec={{t="Помста за полеглих родичів",b="Міцува служить Орді на віддаленій Заставі Зорам'гар на Зорамському Узмор'ї разом зі своєю товаришкою Марукай. Коли загін тролів, що йшов до табору, потрапив у засідку й загинув від рук агресивних фурболгів Будякохутрих на півночі Ашенвалю, Міцува сприйняв цю втрату як тяжку образу. Ведений обов'язком і гнівом, він посилає здатних воїнів до лігв Будякохутрих, щоб повернути викрадені тролячі обереги, — аби вшанувати духів родичів і вирвати їхні священні речі з лап звірів."}},faq={{q="Хто такий Міцува?",a="Міцува — троль із джунглів, із Темного Спису, що живе на Заставі Зорам'гар на північному заході Ашенвалю. Він пильнує цю прикордонну заставу разом зі своєю товаришкою Марукай і організовує відплату ворожим загрозам у краї.",al={"міцува","хто такий міцува","лор міцуви"}},{q="Що сталося з тролями, які прямували до Зорам'гару?",a="Загін тролів, що йшов через Ашенваль підсилити Заставу Зорам'гар чи навідатися туди, потрапив у засідку місцевих фурболгів-будякошерстих: ті перебили мандрівників і забрали їхні особисті речі.",al={"мертві тролі ясенлісся","напад тістлфур на тролів"}},{q="Чому тролячі амулети такі важливі для Міцуви?",a="Амулети мають духовне й культурне значення для племені Темного Спису. Залишити священні реліквії в лапах будякошерстих після жорстокої різанини — тяжка образа для духів загиблих.",al={"чому тролячі амулети","причина завдання амулетів"}},{q="Де шукати амулети?",a="Будякохутрі фурболги віднесли амулети до свого селища й смердючого лігва на півночі Ашенвалю, на схід від Берега Зорам.",al={"де тролячі амулети","село тістлфур"}}},fp="7,235,23.547.0,15.220.0,51.214.0,49.215.0,29.141.0"}
P.entries["npc:monte-gazlowe"] = {n="Монте Ґазлоу",s="Монте Ґазлоу — практичний гоблінський інженер і очільник, який заснував портове містечко Раджет і править ним. Відслуживши головним інженером Орди, коли засновували Дуротар і Оргріммар, він вклав чималі заробітки в гамірний нейтральний торговий вузол картелю Стімвідл.",h="Монте Ґазлоу — практичний гоблінський інженер і очільник, який заснував портове містечко Раджет і править ним.",kw={"монте ґазлоу","раджет","картель стімвідл","гобліни","інженер","оргріммар"},ang={["faction:Alliance"]="Ґазлоу байдуже, хто сидить на троні Стормвінда і які чвари ви привезли зі Східних Королівств: поки ваше золото справжнє, а клинок у піхвах, Раджет радий вас бачити.",["faction:Horde"]="Хоч він, як і кожен порядний гоблін, вимагає з вас монету, Ґазлоу — вірний союзник Тралла відтоді, як вляглася курява Третьої війни: він допомагав закладати саме підмурівки вашої столиці.",["profession:Engineering"]="Ґазлоу — один із найкращих умів гоблінської інженерії в Калімдорі: він опікується всім, від міських водогонів до швидкісних перегонових машин на Перегонах Міражу.",["race:Orc"]="Воду в Оргріммарі орки мають саме завдяки саперам Ґазлоу, і він досі тримає своїх гоблінських механіків у Дуротарі, щоб допомагати з важкими будівництвами."},sec={{t="Мозок Раджета",b="Ґазлоу родом із гоблінського мегаполіса Андермайн — міста, яке він зрештою зненавидів, бо там кожну тяжко зароблену монету крали, а кожну творчу ідею душили суперники. Утікши разом з іншими честолюбними гоблінами за Велике море до Калімдору, він збудував собі зовсім нове життя. Отримавши щедру платню за інженерну роботу для нової Орди, Ґазлоу вклав гроші просто в голе узбережжя й заснував порт Раджет. Працюючи під крилом картелю Стімвідл, він тримає це припортове містечко суворо нейтральним: тут Орда, Альянс і вільні торговці можуть спокійно торгувати — аби лиш зброя лишалася в піхвах, а гаманці були повні."},{t="Інженер Орди",b="Після Третьої війни Вождь Тралл найняв Ґазлоу головним інженером Дуротару, щоб розв'язати нагальні проблеми з облаштуванням молодої оркської столиці. Ґазлоу взявся за небезпечну роботу — забезпечити Оргріммар прісною водою — і прокопав довгі тунелі, що ненароком прорвалися в підземні нори кобольдів. Завдяки вчасній допомозі мандрівного володаря звірів Рекссара Ґазлоу зумів підірвати й завалити печери та завершити роботу. Він і досі улюблений підрядник і друг Тралла й навіть відрядив свого виконроба Резлака, щоб той допомагав оркам на будівництвах по всьому Дуротару."},{t="Клопоти на Узбережжі Крамарів",b="Хоч справи в Раджеті й прибуткові, Ґазлоу постійно має головний біль через морських конкурентів і злодіїв. Флібустьєри Південних морів облаштували табори на сусідньому Узбережжі Крамарів й перехоплюють вантажі для Раджета, крадучи все — від сирої руди до замовлених Ґазлоу чобіт. Щоб захистити свої прибутки, господар порту раз у раз наймає мандрівних найманців будь-якої приналежності: вичищати піратські табори, повертати вкрадені вантажі й зводити рахунки з портовими бешкетниками."}},faq={{q="Хто такий Ґазлоу?",a="Ґазлоу — гоблін-бос і господар Раджета, головного торгового порту на узбережжі Пусток. Родом з Андермайну, він розбагатів як головний інженер, що керував будівництвом Оргріммара, а потім заснував Раджет як відкриту нейтральну гавань під орудою картелю Стімвідл.",al={"хто такий ґазлоу","лор ґазлоу","бос раджета"}},{q="Ґазлоу вірний Орді чи Альянсу?",a="Офіційно Ґазлоу цілком нейтральний: він керує Раджетом під орудою картелю Стімвідл і відкриває пристань для мандрівників і з Альянсу, і з Орди. Утім, його пов'язують із Вождем Траллом близькі особисті стосунки й вигідна спільна історія, адже він сам спроєктував важливі частини поселень Дуротару.",al={"чи ґазлоу з орди","чи раджет нейтральний","фракція ґазлоу"}},{q="Що Ґазлоу збудував у Дуротарі?",a="Коли засновували Дуротар, Вождь Тралл найняв Ґазлоу головним інженером. Ґазлоу керував прокладанням тунелів, щоб знайти підземне водосховище для Оргріммара. Коли гірники ненароком випустили рій ворожих кобольдів, Ґазлоу найняв Рекссара, щоб той допоміг саперам запечатати тунелі.",al={"ґазлоу оргріммар","ґазлоу тал","водопостачання ґазлоу"}},{q="Навіщо Ґазлоу наймає шукачів пригод у Раджеті?",a="Ґазлоу постійно потребує найманих бійців проти Флібустьєрів Південних морів, що отаборилися на Узбережжі Крамарів й раз у раз грабують вантажі, призначені для пристані Раджета. Він платить мисливцям за головами, щоб ті знищували піратів, повертали викрадені накладні й розшукували зниклі вантажі.",al={"завдання ґазлоу","вільні торговці південних морів раджет","проблеми ґазлоу"}},{q="Що пов'язує Ґазлоу з Перегонами Міражу?",a="Ґазлоу — палкий шанувальник інженерії й швидкості. Він спонсорує гоблінські команди, що змагаються з гномами в Мерехтливих Низинах у Тисячі Голок: допомагав будувати їхню перегонову машину й намагається роздобути дослідні регулятори пального.",al={"ґазлоу мерехтливі низини","ґазлоу тисяча голок","ґазлоу перегони"}},{q="Чому Ґазлоу покинув Андермайн?",a="Ґазлоу ненавидів Андермайн, бо чесне підприємництво й кмітлива інженерія там щоразу наражалися на вимагання, крадіжки й диверсії конкурентів. Переконаний, що в цьому місті немає майбутнього для того, хто хоче зберегти власний заробіток, він перебрався зі своїм хистом до Калімдору й поклявся ніколи не озиратися назад.",al={"андермайн ґазлоу","минуле ґазлоу"}}},fp="13,304,25.665.0,22.613.0,29.508.0,15.302.0,46.298.0,34.309.0,45.286.0,51.236.0,32.289.0"}
P.entries["npc:moon-priestess-amara"] = {n="Місячна Жриця Амара",s="Місячна Жриця Амара — жриця, нічна ельфійка, що стоїть біля головної дороги на захід від Доланаара в Тельдрассилі. Оточена вірними охоронницями-мисливицями, вона пильнує лісові шляхи, що з'єднують серце гілки зі столицею — Дарнасусом.",h="Місячна Жриця Амара — жриця, нічна ельфійка, що стоїть біля головної дороги на захід від Доланаара в...",kw={"місячна жриця амара","жриця","сестринство елуни","доланаар","дарнасус","дорога","тельдрассил"},ang={["class:Priest"]="Як членкиня Сестринства Елуни Жриця Амара втілює нічноельфійську відданість Місячній Богині й слугує душпастиркою та духовною провідницею молодих послушників, що вирушають із Тінедолу.",["race:NightElf"]="Амара позначає важливу віху на вашому шляху від Доланаара, даючи настанови й доручення, що ведуть до великого міста Дарнасус."},sec={{t="Охоронниця лісових шляхів",b="Перебуваючи на тихому придорожньому посту на захід від Доланаара, Місячна Жриця Амара уособлює і духовну владу Сестринства Елуни, і практичну пильність, потрібну, щоб дороги Тельдрассила були безпечними. Вона подорожує й пильнує з двома супутницями-мисливицями, Нгемай і Яеліурою. Для подорожніх, що прямують на захід, Амара — провідна рука: вона спрямовує шукачів пригод дорогою до Дарнасуса, а тим, чий дух обтяжений, доручає шукати шляхів спокути."}},faq={{q="Хто така Місячна Жриця Амара?",a="Місячна Жриця Амара, відома у варті як Амара Найтволкер, — жриця Сестринства Елуни, що несе службу на дорозі між Доланааром і Дарнасусом на Тельдрассилі. Вона дбає про безпеку й духовне здоров'я мандрівників, що проходять гілкою.",al={"хто така амара","жриця амара","вартова амара"}},{q="Де знайти Місячну Жрицю Амару?",a="Вона на мощеному шляху трохи на захід від Доланаара на Тельдрассилі, вартує поруч із двома мисливицями з Вартових.",al={"місце амари","де амара","карта жриці амари"}},{q="Хто ці мисливиці, що стоять поруч із нею?",a="Її охороняють і супроводжують Мисливиця Немай і Мисливиця Яеліура — дві нічні ельфійки з Вартових, що допомагають боронити шлях від звірів і ворожої скверни.",al={"супутниці амари","нхемай і яеліура","охорона амари"}}},fp="20,252,25.480.0,28.270.0,38.122.0,41.174.0"}
P.entries["npc:mor-rogal"] = {n="Мор'роґал",s="Мор'роґал — таурен, що живе в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він радник і провідник для мандрівників, які шукають слави й небезпеки в суворих підземних закутках скель.",h="Мор'роґал — таурен, що живе в Притулку Сонячної Скелі в Горах Кам'яного Кігтя.",kw={"мор'роґал","притулок сонячної скелі","яр кам'яного зсуву","таурени","печери","гори кам'яного кігтя"},ang={["faction:Horde"]="Для мандрівників, що дісталися Притулку Сонячної Скелі, Мор'роґал — джерело важливих відомостей про загрози, що чатують серед скель за межами поселення.",["race:Tauren"]="Мор'роґал утілює тауренську шану до випробувань тіла й духу: глибокі кам'яні порожнини Калімдору для нього — священна земля, де можна довести свою гідність."},sec={{t="Спостерігач серед скель",b="Мор'роґал, що живе в Притулку Сонячної Скелі, пильно цікавиться глибокими розколинами й печерами, що прорізають Гори Кам'яного Кігтя. Розуміючи, що звивисті підземні ходи краю ховають і великі багатства, і смертельну небезпеку, він посилає сміливих мандрівників з Орди розвідати неспокійні місця на кшталт Яру Кам'яного Зсуву. Для Мор'роґала спуститися в ці підступні глибини — не лише справа виживання, а й випробування духу для тих, хто йде за серцем і душею в пошуках слави."}},faq={{q="Хто такий Мор'роґал?",a="Мор'роґал — таурен, що дає завдання в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він місцевий провідник, що закликає шукачів пригод Орди випробувати себе в небезпечних печерах і ярах, розкиданих по цьому скелястому кряжу.",al={"морроґал","хто такий мор'роґал","лор мор'роґала"}},{q="Де знайти Мор'роґала?",a="Він стоїть у Притулку Сонячної Скелі — головній заставі Орди, захованій серед вершин центральної частини Гір Кам'яного Кігтя.",al={"місце мор'роґала","де мор'роґал","точка мор'роґала"}},{q="Які доручення дає Мор'роґал?",a="Мор'роґал залучає вправних поборників спуститися до печери в Яру Кам'яного Зсуву, де кобольди гарячково видобувають кристали резоніту, а потім убити Ґоґґерока — сплячого землянина, якого відкопали кобольди.",al={"завдання мор'роґала","чого хоче мор'роґал"}},{q="Чому Мор'роґал зосереджений на печерах і ярах?",a="Мор'роґал вважає, що в небезпечних підземних печерах Гір Кам'яного Кігтя чекають справжні пригоди й випробування духу, які приносять славу й багатство тим, хто готовий ризикнути життям.",al={"чому печери","мор'роґал печери"}}},fp="9,204,20.521.0,17.246.0,27.130.0,32.208.0,46.188.0"}
P.entries["npc:morgan-pestle"] = {n="Морґан Пестл",s="Морґан Пестл — алхімік-людина й крамар, що тримає «Аптеку Пестла» в Торговому Кварталі Стормвінда. Він тісно співпрацює зі своїм братом Вільямом Пестлом із Ґолдширу й відає постачанням та алхімічними дослідженнями для столиці.",h="Морґан Пестл — алхімік-людина й крамар, що тримає «Аптеку Пестла» в Торговому Кварталі Стормвінда.",kw={"морґан пестл","аптека пестла","алхімік","торговий квартал","вільям пестл","стормвінд"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що прибувають до Стормвінда з Елвінна, крамниця Морґана — неминуча зупинка: тут знайдеться потрібне з алхімії, а ще можна взяти місцеві доручення з доставки містом.",["profession:Herbalism"]="Морґан значною мірою покладається на свіжі трави, зібрані в Лісі Елвінн і далі, щоб постачати свою аптеку в Торговому Кварталі."},sec={{t="Міська аптека",b="Зі своєї «Аптеки Пестла» на жвавих вулицях Торгового Кварталу Стормвінда Морґан Пестл постачає алхімічні товари, реагенти й перевірені ліки містянам і подорожнім. Поки його брат Вільям тримає майстерню в корчмі «Лев'яча Гордість» у Ґолдширі, Морґан береже родинне ремесло в самому серці столиці королівства й налагоджує перевезення трав і сумішей між містом і сільськими серцевими землями."}},faq={{q="Де знайти Морґана Пестла?",a="Морґан Пестл — в «Аптеці Пестла», крамниці в Торговому Кварталі Стормвінда.",al={"місце морґана пестла","де морґан пестл","аптека пестла стормвінд"}},{q="Ким Морґан Пестл доводиться Вільямові Пестлу?",a="Морґан і Вільям Пестли — брати. Обидва алхіміки в Елвінні: Морґан тримає їхню крамницю в Стормвінді, а Вільям працює в Ґолдширі.",al={"брат вільяма пестла","чи вільям і морґан родичі","брати пестл"}},{q="Яку роль він відіграє в завданнях Елвінна?",a="Морґан приймає вантажі й алхімічні припаси, які його брат Вільям надсилає на північ із Ґолдшира, пов'язуючи збирання місцевих трав із міською торгівлею.",al={"доставка до стормвінда морґан","завдання морґана пестла"}}},fp="13,242,19.456.0,31.100.0,47.156.0,40.175.0"}
P.entries["npc:morgan-the-collector"] = {n="Морґан Збирач",s="Морґан Збирач — високопоставлений агент Дефіас, що керує здирництвом і збором данини Братства по всьому Лісі Елвінн. Отаборившись на захопленій Гарбузовій Ділянці Брекуеллів, він координує місцеве злодійство просто під носом у варти Ґолдширу.",h="Морґан Збирач — високопоставлений агент Дефіас, що керує здирництвом і збором данини Братства по всьому Лісі...",kw={"морґан збирач","дефіас","гарбузова ділянка","перстень","гільдія каменярів","здирництво"},ang={["class:Rogue"]="Морґан показує, як організована злочинна дисципліна перетворює розрізнених злодіїв на дієвий підпільний синдикат, здатний фінансувати заколот.",["race:Human"]="Знищення Морґана — удар у відповідь зрадникам, що перетворили мирні ферми Стормвінда на укріплені бандитські лігва."},sec={{t="Данина Елвінну",b="Морґан заслужив своє прізвисько, витискаючи соки з віддалених ферм Лісу Елвінн від імені Братства Дефіас. Поки звичайні бандити чіпляються до подорожніх на дорогах, Морґан керує організованими здирствами й збирає крадену монету та припаси, щоб спрямувати їх углиб мережі Братства. Свій штаб він улаштував у будинку на Гарбузовій Ділянці Брекуеллів, оточивши себе вірними посіпаками, серед яких Сурена Каледон і Ерлан Драджмур."},{t="Перстень минулого",b="Справи Морґана — не прості вуличні злочини: він носить особливий перстень-печатку, що позначає його владу. Для слідчих у Ґолдширі цей перстень — твердий доказ, що пов'язує замаскованих злодіїв, які тероризують серце королівства, зі зганьбленою Гільдією Каменярів, що відбудувала Стормвінд після Другої війни. Здобутий перстень пробиває завісу таємниці над тим, хто насправді керує бандитами в лісах."}},faq={{q="Хто такий Морґан Збирач?",a="Це офіцер Братства Дефіас, що відповідає за вимагання грошей і припасів у хуторян Лісу Елвінн і керує бандитськими справами в краї.",al={"хто такий морґан","лор морґана","збирач в елвінні"}},{q="Де знайти Морґана?",a="Він ховає награбоване в покинутій хаті на Гарбузовій Ділянці Брекуеллів на сході Лісу Елвінн.",al={"місце морґана","де морґан збирач","будинок на гарбузовому полі бракуелла"}},{q="Чому Стормвінд полює на нього?",a="Маршал Дуґан і місцева влада хочуть позбутися Морґана, щоб обезголовити Дефіас в Елвінні й здобути докази того, хто організовує заворушення по селах.",al={"чому вбивати морґана","ціль полювання"}},{q="Що особливого в персні, який він носить?",a="Морґан носить перстень-печатку, що слугує доказом для влади, яка розслідує його справи в Лісі Елвінн.",al={"перстень збирача","печатка збирача","лор персня морґана"}}},fp="20,262,19.448.0,20.411.1,28.163.0,22.123.0,29.156.0,42.119.1"}
P.entries["npc:morin-cloudstalker"] = {n="Морін Клаудсталкер",s="Морін Клаудсталкер — тауренський розвідник, що вартує на дорозі, яка веде на схід від Села Бладгуф до Пусток у Малгорі. Пильнуючи рівнини, він стежить за місцевими торговими шляхами й розслідує загрози, що насуваються на тауренських мандрівників.",h="Морін Клаудсталкер — тауренський розвідник, що вартує на дорозі, яка веде на схід від Села Бладгуф до Пусток...",kw={"морін клаудсталкер","розвідник","село бладгуф","малгор","венчурна компанія","караван"},ang={["faction:Horde"]="Морін дає звитяжцям Орди першу нагоду захистити припаси й священні землі своїх нових тауренських союзників.",["race:Tauren"]="Для тауренів, що вирушають із Села Бладгуф у великий світ, Морін уособлює пильну оборону вашої батьківщини — і від зухвалих розбійників, і від корпоративних осквернителів."},sec={{t="Вартовий південного шляху",b="Ставши край ґрунтової дороги, що в'ється на схід до Пусток, Морін Клаудсталкер водночас розвідник і охоронець для подорожніх Малгору. Трав'янисті рівнини тут зазвичай мирні, але відкриття торгових шляхів і зрушення кордонів привабили пройдисвітів і розбійників небезпечно близько до серця тауренської батьківщини."},{t="Розслідування каравану",b="Розвідники Моріна нещодавно напали на караван Венчурної Компанії на північному березі Озера Кам'яного Бика й спалили його. Коли поблизу обгорілих возів помітили гоблінів-збирачів, він послав шукачів пригод оглянути вцілілі ящики з припасами й дізнатися, що саме везла Венчурна Компанія."},{t="Оборона від Венчурної Компанії",b="Окрім звичайних грабіжників, Моріна глибоко турбує промислова присутність Венчурної Компанії, що розгортає діяльність у Малгорі. Він спрямовує шукачів пригод з Орди, які проходять повз, на їхні лісозаготівлі та шахтарські застави й вказує на ключових ватажків — таких як Наглядач Фіззпрокет, — щоб зупинити спустошення природи, яке загрожує священним рівнинам."}},faq={{q="Де знайти Моріна Клаудсталкера?",a="Морін Клаудсталкер стоїть біля ґрунтової стежки на схід від Села Бладгуф у Малгорі, при дорозі, що веде до Пусток.",al={"місце моріна","де морін","карта моріна клаудсталкера"}},{q="Яка роль Моріна в Малгорі?",a="Він пильний тауренський розвідник, що стежить за мандрівниками на півдні Малгору й організовує оборону від бандитів і непроханих гостей-ділків.",al={"хто такий морін клаудсталкер","роль моріна"}},{q="Чому Морін досліджує розгромлений караван?",a="Розвідники Моріна напали на караван Венчурної Компанії біля Озера Кам'яного Бика й спалили його. Коли біля уламків помітили гоблінів-мародерів, він попросив шукачів пригод оглянути вцілілі ящики з припасами, щоб з'ясувати, що перевозила Венчурна Компанія.",al={"завдання розгромленого каравану","напад на караван малгор"}},{q="Чому Морін хоче зупинити Венчурну Компанію?",a="Венчурна Компанія машинами й вирубкою лісів виснажує природні багатства Малгору. Морін прагне зірвати їхню руйнівну справу, знищивши їхніх наглядачів, зокрема Наглядача Фіззпрокета.",al={"венчурна компанія малгор","чому вбивати фізспрокета"}},{q="Кому звітує Морін?",a="Морін діє від імені старійшин і вождів Села Бладгуф та ширшої тауренської верхівки Малгору.",al={"вірність моріна","хто послав моріна"}},{q="Чи дає Морін завдання гравцям Альянсу?",a="Ні. Морін вірний лише Орді й спілкується тільки з шукачами пригод Орди.",al={"чи альянс може говорити з моріном","фракція моріна"}}},fp="18,266,29.343.0,25.268.0,29.346.1,36.128.0,32.152.0,46.232.0,48.212.0,25.124.0,44.94.0"}
P.entries["npc:motega-firemane"] = {n="Мотеґа Фаєрмейн",s="Мотеґа Фаєрмейн — тауренський учений із Застави Білого Рубежу в Тисячі Голок. Він присвятив себе описуванню небезпечних звірів каньйону, проте його дослідження раз у раз перериває мстивий дух вітряного змія та безрозсудні пригоди його юного помічника.",h="Мотеґа Фаєрмейн — тауренський учений із Застави Білого Рубежу в Тисячі Голок.",kw={"мотеґа фаєрмейн","застава білого рубежу","арікара","пао'ка","тисяча голок","вітряний змій"},ang={["class:Hunter"]="Мисливці легко знаходять спільну мову з Мотеґою, бо він покладається на вправних слідопитів: вони збирають рослини каньйону, вистежують віверн у Високосіді й полюють на могутнього духа Арікару.",["faction:Horde"]="Мотеґа уособлює поступ Орди в неприборкані краї Калімдору: він тримає хитку дослідницьку заставу й водночас оберігає Верховного Вождя Кайрна Бладгуфа від загроз світу духів.",["race:Tauren"]="Шануючи природу й віддано служачи Кайрнові Бладгуфу, Мотеґа втілює тауренський ідеал: вивчати створіння Земної Матері й захищати плем'я від прадавніх духів."},sec={{t="Учений каньйонів",b="Через чотири роки після Третьої війни Мотеґа Фаєрмейн вирушив на південь, у Тисячу Голок, щоб спостерігати й описувати незвичних звірів, які виживають серед височенних столових гір. Разом зі своїм юним помічником Пао'кою Свіфтмаунтіном — чий надміру дбайливий батько неохоче відпустив сина з Малгору — Мотеґа розбив табір поряд із Канаті Ґрейклаудом на Заставі Білого Рубежу. Він прийшов сюди заради тихих спостережень за природою, але суворі небезпеки на дні каньйону раз у раз вимагають від нього радше бойового підходу до виживання."},{t="Гнів Арікари",b="Мирні дослідження Мотеґи урвалися, коли із Застави Вільного Вітру надійшла звістка: в каньйони повернувся Арікара — лютий легендарний дух крилатого змія, що жадає помсти Кайрнові Бладгуфу. Мотеґа так і не збагнув, чому ця істота має зуб на Верховного Вождя, але діяв швидко, щоб захистити Орду. Він доручив розвідникам зібрати в улоговині каньйону агаву інсендію й віднести її старійшині Маґаті Ґрімтотем у Тандер Блаф, щоб та зачарувала її на священний порошок. За допомогою цього зілля мисливці викликали й убили духа змія, а його шкуру принесли на Заставу Білого Рубежу на доказ того, що Кайрн у безпеці."},{t="Охоронець Білого Рубежу",b="Арікара був не єдиною небезпекою, що загрожувала Мотеґі на Заставі Білого Рубежу. Місцеві кентаври Ґалак раз у раз прощупували табір і навіть замишляли вбити Канаті Ґрейклауда та його послідовників. На додачу юний Пао'ка відійшов від безпечного вогнища й зник у Високосіді, де аж кишать віверни. Хоч Мотеґа й сердився на легковажність молодого сміливця, він відчув величезне полегшення, коли мандрівники з Орди привели юнака назад живим."}},faq={{q="Хто такий Мотеґа Фаєрмейн?",a="Мотеґа Фаєрмейн — таурен-дослідник на Заставі Білого Рубежу в Тисячі Голок. Він прибув до каньйонів вивчати місцевих тварин разом з іншими воїнами й своїм помічником Пао'кою Свіфтмаунтіном.",al={"лор мотеґи фаєрмейна","хто такий мотеґа","мотеґа біла застава"}},{q="Де знайти Мотеґу Фаєрмейна?",a="Він на Заставі Білого Рубежу — невеликому таборі Орди на дні каньйону в Тисячі Голок, на північ від мерехтливих соляних низин.",al={"місце мотеґи","де мотеґа фаєрмейн","карта мотеґи"}},{q="Чому Мотеґу тривожить Арікара?",a="Арікара — мстивий дух змія, що з'явився в Тисячі Голок і полює на Кайрна Бладгуфа. Хоча Мотеґа не розуміє, чим Верховний Вождь заслужив злобу духа, він сприймає загрозу всерйоз і посилає мисливців викликати й знищити цю істоту.",al={"хто така арікара","чому вбивати арікару","арікара кайрн"}},{q="Яку роль у задумах Мотеґи відіграє Маґата Ґрімтотем?",a="Мотеґа доручає шукачам пригод зібрати агаву Інсендія й віднести її Маґаті Ґрімтотем на Узвишшя Старійшин у Тандер Блафі. Маґата завдяки своїм шаманським знанням зачаровує рослину й перетворює її на священний порошок, яким можна викликати невловну Арікару.",al={"порошок підпалу маґати","мотеґа й маґата","лор священного вогню"}},{q="Що сталося з супутником Мотеґи, Пао'кою?",a="Пао'ка Свіфтмаунтін забрів до небезпечних гнізд віверн на Високосіді й заблукав. Мотеґа тривожився за долю юнака, тим паче що батько Пао'ки неохоче відпустив його в мандри, але мандрівникам вдалося благополучно провести його назад до Застави Білого Рубежу.",al={"пао'ка свіфтмаунтін","зниклий таурен","завдання шлях додому"}},{q="Які ще небезпеки загрожують Заставі Білого Рубежу?",a="Окрім свавільних духів і хижаків, на табір постійно полюють кентаври Ґалак із околиць: вони влаштовують засідки й замишляють убити Канаті Ґрейклауда та інших тауренів застави.",al={"загрози заставі білого рубежу","кентаври біля білого рубежу","змова ґалака"}}},fp="15,267,22.511.0,20.632.1,22.483.1,23.204.0,35.153.0,38.275.1,56.248.1,44.276.1,45.212.0"}
P.entries["npc:mountaineer-barleybrew"] = {n="Горянин Барліброу",s="Горянин Барліброу — горянин Айронфорджа, що служить на Заставі Південної Брами в Дун Мороґу. Стережучи перевал, що веде на схід до Лох Модану, він покладається на ситне дворфійське вариво, щоб вартові лишалися пильними на лютому холоді.",h="Горянин Барліброу — горянин Айронфорджа, що служить на Заставі Південної Брами в Дун Мороґу.",kw={"горянин барліброу","горянин","застава південної брами","лох модан","варта","мерехтливий стаут","дун мороґ"},ang={["race:Dwarf"]="Для дворфів Барліброу втілює необхідну рівновагу між прикордонним обов'язком і міцним трунком, що тримає Каз Модан у безпеці."},sec={{t="Варта на східному перевалі",b="На Заставі Південної Брами, що стереже засніжену дорогу до Лох Модану, горянин Велларт Барліброу несе службу в прикордонній варті Айронфорджа. Як і багато горян, що служать на лютих вітрах Дун Мороґу, він цінує зміцнювальні властивості доброго дворфійського трунку. Носячи ім'я уславленого клану Барліброю, він допомагає доправляти партії міцного Мерехтливого Стауту до побратимів-вартових, яким потрібні тепло й витривалість під час довгих змін на гірських перевалах."}},faq={{q="Де знайти Горянина Барліброу?",a="Горянин Барліброу несе службу на Заставі Південної Брами — дворфійському укріпленні, що стереже східний перевал між Дун Мороґом і Лох Моданом.",al={"місце барліброу","де горянин барліброу","барліброу нпс"}},{q="Які в нього обов'язки на Заставі Південної Брами?",a="Він гірський вартовий, що охороняє дорогу й допомагає з постачанням, зокрема Мерехтливого стауту для інших горян, які несуть службу на перевалах.",al={"обов'язки барліброу","що робить барліброу"}},{q="Чи він родич інших Барліброу?",a="Так. Його брат — пивовар Реджолд Барліброю, а ще він може бути родичем Марлет, Малґіна й Йоруса Барліброу.",al={"рід барліброу","йорус барліброу родич"}}},fp="22,232,27.499.0,40.145.0,39.165.0,39.118.0"}
P.entries["npc:mountaineer-kadrell"] = {n="Горянин Кадрелл",s="Горянин Кадрелл — непохитний дворфійський вартовий, що стоїть навпроти Корчми «Міцний Лагер» у Телсамарі. Як ключова сполучна ланка серед горян Лох Модану, він координує розвідку, доставку припасів і оборону кордонів по всьому краю.",h="Горянин Кадрелл — непохитний дворфійський вартовий, що стоїть навпроти Корчми «Міцний Лагер» у Телсамарі.",kw={"горянин кадрелл","горянин","телсамар","лох модан","корчма міцний лагер","вартовий","розвідка"},ang={["faction:Alliance"]="Кадрелл покладається на мандрівників Альянсу, що проходять через Телсамар, щоб ті носили послання й допомагали далеким заставам горян, які борються з загрозами краю.",["race:Dwarf"]="Як член уславленого корпусу горян, Кадрелл утілює передову варту, що береже східні землі Айронфорджа від небезпек дикої природи."},sec={{t="Вартовий Телсамара",b="Стоячи на варті в людному поселенні Телсамар, Горянин Кадрелл — опора дворфійської оборони по всьому Лох Модану. Поки застави на околицях долини зносять невпинний тиск трогів, гнолів і тутешніх звірів, Кадрелл лишається в центрі містечка, щоб організовувати підкріплення, передавати накази й оцінювати польові звіти, які приносять мандрівні розвідники."},{t="Тримати зв'язок",b="Обов'язки Кадрелла часто передбачають підтримувати зв'язок між Телсамаром і віддаленими передовими позиціями. Чи то узгоджуючи дії з Горянином Стормпайком, чи то посилаючи шукачів пригод доповісти вартовим на кшталт Горянина Рокґара, Кадрелл дбає, щоб відокремлені застави, які стережуть гірські перевали, отримували життєво важливі припаси, підкріплення й оборонні відомості."}},faq={{q="Де знайти Горянина Кадрелла?",a="Кадрелл стоїть просто через дорогу від корчми «Міцний Лагер» у містечку Телсамар, серед хвилястих пагорбів Лох Модану.",al={"місце кадрелла","де кадрелл","знайти кадрелла"}},{q="Яка роль Кадрелла в Лох Модані?",a="Він із дворфійських горян і відповідає за зв'язок між місцевою владою Телсамара й віддаленими вартовими постами по всьому краю: узгоджує патрулі, постачання й донесення з кордону.",al={"що робить кадрелл","мета кадрелла","робота кадрелла"}},{q="Чому інші горяни посилають гінців до Кадрелла?",a="Оскільки він стоїть у самому центрі, біля корчми й головної дороги Телсамара, до Кадрелла сходяться всі польові донесення: він стежить, щоб термінові звіти від далеких розвідників доходили до оборони поселення.",al={"звіт кадреллу","чому звітувати кадреллу"}},{q="З ким співпрацює Кадрелл?",a="Кадрелл часто працює з іншими горянами на місцях, зокрема з Горянином Стормпайком і Горянином Рокґаром: збирає свіжі розвідувальні дані й розподіляє доручення з оборони від місцевих загроз.",al={"контакти кадрелла","кого знає кадрелл"}}},fp="19,256,23.378.0,22.362.0,39.143.0,37.208.0,50.221.0,33.192.0"}
P.entries["npc:mountaineer-stormpike"] = {n="Горянин Стормпайк",s="Горянин Стормпайк — горянин з Айронфорджа, що стоїть на варті на Станції Алґаз у північному Лох Модані. Наглядаючи за гірським перевалом до Багнокраю, він невтомно береже важливі шляхи постачання від трогів і кобольдів, що чатують довкола. Як гордий член клану Стормпайк, він вірний Айронфорджу й безпеці дворфійських земель.",h="Горянин Стормпайк — горянин з Айронфорджа, що стоїть на варті на Станції Алґаз у північному Лох Модані.",kw={"горянин стормпайк","станція алґаз","лох модан","кобольди","троги","дун алґаз","багнокрай"},ang={["faction:Alliance"]="Станція Алґаз тримає ключовий суходільний шлях, що з'єднує Айронфордж із Гаванню Менетіл у Багнокраї, тож пильність Стормпайка вкрай важлива для постачання Альянсу.",["race:Dwarf"]="Для дворфа з Айронфорджа допомогти товаришеві-горянину на кшталт Стормпайка — почесний обов'язок захищати внутрішні кордони Каз Модану від злодійкуватої напасті."},sec={{t="Охоронець Станції Алґаз",b="Станція Алґаз на північному кордоні Лох Модану — важливий пункт перед небезпечним спуском до Багнокраю. Горянин Стормпайк служить тут серед скелястих кряжів і постійних загроз дикої місцини. Його головний обов'язок — підтримувати зв'язок і тримати дороги відкритими для мандрівників і валок із припасами, що проходять через Дун Алґаз."},{t="Боротьба з місцевою напастю",b="Північні околиці Лох Модану потерпають від невгамовної напасті — від кобольдів, що кишать на сусідніх копальнях, до підземних трогів. Стормпайк раз у раз залучає перехожих шукачів пригод, щоб приборкати ці загрози, — передусім кобольдів, які вселилися в Шахту Срібного Потоку й поклали брудні лапи на дворфійські інструменти, що їх зберігала там Ліга Шахтарів."}},faq={{q="Де знайти Горянина Стормпайка?",a="Він несе службу на Станції Алґаз, на півночі Лох Модану, при гірській дорозі, що веде на північ, у прохід Дун Алґаз, до Багнокраю.",al={"місце стормпайка","де стормпайк","де горянин стормпайк"}},{q="Хто такий Горянин Стормпайк?",a="Він горянин з Айронфорджа зі славетного клану Стормпайків. Він вартовий і розвідник застави, що має берегти північний перевал Лох Модану від небезпек диких країв.",al={"хто такий стормпайк","лор горянина стормпайка","хто горянин стормпайк"}},{q="З якими загрозами він має справу на Станції Алґаз?",a="Заставі постійно докучають навали трогів і кобольдів, що заполонили схили й каменоломні. Стормпайк знищує ці загрози, щоб кур'єри й каравани могли безпечно проходити.",al={"небезпеки станції алґаз","що нападає на станцію алґаз","загрози півночі лох модану"}},{q="Навіщо потрібна Станція Алґаз?",a="Станція Алґаз — застава Айронфорджа, що стежить за межею між Лох Моданом і суворими тунелями Дун Алґазу. Це перевалочний пункт для горян, які патрулюють прикордоння й стежать, щоб торговий шлях був вільний.",al={"що таке станція алґаз","лор станції алґаз","мета станції алґаз"}},{q="Чи він пов'язаний із Вартою Стормпайків у Долині Альтерак?",a="Він носить ім'я славетного клану Стормпайків — дворфійського роду, відомого в Айронфорджі своїми запеклими воїнами й старателями, хоча нинішні накази тримають його на перевалах Лох Модану.",al={"стормпайк альтерак","клан стормпайк зв'язок","чи він варта стормпайків"}},{q="Які завдання Горянин Стормпайк дає шукачам пригод?",a="Він посилає шукачів пригод забрати спорядження Ліги Шахтарів із Шахти Срібного Потоку, яку заполонили кобольди, і віднести його замовлення на новий щит аж до Стормвінда, дворфові-зброярю Фуренові Лонґбірду.",al={"завдання стормпайка","доручення горянина стормпайка","завдання брудні лапи"}}},fp="21,362,25.379.0,29.350.0,39.151.0,29.207.0,48.204.0,32.221.0,55.217.0,58.211.0"}
P.entries["npc:mountaineer-thalos"] = {n="Горянин Талос",s="Горянин Талос — дворфійський вартовий, що стоїть біля виходу з Долини Холодного Хребта на Перевал Холодного Кряжа. Йому доручено стерегти шлях, і він попереджає подорожніх про раптову навалу трогів, що забила тунель. Шукачі пригод із нагальними звітами з долини покладаються на нього, щоб безпечно дістатися Хараноса.",h="Горянин Талос — дворфійський вартовий, що стоїть біля виходу з Долини Холодного Хребта на Перевал Холодного...",kw={"горянин талос","горянин","перевал холодного кряжа","троги","вартовий","харанос","долина холодного хребта"},ang={["faction:Alliance"]="Талос підтримує зв'язок уздовж життєво важливого гірського коридору, що з'єднує оборонні сили долини з центральним командуванням Айронфорджа.",["race:Dwarf"]="Для молодих дворфів, що залишають колиску батьківщини, Талос — суворе нагадування: загроза трогів — не навчальна вправа, а облога, що тисне на самі пороги Айронфорджа.",["race:Gnome"]="Гноми, що вирушають із притулків біженців Гномреґану, бачать Талоса на варті біля головного наземного шляху, що спускається до Хараноса й Айронфорджа."},sec={{t="Вартовий Перевалу Холодного Кряжа",b="На засніженій межі, де Долина Холодного Хребта переходить у глибші скелі Дун Мороґу, Горянин Талос — перша лінія оборони для мандрівників, що залишають дворфійські навчальні угіддя. Перевал Холодного Кряжа став підступною тісниною, яку захопили ворожі троги, що вирили собі шлях з підземних глибин. Талос несе варту на холоді, застерігаючи неготових повернути назад і оцінюючи, чи досить у витривалих кур'єрів твердості, щоб пробитися до ширшого королівства."},{t="Контрольний пункт кур'єра",b="Коли Ґрелін Вайтбірд завершує свій звіт про пересування тролів Морозогривів у відлюдній долині, кур'єрові, що несе його до брата Сеніра в Харанос, кажуть поговорити з Горянином Талосом, перш ніж заходити до тунелю. Переконавшись, що шукач пригод здатен подолати заражений прохід, Талос скеровує його далі до Хараноса, де командири краю координують оборону Дун Мороґу. Його пильна присутність гарантує, що важливі відомості дійдуть до військових очільників Айронфорджа, а не згинуть у снігу."}},faq={{q="Хто такий Горянин Талос?",a="Горянин Талос — горянин з Айронфорджа, що стоїть біля південного входу на Перевал Холодного Кряжа. Його пост стереже межу між Долиною Холодного Хребта й широкими просторами Дун Мороґу.",al={"лор талоса","хто такий талос","горянин талос"}},{q="Чому Горянин Талос відраджує мандрівників іти далі?",a="Перевал Холодного Кряжа заполонили люті троги Кам'янощелепих. Талос застерігає мирних людей і бійців-новачків від спроб перейти, пропускаючи всередину лише вправних кур'єрів і загартованих воїнів.",al={"чому перевал закритий","троги в перевалі","небезпека перевалу колдрідж"}},{q="Куди Горянин Талос посилає шукачів пригод?",a="Переглянувши термінові польові донесення з Долини Холодного Хребта, Талос спрямовує мандрівників через перевал до Хараноса — найближчого поселення на шляху до Айронфорджа.",al={"куди йти після талоса","призначення талоса","наступне місто"}},{q="Яке донесення Талос отримує від Сеніра Вайтбірдого?",a="Від самого Сеніра — жодного. Повз Талоса проходить донесення Ґреліна Вайтбірда про загрозу від тролів Морозогривів у Долині Холодного Хребта: його несе кур'єр до Ґрелінового брата Сеніра в Хараносі. Талос застерігає гінця про трогів і пропускає його далі тунелем.",al={"донесення сеніра","депеша сеніра","що читає талос"}},{q="До якої фракції належить Горянин Талос?",a="Талос — присяглий член горян Айронфорджа, загартованих прикордонних слідопитів, які патрулюють для Альянсу кордони, тунелі й засніжені гірські стежки Дун Мороґу.",al={"фракція талоса","чи талос з айронфорджа","горяни альянсу"}},{q="Чи можна пройти Перевал Холодного Кряжа, не поговоривши з Талосом?",a="Перевал відкритий для кожного, хто наважиться в нього увійти, але розмова з Талосом гарантує, що шукач пригод доставить до Хараноса важливі розвідувальні дані й дізнається про небезпеки, які чекають попереду.",al={"чи треба говорити з талосом","обійти талоса"}}},fp="18,308,26.499.0,22.529.0,26.194.0,49.215.0,47.175.0,54.285.0,47.186.0,56.191.0"}
P.entries["npc:mr-smite"] = {n="Пан Кара",s="Пан Кара — могутній таурен, старший помічник на флагмані Братства Дефіас глибоко в Мертвих Копальнях. Вправний майстер зброї на службі в капітана Ґрінскіна, він із нещадною дисципліною стереже підступи до потаємного броненосця з боку доків. Кожен, хто стане проти нього, муситиме протистояти його змінному арсеналу й нищівній силі.",h="Пан Кара — могутній таурен, старший помічник на флагмані Братства Дефіас глибоко в Мертвих Копальнях.",kw={"пан кара","таурен","старший помічник","майстер зброї","мертві копальні","бухта айронклад"},ang={["class:Warrior"]="Кара демонструє дивовижну бойову виучку, плавно переходячи від швидких ударів однією рукою до двох сокир і нищівних ударів дворучного молота.",["faction:Alliance"]="Кара — головна перепона, що не дає агентам Альянсу прорватися трапом до капітана Ґрінскіна й Едвіна Венкліфа.",["race:Tauren"]="Побачити родича-таурена старшим помічником серед морських розбійників у Східних Королівствах — неабияке потрясіння для будь-якого мандрівника з Малгору."},sec={{t="Старший помічник бухти",b="Пан Кара стереже доки Бухти Айронклад і служить старшим помічником гобліна, капітана Ґрінскіна. Братство Дефіас складається здебільшого зі знедолених людей і союзних гоблінів-майстрів, тож Кара тут — разюча дивина: велетенський, загартований у боях таурен, далеко від рівнин Калімдору. Йому доручено тримати в суворому порядку галасливу піратську команду, і він стежить, щоб оснащення таємного броненосця Едвіна Венкліфа йшло без перешкод."},{t="Смертоносний майстер зброї",b="Кара — не просто грубий наглядач, а театральний і різнобічний майстер зброї. Йому подобається гратися з горе-героями: він навмисно затягує бій, щоб подарувати супротивникам оманливу надію. Коли ж на нього насідають, він так тупає, що здригається земля, приголомшуючи ворогів, а сам тим часом нишпорить у скрині зі зброєю. Бій він починає зі спритним дуельним клинком, далі береться за дві сокири, а коли його остаточно розлютять — за свій величезний дворучний бойовий молот."}},faq={{q="Чому таурен працює з людьми-бандитами у Вестфолі?",a="Хоча переважна більшість тауренів живе в Калімдорі разом із союзниками з Орди, вигнанці-найманці й мандрівники часом добираються на схід. Кара — піратський офіцер, а не ідейний прибічник Братства Дефіас: його найняли разом із командою капітана Ґрінскіна наглядати за бухтою й готувати броненосець до виходу в море.",al={"чому таурен у мертвих копальнях","лор пана кари","таурен пірат"}},{q="Хто начальник Пана Кари?",a="Кара підпорядковується безпосередньо капітанові Ґрінскіну — гобліну, господареві піратського корабля, що стоїть на якорі в Бухті Айронклад. А над ними обома в усій цій змові стоїть Едвін Венкліф, верховний очільник Братства Дефіас.",al={"чий бос пан кара","на кого працює пан кара"}},{q="Якою зброєю б'ється Пан Кара?",a="Кара починає бій зі Злодійським Клинком. Коли бій обертається не на його користь, він відступає до своєї скрині й бере пару Різаків Кари, а коли його притиснуть до краю — виймає Могутній Молот Кари.",al={"яку зброю використовує пан кара","яку зброю дістає кара зі скрині"}},{q="Де знайти Пана Кару?",a="Пан Кара вартує на дерев'яних причалах Бухти Айронклад — останньої печери в Мертвих Копальнях — і стереже трап, що веде на величезний броненосець Дефіас.",al={"місце пана кари","де пан кара"}},{q="Чи б'ється Пан Кара сам?",a="Кара тримає поруч двох прихованих розбійників Дефіас, готових напасти з засідки на кожного чужинця, що просуватиметься причалом до корабля.",al={"чи кара б'ється сам","охорона кари"}},{q="Чому Пан Кара такий небезпечний у ближньому бою?",a="Його фірмовий тауренський Бойовий Тупіт пускає по дерев'яному причалу ударну хвилю, що приголомшує цілі загони шукачів пригод — якраз на стільки, щоб він устиг узяти зі скрині нову зброю й відновити напад іще важчим озброєнням.",al={"приголомшення кари","бойовий тупіт кари"}}},fp="9,349,22.480.0,21.512.0,55.342.0,28.219.0,49.205.0,29.166.0,27.133.0,52.214.0"}
P.entries["npc:mull-thunderhorn"] = {n="Малл Тандергорн",s="Малл Тандергорн — тауренський старійшина, що мешкає в Селі Бладгуф у Малгорі. Глибоко відданий Земній Матері та рівновазі землі, він наглядає за священними водяними криницями, розкиданими по рівнинах. Коли чужинці-визискувачі загрожують життєдайним водам краю, Малл проводить молодих тауренів через обряди очищення прабатьківських джерел.",h="Малл Тандергорн — тауренський старійшина, що мешкає в Селі Бладгуф у Малгорі.",kw={"малл тандергорн","старійшина","криниці","очищення","тотем","село бладгуф","малгор"},ang={["class:Druid"]="Друїди поділяють тривогу Малла, бо на власні очі бачать, як отруєні криниці руйнують рівновагу живого світу Малгору.",["class:Shaman"]="Шамани впізнають у Маллі опору на гармонію стихій: його тотеми очищення закликають духів предків, щоб зцілити води, роз'ятрені механічною жадобою.",["faction:Horde"]="Боротьба Малла підкреслює тертя Орди з такими незалежними хижими організаціями, як Венчурна Компанія, що без дозволу вигрібають багатства Калімдору.",["race:Tauren"]="Для тауренів Малл Тандергорн — це пам'ять племені та обов'язок перед предками; він веде молодих сміливців, що захищають священні рівнини від жадібних чужинців."},sec={{t="Хранитель священних вод",b="Стоячи на варті в Селі Бладгуф, Малл Тандергорн несе на собі тягар духовного добробуту Малгору. Кочові племена зібралися під рукою Верховного Вождя Кайрна Бладгуфа, щоб звести собі постійну домівку, та їхні землі вже в облозі жадібності й нерозважливого загарбання. Малл — духовна опора для молодих сміливців, що виходять із Табору Нарачі; він кличе їх берегти життєво важливі скарби предків."},{t="Отруєні криниці й Венчурна Компанія",b="Головна біда Малла — раптова хвороба, що шириться водами Малгору: криницями Вінтергуфів, Тандергорнів і Вайлдмейнів. Сліди цієї скверни ведуть до гоблінів Венчурної Компанії — безсовісного торгового підприємства, що вгризається в довколишні пагорби й зливає отруту в місцеві ґрунтові води. Малл доручає молодим тауренам виготовити особливі тотеми очищення й провести обряд біля кожної прабатьківської криниці, перш ніж зараза безповоротно просякне землю та її живність."}},faq={{q="Хто такий Малл Тандергорн?",a="Малл Тандергорн — таурен, що дає завдання в Селі Бладгуф у Малгорі. Він охоронець священних криниць краю й проводить обряди та ритуали, щоб земля і її води лишалися чистими від зовнішнього зараження.",al={"лор малла тандергорна","хто такий малл","малл село кривавого копита"}},{q="Чому Малла Тандергорна непокоять криниці?",a="Криниці предків — Вінтергуфів, Тандергорнів і Вайлдмейнів — дають життя племенам і тваринам Малгору. Непрохані промисли неподалік отруїли ці священні джерела смердючими стоками й брудом, що загрожує природній рівновазі рівнин.",al={"чому отруєні криниці","криниці малгору","отруєна криниця вінтерхуф"}},{q="Хто забруднює криниці Малгору?",a="Бруд спричиняє Венчурна Компанія — безрозсудне гоблінське підприємство, що закріплюється на околицях Малгору з копальнями й лісорубством. Їхні промисли не зважають на священну землю й зливають промислові отрути в місцеві підземні води.",al={"хто отруїв воду","венчурна компанія в малгорі","хто забруднив криниці"}},{q="Чому завдання Малла з очищення стосуються лише тауренів?",a="Криниці мають глибоке родове й духовне значення, пов'язане з родами-засновниками тауренських племен — Тандергорнами, Вінтергуфами й Вайлдмейнами. Їхнє очищення вважають священним обрядом посвяти й культурним обов'язком тауренів, що дорослішають.",al={"завдання лише для тауренів","чому тільки таурени","вимоги малла тандергорна"}},{q="Як очищають криниці?",a="Малл навчає мандрівників збирати особливо освячені тотеми, наповнені силою місцевих природних реагентів — пазурів і шкур. Освячені тотеми несуть просто до забруднених криниць, щоб спрямувати духовне очищення й змити неприродні отрути.",al={"як очистити криниці","очисні тотеми","очищення води"}},{q="Що таке Обряд Видіння?",a="Обряд Видіння — основна духовна мандрівка, яку здійснюють молоді таурени, щоб поспілкуватися з предками й духами тварин. Послушників посилають до Зарлмана Ту-Мунса в Селі Бладгуф пройти це випробування видінням як один з Обрядів Земної Матері.",al={"обряд видіння","що таке обряд видіння"}}},fp="16,359,29.438.0,37.540.1,24.237.0,54.293.0,44.271.0,54.266.0,33.268.0,27.268.0"}
P.entries["npc:mupsi-shacklefridd"] = {n="Мупсі Шеклфрідд",s="Мупсі Шеклфрідд — гоблінка, що мешкає під самим Раджетом у Пустках. Вона — місцевий контакт для мандрівників, які хочуть залагодити зіпсовані стосунки з картелем Стімвідл.",h="Мупсі Шеклфрідд — гоблінка, що мешкає під самим Раджетом у Пустках.",kw={"мупсі шеклфрідд","раджет","картель стімвідл","гобліни","репутація","пустки"},sec={{t="На околиці Раджета",b="Мупсі Шеклфрідд веде свої справи неподалік від Раджета, на запорошених прибережних дорогах Пусток. Біля портового містечка життя завжди вирує: периметром ходять вартові Стімвідлу, приходять і йдуть купці. Тим, хто опинився в немилості в гоблінів, Мупсі пропонує шлях до примирення — якщо мандрівники готові дати картелеві припаси й працю, яких той вимагає."}},faq={{q="Хто така Мупсі Шеклфрідд?",a="Це гоблінка, що стоїть просто за межами Раджета в Пустках і допомагає мандрівникам, які хочуть відновити свою репутацію в картелі Стімвідл.",al={"мупсі","хто така мупсі","мупсі раджет"}},{q="Де її знайти?",a="Мупсі стоїть одразу за Раджетом у Пустках, так близько до поселення, що портова варта й патрулі час від часу проходять повз неї.",al={"місце мупсі","де мупсі шеклфрідд","знайти мупсі"}},{q="Навіщо комусь говорити з Мупсі Шеклфрідд?",a="Мандрівники, що розгнівали картель Стімвідл — найчастіше сутичками з гоблінами чи підтримкою піратів, — можуть відновити свою репутацію, жертвуючи Мупсі припаси.",al={"загоєння старих ран раджет","здача репутації раджета","завдання мупсі"}}},fp="18,219,27.406.0,26.165.0,21.158.0,45.185.0"}
P.entries["npc:mutanus-the-devourer"] = {n="Мутанус Пожирач",s="Мутанус Пожирач — жахливий блідий мурлок, що постав просто зі Смарагдового Жахіття. Він чатує в найтемніших закутках розуму сплячого друїда Наралекса й виринає, щоб пожерти кожного, хто намагається зламати владу Жахіття над Печерами Стогонів. Убити цю спотворену потвору — останній крок до того, щоб звільнити Наралекса з його болісного сну.",h="Мутанус Пожирач — жахливий блідий мурлок, що постав просто зі Смарагдового Жахіття.",kw={"мутанус пожирач","мурлок","наралекс","смарагдове жахіття","печери стогонів","учень наралекса"},ang={["class:Druid"]="Мутанус показує, які страшні небезпеки чатують на тих, хто без запобіжників занурюється надто глибоко в Смарагдовий Сон, — адже розум побратима-друїда цілком поглинула порча.",["faction:Horde"]="Орда не може дозволити Мутанусові та Жахіттю отруїти серце Пусток, бо це загрожує життєдайним водам оаз, без яких не вижити Дуротару й Малгору.",["race:NightElf"]="Для калдореїв Мутанус — трагедія, що ожила: він втілює те, як шляхетне прагнення Наралекса зцілити Пустки обернулося жахливим маренням."},sec={{t="Найбільший страх сновидця",b="Коли друїд із нічних ельфів Наралекс дістався підземних джерел під Пустками, він хотів повернути життя посушливим пустищам, поєднавши їх зі Смарагдовим Сном. Натомість у його думки вдерлася прадавня порча, відома як Смарагдове Жахіття. Ув'язнений у болісному видінні, Наралекс побачив, як його потаємні страхи набувають плоті. Порча вчепилася в дивну, первісну відразу в душі друїда — його глибоко вкорінений жах перед мурлоками — і роздула її до велетенського хижака-альбіноса."},{t="Жахіття наяву",b="Темна сила, що заполонила розум Наралекса, послала Мутануса у світ наяву, щоб друїд ніколи не прокинувся. Коли Учень Наралекса проводить обряд, щоб пробудити свого наставника, Мутанус проривається крізь межу між сном і дійсністю. Разом зі своєю протиприродною подобою він приносить із краю снів чужинські реліквії — як-от таємничий Перстень Морських Глибин. Доки Мутанус не загине, Наралекс лишається в'язнем власної спотвореної уяви."}},faq={{q="Що таке Мутанус Пожирач?",a="Мутанус Пожирач — величезна бліда потвора, схожа на мурлока, породжена Смарагдовим Жахіттям. Це не звичайний мешканець Азероту, а живий кошмар, викликаний у дійсність зі зіпсованого розуму сплячого друїда Наралекса.",al={"хто такий мутанус","що за істота мутанус","чи мутанус мурлок"}},{q="Чому Мутанус схожий на велетенського мурлока?",a="Жахіття спотворило підсвідомі думки Наралекса й витягло з них його найгіршого особистого ворога — мурлоків. Скверна обернула цей глибоко вкорінений страх на зброю, втіливши його у величезній потворі-альбіносі.",al={"чому мурлок","чому мутанус мурлок","страх наралекса перед мурлоком"}},{q="Чому Мутанус з'являється наприкінці ритуалу?",a="Темна сила, що псує Смарагдовий Сон, наказала Мутанусу не дати нікому перервати сон Наралекса. Коли учні Наралекса починають ритуал пробудження, Мутанус переходить у справжню печеру, щоб пожерти рятівників.",al={"коли з'являється мутанус","чому викликають мутануса","бос ритуалу наралекса"}},{q="Звідки взявся Мутанус?",a="Мутанус походить зі Смарагдового Жахіття — зіпсованого царства, що полонило Наралекса. Переходячи зі світу снів до Азероту, він навіть приніс із собою дивні реліквії на кшталт Персня Глибин.",al={"походження мутануса","чи мутанус із кошмару","смарагдовий кошмар мутанус"}},{q="Чи вбивство Мутануса рятує Наралекса?",a="Так. Щойно Мутануса вбито, безпосередня влада кошмару над розумом Наралекса розбивається, і його учні можуть пробудити друїда й розвіяти темний транс печери.",al={"чи врятований наралекс","що буде після смерті мутануса","пробудження наралекса"}},{q="Чому Мутанус не боїться магії тіней?",a="Мутанус — потвора, сплетена з темних енергій кошмару, тож від природи стійкий до некротичних і тіньових заклинань, що вразили б звичайних звірів.",al={"імунітет мутануса до тіні","закляття тіні мутанус","чи мутанус імунний до тіні"}}},fp="20,358,22.505.0,20.460.1,29.236.0,42.199.0,49.236.0,29.205.0,34.184.1,38.158.0"}
P.entries["npc:mux-manascrambler"] = {n="Мукс Манаскремблер",s="Мукс Манаскремблер — дивакуватий гоблін-інженер, що мешкає в пустельному поселенні Ґаджетзан. На відміну від багатьох своїх колег, які думають лише про вибухівку чи гірниче обладнання, Мукс має дивне захоплення надприродним і окультними енергіями.",h="Мукс Манаскремблер — дивакуватий гоблін-інженер, що мешкає в пустельному поселенні Ґаджетзан.",kw={"мукс манаскремблер","гоблін","інженерія","ґаджетзан","привиди","надприродне"},ang={["profession:Engineering"]="Мукс — диво серед гоблінських майстрів: він застосовує шестерні й енергоелементи, щоб ловити й переганяти незримі надприродні сили, а не просто все підривати."},sec={{t="Майстер незримого",b="У будівлі в центрі Ґаджетзана, позаду Дріза Планкбоу та його брязкітливих ботів-м'ясників, сидить Мукс Манаскремблер. Поки картель Стімвідл жваво торгує нафтою, зброєю й брухтом, Мукс спрямовує свою винахідливість на таємничіші заняття — світ духів і надприродні аномалії. Свої технічні знання він вкладає в химерні пристрої, здатні виявляти й переганяти рештки привидів та взаємодіяти з ними, і так поєднує грубе гоблінське ремесло з незримими світами мертвих."}},faq={{q="Де знайти Мукса Манаскремблера?",a="Мукс живе в Ґаджетзані на півночі Танарісу. Ви знайдете його в будівлі неподалік від центру цього пустельного торгового осередку, просто за Дрізом Планкбоу й ботами-м'ясниками, що розбирають туші.",al={"місце мукса","де мукс","карта мукса манаскремблера"}},{q="Якою роботою займається Мукс?",a="Мукс — інженер, одержимий примарними й невидимими силами. Замість звичайних підривів чи транспорту він будує особливі пристрої, що здатні виявляти духів, переганяти ектоплазму й приборкувати тайну надприродну силу.",al={"робота мукса","що продає мукс","дослідження мукса"}},{q="Чи належить Мукс до якоїсь фракції?",a="Мукс належить до картелю Стімвідл у Ґаджетзані. Як незалежний гоблінський ділок, він суворо дотримується торговельного нейтралітету й охоче допомагає шукачам пригод і з Орди, і з Альянсу.",al={"чи мукс з орди","чи мукс нейтральний","мукс альянс"}}},fp="17,249,24.504.0,35.208.0,30.236.0,29.215.0"}
P.entries["npc:mydrannul"] = {n="Мідраннул",s="Мідраннул — крамар нічних ельфів, що продає всяку всячину на Терасі Воїна в Дарнасусі. Він обслуговує Вартових, солдатів і гостей столиці, тримаючи під рукою найпотрібніше: припаси, набої й провіант.",h="Мідраннул — крамар нічних ельфів, що продає всяку всячину на Терасі Воїна в Дарнасусі.",kw={"мідраннул","крамар","тераса воїна","дарнасус","припаси","набої"},ang={["faction:Alliance"]="Мандрівники Альянсу, що прибувають на Тельдрассил, можуть покластися на торговців на кшталт Мідраннула на Терасі Воїна: у нього є прості торби, набої й похідні харчі.",["race:NightElf"]="Для нічних ельфів, що навчаються в Дарнасусі, Мідраннул — постачальник щоденного спорядження та стріл, завдяки якому Вартові завжди мають усе потрібне."},sec={{t="Припаси Тераси Воїна",b="Серед військових наметів і тренувальних майданчиків Тераси Воїна Мідраннул продає необхідне спорядження і захисникам Дарнасуса, і мандрівним шукачам пригод. У нього є все, що знадобиться в поході: стріли для лучників і кулі для стрільців, метальні ножі, кремінь, торбинки й прості харчі. Порядкуючи своєю яткою в бойовому кварталі міста, він дбає, щоб Вартові й новобранці, які готуються до служби на Тельдрассилі, не потерпали від браку дрібниць першої потреби."}},faq={{q="Де знайти Мідраннула?",a="Мідраннул — на Терасі Воїна, південно-східному бойовому районі Дарнасуса у верхівці Тельдрассила.",al={"місце мідраннула","де мідраннул","карта мідраннула"}},{q="Що продає Мідраннул?",a="Він торгує всякою всячиною: торбами, простою їжею, напоями й табірним приладдям на кшталт кресала й трута, а ще метальною зброєю й набоями — стрілами та кулями.",al={"крам мідраннула","що продає мідраннул","товари мідраннула"}},{q="Чи дає Мідраннул якісь завдання?",a="Так. Окрім торгівлі припасами, Мідраннул посилає шукачів пригод до своєї подруги Несси Шедовсонг — торговки рибою в Селищі Рут'теран, якій треба переправити посилку на Темне Узбережжя.",al={"завдання мідраннула","доручення від мідраннула"}}},fp="9,224,33.502.0,29.134.0,31.190.0,32.172.0"}
P.entries["npc:nalpak"] = {n="Налпак",s="Налпак — учень-друїд, таурен, що пильнує неспокійні Печери Стогонів у Пустках. Зі своєї високої печери в скелі над входом він кличе мандрівних шукачів пригод допомогти стримати жахіття, що спотворює підземну природу.",h="Налпак — учень-друїд, таурен, що пильнує неспокійні Печери Стогонів у Пустках.",kw={"налпак","печери стогонів","наралекс","девіантні шкури","друїди","смарагдовий сон"},ang={["class:Druid"]="Для побратимів-друїдів Налпак — похмуре нагадування про те, яким небезпечним буває дотик до Смарагдового Сну, коли в обряді, що мав зцілювати, пускає коріння темрява.",["race:Tauren"]="Налпак уособлює відданість тауренів зціленню спраглих земель Калімдору: він не кидає місії навіть тоді, коли лихо спіткало самих сновидців."},sec={{t="Вартовий над печерами",b="Сховавшись у потаємній печері просто над входом до Печер Стогонів, Налпак лишається вірним задуму архідруїда Наралекса. Поки його наставник лежить глибоко внизу в полоні спотвореного сну, Налпак намагається стримати скверну, що ширшає. Він просить шукачів пригод збирати девіантні шкури, з яких можна вичинити шкіру."}},faq={{q="Де перебуває Налпак?",a="Налпак — у печері високо на скелі просто над природною кам'яною аркою, що веде до Печер Стогонів у центрі Пусток.",al={"місце налпака","де налпак","знайти налпака"}},{q="Хто такий Налпак?",a="Він таурен-друїд, один з Учнів Наралекса. Він має стежити за спотвореними створіннями, що виповзають із Печер Стогонів, поки його наставник намагається відродити Пустки через Смарагдовий Сон.",al={"хто такий налпак","лор налпака"}},{q="Навіщо Налпакові шкури девіантів?",a="Налпак хоче дослідити шкури девіантних створінь, що заполонили Печери Стогонів. Попри їхню злу природу, він вірить, що їхні незвичайні шкури можна з користю застосувати в шкірництві.",al={"навіщо шкури девіантів","завдання шкур девіантів"}},{q="Що пов'язує Налпака з Наралексом?",a="Налпак — вірний учень і послідовник Архідруїда Наралекса, один з учнів, яких послали підтримати сміливу спробу знову пробудити джерела Пусток.",al={"чи налпак учень наралекса","налпак і наралекс"}}},fp="6,259,25.319.0,24.154.0,14.216.0,35.190.0,41.173.0"}
P.entries["npc:nara-meideros"] = {n="Нара Мейдерос",s="Нара Мейдерос — нічна ельфійка, жриця, що мешкає серед мирної зелені Парку в Стормвінді. Наставниця послушників, вона несе вчення Елуни в серці людської столиці.",h="Нара Мейдерос — нічна ельфійка, жриця, що мешкає серед мирної зелені Парку в Стормвінді.",kw={"нара мейдерос","жриця елуни","нічні ельфи","парк","стормвінд","елуна"},ang={["class:Priest"]="Для жерців із нічних ельфів, що мандрують Східними Королівствами, Нара — наставниця в найважливіших расових обрядах, до якої не треба вертатися аж у Калімдор.",["race:NightElf"]="Далеко від лісів Ашенвалю й Тельдрассила Нара Мейдерос і Парк дарують затишну частку дому серед гамірних кам'яних мурів людської столиці."},sec={{t="Жриця у Стормвінді",b="Більшість жриць Елуни лишається в Калімдорі під гіллям Тельдрассила, та Нара Мейдерос живе далеко за Великим Морем, у Стормвінді. Її можна знайти в Парку — притулку, який плекають нічні ельфи-друїди й жерці, що навідуються до міста. Тут вона веде молодих шукачів духовного шляху стежкою божественної відданості. Поруч із людськими служителями Святого Світла з Соборної Площі Нара дає нічним ельфам, що гостюють чи живуть у Східних Королівствах, знайомий зв'язок із благодаттю Богині Місяця."}},faq={{q="Де знайти Нару Мейдерос?",a="Нара Мейдерос — у Парку Стормвінда, серед місячних колодязів і високих дерев, що нагадують нічним ельфам-мандрівникам про дім.",al={"місце нари мейдерос","де нара мейдерос","тренер жерців парку"}},{q="Яку роль відіграє Нара Мейдерос?",a="Вона наставниця жерців, що допомагає послушникам і жерцям, які зростають, а людей-жерців посилає до Собору Світла вивчати молитви на кшталт Відчайдушної Молитви.",al={"що робить нара","роль нари мейдерос","хто така нара мейдерос"}},{q="Чому жриця нічних ельфів живе в Стормвінді?",a="Що міцнішими стають зв'язки між нічними ельфами Дарнасуса й Великим Альянсом, то активніше посланці, друїди й жерці нічних ельфів присутні в Парку, допомагаючи родичам і представляючи свої духовні традиції.",al={"чому жриця нічних ельфів у стормвінді","нічна ельфійка в стормвінді"}}},fp="13,205,24.491.0,31.148.0,35.176.0,51.220.0"}
P.entries["npc:narain-soothfancy"] = {n="Нарейн Сутфенсі",s="Нарейн Сутфенсі — дивакуватий гном, що мешкає у відлюдній хатині на пляжі трохи на північ від Порту Стімвідла в Танарісі. Він гучно рекламує себе як великого віщуна, що вміє передбачати майбутнє, але ті, хто його знає, вважають його ясновидіння суцільним фарсом — на відміну від справжнього інженерного генія.",h="Нарейн Сутфенсі — дивакуватий гном, що мешкає у відлюдній хатині на пляжі трохи на північ від Порту Стімвідла...",kw={"нарейн сутфенсі","гном","віщун","інженерія","порт стімвідла","танаріс"},ang={["profession:Engineering"]="Інженерам шалені винаходи Нарейна видадуться захопливими, хай навіть він волів би вдавати, що його механічні тріумфи — насправді містичні видіння.",["race:Gnome"]="Нарейн — гномівська винахідливість у найдивакуватішому її прояві: він поєднує блискуче вміння розв'язувати технічні задачі з химерними, нав'язливими захопленнями."},sec={{t="Видіння ясновидця й практична механіка",b="Perched on the eastern coast of Tanaris just north of the goblin docks, Narain Soothfancy lives as a retired engineer turned self-proclaimed master fortune teller. He routinely greets visitors by pressing unopened envelopes against his forehead or making wildly inaccurate guesses about their business, such as wondering if they have arrived seeking the legendary Ashbringer. Despite his theatrical charade, Narain possesses deep technical knowledge. Even ancient beings like the blue dragon Azuregos note that while Narain is a terrible psychic, his engineering aptitude is undeniably brilliant. A handbook titled 'Soothsaying for Dummies' rests nearby."},{t="Аварія на узбережжі",b="Перш ніж оселитися біля Порту Стімвідла, Нарейн розбився на літальній машині далеко на півдні, на Пляжі Край Землі. Він вижив після аварії завдяки несподіваному порятунку, проте дивацтва й химерні нав'язливі ідеї тримають його на самоті на пустельному березі, де він майструє пристрої, що межують із тайною магією, і продає сумнівні пророцтва кожному перехожому."}},faq={{q="Хто такий Нарейн Сутфенсі?",a="Нарейн Сутфенсі — гном-інженер на спочинку, що живе в Танарісі на північ від Порту Стімвідла. Він рекламує себе як майстра-віщуна, хоча його пророцтва славляться своєю неточністю.",al={"лор нарейна сутфенсі","хто такий нарейн","ясновидець гном танаріс"}},{q="Чи справді Нарейн ясновидець?",a="Ні. Могутні знайомі, як-от дракон Азурегос, відкрито називають його жахливим ясновидцем. Справжній його хист — майстерна інженерія й механіка, хоч би як театрально він удавав, що читає думки.",al={"чи бачить нарейн майбутнє","чи нарейн ясновидець","ворожка сутфенсі"}},{q="Що за книга «Віщування для чайників» лежить біля нього?",a="It is a handbook kept in Narain's hut, associated with specialized trades. Narain points travelers seeking such knowledge toward the book.",al={"віщування для чайників","книга нарейна"}},{q="Звідки Нарейн знає Азурегоса?",a="Нарейн — давній знайомий синього дракона Азурегоса, що мандрує Азшарою. Попри дивні претензії Нарейна, дракон поважає його неперевершений хист до інженерії й ремесла.",al={"нарейн і азурегос","синій дракон нарейн"}}},fp="17,315,37.654.0,17.384.0,25.187.0,29.209.0,54.138.0,30.187.0"}
P.entries["npc:naralex"] = {n="Наралекс",s="Наралекс — друїд із нічних ельфів, який прагнув силами Смарагдового Сну перетворити спраглі Пустки на пишний ліс. Натомість його сон поглинуло темне жахіття, що спотворило Печери Стогонів під землею й обернуло його послідовників на отруйних потвор.",h="Наралекс — друїд із нічних ельфів, який прагнув силами Смарагдового Сну перетворити спраглі Пустки на пишний...",kw={"наралекс","печери стогонів","смарагдовий сон","смарагдове жахіття","друїди ікла","пустки"},ang={["class:Druid"]="Наралекс — похмура пересторога для друїдів: якщо наосліп утручатися в первісні стани природи чи необачно занурюватися надто глибоко в Сон, можна вивільнити катастрофічні збочення дикої природи.",["faction:Horde"]="Невдалий містичний дослід нічного ельфа отруїв серце Пусток, і тепер силам Орди з Перехрестя доводиться давати раду звірам, що шаленіють і лізуть із печер.",["race:NightElf"]="Наралекс хотів зцілити Калімдор, але його неприборкані амбіції глибоко на землях Орди принесли ганьбу Колу Кенарія й породили віроломних Друїдів Ікла.",["race:Tauren"]="Спотворені води під Пустками — пряма загроза оазам і звірині, які годують племена Малгору й савани."},sec={{t="Видіння зелені",b="Задовго до Великого Розколу випалені сонцем рівнини Пусток були буйним лісом. Вважаючи цю втрату трагедією, Наралекс вирушив із Дарнасуса на південь разом із гуртом відданих учнів, щоб здолати посуху. Глибоко під саваною він відкрив хитромудру мережу підземних джерел і бурхливих гейзерів і назвав її Печерами Стогонів — через виття вітру й пари, що стогнали в скелі. Він вірив, що коли зануриться в глибокий транс і спрямує чисту енергію Смарагдового Сну в ці підземні води, життєдайна течія дійде до поверхні, і вся пустка розквітне."},{t="Жахіття наяву",b="Наралекс поринув у глибоку медитацію в надрах підземних печер, але його шляхетний задум завалився тієї ж миті, коли його свідомість торкнулася царини Сну. Замість мирних джерел дикої природи його розум обплела зловісна, всепроникна порча — Смарагдове Жахіття. Гнилісна порча захопила тіло сплячого друїда й зробила його відчиненою брамою, крізь яку темні сили просочувалися в живий світ. Чисті джерела зіпсувалися, на них проросли мутовані грибні нарости, а тутешні печерні звірі перетворилися на ненажерливих девіантних страховиськ."},{t="Занепалі учні",b="Жахіття не обмежилося звірами. Власні учні Наралекса, цілком збожеволівши від психічної віддачі, що сочилася з трансу їхнього наставника, відкинули традиції Кола Кенарія. Зрікшись шанування рівноваги, вони прибрали зміїної подоби й назвалися Друїдами Ікла. Вірячи, що їхнє спотворене буяння має поширитися всім Калімдором, вони тепер стережуть сплячого Наралекса, щоб той ніколи не прокинувся. Лише кілька вірних учнів, як-от Муйо, шукають союзників, досить сміливих, щоб перервати транс."}},faq={{q="Хто такий Наралекс?",a="Наралекс — нічний ельф, друїд Кола Кенарія. Він повів експедицію до Печер Стогонів, щоб черпнути сили Смарагдового Сну й знову перетворити посушливі Пустки на буйний ліс, яким вони були до Розколу.",al={"лор наралекса","хто сплячий ельф","сплячий у печерах стогонів"}},{q="Чому Наралекс спить у Печерах Стогонів?",a="Він увійшов у медитативний транс, щоб спрямувати енергію Смарагдового Сну просто в підземні водоносні шари під Пустками. Але його розум поглинув нездоланний кошмар, і тепер він ув'язнений у гарячковому сні, з якого сам не може прокинутися.",al={"чому наралекс спить","що робить наралекс","транс наралекса"}},{q="Звідки взялися Друїди Ікла?",a="Спершу це були вірні учні Наралекса. Коли Смарагдове Жахіття зіпсувало зв'язок Наралекса зі Сном, злоба, що просочувалася назовні, звела його послідовників з розуму. Вони покинули Коло Кенарія, прийняли зміїні тотеми й тепер стережуть його сон, щоб скверна й далі ширилася.",al={"походження друїдів ікла","хто такі друїди ікла","учні наралекса"}},{q="Що спричинило мутації в Печерах Стогонів?",a="Спляче тіло Наралекса стало відкритим проходом для Смарагдового Жахіття. Мерзенна енергія сну просочилася просто в підземні річки й перетворила рослини, крокодилів, ящерів і змій печер на агресивних мутантів-девіантів.",al={"чому печери стогонів зіпсовані","походження девіантів","гриб печер стогонів"}},{q="Чи можна пробудити Наралекса?",a="Так, але лише з допомогою ззовні. Його вірний учень, що лишився, Муйо, працює з шукачами пригод, готовими спуститися в глибини, знищити спотворених Друїдів Ікла й провести ритуал, щоб зламати владу кошмару над розумом Наралекса.",al={"як врятувати наралекса","пробудження наралекса","завдання наралекса"}},{q="Чому Наралекс хотів змінити Пустки?",a="Наралекс дізнався, що колись Пустки були квітучим лісом, доки Великий Розкол не розтрощив Калімдор. Він бачив у їхній нинішній посушливості рану природи й прагнув відродити давній зелений покрив.",al={"навіщо відновлювати пустки","мета наралекса в пустках","чому пустки"}}},fp="7,277,17.662.0,20.602.0,16.560.1,15.231.0,49.256.0,36.285.0,42.245.0,24.224.1,43.216.0"}
P.entries["npc:nat-pagle"] = {n="Нат Паґл",s="Ната Паґла повсюдно вважають найславетнішим рибалкою всього Азероту, хоч сам він стверджує, що рибалить лише як привід добряче випити. Він живе на відлюдній затоці в Багні Пилоброду й навчає найкращих рибалок і з Альянсу, і з Орди — тих, кому вдається довести своє терпіння.",h="Ната Паґла повсюдно вважають найславетнішим рибалкою всього Азероту, хоч сам він стверджує, що рибалить лише...",kw={"нат паґл","рибальство","рибалка","багно пилоброду","ґаз'ранка","зул'ґуруб"},ang={["faction:Alliance"]="Дворфійські майстри-рибалки, як-от Ґрімнур Стоунбренд в Айронфорджі, дуже шанують Ната й посилають досвідчених рибалок Альянсу до Багна Пилоброду, щоб ті вивідали останні таємниці ремесла.",["faction:Horde"]="Лумак, наставник рибалок у Долині Честі в Оргріммарі, вважає Ната Паґла вірним другом і посилає до нього на південь обдарованих рибалок Орди."},sec={{t="Майстер-рибалка",b="Хоч його ім'я по всьому відомому світу стало синонімом рибальської майстерності, Нат Паґл напрочуд невимушено ставиться до свого ремесла. Закидаючи вудку вже кілька десятиліть, він часто зізнається, що не має особливого пієтету до самого рибальства, і славетно називає його просто зручним приводом сидіти собі й добряче пити. Попри цю грубувату безтурботність, Нат розуміє водне життя й мистецтво рибальства краще за будь-кого з живих: він навіть написав власний посібник і дав своє ім'я рибальському спорядженню, на яке полюють професіонали."},{t="Болотяний відлюдник",b="Паґл отаборився на невеликій косі на східному узбережжі Багна Пилоброду, далеко від гамірних таверн Східних Королівств. Він палко незалежний і байдужий до політики фракцій: радо приймає і мандрівників Альянсу, яких посилають наставники на кшталт Ґрімнура Стоунбренда, і прибічників Орди, яких спрямовує до нього Лумак з Оргріммара. Для Ната кожен, хто готовий обнишпорити закутки світу заради рідкісних уловів, заслуговує на урок справжнього рибальства."},{t="Давні байки й морські чудовиська",b="Паґл бував і в небезпечних водах — зокрема ходив у руїни Зул'Ґуруба, де загубив свою улюблену мірну стрічку й скриньку зі снастями біля вод, якими нишпорить жахлива гідра Ґаз'ранка."}},faq={{q="Хто такий Нат Паґл?",a="Нат Паґл — найвідоміший рибалка Азероту. Десятиліттями закидаючи вудку, він тепер тихо живе на узбережжі Багна Пилоброду й навчає досвідчених рибалок, яким уже замало звичайних наставників.",al={"хто такий нат","лор ната паґла","хто рибалка"}},{q="Де знайти Ната Паґла?",a="Він живе на невеликій косі на східному узбережжі Багна Пилоброду в Калімдорі, на південний захід від Острова Терамор.",al={"де нат паґл","місце ната паґла","знайти ната паґла"}},{q="Навіщо Нат Паґл рибалить, якщо каже, що цього не любить?",a="Паґл відверто зізнався, що рибальство для нього — насамперед поважна відмовка, щоб годинами спокійно сидіти біля води й добряче випивати.",al={"чи нат любить рибалити","навіщо нат рибалить","нат паґл п'є"}},{q="Чи навчає Нат Паґл членів Орди?",a="Так. Нат цілком байдужий до ворожнечі фракцій. Рибалок Орди, які досягли межі звичайної майстерності, просто до нього посилає його друг Лумак з Оргріммара.",al={"чи нат лише для альянсу","нат паґл орда","чи орда може говорити з натом"}},{q="Що пов'язує Ната Паґла із Зул'Ґурубом?",a="Колись Нат рибалив у стародавньому тролячому місті Зул'Ґуруб і залишив там свою скриньку зі снастями й цінну рулетку біля вод, де живе велика гідра Ґаз'ранка.",al={"нат у зг","скринька снастей ната паґла","нат паґл зул'ґуруб"}}},fp="9,298,17.508.0,18.473.0,26.212.0,17.202.0,29.115.0,50.156.0,42.172.0,49.169.0"}
P.entries["npc:natalia-mar-alith"] = {n="Наталія Мар'аліт",s="Господиня Наталія Мар'аліт — жриця з нічних ельфів і дослідниця Кола Кенарія, що зникла глибоко в гніздах силітидів у Вулик'Реґалі. Вона прибула в пустелі Силітусу разом зі своїм чоловіком, Командиром Мар'алітом, а згодом вирушила з експедицією у вулики.",h="Господиня Наталія Мар'аліт — жриця з нічних ельфів і дослідниця Кола Кенарія, що зникла глибоко в гніздах...",kw={"наталія мар'аліт","жриця","вулик'реґал","к'тун","силітус","нічні ельфи"},ang={["faction:Alliance"]="Рутґар Ґліфшейпер і Франкал Стоунбридж у Таборі Бронзоборода розповідають похмурі подробиці її падіння дослідникам Альянсу, які йдуть слідами експедиції Бранна.",["race:NightElf"]="Трагічне падіння Наталії — сумне нагадування калдореям, що навіть найвідданіші їхні жриці беззахисні перед прадавніми жахіттями, похованими під пісками Силітусу."},sec={{t="Трагічне падіння",b="Коли Коло Кенарія заснувало Цитадель Кенаріуса, щоб стежити за пробудженням пісків, Наталія вирушила в пустелю разом із чоловіком, Командиром Мар'алітом. Прагнучи розгадати, чому знову ожили силітиди й що криють прадавні руїни кіражів, вона приєдналася до розвідувального загону славетного дослідника Бранна Бронзбірда, у якому були також дворфи-дослідники Рутґар Ґліфшейпер і Франкал Стоунбридж."},{t="Кристал Вулик'Реґала",b="Експедиція пішла слідом за дивними випромінюваннями в південні глибини Вулик'Реґала. У самому серці вулика дослідники натрапили на величезний кристал, укритий прадавніми гліфами кіражів. Приваблена його шепітливим відлунням, Наталія схилилася, щоб роздивитися письмена ближче. Темна магія всередині за мить здолала її розум, розколола свідомість і прикувала її волю до К'Туна. Супутники-дворфи винесли її до Цитаделі Кенаріуса, де друїди привели її до тями, та за кілька тижнів вона, одержима, увірвалася до їхнього табору з вимогою повернути її у вулик — і від неї довелося відбиватися. Нині вона — затята охоронниця жахливого володаря вулика."},{t="Розпач командира",b="У Цитаделі Кенаріуса Командир Мар'аліт відчайдушно тримається надії, що дружину ще можна врятувати, і не хоче визнати, що її розум зламано безповоротно. Та кожен, хто наважиться піти у Вулик'Реґал, знайде не бранку, яка чекає порятунку, а безжальну служницю божевілля, що володіє священною магією жриці, спотвореною злобою Древнього Бога."}},faq={{q="Хто така Наталія Мар'аліт?",a="Наталія Мар'аліт — нічна ельфійка, жриця Кола Кенарія й дружина Командира Мар'аліта. Вона приєдналася до розвідувальної експедиції Бранна Бронзбірда до Вулик'Реґалу, щоб вивчити відродження силітидів, і там стала жертвою темної стародавньої магії.",al={"хто така наталія","наталія мар'аліт","дружина командира мар'аліта"}},{q="Де знайти Наталію Мар'аліт?",a="Вона глибоко в тунелях комах Вулик'Реґалу на півдні Силітусу, стоїть на варті перед сяйливим кристалом, вкритим гліфами.",al={"місце наталії","де наталія","жриця вулика регал"}},{q="Чому Наталія ворожа до шукачів пригод?",a="Досліджуючи кристал кіраджі, Наталія була цілковито зіпсована й зламана шепотом Древнього Бога К'Туна. Тепер вона фанатично боронить кристал від кожного, хто входить до вулика.",al={"чому наталія напала на мене","чому наталія божевільна","наталію зомбовано"}},{q="Хто був із Наталією, коли вона зникла?",a="Вона вирушила до Вулик'Реґалу із Бранном Бронзбірдом, Рутґаром Ґліфшейпером і Франкалом Стоунбриджем. Рутґар і Франкал пережили це випробування й відступили до Табору Бронзоборода на півдні Силітусу, щоб розповісти про те, що сталося.",al={"експедиція наталії","хто був із наталією","бранн і наталія"}},{q="Чому вона така небезпечна в бою?",a="Наталія зберегла свою грізну жрецьку силу: вона раз у раз розганяє нападників Психічним Криком і відновлює сили майже дармовим Великим Зціленням, тож здолати її без постійного переривання заклинань дуже важко.",al={"бій з наталією","як перемогти наталію","лікування наталії"}}},fp="17,280,16.427.0,25.634.1,23.333.1,25.255.1,35.139.0,38.198.1,43.219.0,34.232.0"}
P.entries["npc:nathanos-blightcaller"] = {n="Натанос Блайткаллер",s="Натанос Блайткаллер, колись Натанос Марріс, стоїть на своєму зруйнованому обійсті у Східних Чумних землях як смертоносний чемпіон королеви Сильвани Віндраннер. За життя він був першим і єдиним серед людей Лордом-рейнджером Кель'Таласу, а в нежитті навчає мисливців-Відступників і стереже східне порубіжжя, зустрічаючи кожного, хто наблизиться, їдкою зневагою.",h="Натанос Блайткаллер, колись Натанос Марріс, стоїть на своєму зруйнованому обійсті у Східних Чумних землях як...",kw={"натанос блайткаллер","натанос марріс","сильвана","відступники","далекоходи","садиба марріса","мисливці"},ang={["class:Hunter"]="Натанос — найвищий за рангом наставник мисливців у Відступників: він приносить нежиті Лордерону суворе, легендарне стрілецьке мистецтво далекоходів Кель'Таласу.",["faction:Alliance"]="Бачити, як прославлений герой Лордерону й шанований далекохід б'ється під прапором Відступників, — болюча образа і смертельно небезпечна тактична проблема для Стормвінда.",["faction:Horde"]="Натанос дає Орді в Чумних Землях важливі тактичні поради й навчає мисливців, хоча до відвідувачів ставиться з уїдливою зневагою.",["race:Undead"]="Як чемпіон Темної Леді, Натанос втілює гірку стійкість Відступників, хоча до некомпетентності серед своїх у нього терпіння мало."},sec={{t="Єдиний далекохід серед людей",b="До Третьої війни Натанос Марріс був надзвичайним стрільцем і тактичним генієм із сільських околиць Лордерону. Його навчали високі ельфи Кель'Таласу, він був близький до Сильвани Віндраннер і став єдиною людиною, що будь-коли здобула престижне звання Лорда-рейнджера. Його домом лишався родинний маєток у Лордероні — Садиба Марріса."},{t="Загибель і відродження",b="Коли принц Артас і Погибель пронеслися Лордероном після очищення Стратгольма, чума поглинула королівство. Натанос відчайдушно оборонявся у своєму маєтку, але загинув від потворної гидоти Рамштайна Жеруна. Піднятий як бездумний раб-нежить, він блукав сплюндрованими полями, вбиваючи в ім'я Короля-Ліча. Коли Сильвана зламала владу Погибелі над розумом і заснувала Відступників в Андерсіті, вона прийшла по нього — як він якимось чином і знав — і вирвала його свідомість з-під волі Короля-Ліча, повернувши собі його тактичний хист і палку відданість."},{t="Чемпіон Королеви Баньші",b="Узявши прізвисько Блайткаллер, Натанос назавжди оселився в занедбаній Садибі Марріса. Він — чемпіон Сильвани, наставник мисливців і головний шпигун у спірних Східних Чумних землях, а охороняють його мерзенні чумні пси. Розвідка Альянсу з глибокою тривогою встановила, що він уцілів: Верховний Лорд Болвар Фордрагон вважає, що майстер тактики такого рівня на чолі сил нежиті — нестерпна загроза виживанню людства, і посилає ударні загони, щоб убити полеглого Лорда-рейнджера."}},faq={{q="Хто такий Натанос Блайткаллер?",a="Натанос Блайткаллер — колишній Натанос Марріс, знаменитий стрілець-людина й єдиний не ельф, якого будь-коли робили Лордом-Рейнджером Кель'Таласу. Після смерті й воскресіння під час Третьої війни Сильвана звільнила його розум від Погибелі. Тепер він її поборник і наставник мисливців у своєму родовому гнізді в Східних Чумних Землях.",al={"хто такий натанос","лор натаноса","хто біля хутора маррісів"}},{q="Чому Натанос на Хуторі Маррісів?",a="Хутір Маррісів був домом Натаноса за життя, і саме там він загинув, захищаючи Лордерон. Ставши нежиттю, він вирішив повернутися до свого зруйнованого маєтку й перетворив його на заставу, де навчає мисливців-Відступників і стежить за пересуваннями Альянсу й Погибелі.",al={"де натанос","чому натанос у чумних землях","хутір маррісів натанос"}},{q="Як Натанос став нежиттю?",a="Натаноса вбила на його хуторі під час Третьої війни гидота Погибелі Рамштайн Жерун. Він повстав як слухняний безвольний раб Короля-Ліча, аж поки по нього не прийшла Сильвана й не звільнила його розум, щоб він приєднався до Відступників.",al={"як натанос помер","хто вбив натаноса","смерть натаноса"}},{q="Чому Альянс хоче його вбити?",a="Очільники Альянсу в Стормвінді дізналися, що Натанос Марріс — один із найкращих воєнних умів і тактичних геніїв Альянсу — не загинув назавжди, а приєднався до Відступників. Вважаючи його тактичний хист величезною небезпекою, Верховний Лорд Болвар Фордрагон наказує його знищити.",al={"чому вбивати натаноса","завдання альянсу натанос","порядок має бути відновлений"}},{q="Які в нього стосунки із Сильваною?",a="Натанос був близький до Сильвани ще за життя, коли ельфи Кель'Таласу зробили його своїм єдиним Лордом-Рейнджером із людей, а тепер він її поборник. У нежитті його вірність Королеві Баньші лишається абсолютною й непохитною.",al={"сильвана й натанос","чи сильвана кохала натаноса","роман сильвани й натаноса"}},{q="Що за пси стоять біля нього?",a="Це люті чумні гончаки, яких Натанос вишколив сам. Він тримає їх поруч, щоб стерегли руїни Хутора Маррісів, і вони нападають на кожного, хто необачно вдереться на його землі.",al={"пси натаноса","хорти хутора маррісів","улюбленці блайткаллера"}}},fp="21,344,25.354.0,20.606.0,29.515.1,29.329.0,36.251.0,34.244.0,39.301.0,39.214.0,37.188.0"}
P.entries["npc:nida"] = {n="Гілері",s="Гілері — маленька дівчинка, що живе в прибережному містечку Лейкшир у Горах Редріджу. Упустивши в озеро дорогий подарунок від батька, вона з розпачу плаче на міській пристані.",h="Гілері — маленька дівчинка, що живе в прибережному містечку Лейкшир у Горах Редріджу.",kw={"гілері","намисто гілері","озеро незрушне","пристань","лейкшир","редрідж"},ang={["faction:Alliance"]="Хоч Гори Редріджу потерпають від куди більших бід, допомога Гілері повертає стривоженим мешканцям Лейкширу трішки тепла й безтурботності."},sec={{t="Загублена дитяча пам'ятка",b="Попри дедалі більшу загрозу навали гнолів і загонів орків Блекрок, що насідають на Лейкшир, діти містечка й досі мають свої дитячі клопоти. Гілері ненароком упустила в каламутні води Озера Незрушного намисто, яке подарував їй батько. Боячись, що тато на неї гніватиметься, засмучена дівчинка в сльозах чекає на міській пристані й сподівається, що знайдеться хтось досить сміливий, щоб пірнути в озеро й дістати його."}},faq={{q="Хто така Гілері?",a="Гілері — маленька дівчинка, що живе в Лейкширі в Горах Редріджу; її часто можна побачити заплаканою біля пристані.",al={"хто така гілері","гілері лейкшир","дівчинка що плаче лейкшир"}},{q="Чому Гілері плаче?",a="Гілері загубила дорогоцінне намисто, яке купив їй батько. Воно впало у води Озера Незрушне, і вона страшенно боїться батькового гніву, коли той помітить, що намиста немає.",al={"чому гілері плаче","чому вона сумна","плач гілері"}},{q="Хто намагається допомогти їй знайти намисто?",a="Її товариш з ігор Шон помічає, як вона засмучена, і просить перехожих шукачів пригод пірнути в Озеро Незрушне й дістати для неї затонуле намисто.",al={"хто допомагає гілері","друг гілері","хто дає завдання гілері"}},{q="Де лежить загублене намисто?",a="Намисто лежить під водою Озера Незрушне, біля міської пристані, де його впустила Гілері.",al={"місце намиста","намисто озеро незрушне"}}},fp="6,221,23.444.0,14.126.0,21.185.0,44.137.0,35.114.0"}
P.entries["npc:nikova-raskol"] = {n="Нікова Раскол",s="Нікова Раскол — літня містянка, людина, що блукає бруківкою Старого Міста в Стормвінді. Оплакуючи онука, якого вбило Братство Дефіас, вона прагне справедливої відплати злочинцям, які збунтувалися за ґратами В'язниці.",h="Нікова Раскол — літня містянка, людина, що блукає бруківкою Старого Міста в Стормвінді.",kw={"нікова раскол","старе місто","братство дефіас","в'язниця","помста","стормвінд"},ang={["faction:Alliance"]="Для героїв Альянсу, що навідуються до Стормвінда, допомога Нікові нагадує: захищати королівство — означає берегти й простих містян, чиї родини розірвали внутрішні негаразди."},sec={{t="Бабусине горе",b="Нікова блукає Старим Містом, несучи тягар недавньої страшної трагедії. Її улюбленого онука Мака вбили розбійники з Братства Дефіас. Поки королівство бореться зі зрадою на рівні високої політики, Нікова уособлює ту людську ціну, яку беззаконна навала Братства стягує зі звичайних містян."},{t="Помста у В'язниці",b="Хоча чимало злочинців, що сіяли хаос, спіймали й кинули до В'язниці, тепер ґрати мало тішать: жорстокий бунт в'язнів захопив тюрму. Розчарована тим, що вартові не можуть навести лад, Нікова звертається просто до відважних шукачів пригод, які прямують до в'язниці, й просить принести червоні пов'язки Дефіас — доказ, що вбивці її онука нарешті поплатилися."}},faq={{q="Хто така Нікова Раскол?",a="Нікова Раскол — літня мешканка Стормвінда, що ходить овальною вулицею Старого Міста. Вона оплакує онука Мака, якого вбили головорізи Дефіас.",al={"хто така нікова","роль нікови раскол","лор нікови раскол"}},{q="Що сталося з її онуком Маком?",a="Мака холоднокровно вбили члени Братства Дефіас. Чимало винних опинилися у В'язниці Стормвінда, де згодом підняли бунт.",al={"що сталося з маком","хто такий мак","як помер мак"}},{q="Навіщо їй червоні пов'язки з В'язниці?",a="Червона пов'язка — розпізнавальний знак Братства Дефіас. Нікова просить бійців, що йдуть до охопленої бунтом В'язниці, принести ці хустки як доказ, що злочинців, які забирали невинні життя, покарано.",al={"колір крові","навіщо червоні пов'язки","пов'язки дефіас"}},{q="Де знайти Нікову Раскол?",a="Нікова без упину ходить по колу головною вулицею Старого Міста, неподалік від таверни «Свиня і Свисток» і тренувального майданчика в Стормвінді.",al={"де нікова","місце нікови","шлях нікови раскол"}}},fp="13,262,21.350.0,25.419.0,21.155.0,34.166.0,49.246.0,33.154.0"}
P.entries["npc:nissa-firestone"] = {n="Нісса Файрстоун",s="Нісса Файрстоун — дворфійська лікарка, що працює над гамором Великої Кузні в Айронфорджі. Вона навчає польової медицини, показуючи мандрівникам і солдатам, як перев'язувати рани й допомагати при травмах.",h="Нісса Файрстоун — дворфійська лікарка, що працює над гамором Великої Кузні в Айронфорджі.",kw={"нісса файрстоун","перша допомога","лікарка","бинти","велике горно","айронфордж"},ang={["faction:Alliance"]="Кожен шукач пригод Альянсу, що проходить через Каз Модан, покладається на наставників на кшталт Нісси, щоб опанувати важливі навички виживання без божественної чи арканної магії.",["race:Dwarf"]="Для дворфів, що повертаються із сутичок із трогами чи морозними тролями, Нісса уособлює практичний, тверезий підхід медичної традиції Айронфорджа."},sec={{t="Цілителька над ковадлами",b="Серед брязкоту металу й пекучого жару Великої Кузні Нісса Файрстоун лікує на верхньому поверсі крамниці «Лікар Айронфорджа». Дворфійські воїни славляться витривалістю, але навіть тверда, мов камінь, шкіра розходиться під клинком і пазуром. Нісса дбає, щоб ті, хто вирушає в сніги Дун Мороґа чи далі, вміли зберегти життя собі й союзникам простими перев'язками й польовими пов'язками."},{t="Сортування поранених і складні травми",b="Нісса бачить, коли польовий медик, що опанував основи роботи з тканиною й корпією, переростає її лікарню. Коли учні доходять межі того, чого вона може навчити, вона скеровує їх до фахівців із сортування поранених на далеких заставах — туди, де Альянс зазнає найбільших утрат."}},faq={{q="Хто така Нісса Файрстоун?",a="Нісса Файрстоун — дворфійка, наставниця першої допомоги, що працює в крамниці «Лікар Айронфорджа» на південному краю Великої Кузні.",al={"хто така нісса файрстоун","роль нісси файрстоун","тренер першої допомоги айронфорджа"}},{q="Де знайти Ніссу Файрстоун?",a="Вона на верхньому поверсі крамниці «Лікар Айронфорджа», що стоїть на південному краю кільця Великої Кузні в Айронфорджі.",al={"місце нісси файрстоун","де нісса","лікарка айронфорджа"}},{q="Чого навчає Нісса Файрстоун?",a="Вона навчає шукачів пригод Альянсу ремесла першої допомоги — як готувати бинти й протиотрути, щоб лікувати рани, отримані в польових умовах.",al={"чого навчає нісса","перша допомога айронфордж","вивчити бинти айронфордж"}},{q="Чи може Нісса навчити майстерного сортування поранених?",a="Ні. Коли лікар досягає високої майстерності, Нісса посилає його далі із завданням «Травми Альянсу» — до досвідчених польових хірургів, що працюють біля гарячих точок війни.",al={"завдання травми альянсу","майстерна перша допомога айронфордж","перша допомога понад 225"}}},fp="15,214,25.427.0,26.329.0,23.148.0,33.138.0,32.156.0,36.184.0"}
P.entries["npc:nogg"] = {n="Ноґґ",s="Ноґґ — гоблін-інженер, що має майстерню в Долині Честі в Оргріммарі. Він пропонує Орді свої знання й особливу майстерність, зокрема розбирається з дивними механічними знахідками, винесеними з глибин Гномреґана.",h="Ноґґ — гоблін-інженер, що має майстерню в Долині Честі в Оргріммарі.",kw={"ноґґ","гоблін","інженер","долина честі","оргріммар","гномреґан"},ang={["faction:Horde"]="Для воїнів Орди, що повертаються з небезпечних походів до Східних Королівств, Ноґґ перетворює грубі знахідки на точно налаштоване бойове спорядження.",["profession:Engineering"]="Колеги-інженери часто заходять до майстерні Ноґґа в Долині Честі по деталі, поговорити про ремесло й подивуватися, як легко гоблінські руки переробляють хитромудру гномську техніку."},sec={{t="Майстерня Ноґґа",b="У затишному куточку Долини Честі в Оргріммарі Ноґґ тримає незалежну інженерну майстерню, де раді і шукачам пригод, і ремісникам. Хоча місто довкола покладається переважно на традиційну орочу сталь і грубу силу, Ноґґ пропонує ту особливу механічну тонкість, на яку здатен лише гоблін. Він жваво цікавиться чужоземними пристроями й технікою та охоче оглядає дивні дрібнички й механічні дивовижі, принесені з земель Альянсу чи з підземних руїн."},{t="Гномські пристрої й знахідки",b="Особливо Ноґґа цікавлять речі з полеглої гномської столиці Гномреґана. Коли агенти Орди приносять хитромудрі персні чи рештки техніки з опромінених сховищ за морем, Ноґґ — один із небагатьох у Дуротарі, хто здатен розібрати, розгадати й переробити такі химерні годинникові механізми для потреб Орди."}},faq={{q="Де знайти Ноґґа?",a="Ноґґ — у Долині Честі в Оргріммарі, де він тримає власну інженерну майстерню.",al={"місце ноґґа","де ноґґ","майстерня ноґґа"}},{q="Що пов'язує Ноґґа з Гномреґаном?",a="Коли шукачі пригод Орди спускаються в заражені тунелі Гномреґана в Каз Модані, вони можуть добути там хитромудрі технологічні дрібнички. Ноґґ — місцевий знавець в Оргріммарі, який оглядає й переналаштовує ці чужі гномські персні.",al={"чому ноґґ гномреґан","перстень ноґґа","повернення персня"}},{q="Чи належить Ноґґ до Орди?",a="Ноґґ — незалежний гоблін-майстер, що працює просто в Оргріммарі, охоче служить шукачам пригод Орди й віддає свій технічний хист їхній воєнній справі.",al={"чи ноґґ з орди","фракція ноґґа"}},{q="Чи може Ноґґ змінити чи перекувати персні?",a="Так. Якщо шукач пригод принесе йому перстень, здобутий зі Спарклматика в Гномреґані, і захоче інших чар чи механічних властивостей, Ноґґ знає, як розібрати й перезібрати виріб, щоб той краще пасував власникові.",al={"перекувати перстень","змінити перстень гномреґана"}}},fp="4,248,15.481.0,27.354.0,22.100.0,40.235.0,26.163.0,32.217.0"}
P.entries["npc:nori-pridedrift"] = {n="Норі Прайддріфт",s="Норі Прайддріфт — заповзятливий дворф, що розносить свій обпікаюче гарячий Ранковий Узвар засніженою Долиною Холодного Хребта. Він заробляє на життя, кидаючи виклик холоду, щоб постачати змерзлим горянам їхню ранкову підбадьорливу порцію, і часто наймає прудких новобранців розносити напій, поки той ще парує.",h="Норі Прайддріфт — заповзятливий дворф, що розносить свій обпікаюче гарячий Ранковий Узвар засніженою Долиною...",kw={"норі прайддріфт","ранковий узвар","дворф","кухоль","доставка","долина холодного хребта","гарячий напій"},ang={["profession:Cooking"]="Кулінари-мандрівники в Дун Мороґу цінують відданість Норі, який подає свій фірмовий напій обпікаюче гарячим попри крижане повітря довкола.",["race:Dwarf"]="Кожен дворф розуміє життєво важливу втіху від міцного напою на морозі, тож гарячий Ранковий Узвар Норі — жаданий гість на гірських постах варти."},sec={{t="Паруючий кухоль у снігу",b="Життя в Долині Холодного Хребта суворе й люто холодне, і ніщо не пробиває мороз так, як ковток Гарячого Ранкового Узвару. Норі Прайддріфт заробляє на життя тим, що варить і розносить цей гарячий, схожий на каву ранковий напій замерзлими заметами. Оскільки узвар треба пити ще обпікаючим, щоб повністю його оцінити, доставка — це перегони зі стихією. Норі часто наймає прудких кур'єрів бігти зі свіжими порціями до змерзлих вартових, перш ніж гірське повітря забере в напою тепло. Не менш важливий за сам узвар і його обмежений запас міцних кухлів, які він вимагає від своїх гінців повертати негайно."}},faq={{q="Хто такий Норі Прайддріфт?",a="Норі Прайддріфт — заповзятливий дворф-рознощик із Долини Холодного Хребта. Він варить і продає Пекучий Ранковий Відвар — гарячий напій на кшталт кави, що зігріває місцевих вартових і гірників.",al={"хто такий норі","лор норі прайддріфта","торговець пекучим ранковим відваром"}},{q="Що таке Пекучий Ранковий Відвар?",a="Пекучий Ранковий Відвар — особливий гарячий напій, який варить Норі Прайддріфт. Схожий на окріп-каву чи пряний ранковий ель, він дуже до вподоби мешканцям долини, бо проганяє лютий холод Дун Мороґу.",al={"пекучий ранковий відвар","який напій продає норі","ранковий відвар"}},{q="Чому доставки такі термінові?",a="Уся принадність напою в тому, що він гарячий. На морозних гірських вітрах Долини Холодного Хребта кухоль швидко холоне, тож гінці Норі мусять щодуху бігти до спраглих покупців.",al={"чому доставки термінові","поспіх доставки відвару","чому напій холоне"}},{q="Чому Норі так переймається поверненням кухлів?",a="У Норі в долині обмежений запас кухлів. Якщо покупці розходяться з ними чи розбивають їх у заметах, його ранкова торгівля швидко зупиняється.",al={"чому повертати кухлі","кухлі норі","повернення кухлів"}}},fp="15,301,26.649.0,23.186.0,26.211.0,29.207.0,48.181.0"}
P.entries["npc:novice-elreth"] = {n="Послушниця Елрет",s="Послушниця Елрет — нежить із Відступників, що перебуває в каплиці Похоронного Подзвону. Коли щойно підняті мерці прокидаються до другого життя, вона скеровує їх стати проти безтямної Погибелі, що никає сусідніми могилами, і подбати про трагічні наслідки чуми.",h="Послушниця Елрет — нежить із Відступників, що перебуває в каплиці Похоронного Подзвону.",kw={"послушниця елрет","каплиця","похоронний подзвін","погибель","семюел фіппс","відступники"},ang={["class:Priest"]="Стоячи на колишній святій землі Лордерону, Елрет утілює різкий, прагматичний перехід від святого поклоніння до похмурої потреби нежиті.",["race:Undead"]="Для свіжих Відступників, що видряпуються з могили, Послушниця Елрет пропонує перші практичні кроки до виживання, спрямовуючи холодну ненависть на безтямну Погибель."},sec={{t="Провідниця в церкві проклятих",b="У оскверненій каплиці Похоронного Подзвону Послушниця Елрет допомагає новопосталим мерцям, що силкуються осягнути своє жахливе пробудження. Замість піддаватися розпачу чи безтямному голоду Погибелі, Відступники мусять швидко згуртуватися, щоб убезпечити свою землю. Елрет дає щойно звільненим душам перші завдання: збирати могильний прах із безтямних трупів і давати раду недобиткам трагічного падіння Лордерону, зокрема й невідступній скорботі Семюела Фіппса та його покійної дружини Марли."}},faq={{q="Де перебуває Послушниця Елрет?",a="Послушниця Елрет стоїть у каплиці в Похоронному Подзвоні — зруйнованому селищі в Галявинах Тірісфалю, де прокидаються щойно створені Відступники.",al={"місце елрет","де послушниця елрет","послушниця елрет церква"}},{q="Яка роль Послушниці Елрет у Похоронному Подзвоні?",a="Вона місцева провідниця, що дає доручення щойно повсталим Відступникам. Вона дає важливі перші настанови й навчає свіжу нежить битися з безмозкою Погибеллю, що нишпорить селищним цвинтарем.",al={"роль елрет у похоронному подзвоні","що робить елрет","мета послушниці елрет"}},{q="Які завдання дає Послушниця Елрет?",a="Вона дає доручення на кшталт «Прокляті», у якому шукачі пригод збирають рештки з безмозких зомбі, і допомагає Семюелу Фіттсу з його сумним проханням про покійну дружину в завданні «Остання воля Марли».",al={"завдання елрет","завдання послушниці елрет"}},{q="Чому її титул — «Послушниця»?",a="Зважаючи на те, що вона в каплиці, і на її титул, Елрет — початківиця серед релігійних чи громадських чинів Відступників, яка опановує темні премудрощі опіки над щойно піднятою нежиттю Тірісфалю під крилом ордену Відступників.",al={"чому послушниця","значення послушниці елрет","чи елрет жриця"}}},fp="13,270,35.534.0,31.128.0,43.193.0,37.209.0,27.234.0"}
P.entries["npc:oben-rageclaw"] = {n="Обен Рейджклов",s="Обен Рейджклов — неприкаяний дух друїда, нічного ельфа, що блукає споганеними глибинами Курганного Лігва Бан'етіл у Тельдрассилі. Поки його дух тиняється в пастці курганного лігва, його сплячу тілесну оболонку підкорила огидна магія фурболгів.",h="Обен Рейджклов — неприкаяний дух друїда, нічного ельфа, що блукає споганеними глибинами Курганного Лігва...",kw={"обен рейджклов","друїд","дух","курганне лігво бан'етіл","вузлошкіри","фурболги","смарагдовий сон"},ang={["class:Druid"]="Доля Обена — болісне нагадування про вразливість друїдів під час трансу єднання зі Смарагдовим Сном, коли священні курганні лігва лишаються без захисту.",["race:NightElf"]="Споганення Обена Рейджклова фурболгами Вузлошкірів показує, як глибоко скверна вразила корінних мешканців і священні святилища Тельдрассила."},sec={{t="Споганений сон",b="Як і багато Друїдів Пазура, Обен Рейджклов усамітнився в підземному святилищі Курганного Лігва Бан'етіл, щоб єднатися з природою й блукати Смарагдовим Сном. Та коли тутешні фурболги Вузлошкірів піддалися скверні й заполонили кургани, Обен, занурений у транс, виявився цілком беззахисним. Замість просто вбити його, споганений шаман Вузлошкірів темними обрядами захопив владу над його непритомним смертним тілом, і витіснений дух лишився тинятися змученим привидом, нездатним ні відійти, ні прокинутися."},{t="Розрив із посудиною",b="Не маючи змоги відвоювати власну плоть із поневолення шамана, Обен покладається на мандрівників, що прокладають шлях небезпечними тунелями, аби ті поклали край його мукам. Лише знайшовши й знищивши його тіло-маріонетку, можна розірвати його смертні пута. Щойно викрадену посудину повалено, замучений привид Обена нарешті звільняється з підземної пітьми, щоб знайти вічний спокій у Смарагдовому Сні."}},faq={{q="Хто такий Обен Рейджклов?",a="Обен Рейджклов — нічний ельф, Друїд Пазура, чий привид блукає Курганним Лігвом Бан'етіл на Тельдрассилі, відколи зіпсовані фурболги відірвали його від тіла.",al={"хто такий обен","лор обена рейджклова","дух у барлозі"}},{q="Чому Обен Рейджклов став привидом?",a="Поки Обен спав у глибокому друїдському трансі, спілкуючись зі Смарагдовим Сном, шамани фурболгів-вузлошкірів пробралися до лігва й наклали на його тіло мерзенні чари: заволоділи ним, а його дух лишили назовні примарою.",al={"чому обен привид","чому обен мертвий","як обен помер"}},{q="Де тіло Обена?",a="Його тіло лежить глибше у звивистих коридорах Курганного Лігва Бан'етіл, під охороною й владою шаманів-вузлошкірів, що осквернили лігво.",al={"знайти тіло обена","де тіло обена","місце сплячого друїда"}},{q="Що стається, коли тіло Обена знищено?",a="Знищення тіла-маріонетки зламує темну владу шаманів-вузлошкірів над ним, і його дух може спокійно покинути Тельдрассил і навіки спочити в Смарагдовому Сні.",al={"доля обена","що буде з духом обена","порятунок обена"}}},fp="13,260,20.516.0,19.384.1,21.166.0,29.225.0,30.155.0,44.169.1"}
P.entries["npc:oggleflint"] = {n="Оґґлфлінт",s="Оґґлфлінт — ватажок племені трогів, що живе у вулканічних глибинах Провалля Лютого Вогню просто під Оргріммаром. Колись володар усієї підземної печери, він і його родичі були відтиснуті до верхніх тунелів культистами Пекучого Клинка, що прийшли сюди. Тепер він окопався біля входу, керує своєю дикою зграєю й становить безпосередню загрозу для столиці Орди нагорі.",h="Оґґлфлінт — ватажок племені трогів, що живе у вулканічних глибинах Провалля Лютого Вогню просто під...",kw={"оґґлфлінт","троги","провалля лютого вогню","оргріммар","ватажок"},ang={["class:Warrior"]="Вийти проти Оґґлфлінта — означає зійтися з важким громилом, що покладається лише на м'язи й первісну лють, а не на обладунки чи дисципліну.",["faction:Horde"]="Троги Оґґлфлінта, що живуть просто під фортецею Тралла, — дика, непередбачувана загроза безпеці в самому серці Дуротара.",["race:Orc"]="Для молодих орків, що доводять свою силу у випробуванні зброєю, вбивство ватажка, який чатує просто під Проходом, — одне з перших випробувань бойової дисципліни."},sec={{t="Ватажок глибин",b="Доки культисти тіні не проникли в провалля під Оргріммаром, Оґґлфлінт і його троги безроздільно панували у вогняних підземних тунелях. Жорстокі й ревниві до своєї території, вони вирізали собі примітивне володіння серед розпеченого каміння. Хоч троги майже не знають цивілізації, Оґґлфлінт тримав над зграєю цілковиту владу самою лише грубою силою."},{t="Витіснені культом",b="Рівновага сил під містом розбилася, коли Пекучий Клинок оселився в найглибших залах Провалля Лютого Вогню. Не в змозі протистояти темній магії й злагодженим фанатикам культу, Оґґлфлінт змушений був поступитися нижніми тунелями. Відступивши нагору, ватажок трогів тепер чатує біля входу в печеру, нападаючи на будь-яких чужинців і плекаючи образу на зайд унизу."},{t="Загроза під Оргріммаром",b="Витіснені троги просто під столицею Тралла — небезпека, якої Орда не може терпіти. Відтиснуте ближче до поверхні плем'я Оґґлфлінта надто непередбачуване, щоб лишати його без нагляду: воно загрожує вихлюпнутися в Прохід і Тіньову Розколину, якщо його не зупинити."}},faq={{q="Хто такий Оґґлфлінт?",a="Оґґлфлінт — могутній вождь трогів, що очолює зграю, яка живе в Проваллі Лютого Вогню під містом Оргріммар.",al={"оґґлфлінт","хто такий оґґлфлінт","бос трогів лютого вогню"}},{q="Де знайти Оґґлфлінта?",a="Він у верхніх печерах Провалля Лютого Вогню, неподалік від вхідного тунелю, де його вцілілий клан отаборився, коли його витіснили з глибин.",al={"де оґґлфлінт","місце оґґлфлінта","знайти оґґлфлінта"}},{q="Що троги роблять у Проваллі Лютого Вогню?",a="Троги від природи живуть глибоко під землею, у підземних вулканічних мережах. Зграя Оґґлфлінта зайняла вогняні печери під Дуротаром задовго до того, як прийшов культ Пекучого Клинка.",al={"чому троги під оргріммаром","лор трогів лютого вогню"}},{q="Чому Оґґлфлінт ворожий до Орди?",a="Троги від природи люті й ревно бережуть свої землі. Витіснені культистами ближче до поверхні, Оґґлфлінт і його поплічники становлять безпосередню загрозу для тунелів Орди й міста вгорі.",al={"чому вбивати оґґлфлінта","чому воювати з оґґлфлінтом"}},{q="Які в Оґґлфлінта стосунки з Пекучим Клинком?",a="Вони запеклі вороги. Культисти Пекучого Клинка вдерлися до Провалля Лютого Вогню й здолали трогів Оґґлфлінта, витіснивши тих, хто вцілів, у верхні печери.",al={"пекучий клинок і оґґлфлінт","чи троги з культом"}}},fp="10,398,21.372.0,21.392.0,28.262.0,18.116.0,30.168.0,37.178.0,39.194.0,57.155.0"}
P.entries["npc:ogtinc"] = {n="Оґтінк",s="Оґтінк — незалежний мисливець-фурболг, що отаборився на високому гребені над Руїнами Елдарата в Азшарі. Розійшовшись зі своїм племенем, щоб служити рівновазі природи, він став надійним союзником і наставником для Кола Кенарія. Досвідчені мисливці, які хочуть випробувати своє вміння на найлютіших звірах Калімдору, часто шукають його порад.",h="Оґтінк — незалежний мисливець-фурболг, що отаборився на високому гребені над Руїнами Елдарата в Азшарі.",kw={"оґтінк","фурболг","коло кенарія","мисливці","руїни елдарата","азшара","трофеї"},ang={["class:Druid"]="Як вірний партнер Кола Кенарія, Оґтінк — рідкісний міст між дикою мудрістю фурболгів, не зачеплених порчею, і турботою друїдів про природу.",["class:Hunter"]="Оґтінк пропонує досвідченим мисливцям глибокі духовні й практичні випробування, перевіряючи їхню влучність і вміння виживати в боротьбі з найнебезпечнішими істотами Калімдору."},sec={{t="Фурболг-одинак",b="Більшість фурболгів Калімдору й досі тісно пов'язані зі своїми племенами — або піддалися порчі після Третьої війни, — та Оґтінк обрав інший шлях. Покинувши родичів, він присвятив свій лук і знання про виживання допомозі Колу Кенарія. Його табір стоїть високо на кручі на південний схід від Твердині Деревопащих, звідки він пильно наглядає за прадавніми розтрощеними землями Азшари."},{t="Майстер полювання",b="Серед досвідчених слідопитів Оґтінк славиться глибоким знанням дикої природи Калімдору. Він випробовує мисливців, що відточили майстерність на різних континентах, посилаючи їх по рідкісні трофеї — роги прудконогих звірів, луску морських змій із бурхливих хвиль і частини тіл зелених драконів. Цими випробуваннями він учить, що справжнє полювання шанує природу й береже рівновагу, а не забирає життя бездумно."}},faq={{q="Хто такий Оґтінк?",a="Оґтінк — вправний фурболг-мисливець, що отаборився на кручах Азшари. На відміну від більшості своїх відлюдних чи зіпсованих побратимів, він покинув рідне плем'я, щоб служити своїм мисливським хистом і мудрістю друїдам Кола Кенарія.",al={"хто такий оґтінк","лор оґтінка","фурболґ в азшарі"}},{q="Де знайти Оґтінка?",a="Він в Азшарі, у таборі на кручі над стародавніми Руїнами Елдарата, трохи на південний схід від Твердині Деревопащих.",al={"де оґтінк","місце оґтінка","як знайти оґтінка"}},{q="Чому Оґтінк покинув своє плем'я?",a="Оґтінк покинув родичів саме для того, щоб допомагати Колу Кенарія берегти природу. Хоча з якого він племені, точно не сказано, його ясний розум і мирна вдача різко відрізняють його від зіпсованих племен в інших куточках північного Калімдору.",al={"чому оґтінк покинув плем'я","плем'я оґтінка","чи оґтінк деревопад"}},{q="Яку роль Оґтінк відіграє для мисливців?",a="Оґтінк — наставник для досвідчених мисливців, що дійшли до вершини свого навчання. Він доручає їм вистежувати грізних звірів по всьому Калімдору — від прудких скакунів до виводку зеленого драконячого роду, — щоб довести своє панування над дикою природою.",al={"завдання мисливців оґтінка","тренер мисливців оґтінк","навіщо йти до оґтінка"}},{q="Чи пов'язаний Оґтінк із Твердинею Деревопащих?",a="Хоча він таборує біля Твердині Деревопащих, Оґтінк діє незалежно, у прямому союзі з Колом Кенарія. Він привітний до мандрівників, що приходять із миром, хоч би якою була їхня репутація в племені Деревопащих.",al={"оґтінк деревопади","репутація деревопадів оґтінк","чи оґтінк дружній"}},{q="Чому Оґтінк стежить за Руїнами Елдарата?",a="З його місця високо над руїнами добре видно неспокійні нетрі внизу, де наги, елементалі й відлуння давньої магії загрожують хиткій рівновазі прибережного лісу.",al={"чому оґтінк в азшарі","елдарат оґтінк","скеля оґтінка"}}},fp="6,350,15.381.0,18.456.0,14.243.0,26.137.0,31.267.0,39.257.0,41.231.0,49.209.0"}
P.entries["npc:ogunaro-wolfrunner"] = {n="Оґунаро Вульфраннер",s="Оґунаро Вульфраннер — найкращий заводчик вовків Орди й доглядач псарні в Оргріммарі; його місце — біля Зали Мисливця в Долині Честі. Він доглядає лютих вовків, обраних нести в бій оркських поборників і їхніх вірних союзників. Досвідченим вершникам, що прагнуть порозумітися з верховними хижаками Дуротару, варто йти саме до Оґунаро.",h="Оґунаро Вульфраннер — найкращий заводчик вовків Орди й доглядач псарні в Оргріммарі; його місце — біля Зали...",kw={"оґунаро вульфраннер","вовки","верховий звір","зала мисливця","долина честі","дренор"},ang={["faction:Horde"]="Тролі, таурени й Відступники мусять довести Оргріммару свою відданість і честь, перш ніж Оґунаро довірить їм бойового вовка.",["race:Orc"]="Для орків їзда на вовках — родова традиція, що сягає кланів Дренору; Оґунаро — охоронець цього священного бойового зв'язку."},sec={{t="Ватажок зграї",b="Біля Зали Мисливця в Долині Честі Оґунаро Вульфраннер керує розведенням і вишколом бойових вовків Оргріммара. Зв'язок між орком і вовком тягнеться поколіннями — з рівнин Дренору до диких нетрів Дуротару — і це союз взаємної поваги, а не просте приручення. Оґунаро стежить, щоб найвитриваліших і найлютіших звірів — від грізних велетенських вовків до моторних лісових — довіряли лише воїнам, що довели свою силу й гідність перед вождем."}},faq={{q="Хто такий Оґунаро Вульфраннер?",a="Оґунаро Вульфраннер — головний розводчик вовків і продавець їздових тварин Орди; його можна знайти біля Зали Мисливця в Долині Честі Оргріммара.",al={"оґунаро","торговець вовками оргріммар","торговець орківськими їздовими"}},{q="Чи кожен може купити в нього вовка?",a="За правом походження орки можуть вільно придбати вовків, щойно навчаться їзди. Іншим членам Орди треба здобути звеличення й найвищу довіру Оргріммара, перш ніж Оґунаро віддасть їм одного зі своїх цінних звірів.",al={"чи не орки можуть купити вовка","вимоги репутації для вовка"}},{q="Яких вовків він пропонує?",a="Оґунаро тримає різноманітну псарню загартованих у боях їздових вовків — чорних, бурих, лютововків і лісових вовків, — а також прудких броньованих порід для ветеранів війни.",al={"види вовків-їздових","яких вовків продає оґунаро"}}},fp="18,331,18.525.0,26.142.0,36.212.0,37.167.0"}
P.entries["npc:old-murk-eye"] = {n="Старий Мутноокий",s="Старий Мутноокий — сумнозвісний, загартований у боях мурлок, що нишпорить південним узбережжям Вестфолу. Шанований серед своїх і страшний для прибережних моряків, він становить смертельну загрозу для кожного, хто забреде до Маяка Вестфолу.",h="Старий Мутноокий — сумнозвісний, загартований у боях мурлок, що нишпорить південним узбережжям Вестфолу.",kw={"старий мутноокий","мурлок","маяк вестфолу","капітан ґрейсон","луска","вестфол"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу, які очищають Вестфол, знищення Старого Мутноокого позбавляє край сумнозвісного хижака, що полює на корабельні команди й мандрівників, які застрягли на березі."},sec={{t="Жах узбережжя",b="Мурлоки на берегах Вестфолу — звична напасть, але Старий Мутноокий вирізняється з-поміж дрібніших падальників. Значно міцніший і набагато агресивніший за родичів, цей посивілий звір нишпорить у прибої довкола Маяка Вестфолу. Він завдав стільки горя місцевим морякам, що примарний Капітан Ґрейсон прагне його смерті й обіцяє винагороду за бездоганну луску потвори, щоб звільнити мілини від її влади."}},faq={{q="Де блукає Старий Мутноокий?",a="Він обходить піщані береги й мілини на південному заході Вестфолу, просто вздовж узбережжя біля Маяка Вестфолу.",al={"місце старого мутноокого","де знайти старого мутноокого","де мутноокий"}},{q="Чому Капітан Ґрейсон хоче смерті Старого Мутноокого?",a="Капітан Ґрейсон вважає Старого Мутноокого постійною загрозою для прибережних вод. Щоб приборкати насильство на пляжі, він оголошує нагороду за цього легендарного мурлока й вимагає луску як доказ.",al={"ґрейсон мутноокий","чому вбивати старого мутноокого"}},{q="Чи Старий Мутноокий відрізняється від звичайних мурлоків?",a="Так. Він помітно сильніший, витриваліший і лютіший за підручних Берегоходів і Мисливців Припливу довкола нього й верховодить серед місцевих прибережних зграй.",al={"наскільки міцний мутноокий","чи мутноокий елітний"}}},fp="12,229,23.451.0,31.127.0,48.203.0,48.184.0"}
P.entries["npc:old-serra-kis"] = {n="Старий Серра'кіс",s="Старий Серра'кіс — давній велетенський трешадон, що живе в затоплених підземних водах Чорноглибинних Печер. Культисти Молота Присмерку, що вторглися сюди, винищили на харч більшість водних мешканців храму, але полювання на цього велетенського звіра виявилося смертельно небезпечним.",h="Старий Серра'кіс — давній велетенський трешадон, що живе в затоплених підземних водах Чорноглибинних Печер.",kw={"старий серра'кіс","трешадон","чорноглибинні печери","підводна печера","молот присмерку"},ang={["class:Druid"]="Друїдам дикої природи Водяна форма стане незамінною, коли доведеться пірнати в непроглядний ставок, щоб зійтися з цим доісторичним хижаком.",["class:Shaman"]="Закляття «Підводне дихання», дароване духовним єднанням зі стихіями, не дасть вашим супутникам потонути, поки ви боретеся з давнім хижаком.",["class:Warlock"]="Чорнокнижникове закляття «Нескінченний подих» перетворює смертельну безповітряну підземну засідку на цілком подоланний бій."},sec={{t="Нескорений у глибинах",b="Коли культисти Молота Присмерку спустилися до затонулих Руїн Місячної Святині, вони перебили місцевих підводних звірів собі на поживу. Та під Святилищем Місячної Святині одна первісна істота не захотіла ставати здобиччю. Старий Серра'кіс, найбільший трешадон затонулого храму, швидко розправлявся з кожним культистом, що мав зухвалість націлити на нього спис. Зрештою мисливці відступилися, і давній хижак лишився у своїх водяних володіннях сам."},{t="Прихована загроза",b="Щоб дістатися Старого Серра'кіса, треба пірнути глибоко під підлогу храму, у затоплену печеру під руїнами. Повітряних кишень там немає, тож сама печера не менш смертоносна, ніж звір у ній. Ті, хто заганяє його в кут, дізнаються, що Серра'кіс має неприродну тіньову живучість: він висмоктує життя з нападників, підтримуючи власні сили в каламутній темряві."}},faq={{q="Що за створіння Старий Серра'кіс?",a="Старий Серра'кіс — величезний стародавній трешадон, довгошия водяна рептилія, що водиться в озерах і прибережних водах Азероту.",al={"що таке серра'кіс","чи серра'кіс гідра","вид серра'кіса"}},{q="Чому Молот Присмерку його не вбив?",a="Культ вибив більшість водяних створінь під Руїнами Місячної Святині на їжу, але Серра'кіс виявився надто сильним і хитрим. Культисти, які вперто намагалися на нього полювати, неминуче самі ставали його обідом, тож культ узагалі обходить його печеру стороною.",al={"чому серра'кіс живий","молот присмерку серра'кіс"}},{q="Де перебуває Старий Серра'кіс?",a="Він чатує в затопленій печері під водою довкола Святилища Місячної Святині в Чорноглибинних Печерах. Щоб зустрітися з ним, плавцям доводиться пірнути під руїни, у водойму без повітря.",al={"як знайти серра'кіса","місце серра'кіса","де старий серра'кіс"}},{q="Чим небезпечний бій із ним?",a="Мало того, що битися доводиться цілком під водою, де немає повітряних кишень, — Старий Серра'кіс ще й висмоктує тіньову енергію з усіх ворогів поблизу, щоб загоювати власні рани впродовж бою.",al={"здібності серра'кіса","як перемогти серра'кіса"}},{q="Чи служить Серра'кіс Молотові Присмерку?",a="Ні. На відміну від інших звірів, яких культ зіпсував чи вишколив, Старий Серра'кіс лишається цілком диким хижаком, що боронить своє підводне лігво.",al={"чи серра'кіс улюбленець культистів","хто керує серра'кісом"}},{q="Чи можна дихати під час бою із Серра'кісом?",a="У його замкненій печері під склепінням немає повітряних кишень, тож підводним бійцям доводиться або берегти подих, або вдаватися до магічного дихання під водою, або виманювати звіра на відкриту воду.",al={"тонути серра'кіс","дихання під водою серра'кіс"}}},fp="13,285,25.465.0,15.368.0,39.130.0,42.257.0,31.183.0,34.166.0,43.147.0,49.181.0"}
P.entries["npc:onyxia"] = {n="Оніксія",s="Оніксія — матір виводку чорних драконів і підступна донька Детвінга. Причаївшись у своєму драконячому лігві в Багні Пилоброду, вона доглядає свій зростаючий виводок і разом зі своєю зловісною зграєю прагне панувати над світами смертних.",h="Оніксія — матір виводку чорних драконів і підступна донька Детвінга.",kw={"оніксія","чорні дракони","катрана престор","багно пилоброду","стормвінд","детвінг"},sec={{t="Матір виводку при дворі",b="Поки її брат Нефаріан збирає армії в Шпилі Блекрок, Оніксія йде до влади хитрістю. Прибравши личину Леді Катрани Престор, вона пролізла в найвищі кола знаті Стормвінда. Удаючи довірену радницю Дому Вельмож, вона планомірно підточує воєнні зусилля королівства, навмисно не даючи солдатів і припасів заставам у Вестфолі, Редріджі та Палаючих Степах, щоб лишити світи смертних беззахисними."},{t="Архітекторка руїни",b="За намальованими усмішками Леді Престор ховається хижий розум, що стоїть за найболючішими трагедіями Стормвінда. Саме Оніксія розпалила запеклу суперечку між Гільдією Каменярів і Домом Вельмож, що призвела до смертельного бунту, у якому загинула королева Тіффін Рінн. Тепер, коли короля Варіана викрали дорогою на мирну зустріч у Тераморі, Престор має глибокий вплив на юного короля-хлопчика Андуїна й обплутала своїми тенетами Верховного Лорда Болвара Фордрагона, і трон уже хитається в її пазурах."}},faq={{q="Хто така Леді Катрана Престор?",a="Леді Катрана Престор — шляхетна пані зі Стормвінда й довірена радниця при дворі. Поки Король Варіан зник, вона стоїть поруч із юним королем Андуїном і Верховним Лордом Болваром Фордрагоном у Фортеці Стормвінда, і її поради мають велику вагу в Домі Вельмож.",al={"особа престор","хто така престор","справжня особа катрани престор"}},{q="Чому Оніксія обрала своєю ціллю Стормвінд?",a="Оніксія вважає людей тим смертним народом, що найкраще здатен кинути виклик драконам. Вона прагне підкорити королівство Стормвінд владі чорного драконячого роду, знешкодити його військову силу й допомогти своєму братові Нефаріану панувати в цьому краї.",al={"мета оніксії","чому напад на стормвінд","мотив престор"}},{q="Де живе Оніксія?",a="Домівка Оніксії — підземне лігво серед боліт Багна Пилоброду, де вона доглядає кладки яєць чорного драконячого роду.",al={"де оніксія","місце оніксії","лігво оніксії"}},{q="Що пов'язує її з Нефаріаном і Детвінгом?",a="Оніксія — донька Аспекта Детвінга та його подруги Сінтарії. Вона також молодша сестра-близнючка Нефаріана й тісно співпрацює з ним, щоб відновити панування чорного драконячого роду в Азероті.",al={"брат оніксії","батько оніксії","родина оніксії"}}},fp="6,267,28.488.1,17.522.2,28.254.2,33.250.2,23.138.2,49.209.0"}
P.entries["npc:orendil-broadleaf"] = {n="Орендил Броудліф",s="Орендил Броудліф — вправний травник і цілитель із нічних ельфів на Посту Маестри в західному Ашенвалі. Відомий глибоким знанням лісових рослин, він готує життєво важливі ліки, що рятують юні життя по всіх неспокійних лісах.",h="Орендил Броудліф — вправний травник і цілитель із нічних ельфів на Посту Маестри в західному Ашенвалі.",kw={"орендил броудліф","травник","цілитель","пост маестри","релара вайтмун","волосся батрана"},ang={["profession:Herbalism"]="Орендил показує, яку рятівну вагу мають місцеві рослини: він покладається на рідкісні трави на кшталт Волосся Батрана, щоб варити сильні протиотрути просто в польових умовах.",["race:NightElf"]="Для нічних ельфів, що боронять Ашенваль, Орендил — незамінний охоронець життя, чиї лагідні ліки здатні врятувати навіть смертельно хвору дитину."},sec={{t="Цілитель лісового порубіжжя",b="Орендил Броудліф, що служить на Посту Маестри на західному порозі Ашенвалю, як вправний цілитель доглядає хворих. Знаний за майстерне знання місцевих трав і цілющого ремесла, Орендил покладається на перехожих мандрівників, щоб збирати рідкісні природні складники. Навіть коли напруга й ворожнеча підступають до лісу, він невтомно дбає про те, щоб уберегти родичів і полегшити їхні недуги."},{t="Перегони з хворобою",b="Понад усе Орендил відіграє головну роль у відчайдушних спробах вилікувати Релару Вайтмун, хвору дитину з Астранаару. Ретельно вивчаючи лісові рослини — зокрема Волосся Батрана, — він створює сильні еліксири, здатні стримати смертельну недугу, і показує, що травницька майстерність лишається важливим щитом від небезпек, які чатують в Ашенвалі."}},faq={{q="Хто такий Орендил Броудліф?",a="Орендил Броудліф — нічний ельф, травник і цілитель, що живе на Посту Маестри на заході Ашенвалю. Його вміння з травами й лікуванням широко відоме.",al={"орендил броудліф","хто такий орендил","орендил ясенлісся"}},{q="Де знайти Орендила Броудліфа?",a="Він на Посту Маестри — заставі нічних ельфів при головній дорозі на заході Ашенвалю, неподалік від межі з Темним Узбережжям.",al={"місце орендила броудліфа","знайти орендила","де орендил"}},{q="Що намагається вилікувати Орендил?",a="Орендил готує цілюще зілля, щоб урятувати Релару Вайтмун — хвору дитину нічних ельфів з Астранаару, — з рідкісних трав, зібраних у диких куточках Ашенвалю.",al={"лікування орендила","кого лікує орендил","ліки релари вайтмун"}}},fp="17,235,27.408.0,23.358.1,25.148.0,37.135.0,31.174.0"}
P.entries["npc:orenthil-whisperwind"] = {n="Орентіл Віспервінд",sec={{t="Дружнє обличчя в Тельдрассилі",b="Orenthil Whisperwind resides among the night elves of Shadowglen, beneath the canopy of Teldrassil. Little is recorded about his personal history."}},faq={{q="Хто такий Орентіл Віспервінд?",a="Це нічний ельф, якого можна зустріти в Тінедолі на Тельдрассилі. Він привітно зустрічає шукачів пригод, що вирушають у мандри гілками Світового Дерева.",al={"орентіл","лор орентіла віспервінда","хто цей ельф"}},{q="Де знайти Орентіла Віспервінда?",a="Орентіл живе в Тінедолі — стартовому поселенні нічних ельфів на Тельдрассилі.",al={"місце орентіла","де орентіл","карта орентіла"}}},fp="20,105,29.146.0,28.147.0,38.84.0"}
P.entries["npc:orgnil-soulscar"] = {n="Орґніл Соулскар",s="Орґніл Соулскар — орк-слідчий, що стоїть на Гострому Пагорбі в центральному Дуротарі. Він виконує роль неофіційного охоронця порядку, узгоджуючи оборону й розвідку проти внутрішніх загроз молодій державі. Найбільше його непокоїть тінь, яку кидає на каньйони Дуротару культ Палаючого Клинка.",h="Орґніл Соулскар — орк-слідчий, що стоїть на Гострому Пагорбі в центральному Дуротарі.",kw={"орґніл соулскар","слідчий","орк","гострий пагорб","палаючий клинок","культ","дуротар"},ang={["class:Warlock"]="Чорнокнижникам варто поводитися обережно поруч з Орґнілом, адже вся його увага зосереджена на тому, щоб вистежити й викорінити неконтрольоване демонічне скверніння в межах Дуротару.",["faction:Horde"]="Орґніл дбає, щоб, поки Орда дивиться назовні й будує нову державу, її серце не випорожнили зсередини культисти.",["race:Orc"]="Для молодих орків Орґніл — передова лінія проти демонічної зарази, що колись поневолила клани; він нагадує новобранцям, якої пильності вимагає чистота нової батьківщини."},sec={{t="Вартівник Гострого Пагорба",b="На Гострому Пагорбі Орґніл Соулскар узяв на себе похмурий обов'язок вистежувати підривну діяльність і підступні загрози по всьому Дуротару. Поки патрулі бійців дивляться назовні — на плацдарми Альянсу та загони кентаврів-нападників, — Орґніл зосереджений на гнилі, що визріває зсередини. Він збирає донесення розвідників з усього краю, складаючи докупи докази обрядового скверніння та потаємних зібрань."},{t="Полювання на рештки Ради Тіней",b="Головний клопіт Орґніла — таємне відродження культу Палаючого Клинка, чиї чорнокнижники ховаються в печерах на кшталт Череп-скелі. Знаючи, яке спустошення магія Скверни принесла орківському народові в минулих поколіннях, Орґніл не дозволить поклонінню демонам знову закріпитися біля Оргріммара. Він посилає довірених новобранців убивати культистів, збирати обрядові талісмани й радитися з місцевими відлюдниками та шаманами, як-от Марґоз, щоб зрозуміти, яка темна магія тут діє."}},faq={{q="Хто такий Орґніл Соулскар?",a="Орґніл Соулскар — орк-посадовець із Гострого Пагорба, що розслідує загрози й організовує оборону Дуротару. Він спрямовує воїнів і розвідників проти прихованих небезпек, що загрожують щойно заселеним землям орків.",al={"хто такий орґніл","лор орґніла соулскара","давець завдань гострого пагорба"}},{q="Яка загроза найбільше тривожить Орґніла?",a="Орґніл присвятив себе викоріненню культу Палаючого Клинка. Їхню присутність у потаємних печерах Дуротару й їхню згубну магію Скверни він вважає смертельною загрозою для нового початку, який Тралл бачить для Орди.",al={"чого хоче орґніл","вороги орґніла","з ким бореться орґніл"}},{q="Чому Орґніл посилає мандрівників до Марґоза?",a="Марґоз — обізнаний відлюдник, що живе на північ від Гострого Пагорба й знається на темних знаках і ритуалах Палаючого Клинка. Орґніл посилає розвідників до Марґоза, щоб розгадати задуми культу й розплутати магічну скверну, що назріває.",al={"чому марґоз","орґніл і марґоз","хто марґоз для орґніла"}},{q="Де знайти Орґніла Соулскара?",a="Орґніл стоїть надворі в поселенні Гострий Пагорб, біля головного перехрестя Дуротару.",al={"місце орґніла","де орґніл","знайти орґніла соулскара"}},{q="Що таке Палаючий Клинок у Дуротарі?",a="Палаючий Клинок — зловісний культ, що служить демонічним володарям і Раді Тіней. Вони ховаються в ярах на кшталт Череп-скелі й у Печері Пилового Вітру, намагаючись отруїти тварин Дуротару й знову спокусити молодих орків на службу демонам.",al={"палаючий клинок дуротар","культ палаючого клинка","хто палаючий клинок"}},{q="Чи працює Орґніл безпосередньо на Тралла?",a="Орґніл належить до місцевої оборони з осередком на Гострому Пагорбі й виконує веління Вождя берегти Дуротар від заколотів і демонічного впливу.",al={"орґніл тралл","чи орґніл охоронець вождя"}}},fp="15,308,21.388.0,37.458.1,23.216.0,41.210.0,41.233.0,35.101.0,37.240.0,37.175.0"}
P.entries["npc:orgrim-doomhammer"] = {n="Оргрім Думхаммер",s="Оргрім Думхаммер був верховним Вождем Старої Орди впродовж усієї Другої війни; його пам'ятають як одного з найвидатніших орочих воїнів в історії. Він загинув, визволяючи табори ув'язнення в Аратійському нагір'ї, але його спадщина живе у столиці Оргріммар і в Траллі, який успадкував його могутній бойовий молот і чорні латні обладунки.",h="Оргрім Думхаммер був верховним Вождем Старої Орди впродовж усієї Другої війни; його пам'ятають як одного з...",kw={"оргрім думхаммер","вождь","стара орда","друга війна","тралл","гаммерфолл","оргріммар"},ang={["faction:Alliance"]="Для Альянсу Думхаммер лишається похмурим символом того, як у Другій війні Східні Королівства опинилися на межі знищення: до поразки під Шпилем Блекрок він стяв безліч героїв.",["race:Orc"]="Орки шанують Оргріма Думхаммера як визволителя, що вирвав їхній народ з апатії й неволі таборів і обрав честь замість покори демонам."},sec={{t="Сходження Вождя",b="Спершу Оргрім був правою рукою Блекгенда з клану Блекрок. Він відмовився від демонічної крові, яку пропонував Ґул'дан, хоча й ховав свої сумніви за запеклою вірністю. Наприкінці Першої війни, з огидою спостерігаючи за підступністю Ради Тіней і вбивством свого друга дитинства Дуротана, Оргрім убив Блекгенда в чесному поєдинку. Ставши Вождем, він нещадно винищив чорнокнижників Ґул'дана й повів Орду через Східні Королівства в Другій війні. Грізний стратег, що поставив людські королівства на межу загибелі, він усе ж зазнав поразки й потрапив у полон під Шпилем Блекрок, коли зрада Ґул'дана розколола його військо."},{t="Загибель і спадщина",b="Утікши з людського полону, Думхаммер переховувався, доки не зустрів Тралла — осиротілого сина Дуротана. Натхненний задумом молодого шамана, Оргрім згуртував рештки орочих кланів, щоб штурмувати табори ув'язнення й визволити свій народ. У запеклій битві біля одного з таборів в Аратійському нагір'ї Вождя вдарили списом у спину. Помираючи, він передав Траллові свої чорні латні обладунки, родову зброю — молот Думхаммер — і титул Вождя. На його честь визволену заставу назвали Гаммерфолл, а нову столицю в Дуротарі — Оргріммаром."}},faq={{q="Хто такий Оргрім Думхаммер?",a="Він був вождем клану Блекрок і Вождем, що очолював Орду під час Другої війни. Через багато років, утікши з людського полону, він бився пліч-о-пліч із Траллом, визволяючи ув'язнених родичів, аж до своєї загибелі в Аратійському нагір'ї.",al={"хто такий думхаммер","минуле оргріма думхаммера","хто був вождем думхаммером"}},{q="Як загинув Оргрім Думхаммер?",a="Оргрім загинув під час штурму людського табору для інтернованих в Аратійському нагір'ї: лицар ударив його списом у спину. Тралл перейняв його мантію, а місце тієї перемоги назвали Гаммерфолл на згадку про його самопожертву.",al={"смерть оргріма думхаммера","як помер думхаммер","хто вбив думхаммера"}},{q="Чому столицю Орди названо Оргріммаром?",a="Тралл назвав укріплене місто в Дуротарі на честь свого наставника й попередника. Оргрім розгледів у Траллові обіцянку й назвав його новим Вождем, щоб Орда відроджувалася на засадах честі, а не демонічної скверни.",al={"чому оргріммар так названо","тезка оргріммара","місто назване на честь оргріма"}},{q="Чи пив Оргрім демонічну кров?",a="Ні. Оргрім удав смирення, сказавши Блекгенду й Ґул'дану, що простий слуга не гідний пити з однієї чаші з Вождем. Ця хитра відмовка дозволила йому зберегти ясний розум і згодом зсередини знищити Раду Тіней Ґул'дана.",al={"чи оргрім пив кров демона","чи оргрім осквернений","демонська кров оргріма"}}},fp="17,342,20.674.0,15.625.0,26.251.0,30.231.0,41.218.0,33.251.0"}
P.entries["npc:ormak-grimshot"] = {n="Ормак Ґрімшот",s="Ормак Ґрімшот — досвідчений орк, наставник мисливців у Залі Мисливця в Долині Честі Оргріммара. У супроводі вірного вовка Ґрімфанґа він навчає молодих мисливців Орди вистежування, стрільби та єднання з дикими звірами.",h="Ормак Ґрімшот — досвідчений орк, наставник мисливців у Залі Мисливця в Долині Честі Оргріммара.",kw={"ормак ґрімшот","мисливець","наставник","зала мисливця","долина честі","оргріммар","вовк"},ang={["class:Hunter"]="Ормак — необхідний наставник для мисливців Орди, що проводить їх крізь обов'язки приборкання й утримання вірного тваринного супутника.",["race:Orc"]="Відображаючи класичні орчі навички виживання, Ормак показує, як орки працюють пліч-о-пліч із вовками й тутешніми хижаками, боронячи Дуротар."},sec={{t="Майстер полювання",b="Ормак Ґрімшот, що стоїть у Залі Мисливця в Долині Честі, — наріжний камінь бойового вишколу слідопитів і стрільців Орди. Разом зі своїм супутником-вовком Ґрімфанґом Ормак передає основи дисципліни, потрібної, щоб вижити в суворих нетрях Калімдору. Оркам і тролям-мисливцям, що прибувають після випробувань у Дуроторі, він дає важливі настанови щодо священного мистецтва приборкання диких звірів і керування ними, щоб кожен мисливець створив тривкий зв'язок зі своїм тваринним партнером."}},faq={{q="Хто такий Ормак Ґрімшот?",a="Ормак Ґрімшот — бувалий орк, наставник мисливців у Долині Честі Оргріммара. Він навчає нових мисливців Орди вищої майстерності в стрільбі й володінні звірами.",al={"хто такий ормак","лор ормака ґрімшота","тренер мисливців ормак"}},{q="Де знайти Ормака Ґрімшота?",a="Ормак — у Залі Мисливця, що в Долині Честі на сході Оргріммара. Він стоїть поруч зі своїм вовком Ґрімфенгом.",al={"місце ормака","де ґрімшот","знайти ормака"}},{q="Що за вовк поруч із ним?",a="Вовк поруч із ним — Ґрімфенг, вірний звір-супутник Ормака, що показує, який міцний зв'язок поєднує вправного мисливця з його улюбленцем.",al={"вовк ормака","ґрімфенг","улюбленець ормака"}},{q="Яку роль він відіграє для нових мисливців?",a="Ормак навчає мисливців-новачків — орків і тролів, які пройшли перші випробування в Дуротарі, — як вишколювати, годувати й доглядати щойно приручених звірів.",al={"завдання улюбленця оргріммар","завдання приборкання ормак","навчання звіра ормак"}}},fp="14,255,18.508.0,22.169.0,32.134.0,27.133.0,39.149.0"}
P.entries["npc:ormer-ironbraid"] = {n="Ормер Айронбрейд",s="Ормер Айронбрейд — дворф-археолог на Місці Розкопок Велґара на півдні Багнокраю. Історичні дослідження його загону жорстоко перервали ненажерливі раптори, що заполонили розкоп. Ормер шукає відважних союзників, щоб вичистити звірів і помститися за копачів, вигнаних із розкопу.",h="Ормер Айронбрейд — дворф-археолог на Місці Розкопок Велґара на півдні Багнокраю.",kw={"ормер айронбрейд","раптори","місце розкопок велґара","помста","ліга дослідників","багнокрай"},ang={["class:Hunter"]="Мисливцям прохання Ормера видасться знайомим завданням: зміряти свою вправність у вистежуванні й убиванні звірів із кількома найлютішими рапторами Каз Модану.",["faction:Alliance"]="Допомагаючи Ормерові, ви вбезпечуєте південну дорогу Багнокраю й підтримуєте важливі археологічні починання Айронфорджа.",["race:Dwarf"]="Ормер утілює дворфійську впертість — він не віддасть прадавніх земель предків зграї переростків-ящірок."},sec={{t="Розкоп, що зійшов з колії",b="Ормер Айронбрейд прибув у Багнокрай у межах дворфійських пошуків реліквій титанів і давньої історії на Місці Розкопок Велґара. На жаль, відкопуючи давні камені, вони відкопали — чи принаймні розлютили — зграї лютих рапторів Багнокраю. Замість описувати давній посуд і таблички, Ормер днями спостерігає, як звірі нишпорять серед руїн, і плекає люту ненависть до істот, що зірвали їхню роботу."},{t="Гірка ворожнеча з пазурами",b="Ормер не кидає розкопу, але йому бракує грубої сили, щоб очистити його самотужки. Він спрямовує свою досаду в планомірну кампанію винищення, наймаючи мандрівників убивати дедалі більших і лютіших рапторів. Для Ормера повернути розкоп — справа не лише артефактів, а й глибоко особиста: справа дворфійської гордості й помсти місцевій звірині."}},faq={{q="Хто такий Ормер Айронбрейд?",a="Ормер Айронбрейд — дворф-дослідник, що наглядає за роботами на Місці Розкопок Велґара в Багнокраї. Він представляє інтереси Ліги Дослідників у вивченні стародавніх руїн, похованих у болотах.",al={"хто такий ормер","ормер айронбрейд","ормер мокрі землі"}},{q="Де знайти Ормера Айронбрейда?",a="Він стоїть на оглядовому майданчику над Місцем Розкопок Велґара, на південних кручах Багнокраю, трохи на схід від головної дороги до Лох Модану.",al={"місце ормера","де ормер","знайти ормера айронбрейда"}},{q="Чому Ормер так ненавидить ящерів?",a="Місцеві зграї ящерів захопили розкопки, вигнали дворфів-робітників і зупинили всю археологічну роботу. Ормер сприйняв це як особисту образу й прагне сповна поквитатися.",al={"чому ормер ненавидить раптори","ормер раптори","помста ормера лор"}},{q="Що таке Місце Розкопок Велґара?",a="Це археологічні розкопки, які заснували дворфи Айронфорджа, щоб відкопати стародавні руїни титанів і землян під Багнокраєм. Але люті тварини перетворили розкопки на небезпечне поле бою.",al={"місце розкопок велґара","що за розкопки","розкопки мокрих земель"}},{q="Які завдання дає Ормер?",a="Ормер дає ланцюжок із трьох завдань «Помста Ормера», доручаючи шукачам пригод винищувати на розкопках дедалі більших ящерів.",al={"завдання ормера","вдар по землі","завдання помста ормера"}},{q="Чи пов'язаний Ормер із Лігою Дослідників?",a="Так. Як і багато дворфів, що розкопують стародавні руїни по всьому Каз Модану, Ормер працює для археологічних досліджень Айронфорджа, які мають відкрити титанічне коріння його народу.",al={"ормер ліга дослідників","чи ормер археолог"}}},fp="15,310,14.448.0,24.396.0,23.200.0,33.175.0,36.196.0,34.205.0,29.135.0,47.184.0"}
P.entries["npc:orokk-omosh"] = {n="Орокк Омош",s="Орокк Омош — старіючий орк-коваль у Долині Честі Оргріммара. Останній спадкоємець славетного роду ковалів, він шукає по всій Орді гідних учнів, щоб зберегти таємниці родинного бронярства, перш ніж їх поглине час.",h="Орокк Омош — старіючий орк-коваль у Долині Честі Оргріммара.",kw={"орокк омош","коваль","ковальство","обладунки","долина честі","танок радості"},ang={["faction:Horde"]="Відданість Орокка зберігає традиційні оркські прийоми виготовлення латних і кольчужних обладунків, що зміцнюють воїнів молодої Орди.",["profession:Blacksmithing"]="Для бронярів Орди Орокк Омош — незамінний наставник, що дає особливі креслення й вишкіл, аби родове ремесло вижило."},sec={{t="Рід на межі",b="Стоячи біля ревучих горнів Долини Честі, Орокк Омош несе важкий тягар: він останній коваль шанованого роду Омош. Не маючи дітей, які успадкували б його ремесло, Орокк не хоче, щоб здобуті тяжкою працею прийоми його родини померли разом із ним. Тож він запрошує вправних ковалів Орди пройти вимогливі випробування з обробки металу й обіцяє відкрити шановані таємниці бронярства Омошів тим, хто доведе свою відданість."},{t="Дух кузні",b="Попри сумну правду про згасання свого роду, Орокк відомий серед ремісників гучним запалом, коли бачить справжню майстерність. Пройдені випробування дають не лише особливі креслення обладунків — часто вони викликають славетний «Танок радості Омоша», бурхливе свято традиційного ковальства, що лунає залами Оргріммара."}},faq={{q="Хто такий Орокк Омош?",a="Орокк Омош — орк, майстер-коваль із Долини Честі в Оргріммарі. Він останній живий із ковальського роду Омошів і проводить дні в пошуках обдарованих учнів, яким міг би передати родинне знання металургії.",al={"хто такий орокк","лор орокка омоша","орк-коваль оргріммар"}},{q="Де знайти Орокка Омоша?",a="Ви знайдете Орокка Омоша біля ковальських горнів і ковадел у Долині Честі, у північно-східній частині Оргріммара.",al={"місце орокка омоша","де орокк","знайти орокка омоша"}},{q="Чому Орокк Омош розкриває родинні таємниці чужим?",a="В Орокка немає власних дітей, яким можна передати родинне ремесло. Щоб не дати зникнути вікам орківського мистецтва кування обладунків, він вирішив навчати кожного вправного коваля Орди, який доведе, що відповідає його високим вимогам.",al={"чому орокк дає завдання","спадок омоша","чому навчає ковалів"}},{q="Що таке «Радісний танець Омоша»?",a="Це бурхливий святковий танок, який Орокк виконує, коли ремісник доводить свою вартість і опановує ковальські прийоми його роду. Це і його особиста печатка схвалення, і завзята данина ремеслу.",al={"радісний танець омоша","танець омоша","радощі омоша"}}},fp="11,246,20.450.0,23.384.0,19.252.0,31.134.0,57.237.0,33.233.0"}
P.entries["npc:orphan-matron-battlewail"] = {n="Матрона Сиротинця Баттлвейл",s="Матрона Сиротинця Баттлвейл керує сиротинцем Орди в Долині Честі Оргріммара. Разом із товаришкою-доглядальницею Тосаміною вона дає притулок і виховує маленьких орків, що втратили родини в безкінечних війнах.",h="Матрона Сиротинця Баттлвейл керує сиротинцем Орди в Долині Честі Оргріммара.",kw={"баттлвейл","сиротинець","тосаміна","тиждень дітей","долина честі","сироти"},ang={["faction:Horde"]="Баттлвейл береже майбутнє Орди, даючи настанови й притулок дітям, яких залишила по собі сувора дійсність війни.",["race:Orc"]="Для орків, що прагнуть збудувати в Дуротарі тривку батьківщину, сиротинець Баттлвейл — тверезе нагадування про жертви, яких зазнає їхній народ."},sec={{t="Опікунка молоді Орди",b="Війна безупинно збирає свою данину по всьому Азероту, і молода столиця Оргріммар бачить цю ціну на власні очі. Матрона Сиротинця Баттлвейл піклується про малечу, що втратила рідних через насильство, щоб наступне покоління Орди мало захист, дах над головою й турботу. Працюючи пліч-о-пліч із Тосаміною в Долині Честі, Баттлвейл відчиняє двері сиротинця для мандрівних шукачів пригод — особливо на свята, як-от Тиждень Дітей, коли мандрівників просять узяти дітей під свою опіку."}},faq={{q="Хто така Матрона Сиротинця Баттлвейл?",a="Це орчиха, що опікується сиротинцем в Оргріммарі й присвятила життя тому, щоб давати притулок і виховувати дітей, чиї батьки загинули в боях.",al={"роль баттлвейл","хто така баттлвейл","матрона баттлвейл"}},{q="Де її знайти в Оргріммарі?",a="Баттлвейл і її помічниця Тосаміна доглядають дітей у Долині Честі, у східній частині Оргріммара.",al={"місце баттлвейл","де сиротинець","знайти баттлвейл"}},{q="Яка її роль під час Тижня Дітей?",a="Під час свята Тижня Дітей Баттлвейл організовує наставництво: посилає охочих поборників у світ разом із сиротою, щоб показати йому дива й спадщину Орди.",al={"тиждень дітей баттлвейл","опікун орди","завдання сироти"}},{q="Хто допомагає Баттлвейл у сиротинці?",a="Тосаміна живе й працює поруч із Баттлвейл, допомагаючи доглядати й захищати дітей, довірених їхній опіці.",al={"тосаміна","помічниця матрони сиротинця"}}},fp="24,224,30.498.0,32.145.0,36.133.0,40.191.0,40.115.0"}
P.entries["npc:orphan-matron-nightingale"] = {n="Матрона Сиротинця Найтінґейл",s="Матрона Сиротинця Найтінґейл опікується сиротинцем Стормвінда на Соборній Площі. Разом із Матроною Шеллін вона доглядає дітей, які втратили родини в нескінченних війнах, що терзають королівство. А на Тиждень Дітей вона залучає надійних шукачів пригод Альянсу, щоб ті стали наставниками й натхненням для її маленьких підопічних.",h="Матрона Сиротинця Найтінґейл опікується сиротинцем Стормвінда на Соборній Площі.",kw={"матрона найтінґейл","сиротинець","тиждень дітей","соборна площа","шеллін","сироти"},ang={["class:Priest"]="Справа Найтінґейл, яка стоїть просто біля Собору Світла, втілює ті чесноти співчуття й служіння, яких прагнуть дотримуватися жерці Святого Світла.",["faction:Alliance"]="Для героїв Альянсу Найтінґейл — нагадування про тиху, буденну ціну війни й про обов'язок берегти майбутні покоління королівства."},sec={{t="Хранителька знедолених",b="Матрона Сиротинця Найтінґейл чатує просто біля сиротинця на південний схід від Собору Світла й дбає про найвразливіших уцілілих Стормвінда. Недавні війни, набіги гнолів і піднесення Братства Дефіас залишили багатьох дітей без даху й батьків. Найтінґейл і її товаришка-доглядальниця, Матрона Шеллін, дають цим малим притулок, найпростіший догляд і настанови під пильним оком Церкви Святого Світла."},{t="Покровителька Тижня Дітей",b="Певна, що надія потрібна не менше за їжу й дах, Матрона Найтінґейл влаштовує в Стормвінді свято Тижня Дітей. У ці дні вона просить героїв Альянсу взяти сироту з собою в мандри Азеротом. Поєднуючи дітей зі славетними звитяжцями, вона сподівається додати малим упевненості, показати їм ширший світ за міськими мурами й нагадати, що про них ніколи не забувають."}},faq={{q="Де знайти Матрону Сиротинця Найтінґейл?",a="Вона стоїть просто біля входу до Сиротинця Стормвінда, на Соборній Площі на південний схід від Собору Світла.",al={"місце матрони найтінґейл","місце сиротинця стормвінда","де найтінґейл"}},{q="Чому в Стормвінді стільки сиріт?",a="Королівство пережило спустошливі війни, зокрема Третю війну, і досі веде сутички з Братством Дефіас, рештками орків і ворожими звірами в сусідніх землях. Багато містян і прикордонних хуторян загинули, лишивши дітей, яким нема куди подітися.",al={"чому в стормвінді сироти","звідки сироти стормвінда","хто ці діти"}},{q="Що таке Тиждень Дітей?",a="Тиждень Дітей — щорічне свято в Стормвінді, яке організовує Матрона Найтінґейл. Шукачів пригод Альянсу запрошують стати опікунами й провідниками для сироти й поводити дитину світом, щоб показати їй дива й героїв широкого світу.",al={"тиждень дітей стормвінд","що таке тиждень дітей","свято сиріт"}},{q="Хто допомагає Матроні Найтінґейл у сиротинці?",a="Поруч із Найтінґейл у сиротинці й біля нього працює Матрона Шеллін: вона допомагає виховувати, годувати й дає прихисток дітям, що під їхньою опікою.",al={"інша матрона сиротинця","хто керує сиротинцем","матрона шеллін"}}},fp="25,325,25.443.0,22.433.0,45.142.0,43.280.0,24.241.0,47.143.0"}
P.entries["npc:osric-strang"] = {n="Осрік Стренг",s="Осрік Стренг — бувалий торговець обладунками, що тримає крамницю «Обмежена Невразливість» у Старому Місті Стормвінда. Він спеціалізується на важких кольчугах і латах і постачає міцне спорядження та щити захисникам Альянсу й утомленим мандрівникам, що минають столицю.",h="Осрік Стренг — бувалий торговець обладунками, що тримає крамницю «Обмежена Невразливість» у Старому Місті...",kw={"осрік стренг","обладунки","старе місто","крамниця","лати","стормвінд"},ang={["class:Warrior"]="Осрік Стренг пропонує надійні комплекти кольчужних, лускатих і латних обладунків та щити — одне з перших джерел добротного важкого захисту для воїнів, що завітали до Старого Міста.",["faction:Alliance"]="Відданий мешканець міста й колишній міський вартовий, Осрік споряджає захисників королівства й допомагає гінцям, що підтримують шляхи постачання між Стормвіндом і віддаленими поселеннями."},sec={{t="Крамар з «Обмеженої Невразливості»",b="На обшарпаних вулицях Старого Міста Осрік Стренг веде крамницю «Обмежена Невразливість», що обслуговує бійців передової, яким потрібні важкі обладунки й щити. Осрік колись служив у варті Стормвінда, тож має наметане око на захисну цінність кольчуг і лат. Його товар пасує звичайним воякам і мандрівним шукачам пригод, а ще він часто допомагає гінцям, яким потрібна знайома людина в столиці, коли вони прибувають із ближніх поселень, як-от із Сентінел Гілла у Вестфолі."}},faq={{q="Що продає Осрік Стренг?",a="Осрік продає різні важкі захисні обладунки — від посиленої кольчуги й полірованої луски до цільних латних обладунків, малих круглих щитів і щитів-трикутників.",al={"крам осріка","що має осрік стренг","товари обмеженого імунітету"}},{q="Де знайти Осріка Стренга?",a="Він у крамниці обладунків «Обмежена Недоторканність» у Старому Місті, неподалік від південного району Стормвінда.",al={"місце осріка","де осрік стренг","місце обмеженого імунітету"}},{q="Чому мене посилають до Осріка Стренга в завданні?",a="Кур'єрів, що доставляють товари по всьому королівству — наприклад, вантажі, які прибувають через наглядача грифонів із Вестфолу, — часто посилають до крамниці Осріка в Старому Місті, щоб завершити доставку й отримати відповідь.",al={"чому до осріка стренга","завдання осріка стренга","доставка до осріка"}}},fp="12,257,30.507.0,28.157.0,30.107.0,41.205.0"}
P.entries["npc:overlord-mok-morokk"] = {n="Володар Мок'Морокк",s="Володар Мок'Морокк — брутальний вождь огрів Кам'яного Молота, що владарює в Селі Папоротяної Стіни в Багні Пилоброду. Колись Рекссар поставив його на чолі за силу, але він став тираном і боягузом, що відмовляється захищати свій клан від чорних драконів.",h="Володар Мок'Морокк — брутальний вождь огрів Кам'яного Молота, що владарює в Селі Папоротяної Стіни в Багні...",kw={"мок'морокк","кам'яний молот","огри","село папоротяної стіни","багно пилоброду","рекссар","драз'зілб"},ang={["class:Warrior"]="Мок'Морокк — хрестоматійний приклад грубої бойової сили без честі й мужності: він показує, як легко брутальна сила вироджується в боягузтво й тиранію.",["faction:Horde"]="Огри Кам'яного Молота — цінні союзники, які присягли Орді ще з часів походу Рекссара, але бездарне й боягузливе правління Мок'Морокка загрожує лишити Село Папоротяної Стіни зовсім беззахисним."},sec={{t="Тиран у болотах",b="Коли Рекссар здолав попереднього вождя Кор'ґалла й повів клан Кам'яного Молота захищати Дуротар, він лишив на чолі Мок'Морокка, бо побачив у ньому неабияку бойову силу. Ця віра виявилася хибною. Мок'Морокк швидко піддався згубному впливу необмеженої влади: він правив залякуванням і потуранням собі, а не дбайливим проводом. Замість турбуватися про родичів, він вимагає незаслуженої данини, вилежується в Селі Папоротяної Стіни й цькує кожного, хто сумнівається в його наказах."},{t="Боягуз Папоротяної Стіни",b="Провід Мок'Морокка остаточно розвалився, коли чорні дракони налетіли на прадавнє Село Кам'яного Молота, вбили багатьох огрів, а вцілілих загнали в багнюку Папоротяної Стіни. Замість того щоб зібрати сили для контрудару, повернути дім чи помститися за загиблих, Мок'Морокк заборонив будь-які дії, ховаючись від драконячого гніву. Серед його радників зріє невдоволення: такі, як огр-маг Драз'Зілб, потай шукають сторонніх чемпіонів, готових кинути виклик ганебному правлінню володаря."}},faq={{q="Хто такий Володар Мок'Морокк?",a="Мок'Морокк — вождь огрів Кам'яного Молота, що нині живе в Селі Папоротяної Стіни в Багні Пилоброду. Ватажком його поставив Рекссар, але він швидко перетворився на себелюбного й вимогливого деспота.",al={"хто такий мок'морокк","вожак папоротяної стіни","бос огрів кам'яного молота"}},{q="Як Мок'Морокк став ватажком клану Кам'яного Молота?",a="Коли засновували Дуротар, Чемпіон Орди Рекссар переміг попереднього ватажка клану й узяв Кам'яний Молот під свою руку. Вирушаючи мандрувати дикими краями, Рекссар призначив Мок'Морокка володарем через його грубу фізичну силу.",al={"як мок'морокк став вожаком","рекссар обрав мок'морокка","чому він вождь"}},{q="Чому огри Кам'яного Молота живуть у Селі Папоротяної Стіни?",a="Спершу огри Кам'яного Молота жили в Селі Кам'яного Молота, але чорні дракони напали на поселення й зрівняли його із землею. Ті, хто вцілів, утекли на північ, у болота, і заснували Село Папоротяної Стіни як табір біженців.",al={"чому огри в папоротяній стіні","що сталося з селом кам'яного молота","напад чорного дракона на огрів"}},{q="Чому Мок'Морокк не хоче битися з чорним драконячим родом?",a="Попри величезний зріст і грізну славу, Мок'Морокк до смерті боїться драконів. Замість повести контрнаступ, щоб повернути родові землі клану, він сидить без діла в Папоротяній Стіні, збирає данину й не зважає на благання свого народу.",al={"чому мок'морокк не б'ється з драконами","чи мок'морокк боягуз","повернути кам'яний молот"}},{q="Чи поважають Мок'Морокка інші огри Кам'яного Молота?",a="The clan grows increasingly resentful of his laziness, cowardice, and bullying. His advisers worry about the future of the Stonemaul under his rule.",al={"чи огри поважають мок'морокка","драз'зілб мок'морокк","бунт кам'яного молота"}}},fp="19,280,21.497.0,25.495.1,27.205.0,55.258.0,51.209.0,50.250.0,48.148.1"}
P.entries["npc:overlord-ramtusk"] = {n="Володар Рамтаск",s="Володар Рамтаск — загартований командир військових сил племені Мертвої Голови глибоко в Рейзорфен Краулі. Шкура цього величезного старого воїна-шипогрива всіяна шрамами за десятиліття жорстоких сутичок по всіх Пустках. Його смерть ламає бойовий хребет захисників Краула.",h="Володар Рамтаск — загартований командир військових сил племені Мертвої Голови глибоко в Рейзорфен Краулі.",kw={"володар рамтаск","мертва голова","шипогриви","рейзорфен краул","воєначальник"},ang={["class:Warrior"]="Рамтаск уособлює чисту, жорстоку бойову бувалість: він покладається на громові удари й владні бойові окрики, а не на шаманську геомантію чи магію колючок.",["race:Orc"]="Шипогриви нападають на поселення Орди ще відтоді, як засновано Дуротар і застави в Пустках. Зламавши військовий провід Рамтаска, ви вбережете Південні Пустки.",["race:Tauren"]="Поколіннями кочові племена Пусток вели запеклі сутички з Рамтаском і його розбійниками; його смерть — помста за полеглих воїнів."},sec={{t="Ветеран Пусток",b="Володар Рамтаск пережив десятиліття на одному з найкривавіших прикордонь Калімдору. Його товсту, мов дублена, шкуру перетинають глибокі шрами, здобуті в сутичках із загонами кентаврів, дикими гарпіями, орками-загарбниками й стійкими тауренськими воїнами. Похилий вік сповільнює багатьох бійців, але досвідчене чуття й фізична витривалість Рамтаска лише загартувалися, тож він керує постійним гарнізоном Рейзорфен Краула з непохитною владою."},{t="Командир Мертвої Голови",b="У звивистих терновиках Краула Рамтаск керує військовими силами шипогривів Мертвої Голови. Як їхній воєначальник, він тримає сувору дисципліну серед щетинистих бійців, що боронять святилище племені. В оточенні елітних стрільців Рамтаск б'ється, як берсерк на передовій: він ревом згуртовує своїх і завдає нищівних ударів об землю, що за лічені секунди можуть прорвати ворожий стрій."}},faq={{q="Хто такий Володар Рамтаск?",a="Володар Рамтаск — верховний воєначальник шипогривів Мертвої Голови в Рейзорфен Краулі. Це грізний, увесь у шрамах ветеран, що воював з усіма великими силами Пусток.",al={"хто такий рамтаск","лор рамтаска","володар рамтаск"}},{q="Де знайти Володаря Рамтаска?",a="Він командує своєю добірною охороною з тернового серця Рейзорфен Краулу на самому південному краю Пусток.",al={"місце рамтаска","де рамтаск","карта володаря рамтаска"}},{q="З якими ворогами Рамтаск воював у минулому?",a="Його вкрита шрамами шкура розповідає про незліченні сутички по всіх Пустках — із зграями кентаврів, гарпіями, що боронять свої землі, новоприбулими орками й місцевими захисниками-тауренами.",al={"вороги рамтаска","хто залишив шрами рамтаску","історія битв рамтаска"}},{q="До якого племені належить Рамтаск?",a="Він верховний воєначальник племені Мертвої Голови — панівної громади шипогривів, що закріпилася в Рейзорфен Краулі.",al={"фракція рамтаска","плем'я рамтаска","яке плем'я кабанів у рамтаска"}},{q="Чому шукачі пригод полюють на Рамтаска?",a="Як верховний командувач сил Мертвої Голови, Рамтаск, загинувши, завдає нищівного удару військовій ієрархії шипогривів і вносить цілковитий безлад у їхню оборону.",al={"чому вбивати рамтаска","завдання здолати їх","нагорода за рамтаска"}},{q="Як б'ється Рамтаск?",a="Рамтаск б'ється як справжній загартований воїн: деморалізаційними вигуками підбадьорює своїх, приголомшує ворогів нищівними ударними хвилями й діє злагоджено з добірними охоронцями-стрільцями.",al={"тактика рамтаска","стиль бою рамтаска","здібності рамтаска"}}},fp="16,302,22.450.0,29.397.0,24.190.0,36.120.0,44.164.0,34.121.0,39.181.0,23.192.0"}
P.entries["npc:ozzie-togglevolt"] = {n="Оззі Тоґлвольт",s="Оззі Тоґлвольт — гном-інженер, що пережив падіння Гномреґана, а тепер працює в засніженому селищі Харанос у Дун Мороґу. Переслідуваний трагедією, що спіткала його народ, він разом зі своїм напарником Раззлом Спрайспрокетом шукає ліки для опромінених гномів-прокажених.",h="Оззі Тоґлвольт — гном-інженер, що пережив падіння Гномреґана, а тепер працює в засніженому селищі Харанос у...",kw={"оззі тоґлвольт","гном","інженер","харанос","раззл спрайспрокет","гноми-прокажені"},ang={["faction:Alliance"]="Оззі, що працює в Хараносі під самим Айронфорджем, допомагає мандрівникам і підтримує присутність Альянсу на морозних пагорбах Дун Мороґу.",["profession:Engineering"]="Оззі показує, як гномське ремесло насправді тримається на спробах і помилках: пристрої можуть ефектно дати збій у бою або ж принести геніальний прорив у біохімічному знезараженні.",["race:Gnome"]="Для гномів-шукачів пригод Оззі уособлює горе й рішучість тих, хто вижив у Гномреґані й не збирається кидати опромінених родичів напризволяще."},sec={{t="Втеча з глибин",b="Оззі Тоґлвольт був серед підземних див Гномреґана, коли сталася катастрофа. Коли отруйні викиди пустили коридорами, щоб зупинити навалу трогів, Оззі стояв поруч зі своїм товаришем-гномом Ґноарном. Раптовий радіоактивний викид ударив просто в Ґноарна й назавжди змінив його на очах в Оззі. Хоч Оззі вибрався на поверхню живим і дістався прихистку в Дун Мороґу, жахливий спогад про ту катастрофу так і не покинув його."},{t="Майстерня в Хараносі",b="Тепер, оселившись у Хараносі, Оззі проводить дні за майструванням разом із Раззлом Спрайспрокетом. Попри дрібні негаразди й поспішну оборону від тролів Морозогривів, що підступають, їхня головна технічна й наукова справа лишається глибоко особистою: знайти спосіб скасувати жахливі мутагенні наслідки викидів у їхній утраченій домівці й вилікувати знедолених гномів-прокажених."}},faq={{q="Хто такий Оззі Тоґлвольт?",a="Оззі Тоґлвольт — гном-інженер, що живе в Хараносі в Дун Мороґу. Він утік від радіоактивного спустошення Гномреґана й тепер присвячує свій технічний хист пошукам ліків для своїх уражених побратимів.",al={"хто такий оззі","лор оззі тоґлвольта","гном оззі харанос"}},{q="Що намагається вилікувати Оззі?",a="Оззі разом зі своїм колегою Раззлом Спрайспрокетом шукає спосіб очистити від отруйного випромінювання, що перетворило стількох їхніх родичів на збожеволілих гномів-прокажених.",al={"що досліджує оззі","ліки для гномів-прокажених","ліки від гномів-прокажених"}},{q="Ким Ґноарн доводиться Оззі?",a="Ґноарн був з Оззі в Гномреґані, коли вирвалися отруйні викиди. Оззі бачив, як радіоактивний розряд влучив просто в Ґноарна, і цей трагічний випадок розпалив у ньому одержимість повернути зараження назад.",al={"оззі й ґноарн","що сталося з ґноарном","хто такий ґноарн"}},{q="Хто працює з Оззі в Хараносі?",a="Оззі працює разом із Раззлом Спрайспрокетом. Удвох вони майструють у Хараносі: розробляють суміші й збирають заражені зразки, щоб дослідити радіоактивні наслідки.",al={"напарник оззі","хто такий раззл","раззл спрайспрокет"}},{q="Чи допомагав Оззі боронити Харанос від тролів?",a="Так. Коли на Харанос напав величезний троль-морозогрив, Оззі й Раззл спробували відбитися, жбурляючи, як вони думали, ударні гранати, — і лише тоді з'ясували, що це бомби уповільненої дії, аж поки не втрутився їхній колега-винахідник Лазло Ґріндвіджет.",al={"оззі напад тролів","тролі фростмейн харанос","гранати оззі"}},{q="Які завдання дає Оззі?",a="Оззі залучає мандрівників у Дун Мороґу збирати заражені рештки й деталі довкола Гномреґана в завданнях на кшталт «Наступного дня», «Гноґаїн» і «Єдині ліки — ще більше зеленого сяйва».",al={"завдання оззі","завдання тоґлвольта","які завдання дає оззі"}}},fp="16,295,20.460.0,21.367.0,24.216.0,29.170.0,23.212.0,38.179.0,43.256.0,29.196.0"}
P.entries["npc:pao-ka-swiftmountain"] = {n="Пао'ка Свіфтмаунтін",s="Пао'ка Свіфтмаунтін — юний таурен-природознавець, що застряг серед диких віверн Високосіду в Тисячі Голок. Він прийшов на південь під проводом Мотеґи Фаєрмейна, але юнацька цікавість узяла гору: він підійшов надто близько до гніздовища й опинився загнаним у кут серед скель.",h="Пао'ка Свіфтмаунтін — юний таурен-природознавець, що застряг серед диких віверн Високосіду в Тисячі Голок.",kw={"пао'ка свіфтмаунтін","високосід","віверни","мотеґа фаєрмейн","застава білого рубежу","природознавець"},ang={["faction:Horde"]="Пао'ка — нове покоління тауренських дослідників, що вивчають Калімдор; урятувавши його, ви зміцните зв'язки зі старійшинами на Заставі Білого Рубежу.",["race:Tauren"]="Таурени глибоко шанують віверн як союзників і вірних їздових звірів, тож непродумане вторгнення Пао'ки — водночас і сором, і небезпека."},sec={{t="Природознавець у біді",b="Пао'ка прибув у край каньйонів Тисячі Голок разом із Мотеґою Фаєрмейном, прагнучи описати й вивчити небезпечних звірів цих ущелин. Батько неохоче відпускав сина в таку ризиковану мандрівку, і нещодавня пригода Пао'ки довела, що ці побоювання були недаремні. Зачарований величними вівернами Високосіду, юний дослідник прокрався гірською стежкою за самотнім тауренським тотемом. Звісно, звірі, що ревно бережуть свою територію, образилися на таке вторгнення й загнали його глибоко в кручі, де він опинився в пастці, наляканий до смерті, нездатний прослизнути повз хижаків, що пікірують з неба, й повернутися на Заставу Білого Рубежу."}},faq={{q="Хто такий Пао'ка Свіфтмаунтін?",a="Пао'ка — молодий таурен-учений, що супроводжував Мотеґу Фаєрмейна до Тисячі Голок вивчати місцевих тварин, але опинився в пастці віверн, що боронять свої гнізда на Високосіді.",al={"хто такий пао'ка","пао'ка свіфтмаунтін","хто таурен на високосіді"}},{q="Де знайти Пао'ку Свіфтмаунтіна?",a="Він застряг на вершині Високосіду в Тисячі Голок. Щоб дістатися до нього, треба знайти високий тауренський тотем біля круч: за ним вузька стежка піднімається схилом до гнізд віверн.",al={"де пао'ка","стежка високосіду","як знайти пао'ку"}},{q="Чому він ховається на Високосіді?",a="Захоплення вівернами завело його надто близько до одного з їхніх гнізд. Розлючені звірі прогнали його й відрізали шлях назад, тож кілька днів йому довелося ховатися.",al={"чому пао'ка в пастці","чому віверни напали на пао'ку"}},{q="Що стається, коли допомагаєш йому втекти?",a="Коли його безпечно виводять із гніздовищ, Пао'ка тікає назад до Мотеґи Фаєрмейна на Заставу Білого Рубежу, щиро сподіваючись, що наставник не розповість про його промах батькові.",al={"наслідок завдання шлях додому","чи пао'ка дістанеться додому"}}},fp="20,303,23.650.0,28.172.0,40.202.0,30.169.0,39.178.1"}
P.entries["npc:parqual-fintallas"] = {n="Парквал Фінталлас",s="Парквал Фінталлас — учений із Відступників, а за життя — людина, історик Лордерона, що нині мешкає в Апотекаріумі Андерсіті. Попри похмуре існування в нежитті, він зберіг ввічливу вдачу й незгасну пристрасть до давніх знань і часто допомагає мандрівникам, яких посилають до нього по глибокі знання з історії.",h="Парквал Фінталлас — учений із Відступників, а за життя — людина, історик Лордерона, що нині мешкає в...",kw={"парквал фінталлас","відступники","апотекаріум","андерсіті","випробування знань","лордерон"},ang={["faction:Horde"]="Коли шукачам пригод з Орди випадають випробування розуму, а не клинка, Парквал дає ту глибоку історичну мудрість, без якої не відкрити давніх істин Азероту.",["race:Undead"]="Парквал — рідкісне нагадування про інтелектуальне минуле королівства Лордерон: серед похмурості Апотекаріуму він тихо тримається за науку й вишукану розмову."},sec={{t="Учений утраченого Лордерона",b="За життя Парквал був шанованим ученим Лордерона, що знав про королівство все, що тільки можна знати, і з головою поринав в історичні тексти. Коли спалахнула чума нежиття, Парквал був серед багатьох городян, яких убило й підняло, — аж поки зрештою не вирвався на волю під проводом Леді Сильвани Віндраннер. Відступники здебільшого приймають холодний прагматизм і відвертаються від колишнього життя, але Парквал зберіг і пристрасть до науки, і приємні манери, тихо сумуючи за історичними томами й спогадами про світ, якого вже немає."},{t="Хранитель давніх знань",b="Парквал живе серед булькотливих чанів і алхіміків Апотекаріуму в Андерсіті. Попри моторошне оточення, він лишається безцінним джерелом знань про історію Азероту. Коли шукачі пригод беруться до суворих випробувань розуму, як-от до непростого «Випробування знань», їх скеровують до Парквала, а той посилає їх по книгу до бібліотеки Багряного Монастиря, а тоді ставить власне запитання."}},faq={{q="Де знайти Парквала Фінталласа?",a="Парквал Фінталлас стоїть в Апотекаріумі в Андерсіті — столиці Відступників під руїнами Лордерону.",al={"місце парквала","де парквал","парквал андерсіті"}},{q="Чим відомий Парквал Фінталлас?",a="За життя Парквал був знаним істориком, що знав про королівство Лордерон майже все. Навіть у нежитті він лишається знавцем, до якого звертаються шукачі пригод, що розшукують маловідомі історичні тексти й давні знання.",al={"хто такий парквал","що робить парквал","лор парквала фінталласа"}},{q="Чому Парквал бере участь у Випробуванні Знань?",a="Випробування Знань вимагає від шукачів пригод довести не лише силу, а й знання. Як учений, Парквал проводить одне з його випробувань: посилає їх до Багряного Монастиря по книгу «Зародження Загрози Нежиті», а потім ставить запитання про неї.",al={"парквал випробування знань","випробування знань андерсіті","завдання парквала фінталласа"}},{q="Чи Парквал такий самий неприязний, як більшість Відступників?",a="На відміну від багатьох озлоблених і цинічних Відступників, Парквал напрочуд лагідний і чемний. Він щиро тепло вітає шукачів пригод і зауважує, як приємно, коли хтось знаходить час із ним поговорити.",al={"чи парквал привітний","характер парквала"}}},fp="17,331,25.528.0,22.428.0,35.155.0,36.257.0,44.273.0,57.197.0"}
P.entries["npc:pelturas-whitemoon"] = {n="Пелтурас Вайтмун",s="Пелтурас Вайтмун — нічний ельф з Астранаару, батько маленької Релари, яку вразила страшна хвороба скверни. Відчайдушно прагнучи врятувати доньку, він разом із місцевим травником Орендилом Броудліфом та героями Альянсу збирає священні ліки в навколишніх нетрях. Пошуки зцілення для Релари ведуть шукачів пригод до найдавніших священних гаїв і руїн Ашенвалю.",h="Пелтурас Вайтмун — нічний ельф з Астранаару, батько маленької Релари, яку вразила страшна хвороба скверни.",kw={"пелтурас","вайтмун","релара","астранаар","озеро впалого неба","сльоза елуни","травництво"},ang={["class:Priest"]="Обряди очищення й священні інгредієнти, присвячені Елуні, показують ту цілющу силу й благоговіння, які Сестринство Елуни приносить у культуру нічних ельфів.",["faction:Alliance"]="Допомога Пелтурасові в порятунку доньки — ще одне свідчення того, що Альянс захищає поселення калдореїв на Калімдорі й дбає про них.",["profession:Herbalism"]="Ціла низка природних відварів, припарок і рослинних настоянок, потрібних Реларі, показує, як тісно медицина калдореїв пов'язана з травознавством.",["race:NightElf"]="Біда Пелтураса показує, наскільки вразливі звичайні родини калдореїв, коли давні галявини стають жертвою скверни й місцевих чвар."},sec={{t="Батьківське горе в Астранаарі",b="Пелтурас Вайтмун живе серед спокійного віття Астранаару тихим життям, звичним для лісових калдореїв, і часто ходить зі своєю маленькою донькою Реларою збирати мерехтливі місячні камені біля Озера Впалого Неба. Та коли Релара тяжко захворіла на загадкову недугу, його тихий світ обернувся відчаєм. Астранаар оточений ворогами з багатьох боків, але для Пелтураса ніщо в цьому великому лісі не важить більше, ніж порятунок дитини."},{t="Давні ліки та осквернені гаї",b="Звичайні трав'яні засоби Реларі не допомагають, і Пелтурас звертається до травника Орендила Броудліфа. Щоб здолати недугу, потрібні рідкісні священні інгредієнти, пов'язані з землею та Місячною Богинею, — зокрема Сльоза Елуни й мерехтливий зоряний пил із давніх руїн калдореїв, що має остудити її пекучий жар. Кожен крок лише ледь-ледь відганяє смерть, і це показує, як глибоко скверна, що розтікається ґрунтами й водами Ашенвалю, вже торкнулася його народу."},{t="Озеро Впалого Неба",b="Щоб остаточно повернути Реларі сили, Пелтурас шукає місячний камінь Оракула Тінявої Хащі біля Озера Впалого Неба. Озеро, колись тихе місце, де батько з донькою мирно збирали камінці, стало небезпечним, відколи там з'явилися люті осквернені болотяні звірі. Розтерши здобутий місячний камінь на цілющий чай, Пелтурас нарешті проганяє затяжну слабкість, і Релара одужує."}},faq={{q="Хто такий Пелтурас Вайтмун?",a="Пелтурас Вайтмун — нічний ельф, мешканець Астранаару в центрі Ашенвалю. Найбільше він відомий тим, що просить мандрівників Альянсу допомогти зібрати священні складники, щоб вилікувати його тяжко хвору доньку Релару.",al={"пелтурас","хто такий пелтурас вайтмун","пелтурас астранаар"}},{q="Що сталося з його донькою Реларою?",a="Релару вразила раптова тяжка хвороба, що спричиняє сильну гарячку й глибоку слабкість. Схоже, недуга пов'язана з неприродною скверною, що ширить дикими краями Ашенвалю: звичайні ліки її не беруть, і для очищення потрібні священні реагенти.",al={"хвороба релари","чому релара хвора","недуга релари"}},{q="Хто допомагає Пелтурасові лікувати хворобу?",a="Пелтурас радиться з Орендилом Броудліфом — обізнаним місцевим нічним ельфом, що призначає традиційні калдорейські ліки, зокрема очисні камені й трав'яні припарки.",al={"пелтурас травник","хто допомагає релері","орендил броудліф пелтурас"}},{q="Які реагенти потрібні, щоб вилікувати Релару?",a="Щоб урятувати Релару, потрібне поступове лікування: спершу трав'яний відвар від Орендила, потім очисна Сльоза Елуни, далі зоряний пил зі стародавніх руїн, щоб збити пекучу гарячку, і нарешті місячний камінь з Озера Впалого Неба, заварений на чай, щоб повернути їй сили.",al={"реагенти для ліків","складники ліків релари","чим лікувати релару"}},{q="Чим Озеро Впалого Неба важливе для Пелтураса?",a="Біля Озера Впалого Неба Пелтурас і Релара колись разом збирали місячні камені. Нещодавно озеро захопили ворожі болотяні чудовиська Тіньової Гущавини, тож Пелтурас просить шукачів пригод дістати місячний камінь, потрібний для одужання доньки.",al={"озеро впалого неба пелтурас","місячний камінь озеро впалого неба"}},{q="Чи належить Пелтурас до Кола Кенарія чи до Вартових?",a="Ні. Пелтурас — мирний мешканець Астранаару, один зі звичайних калдорейських родин, що живуть в Ашенвалі й потерпають від небезпек, які дедалі тісніше обступають ліс.",al={"чи пелтурас вартовий","роль фракції пелтураса"}}},fp="18,409,30.472.0,34.481.1,15.414.1,26.217.0,40.252.0,38.173.0,40.257.0,47.274.0,61.174.0"}
P.entries["npc:pilot-bellowfiz"] = {n="Пілот Беловфіз",s="Пілот Беловфіз, якого ласкаво звуть «Фіззером», — дворфійський водій, що служить на Складі Стілґрила в Дун Мороґу. Як член Облогової Бригади Айронфорджа, він відповідає за обслуговування й виведення в поле важких дворфійських бойових машин, зокрема власної облогової машини Джетстім.",h="Пілот Беловфіз, якого ласкаво звуть «Фіззером», — дворфійський водій, що служить на Складі Стілґрила в Дун...",kw={"пілот беловфіз","фіззер","джетстім","облогова бригада","склад стілґрила","облогова машина","дун мороґ"},ang={["profession:Engineering"]="Для дворфійських і гномських майстрів Беловфіз — вершина практичної польової інженерії: він тримає потужні облогові машини на ходу в крижаній гірській погоді.",["race:Dwarf"]="Беловфіз утілює гордість механізованих бригад Айронфорджа, показуючи інженерну майстерність і важку вогневу міць, що бережуть Каз Модан."},sec={{t="Володар Джетстіма",b="Пілот Беловфіз, що служить на Складі Стілґрила просто біля людних зал Айронфорджа, — механічний хребет дворфійського війська. Керуючи потужною облоговою машиною Джетстім, Беловфіз проводить дні, налаштовуючи деталі, добуваючи необхідні запчастини й тримаючи машину в бойовій готовності. Разом зі своїм товаришем Пілотом Стоунґіром Беловфіз без упину обговорює конструкції машин, броньові плити й потужність двигунів, пильнуючи, щоб механізована вогнева міць гірського королівства лишалася неперевершеною в усьому Каз Модані."}},faq={{q="Хто такий Пілот Беловфіз?",a="Пілот Беловфіз — дворф-пілот Облогової Бригади Айронфорджа. Він служить на Складі Стілґрила в Дун Мороґу, де обслуговує важкі облогові машини й керує ними для оборони Каз Модану.",al={"пілот беловфіз","фізер","хто такий фізер"}},{q="Якою машиною керує Беловфіз?",a="Він водить дворфійську облогову машину на ім'я Парострумінь. Він постійно поповнює її запасні частини, особливе спорядження й припаси для обслуговування, щоб вона працювала як годинник.",al={"танк беловфіза","джетстім","яка облогова машина в беловфіза"}},{q="Де знайти Пілота Беловфіза?",a="Ви знайдете його серед снігів на Складі Стілґрила — інженерному майданчику й місці збору трохи далі по дорозі на схід від Хараноса в Дун Мороґу.",al={"місце беловфіза","де пілот беловфіз","знайти беловфіза"}},{q="Що він робить разом із Пілотом Стоунґіром?",a="Беловфіз і Пілот Стоунґір — товариші-водії в Облоговій Бригаді. Коли не доглядають своїх машин, вони часто кепкують одне з одного й сперечаються про тонкощі будови облогових машин, броні й механіки.",al={"стоунґір і беловфіз","розмова беловфіза"}}},fp="15,281,22.539.0,23.194.0,34.176.0,35.144.0,37.204.0"}
P.entries["npc:pilot-hammerfoot"] = {n="Пілот Гаммерфут",kw={"пілот гаммерфут","облогова бригада","гільдельве","дробкіготь","застава північної брами","помста","лох модан"},ang={["faction:Alliance"]="Допомога Гаммерфуту убезпечує важливі розвідувальні застави вздовж головного шляху, що з'єднує Дун Мороґ і Лох Модан.",["race:Dwarf"]="Гаммерфут утілює люте побратимство горян Айронфорджа, які не дозволять, щоб убивство полеглого брата лишилося без відповіді."},sec={{t="Очі в горах",b="Облогові машини Айронфорджа — гордість його Облогової Бригади, але вести їх суворою гірською місцевістю вкрай ризиковано. Пілот Гаммерфут, що служить на Заставі Північної Брами над кордоном між Дун Мороґом і Лох Моданом, стереже машини пілотів і пильнує гірські перевали. Коли пілот зникає, знайти його швидко стає першочерговою справою — особливо коли довколишніми пагорбами никають дикі звірі."},{t="Помста за товариша",b="Гаммерфут був близьким другом Пілота Морі Гільдельве, побратима-пілота облогової машини, який розбив свою машину на крутому схилі, коли двоє шукали рідкісну руду, а тоді пішов далі сам пішки. Дізнавшись, що Гільдельве на смерть пошматував Дробкіготь, величезний крижанокігтий ведмідь, Гаммерфут змінює буденну прикордонну варту на особисту помсту, вимагаючи відплати звірові, винному в смерті його друга."}},faq={{q="Хто такий Пілот Гаммерфут?",a="Пілот Гаммерфут — дворф, пілот облогової машини на службі Айронфорджа. Він служить на Заставі Північної Брами на перевалі між Дун Мороґом і Лох Моданом, стежить за кордонами краю й за своїми товаришами-пілотами.",al={"лор гаммерфута","хто такий гаммерфут","про пілота гаммерфута"}},{q="Де знайти Пілота Гаммерфута?",a="Він на Заставі Північної Брами, при гірському шляху, що стереже тунельний перевал між Дун Мороґом і Лох Моданом.",al={"місце гаммерфута","де пілот гаммерфут","де гаммерфут"}},{q="Що сталося з напарником Гаммерфута, Пілотом Гілделвом?",a="Pilot Mori Hildelve broke his siege engine on a steep hill while searching for rare ore and continued on foot. Hammerfoot has not heard from him and asks travelers to investigate.",al={"доля пілота гілделва","що сталося з гілделвом","смерть гілделва"}},{q="Why is Hammerfoot worried about his partner?",a="Hammerfoot and Mori Hildelve are close friends and fellow Siege Brigade pilots. Hildelve has gone missing in dangerous mountain terrain, and Hammerfoot needs someone to discover what happened.",al={"чому помста пілота","чому мстити за гілделва","образа на манджкло"}}},fp="16,337,21.428.0,18.424.1,24.215.0,36.132.0,54.179.0,44.192.0"}
P.entries["npc:pilot-longbeard"] = {n="Пілот Лонґбірд",s="Пілот Лонґбірд — дворф, пілот облогової машини з Облогової Бригади Айронфорджа, що служить у Залі Зброї у Військовому Кварталі Айронфорджа. Хоча його пост — у гірському місті, він підтримує тісні зв'язки з гномськими майстрами й іншими шанувальниками польотів, що працюють далеко в Мерехтливих Низинах.",h="Пілот Лонґбірд — дворф, пілот облогової машини з Облогової Бригади Айронфорджа, що служить у Залі Зброї у...",kw={"пілот лонґбірд","облогова бригада айронфорджа","зала зброї","айронфордж","брати брассболтс","облогові машини"},ang={["profession:Engineering"]="Як пілот облогової машини, що має знайомих серед гномських майстрів, Лонґбірд цінує механічну винахідливість, без якої машини не працюватимуть і не мчатимуть.",["race:Dwarf"]="Пілот Лонґбірд — утілення дворфійського духу пригод: він поєднує традиційну військову службу Айронфорджа із захватом від облогових машин і гномської механіки."},sec={{t="Пілот Облогової Бригади",b="Серед бойових експозицій і зброярів Військового Кварталу Айронфорджа Пілот Лонґбірд представляє горді облогові частини Каз Модану. Служба тримає його в місті-фортеці, але Лонґбірд завжди уважно дослухається до новинок і звісток від колег-механіків з усього світу — зокрема від братів Брассболтс, що майструють на солончаках Калімдору."},{t="Зв'язки між континентами",b="Лонґбірд — зв'язковий для відчайдушних мандрівників, що прямують на південь, до Калімдору. Він часто скеровує перспективних новобранців і гінців до Мерехтливих Низин у Тисячі Голок, де гномські винахідники розсувають межі механіки поряд зі своїми суперниками-гоблінами."}},faq={{q="Де знайти Пілота Лонґбірда?",a="Він у Залі Зброї у Військовому Кварталі Айронфорджа, неподалік від наставників і військових експонатів.",al={"місце пілота лонґбірда","де лонґбірд айронфордж","як знайти пілота лонґбірда"}},{q="Яка роль Пілота Лонґбірда?",a="Пілот Лонґбірд дає завдання й спрямовує шукачів пригод Альянсу в далекі мандри, зокрема зводить мандрівників зі своїми друзями, братами Брассболтсами, у Тисячі Голок.",al={"що робить лонґбірд","завдання пілота лонґбірда","чому говорити з лонґбірдом"}},{q="Ким брати Брассболтси доводяться Лонґбірдові?",a="Це гноми-майстри й соратники Лонґбірда, що працюють у Мерехтливих Низинах; їх пов'язує спільна пристрасть до інженерії й дослідних машин.",al={"зв'язок із брассболтсами","чому лонґбірд знає брассболтса","лонґбірд мерехтлива глибина"}},{q="Чи Пілот Лонґбірд родич Фурена Лонґбірда?",a="Обидва носять відоме в Айронфорджі родове ім'я Лонґбірд, що натякає на спорідненість у клані, хоча Пілот Лонґбірд зосереджений на облогових машинах та інженерних зв'язках, а не на ковальстві.",al={"фурен лонґбірд брат","рід лонґбірд дворф","чи він родич фурена"}}},fp="15,300,28.385.0,29.278.0,33.122.0,31.191.0,45.159.0,46.181.0"}
P.entries["npc:pilot-stonegear"] = {n="Пілот Стоунґір",s="Пілот Стоунґір, на прізвисько «Стоун», — дворф, механік і водій Облогової Бригади Айронфорджа, що служить на Складі Стілґрила. Він керує грізною облоговою машиною Троллплоу й невтомно працює, щоб поліпшити її хід і броню. Шукачі пригод, що мандрують Дун Мороґом, часто допомагають йому добувати рідкісні матеріали, щоб його бойова машина лишалася боєздатною.",h="Пілот Стоунґір, на прізвисько «Стоун», — дворф, механік і водій Облогової Бригади Айронфорджа, що служить на...",kw={"пілот стоунґір","стоун","троллплоу","облогова бригада","склад стілґрила","облоговий танк","механік"},ang={["profession:Engineering"]="Інженери оцінять відданість Стоунґіра польовим доробкам Троллплоу, що врівноважують убивчу бойову ефективність з ергономікою для пілота.",["profession:Mining"]="Шахтарі постачають життєво важливі сирі руди й нестабільні підземні поклади, які потрібні Стоунґіру, щоб кувати посилене обшиття й боєприпаси.",["race:Dwarf"]="Стоунґір утілює дворфійську любов до важкої сталі, ревучих двигунів і трощення гірських ворогів під масивними залізними гусеницями.",["race:Gnome"]="Гноми, що працюють разом з Облоговою Бригадою, знаходять у Стоунґірі споріднену душу: він завжди радо майструє експериментальні конструкції й підвищує віддачу."},sec={{t="Володар Троллплоу",b="Серед гуркітливих котлів і брязкітливих гусениць Складу Стілґрила Пілот Стоунґір служить Айронфорджу як гордий водій Облогової Бригади. Його гордість і радість — Троллплоу, важкий облоговий танк, збудований, щоб трощити ворожі лави. Стоунґір ставиться до своєї машини серйозно, знаючи: у запалі бою життя водія цілком залежить від міцності шестерень, плит і тиску пари. Він невпинно шукає, як підвищити й бойову ефективність Троллплоу, і повсякденну придатність до життя його тісної кабіни."},{t="Винахідництво й металургія",b="Як і багато дворфійських та гномських механіків на складі, Стоунґір рідко вдовольняється заводськими характеристиками. У вільний час він часто сперечається про інженерні схеми з товаришами на кшталт Пілота Беловфіза й Пілота Гаммерфута. Чи то женучись за чутками про екзотичні руди, чи то вистежуючи нестабільні мінерали для посиленого обшиття й боєприпасів, Стоунґір покладається на завзятих новобранців, які вирушать у засніжену пустку й небезпечні печери Дун Мороґу по припаси."}},faq={{q="Хто такий Пілот Стоунґір?",a="Пілот Стоунґір, якого часто кличуть просто «Камінь», — дворф з Айронфорджа й член Облогової Бригади Айронфорджа. Він служить на Складі Стілґрила в Дун Мороґу, де обслуговує свою облогову машину Тролеплуг і керує нею.",al={"лор пілота стоунґіра","хто такий стоунґір","пілот стоун"}},{q="Де перебуває Пілот Стоунґір?",a="Стоунґір — одразу за Хараносом, на Складі Стілґрила в Дун Мороґу, серед облогових танків, запасних частин і товаришів-пілотів.",al={"місце пілота стоунґіра","де стоунґір","знайти стоунґіра"}},{q="Що таке Тролеплуг?",a="Тролеплуг — особиста облогова машина Пілота Стоунґіра. Він постійно вдосконалює її механічну надійність, броню й зручність усередині, щоб вона витримала жорсткі вимоги бою на передовій.",al={"що таке тролеплуг","танк тролеплуг","танк стоунґіра"}},{q="Навіщо Стоунґірові шукачі пригод?",a="Стоунґір залучає мандрівників розвідувати загрози поблизу й збирати рідкісні мінерали — як-от інцендицитову руду, — щоб удосконалювати й обслуговувати важку бойову техніку Облогової Бригади.",al={"завдання пілота стоунґіра","навіщо стоунґіру завдання","пошуки стоунґіра"}},{q="З ким працює Пілот Стоунґір?",a="Він служить в Облоговій Бригаді Айронфорджа разом з іншими знаними водіями, як-от Пілотом Беловфізом і Пілотом Гаммерфутом, і часто сперечається з ними на складі про механічні вдосконалення й будову машин.",al={"друзі стоунґіра","пілоти облогової бригади","беловфіз і стоунґір"}},{q="Що таке Облогова Бригада Айронфорджа?",a="Облогова Бригада Айронфорджа — механізований броньований підрозділ дворфійського війська. Із паровими танками, облоговими машинами й важкою артилерією вона дає бронепідтримку обороні Дун Мороґу й несе військову міць Айронфорджа по всьому Каз Модану.",al={"облогова бригада айронфорджа","лор облогової бригади","дворфійська танкова бригада"}}},fp="15,364,23.524.0,24.475.0,23.221.0,33.138.0,22.211.0,41.175.0,35.200.0,36.252.0"}
P.entries["npc:pixel"] = {n="Піксель",s="Піксель — заповзятлива гоблінка-кур'єрка, що працює на Заставі Розщепленого Дерева в Ашенвалі. Вона заробляє на життя, доставляючи важкі вантажі через небезпечні землі, і возить для місцевих сил Орди такі речі, як пиляльні леза Бойової Пісні, — хоча жоден вантаж не віддає без належної плати.",h="Піксель — заповзятлива гоблінка-кур'єрка, що працює на Заставі Розщепленого Дерева в Ашенвалі.",kw={"піксель","гобліни","кур'єрка","застава розщепленого дерева","бойова пісня","роги сатирів"},ang={["faction:Horde"]="Для звитяжців Орди, що борються за опору в Ашенвалі, Піксель постачає промислове обладнання, без якого клан Бойової Пісні не втримав би в роботі свої лісорубні машини."},sec={{t="Справи в глибокому лісі",b="Застава Розщепленого Дерева — укріплений оплот Орди посеред ворожих хащів Ашенвалю, але Піксель думає передусім про зиск. Як незалежна кур'єрка, готова возити вантажі в саме пекло бойових дій, вона забезпечує важливе постачання для лісозаготівель клану Бойової Пісні. Та, як і годиться гоблінам, її співпрацю визначають угоди й монета. Вона притримує доставлене, доки замовник не заплатить, і часто вимагає від перехожих шукачів пригод практичної винагороди — як-от рогів сатирів, — перш ніж віддати цінне лісорубське приладдя."}},faq={{q="Хто така Піксель?",a="Піксель — гоблінка, вільна кур'єрка, що зупинилася на Заставі Розщепленого Дерева на сході Ашенвалю. Вона заробляє, перевозячи вантажі небезпечними землями, а зараз відає партією пилок, без яких не обійтися лісозаготівлі Пісні Війни в цьому краї.",al={"хто ця гоблінка","лор піксель","гоблінка сплінтертрі"}},{q="Чому Піксель не віддає пилки одразу?",a="Як і кожна кмітлива гоблінка, Піксель живе за законами ділу. Хоч би як Орді в Ашенвалі пекло, вона не віддасть свого вантажу пилок без належної плати чи товару, що покриє її винагороду.",al={"чому піксель просить плату","доставка пилок співу війни","завдання пилок"}},{q="Навіщо їй роги сатирів?",a="Піксель приймає як плату чи заставу цінні трофеї з місцевих лісів, як-от роги сатирів. Сатирів в Ашенвалі сила-силенна, і вони ворожі, тож їхні роги — знаний і вигідний товар для торговця, готового на обмін.",al={"навіщо роги сатирів","піксель сатири","завдання сатирів сплінтертрі"}},{q="Чи Піксель офіційно належить до Орди?",a="Піксель тісно співпрацює з Ордою на Заставі Розщепленого Дерева завдяки вигідним угодам із лісозаготівлею Пісні Війни, але найбільше вона вірна торгівлі, зискові й виконанню своїх угод про доставку.",al={"чи піксель з орди","фракція піксель","чи піксель нейтральна"}}},fp="5,298,26.566.0,13.235.0,53.220.0,30.237.0,42.207.0"}
P.entries["npc:piznik"] = {n="Пізнік",s="Пізнік — незадоволений гоблін-розвідник надр, що ховається глибоко в Шахті Зрізаного Вітру в Горах Кам'яного Кігтя. Колись високопоставлений наглядач на місцевих роботах Венчурної Компанії, він був відсунутий безжальним Ґерензо Ренчвіслом. Тепер, плекаючи образу, Пізнік таємно збирає відомості, щоб підточити свого колишнього роботодавця.",h="Пізнік — незадоволений гоблін-розвідник надр, що ховається глибоко в Шахті Зрізаного Вітру в Горах Кам'яного...",kw={"пізнік","шахта зрізаного вітру","ґерензо ренчвісл","зіз фіззікс","венчурна компанія","гобліни"},ang={["profession:Mining"]="Рудокопи, що проходять Шахтою Зрізаного Вітру, зустрінуть Пізніка — живий приклад того, як стрімко може обвалитися посада під вагою корпоративної жадібності."},sec={{t="Падіння з висоти",b="Доки Ґерензо Ренчвісл не захопив верховну владу над Кручею Вітрорізу, Пізнік мав завидне звання заступника керівника всієї справи. Та корпоративні перебудови у Венчурній Компанії безжальні. Щойно Ґерензо взяв усе під контроль, Пізніка відсунули й заслали в похмурі глибини Шахти Зрізаного Вітру. Не змирившись тихо з пониженням, Пізнік вичікує під землею, пильно стежить за всім, що діється в шахті, і тихцем замишляє помсту начальникові, що його понизив."},{t="Корпоративне шпигунство",b="Тихий бунт Пізніка набув практичного вигляду завдяки союзу із Зізом Фіззіксом — агентом, що діє ззовні й якого Ґерензо так само вигнав. Як Зізова людина всередині, Пізнік збирає все, що може, про задуми Ґерензо. Винісши зразок загадкової золотаво-зеленої руди, яку Ґерензо наказав видобувати у великих кількостях, і переславши його Зізові, Пізнік із тіні зриває вирубку й видобуток Венчурної Компанії, щоб честолюбне керівництво Ґерензо раз у раз натикалося на болісні невдачі."}},faq={{q="Де знайти Пізніка?",a="Пізнік захований у Шахті Зрізаного Вітру — системі печер, вирубаних у схилах Кручі Вітрорізу в Горах Кам'яного Кігтя. Ви знайдете його глибоко в тунелях серед робітників Венчурної Компанії.",al={"місце пізніка","де пізнік","знайти пізніка в стоунталоні"}},{q="Що Пізнік має проти Ґерензо Ренчвісла?",a="Колись Пізнік був другим за владою на Кручі Вітрорізу. Коли Ґерензо Ренчвісл узяв повний контроль над лісозаготівлею й видобутком, він понизив Пізніка, і колишній наглядач затаїв образу й мріє побачити Ґерензо зруйнованим.",al={"чому пізнік ненавидить ґерензо","ворожнеча пізніка й ґерензо"}},{q="Яке місце Пізнік посідає в задумах Зіза Фіззікса?",a="Зіза Фіззікса Ґерензо просто звільнив, а Пізніка лише понизив. Пізнік користується тим, що досі має доступ углиб Шахти Зрізаного Вітру, і стає інформатором: збирає чутки про задуми Ґерензо й передає Зізові зразок загадкової руди, яку Ґерензо наказав видобувати.",al={"пізнік і зіз","з ким працює пізнік"}},{q="Чи Пізнік досі вірний Венчурній Компанії?",a="Лише на папері. Хоча він досі вдає працівника Венчурної Компанії, щоб лишатися в шахті, по-справжньому Пізнік вірний тільки власній вигоді й бажанню насолити Ґерензо.",al={"чи пізнік венчурна компанія","фракція пізніка"}}},fp="6,315,17.529.0,19.532.1,24.212.0,54.240.0,44.276.0,45.201.0"}
P.entries["npc:pozzik"] = {n="Поззік",s="Поззік — шанований гоблін-майстер і гонщик на Перегонах Міражу в Мерехтливих Низинах, що в Тисячі Голок. Колись один із найповажніших інженерів Андермайну, тепер він віддає свій технічний геній створенню експериментальних ракетних автомобілів і остаточному розв'язанню суперечки з колегою-гномом про те, чия інженерія краща.",h="Поззік — шанований гоблін-майстер і гонщик на Перегонах Міражу в Мерехтливих Низинах, що в Тисячі Голок.",kw={"поззік","перегони міражу","андермайн","ракетні автомобілі","фіззл брассболтс","гобліни-інженери"},ang={["profession:Engineering"]="Для інженерів обох шкіл — гоблінської чи гномської — Поззік уособлює абсолютну вершину ризикованої, надшвидкісної прикладної механіки.",["race:Gnome"]="Гноми, що завітають на трасу, знайдуть у Поззікові свого улюбленого суперника — галасливого гобліна-інженера, переконаного, що груба тяга переважить тонку точність."},sec={{t="Майстер з Андермайну",b="Перш ніж осісти на суворих солончаках Тисячі Голок, Поззік здобув легендарну славу на острові Кезан. Як один із найповажніших майстрів Андермайну, він тямить і в складних двигунах внутрішнього згоряння, і в рушійних системах, і в будові небезпечних шасі. Та замість того щоб тихо доживати в затишній безвісті, Поззік забрав свою механічну майстерність у пустелю, щоб гнати швидкісні машини далеко за межу їхньої міцності."},{t="Двобій на солончаках",b="На Перегонах Міражу Поззік об'єднав зусилля зі своїм вічним колегою-гномом, Фіззлом Брассболтсом. Попри давнє суперництво гоблінської вибухівки й тонкого гномського калібрування, вони разом проклали розлогу трасу висохлим дном озера. Обидва виставляють суперницькі гоночні команди й випробовують прототипи ракетних автомобілів, щоб остаточно довести, чия расова філософія конструювання панує на трасі. Звісно, Поззік завжди шукає кмітливих шукачів пригод, готових роздобути деталі й полегшити його машини."}},faq={{q="Хто такий Поззік?",a="Поззік — досвідчений гоблін-майстер, родом з Андермайну, що тепер очолює одну зі сторін змагань ракетних автомобілів на Перегонах Міражу в Тисячі Голок.",al={"поззік","хто такий поззік","лор поззіка"}},{q="Що Поззік робить у Тисячі Голок?",a="Залишивши офіційну роботу в Андермайні, Поззік перебрався до Мерехтливих Низин, щоб будувати дослідні ракетні автомобілі й ганяти на них неозорими рівними соляними низинами.",al={"чому поззік тут","поззік мерехтливі низини"}},{q="Які в нього стосунки з Фіззлом Брассболтсом?",a="Фіззл Брассболтс — давній суперник Поззіка, гном, і співзасновник траси. Хоча вони пліч-о-пліч підтримують Перегони Міражу, вони постійно змагаються, щоб довести, що гоблінська інженерія краща за гномську майстерність.",al={"поззік і фіззл","суперник-гном поззіка"}},{q="Поззік працює на Орду чи на Альянс?",a="Поззік цілком нейтральний: він незалежний гоблін-підприємець на трасі. Він охоче має справи й дає доручення мандрівникам і з Альянсу, і з Орди.",al={"чи поззік нейтральний","фракція поззіка"}},{q="Над чим зараз працює Поззік?",a="Поззік одержимий тим, щоб вичавити зі своїх ракетних автомобілів іще більше швидкості. Він розробляє багатодвигунні перегонові шасі, збирає рідкісні легкі руди й посилає шукачів пригод по вживані деталі й складники.",al={"завдання поззіка","що будує поззік"}}},fp="6,347,21.449.0,26.542.0,14.157.0,38.167.0,48.234.0,47.172.0,53.199.0"}
P.entries["npc:priestess-a-moora"] = {n="Жриця А'мура",s="Жриця А'мура — побожна служителька Богині Місяця з-поміж нічних ельфів, що живе в Храмі Місяця в Дарнасусі. Вона служить під проводом жрецтва Верховної Жриці Тіранди Віспервінд і дбає про обряди духовного очищення та єднання з Елуною. Мандрівників, що досліджують Тельдрассил, часто скеровують до неї, коли йдеться про священні пожертви й таємничих звірів гілля.",h="Жриця А'мура — побожна служителька Богині Місяця з-поміж нічних ельфів, що живе в Храмі Місяця в Дарнасусі.",kw={"жриця а'мура","храм місяця","елуна","леді сатра","сестринство елуни","дарнасус","тіранда віспервінд"},ang={["class:Priest"]="Жерці, що ходять залами Храму Місяця, можуть побачити в А'мурі приклад щирого служіння, що поєднує храмовий обряд зі світом природи за міською брамою.",["faction:Alliance"]="Жриця А'мура допомагає мандрівникам Альянсу, що досліджують священне серце Дарнасуса, і знайомить їх зі священними звичаями Сестринства Елуни.",["race:NightElf"]="Для нічних ельфів Жриця А'мура уособлює одвічні традиції шанування Елуни, що пов'язують молоде гілля Тельдрассилу з давньою духовною спадщиною їхнього народу."},sec={{t="Служителька Елуни",b="У спокійних мармурових залах Храму Місяця Жриця А'мура проводить дні в спогляданні й служінні. Як висвячена жриця Елуни, вона допомагає дбати про духовні потреби Дарнасуса й берегти тонкі обряди, що передаються тисячоліттями. Багато сестер опікуються військовою обороною чи дипломатією, а А'мура зосереджується на традиційних молитвах і священних справах, пов'язаних із духами природи Тельдрассилу."},{t="Сльози Місяця",b="А'мура пов'язана із сумною долею Леді Сатри — великої павучихи, колись улюбленої Елуною, чию сріблясту росу зберігали в храмі за цілющу силу. Коли Сатра поринула в безумство, А'мура послала молодих шукачів пригод на північні околиці Тельдрассилу, до Озера Джерела, щоб припинити її страждання й принести її сріблясті павутинні залози. Піднесені біля храмового фонтана, залози стають жертвою Елуні, щоб Сатра могла відродитися в спокої."}},faq={{q="Де знайти Жрицю А'муру?",a="Жриця А'мура — у Храмі Місяця в Дарнасусі, столиці у верхівці Тельдрассила. Вона стоїть серед жриць, що служать біля вівтаря Елуни.",al={"місце а'мури","де жриця а'мура","а'мура дарнас"}},{q="Яка роль Жриці А'мури в Дарнасусі?",a="Вона з Сестринства Елуни й відає певними релігійними обрядами та священними жертвами. Вона дає завдання й наставляє мандрівників, які прагнуть виконати давні обряди очищення й жертвоприношення на Тельдрассилі.",al={"що робить а'мура","мета жриці а'мури"}},{q="Які завдання дає Жриця А'мура?",a="Вона дає ланцюжок завдань «Сльози Місяця»: посилає шукачів пригод убити збожеволілу павучиху Леді Сатру біля Озера Джерела, а потім принести її сріблясті павутинні залози в жертву біля фонтана храму.",al={"завдання а'мури","ланцюжок завдань жриці а'мури"}},{q="Що пов'язує Жрицю А'муру з Храмом Місяця?",a="Вона служить у Храмі Місяця — духовному серці культури нічних ельфів, яким править Верховна Жриця Тіранда Віспервінд. А'мура допомагає вести духовне навчання й обрядові служіння під дахом храму.",al={"чи а'мура з храму","сестринство елуни а'мура"}},{q="Хто така Сатра і чому А'мура про неї говорить?",a="Леді Сатра — велика павучиха, колись улюблениця Елуни, що живе на північних межах Тельдрассила біля Озера Джерела. Вона збожеволіла, тож А'мура просить шукачів пригод покласти край її стражданням і принести її павутинні залози в жертву Елуні, щоб вона могла відродитися в спокої.",al={"жертва сатри","хто така сатра"}},{q="Чи належить А'мура до Альянсу?",a="Так. Як жриця нічних ельфів зі столиці Дарнасус, вона цілком на боці Альянсу й не допомагатиме членам Орди та не даватиме їм завдань.",al={"чи а'мура з альянсу","чи орда може говорити з а'мурою"}}},fp="17,418,18.455.0,17.456.0,35.187.0,46.232.0,41.205.0,59.238.0,50.268.0,36.181.0"}
P.entries["npc:priestess-alathea"] = {n="Жриця Алатея",s="Жриця Алатея — наставниця жерців серед нічних ельфів, що служить у тихих залах Храму Місяця в Дарнасусі. Віддана Місячній Богині, вона навчає послушників священних мистецтв і особливих благословень, якими Елуна обдаровує свій народ. Її наука допомагає нічним ельфам налаштувати розум на захисні молитви й небесну магію.",h="Жриця Алатея — наставниця жерців серед нічних ельфів, що служить у тихих залах Храму Місяця в Дарнасусі.",kw={"алатея","жриця","жрець","храм місяця","елуна","дарнасус","сестринство елуни"},ang={["class:Priest"]="Для жерців Альянсу, що навідуються до Дарнасуса, Жриця Алатея — важлива наставниця: вона навчає вищих рангів заклять і веде калдорейських послушників до їхніх особливих небесних сил.",["faction:Alliance"]="Алатея відкриває науку Храму Місяця всім мандрівникам з Альянсу, які вивчають жрецьке мистецтво.",["race:NightElf"]="Алатея служить у самому серці Дарнасуса й уособлює живі духовні традиції Сестринства Елуни, що тисячоліттями оберігали калдореїв."},sec={{t="Служіння в Храмі Місяця",b="Під високими срібними склепіннями найвеличнішого святилища Дарнасуса Жриця Алатея служить Сестринству Елуни як наставниця й духовна провідниця. Коли молоді нічні ельфи виростають із тихого затінку Тінедолу, їх скеровують до Храму Місяця, щоб поглибити їхній завіт із Богинею. Алатея — серед жриць, готових передати священне знання тим, хто присвячує життя зціленню, захисту й божественному світлу."},{t="Благословення Білої Леді",b="Жерці Святого Світла черпають силу з людських і дворфійських традицій, а калдорейські жерці звертаються просто до ласки Елуни. Алатея відіграє тут ключову роль: випробовує нічних ельфів і дарує їм благословення, призначені саме для їхнього народу, як-от Зорі Елуни та Благодать Елуни. Під її проводом послушники вчаться вплітати зоряне світло в щити, що дарують швидкість і захисну міць, — аби вижити серед дедалі більших небезпек Калімдору."}},faq={{q="Хто така Жриця Алатея?",a="Жриця Алатея — калдорейська наставниця жерців у Храмі Місяця в Дарнасусі, що навчає молодих жерців і проводить послушниць нічних ельфів через священні випробування.",al={"хто така алатея","алатея дарнас","тренер жерців алатея"}},{q="Яких умінь вона навчає?",a="Вона навчає звичайних жрецьких заклинань, а також проводить особливі випробування на расові вміння нічних ельфів — Зоряні Уламки й Благодать Елуни, — що черпають пряму силу й захист Богині Місяця.",al={"вміння алатеї","закляття алатеї","закляття жерців дарнас"}},{q="Де знайти Жрицю Алатею?",a="Вона на першому поверсі Храму Місяця на півдні Дарнасуса, серед сяйливих вод святилища й інших жриць.",al={"де алатея","місце алатеї"}},{q="Чому жерці нічних ельфів приходять саме до неї?",a="Коли калдорейські жерці зростають у навчанні, наставники-новачків по всьому Тельдрассилу посилають їх до Алатеї проходити духовні обряди — як-от Зорі Елуни й Благодать Елуни, — що знаменують їхнє становлення як зрілих служителів богині.",al={"завдання жерців алатея","завдання зірок елуни"}},{q="Чи навчає вона інші народи, крім нічних ельфів?",a="Так. Хоча люди й дворфи-жерці належать до Церкви Святого Світла, будь-який жрець Альянсу, що прибуде до Дарнасуса, може вивчити в неї загальні заклинання, але суто калдорейські расові випробування вона проводить лише для нічних ельфів.",al={"чи люди навчаються в алатеї","дворф-жрець алатея"}},{q="Чим її віра відрізняється від віри людей і дворфів-жерців?",a="Жерці Стормвінда й Айронфорджа закликають розлите в усьому, філософське Святе Світло, а Алатея та її сестри шанують Елуну як живу богиню й поряд із цілющою магією володіють зоряним сяйвом і місячними оберегами.",al={"елуна проти священного світла","лор жерців нічних ельфів"}}},fp="17,336,34.465.0,27.429.0,25.201.0,30.198.0,35.165.0,48.240.0,44.226.0,57.212.0"}
P.entries["npc:priestess-anetta"] = {n="Жриця Анетта",s="Жриця Анетта — людська клірикиня Святого Світла, що служить в Абатстві Нортшира. Як член Братства Нортшира, вона доглядає поранених учнів і навчає новоприбулих жерців їхніх перших священних обрядів.",h="Жриця Анетта — людська клірикиня Святого Світла, що служить в Абатстві Нортшира.",kw={"жриця анетта","жрець","святе світло","абатство нортшира","цілителька","наставниця"},ang={["class:Priest"]="Для молодих людей-жерців, що починають у Нортширі, Жриця Анетта — ваша найперша наставниця: вона підтверджує ваше святе покликання й учить спілкуватися зі Світлом напряму.",["faction:Alliance"]="Анетта втілює незмінне духовне осердя Альянсу: вона дбає, щоб новобранці, поранені на захисті Долини Нортширу, вижили й продовжили боротьбу."},sec={{t="Опікунка вірних",b="Жрицю Анетту можна знайти на першому поверсі Абатства Нортшира, у його тихому бібліотечному крилі. Серед загрози бандитів Дефіас і кобольдів, що турбують долину, Анетта невтомно доглядає поранених новобранців, яких приносять з поля. Вона — опора Братства Нортшира: дбає, щоб ті, хто б'ється за абатство, відновлювалися тілом і духом милістю Святого Світла."},{t="Настанова жерцям-новачкам",b="Окрім обов'язків польової цілительки в обителі, Анетта — головна наставниця людей-жерців-початківців. Новачки, що приходять з освяченим листом-рекомендацією, шукають її, щоб опанувати основи віри: спрямовувати святі слова на зцілення плоті й випускати караюче сяйво, щоб відганяти зло. Під її проводом молоді послушники готуються нести Світло за усамітнені стіни Нортширу."}},faq={{q="Хто така Жриця Анетта?",a="Жриця Анетта — наставниця жерців і цілителька з Братства Нортшира. Вона живе на першому поверсі Абатства Нортшира, у крилі бібліотеки, де допомагає пораненим воякам і наставляє жерців-новачків.",al={"хто така анетта","лор жриці анетти","жриця анетта нортшир"}},{q="Де знайти Жрицю Анетту?",a="Вона в Абатстві Нортшира на півночі Лісу Елвінн. Увійдіть у головну браму абатства, пройдіть до головної зали й пошукайте на першому поверсі в крилі бібліотеки.",al={"де жриця анетта","місце анетти","знайти анетту"}},{q="Яку роль вона відіграє в обороні Абатства?",a="Поки маршали й новобранці Стормвінда відвойовують долину в бандитів Дефіас і кобольдів, Анетта надає їм життєво важливу медичну допомогу. Вона лікує поранених новобранців, яких приносять до абатства, і закликає Світло, щоб загоїти їхні рани.",al={"що робить анетта","роль анетти"}},{q="Чого вона навчає?",a="Анетта навчає молодих жерців перших жрецьких заклинань і молитов — основ зцілення й ураження ворогів в ім'я Святого Світла.",al={"чи анетта навчить заклять","закляття жерців анетти"}}},fp="16,228,22.438.0,22.405.0,24.230.0,34.179.0,47.237.0,29.171.0"}
P.entries["npc:priestess-josetta"] = {n="Жриця Джозетта",s="Жриця Джозетта — людська наставниця жерців на верхньому поверсі корчми «Лев'яча Гордість» у Ґолдширі. Віддана тому, щоб вести новачків Святого Світла далі після їхніх перших випробувань у Нортширі, вона наставляє молодих жерців у вірі, відданості й практичному служінні.",h="Жриця Джозетта — людська наставниця жерців на верхньому поверсі корчми «Лев'яча Гордість» у Ґолдширі.",kw={"жриця джозетта","жрець","ґолдшир","лев'яча гордість","святе світло","наставниця"},ang={["class:Priest"]="Джозетта — важлива рання наставниця для молодих жерців, що покидають Нортшир: вона дає основне навчання заклинань і настанови, як утілити обітниці зцілення в практичне служіння.",["faction:Alliance"]="Джозетта зміцнює хребет Альянсу в Елвінні, дбаючи, щоб тутешні захисники мали духовну й цілющу підтримку, потрібну для охорони серця королівства.",["race:Human"]="Люди-жерці знайдуть у порадах Джозетти знайомі вчення Церкви Світла — вона допомагає посвятити їх у молитовні традиції предків."},sec={{t="Світоч у Ґолдширі",b="Поки багато хто зі святими обітницями проводить дні у величних соборах чи усамітнених монастирях, Жриця Джозетта служить просто серед простого люду Лісу Елвінн. Зі своїх скромних покоїв нагорі в гамірній корчмі «Лев'яча Гордість» вона дбає про духовне здоров'я подорожніх, вартових і тутешніх робітників, доводячи, що служіння Святому Світлу потребує присутності всюди, де серця шукають розради."},{t="Настанова молодим послушникам",b="Джозетта відіграє важливу роль для жерців-початківців, що завершили перше навчання в Абатстві Нортшира. Вона навчає їх практичної суті їхнього покликання, посилаючи в довколишню околицю допомагати пораненим вартовим і втішати стражденних. Через ці завдання вона наголошує: обов'язки клірика — не просто вивчити слова молитви, а діяльно спрямовувати Світло, щоб зцілювати зламаний світ."},{t="Тихий жаль",b="Попри непохитну відданість, Джозетта несе в собі тінь смутку щодо власного життєвого вибору. У юності їй забракло сміливості ступити на широкі дороги й дослідити Азерот — вона обрала безпеку знайомої землі. Хоч вона й задоволена своїм священним служінням у Ґолдширі, вона часто закликає молодих учнів, що переступають її поріг, бути сміливішими за неї й нести свою віру на далекі рубежі."}},faq={{q="Де знайти Жрицю Джозетту?",a="Жриця Джозетта — на другому поверсі корчми «Лев'яча Гордість» у Ґолдширі, у середній кімнаті нагорі разом із Мішель Белль.",al={"місце джозетти","де жриця джозетта","тренер жерців ґолдшира"}},{q="Яку роль відіграє Жриця Джозетта?",a="Вона наставниця жерців Альянсу: навчає жерців-новачків святих заклинань, дисципліни й обов'язків їхнього священного покликання, коли ті вирушають у світ із Нортшира.",al={"що робить джозетта","роль жриці джозетти"}},{q="Чому Джозетта працює в корчмі, а не в церкві?",a="У Ґолдширі немає окремої каплиці, тож корчма «Лев'яча Гордість» — серце містечка. Оселившись нагорі, Джозетта може безпосередньо допомагати втомленим мандрівникам, пораненим міським вартовим і місцевим мешканцям.",al={"чому в корчмі","чому гордість лева"}},{q="Про який свій жаль Джозетта розповідає учням?",a="Вона зізнається, що замолоду так і не наважилася покинути дім і помандрувати світом, і заохочує молодих шукачів пригод досліджувати світ за межами Елвінна.",al={"минуле джозетти","подорожній жаль джозетти"}},{q="Які обов'язки Джозетта дає новим жерцям?",a="Джозетта посилає послушників допомагати пораненим захисникам у полі, навчає їх загоювати рани цілющими молитвами й наголошує, що Світло треба нести просто тим, хто його потребує.",al={"завдання джозетти","завдання шати світла"}},{q="Чи навчає Джозетта расових жрецьких заклинань?",a="Так, як жриця-людина в Елвінні, вона знайомить людей-жерців з особливими молитвами, які шанує їхній народ, як-от Відчайдушною Молитвою.",al={"відчайдушна молитва тренер","людські закляття жерців"}}},fp="17,270,21.418.0,22.429.0,14.412.0,35.146.0,39.184.0,59.220.0,55.182.0,55.197.0,40.139.0"}
P.entries["npc:prospector-ironband"] = {n="Шукач Айронбенд",s="Шукач Дартеус Айронбенд — чесний і працьовитий дворфійський розвідник надр, що керує археологічними розкопками в південно-східному Лох Модані. Працюючи під знаменом Дворфійської Гільдії Дослідників, він прагне відкрити давню спадщину, поховану в надрах Каз Модану. Попри невдачі й ворожих місцевих створінь, Айронбенд справно надсилає до Айронфорджа звіти про поступ і знайдені реліквії.",h="Шукач Дартеус Айронбенд — чесний і працьовитий дворфійський розвідник надр, що керує археологічними...",kw={"шукач айронбенд","розкопки","лох модан","археологія","троги","гільдія дослідників","реліквії"},ang={["faction:Alliance"]="Постачаючи й захищаючи табір Айронбенда, ви допомагаєте вберегти південно-східні околиці Лох Модану від навали трогів і зберегти цінні реліквії для Альянсу.",["profession:Mining"]="На розкопках Айронбенда працюють звичайними кайлами й траншейними прийомами, знайомими кожному рудокопу, а оброблений камінь і поховані шари серед скелі розпізнають гострим оком.",["race:Dwarf"]="Шукач Айронбенд працює на передньому краї задуму короля Маґні збагнути походження дворфів, тож його розкопки — справа глибокої гордості для кожного сина й доньки Айронфорджа."},sec={{t="Розкопуючи минуле",b="Дартеус Айронбенд очолює роботи на Місці розкопок Айронбенда серед пагорбів південно-східного Лох Модану. Як і чимало польових дослідників Гільдії Дослідників, Айронбенд вірить, що земля Каз Модану ховає важливі істини про походження дворфійського народу. Його табір невтомно копає траншеї й просіює уламки в пошуках давніх реліквій, кам'яних скрижалей і артефактів кам'яних предків. Хоч поховану історію видобувають повільно, рішучість Айронбенда непохитна, і він завжди радо наймає тямущих шукачів пригод, щоб захистити свою справу."},{t="Негаразди на порубіжжі",b="Розкопки в суворій дикій місцині ніколи не минають тихо. Табір раз у раз потерпає від місцевих трогів і звірів, що загрожують постачанню й спорядженню, без якого не обійтися. Реліквії й цінні вимірювальні прилади постійно ризикують бути вкраденими чи розтрощеними, перш ніж їх устигнуть дослідити. Айронбенд покладається на мандрівників Альянсу: вони охороняють вантажі, тримають ворожих нападників на відстані й шукають зниклих побратимів гільдії у сусідніх безплідних землях."}},faq={{q="Хто такий Шукач Айронбенд?",a="Шукач Дартеус Айронбенд — відданий своїй справі дворф-розвідувач, що керує археологічними розкопками на південному сході Лох Модану. Він працює від імені Гільдії Дворфів-Дослідників і організовує польові розкопки, щоб повернути втрачені реліквії з історії титанів і землян.",al={"лор айронбенда","хто такий дартеус айронбенд","шукач айронбенд"}},{q="Де знайти Шукача Айронбенда?",a="Він на Місці розкопок Айронбенда, серед пагорбів на південному сході Лох Модану, трохи на схід від головної дороги до південного кордону.",al={"місце айронбенда","де айронбенд","місце розкопок айронбенда"}},{q="Що тут розкопує Гільдія Дослідників?",a="Гільдія Дослідників розкопує стародавні кам'яні руїни по всьому Каз Модану, щоб відтворити історію походження дворфів і знайти артефакти, залишені титанами.",al={"чому айронбенд копає","що розкопують","цілі розкопок айронбенда"}},{q="Навіщо Айронбендові шукачі пригод для охорони вантажів?",a="Розкопки залежать від спеціального копального знаряддя, спорядження для збереження знахідок і харчів, які везуть через Лох Модан. Місцеві троги й люті звірі постійно нападають на каравани з припасами й намагаються пограбувати запаси табору.",al={"лор захисту вантажу","навіщо захищати товари","припаси айронбенда"}},{q="Хто такий Аґмонд і чому Айронбенд про нього питає?",a="Аґмонд — товариш-розвідувач, дворф, що вирушив розвідати розкопки південніше. Коли зв'язок із ним обірвався, Айронбенд попросив мандрівників обшукати Пустища й з'ясувати, що з ним сталося.",al={"знайти аґмонда","хто такий аґмонд","доля аґмонда"}},{q="Чи Шукач Айронбенд родич Бардіна Айронбенда?",a="У них одне прізвище, і обидва тісно пов'язані з дворфійськими справами на прикордонні, що натякає на спорідненість, хоча Дартеус думає лише про археологію й звіти гільдії.",al={"бардін айронбенд родич","рід айронбенд","дартеус і бардін"}}},fp="19,416,19.576.0,17.487.0,27.256.0,37.159.0,46.173.0,56.229.0,50.180.0,50.186.0"}
P.entries["npc:prospector-remtravel"] = {n="Шукач Ремтревел",s="Шукач Ремтревел — дворфський археолог із Ліги Дослідників, що працює глибоко в похмурих лісах Темного Узбережжя. Він керує розкопками, де відкопують давні реліквії, але через розпорошену увагу й небезпечне оточення постійно потребує допомоги.",h="Шукач Ремтревел — дворфський археолог із Ліги Дослідників, що працює глибоко в похмурих лісах Темного...",kw={"шукач ремтревел","ліга дослідників","розкопки","скам'янілості","дворфи","темне узбережжя"},ang={["race:Dwarf"]="Ремтревел втілює невтомну рішучість Ліги Дослідників скласти докупи історію походження дворфів, навіть якщо для цього доводиться ставити намети в холодних, сирих лісах Калімдору.",["race:NightElf"]="Нічні ельфи терплять мирних гостей з Альянсу, але гучні розкопки Ліги й потривожена давня земля часто випробовують терпіння місцевих Вартових і друїдів."},sec={{t="Дворфські розкопки на ельфійських землях",b="Ліга Дослідників послала шукача Ремтревела далеко за море, і він заклав свої розкопки на південних околицях Темного Узбережжя. Нічні ельфи часто ревно оберігають землі своїх предків, але ненаситне прагнення Ліги розкрити походження Азероту жене шукачів у кожен забутий куточок. Ремтревел відкопує закам'янілу історію й давнє каміння, але агресивні місцеві звірі та ворожі сили роблять керування прикордонними розкопками майже непосильним для одного неуважного дворфа."},{t="Неуважний учений",b="Як і годиться його славі, Ремтревел легко поринає у власні думки й дослідницькі нотатки. Коли він забрідає надто далеко від табору в пошуках скам'янілостей чи загублених артефактів, це часто закінчується лихом: хижаки чи ворожі істоти заганяють його в кут. Ті, хто натрапляє на нього в нетрях, зазвичай мусять берегти його крихкі знахідки — і рятувати самого шукача, доки небезпеки Темного Узбережжя не поклали край його місії."}},faq={{q="Хто такий Шукач Ремтревел?",a="Це археолог і розвідувач з Айронфорджа, що представляє Лігу Дослідників. Він облаштував невеликий табір розкопок на півдні Темного Узбережжя, щоб відкопувати стародавні реліквії й скам'янілості.",al={"хто такий ремтревел","лор ремтревела","хто дворф на темному узбережжі"}},{q="Чому дворф з Айронфорджа копає на Темному Узбережжі?",a="Ліга Дослідників прочісує весь відомий світ у пошуках артефактів титанів, утраченої історії й давніх скам'янілостей. Темне Узбережжя — стародавній зруйнований край, глибоко пов'язаний із далеким минулим, тож це чудове місце для дворфійських археологічних досліджень.",al={"чому дворф на темному узбережжі","що робить ліга дослідників на темному узбережжі","чому тут копає"}},{q="Чому його називають неуважним?",a="Ремтревел, поринувши в наукові пошуки, має звичку забувати і про все довкола, і про власне спорядження. Він часто забрідає в небезпечні місця, не помічаючи хижаків і звірів, що підкрадаються до нього.",al={"чому неуважний","чи ремтревел божевільний","що сталося з ремтревелом"}},{q="Чи Шукач Ремтревел має родичів у Лізі?",a="Вважають, що він і є тим заповзятливим дядьком, якого згадує Карна Ремтревел — дослідниця, що завдячує дядькові своєю пристрастю до відкриттів і широкого світу.",al={"родина ремтревела","карна ремтревел дядько","хто така карна ремтревел"}}},fp="20,292,28.532.0,25.452.1,28.190.0,47.243.0,31.230.0,56.168.0"}
P.entries["npc:prospector-ryedol"] = {n="Шукач Райдол",s="Шукач Райдол — розвідник Ліги Дослідників, що стоїть на запиленому пагорбі над східними Пустищами. Наглядаючи за небезпечними розкопками внизу, він намагається повернути втрачені дворфські реліквії й не дати згаснути надії в безплідному пустирі, який заполонили троги та звірі.",h="Шукач Райдол — розвідник Ліги Дослідників, що стоїть на запиленому пагорбі над східними Пустищами.",kw={"райдол","ліга дослідників","пустища","розкопки","дворфи","троги","айронфордж"},ang={["faction:Alliance"]="Для шукачів пригод з Альянсу, що пробираються небезпечними пустирями Пустищ, Райдол — привітне обличчя і джерело нагальних доручень на підтримку Ліги Дослідників.",["race:Dwarf"]="Райдол утілює невгамовне прагнення Айронфорджа розкрити походження дворфів — навіть коли копати доводиться в найсуворіших куточках Каз Модану."},sec={{t="Нагляд за розкопками",b="Шукач Райдол, що отаборився на скелястому пагорбі трохи на південь від Розкопок Гаммертоу, уособлює невтомну працю Ліги Дослідників з Айронфорджа в Пустищах. Посушлива долина багата на прадавні таємниці титанів і спадщину землян, але польові експедиції тут постійно потерпають від лютих трогів, ненажерливих койотів і драконів, що ревно стережуть свої угіддя. Райдол організовує повернення дворфського спорядження, яке викрали дворфи Темного Заліза, і шукає проблисків надії серед зруйнованих застав, сповнений рішучості не дати жертвам Ліги в цих пустирях виявитися марними."}},faq={{q="Хто такий Шукач Райдол?",a="Райдол — дворф, польовий дослідник Ліги Дослідників. Він отаборився на високому пагорбі над Розкопками Гаммертоу на сході Пустищ і допомагає керувати пошуком і поверненням знахідок.",al={"райдол","хто такий райдол","де шукач райдол"}},{q="Що Райдол робить у Пустищах?",a="Він перебуває в Пустищах, щоб підтримувати археологічні справи Ліги Дослідників. Оскільки кілька розкопок поблизу пограбовано чи захоплено трогами, він разом із мандрівниками рятує знайдені реліквії, розшукує загублене знаряддя й з'ясовує долю своїх товаришів-дворфів.",al={"що робить райдол","місія райдола","чому райдол тут"}},{q="Що таке Молот Раєдола?",a="Молот Раєдола — нагорода за повернення його Щасливого Кайла, яке забрали дворфи Темного Заліза, що напали на Розкопки Гаммертоу. Украли саме кайло, а не молот, який дають у нагороду.",al={"молот раєдола","дворф та його інструменти"}}},fp="17,268,22.553.0,25.209.0,37.267.0,24.170.0"}
P.entries["npc:prospector-stormpike"] = {n="Шукач Стормпайк",s="Шукач Стормпайк — різкий, запальний дворф із Бібліотеки Зали Дослідників в Айронфорджі. Член славетного клану Стормпайків, він забезпечує постачання далеких археологічних розкопок і застосовує свій гострий розум, щоб розшифровувати таємні послання.",h="Шукач Стормпайк — різкий, запальний дворф із Бібліотеки Зали Дослідників в Айронфорджі.",kw={"шукач стормпайк","зала дослідників","бібліотека","ліга дослідників","шифри","айронфордж","розкопки"},ang={["faction:Alliance"]="Окрім розкопок, хист Стормпайка до криптографії допомагає операціям Альянсу в північних землях проти тіньових людських культів на кшталт «Пробудження Аргуса».",["race:Dwarf"]="Стормпайк утілює завзятий, тверезий дух Ліги Дослідників: давні дослідження й постачання для нього — справа найвищої дворфійської гордості."},sec={{t="Учений Зали Дослідників",b="Захований серед високих книжкових полиць Зали Дослідників, Шукач Стормпайк координує розкопки в Каз Модані й за його межами. Попри буркотливу вдачу й нетерпимість до пустих балачок, він глибоко відданий розкриттю дворфійської історії й дбає, щоб далекі розкопки мали все необхідне, як-от вибуховий порох. За грубуватою зовнішністю ховається гострий аналітичний розум, що вміє зламувати складні шифри, — і це робить його несподівано цінним помічником для розвідників Альянсу, які мають справу з таємними загрозами."}},faq={{q="Хто такий Шукач Стормпайк?",a="Це археолог і відповідальний за постачання зі славетного клану Стормпайків, що працює в Бібліотеці — крилі Зали Дослідників Айронфорджа.",al={"хто такий стормпайк","лор шукача стормпайка","стормпайк нпс"}},{q="Де знайти Шукача Стормпайка?",a="Він стоїть у Бібліотеці, що в Залі Дослідників у східній частині Айронфорджа.",al={"місце стормпайка","де шукач стормпайк"}},{q="Якою роботою він займається?",a="Стормпайк відає постачанням і звітами археологічних розкопок — наприклад, відправляє вибуховий порох польовим шукачам на кшталт Шукача Айронбенда в Лох Модані — і допомагає розгадувати складні шифри, які приносять розвідники.",al={"завдання стормпайка","що робить стормпайк"}},{q="Навіщо Саутшору його допомога?",a="Влада Альянсу в Саутшорі покладається на його хист до криптографії, щоб розшифровувати перехоплені листи потаємного культу Бдіння Аргуса.",al={"шифр пробудження аргуса","стормпайк саутшор"}}},fp="20,286,32.511.0,28.152.0,38.118.0,29.253.0,34.141.0"}
P.entries["npc:prospector-whelgar"] = {n="Шукач Велґар",kw={"шукач велґар","місце розкопок велґара","камінь ґоаза","ліга дослідників","раптори","багнокрай"},ang={["profession:Mining"]="Скелясті гребені довкола розкопу Велґара мають багаті рудні жили, хоча рудошукачам доведеться мати справу з тими самими рапторами, що допікають загонові Велґара.",["race:Dwarf"]="Місія Велґара прямо служить Лізі Дослідників і тривалим пошукам Короля Маґні Бронзбірда, що прагне відшукати титанічне коріння дворфійського роду."},sec={{t="Розкоп в облозі",b="Відряджений у болотяну глушину Багнокраю, щоб розкрити історію дворфійського роду, Шукач Велґар заснував археологічний табір, відомий як Місце Розкопок Велґара. Долина колись була багата на прадавні кам'яні реліквії, але місцеві раптори швидко взялися боронити свою територію й змусили його загін ховатися. Попри небезпеку, Велґар не кидає свого обов'язку. Він зосереджений на тому, щоб повернути цінні реліквії — зокрема загадковий Камінь Ґоаза, — перш ніж дикі хижаки чи суперники-пройдисвіти остаточно знищать розкоп."}},faq={{q="Хто такий Шукач Велґар?",a="Prospector Whelgar is an Ironforge dwarf archaeologist tasked with leading an expedition in the Wetlands. He oversees the dig site east of Menethil Harbor, studying relics from the dawn of dwarven history.",al={"велґар","хто такий велґар","лор шукача велґара"}},{q="Де знайти Шукача Велґара?",a="He shelters on a ridge overlooking Whelgar's Excavation Site, east of Menethil Harbor and southwest of Dun Modr in the Wetlands.",al={"місце велґара","де велґар","карта велґара мокрі землі"}},{q="Чому у Велґара негаразди на розкопках?",a="Люті місцеві ящери цілком захопили розкопки: вони перебили чи розігнали його людей і змусили Велґара забитися в оборонний закуток. Без захисту ззовні він не може далі відкопувати реліквії.",al={"раптори розкопки","що сталося з розкопками велґара","раптори на розкопках велґара"}},{q="Що таке Камінь Ґоаза?",a="Камінь Ґоаза — стародавній артефакт, знайдений серед руїн на розкопках. Велґар працює над перекладом його написів, щоб краще зрозуміти забуте походження й давню історію дворфійського народу.",al={"камінь ґоаза","що таке камінь ґоаза","реліквія розкриття минулого"}}},fp="18,294,17.523.0,26.205.0,36.128.0,46.200.0,23.217.0"}
P.entries["npc:quartermaster-lewis"] = {n="Інтендант Льюїс",s="Інтендант Льюїс — людина-торговець припасами в Сентінел Гіллі у Вестфолі. Служачи місцевому Народному ополченню, він забезпечує пайками, боєприпасами й щоденними припасами мандрівників і захисників, що намагаються втримати прикордоння від Братства Дефіас.",h="Інтендант Льюїс — людина-торговець припасами в Сентінел Гіллі у Вестфолі.",kw={"інтендант льюїс","сентінел гілл","вежа вартових","припаси","народне ополчення","вестфол"},ang={["class:Hunter"]="Льюїс — важливий польовий постачальник для стрільців у центральному Вестфолі: у нього є і звичайні кулі, і стріли для захисників, що б'ють здалеку.",["faction:Alliance"]="Для новобранців Альянсу, що вирушають до Вестфолу, Льюїс — необхідна зупинка для поповнення припасів на ворожій землі, де офіційних королівських ресурсів загрозливо бракує."},sec={{t="Охоронець запасів вежі",b="Інтендант Льюїс, що облаштувався у Вежі Вартових, опікується мізерним постачанням ополчення Вестфолу. Королівська влада Стормвінда майже не допомагає збіднілому краю, тож Сентінел Гілл покладається на місцевих добровольців і на все, що їм вдається роздобути. Льюїс видає звичайні польові потреби — від сухих пайків і свіжої води до стріл, куль і метальних ножів, — щоб бійці на варті мали бодай найнеобхідніше, аби пережити набіги Дефіасу."}},faq={{q="Хто такий Інтендант Льюїс?",a="Це інтендант у Вежі Вартових у Вестфолі. Льюїс відає повсякденними припасами, пайками й озброєнням для Народного ополчення й шукачів пригод, що допомагають в обороні.",al={"лор льюїса","хто такий льюїс","інтендант сентінел гілла"}},{q="Що продає Інтендант Льюїс?",a="Він торгує всякою всячиною, пропонуючи найпотрібніше для виживання: хліб, молоко, воду, торби, кресало й різні набої для стрільби — стріли, кулі й метальні кинджали.",al={"що продає льюїс","крам льюїса","товари вестфола"}},{q="Яка його роль у завданнях краю?",a="Льюїс допомагає новачкам розібратися в місцевому зв'язку й кур'єрських шляхах довкола Сентінел Гілла: посилає шукачів пригод із місцевими дорученнями, як-от доставити послання Торові, наглядачеві грифонів, і принести відповідь.",al={"завдання льюїса","швидке повідомлення","повернутися до льюїса"}},{q="Чи Льюїс служить в армії Стормвінда?",a="Як і більшість захисників Сентінел Гілла, Льюїс служить Народному ополченню, а не офіційному загонові, присланому короною Стормвінда. Край здебільшого покинули самотужки боронитися від Братства Дефіас.",al={"чи льюїс армія","вартовий стормвінда льюїс","народне ополчення льюїс"}}},fp="19,270,28.480.0,27.189.0,35.199.0,36.218.0,36.217.0"}
P.entries["npc:quinn-yorick"] = {n="Квінн Йорік",s="Квінн Йорік — поранений розвідник-Відступник, що ховається на горищі зруйнованої хати на Іваровій ділянці. Ледве переживши сутичку з дикою потворою, відомою як Івар Мерзенний, він тепер покладається на союзників, що проходять повз, аби вижити.",h="Квінн Йорік — поранений розвідник-Відступник, що ховається на горищі зруйнованої хати на Іваровій ділянці.",kw={"квінн йорік","івар мерзенний","відступники","розвідник","срібнолісся","іварова ділянка"},ang={["race:Undead"]="Скрута Квінна показує, якою постійною небезпекою є дикі потвори для сил Відступників, що намагаються вбезпечити північне Срібнолісся."},sec={{t="Хиткий притулок",b="Квінн Йорік лежить тяжко поранений нагорі в покинутому домі на Іваровій ділянці. Так він опинився після лютої сутички з Іваром Мерзенним — однією з диких потвор, що блукають північними околицями Срібнолісся. Не маючи змоги ні завершити місію, ні безпечно відступити сам, Квінн переховується й чекає на мандрівників, що служать Відступникам, — щоб ті допомогли йому в біді й покарали звіра, який мало не розірвав його на шматки."}},faq={{q="Де перебуває Квінн Йорік?",a="Квінн Йорік ховається на горішньому поверсі зруйнованої хати на Ділянці Івара в Срібноліссі, на північ від Гробниці.",al={"місце квінна йоріка","де квінн","будинок квінна йоріка"}},{q="Хто поранив Квінна Йоріка?",a="Його тяжко поранив Івар Мерзенний — могутній і лютий ворген, що нишпорить довколишніми полями.",al={"хто напав на квінна","що сталося з квінном йоріком","квінн поранений"}},{q="Яку роль Квінн відіграє для шукачів пригод Орди?",a="До Квінна повертаються розвідники й союзники Відступників, яких посилають йому на допомогу, щоб помститися Іварові Мерзенному.",al={"завдання квінна йоріка","давець завдань квінн"}}},fp="12,254,19.454.0,30.145.0,25.101.0,49.138.0"}
P.entries["npc:raene-wolfrunner"] = {n="Рейн Вульфраннер",s="Рейн Вульфраннер — досвідчена офіцерка Вартових і мисливиця, що несе службу в самому серці Астранаару в Ашенвалі. Разом із вірними супутниками — вовком і шаблезубою кішкою — вона керує обороною лісу від Орди та осквернених племен фурболгів. Для героїв Альянсу, що захищають священну дикину, вона — надійна опора.",h="Рейн Вульфраннер — досвідчена офіцерка Вартових і мисливиця, що несе службу в самому серці Астранаару в...",kw={"рейн вульфраннер","вартові","астранаар","фурболги","жезл дартола","мисливиця"},ang={["class:Hunter"]="Досвідчена мисливиця, якій корються і вовк, і шаблезуба кішка, Рейн утілює вміння жити в дикій природі та спорідненість зі звірами, які так цінують мисливці.",["faction:Alliance"]="Для мандрівників Альянсу, що прибувають з Темного Узбережжя, Рейн — головна офіцерка, яка обороняє Ашенваль і від ворожих військ, і від скверни.",["race:NightElf"]="Рейн утілює відданість Вартових Елуні та дикій природі Калімдору: вона не дозволить сплюндрувати лісові святилища Ашенвалю."},sec={{t="Захисниця Астранаару",b="Рейн Вульфраннер пильно стоїть на варті в Астранаарі разом зі своєю вірною шаблезубою кішкою Коррою та вовком Даґрі. Як офіцерка Вартових, вона наглядає за патрулями по всьому Ашенвалю й координує розвідку далеко за його межами, посилаючи розвідниць на кшталт Каели Шедовспір у сусідні краї, як-от Гори Кам'яного Кігтя. Відданість Рейн давнім лісам безмежна: вона заявила, що радше сама вийде проти неповоротких загонів Орди, ніж дивитиметься, як вони безкарно рубають і палять священні дерева."},{t="Стримати скверну",b="Окрім протистояння з Ордою, Рейн глибоко переймається темною скверною, що отруює корінних мешканців Ашенвалю. Вона спрямовує походи проти ворожих племен фурболгів — зокрема рішучі удари по таборах Гнилолісу, звідки нападають на мандрівників, і точкові вилазки проти ватажків Будякохутрих, які дедалі більше набирають сили. Її розвідниці пильно стежать, як змінюється поведінка фурболгів, і покладаються на тверде командування Рейн, щоб уберегти місцеві поселення й подорожніх від злагоджених засідок."},{t="Жезл Дартола",b="Найособистіша справа Рейн пов'язана з Жезлом Дартола — давньою реліквією, що допомагає очищати фурболгів. Її давній друг Теронис загинув, шукаючи втрачений самоцвіт жезла, і Рейн наказала повернути його тіло й пообіцяла довести його дослідження до кінця. Разом із дріадою Шаель'дрін вона допомагає героям зібрати реліквію. Зрештою шукач пригод, прибравши подоби фурболга, радиться з вождем Кролґом і перемагає оскверненого ватажка Рана Бладтуса, усуваючи загрозу для всього краю."}},faq={{q="Де знайти Рейн Вульфраннер?",a="Рейн несе службу в Астранаарі — головному містечку нічних ельфів в Ашенвалі. Вона стоїть надворі, напоготові, а обабіч неї — двоє її звірів-супутників.",al={"місце рейн вульфраннер","де рейн","точка рейн астранаар"}},{q="Що за звірі стоять поруч із Рейн?",a="Це її вишколені мисливські супутники — шаблезуба кішка на ім'я Корра й вовк на ім'я Даґрі, що не відходять від неї в Астранаарі.",al={"улюбленці рейн","вовк і кішка рейн","супутники рейн"}},{q="Яка роль Рейн серед Вартових?",a="Вона високопоставлена офіцерка Вартових у центральному Ашенвалі: віддає накази розвідникам, керує заставами й організовує тактичні дії проти місцевих загроз.",al={"ранг рейн","чи рейн офіцер","роль рейн вартова"}},{q="Що сталося з другом Рейн, Теронісом?",a="Тероніс допомагав Вартовим, шукаючи самоцвіт, потрібний для Жезла Дартола. Він загинув у дорозі, і Рейн доручає забрати його останки й завершити його місію.",al={"хто такий тероніс","друг рейн тероніс","смерть тероніса"}},{q="Чому Рейн так зосереджена на фурболгах?",a="Зіпсовані племена на кшталт Гнилого Гаю й Будякохутрих стають дедалі лютішими: вони нападають із засідок на мандрівників на лісових дорогах і загрожують спокою Астранаару.",al={"завдання рейн про фурболґів","чому воювати з тістлфур","біда фаулвілд"}},{q="Навіщо потрібен Жезл Дартола в її ланцюжку завдань?",a="Відновлений жезл дає шукачеві пригод змогу на час набути подоби фурболга, щоб поговорити з Кролґом і вийти на зіпсованого вождя Рана Бладтуса й знищити його.",al={"призначення жезла дартола","що робить жезл дартола","жезл очищення рейн"}}},fp="16,377,21.527.0,32.500.0,12.519.1,36.138.0,43.125.0,42.165.0,40.169.1,49.166.0,53.180.1"}
P.entries["npc:ragnar-thunderbrew"] = {n="Раґнар Тандербрю",s="Раґнар Тандербрю — дворфійський бровар і співвласник уславленої Ґуральні Тандербрю в Хараносі. Відомий по всьому Дун Мороґу тим, що подає фірмові Кабанячі ребра в пивному соусі своєї родини, він невпинно працює, щоб у людній корчмі всього вистачало, а відвідувачі лишалися задоволеними.",h="Раґнар Тандербрю — дворфійський бровар і співвласник уславленої Ґуральні Тандербрю в Хараносі.",kw={"раґнар тандербрю","бровар","ґуральня тандербрю","харанос","кабанячі ребра","корчма","ґрімбуз тандербрю"},ang={["profession:Cooking"]="Раґнар уславився родинним рецептом Кабанячих ребер у пивному соусі від Тандербрю, тож це корисне знайомство для кухарів-початківців, які прагнуть опанувати ситні дворфійські корчемні страви.",["race:Dwarf"]="Для дворфів, що проходять через Дун Мороґ, корчма Раґнара — дім удалині від дому, де подають найкращий ель і найкращі ребра, які лише може запропонувати клан."},sec={{t="Опора гостинності Хараноса",b="У Ґуральні Тандербрю в Хараносі Раґнар Тандербрю дбає про кулінарну славу закладу поряд із броварським ремеслом своєї родини. Ґуральня — центральне місце зустрічі для місцевих горян, мандрівних шукачів пригод і гномів-біженців, що тікають із Гномреґану. Головний його обов'язок — готувати уславлені родинні Кабанячі ребра в пивному соусі, ситну страву Дун Мороґу, тушковану в міцному дворфійському елі. Та підтримувати постачання стало важко: його звичний постачальник м'яса записався до Королівської армії, і Раґнар тепер залежить від мандрівних горян і мисливців, які приносять на кухню свіжі боки скельних вепрів."},{t="Спадок Тандербрю",b="Ім'я Тандербрю — синонім дворфійського хмільного й корчемної культури по всіх землях Айронфорджа. Раґнар тримає родинну ґуральню на ходу, відколи його старший брат Ґрімбуз Тандербрю кілька жнив тому зник у п'яному чаду, боронячи ревно бережену броварську спадщину родини від суперників на кшталт Барліброю. Серед неспокійних відвідувачів, зниклих ліній постачання й галасливих корчемних суперечок Раґнар твердо тримає руку на кранах, пильнуючи, щоб жоден мандрівник не покинув Харанос із порожнім кухлем чи порожнім шлунком."}},faq={{q="Хто такий Раґнар Тандербрю?",a="Раґнар Тандербрю — дворф-пивовар і співвласник Ґуральні Тандербрю в Хараносі. Він порядкує в таверні й готує славетні родинні вепрячі реберця в елі.",al={"хто такий раґнар","роль раґнара тандербрю","раґнар харанос"}},{q="Навіщо Раґнарові вепрячі реберця?",a="Постійний постачальник м'яса Раґнара пішов до війська Короля Маґні, і на кухні забракло припасів. Щоб нагодувати голодних відвідувачів, він купує свіжі боки в мисливців і мандрівників.",al={"навіщо вепряче м'ясо","завдання пивних реберець","постачання кабаняти ребер"}},{q="Ким Раґнарові доводиться Ґрімбуз Тандербрю?",a="Ґрімбуз — старший брат Раґнара. Їхній батько, Аркілус, заснував Ґуральню Тандербрю, і Раґнар веде справу відтоді, як кілька врожаїв тому Ґрімбуз зник у п'яному чаду.",al={"раґнар і ґрімбуз","ґрімбуз тандербрю родич"}},{q="Де перебуває Раґнар Тандербрю?",a="Раґнара можна знайти в Ґуральні Тандербрю в селищі Харанос, серед засніжених пагорбів у центрі Дун Мороґу.",al={"місце раґнара","знайти раґнара тандербрю"}}},fp="18,264,32.668.0,22.541.0,26.187.0,36.187.0,47.197.0,36.131.0"}
P.entries["npc:rahauro"] = {n="Рагауро",s="Рагауро — таурен-прислужник з Узвишшя Старійшин у Тандер Блафі, що вірно служить Старій Відьмі Маґаті Ґрімтотем. Діючи від її імені, він набирає хоробрих шукачів пригод, щоб ті спустилися у вулканічні глибини Провалля Лютого Вогню під Оргріммаром. Він організовує відплату ворожим трогам і пошук зниклих речей полеглих посланців своєї господині.",h="Рагауро — таурен-прислужник з Узвишшя Старійшин у Тандер Блафі, що вірно служить Старій Відьмі Маґаті...",kw={"рагауро","маґата ґрімтотем","провалля лютого вогню","троги","маур ґрімтотем","узвишшя старійшин","тандер блаф"},ang={["faction:Horde"]="Рагауро дає членам Орди в Тандер Блафі перші доручення в підземеллях, поєднуючи інтереси провідників тауренів із захистом столиці орків — Оргріммара.",["race:Tauren"]="Для тауренів, що ходять терасами Тандер Блафа, Рагауро уособлює далекосяжний вплив Узвишшя Старійшин і тихі інтриги найближчого оточення Маґати."},sec={{t="Голос Старої Відьми",b="Рагауро вірно стоїть біля Маґати Ґрімтотем на високій терасі Узвишшя Старійшин і є її безпосереднім посередником. Маґата часто діє через довірених підлеглих, щоб не бруднити власних копит прилюдним вербуванням. Коли надходять звістки про диких істот, що кишать під столицею орків, саме Рагауро береться за всі подробиці й відряджає найманців Орди придушити заворушення."},{t="Біда в Проваллі Лютого Вогню",b="Троги, що заполонили підземні печери Провалля Лютого Вогню, не надто привітно зустріли мирні пропозиції. Маґата спершу відрядила посланців, сподіваючись укласти мир із первісними звірами, та троги люто накинулися на посольство й порубали його. Вважаючи їх нестерпною загрозою для Орди, Рагауро скеровує чемпіонів у печери, щоб проріджити лави трогів і з'ясувати їхню справжню силу."},{t="Сумка полеглого посланця",b="Серед жертв нападу трогів був Маур Ґрімтотем — один із довірених слуг Маґати. Перед загибеллю у вогняних глибинах Маур натрапив на щось цікаве й дуже хотів показати це своїй господині. Рагауро доручає дослідникам обнишпорити вулканічні стежки й повернути загублену сумку Маура, сподіваючись забрати всі делікатні знахідки, які лишив по собі полеглий посланець."}},faq={{q="Хто такий Рагауро?",a="Рагауро — таурен-прислужник на Узвишші Старійшин у Тандер Блафі. Він помічник Маґати Ґрімтотем і посилає мандрівників виконувати доручення на службі його пані й Орди.",al={"хто такий рагауро","лор рагауро","хто цей таурен"}},{q="Де знайти Рагауро?",a="Ви знайдете Рагауро в Тандер Блафі на Узвишші Старійшин, поруч із матріарх Ґрімтотемів Маґатою Ґрімтотем.",al={"місце рагауро","де рагауро","знайти рагауро"}},{q="Чому Рагауро посилає шукачів пригод до Провалля Лютого Вогню?",a="Маґата Ґрімтотем намагалася послати посланців на перемовини з трогами, що вилазять з-під Оргріммара, але звірі їх убили. Рагауро наймає шукачів пригод, щоб прорідити трогів і покінчити із загрозою, яку вони становлять для Орди.",al={"рагауро лютий вогонь","навіщо посилати в лютий вогонь","завдання про трогів рагауро"}},{q="Хто такий Маур Ґрімтотем?",a="Маур Ґрімтотем — слуга, якого Маґата послала в глибини Провалля Лютого Вогню. Він знайшов у печерах щось важливе, але троги вбили його, перш ніж він устиг передати свої знахідки.",al={"маур ґрімтотем","хто такий маур","хлопець із загубленою торбою"}},{q="Що в загубленій торбі, яку шукає Рагауро?",a="У торбі — дивна знахідка, яку Маур Ґрімтотем зробив перед смертю. Рагауро просить шукачів пригод забрати її з печер, що кишать трогами, і цілою повернути до Тандер Блафа.",al={"вміст загубленої торби","що в торбі","торба маура"}},{q="Чи належить Рагауро до племені Ґрімтотем?",a="Він — особистий прислужник Маґати Ґрімтотем на Узвишші Старійшин і відає справами агентів Ґрімтотемів на кшталт Маура, тож тісно пов'язаний із почтом Маґати в Тандер Блафі.",al={"чи рагауро з ґрімтотемів","плем'я рагауро","фракція рагауро"}}},fp="7,388,24.407.0,25.418.0,26.392.1,15.201.0,25.117.0,58.244.0,23.206.0,46.192.0,43.196.0"}
P.entries["npc:raleigh-andrean"] = {n="Ралей Андреан",s="Ралей Андреан — мешканець Андерсіті з Відступників. Його прохання виказують черстве ставлення до власного людського життя й до тих, кого він колись знав.",h="Ралей Андреан — мешканець Андерсіті з Відступників.",kw={"ралей андреан","валдред морей","делайя","помста","відступники","андерсіті"},ang={["race:Undead"]="Те, як Ралей ставиться до своїх колишніх людських зв'язків, — тривожний приклад того, як один із Відступників сприйняв нежиття."},sec={{t="Гірке нежиття",b="До того як Третя війна спустошила Лордерон, Ралей Андреан жив звичайним людським життям: був одружений із жінкою на ім'я Делайя й товаришував із Валдредом Мореєм. Як і безліч інших, він загинув, коли Погибель пронеслася королівством, і повстав бездумним рабом на службі Короля-Ліча. Він повернув собі вільну волю, коли влада Нер'жула похитнулася, а Сильвана Віндраннер підняла повстання, і зайняв своє місце серед Відступників в Андерсіті."},{t="Помста замість скорботи",b="Коли Ралеєві показують обручку його покійної дружини, видно, як нежиття випалило в ньому всі почуття. Він не відчуває ні смутку, ні залишків любові до Делайї й холодно відмахується від її смерті. Натомість усі його думки — про злобу: він вимагає відрубаних рук Валдреда Морея, свого колишнього друга, що вбив її. Ралей зберігає ці моторошні трофеї не з любові до Делайї, а як вічну пам'ятку про зраду, а того, хто йому допоможе, винагороджує перснем, викуваним із чистої зневаги."}},faq={{q="Де перебуває Ралей Андреан?",a="Ралей Андреан живе в гамірному Торговому Кварталі Андерсіті, серед Відступників, що населяють це підземне місто.",al={"місце ралея андреана","де ралей","знайти ралея андреана"}},{q="Ким був Ралей за життя?",a="За життя Ралей був смертним мешканцем королівства Лордерон. Він був одружений із жінкою на ім'я Делайя й дружив із чоловіком на ім'я Валдред Морей, доки королівство не накрила Погибель.",al={"минуле ралея","хто був ралей","лор ралея андреана"}},{q="Чому Ралей прагне помститися Валдредові Морею?",a="Ралей прагне помститися комусь зі свого колишнього життя. Принесена йому обручка відкриває подробиці цієї кривди.",al={"чому вбивати валдреда","дружина ралея","вбивство валдреда морея"}},{q="Як Ралей звільнився з-під влади Погибелі?",a="Ралей загинув під час Третьої війни, і Погибель підняла його собі на службу. Коли влада Короля-Ліча послабшала після нападів на Крижаний Трон, Сильвана Віндраннер очолила повстання й звільнила Ралея та багатьох інших, які стали Відступниками.",al={"як ралей став відступником","свобода ралея від плеті"}}},fp="15,148,18.477.0,20.484.1,33.133.0,34.205.0,47.133.0,45.248.0"}
P.entries["npc:randis"] = {n="Рендіс",s="Рендіс — жвавий хлопчик-сирота, людина, якого доглядає Матрона Сиротинця Найтінґейл у сиротинці на Соборній Площі. На Тиждень Дітей він залюбки мандрує з охочими шукачами пригод землями Альянсу, щоб побачити дива далеко за міськими мурами.",h="Рендіс — жвавий хлопчик-сирота, людина, якого доглядає Матрона Сиротинця Найтінґейл у сиротинці на Соборній...",kw={"рендіс","сирота","тиждень дітей","сиротинець","соборна площа","стормвінд"},ang={["faction:Alliance"]="Опікуючись Рендісом на Тиждень Дітей, герої Альянсу згадують, за що насправді воюють: щоб захистити наступне покоління мирних людей і мрійників."},sec={{t="Вихованець Стормвінда",b="Рендіс живе в сиротинці біля Собору Світла в Стормвінді — він один із багатьох дітей, що лишилися без родини через нескінченні війни королівства. Коли настає щорічний Тиждень Дітей, Матрона Сиротинця Найтінґейл вручає небайдужим героям свисток, щоб ті взяли хлопця під своє крило. Сповнений дитячої цікавості й безупинних запитань, Рендіс мріє про пригоди, без кінця загадує загадки й сміливо заявляє, що коли виросте, стане королем Стормвінда."},{t="Очі на світ",b="Для хлопця, який здебільшого сидить замкнений на Соборній Площі, вибратися зі столиці — справжня пригода. Рендіс захоплюється далекими дивами, як-от величною Каменетесною Греблею в Лох Модані, й мріє зустріти славетних героїв Азероту. Хоч він і не забуває зауважити, що в місцях на кшталт Айронфорджа пахне доволі дивно, його безмежне захоплення віддзеркалює те безневинне майбутнє, за яке борються герої Альянсу."}},faq={{q="Хто такий Рендіс?",a="Рендіс — хлопчик, що живе в Сиротинці Стормвінда на Соборній Площі. Під час святкувань Тижня Дітей шукачі пригод можуть зголоситися наглядати за ним і поводити його світом.",al={"рендіс нпс","хто сирота-людина","людина-сирота стормвінд"}},{q="Як познайомитися з Рендісом?",a="Під час Тижня Дітей Матрона Сиротинця Найтінґейл на Соборній Площі дає шукачам пригод свисток сироти. Подувши в нього, ви покличете Рендіса, і він вирушить разом із вами в пригоди.",al={"як отримати рендіса","викликати рендіса","свисток сироти стормвінд"}},{q="Які місця хоче побачити Рендіс?",a="Рендіс мріє побачити легендарні пам'ятки Альянсу — зокрема величезну Каменетесну Греблю в Лох Модані — і видатних людей королівства, щоб хоч одним оком глянути на життя за межами Стормвінда.",al={"місця рендіса","пам'ятки рендіса","місця для сироти-людини"}},{q="Чому Рендіс живе в сиротинці?",a="Як і багато дітей під дахом Матрони Найтінґейл, Рендіс утратив батьків через безперервні війни, навали й лиха, що спіткали королівство Стормвінд і ширші землі Азероту.",al={"батьки рендіса","чому рендіс сирота","сиротинець стормвінда лор"}}},fp="6,267,19.485.0,17.411.0,14.208.0,23.189.0,38.197.0,37.196.0"}
P.entries["npc:ranger-glynda-nal-shea"] = {n="Рейнджерка Ґлінда Нал'Шея",s="Рейнджерка Ґлінда Нал'Шея — досвідчена вартова з нічних ельфів, що служить у прибережному містечку Обердайн. Зі свого посту біля міської варти вона керує обороною Темного Узбережжя, посилаючи мандрівників знищувати причаєні загрози й розслідувати дивні явища на узбережжі.",h="Рейнджерка Ґлінда Нал'Шея — досвідчена вартова з нічних ельфів, що служить у прибережному містечку Обердайн.",kw={"ґлінда нал'шея","рейнджерка","обердайн","каламутноглиб","мурлоки","темне узбережжя"},ang={["class:Hunter"]="Колеги-рейнджери й слідопити відчують споріднену душу в гострих інстинктах Ґлінди та її прямому підході до знищення диких звірів і прибережних хижаків.",["faction:Alliance"]="Мандрівникам Альянсу, що припливають кораблем із Тельдрассилу чи Східних Королівств, Ґлінда дає важливі доручення за винагороду, щоб убезпечити периметр Темного Узбережжя.",["race:NightElf"]="Для нічних ельфів Ґлінда Нал'Шея уособлює незмінну пильність, потрібну, щоб боронити священні береги Калімдору від агресивних звірів і давньої порчі."},sec={{t="Охоронниця Обердайна",b="Поки Темне Узбережжя потерпає від дедалі сильнішої порчі й ворожих вторгнень, рейнджерка Ґлінда Нал'Шея координує з Обердайна важливу розвідку. Вона пильно стежить за навколишніми нетрями й покладається на здібних шукачів пригод, щоб тримати периметр і берегти володіння нічних ельфів на оповитому туманом узбережжі."},{t="Загрози на узбережжі",b="Ґлінда зосереджена на небезпеках, що дедалі ближче підступають до берегів, — передусім на зухвалих мурлоках, які збираються на південь від містечка. Вона оголошує нагороди за голови горезвісних лиходіїв на кшталт Каламутноглиба й доручає розвідникам вивчати дивні артефакти, зокрема таємничий багряний кристал, що вріс у висоти над морем."}},faq={{q="Хто така Рейнджерка Ґлінда Нал'Шея?",a="Це ельфійка-рейнджерка з Обердайна, що організовує розвідувальні патрулі й оборонні доручення по всьому Темному Узбережжю від імені Вартових нічних ельфів.",al={"ґлінда нал'шея","хто така ґлінда","рейнджерка ґлінда"}},{q="Де знайти Ґлінду Нал'Шею?",a="Вона в Обердайні, головному поселенні Альянсу на Темному Узбережжі; зазвичай її можна знайти біля варти Вартових і при входах до містечка.",al={"місце ґлінди","де ґлінда","де знайти ґлінду"}},{q="Які завдання дає Рейнджерка Ґлінда Нал'Шея?",a="Вона дає доручення, пов'язані з небезпеками краю, зокрема оголошення на кшталт «РОЗШУКУЄТЬСЯ: Каламутноглиб!» і розслідування загадкового червоного кристала на кручах Темного Узбережжя.",al={"завдання ґлінди","що дає ґлінда"}},{q="Чому Ґлінду тривожить Каламутноглиб?",a="Каламутноглиб — лютий вождь мурлоків, винний у нападах на застави нічних ельфів і мандрівників на південному узбережжі; він становить постійну загрозу безпеці Обердайна.",al={"хто такий каламутноглиб","чому вбивати каламутноглиба"}},{q="Що за ланцюжок завдань про Червоний Кристал?",a="Це низка розвідувальних розслідувань, які розпочинає Ґлінда: вона доручає шукачам пригод піднятися на східні кручі Темного Узбережжя, оглянути дивний пульсуючий кристал і принести його уламки для дослідження.",al={"червоний кристал темне узбережжя","завдання червоного кристала"}},{q="Якій фракції служить Ґлінда Нал'Шея?",a="Вона служить нічним ельфам Дарнасуса й командує військовою заставою Альянсу на Темному Узбережжі.",al={"фракція ґлінди","на кого працює ґлінда"}}},fp="22,278,21.314.0,23.337.0,30.148.0,35.131.0,46.176.0,39.179.0,35.192.0,40.111.0"}
P.entries["npc:rau-cliffrunner"] = {n="Рау Кліффраннер",s="Рау Кліффраннер — таурен-розвідник і вчений, що несе службу високо на Заставі Вільного Вітру в Тисячі Голок. Віддано захищаючи свій народ від загроз краю, він вивчає історію й походження ворожих кентаврів Ґалак за їхніми прадавніми реліквіями. Тісно співпрацюючи із союзниками в Тандер Блафі, Рау організовує вилазки до небезпечних ворожих твердинь у каньйоні.",h="Рау Кліффраннер — таурен-розвідник і вчений, що несе службу високо на Заставі Вільного Вітру в Тисячі Голок.",kw={"рау кліффраннер","застава вільного вітру","тисяча голок","кентаври","ґалак","роздвоєне копито","занген стоунгуф"},ang={["faction:Horde"]="Зусилля Рау допомагають утримати Заставу Вільного Вітру — відокремлений бастіон Орди, без якого не вберегти шляхів постачання між Пустками й Танарісом.",["race:Tauren"]="Для тауренів розуміння кентаврів — питання виживання культури: досліджуючи витоки кентаврів, Рау прагне збагнути давній конфлікт, що мало не стер шу'гало з лиця землі."},sec={{t="Вартовий каньйонів",b="З небезпечних круч Застави Вільного Вітру Рау Кліффраннер пильно стежить за широкими, випаленими сонцем просторами Тисячі Голок. Ця застава тауренів — важливий прихисток Орди посеред ворожого краю, що кишить лютими хижаками, шипогривами й войовничими кланами кентаврів. Рау водночас і організатор застави, і відданий дослідник, що прагне знешкоджувати нові загрози, перш ніж вони захлиснуть вразливі поселення на столових горах."},{t="Таємниці Ґалак",b="Найбільше Рау захоплює прадавнє походження кентаврів — народу, що поколіннями вів жорстоку війну проти тауренів. Дізнавшись, що місцеве плем'я Ґалак стереже священну реліквію, яка сягає світанку їхнього роду, Рау почав шукати спосіб обійти її містичний захист. Разом із Зангеном Стоунгуфом із Тандер Блафа Рау здобув священну воду місячного колодязя з Ашенвалю, щоб загасити вічне полум'я у Твердині Розщепленого Копита, — і шукачі пригод змогли винести загадкове Роздвоєне Копито для його досліджень."}},faq={{q="Де знайти Рау Кліффраннера?",a="Рау Кліффраннер живе на вершині Застави Вільного Вітру — відомої застави на плато посеред Тисячі Голок.",al={"місце рау кліффраннера","де рау","де рау кліффраннер"}},{q="Що досліджує Рау Кліффраннер?",a="Рау досліджує походження й містичні традиції кентаврів. Він шукає Роздвоєне Копито — стародавню племінну реліквію, яку кентаври Ґалак тримають на Кручі Розколотого Копита, — сподіваючись, що її дивна енергія проллє світло на давніх ворогів тауренів.",al={"мета рау кліффраннера","чого хоче рау","навіщо рау копито"}},{q="Навіщо Рау вода з місячного колодязя?",a="Кентаври Ґалак тримають свою стародавню реліквію за вічним містичним вогнем. Рау дізнався, що чиста вода з місячного колодязя нічних ельфів в Ашенвалі має священну силу, здатну загасити полум'я жаровні й пробити її захист.",al={"вода місячного колодязя рау","священне полум'я місячний колодязь","навіщо вода колодязя"}},{q="Хто працює з Рау Кліффраннером у Тандер Блафі?",a="Із Рау безпосередньо співпрацює Занген Стоунгуф з Узвишшя Мисливців у Тандер Блафі. Занген організовує здобуття води з місячного колодязя Ашенвалю, а потім посилає надійних мандрівників Орди вниз, до Рау на Заставу Вільного Вітру.",al={"союзник рау","зенґен і рау","хто послав мене до рау"}},{q="Що таке Роздвоєне Копито?",a="Роздвоєне Копито — прадавній артефакт кентаврів, який береже клан Ґалак у Твердині Розщепленого Копита. Він сягає часів появи народу кентаврів і випромінює незвичайну енергію, яку Рау прагне розгадати.",al={"реліквія роздвоєного копита","що таке копито","реліквія кентаврів тисяча голок"}},{q="Чи належить Рау Кліффраннер до певного тауренського племені?",a="Племені Рау ніде не зазначено. Він таурен-воїн із Тандер Блафа, що служить на Заставі Вільного Вітру, і ніщо не пов'язує його прізвища з якимсь відомим плем'ям.",al={"плем'я рау кліффраннера","яке плем'я в рау"}}},fp="15,375,22.478.0,20.529.1,33.113.0,38.254.0,33.239.0,53.225.0,24.201.0,55.153.0"}
P.entries["npc:razzle-sprysprocket"] = {n="Раззл Спрайспрокет",s="Раззл Спрайспрокет — гномський інженер і пілот, що мешкає в Хараносі в Дун Мороґу. Відомий технічним майструванням разом з Оззі Тоґлвольтом, він залучає мандрівників, щоб ті допомагали рятувати розкидані гномські механізми й деталі по засніжених пагорбах.",h="Раззл Спрайспрокет — гномський інженер і пілот, що мешкає в Хараносі в Дун Мороґу.",kw={"раззл спрайспрокет","гном","інженер","пілот","харанос","оззі тоґлвольт","гномреґан"},ang={["profession:Engineering"]="Інженери знайдуть у Раззлі споріднену душу: його проєкти показують тонку межу між блискучим гномським винаходом і вибуховим прорахунком.",["race:Gnome"]="Для гномів-вигнанців, що проходять через Дун Мороґ, Раззл утілює незгасний винахідницький дух і рішучість відбудувати й повернути втрачене після падіння Гномреґану."},sec={{t="Майстрування в Хараносі",b="Після трагедії в Гномреґані Раззл Спрайспрокет знайшов притулок серед заметів Дун Мороґу й облаштував майстерню в Хараносі. Уславлений серед колег як пілот-рекордсмен із хистом до тонких механічних деталей, Раззл працює разом з інженером Оззі Тоґлвольтом. Їхні зусилля часто спрямовані на повернення гіромеханізмів і зубчастих збірок, які загубили чи розтягли під час утечі з їхньої опроміненої батьківщини."},{t="Оборона майстерні",b="Життя в Дун Мороґу для гнома-винахідника далеко не мирне. Між дикими звірами замерзлих хребтів і набігами місцевих тролів Морозогривів експерименти Раззла часом призводили до хаотичних пригод — як-от коли він переплутав цокотливі бомби з годинниковим механізмом зі звичайними вибуховими снарядами. Попри такі інженерні халепи, він лишається відданим тому, щоб гномські пристрої працювали, а втрачені дива Гномреґану повернулися."}},faq={{q="Хто такий Раззл Спрайспрокет?",a="Раззл Спрайспрокет — ексцентричний гном-майстер і, за чутками, пілот-рекордсмен, що працює в Хараносі в Дун Мороґу разом з Оззі Тоґлвольтом.",al={"хто такий раззл","раззл спрайспрокет","раззл харанос"}},{q="З чим Раззлові Спрайспрокету потрібна допомога?",a="Раззл раз у раз просить шукачів пригод вирушити в Дун Мороґ і зібрати загублені штуковини, вузли шестерень і деталі, щоб допомогти перезбахурити гномські інженерні задуми.",al={"завдання раззла","операція перезбірка допомога","чого хоче раззл"}},{q="Де знайти Раззла Спрайспрокета?",a="Він працює надворі біля майстерні в Хараносі, одразу за корчмою й кузнею в центрі Дун Мороґу.",al={"місце раззла","де раззл","карта раззла спрайспрокета"}},{q="Чи Раззл Спрайспрокет родич інших Спрайспрокетів?",a="Вважають, що Раззл — близький родич Краззла Спрайспрокета, адже в них однаково підстрижені бороди; ще в нього є двоюрідний брат Ґімбл, а от із Різзлом Спрайспрокетом близького зв'язку немає.",al={"краззл спрайспрокет брат","рід спрайспрокет","родичі раззла"}}},fp="19,253,21.451.0,23.425.0,27.160.0,45.183.0,37.122.0,54.186.0"}
P.entries["npc:red-jack-flint"] = {n="Рудий Джек Флінт",s="Рудий Джек Флінт — досвідчений моряк-людина, що перебуває у Фортеці Менетіл у Гавані Менетіл. Член команди корабля «Дівоча Чеснота», він допомагає мандрівникам, які шукають, як перебратися через море до Калімдору, чи потрібних знайомств по той бік.",h="Рудий Джек Флінт — досвідчений моряк-людина, що перебуває у Фортеці Менетіл у Гавані Менетіл.",kw={"рудий джек флінт","гавань менетіл","фортеця менетіл","дівоча чеснота","фіора лонґірс","моряк"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що прокладають курс через море з Каз Модану, моряки на кшталт Рудого Джека Флінта — важливі зв'язкові із заставами на північному узбережжі Калімдору."},sec={{t="Моряк у Фортеці Менетіл",b="Рудий Джек Флінт, якого можна знайти в кам'яних мурах Фортеці Менетіл, — бувалий мореплавець, пов'язаний із морською торгівлею гавані. Як член команди «Дівочої Чесноти», він ходить небезпечними морськими шляхами, що з'єднують болота Каз Модану з далекими берегами. Флінт не обмежується корабельною рутиною: він скеровує здібних шукачів пригод до союзників за Великим Морем, зокрема до знайомих у Калімдорі на кшталт Фіори Лонґірс."}},faq={{q="Хто такий Рудий Джек Флінт?",a="Рудий Джек Флінт — моряк-людина з команди «Дівочої Чесноти». Він перебуває у Фортеці Менетіл у Гавані Менетіл і допомагає налагоджувати зв'язки між Східними Королівствами й Калімдором.",al={"хто такий флінт","лор рудого джека флінта","що робить флінт"}},{q="Де знайти Рудого Джека Флінта?",a="Він відпочиває у Фортеці Менетіл — головній кам'яній твердині, що боронить Гавань Менетіл у Багнокраї.",al={"місце рудого джека флінта","де флінт","знайти рудого джека флінта"}},{q="На якому кораблі ходить Рудий Джек Флінт?",a="Він служить на «Дівочій Чесноті» — торговому судні, що ходить із Гавані Менетіл.",al={"корабель флінта","яким кораблем ходить рудий джек","чеснота діви"}},{q="До кого Рудий Джек Флінт посилає мандрівників?",a="Він радить мандрівникам зв'язатися з Фіорою Лонґірс — знайомою, що живе за Великим Морем, на Темному Узбережжі.",al={"завдання флінта","фіора лонґірс зв'язок","куди флінт посилає"}}},fp="14,251,25.430.0,22.196.0,34.115.0,38.89.0,46.114.0"}
P.entries["npc:rejold-barleybrew"] = {n="Реджолд Барліброю",s="Реджолд Барліброю — майстер-пивовар із дворфів, що оселився в прибережному Селі Брюнолл на заході Дун Мороґу. Відданий удосконаленню міцних гірських напоїв, він раз у раз залучає мандрівників збирати місцеві інгредієнти й випробовувати його потужні рецепти по всій засніженій долині.",h="Реджолд Барліброю — майстер-пивовар із дворфів, що оселився в прибережному Селі Брюнолл на заході Дун Мороґу.",kw={"реджолд барліброю","пивовар","село брюнолл","стаут","ель","дун мороґ"},ang={["faction:Alliance"]="Стаут Реджолда підтримує бойовий дух Альянсу по всьому Дун Мороґу, зміцнюючи вартових і мандрівників, які зносять набіги трогів та люті хуртовини.",["profession:Cooking"]="Кулінари-мандрівники оцінять, як Реджолд шукає бездоганні інгредієнти й вивіряє рецепти, ставлячись до пивоваріння як до точного й шанованого мистецтва.",["race:Dwarf"]="Для дворфів Реджолд уособлює горду горянську традицію варити міцний ель, що дає тепло й силу проти лютого зимового холоду Каз Модану."},sec={{t="Майстер своєї справи",b="У Дун Мороґу пивоваріння — не просто ремесло, а справжнє мистецтво, яке визначає характер краю. Реджолд Барліброю втілює цю традицію в Селі Брюнолл, що притулилося біля замерзлого озера на річці Крижаного Потоку. Замість задовольнятися звичайним шинковим пійлом, Реджолд невпинно вдосконалює свої купажі, шукаючи рідкісний хміль, гірські мінерали та чисту талу воду, щоб варити стаути, здатні зігріти найміцніших дворфських воїнів."},{t="У пошуках досконалого стауту",b="Реджолд невтомний у своєму прагненні до ідеального смаку: він розсилає заповзятливих мандрівників по всьому Дун Мороґу збирати найважливіші складники для напоїв на кшталт Мерехтливого стауту. Чи то обмінюючись послугами з пілотами облогових машин зі Складу Стілґрила, чи то влаштовуючи доставку спраглим гостям, він дбає, щоб холодні, повні трогів дороги Дун Мороґу можна було стерпіти завдяки щедрому запасу доброго елю."}},faq={{q="Хто такий Реджолд Барліброю?",a="Реджолд Барліброю — дворф-пивовар, що живе в Селі Брюнолл у Дун Мороґу. Він присвятив себе створенню легендарних дворфійських елів і залучає мандрівних шукачів пригод приносити складники й доставляти дослідні напої.",al={"реджолд","хто такий реджолд","реджолд барліброю"}},{q="Де знайти Реджолда Барліброю?",a="Реджолд у Селі Брюнолл, на заході Дун Мороґу, біля замерзлих вод Улоговини Крижаного Потоку.",al={"місце реджолда","де реджолд барліброю","реджолд пивоварня"}},{q="Над чим працює Реджолд?",a="Реджолд удосконалює міцні гірські рецепти, зокрема свій фірмовий Мерехтливий стаут і нові дослідні елі, для яких потрібні холодостійкі гірські рослини й особливі пивоварні складники з засніжених пагорбів.",al={"завдання реджолда","завдання ідеального стауту","що вариться в реджолда"}},{q="Чому Реджолд посилає мандрівників до гномів?",a="Насправді його доручення пов'язують його з дворфами, а не з гномами: Пілот Беловфіз зі Складу Стілґрила посилає мандрівників до Реджолда по партію Вічносяйва, а Мерехтливий стаут Реджолда вирушає до його брата, Горянина Барліброу.",al={"реджолд гноми","реджолд вічносяйво","беловфіз реджолд"}},{q="Що таке Мерехтливий стаут?",a="Мерехтливий стаут — відомий міцний дворфійський напій, який варить Реджолд Барліброю з особливих гірських складників: саме вони дають йому характерну силу, що так до речі в морозну зиму.",al={"що таке мерехтливий стаут","історія мерехтливого стауту"}}},fp="17,286,21.423.0,32.395.0,25.223.0,37.131.0,26.212.0,41.231.0,22.187.0"}
P.entries["npc:rema-schneider"] = {n="Рема Шнайдер",s="Рема Шнайдер — містянка, людина, що працює в «Кравецькій майстерні на Каналах» у Стормвінді. Майстерня стоїть над тихими водними шляхами між головними кварталами міста, а сама Рема часто допомагає місцевим крамарям і ремісникам із торговими доставками.",h="Рема Шнайдер — містянка, людина, що працює в «Кравецькій майстерні на Каналах» у Стормвінді.",kw={"рема шнайдер","кравецтво","канали","стормвінд","доручення","крамниця"},ang={["faction:Alliance"]="Мандрівники й новобранці в Стормвінді часто виконують для Реми прості доручення гінця, поки звикають до столиці.",["profession:Tailoring"]="Рема працює в «Кравецькій майстерні на Каналах» і давно стала звичною частиною кравецького ремесла Стормвінда."},sec={{t="Крамарка з Каналів",b="У «Кравецькій майстерні на Каналах», що стоїть одразу на захід від кам'яного мосту до Соборної Площі, Рема Шнайдер дбає про щоденні потреби міської торгівлі. Як і багато вправних ремісників і помічників по всьому місту, вона стежить, щоб тканина й готовий одяг не застоювалися, а переходили від майстра до майстра, — і покладається на послужливих гінців, які носять припаси між майстернями."}},faq={{q="Де працює Рема Шнайдер?",a="Рема Шнайдер працює в кравецькій майстерні біля Каналу в Стормвінді. Крамниця стоїть над північними каналами, трохи на захід від мосту на Соборну Площу.",al={"місце реми шнайдер","де рема","знайти рему шнайдер"}},{q="Яку роль Рема відіграє в Стормвінді?",a="Вона посередниця й дає завдання в місцевих торгових справах: допомагає узгоджувати пакунки з припасами й замовлення на поповнення запасів між торговцями й ремісниками по всьому місту.",al={"хто така рема шнайдер","що робить рема","роль реми шнайдер"}},{q="Чи навчає Рема кравецтва?",a="Ні. Хоча вона працює в кравецькій майстерні біля Каналу й відає поставками кравецьких товарів, вона не наставниця ремесла й не головна продавчиня.",al={"чи рема тренер кравців","навчання кравецтва реми"}}},fp="14,240,24.376.0,32.180.0,38.169.0,26.146.0"}
P.entries["npc:remulos"] = {n="Ремулос",s="Хранитель Ремулос — напівбог, син Кенарія й шанований захисник Місячного Гаю. Разом із верховним друїдом Фандралом Стаґгелмом і Хамуулом Рунтотемом він допомагає вести Коло Кенарія, поки його полеглого батька немає, а Малфуріон Стормрейдж спить. На відміну від Стаґгелма, Ремулос ставить рівновагу всієї природи вище за відлюдність нічних ельфів.",h="Хранитель Ремулос — напівбог, син Кенарія й шанований захисник Місячного Гаю.",kw={"ремулос","хранитель","місячний гай","коло кенарія","кенарій","друїди","стаґгелм"},ang={["class:Druid"]="Кожен друїд — нічний ельф чи таурен — вирушає до Місячного Гаю, щоб поспілкуватися з Хранителем Ремулосом і дістати настанови щодо звірячих подоб і священних випробувань.",["race:Tauren"]="Таурени-друїди шанують Ремулоса за те, що він пішов наперекір Фандралові Стаґгелму й дав їхньому народові вхід до Кола Кенарія та повне навчання в ньому."},sec={{t="Володар священного гаю",b="Хранитель Ремулос — безсмертний хранитель гаю: нижня частина тіла в нього — як у могутнього оленя, а торс увінчаний рогами, наче в прадавнього батька дріад. Він стереже Місячний Гай — священний притулок друїдів Азерота на північ від Гори Гіджал. Поки Малфуріон Стормрейдж лишається в полоні Смарагдового Сну, Ремулос дає смертним із Кола Кенарія божественну владу й пораду. Він щиро прагне загоїти рани Азерота й допомагає друїдам, які звершують свої священні обряди довкола Озера Елуне'ара."},{t="Розкол у Колі",b="Ремулос часто розходиться в поглядах із верховним друїдом Фандралом Стаґгелмом. Стаґгелм обстоює зверхність нічних ельфів і намагався повернути їм утрачене безсмертя за допомогою Тельдрассила, тоді як Ремулос рішуче виступав проти того, щоб садити нове Світове Древо, вважаючи це пихою. Усупереч відлюдницькому угрупованню Стаґгелма, Ремулос прийняв до Кола Кенарія Хамуула Рунтотема й тауренів і відкрив їхнім шаманам, що стали друїдами, ретельно бережені таємниці природи, щоб зцілювати землю спільно."}},faq={{q="Хто такий Хранитель Ремулос?",a="Він безсмертний син Кенарія й брат полеглого Заетара. Ремулос живе у Святилищі Ремулоса в Місячному Гаю, оберігає гай і є одним зі старших очільників Кола Кенарія.",al={"лор ремулоса","хто такий ремулос","минуле хранителя ремулоса"}},{q="Чому Ремулос підтримує тауренів-друїдів?",a="Ремулос вважає, що рівновага природи стоїть понад расовими поділами смертних. Визнаючи глибокий зв'язок тауренів із Земною Матір'ю, Ремулос переступив через заперечення Архідруїда Фандрала Стаґгелма й прийняв до Кола Кенарія Архідруїда Гамуула Рунтотема та його народ.",al={"ремулос таурени","чому в тауренів є друїди","ремулос гамуул"}},{q="Що Ремулос думає про Тельдрассил?",a="Ремулос рішуче виступав проти створення Тельдрассила. Він бачив у висадженні нового Світового Дерева себелюбну спробу нічних ельфів повернути втрачене безсмертя, а не справу заради справжнього зцілення Азероту.",al={"ремулос світове дерево","ремулос фандрал дерево"}},{q="Що пов'язує Ремулоса з Мародоном?",a="His brother Zaetar ventured into Desolace and mated with Princess Theradras, becoming the father of the centaur before his death. Remulos warned Zaetar against that union, and Maraudon holds the legacy of his brother and the centaur.",al={"ремулос зетар","ремулос терадрас","брат ремулоса"}}},fp="7,351,24.516.0,20.506.0,22.203.0,43.265.0,40.231.0,44.233.1"}
P.entries["npc:remy-two-times"] = {n="Ремі \"Двічі\"",s="Ремі «Двічі» — людський крамар, що нині живе в селищі Ґолдшир. Його батьківщина — Гори Редріджу, а впізнати його легко за дивною звичкою повторювати кінці речень. Він має ділові інтереси по всьому Лісі Елвінн: торгує товарами й платить шукачам пригод за сировину на кшталт золотого пилу.",h="Ремі «Двічі» — людський крамар, що нині живе в селищі Ґолдшир.",kw={"ремі двічі","крамар","ґолдшир","золотий пил","редрідж","мурлоки"},ang={["faction:Alliance"]="Для новобранців Альянсу, що прибувають у Ґолдшир, Ремі пропонує нескладні завдання, які допомагають усунути місцеві загрози й водночас дають швидку монету.",["profession:Mining"]="Рудокопи, що працюють у копальнях Фарґодіп і Яшмовій, часто перетинаються з Ремі, який залюбки торгується за золотий пил, зібраний у кобольдів, що там заполонили."},sec={{t="Крамар із дивною звичкою",b="Працюючи з Ґолдширу, Ремі «Двічі» — заповзятливий торговець, що прийшов на захід із суворих земель Гір Редріджу. Вірний своєму прізвиську, Ремі має характерну мовну звичку: повторює останні слова своїх речень, зазвичай двічі. Попри кумедну манеру мовлення, він лишається тямущим крамарем, що хоче заробити серед дедалі більших негараздів Лісу Елвінн і охоче укладає угоди з мандрівними шукачами пригод."},{t="Справи в неспокійних водах",b="Кобольди заполонили тутешні золоті копальні, агресивні мурлоки обсіли береги річок, і звичайна торгівля в Елвінні зазнала тяжких збитків. Ремі вбачає нагоду там, де інші бачать лихо: він доручає шукачам пригод приносити йому кисети золотого пилу, зібраного зі шкідників у копальнях, і стежить за підозрілими пересуваннями мурлоків біля Кришталевого Озера."}},faq={{q="Чому його звуть «Двічі»?",a="Ремі дістав своє прізвисько через дивну мовну звичку: щоразу, коли говорить, він повторює останні слова речення двічі.",al={"чому його звуть двічі","чому ремі повторює слова","значення двічі"}},{q="Звідки родом Ремі?",a="Він прибув до Ґолдшира з Гір Редріджу, щоб торгувати в самому серці Лісу Елвінн.",al={"звідки ремі","походження ремі"}},{q="Що Ремі робить із золотим піском, який скуповує?",a="Як спритний торговець, Ремі збирає золотий пісок, який відбирають у кобольдів у місцевих копальнях, щоб переплавляти, вимінювати чи перепродувати його з добрим зиском.",al={"навіщо ремі золотий пісок","обмін золотого піску лор"}},{q="Де знайти Ремі в Ґолдширі?",a="Ремі стоїть надворі в Ґолдширі, у Лісі Елвінн, біля корчми «Лев'яча Гордість», готовий поторгуватися з перехожими мандрівниками.",al={"де ремі двічі","місце ремі в ґолдширі"}}},fp="16,343,28.449.0,27.381.0,29.153.0,37.104.0,49.158.0,37.118.0"}
P.entries["npc:renato-gallina"] = {n="Ренато Галліна",s="Ренато Галліна — енергійний зазивала, який розхвалює торгівлю на гамірних вулицях Торгового Кварталу Стормвінда. Він належить до родини виноробів Галліна, і його робота — заманювати покупців і скеровувати спраглих подорожніх до родинної виноробні, що сховалася вздовж міських каналів.",h="Ренато Галліна — енергійний зазивала, який розхвалює торгівлю на гамірних вулицях Торгового Кварталу...",kw={"ренато галліна","зазивала","виноробня галліна","торговий квартал","вино","стормвінд"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що прибувають до столиці, Ренато — швидке знайомство з місцевою торгівлею й ремеслами Стормвінда."},sec={{t="Голос виноробні Галліна",b="Серед людних яток Торгового Кварталу Ренато Галліна цілими днями гукає до перехожих, сміливо проголошуючи, що його родина продає найкращі вина в усьому Стормвінді. Родина тримає виноробню Галліна неподалік, на Каналах, а Ренато — її вуличний голос: він роздає оголошення кожному, хто готовий рознести звістку про їхній льох спраглим мандрівникам по всьому королівству."}},faq={{q="Хто такий Ренато Галліна?",a="Ренато — зазивало в Торговому Кварталі Стормвінда. Він належить до родини Галліна й проводить дні, рекламуючи родинну виноробню місцевим мешканцям і мандрівним шукачам пригод.",al={"хто такий ренато","ренато галліна","крамар вина стормвінд"}},{q="Де розташована Виноробня Галліни?",a="Виноробня Галліни стоїть на Каналах Стормвінда, трохи осторонь від гамірних вулиць головних торгових кварталів.",al={"де винарня галліни","винна крамниця стормвінда","винарня галліни"}},{q="Про що Ренато просить шукачів пригод?",a="Ренато дає оголошення про винну крамницю своєї родини, сподіваючись, що охочі посланці поширять звістку й приведуть нових покупців до їхнього льоху біля каналу.",al={"завдання ренато галліни","завдання реклами вина","чого хоче ренато"}}},fp="14,261,27.432.0,22.193.0,36.136.0,39.162.0"}
P.entries["npc:renee-lauer"] = {n="Рене Лауер",s="Рене Лауер — корчмарка Таверни «Шибеничний Кінець» у Бріллі, що дає притулок, їжу й питво мандрівникам, які проходять Галявинами Тірісфалю. За життя вона була ревною капітанкою Багряного Хрестового Походу, і її криваве минуле скінчилося контрударом Відступників, який забрав життя і їй, і її небожеві.",h="Рене Лауер — корчмарка Таверни «Шибеничний Кінець» у Бріллі, що дає притулок, їжу й питво мандрівникам, які...",kw={"рене лауер","корчмарка","таверна шибеничний кінець","багряний хрестовий похід","брілл","стефан"},ang={["race:Undead"]="Рене — суворе нагадування про те, як швидко людські фанатики Багряного Хрестового Походу можуть опинитися по той бік могили й скинути стару догму, звільнившись від життєвих омань."},sec={{t="Від фанатички до корчмарки",b="До свого нежиття Рене була успішною капітанкою: Багряний Хрестовий Похід був її домом і вірою. Переконана, що Лордерон належить суто живим і суто людям, вона без докорів сумління вбивала нелюдів. Її фанатизм обернувся крахом, коли родичі її жертв вистежили табір, щоб помститися. Хоч її небіж Стефан і втрутився, сутичка привернула увагу Леді Сильвани Віндраннер і Варіматраса. Військо Відступників стерло табір: Стефана вбили, а Рене підняли в нежитті. Вражена тим, як її похід накликав загибель на власну рідню, вона цілком покинула ратне життя й узялася тримати Таверну «Шибеничний Кінець», сповнена рішучості плекати, а не вбивати."},{t="Послання для живих",b="Замість шукати помсти Відступникам, які її вбили, Рене спрямовує свій жаль на фанатизм, що прирік її родину. Щоразу, коли полонені багряні хрестоносці чи мандрівники опиняються у Бріллі, вона ділиться своєю історією, застерігаючи їх від безглуздої ненависті. Догму Хрестового Походу вона бачить як нескінченне коло різанини, що гарантує лише горе. Фанатики рідко слухають її порад, та Рене не полишає спроб переконати їх, пропонуючи гостинність і терплячі слова і бранцям, і відвідувачам."}},faq={{q="Хто така Рене Лауер?",a="Рене Лауер — корчмарка з Відступників у таверні «Шибеничний Кінець» у Бріллі. Вона продає їжу, напої й усякі припаси мандрівникам Галявин Тірісфалю.",al={"рене лауер","корчмарка брилла","хто корчмарка в бриллі"}},{q="Чим займалася Рене, перш ніж стала Відступницею?",a="За життя вона була вправною капітанкою й бойовою наставницею Багряного Хрестового Походу. Вона завзято переслідувала й убивала нелюдей, вірячи, що Лордерон належить лише живим людям.",al={"минуле рене лауер","чи рене була в багряних","історія рене"}},{q="Як загинула Рене Лауер?",a="Після того як її жорстокі набіги розпалили ворожнечу, що поставила під загрозу її небожа Стефана, їхній табір захопили Відступники на чолі із Сильваною Віндраннер і Варіматрасом. Стефан загинув, а Рене вбили й підняли як нежить.",al={"як померла рене","смерть рене лауер","хто вбив рене"}},{q="Чому вона стала корчмаркою, а не воїном?",a="Смерть відкрила їй очі: одержима жорстокість Багряного Хрестового Походу не дала нічого, крім загибелі її близьких. У нежитті вона обрала ремесло, що дає турботу й притулок, а не забирає життя.",al={"чому рене корчмарка","чому рене перестала воювати"}},{q="Що пов'язує Рене з Келвіном Монтеґ'ю?",a="У завданні «Угода розбійника» шукачів пригод, що виконують доручення Келвіна Монтеґ'ю, посилають передати листа просто Рене в таверну «Шибеничний Кінець».",al={"угода розбійника рене","лист келвіна монтеґ'ю"}}},fp="11,296,24.661.0,24.516.0,19.155.0,45.188.0,24.228.0,53.235.0,46.152.0"}
P.entries["npc:renzik-the-shiv"] = {n="Рензік \"Ніж\"",s="Рензік \"Ніж\" — гоблін-агент і довірений заступник очільника SI:7, що перебуває в їхній штаб-квартирі в Старому Місті Стормвінда. Він вірно служить майстрові шпигунів Матіасу Шоу, керує новобранцями-розбійниками й веде таємні операції там, куди звичайним агентам Альянсу не ступити.",h="Рензік \"Ніж\" — гоблін-агент і довірений заступник очільника SI:7, що перебуває в їхній штаб-квартирі в...",kw={"рензік","si:7","матіас шоу","старе місто","стормвінд","розбійник","гоблін","луціус"},ang={["class:Rogue"]="Для розбійника Альянсу Рензік — ваш місток від вуличної роботи ножем до мережі розвідки SI:7, де ставки найвищі; він відсіює нерозважливих, перш ніж послати вас до Луціуса в Редрідж.",["faction:Alliance"]="Хоч Рензік і гоблін, він — один із найздібніших розвідників Стормвінда й керує операціями на ворожих землях, де людського шпигуна викрили б із першого погляду.",["race:Human"]="Рензік, що стоїть поруч із майстром шпигунів Шоу в Старому Місті, — рідкісний гоблін серед військової еліти королівства, і він доводить: у тіньових війнах вірність і вміння важать більше за расу."},sec={{t="Гоблін у SI:7",b="Про своє минуле Рензік мовчить. Стормвінду відомо лише те, що цей гоблін якось потрапив до SI:7 і тепер є заступником майстра шпигунів Матіаса Шоу. Товариства він не надто любить, але платня добра, і він цінує повагу, яку дає його посада: Рензік вважає себе одним із небагатьох гоблінів, які можуть чесно сказати, що їх поважають, а не просто бояться."},{t="Права рука Матіаса Шоу",b="Тепер Рензік, що перебуває в таємній фортеці SI:7 у Старому Місті, — заступник Матіаса Шоу. Більшість розвідників — люди, дворфи чи гноми, які в Калімдорі одразу впадають в око, тож гоблінське походження Рензіка робить його незамінним для проникнення до Оргріммара й інших земель Орди. Наставники розбійників з усього Альянсу — від Прихованого Кола в Айронфорджі до тіньових агентів у Дарнасусі — посилають до Рензіка своїх найздібніших учнів. Та замість кидати їх просто на забій, Рензік скеровує їх до польових інструкторів, як-от Луціуса в Редріджі, щоб ті відточили мистецтво виживання."}},faq={{q="Чому гоблін працює на SI:7 Стормвінда?",a="Рензік тримає при собі історію про те, як потрапив до Стормвінда. Він цінує сталу платню й щиру повагу, яку здобув у SI:7, і пишається тим, що його поважають, а не просто бояться. До того ж його гоблінське обличчя — неабияка перевага: він може працювати в Оргріммарі та інших землях Орди, де агенти-люди, дворфи чи гноми впадали б у вічі.",al={"чому гоблін працює на таємну службу","чому рензік альянсу","гоблін у стормвінді"}},{q="Чому його звуть «Ніж»?",a="Рензік ніколи не розповідав Стормвінду, звідки взялося це прізвисько. Усе, що знають у Старому Місті, — саме прізвисько, і для шпигуна, мабуть, у цьому й річ.",al={"чому ніж","прізвисько рензіка","значення ніж"}},{q="Що Рензік робить для гравців-розбійників?",a="Коли розбійники Альянсу доводять свою вправність, наставники посилають їх до Рензіка в Стормвінд. Він приймає їх до SI:7 і посилає новобранців до особливих наставників на кшталт Луціуса в Горах Редріджу, щоб вони набули польових навичок і лишилися живими.",al={"завдання розбійника рензіка","що дає рензік","поговорити з рензіком ножем"}},{q="Де зазвичай діє Рензік?",a="Він служить у штабі SI:7 у Старому Місті Стормвінда. А в ширшій розвідувальній роботі його гоблінська подоба дозволяє йому злитися з натовпом і вести шпигунські операції там, куди звичайним агентам Альянсу шлях закритий, як-от в Оргріммарі.",al={"місце рензіка","де шукати рензіка","де рензік"}},{q="Чи має Рензік зв'язки за межами Стормвінда?",a="Так. У розвідувальній мережі Альянсу він співпрацює з розбійницькими спільнотами, зокрема з дворфійським Прихованим Колом в Айронфорджі й агентами нічних ельфів у Дарнасусі, поєднуючи тіньові мережі обох континентів.",al={"мережа рензіка","зв'язки рензіка","союзники рензіка"}}},fp="17,297,16.382.0,26.626.0,45.321.0,28.147.0,38.268.0,34.253.0,44.227.0"}
P.entries["npc:rethiel-the-greenwarden"] = {n="Ретіель Зеленовартовий",s="Ретіель Зеленовартовий — прадавній розумний болотяний звір, що живе в Зеленому Поясі в Багнокраї. Він тонко відчуває природну рівновагу боліт, оберігає цю землю й закликає мандрівників винищувати загрози, що порушують її злагоду.",h="Ретіель Зеленовартовий — прадавній розумний болотяний звір, що живе в Зеленому Поясі в Багнокраї.",kw={"ретіель зеленовартовий","багнокрай","зелений пояс","болотяний звір","мохошкірі гноли","рівновага природи"},ang={["class:Druid"]="Ретіель — незвичний вияв дикої рівноваги Азерота: він говорить просто від імені пораненої природи, подібно до прадавніх охоронців Калімдору.",["class:Shaman"]="Ретіель, чутливий до розладу стихій і плоті боліт, вторує стражданню самої землі, що стогне від отрути й вогню."},sec={{t="Охоронець боліт",b="Ретіель, що височіє серед вологих хащів Зеленого Поясу, — велетенське створіння з моху, торфу й первісної рослинної плоті. Багато болотяних звірів тиняються драговинами як безтямні хижаки, а Ретіель має рідкісну свідому тяму й журливий голос. Для нього болота — не просто каламутна місцевість, а живий світ, який нині стогне під тягарем зайд-хижаків і порчі."},{t="Загоєння ран",b="Ретіель прагне полегшити страждання Багнокраю, посилаючи співчутливих шукачів пригод проти головних його кривдників. Він закликає мандрівників винищувати руйнівних мохошкірих гнолів, що нищать звірину, забирати в них грубі кремені, якими вони підпалюють живі дерева боліт, і проріджувати хворих болотяних повзунів, що гниють у болотяних водах. Так, крок за кроком, він сподівається повернути спокій пораненій землі."}},faq={{q="Хто такий Ретіель Зеленовартовий?",a="Ретіель — розумне болотяне чудовисько, що живе в Зеленому Поясі в Багнокраї. На відміну від безмозких створінь свого роду, він може спілкуватися зі смертними й захищає болота.",al={"хто такий ретіель","лор ретіеля","болотне чудовисько мокрих земель"}},{q="Де знайти Ретіеля?",a="Він у Зеленому Поясі на сході Багнокраю, на північний схід від Дун Алґазу.",al={"місце ретіеля","де ретіель"}},{q="Навіщо Ретіелю допомога мандрівників?",a="Ретіель відчуває, що болота страждають. Він шукає шукачів пригод, які позбавлять край загроз-зайд — руйнівних зграй гнолів Мохошкірих, грубих кресал, якими вони підпалюють дерева на болотах, і хворих болотяних повзунів, — щоб дати землі полегшення.",al={"чому ретіель дає завдання","мета ретіеля","чого хоче ретіель"}},{q="Чи всі болотяні чудовиська розумні, як Ретіель?",a="Більшість болотяних чудовиськ Азероту діють на чистому ворожому інстинкті й не мають вищого розуму. Ретіель — виняткове створіння, якому глибокий зв'язок із природою дав розум і мову.",al={"чи говорять болотні чудовиська","розумні болотні чудовиська","чому ретіель говорить"}},{q="На яких загрозах зосереджується Ретіель?",a="Він прагне приборкати агресивних гнолів Мохошкірих, відібрати в них грубі кресала, якими вони палять живе дерево, і вичистити хворих болотяних повзунів, що розплодилися на болотах.",al={"завдання ретіеля","вороги ретіеля","загрози мокрим землям"}},{q="Ретіель на боці Альянсу чи Орди?",a="Ретіель привітний до Альянсу й ворожий до Орди. Він дбає про добробут землі й просить допомоги в мандрівників Альянсу, готових зцілити болота.",al={"чи ретіель альянсу","фракція ретіеля","чи орда може говорити з ретіелем"}}},fp="23,246,21.432.0,18.425.0,31.188.0,25.82.0,44.264.0,41.195.0,35.174.0,50.165.0"}
P.entries["npc:rezlak"] = {n="Резлак",s="Резлак — гоблін-підприємець і член Спілки Винахідників, що влаштувався на запорошених дорогах Дуротару на південь від Оргріммара. Він наймає мандрівних шукачів пригод, щоб повернути свої зниклі припаси й вичистити гнізда гарпій, які порушують зв'язок у краї.",h="Резлак — гоблін-підприємець і член Спілки Винахідників, що влаштувався на запорошених дорогах Дуротару на...",kw={"резлак","гоблін","спілка винахідників","гарпії","припаси","оргріммар","дуротар"},ang={["faction:Horde"]="Хоч Резлак стоїть просто за межами Оргріммара, він утілює суто ділові стосунки між нейтральними гоблінськими спілками та молодою Ордою.",["profession:Engineering"]="Як представник Спілки Винахідників, Резлак понад усе цінує механічну ефективність, практичні інструменти й урятовані деталі."},sec={{t="Прагматичний агент Спілки Винахідників",b="Умостившись біля доріг у каньйоні, що з'єднують Гострий Пагорб з Оргріммаром, Резлак представляє Спілку Винахідників — гоблінську спілку, зосереджену на інженерії, постачанні та промисловому прагматизмі. Резлака мало обходять фракційні тертя Калімдору, доки справи йдуть гладко. Коли люті гарпії Пилового Вітру напали на його вантажні каравани й порушили місцеві лінії зв'язку, Резлак лишився на місці, воліючи передоручити небезпечну роботу з винищення та повернення вантажу будь-якому перехожому, охочому заробити."}},faq={{q="Хто такий Резлак?",a="Резлак — незалежний гоблін-торговець та інженер, пов'язаний зі Спілкою Винахідників. Він стоїть при головній північній дорозі через Дуротар і шукає охочих найманців, щоб убезпечити свої шляхи постачання й відбити загублене спорядження в місцевих шкідників.",al={"лор резлака","хто такий резлак","резлак дуротар"}},{q="Що Резлак робить у Дуротарі?",a="Резлак працює на торгових шляхах між центральними рівнинами й каньйоном, що веде до Оргріммара. На його каравани з припасами напали гарпії Пилового Вітру: вантаж розкидано посушливими каньйонами, а важливі лінії зв'язку перерізано.",al={"чому резлак у дуротарі","мета резлака","місія резлака"}},{q="Які завдання дає Резлак?",a="Резлак дає два головні завдання: «Вітри в пустелі», у якому шукачі пригод збирають розкидані на дні каньйону мішки з утраченими припасами, і «Убезпечити шляхи», у якому треба прорідити агресивних гарпій Пилового Вітру, що гніздяться поблизу.",al={"завдання резлака","які завдання дає резлак"}},{q="Що таке Спілка Винахідників?",a="Спілка Винахідників — заповзятлива гоблінська торгова спілка, що опікується механіками, винахідниками й постачанням. Як і в багатьох гоблінських картелях і гільдіях, її члени ставлять вигідну торгівлю й практичне розв'язання проблем вище за політичну вірність.",al={"спілка винахідників","фракція резлака"}}},fp="6,256,32.521.0,14.244.0,32.255.0,31.255.0,27.261.0"}
P.entries["npc:rhahk-zor"] = {n="Рагк'Зор",s="Рагк'Зор — кремезний огр, головний наглядач у Мертвих Копальнях. Він стежить за підземним будівництвом Едвіна Венкліфа й тримає робітників та гірників Дефіас у покорі грубою силою й важкою рукою.",h="Рагк'Зор — кремезний огр, головний наглядач у Мертвих Копальнях.",kw={"рагк'зор","огр","наглядач","мертві копальні","дефіас","мунбрук"},ang={["class:Warrior"]="Бій із Рагк'Зором — випробування чистої витривалості на передовій проти велетенського огра з кувалдою, що трощить і камінь, і кістки.",["faction:Alliance"]="Для шукачів пригод Альянсу, що пробиваються в Мунбрук, Рагк'Зор — перший похмурий доказ того, що Братство Дефіас виросло з дрібного розбою на дорогах у добре укріплене військо.",["profession:Mining"]="Рагк'Зор жене гірників із грубою жорстокістю, не шануючи золотих жил, і перетворює славетні старі копальні Вестфолу на поспіхом зведену воєнну фабрику."},sec={{t="Майстер глибин",b="Глибоко під пологими пагорбами Вестфолу Братство Дефіас перетворило покинуті золоті копальні Мунбрука на підземну фортецю. Таке розлоге будівництво потребує суворої дисципліни, і цю роль виконує огр Рагк'Зор. Призначений головним наглядачем, він керує бригадами копачів і робітниками, підганяючи їх прокладати тунелі й утілювати таємні задуми Венкліфа."},{t="Переконання кулаком",b="Рагк'Зор тримає лад невтомними м'язами, а не продуманою інженерією. Озброєний величезним молотом із кам'яним бойком, нагляд за роботою він розуміє прямо й безжально. І копачі Дефіас, і гобліни-інженери спритно обходять його стороною, знаючи: відставання від графіка чи непослух закінчиться нищівним ударом височенного наглядача."}},faq={{q="Хто такий Рагк'Зор?",a="Рагк'Зор — огр, головний десятник і наглядач Братства Дефіас у Мертвих Копальнях. Він стереже перші розкопні тунелі й стежить, щоб робітники копали й не виходили за межі дозволеного.",al={"рагк'зор","хто огр бос у мертвих копальнях","перший бос мертвих копалень"}},{q="Чому огр працює на Братство Дефіас?",a="Повстання Едвіна Венкліфа тримається на будь-якій силі й найманому хисті, які вдається роздобути. Огр наганяє страху як ніхто, тож Рагк'Зор — ідеальний наглядач, щоб підганяти виснажливу працю в копальнях.",al={"чому огр у мертвих копальнях","рагк'зор дефіас"}},{q="Яка робота Рагк'Зора в копальнях?",a="Він головний десятник будівництва. Рагк'Зор наглядає за шахтарями, гоблінами й будівельниками Дефіас, поки ті видовбують печери, лагодять обладнання й зводять укріплення для Братства.",al={"що робить рагк'зор","роль рагк'зора"}},{q="Де в Мертвих Копальнях Рагк'Зор?",a="Рагк'Зор стереже перші зали кар'єру в Мертвих Копальнях, за першими шахтарськими тунелями, просто перед важкими залізними дверима, відомими як Двері Рагк'Зора.",al={"місце рагк'зора","де рагк'зор"}},{q="Чи пов'язаний Рагк'Зор з ограми часів Першої війни?",a="Колись, під час Першої війни, у Мертвих Копальнях жили огри, доки Орда Блекгенда їх не винищила. Чи Рагк'Зор — уцілілий нащадок тих давніх кланів, чи просто громило, найняте Венкліфом, не підтверджено.",al={"огри першої війни в копальнях","лор огрів мертвих копалень"}},{q="Що стається, коли Рагк'Зора переможено?",a="Перемога над Рагк'Зором ламає владу Дефіас над зовнішнім кар'єром: шлях крізь укріплені вибухостійкі двері, які він стереже, відкривається, і непрохані гості можуть пройти глибше, до потаємних верфей і майстерень.",al={"двері рагк'зора","після рагк'зора"}}},fp="9,243,23.412.0,16.365.0,17.234.0,50.231.0,37.203.0,44.169.0,67.221.0,40.202.0"}
P.entries["npc:rhinag"] = {n="Рінаґ",s="Рінаґ — уражений отрутою троль із джунглів, що знайшов притулок у скромній оселі на Фермі Кам'яного Ікла в Дуроторі. Паралізований сильною отрутою тутешніх скорпіонів, він цілком залежить від перехожих мандрівників, які мають вчасно дістати йому ліки.",h="Рінаґ — уражений отрутою троль із джунглів, що знайшов притулок у скромній оселі на Фермі Кам'яного Ікла в...",kw={"рінаґ","скорпід","отрута","ферма кам'яного ікла","протиотрута","троль","дуротар"},ang={["race:Troll"]="Знайти родича, якого звалила тутешня звірина в посушливих пустках Дуротару, — суворе нагадування про випробування, що постають перед племенем Темного Списа, коли воно вибудовує дім поряд з Ордою."},sec={{t="Отруйна небезпека",b="Перетинаючи посушливі землі Дуротару, Рінаґ став жертвою лютого жала тутешнього Отрутохвостого Скорпіда. Здоланий сильною отрутою, він зумів доповзти до напівзруйнованого прихистку на Фермі Кам'яного Ікла. Знесилений і відрізаний від усіх, він може вижити лише завдяки комусь, хто пройде повз і матиме рішучість дістати протиотруту отрутохвоста, доки токсини не зробили свого."}},faq={{q="Хто такий Рінаґ?",a="Рінаґ — троль із джунглів, мандрівник, що застряг паралізований на Фермі Кам'яного Ікла в Дуротарі після отруйного укусу місцевого скорпіона.",al={"хто такий рінаґ","лор рінаґа","троль біля рокатаск"}},{q="Де знайти Рінаґа?",a="Він лежить у невеликій будівлі на Фермі Кам'яного Ікла, у центрі Дуротару на південь від Гострого Пагорба.",al={"місце рінаґа","де рінаґ","троль на фермі рокатаск"}},{q="Що з ним сталося?",a="Коли Рінаґ ішов рівнинами Дуротару, його вжалив небезпечний Отрутохвостий Скорпід. Сильна отрута його знесилила, і, щоб знешкодити її, поки вона не вбила його, потрібна протиотрута.",al={"чому рінаґ хворий","що отруїло рінаґа","потреба в ліках передісторія"}}},fp="6,233,16.386.0,14.158.0,26.106.0,21.204.0"}
P.entries["npc:ringo"] = {n="Рінґо",s="Рінґо — невдаха-дослідник із гоблінів, що поліз на розпечені висоти Хребта Вогняного Шлейфу в Кратері Ун'Ґоро. Не витримавши задушливої спеки й отруйних випарів вулкана, він звалився в печері й відчайдушно чекає, щоб хтось допоміг йому спуститися. Його близький друг Спреґґл Фрок тим часом місця собі не знаходить у Притулку Маршала.",h="Рінґо — невдаха-дослідник із гоблінів, що поліз на розпечені висоти Хребта Вогняного Шлейфу в Кратері Ун'Ґоро.",kw={"рінґо","гоблін","хребет вогняного шлейфу","ун'ґоро","спреґґл фрок","супровід","спека"},sec={{t="Надто близько до вогню",b="Гобліни славляться тим, що лізуть у найнебезпечніші місця заради багатства чи дивовиж, але Хребет Вогняного Шлейфу суворий навіть за їхніми мірками. Цей діючий вулкан здіймається посеред Кратера Ун'Ґоро й вивергає попіл, магму та пекучу пару. Рінґо видерся десь до половини південного схилу, коли задушлива спека нарешті його здолала. Покинувши свої речі розкиданими просто біля входу, він заповз у печеру, щоб сховатися від пекельного жару, — і там остаточно знесилів від теплового виснаження."},{t="Важкий спуск схилами",b="Звести Рінґо з гори — уже саме по собі випробування. Гоблін так знесилений зневодненням і тепловим ударом, що раз у раз непритомніє дорогою вниз. Щоб утримати його на ногах, доводиться щедро бризкати на нього з баклаги, а часом і дати добрячого ляпаса, щоб привести до тями. Увесь шлях повз непередбачуваних елементалів і хижаків гори аж до безпечного Притулку Маршала треба пильнувати, доки Рінґо нарешті не зустрінеться зі своїм другом Спреґґлом."}},faq={{q="Хто такий Рінґо?",a="Рінґо — гоблін-дослідник у Кратері Ун'Ґоро, який піднявся вулканічними схилами Хребта Вогняного Шлейфу, але в печері знесилів від страшної спеки.",al={"рінґо","хто такий рінґо","гоблін рінґо"}},{q="Де перебуває Рінґо?",a="Він лежить у печері, що виходить на південь, приблизно на півдорозі вгору схилами Хребта Вогняного Шлейфу, у центрі Кратера Ун'Ґоро.",al={"місце рінґо","де рінґо","знайти рінґо"}},{q="Хто шукає Рінґо?",a="Його добрий друг Спреґґл Фрок, що живе в Притулку Маршала на півночі Ун'Ґоро, дуже переживає через зникнення Рінґо.",al={"хто такий спраґл","друг рінґо","спраґл фрок"}},{q="Чому він раз у раз непритомніє дорогою вниз?",a="Рінґо потерпає від тяжкого теплового удару й зневоднення через жар і випари діючого вулкана на Хребті Вогняного Шлейфу. Щоразу, коли він непритомніє, щоб привести його до тями, потрібна фляжка Спреґґла.",al={"чому рінґо непритомніє","рінґо втрачає свідомість","рінґо падає"}},{q="Що таке Торба Рінґо?",a="Це особиста торба Рінґо, яку він упустив просто біля входу до печери, коли зомлів від спеки, перш ніж заповзти всередину.",al={"торба рінґо","мішок рінґо","загублена торба рінґо"}},{q="Куди Рінґо треба дістатися?",a="Його треба безпечно провести з вулкана через дно кратера до Притулку Маршала, де на нього чекає друг Спреґґл Фрок.",al={"куди вести рінґо","куди рінґо дістатися","кінець супроводу рінґо"}}},fp="5,332,32.512.0,31.488.1,13.158.0,23.134.0,25.138.0,35.196.0,21.138.0,28.131.0"}
P.entries["npc:rivern-frostwind"] = {n="Ріверн Фроствінд",s="Ріверн Фроствінд — нічний ельф, наставник вершників, що несе службу високо на Камені Морозних Шаблезубів у північному Вінтерспрінгу. Разом зі своїм супутником, морозним тигром на ім'я Льодовик, він опікується місцевими зимовими шаблезубами й навчає вершників, яких його орден визнав гідними. Лише найвідданішим поборникам Альянсу випадає честь виростити й осідлати одного з його славетних скакунів.",h="Ріверн Фроствінд — нічний ельф, наставник вершників, що несе службу високо на Камені Морозних Шаблезубів у...",kw={"ріверн фроствінд","морозний шаблезуб","камінь морозних шаблезубів","вінтерспрінг","нічні ельфи","скакун","льодовик"},ang={["faction:Alliance"]="Для Альянсу Ріверн Фроствінд — єдиний, від кого можна отримати рідкісного Морозного Шаблезуба з Вінтерспрінга. Навіть якщо ви не з Дарнасуса, терпіння й наполегливість дозволять вам приборкати одного з найлютіших звірів Калімдору.",["race:NightElf"]="Нічні шаблезуби тісно пов'язані з жрецтвом Елуни та Вартовими Калімдору, а морозні шаблезуби Ріверна — окрема відлюдна порода, виведена саме для суворих сніжних просторів Вінтерспрінгу."},sec={{t="Володар морозних шаблезубів",b="Зі свого крижаного виступу на Камені Морозних Шаблезубів Ріверн Фроствінд наглядає за розведенням легендарних морозних шаблезубів Вінтерспрінгу й піклується про них. Нічні шаблезуби блукають буйними лісами Тельдрассила й Ашенвалю, а їхніх приполярних родичів виводять так, щоб вони витримували лютий холод північного Калімдору. Ріверн — справжній брамник для цих величних хижаків. Від чужинців він вимагає довести, що вони готові оберігати звірів: добути свіжого м'яса в тундрі, прогнати фурболгів Зимопадів і відтіснити розлючених морозних велетнів — і лише тоді він бодай подумає, чи довірити їм дитинча."}},faq={{q="Хто такий Ріверн Фроствінд?",a="Ріверн Фроствінд — нічний ельф, майстер верхової їзди й доглядач фракції Дресирувальників Зимосаблезубів на Камені Морозних Шаблезубів на півночі Вінтерспрінгу. Разом зі своїм вірним тигром Льодовиком він дбає, щоб могутніх місцевих великих кішок захищали й належно вирощували.",al={"лор ріверна фроствінда","тренер шаблезубів","хто такий ріверн"}},{q="Чому він у Вінтерспрінгу?",a="Він живе на Камені Морозних Шаблезубів, щоб вишколювати й оберігати рідкісних білих морозних шаблезубів цього краю. Цим хижакам постійно загрожують люті фурболги Зимопаду, велетні, що підбираються ближче, і суворий клімат, тож Ріверн тримає лад і дбає про їхній добробут.",al={"чому він у вінтерспрінгу","мета скелі шаблезубів"}},{q="Чи можуть гравці Орди працювати з Ріверном?",a="Ні. Ріверн Фроствінд вірний лише нічним ельфам і Альянсу. Мандрівники Орди, що прийдуть до Каменя Морозних Шаблезубів, побачать, що він зовсім не хоче з ними знатися: свою довіру й навчання їзди він зберігає лише для поборників Альянсу.",al={"чи орда може працювати з ріверном","ріверн дружній до орди"}},{q="Що за тигр поруч із ним?",a="Морозний тигр, що лежить поруч із Ріверном, — Льодовик, його особистий супутник і чудовий представник витривалих кішок, які водяться в тундрі Вінтерспрінгу.",al={"хто такий глейшер","тигр ріверна фроствінда"}}},fp="16,367,25.606.0,24.265.0,26.262.0,35.248.0,28.150.0"}
P.entries["npc:roetten-stonehammer"] = {n="Роеттен Стоунгаммер",s="Роеттен Стоунгаммер — заповзятливий дворф, якого можна зустріти в Бібліотеці Зали Дослідників в Айронфорджі. Він представляє інтереси Компанії «Відновлювачі», організовує експедиції й наймає шукачів пригод для рятування майна в далеких краях на кшталт Пустограю.",h="Роеттен Стоунгаммер — заповзятливий дворф, якого можна зустріти в Бібліотеці Зали Дослідників в Айронфорджі.",kw={"роеттен стоунгаммер","компанія «відновлювачі»","зала дослідників","бібліотека","пустограй","айронфордж"},ang={["faction:Alliance"]="Роеттен — важливий зв'язковий Альянсу в Айронфорджі для експедицій, що перетинають море до спірних, безплідних диких земель Пустограю в Калімдорі.",["race:Dwarf"]="Для дворфів, що гортають величні архіви Айронфорджа, Роеттен доводить: археологічна цікавість часто йде пліч-о-пліч із кмітливим комерційним рятуванням майна."},sec={{t="Справи в Бібліотеці",b="Серед давніх фоліантів і пилу Бібліотеки Зали Дослідників Роеттен Стоунгаммер пильнує справ практичного повернення майна. Діючи від імені Компанії «Відновлювачі», Роеттен зводить сміливих найманців із вигідними угодами на рятування майна по всьому Калімдору. Його спільники копають не заради самої історичної цікавості — вони прагнуть повернути цінні вантажі, уламки й рідкісні реагенти з небезпечних прикордонь на кшталт суворих пусток Пустограю."}},faq={{q="Хто такий Роеттен Стоунгаммер?",a="Роеттен Стоунгаммер — дворф, що дає завдання в Бібліотеці Зали Дослідників в Айронфорджі. Він керує справами й шукає здібних людей для Компанії «Відновлювачі», спрямовуючи шукачів пригод на ризиковані пошукові підряди за кордоном.",al={"хто такий роеттен","хто такий роеттен стоунгаммер","лор роеттена"}},{q="Що таке Компанія «Відновлювачі»?",a="Компанія «Відновлювачі» — підприємство, що займається порятунком утрачених вантажів, збиранням рідкісних реагентів і дослідженням цінних уламків у небезпечних диких краях, як-от на узбережжі й серед руїн Пустограю.",al={"що таке відновлювачі","відновлювачі інкорпорейтед","справи відновлювачів"}},{q="Куди Роеттен посилає шукачів пригод?",a="Роеттен посилає вправних мандрівників за море, до Пустограю на заході Калімдору, де його партнери займаються підйомом уламків кораблів і збиранням реагентів на суворому узбережжі й у безплідних нетрях.",al={"завдання роеттена","куди роеттен посилає","справи відновлювачів у пустограї"}}},fp="19,264,23.448.0,27.237.0,24.204.0,36.201.0"}
P.entries["npc:rorian-the-dayseeker"] = {n="Роріан Деньошукач",s="Роріан Деньошукач — шанований старійшина небороджених у Селі Тендаль на Острові Зефрас. Він наглядає за посвятою юних новаків, коли ті відкривають своє покликання, дорослішають і налаштовуються на природні стихії рідного краю. Під його пильним проводом новачки опановують основи виживання, традицій і служіння громаді.",h="Роріан Деньошукач — шанований старійшина небороджених у Селі Тендаль на Острові Зефрас.",kw={"роріан деньошукач","небороджені","село тендаль","острів зефрас","посвята","наставник"},ang={["class:Mage"]="Юні чарівники знаходять у Роріанові чуйного провідника: він посилає початківців у таємній магії до вчителів, здатних відшліфувати їхній сирий чарівний хист.",["class:Shaman"]="Роріан надає величезного значення злагоді острова: він посилає молодь угамовувати збурених елементалів і єднатися з традиціями предків.",["class:Warrior"]="Роріан цінує тілесну відданість майбутніх бійців і скеровує охочих стати воїнами до наставників, які навчають дисципліни на полі бою.",["race:Skyborne"]="Для кожного юного небородженого Роріан Деньошукач — перший поріг обов'язку й традиції: він веде вас до дорослості в Селі Тендаль."},sec={{t="Старійшина Села Тендаль",b="У спокійному затишку Села Тендаль на Острові Зефрас Роріан Деньошукач — один із головних наставників юних небороджених. Шанований за досвід і спокійну мудрість, Роріан скеровує молодь на важливому шляху до дорослості. Саме під його наглядом новаки проходять традиційний обряд посвяти, що засвідчує їхню готовність боронити й підтримувати рідний острів."},{t="Нові покликання",b="Окрім основних випробувань, Роріан указує здібним новакам на особливі шляхи, що пасують до їхніх талантів. Чи то майбутній воїн, мисливець, розбійник, маг, шаман чи друїд — Роріан посилає молодь до відповідних наставників по всьому острову. Він також попереджає їх про розлад стихій, що порушує злагоду острова, і прищеплює їм непохитний обов'язок оберігати рівновагу на обвітрених висотах."}},faq={{q="Хто такий Роріан Деньошукач?",a="Роріан Деньошукач — старійшина й очільник Небороджених у Селі Тендаль на Острові Зефрас. Він головний наставник для шукачів пригод-новачків і молодих Небороджених, що проходять перші випробування.",al={"хто такий роріан","роль роріана","що робить роріан"}},{q="Де знайти Роріана Деньошукача?",a="Він у Селі Тендаль — стартовому поселенні Небороджених на Острові Зефрас.",al={"де роріан","місце роріана","знайти роріана"}},{q="Яка роль Роріана в посвяті Небороджених у дорослість?",a="Роріан керує першими обрядами посвяти, що знаменують перехід молодого Небородженого в дорослість. Він випробовує їхню мужність і злагоду з життям острова, а потім посилає служити всьому поселенню.",al={"роріан дорослішання","наставник небороджених"}},{q="Як Роріан спрямовує новачків до їхніх класів?",a="Коли новачок доводить свою вартість, Роріан радить йому, де здобути подальшу науку, — на шляху воїна, мисливця, розбійника, мага, шамана чи друїда.",al={"завдання класів роріана","вибір класу з роріаном"}},{q="Чому Роріан посилає шукачів пригод до елементалів?",a="Природна рівновага довкола Острова Зефрас легко порушується. Роріан доручає вправним послушникам розвідати й утихомирити збурення стихій, щоб Село Тендаль і довколишні дикі краї жили в злагоді.",al={"неспокій стихій роріан","чому воювати зі стихіями зефрас"}},{q="Хто такий Етін Вітрів?",a="Етін Вітрів — мешканець Острова Зефрас, до якого Роріан посилає молодих, коли ті просуваються у своїх острівних обов'язках і навчанні.",al={"етін вітрів","етін роріан"}}},fp="20,375,24.414.0,24.408.0,28.201.0,40.91.0,52.208.0,55.181.0,57.219.0,28.156.0"}
P.entries["npc:royal-historian-archesonus"] = {n="Королівська Історикиня Архесонус",s="Королівська Історикиня Архесонус — дворфійська вчена, що служить Королю Маґні Бронзбірду на Високому Престолі Айронфорджа. Відома своїми працями про недавні катастрофи в північних людських королівствах, вона також керує дослідженнями давніх дворфійських трагедій, зокрема випалених решток королівства Темного Заліза.",h="Королівська Історикиня Архесонус — дворфійська вчена, що служить Королю Маґні Бронзбірду на Високому Престолі...",kw={"королівська історикиня архесонус","високий престол","війна трьох молотів","тауріссан","темне залізо","лордерон","історія"},ang={["faction:Alliance"]="Її наукові праці зберігають похмурі свідчення про падіння Лордерона, щоб південні союзники розуміли природу чуми й сил, які зламали північні королівства людей.",["race:Dwarf"]="Архесонус береже офіційну пам'ять вашого народу й болючі уроки Війни Трьох Молотів, щоб клан Бронзбірдів не повторив гордині дворфів Темного Заліза."},sec={{t="Літописиця катастроф",b="Королівська Історикиня Архесонус, що стоїть за кілька кроків від трону Короля Маґні Бронзбірда на Високому Престолі, веде історичні записи від імені корони Айронфорджа. Її науковий погляд сягає далеко за гори Каз Модану. Вона написала «Падіння Лордерона й спустошення Іствілду» та «Про чуми, прокляття й пошесті», простеживши жахливий крах північного королівства людей під навалою Погибелі. Архесонус не ховається від темної історії, а методично досліджує катастрофи, прагнучи записати правду про згубну магію й політичний крах."},{t="Попіл Тауріссана",b="Окрім праць про Лордерон, Архесонус керує дослідженнями Війни Трьох Молотів і катастрофічного падіння Імператора Тауріссана. Шукаючи реліквії й обвуглені таблички з Палаючих Степів, вона наймає шукачів пригод, щоб ті обшукали Тліючі Руїни Тауріссана. Для Архесонус розуміння катаклізму, що розколов Гори Редріджу й прив'язав клан Темного Заліза до Володаря вогню, — важлива державна справа: королівство Бронзбірдів має пам'ятати, що можуть накоїти чаклунство й відчай."}},faq={{q="Де знайти Королівську Історикиню Архесонус?",a="Королівська Історикиня Архесонус — на Високому Троні в Айронфорджі, неподалік від тронної зали Короля Маґні Бронзбірда.",al={"місце архесонус","де королівська історикиня архесонус","архесонус айронфордж"}},{q="Які книги написала Королівська Історикиня Архесонус?",a="Вона авторка праць «Падіння Лордерону й спустошення Східнолісся» та «Про чуми, прокляття й пошесті», що описують занепад людської півночі й некротичні недуги, поширені Погибеллю.",al={"книги архесонус","що написала архесонус","книги лору архесонус"}},{q="Чому Архесонус цікавлять Руїни Тауріссана?",a="Вона вивчає давню історію дворфів і посилає розвідників до Палаючих Степів по втрачені реліквії з Руїн Тауріссана, щоб відтворити картину катастрофи, яка знищила стародавню столицю Темного Заліза.",al={"завдання тауріссана архесонус","чому руїни тауріссана","тліючі руїни тауріссана"}},{q="Яка її роль в Айронфорджі?",a="Як офіційна Королівська Історикиня, вона головна літописиця й архіваріус Короля Маґні Бронзбірда: укладає записи і про дворфійську давнину, і про ширші світові події, що загрожують Альянсу.",al={"титул архесонус","що робить королівський історик","хто така архесонус"}}},fp="26,318,25.575.0,23.529.0,44.116.0,48.213.0,56.209.0,30.198.0"}
P.entries["npc:ruga-ragetotem"] = {n="Руґа Рейджтотем",s="Руґа Рейджтотем — тауренський воїн-ветеран, що стоїть у Таборі Тауражо на півдні Пусток. Як наставник багатообіцяльних бійців Орди, він випробовує їх у боротьбі з дивною навалою силітидів, що з'явилася неподалік, а тоді скеровує по обладунки, виготовлені на замовлення.",h="Руґа Рейджтотем — тауренський воїн-ветеран, що стоїть у Таборі Тауражо на півдні Пусток.",kw={"руґа рейджтотем","табір тауражо","силітиди","поле велетнів","воїн","таурени"},ang={["class:Warrior"]="Руґа — важлива віха раннього бойового вишколу: він випробовує ваше бойове чуття в сутичках із силітидами, а тоді скеровує вас до Тун'ґріма Файрґейза по викуваний обладунок.",["race:Tauren"]="Руґа Рейджтотем у Таборі Тауражо уособлює силу й незворушну пильність дітей Земної Матері, що стережуть свої південні простори."},sec={{t="Наставник у Таборі Тауражо",b="Стоячи на варті Табору Тауражо, Руґа Рейджтотем допомагає вишколювати молодих воїнів, які хочуть довести свою силу в Калімдорі. Помітивши раптову й тривожну появу комахоподібних силітидів, що видовбують вулики на Полі Велетнів на півдні, Руґа влаштовує юним бійцям випробування: вполювати цих тварюк і відтяти їм вусики. Ті, хто витримає випробування, здобувають його повагу й рекомендацію до знаного зброяра Тун'ґріма Файрґейза."}},faq={{q="Хто такий Руґа Рейджтотем?",a="Руґа Рейджтотем — таурен-воїн у Таборі Тауражо на півдні Пусток. Він наставник і суддя випробувань для молодих воїнів Орди.",al={"хто такий руґа","лор руґи рейджтотема","руґа таурахо"}},{q="Яке випробування Руґа дає воїнам?",a="Руґа посилає воїнів на південь, на Поле Велетнів, битися з силітидами, що нещодавно там з'явилися. Послушники мають убити цих лютих комахоподібних і принести їхні вусики як доказ своєї відваги й бойової майстерності.",al={"випробування руґи","випробування на полі велетнів","чого хоче руґа"}},{q="До кого Руґа посилає після свого випробування?",a="Коли воїн доведе себе в боротьбі із силітидами, Руґа посилає його на північ до орка-зброяра Тун'ґріма Файрґейза, що кує особливі обладунки для гідних бійців.",al={"де після руґи","наступне завдання руґи","тан'грім руґа"}},{q="Чому Руґу цікавить Поле Велетнів?",a="Поле Велетнів нещодавно захопили силітиди — моторошна загроза з комах, що прокладає вулики в землі. Руґа використовує цю близьку небезпеку як справжню бойову перевірку для воїнів, які прагнуть боронити Орду.",al={"чому поле велетнів","руґа комахи","силітиди таурахо"}}},fp="14,262,24.438.0,22.159.0,38.202.0,42.172.0,46.207.0"}
P.entries["npc:rutgar-glyphshaper"] = {n="Рутґар Ґліфшейпер",s="Рутґар Ґліфшейпер — дворфійський археолог, що перебуває в Таборі Бронзоборода на півдні Силітусу. Як учасник експедиції Бранна Бронзбірда, він вивчає прадавні реліквії й руни силітидів і намагається розгадати таємницю вуликів навіть після того, як Бранн подався блукати пустелею.",h="Рутґар Ґліфшейпер — дворфійський археолог, що перебуває в Таборі Бронзоборода на півдні Силітусу.",kw={"рутґар ґліфшейпер","табір бронзоборода","археолог","силітиди","гліфи","ліга дослідників"},ang={["faction:Alliance"]="Шукачі пригод з Альянсу знаходять тут рідкісний осередок привітних облич посеред суворої південної пустелі, хоча загін Рутґара не має жодної офіційної підтримки від корони Айронфорджа.",["race:Dwarf"]="Дворфи впізнають у Рутґарі вперту відданість Лізі Дослідників: він ризикує життям і здоров'ям глибоко у ворожих вуликах комах заради прадавніх знань."},sec={{t="Експедиція Бронзбірда",b="Рутґар Ґліфшейпер прибув до Силітусу під проводом Бранна Бронзбірда, щоб дослідити величезні вулики силітидів і відкопати загублені реліквії, поховані під пустельними пісками. Облаштувавши базу в Таборі Бронзоборода на південь від Цитаделі Кенаріуса, Рутґар і його товариші часто ходили просто у вулики комах по камені з написами й рунічні артефакти, нерідко разом із дослідниками — нічними ельфами з Кола Кенарія."},{t="Лихо у вуликах",b="Під час походу у Вулик'Реґал разом із жрицею з нічних ельфів Наталією Мар'аліт загін знайшов дивний кристал, укритий гліфами. Реліквія тримала Наталію, мов у трансі, тож дворфам довелося винести її й доставити на зцілення до Цитаделі Кенаріуса. Коли згодом вона в нестямі повернулася до табору дворфів, вимагаючи пустити її назад у вулик, Рутґарові та його експедиції довелося відбиватися від неї у відчайдушній сутичці, після чого вона втекла назад у дюни."},{t="Розгадати силітидів",b="Бранн Бронзбірд, як це з ним часто буває, загадково зник у пустелі, тож Рутґар лишається в таборі й продовжує їхні дослідження. Він збирає відбитки написів із кристалів і розшифровує гліфи комах, розкидані по вуликах силітидів, — намагається скласти докупи історію вуликів і дізнатися, де міг зникнути Бранн."}},faq={{q="Хто такий Рутґар Ґліфшейпер?",a="Це дослідник і вчений, що супроводжував Бранна Бронзбірда в археологічній експедиції до Силітусу, а нині перебуває в Таборі Бронзоборода.",al={"рутґар","хто такий рутґар","про рутґара ґліфшейпера"}},{q="Де Бранн Бронзбірд?",a="Бранн, як завжди, сам-один подався в розвідку пустищами Силітусу, залишивши Рутґара й решту людей підтримувати табір і досліджувати вулики.",al={"де бранн","куди пішов бранн","бранн зник"}},{q="Що сталося з Наталією Мар'аліт у таборі?",a="Піддавшись впливу стародавнього кристала у Вулик'Реґалі, Наталія Мар'аліт повернулася до Табору Бронзоборода в шаленій люті, напала на Рутґара, Бранна й інших, а потім знову зникла в пустелі.",al={"що сталося з наталією","напад наталії","жриця напала на табір"}},{q="Чому Рутґар вивчає кристали силітидів?",a="Рутґар намагається перекласти стародавні гліфи, вирізьблені на кристалах у вуликах, щоб зрозуміти походження силітидів і знайти підказки, де подівся Бранн.",al={"чому ґліфи","що вивчає рутґар","ґліфічні кристали"}},{q="Чи надіслав Айронфордж допомогу експедиції?",a="Ні. Експедиція просила в Айронфорджа військової підтримки, але дворфійське королівство відмовило, пославшись на те, що його сили й так розпорошені на обороні держави.",al={"чи айронфордж надіслав підкріплення","армія айронфорджа сілітус"}},{q="Де розташований Табір Бронзоборода?",a="Він на півдні Силітусу, серед пустельних пісків на південь від Цитаделі Кенаріуса й трохи на захід від Вулик'Реґалу.",al={"де табір бронзоборода","місце табору бронзоборода"}}},fp="18,306,26.434.0,20.478.1,24.352.1,26.155.0,27.186.0,47.223.1,45.186.0,41.167.0,44.116.0"}
P.entries["npc:ruul-eagletalon"] = {n="Руул Іглталон",s="Руул Іглталон — таурен, мешканець Села Бладгуф у Малгорі. Стоячи біля околиці поселення, він пильно стежить за місцевою звіриною, особливо за агресивними гарпіями Вітрофурій, що зазіхають на землі тауренів.",h="Руул Іглталон — таурен, мешканець Села Бладгуф у Малгорі.",kw={"руул іглталон","гарпії","вітряна лють","варта","село бладгуф","малгор"},ang={["race:Tauren"]="Руул уособлює практичну пильність, якої вимагають від шу'гало: новознайдений прихисток Малгору має лишатися безпечним від територіальних хижаків і крилатих нападників."},sec={{t="Сторож Бладгуфа",b="Руул Іглталон стоїть на варті в Селі Бладгуф і дбає про безпеку поселення, поки молоді сміливці прибувають із плато, де стоїть Табір Нарачі. Хоч Малгор — мирна батьківщина порівняно з посушливими просторами Пусток, територіальні хижаки й ворожі істоти постійно натискають на пасовища. Руул переймається загрозами, що блукають ближніми рівнинами, і зокрема направляє здібних мандрівників проти лютих гарпій Вітрофурій, які полюють на необачних кочівників і дичину."}},faq={{q="Хто такий Руул Іглталон?",a="Руул Іглталон — таурен із Села Бладгуф, що допомагає боронити поселення, посилаючи шукачів пригод проти місцевих загроз по всьому Малгору.",al={"хто такий руул","руул іглталон нпс","руул кривавого копита"}},{q="З якою загрозою Руул Іглталон просить упоратися мандрівників?",a="Руул застерігає від ворожих гарпій Вітролютих, що гніздяться в Малгорі, і доручає вправним воїнам прорідити їхні лави, перш ніж вони заподіють шкоди селу.",al={"завдання руула","небезпека вітрорізу","завдання гарпій малгору"}},{q="Де знайти Руула Іглталона?",a="Він стоїть у Селі Бладгуф, на березі Озера Кам'яного Бика в центрі Малгору.",al={"місце руула іглталона","знайти руула","де руул"}}},fp="15,235,20.473.0,23.154.0,60.156.0,35.125.0"}
P.entries["npc:ruul-snowhoof"] = {n="Руул Сноугуф",s="Руул Сноугуф — тауренський друїд, якого тримають у полоні у Твердині Будякохутрих на півночі Ашенвалю. Замкнений у грубій клітці в подобі ведмедя, він сподівається, що шукачі пригод з Орди визволять його й виведуть у безпечне місце.",h="Руул Сноугуф — тауренський друїд, якого тримають у полоні у Твердині Будякохутрих на півночі Ашенвалю.",kw={"руул сноугуф","друїд","ведмежа подоба","будякохутрі","фурболги","яма сноугуф"},ang={["class:Druid"]="Брат кенарійського шляху, замкнений у звіриній подобі зіпсованими фурболгами, — промовистий доказ того, як порча підточує звірів і первісні племена Ашенвалю.",["race:Tauren"]="Руул належить до шанованого роду Сноугуфів; врятувавши його, ви повернете живим одного з вашої крові до його сестри Ями на Заставі Розщепленого Дерева."},sec={{t="Ведмідь у клітці",b="Руул Сноугуф вирушив на північ Ашенвалю — і потрапив до лап зіпсованих фурболгів Будякохутрих. Коли його схопили, він прибрав подоби могутнього ведмедя, і його кати сприйняли його за справжнього дикого звіра. Замість того щоб одразу вбити, фурболги замкнули його в дерев'яній клітці глибоко у Твердині Будякохутрих і лишили поволі вмирати з голоду. Знесилений, він не може ні безпечно скинути подобу, ні сам прорватися назовні, тож Руул чекає, поки союзники з Орди зламають замок, відіб'ються від його вартових і проторують шлях крізь лігво, щоб він міг повернутися до своєї сестри, Ями Сноугуф, на Заставу Розщепленого Дерева."}},faq={{q="Чому Руул Сноугуф сидить у клітці в подобі ведмедя?",a="Руул — таурен-друїд, що прийняв Ведмежу подобу, коли на нього напали фурболги-будякошерсті. Ті, хто його схопив, сприйняли його за справжнього дикого звіра, а не за друїда в звіриній подобі, і замкнули в клітці глибоко у своїй твердині.",al={"чому руул ведмідь","руул сноугуф у подобі ведмедя","чому він у клітці"}},{q="Чому фурболги не вбивають Руула?",a="Зіпсовані будякошерсті вирішили тримати Руула в полоні в звіриній подобі й — чи то з жорстокості, чи то зі злоби — поволі морять його голодом у клітці, замість одразу вбити.",al={"чому руул голодує","чого фурболґи хочуть від руула"}},{q="Куди йде Руул, утікши з Твердині Будякохутрих?",a="Коли його проводять повз патрулі фурболгів у безпечне місце за межами Твердині Будякохутрих, Руул просить своїх рятівників переказати, що він живий, його сестрі Ямі Сноугуф, яка служить на Заставі Розщепленого Дерева.",al={"куди йде руул","призначення руула сноугуфа"}},{q="Чи можуть гравці Альянсу спілкуватися з Руулом Сноугуфом?",a="Ні. Руул Сноугуф вірний Орді й дає завдання на втечу й допомогу лише шукачам пригод Орди, які знайдуть його клітку.",al={"руул лише для орди","руул сноугуф альянс"}}},fp="13,209,16.620.0,38.224.0,38.200.0,50.194.0,49.135.0"}
P.entries["npc:rwag"] = {n="Рваґ",s="Рваґ — орк, наставник розбійників у Лігві, схованому в Долині Випробувань Дуротару. Він навчає новоприбулих орків і тролів мистецтва скрадання, хитрощів і брудного бою під пильним оком Орди.",h="Рваґ — орк, наставник розбійників у Лігві, схованому в Долині Випробувань Дуротару.",kw={"рваґ","розбійник","наставник","лігво","долина випробувань","нарток","скрадання"},ang={["class:Rogue"]="Для молодих орків і тролів-розбійників, що ступають у Долину Випробувань, Рваґ — найперший наставник в основах шахрайського ремесла, який навчає перших атакувальних прийомів і розгадування таємних шифрів.",["race:Orc"]="Рваґ утілює практичний, неприкрашений бік орчого виживання і доводить, що навіть у чесній новій Орді Тралла тіні й холодна сталь лишаються необхідними."},sec={{t="Тіні долини",b="Діючи глибоко в печері, відомій як Лігво, Рваґ вишколює розбійників-початківців, злодюжок і крадіїв, перш ніж ті вийдуть у широкий світ Дуротару. Поки нова Орда обстоює бойову честь і звитягу на полі бою, Рваґ розуміє, що хитрість, отрути й влучно встромлений кинджал лишаються безцінними знаряддями виживання в безжальній пустелі. Він пильно стежить за справами в Долині й плекає глибокі підозри щодо темних чаклунів, які також ховаються в печері, — надто щодо чорнокнижника Нартока."}},faq={{q="Хто такий Рваґ?",a="Рваґ — орк, наставник розбійників у Лігві в Долині Випробувань. Він навчає розбійників-новачків — орків і тролів, — що починають навчання в Дуротарі.",al={"хто такий рваґ","рваґ долина випробувань","орк тренер розбійників"}},{q="Де знайти Рваґа?",a="Рваґ стоїть глибоко в Лігві — печері, вирубаній у скелястих кручах Долини Випробувань у Дуротарі, серед кількох інших наставників класів.",al={"місце рваґа","де рваґ","знайти рваґа"}},{q="Що Рваґ думає про чорнокнижників у Лігві?",a="Рваґ відкрито не довіряє чорнокнижникам, з якими ділить Лігво, і особливо пильно стежить за Нартоком, що практикує магію Скверни: темна магія й потайні культисти, каже він, вимагають постійної пильності.",al={"рваґ нартик","чому рваґ не довіряє чорнокнижникам","зашифрований пергамент рваґа"}},{q="Яких класів навчає Рваґ?",a="Рваґ навчає лише розбійників: дає перші бойові уроки вмінь на кшталт Потрошіння, а на прохання Розтрощеної Руки ще й придивляється до новобранців і передає все, що Руці від них може знадобитися.",al={"чого навчає рваґ","чи рваґ мене навчить"}}},fp="4,229,21.514.0,12.159.0,22.152.0,48.195.0,30.220.0"}
P.entries["npc:saelienne"] = {n="Селієнн",s="Корчмар Селієнн тримає корчму на Терасі Ремісників у Дарнасусі. Вона пропонує втомленим мандрівникам і місцевим ремісникам їжу, напої та спокійний притулок для каменя повернення в самому серці столиці нічних ельфів.",h="Корчмар Селієнн тримає корчму на Терасі Ремісників у Дарнасусі.",kw={"селієнн","корчмар","корчма","тераса ремісників","дарнасус","камінь повернення"},ang={["faction:Alliance"]="Посланці й торговці Альянсу, що мандрують до далеких крон Тельдрассилу, покладаються на Селієнн: у неї є їжа, напої й теплий притулок для каменя повернення.",["race:NightElf"]="Для шукачів пригод із нічних ельфів, що повертаються з диких куточків Тельдрассилу, корчма Селієнн — рідне вогнище серед ремісників Дарнасуса."},sec={{t="Гостинність на Терасі",b="Серед гомінких майстерень і торгових яток Тераси Ремісників Корчмар Селієнн дарує спокійний перепочинок і мешканцям Дарнасуса, і його гостям. Як хранителька домашнього вогнища, вона приймає шукачів пригод з усього Калімдору й далеких країв і подає звичні частування нічних ельфів разом із товарами, які привозять до міського порту. Її заклад — улюблене місце зборів ремісників, що шукають спочинку після довгих годин біля горна чи ткацького верстата."}},faq={{q="Де знайти Корчмарку Селієнн?",a="Селієнн — на Терасі Ремісників у Дарнасусі, де тримає місцеву корчму серед наставників ремесел і майстерень.",al={"місце селієнн","де селієнн","корчмар дарнасу","корчма тераси ремісників"}},{q="Які послуги надає Селієнн?",a="Вона корчмарка, у якої гравці можуть прив'язати свій камінь повернення до Дарнасуса. Також вона продає різну їжу й напої, що відновлюють здоров'я й ману.",al={"послуги селієнн","торговець селієнн","камінь повернення дарнас"}},{q="Чи дає Селієнн якісь сезонні завдання?",a="Під час святкування Переддня Усіх Святих Селієнн долучається до свята й пропонує шукачам пригод Альянсу завдання «Танці за марципан» в обмін на святкові ласощі.",al={"завдання селієнн","селієнн свято мертвих","танець за марципан"}}},fp="9,227,26.471.0,37.135.0,37.166.0,40.177.0"}
P.entries["npc:sally-whitemane"] = {n="Саллі Вайтмейн",s="Саллі Вайтмейн — верховна інквізиторка Багряного Хрестового Походу, що очолює Собор Багряного Монастиря. Могутня жриця Святого Світла, вона палає ненавистю до нежиті, і саме ця ненависть живить безкомпромісний фанатизм Походу. Разом із Багряним командиром Рено Моґрейном вона керує військовими та ідейними кампаніями ордену по всьому Лордерону.",h="Саллі Вайтмейн — верховна інквізиторка Багряного Хрестового Походу, що очолює Собор Багряного Монастиря.",kw={"саллі вайтмейн","вайтмейн","багряний хрестовий похід","багряний монастир","інквізиторка","моґрейн","лордерон"},ang={["class:Paladin"]="Для паладинів Срібної Длані правління Вайтмейн — приклад трагічного занепаду захисників Лордерону, які зреклися милосердя й справедливості заради сліпих чисток.",["class:Priest"]="Вайтмейн показує, якої страхітливої сили набуває Святе Світло, злите з непохитним фанатизмом, — і застерігає, як переконаність може обернутися на фанатичну безжальність.",["faction:Alliance"]="Колись Вайтмейн була підданою Альянсу в Лордероні, але тепер її Похід нападає на будь-яких чужинців, що наближаються до його земель, — і вірні Альянсу з Саутшора мусять стати проти чудовиськ, якими обернулися їхні колишні родичі.",["race:Undead"]="Для Відступників Вайтмейн уособлює небажання Походу відрізняти бездумну Погибель від нежиті з вільною волею, тож її знищення необхідне для виживання Андерсіті."},sec={{t="Трагедія в Лордероні",b="Саллі Вайтмейн провела юність у Саутшорі разом із друзями дитинства Рено Моґрейном і Джеймсом Вішасом. Ця безтурботність скінчилася під час Третьої війни: її родина вирушила на північ через Лордерон і загинула від чуми нежиття. Коли батьки, брати й сестри повстали бездумними посіпаками Погибелі, Вайтмейн мусила власноруч їх упокоїти — і відтоді її пожирали провина, горе й невгамовна лють. Від того дня вона присвятила все своє життя одній меті: викорінити нежиття в усіх його проявах."},{t="Верховна інквізиторка Походу",b="Стрімко піднявшись ієрархією Багряного Хрестового Походу, Вайтмейн стала його верховною інквізиторкою й очолила величний Собор Багряного Монастиря. Уславлена грізним опануванням святої магії, вона вела загони, що прийшли на поміч Гартглену й вирвали його з лап Погибелі, а також була наставницею під час посвяти високопоставлених хрестоносців, як-от Тейлана Фордрінга. Непохитна переконаність зробила її одним із головних символів Походу: Світло в її руках — безжальна зброя проти всіх, кого визнано нечистими."},{t="Цілі в Соборі",b="На 25 рік після Темного Порталу фанатизм Вайтмейн уже нажив їй ворогів в обох фракціях. У Саутшорі Релі Побожний вважає, що Похід безповоротно скотився до скверни й божевілля, і закликає знищити Вайтмейн і Моґрейна, щоб повернути орденові його первісні чесноти. А в Андерсіті жахолорд Варіматрас готує удари по Монастирю, щоб розчавити фанатиків, які хазяйнують просто на порозі Відступників."}},faq={{q="Хто така Саллі Вайтмейн?",a="Саллі Вайтмейн — Верховна Інквізиторка Багряного Хрестового Походу. Вона керує духовними й інквізиторськими справами ордену із Собору в Багряному Монастирі в Галявинах Тірісфалю й б'ється пліч-о-пліч із Командиром Рено Моґрейном.",al={"лор вайтмейн","хто верховна інквізиторка вайтмейн","бос багряного монастиря"}},{q="Чому Вайтмейн так ненавидить нежить?",a="Під час Третьої війни родину Вайтмейн уразила чума нежиття, коли вони мандрували північним Лордероном. Їй довелося власноруч убити батьків і братів та сестер, коли ті повстали безмозкою Погибеллю, — це глибоко поранило її горем і породило одержиму мету знищити всю нежить.",al={"чому вайтмейн ненавидить нежить","минуле вайтмейн","родина вайтмейн"}},{q="Де виросла Вайтмейн?",a="Вона виросла в містечку Саутшор у Передгір'ї Гілсбреда, де гралася в мисливців на чудовиськ із друзями дитинства Рено Моґрейном і Джеймсом Вішасом задовго до того, як вони вступили до Багряного Хрестового Походу.",al={"дитинство вайтмейн","звідки вайтмейн"}},{q="Чому Альянс хоче смерті Вайтмейн?",a="Релі Побожний, колишній хрестоносець із Саутшора, вважає, що Багряний Хрестовий Похід скотився до параної й божевілля. Він просить поборників Альянсу знищити Вайтмейн і Моґрейна, щоб орден, можливо, повернувся до свого шляхетного коріння.",al={"релі побожний вайтмейн","чому альянс вбиває вайтмейн","завдання в ім'я світла"}},{q="Чому Орда хоче смерті Вайтмейн?",a="Варіматрас і Відступники в Андерсіті вважають Багряний Хрестовий Похід діючою ворожою силою просто під стінами своєї столиці. Жахолорд наказує вбити її, щоб розбити верхівку Монастиря й усунути безпосередню загрозу землям Відступників.",al={"варіматрас вайтмейн завдання","до багряного монастиря","чому орда вбиває вайтмейн"}},{q="Які стосунки у Вайтмейн із Рено Моґрейном?",a="Вайтмейн і Рено Моґрейн разом росли в Саутшорі, а згодом стали двома очільниками Багряного Монастиря. Пліч-о-пліч у Соборі їх пов'язує близький зв'язок і спільна відданість походові Хрестового Походу проти нежиття.",al={"вайтмейн і моґрейн","командир моґрейн і вайтмейн"}}},fp="15,366,20.508.0,30.507.0,24.444.1,23.238.0,43.307.0,28.205.0,42.246.0,39.253.0,55.257.0"}
P.entries["npc:salma-saldean"] = {n="Салма Салдін",s="Салма Салдін — витривала господиня з Вестфолу, що доглядає Ферму Салдина разом із чоловіком, Фермером Салдіном. У краї, заполоненому розбійниками й покинутому Стормвіндом, вона тримає двері відчиненими й частує мандрівників гарячою їжею в обмін на трохи допомоги по господарству.",h="Салма Салдін — витривала господиня з Вестфолу, що доглядає Ферму Салдина разом із чоловіком, Фермером...",kw={"салма салдін","ферма салдина","вестфоллське рагу","пиріг із печінки кровоікла","кулінарія","вестфол"},ang={["faction:Alliance"]="Салма — приклад упертої стійкості господарів Альянсу, які не відмовляються від свого хліба попри байдужість Корони.",["profession:Cooking"]="Салма Салдін — важлива знайома для кухарів, що мандрують Вестфолом: вона ділиться практичними рецептами, як-от Вестфоллське Рагу й Пиріг із Печінки Кровоікла, що повною мірою використовують місцеву дичину.",["race:Human"]="Для людських мандрівників гостина в Салми — щемке нагадування про злигодні, які терпить простий люд Стормвінда за межами укріпленої столиці."},sec={{t="Гостинність у суворому краї",b="Поки сусідні господарства пограбувало й спалило Братство Дефіас, Салдінам вдається зберегти вогонь у домашньому вогнищі. Салма зустрічає мандрівників теплою усмішкою й ситним казанком на плиті та завжди шукає вправних людей, готових допомогти на фермі."},{t="Щоб на столі була їжа",b="Щоб вижити у Вестфолі, треба бути винахідливим. Салма використовує все, що дає земля, щоб нагодувати родину й гостей, і вчить мандрівників готувати місцеві страви, як-от Пиріг із Печінки Кровоікла, і своє славетне Вестфоллське Рагу з м'яса диких кабанів-кривавоіклих, стерв'ятників, мурлоків і окри, що трапилася під руку."}},faq={{q="Хто така Салма Салдін?",a="Салма Салдін — фермерка, що живе на Фермі Салдина в центрі Вестфолу разом із чоловіком. Вона дає мандрівникам розраду й їжу, а сама насилу тримає ферму серед лиха, що спіткало край.",al={"хто така салма","лор салми салдін","дружина фермера салдіна"}},{q="Де знайти Салму Салдін?",a="Вона біля свого будинку на Фермі Салдина, при дорозі в центрі Вестфолу, трохи на північ від перехрестя, звідки дорога веде вниз до Сентінел Гілла.",al={"місце салми","де салма салдін","де ферма салдіна"}},{q="Яких рецептів навчає Салма Салдін?",a="Салма ділиться секретами ситних місцевих страв, насамперед Пирога з Печінки Кровоікла й Вестфоллського Рагу, з місцевих складників, які добувають із тварин Вестфолу.",al={"рецепт рагу вестфола","їжа салми","пиріг з печінки кабана"}},{q="Чому Салдінам так важко знайти допомогу?",a="Більшість фермерів і наймитів Вестфолу покинули свої землі й утекли через бандитів-грабіжників, жнивних големів, що вийшли з-під контролю, і відсутність королівської армії Стормвінда, тож нечисленним хуторянам, що лишилися, геть бракує рук.",al={"чому покинута ферма","чому салдінам потрібна допомога","покинута ферма вестфол"}},{q="Як Салдіни виживають поруч із Братством Дефіас?",a="Салдіни покладаються на перехожих шукачів пригод і власну стійкість, щоб боронити своє господарство. Хоча небезпека обступає їх звідусіль, вони вперто не хочуть покидати свою землю й дім.",al={"салдін дефіас","чому ферма не згоріла"}},{q="Хто чоловік Салми?",a="Вона одружена з Фермером Салдіном, який працює з нею на фермі й намагається впоратися зі зламаними вартовими врожаю та здичавілими звірами.",al={"чоловік салми","фермер салдін"}}},fp="13,281,26.291.0,25.281.0,21.208.0,31.166.0,38.183.0,48.227.0,51.173.0,23.139.0"}
P.entries["npc:sara-balloo"] = {n="Сара Баллу",s="Сара Баллу — убита горем дворфійська вдова, що мешкає у Військовому Кварталі Айронфорджа. Вона проводить дні в жалобі за покійним чоловіком, Саллі Баллу, чіпляючись за будь-яку згадку чи послання з його останніх днів служби.",h="Сара Баллу — убита горем дворфійська вдова, що мешкає у Військовому Кварталі Айронфорджа.",kw={"сара баллу","удова","саллі баллу","військовий квартал","айронфордж","король маґні бронзбірд","жалоба"},ang={["faction:Alliance"]="Принести звістку Сарі — означає дати розраду родині воїна Альянсу, показавши трагічні домашні реалії за битвами, що точаться по всьому Азероту.",["race:Dwarf"]="Для дворфів, що проходять через Військовий Квартал, Сара Баллу — болісне нагадування про особисту ціну, яку несуть родини, чиї рідні йдуть боронити Каз Модан."},sec={{t="Чування вдови",b="Серед людного Військового Кварталу Айронфорджа Сара Баллу — скорботний контраст до брязкоту зброї та бойових вправ. Її чоловік, Саллі Баллу, поліг у бою далеко від дому, лишивши її саму зі спогадами й невідступним горем. Для Сари розрада приходить лише через знайдені слова — останній лист, що несе відданість Саллі через гори з місця його загибелі."},{t="Поклик до пам'яті",b="Не бажаючи, щоб жертва її чоловіка тихо канула в забуття, Сара шукає більшого за просту втіху. Своїми щирими зверненнями вона просить Короля Маґні Бронзбірда подбати, щоб Саллі й подібних до нього полеглих воїнів офіційно вшанував і пам'ятав престол, аби ціна, яку платять звичайні дворфійські родини, ніколи не була забута."}},faq={{q="Хто така Сара Баллу?",a="Сара Баллу — дворфійка, що живе у Військовому Кварталі Айронфорджа. Вона вдова Саллі Баллу, полеглого дворфа-воїна.",al={"сара баллу","хто така сара баллу","сара баллу айронфордж"}},{q="Де знайти Сару Баллу?",a="Вона у Військовому Кварталі гірського міста Айронфордж, біля тренувальних майданчиків і казарм.",al={"де сара баллу","місце сари баллу","знайти сару баллу"}},{q="Що сталося з її чоловіком?",a="Її чоловік, Саллі Баллу, загинув на військовій службі. Його речі й останній, розмоклий від води лист вважалися втраченими, доки їх не знайшов шукач пригод.",al={"чоловік сари баллу","хто такий саллі баллу","що сталося з саллі"}},{q="Що Сара робить із листом Саллі?",a="Прочитавши щирі слова покійного чоловіка, Сара пише прохання Королю Маґні Бронзбірду, щоб самопожертву Саллі належно визнали й ушанували.",al={"лист саллі баллу","прохання сари баллу","чого хоче сара баллу"}}},fp="11,223,15.401.0,21.343.1,19.132.0,29.121.0,29.148.1,38.163.1"}
P.entries["npc:sara-timberlain"] = {n="Сара Тімберлейн",s="Сара Тімберлейн — уміла кравчиня; її дім — Лісозаготівельний Табір Східної Долини на сході Лісу Елвінн. Відома винахідливим шиттям зі здобутих тканин, вона допомагає військовій справі, зшиваючи тканинний і шкіряний обладунок для війська Стормвінда.",h="Сара Тімберлейн — уміла кравчиня; її дім — Лісозаготівельний Табір Східної Долини на сході Лісу Елвінн.",kw={"сара тімберлейн","кравчиня","східна долина","льон","обладунок","бандани"},ang={["faction:Alliance"]="Віддалені поселення на кшталт Східної Долини напряму підтримують оборону королівства: тутешні ремісники постачають основний обладунок недостатньо забезпеченому війську Стормвінда.",["profession:Tailoring"]="Сара — зразок винахідливості прикордонних кравців: вона перетворює клапті грубого льону й бандитської тканини на практичний одяг на замовлення війська."},sec={{t="Шиття на рубежі",b="Біля маленької хатини на західному краю Лісозаготівельного Табору Східної Долини Сара Тімберлейн невтомно працює голкою й ниткою під стукіт сокир лісорубів. Попри віддаленість Східної Долини й нависання загрози від вовків і мурлоків, що никають довкола, вона дарує подорожнім гостинність і важливе ремесло. Її хист перетворювати клапті льону й здобуті бандани на міцне спорядження заслужив офіційне визнання: їй доручено постачати захисний тканинний і шкіряний обладунок просто війську Стормвінда."}},faq={{q="Хто така Сара Тімберлейн?",a="Сара Тімберлейн — вправна швачка, що живе в Лісозаготівельному Таборі Східної Долини в Лісі Елвінн. Вона славиться тим, що шиє практичне спорядження з вживаних тканин, і має замовлення на постачання армії Стормвінда.",al={"хто така сара тімберлейн","сара тімберлейн","кравчиня іствейла"}},{q="Де знайти Сару Тімберлейн?",a="Вона сидить надворі біля будинку в західній частині Лісозаготівельного Табору Східної Долини, на далекому сході Лісу Елвінн, при дорозі до Редріджу.",al={"місце сари тімберлейн","де сара тімберлейн","будинок тімберлейн"}},{q="Навіщо Сара збирає тканину для армії?",a="Армія Стормвінда покладається на місцевих ремісників, щоб поповнювати запаси спорядження. Із зібраної тканини — наприклад, полотна, яке приносять шукачі пригод, — Сара шиє міцний одяг і підкладки для обладунків солдатів королівства.",al={"навіщо сарі тканина для армії","броня армії стормвінда","завдання тканини й шкіри"}}},fp="15,251,26.559.0,23.216.0,33.171.0,41.222.0"}
P.entries["npc:scarlet-commander-mograine"] = {n="Багряний Командир Моґрейн",s="Багряний командир Моґрейн — воєначальник гарнізону в Соборі Багряного Монастиря. Ревний паладин Багряного Хрестового Походу, він боронить каплицю разом із Верховною інквізиторкою Вайтмейн. І Орда, і Альянс полюють на нього, щоб приборкати фанатиків, які загрожують Галявинам Тірісфалю й сусіднім землям.",h="Багряний командир Моґрейн — воєначальник гарнізону в Соборі Багряного Монастиря.",kw={"моґрейн","багряний командир","собор","вайтмейн","каплиця хрестоносця","паладин","багряний монастир"},ang={["class:Paladin"]="Моґрейн уособлює трагічне спотворення покликання паладина: святі обітниці захисту й праведності він перетворив на нещадний, непохитний фанатизм.",["faction:Alliance"]="Колись Багряний Хрестовий Похід мав з Альянсом спільну мету, але провідники в Саутшорі й Стормвінді визнають, що фанатичні командири на кшталт Моґрейна скотилися в жорстоке безумство.",["race:Undead"]="Для Відступників командир Моґрейн — найгостріший клинок Багряного Хрестового Походу: він стоїть просто біля кордонів Андерсіті й загрожує вашому виживанню в Тірісфалі."},sec={{t="Захисник каплиці",b="У величній Каплиці Хрестоносця, в самому серці Багряного Монастиря, Багряний командир Моґрейн очолює постійний гарнізон Багряного Хрестового Походу. Він володіє святою силою паладина з лютою відданістю й покладається на відплату, божественні щити та приголомшливі удари, щоб розтрощити кожного, кого Похід вважає зіпсованим чи нечистим."},{t="Чудесний зв'язок",b="Оборона каплиці нерозривно пов'язана з Верховною інквізиторкою Вайтмейн. Якщо нападникам вдасться поставити командира на коліна, Вайтмейн виходить із заднього святилища, щоб переломити хід бою. Закликавши Святе Світло, вона вмить знерухомлює загарбників і повертає Моґрейна з мертвих, тож ворогам доводиться в розпачливій боротьбі стати проти обох ватажків одночасно."}},faq={{q="Де знайти Багряного Командира Моґрейна?",a="Він у крилі Собору Багряного Монастиря на північному сході Галявин Тірісфалю. Ви знайдете його перед вівтарем у Каплиці Хрестоносця.",al={"місце моґрейна","де моґрейн","кімната моґрейна в монастирі"}},{q="Яка роль Моґрейна в Багряному Хрестовому Поході?",a="Він воєначальник сил Багряного Хрестового Походу, що стоять гарнізоном у Монастирі, і разом із Верховною інквізиторкою Вайтмейн командує його паладинами й солдатами.",al={"хто командир моґрейн","звання моґрейна","що робить моґрейн"}},{q="Як він б'ється?",a="Моґрейн б'ється як важкоозброєний паладин ближнього бою. Він приголомшує супротивників Молотом Правосуддя, завдає Ударів Хрестоносця, захищається Аурою Відплати, а коли його притиснуть до краю — вдається до Божественного Щита.",al={"здібності моґрейна","бій з моґрейном","як воювати з моґрейном"}},{q="Чому Верховна інквізиторка Вайтмейн його воскрешає?",a="Вайтмейн і Моґрейна пов'язують тісні узи, і вони разом б'ються як очільники Монастиря. Коли Моґрейн падає в бою, Вайтмейн утручається: чарами присипляє нападників і повертає Моґрейна до життя з повною силою.",al={"вайтмейн воскрешає моґрейна","чи моґрейн воскресає","воскресити моґрейна"}},{q="Чому з ним воюють і Альянс, і Орда?",a="Багряний Хрестовий Похід вважає всіх чужинців — і живих, і нежить — носіями скверни. І Альянс, і Відступники посилають поборників ударити по Собору й стратити його очільників, щоб знешкодити фанатичну присутність Хрестового Походу в Лордероні.",al={"чому вбивати моґрейна","завдання багряного командира","в ім'я світла"}},{q="Чи зцілює себе Моґрейн під час бою?",a="Так, у скрутну хвилину. Окрім Божественного Щита й ударів у ближньому бою, він може вдатися до Накладання Рук і повністю відновити здоров'я, а Верховна інквізиторка Вайтмейн, вступивши в бій, зцілює його ще й додатково.",al={"чи моґрейн лікує себе","лікування моґрейна"}}},fp="26,332,22.349.0,17.393.1,46.170.0,47.169.0,18.212.0,46.244.0,44.249.0,48.203.0"}
P.entries["npc:scooty"] = {n="Скуті",s="Скуті — гоблін-інженер, що працює в жвавому піратському порту Буті Бей. Проголосивши себе майстром інженерії, він підтримує тонку систему транспондерів, пов'язану просто з експериментальним телепортом у полеглому місті Гномреґан. Його пристрої дають агентам Орди прямий, хоч і небезпечний, технологічний обхідний шлях просто в серце Дун Мороґу.",h="Скуті — гоблін-інженер, що працює в жвавому піратському порту Буті Бей.",kw={"скуті","гоблін","телепорт","буті бей","гномреґан","трансполіпортер","совік"},ang={["faction:Horde"]="Скуті дає Орді незамінний короткий шлях до Гномреґана, дозволяючи вашим ударним загонам оминути залізну оборону Альянсу в Дун Мороґу.",["profession:Engineering"]="Колеги-майстри оцінять зухвале застосування Скуті фізики транспондерів, навіть якщо звична гоблінська зневага до елементарних правил безпеки перетворює кожне ввімкнення на лотерею."},sec={{t="Знавець телепортації з Буті Бей",b="Серед пристаней і майстерень Буті Бей Скуті правує як один із найамбітніших майстрів картелю Стімвідл. Поки звичайні гобліни марять порохом і вибухівкою, Скуті зосередився на миттєвому молекулярному переміщенні. Налаштовуючи складні системи транспондерів, він підтримує прямий робочий зв'язок із платформою телепорту в Гномреґані. Сили Орди, що прагнуть прорватися до підземної гномської твердині, значною мірою покладаються на майстерність Скуті, щоб цілком оминути підступні землі Альянсу."},{t="Гномські пристрої й гоблінський ризик",b="Обслуговувати експериментальні гоблінські телепорти — справа рідко нудна. Скуті та його компаньйон Совік збудували «Трансполіпортер 6000», щойно до них дійшла звістка про нову гномську установку в Гномреґані, і, за веселим зізнанням самого Скуті, той вибухав лише з десяток разів. Попри очевидну тілесну небезпеку дематеріалізації через континенти, Скуті цілком певен у своєму генії й вважає кожен катастрофічний механічний збій лише дрібною перешкодою на шляху до справжнього винаходу."}},faq={{q="Хто такий Скуті?",a="Скуті — гоблін-інженер із Буті Бею, що називає себе майстром-інженером. Він обслуговує й налаштовує мережу Гоблінського Транспондера, яка пов'язує Буті Бей просто з дослідним телепортаційним майданчиком глибоко в Гномреґані.",al={"хто такий скуті","лор скуті","скуті нпс","скуті затока здобичі"}},{q="Звідки в Скуті телепорт до Гномреґана?",a="Скуті налагодив зв'язок із дослідним телепортаційним майданчиком у Гномреґані, щоб можна було потрапити просто в гномське місто. Для Орди його пристрій — важливий чорний хід до Дун Мороґу без потреби пробиватися через добре укріплені землі Альянсу.",al={"чому телепорт до гномреґана","як працює телепорт скуті","порт скуті до гномреґана"}},{q="Де знайти Скуті?",a="Скуті працює в Буті Бей — нейтральному гоблінському портовому місті на південному краю Долини Стренглторну.",al={"де скуті","місце скуті","знайти скуті"}},{q="Чи безпечно користуватися телепортом Скуті?",a="Гоблінська інженерія сумно відома непередбачуваними поломками, і телепорт Скуті не виняток. Хоча він таки переносить шукачів пригод до Гномреґана, механічні збої й погано налаштовані транспондери — постійний ризик для тих, хто довіряє його примхливим технологіям.",al={"чи безпечний скуті","чи безпечний телепорт","ризики телепорта"}}},fp="6,370,32.546.0,31.517.0,14.237.0,48.270.0,24.121.0,34.271.0"}
P.entries["npc:scout-riell"] = {n="Розвідник Рієлл",s="Розвідник Рієлл — пильна дозорна на сторожовій вежі Сентінел Гілла у Вестфолі. Служачи місцевому Народному ополченню, вона стежить, чи не з'являться на рівнинах довкола розбійники Дефіасу, і наймає шукачів пригод полювати на грабіжників у масках.",h="Розвідник Рієлл — пильна дозорна на сторожовій вежі Сентінел Гілла у Вестфолі.",kw={"розвідник рієлл","сентінел гілл","братство дефіас","червона бандана","народне ополчення","вестфол"},ang={["faction:Alliance"]="Для героїв Альянсу Розвідник Рієлл уособлює гірку правду Вестфолу: покинуті люди змушені платити чужим мечам, щоб протистояти дедалі більшій загрозі Братства Дефіас.",["profession:Tailoring"]="Кравці помітять, що знамениті червоні маски Дефіасу пошиті зі справжнього шовку — напрочуд дорогої тканини як для звичайних сільських грабіжників."},sec={{t="Очі над Вестфолом",b="Високо над Сентінел Гіллом Розвідник Рієлл пильнує край, обложений розбійниками й жнивними големами. Королівське військо Стормвінда далеко, корона відмовляє в допомозі, тож місцева оборона цілком лягла на Народне ополчення. Зі свого спостережного пункту на кам'яній вежі Рієлл стежить за зухвалими пересуваннями Братства Дефіас і збирає докази їхніх злочинів, закликаючи мандрівників зривати з розбійників їхні знамениті червоні шовкові бандани."}},faq={{q="Де знайти Розвідника Рієлл?",a="Розвідник Рієлл — у Сентінел Гіллі у Вестфолі. Підніміться сходами аж на відкритий дах кам'яної сторожової вежі, звідки вона стежить за рівнинами.",al={"місце рієлл","де розвідник рієлл","знайти рієлл"}},{q="Про що Розвідник Рієлл просить шукачів пригод?",a="Рієлл доручає шукачам пригод збирати червоні шовкові пов'язки з кишенькових злодіїв, розбійників із великої дороги й контрабандистів Дефіас, що нишпорять Вестфолом і ховаються в Мертвих Копальнях, як доказ, що місцевих злочинців знищено.",al={"завдання рієлл","яке завдання дає рієлл","завдання червоних шовкових пов'язок"}},{q="Навіщо Рієлл збирає червоні шовкові пов'язки?",a="Червона шовкова пов'язка — загальний знак Братства Дефіас. Ці пов'язки — надійний доказ, що бандитів, які тероризують хутори Вестфолу, меншає, і заразом вони позбавляють розбійників символу, що їх об'єднує.",al={"навіщо пов'язки","навіщо червоні шовкові пов'язки","маски дефіас"}},{q="На кого працює Розвідник Рієлл?",a="Рієлл служить Народному ополченню — добровольчим силам оборони, які створив Ґраян Стаутмантл, щоб захистити Вестфол, коли Дім Вельмож у Стормвінді заплющив очі на біди провінції.",al={"фракція рієлл","чи рієлл армія стормвінда","кому служить рієлл"}}},fp="11,241,18.454.0,29.166.0,44.213.0,41.227.0,30.193.0"}
P.entries["npc:scout-thaelrid"] = {n="Срібний Вартовий Таелрід",s="Срібний Вартовий Таелрід — поранений нічний ельф-розвідник, якого Срібний Світанок послав у затоплені руїни Чорноглибинних Печер. Опинившись у пастці біля Озера Аск'ар, він стає свідком темного союзу, що визріває між нагами й культом Молота Присмерку.",h="Срібний Вартовий Таелрід — поранений нічний ельф-розвідник, якого Срібний Світанок послав у затоплені руїни...",kw={"таелрід","срібний вартовий","срібний світанок","чорноглибинні печери","молот присмерку","аку'май"},ang={["faction:Alliance"]="Розвідники Альянсу, яких посилають в Ашенваль, ідуть слідом за зниклим Таелрідом, прагнучи вберегти Зорамський Берег і підтримати нейтральну справу Срібного Світанку.",["faction:Horde"]="Хоч Таелрід — нічний ельф, він вірний Срібному Світанку, тож допомогти йому може кожен шукач пригод, готовий ударити по Молоту Присмерку й очистити печеру.",["race:NightElf"]="Для нічних ельфів осквернення священних прадавніх храмових земель на кшталт Блекфатому нагами й культами кінця світу — гірка наруга; Таелрід уособлює варту свого народу над найглибшими ранами Калімдору."},sec={{t="Очі Срібного Світанку",b="Коли із Зорамського Берега почали просочуватися дивні звістки про мерзенні обряди глибоко під морем, Срібний Світанок зацікавився. Відданий пильнуванню за зростанням зла й неприродної скверни по всьому Азероту, орден послав Розвідника Таелріда непомітно проникнути в Чорноглибинні Печери. Його завдання було просте: оцінити масштаб загрози, простежити за рухом у затопленому храмі й доповісти, щоб Світанок міг вирішити, де допомога потрібна найбільше."},{t="Темрява, що хапає",b="Таелрід швидко з'ясував, що чутки далеко не дотягують до жахливої дійсності. Підземні руїни приховують нечестивий союз між дикими нагами й фанатиками кінця світу з Молота Присмерку. Глибоко в залах сектанти під командуванням сутінкового володаря Келріса приносять криваві жертви, щоб нагодувати гідру Аку'май, торгуючись із прадавніми жахіттями за темну силу. Перш ніж Таелрід устиг донести це застереження на поверхню, його тяжко поранили й відрізали від виходу, і він опинився в пастці біля Озера Аск'ар."}},faq={{q="Хто такий Срібний Вартовий Таелрід?",a="Це нічний ельф, агент Срібного світанку. Йому доручили проникнути до Чорноглибинних Печер на узбережжі Ашенвалю й зібрати відомості про зловісні сили, що збираються в глибинах.",al={"хто такий таелрід","лор таелріда","минуле таелріда"}},{q="Чому Таелрід застряг у Чорноглибинних Печерах?",a="Під час розвідки печерного храму мешканці глибин помітили Таелріда й тяжко поранили. Не маючи змоги самотужки пробитися на поверхню, він сховався біля Озера Аск'ар.",al={"чому він застряг","як його поранили","чому таелрід вмирає"}},{q="Що Таелрід виявив у глибинах?",a="Таелрід розслідує діяльність Молота Присмерку в Чорноглибинних Печерах, де присутність культу загрожує стародавньому храмові й усім, хто туди заходить.",al={"що знайшов таелрід","що роблять культисти","таємниці чорноглибини"}},{q="На кого працює Таелрід?",a="Він належить до Срібного світанку — нейтральної спілки, що бореться зі скверною, злом і загрозами кінця світу по всьому Азероту, незалежно від меж фракцій.",al={"фракція таелріда","чи таелрід срібний світанок","чи таелрід альянсу"}},{q="Про що Таелрід просить шукачів пригод?",a="Не маючи змоги покинути свій сховок, Таелрід просить відважних шукачів пригод покласти край різанині: убити сутінкового володаря Келріса й принести голову ватажка культу як доказ, що загрозу зламано.",al={"завдання таелріда","завдання лиходійство чорноглибини","чого він хоче"}},{q="Де знайти Таелріда?",a="Він лежить поранений у відлюдній ніші біля Озера Аск'ар, одразу за затопленими першими печерами Чорноглибинних Печер.",al={"де таелрід","місце таелріда","розвідник біля ставка аск'ар"}}},fp="21,253,23.463.0,19.517.1,29.189.0,49.205.0,41.153.0,27.168.0,41.192.0,28.134.0"}
P.entries["npc:searn-firewarder"] = {n="Серн Фаєрвордер",s="Серн Фаєрвордер — троль із Темного Спису, наставник шаманів у Фортеці Ґроммаш в Оргріммарі. Він допомагає шаманам Орди зростати й скеровує їх до випробувань, без яких не порозумітися з духами стихій — вогню, води й повітря.",h="Серн Фаєрвордер — троль із Темного Спису, наставник шаманів у Фортеці Ґроммаш в Оргріммарі.",kw={"серн фаєрвордер","шаман","фортеця ґроммаш","стихії","поклик вогню","темний спис"},ang={["class:Shaman"]="Серн — важлива віха для шаманів Орди: він скеровує їх до майстрів і випробувань, потрібних, щоб прив'язати стихії до своїх тотемів.",["race:Troll"]="Шаман Темного Спису у Фортеці Ґроммаш, Серн показує, як тролі-духовидці пристосували свої родові зв'язки до життя пліч-о-пліч із союзниками-орками й тауренами."},sec={{t="Провідник стихій",b="У захищених стінах Фортеці Ґроммаш, поряд із верховним командуванням Орди, Серн Фаєрвордер служить провідником стихій для шаманів-початківців. Багато тролів Темного Спису спілкуються з духами через знахарів і ритуали вуду, але Серн утілює зв'язок, який тролі-шамани плекають безпосередньо з живими стихіями Калімдору. Він — посередник, що скеровує посвячених до далеких наставників і обрядів, без яких не здобути Поклику вогню, Поклику води й Поклику повітря."}},faq={{q="Хто такий Серн Фаєрвордер?",a="Серн Фаєрвордер — троль із джунглів, наставник шаманів у Фортеці Ґроммаш в Оргріммарі. Він веде шаманів Орди, що зростають, етапами їхньої духовної мандрівки.",al={"хто такий серн","лор серна фаєрвордера","серн оргріммар"}},{q="Які завдання дає Серн Фаєрвордер?",a="Серн проводить шаманів через завдання пробудження стихій — «Поклик Вогню», «Поклик Води» й «Поклик Повітря», — вказуючи їм на далекі святилища й духовних наставників на обох континентах.",al={"завдання серна","ланцюжок завдань серна фаєрвордера"}},{q="Чому троль-шаман служить у Фортеці Ґроммаш?",a="Фортеця Ґроммаш — серце влади Оргріммара, де перебувають Вождь Тралл і поважні представники союзних народів. Присутність Серна відбиває тісну єдність орків і племені Темного Спису, а також ключову роль шаманства в Новій Орді.",al={"чому троль-шаман у фортеці ґроммаш","серн фортеця ґроммаш"}}},fp="16,248,23.498.0,24.173.0,40.206.0,53.283.0"}
P.entries["npc:seer-graytongue"] = {n="Віщун Ґрейтанг",s="Віщун Ґрейтанг — поважний старійшина тауренів і духовний провідник, що мешкає на Плато Червоної Хмари в Малгорі. Його пост — Табір Нарачі, де він випробовує молодих сміливців, які проходять свої найперші племінні випробування. Через такі ритуали, як Обряд Сили, він дбає, щоб молодь шанувала Матір-Землю, перш ніж ступити в широкий світ.",h="Віщун Ґрейтанг — поважний старійшина тауренів і духовний провідник, що мешкає на Плато Червоної Хмари в...",kw={"віщун ґрейтанг","старійшина","обряд сили","табір нарачі","плато червоної хмари","мати-земля"},ang={["class:Shaman"]="Духовні посвячені звертаються до старійшин на кшталт Ґрейтанга, щоб навчитися, як священний ритуал і випробування поєднують тілесну міць воїна з настановами предків.",["race:Tauren"]="Для молодих тауренів відвідини Віщуна Ґрейтанга — священний обряд посвяти, що поєднує особисту силу з вічними благословеннями Матері-Землі."},sec={{t="Провідник на плато",b="Віщун Ґрейтанг живе на Плато Червоної Хмари й служить раннім наставником для майбутніх сміливців і заклиначів із тауренів. Коли молоді шукачі пригод вирушають із Табору Нарачі, Ґрейтанг наглядає за ключовими кроками їхнього священного шляху, зокрема за Обрядами Матері-Землі. Випробовуючи їхню рішучість суворими рівнинами й небезпечними звірами Малгору, він прищеплює чесноти честі, терпіння й шани, які кожен справжній таурен має нести в доросле життя."}},faq={{q="Хто такий Віщун Ґрейтанг?",a="Віщун Ґрейтанг — тауренський старійшина-віщун, що живе в наметі на Плато Червоної Хмари в Малгорі. Він проводить молодих героїв через традиційні обрядові обов'язки, щоб вони довели свою вартість племені.",al={"ґрейтанг","роль віщуна ґрейтанга","віщун на червоній хмарній мезі"}},{q="Якими випробуваннями керує Віщун Ґрейтанг?",a="Він проводить молодь через частини Обрядів Земної Матері, зокрема Обряд Сили. Ці ритуали випробовують стійкість воїна й його шану до природної рівноваги рівнин.",al={"завдання ґрейтанга","чого хоче ґрейтанг","обряди матері-землі ґрейтанг"}},{q="Де знайти Віщуна Ґрейтанга?",a="Він живе у скромному шкіряному наметі на краю Плато Червоної Хмари, трохи осторонь від гамору Табору Нарачі в Малгорі.",al={"місце віщуна ґрейтанга","де ґрейтанг","хатина ґрейтанга"}}},fp="15,327,19.468.0,23.188.0,41.206.0,33.145.0"}
P.entries["npc:seer-ravenfeather"] = {n="Віщун Рейвенфезер",s="Віщун Рейвенфезер — наставниця шаманів із тауренів, що працює в Таборі Нарачі на Плато Червоної Хмари. Вона веде духовних учнів-початківців крізь їхні перші випробування, допомагаючи налаштуватися на голоси духів і землі Малгору.",h="Віщун Рейвенфезер — наставниця шаманів із тауренів, що працює в Таборі Нарачі на Плато Червоної Хмари.",kw={"віщун рейвенфезер","шаман","наставниця","поклик землі","сапта","табір нарачі","плато червоної хмари"},ang={["class:Shaman"]="Для молодих шаманів-тауренів Віщун Рейвенфезер — найперша провідниця в довгій подорожі, у якій вони вчаться єднатися зі стихіями й зв'язувати сили землі.",["race:Tauren"]="Як віщунка Табору Нарачі, вона уособлює глибоку духовну традицію, що є опорою суспільства тауренів, які облаштовуються на прабатьківській землі."},sec={{t="Провідниця на плато",b="Табір Нарачі — тихий прихисток, де Віщун Рейвенфезер терпляче навчає молодих тауренів, покликаних на шаманський шлях. Плато Червоної Хмари — священне місце випробувань, і Рейвенфезер дбає, щоб адепти-новачки зрозуміли свої обов'язки, перш ніж вирушити в ширші простори Малгору. Вона навчає їх засадничих обрядів, потрібних, щоб єднатися з силами стихій і шанувати Матір-Землю."},{t="Поклик стихій",b="Головний обов'язок Рейвенфезер — наглядати за першими духовними кроками шаманів-початківців і вести їх традиційним обрядом, відомим як Поклик Землі. Під її проводом посвячені готують церемоніальні сапти й шукають єднання з духами землі, що гніздяться в кам'яних виступах плато, — так кується зв'язок, що закріплює їхню стихійну магію."}},faq={{q="Хто така Віщун Рейвенфезер?",a="Віщун Рейвенфезер — духовна наставниця, що живе в Таборі Нарачі на Плато Червоної Хмари. Вона навчає молодих тауренів-шаманів, які роблять у світі свої перші кроки.",al={"лор рейвенфезер","хто така рейвенфезер","віщун табору нараче"}},{q="Яку роль вона відіграє в навчанні шаманів?",a="Вона проводить шаманів-новачків через їхні найперші обряди, насамперед через ланцюжок завдань, у якому вони спілкуються з духами землі й відповідають на «Поклик Землі».",al={"завдання шаманів рейвенфезер","тренер поклику землі","чого навчає рейвенфезер"}},{q="Де знайти Віщуна Рейвенфезер?",a="Вона серед наметів і хиж Табору Нарачі на відлюдному Плато Червоної Хмари на південному заході Малгору.",al={"місце рейвенфезер","де рейвенфезер","табір нараче"}}},fp="17,232,19.436.0,24.353.0,25.158.0,43.156.0,35.124.0"}
P.entries["npc:seereth-stonebreak"] = {n="Сірет Стоунбрейк",s="Сірет Стоунбрейк — орчиха-шаманка, що служить Орді, стежачи за негараздами, які тривожать землю. Отаборившись біля Долини Великолісся на межі Гір Кам'яного Кігтя й Пусток, вона посилає мандрівників протистояти руйнуванню природи, некерованим машинам і зростанню напруги в Калімдорі.",h="Сірет Стоунбрейк — орчиха-шаманка, що служить Орді, стежачи за негараздами, які тривожать землю.",kw={"сірет стоунбрейк","шаманка","гори кам'яного кігтя","долина великолісся","венчурна компанія","природа"},ang={["class:Shaman"]="Турбота Сірет про стривожені стихії й поранену природу Кам'яного Кігтя — дзеркало обов'язку кожного шамана: гоїти рани землі й угамовувати збурених духів.",["faction:Horde"]="Її накази захищають важливі суходільні шляхи й ресурси і від військ Альянсу, що підступають, і від безрозсудних гоблінських підприємств.",["race:Orc"]="Сірет утілює повернення сучасних орків до шаманізму й шанування природи — на противагу бездумному руйнуванню."},sec={{t="Пильна шаманка",b="Сірет Стоунбрейк — орчиха, віддана гармонії стихій і захистові земель Орди. Її послали до Кам'яного Кігтя, коли духи землі заголосили проти гоблінського грабунку, і тепер вона тримає табір біля Долини Великолісся й пильно стежить за околицями. Замість поринати у відчай, вона використовує своє духовне прозріння й знання дикого прикордоння, щоб вести шукачів пригод проти загроз, що нависли над краєм."},{t="Сум'яття в Кам'яному Кігті",b="Сірет глибоко тривожить сум'яття, що шматує гори Кам'яного Кігтя. Безжальні гоблінські підприємства й нестримні механічні подрібнювачі, що прорубують давні ліси, тяжко підірвали духовну рівновагу гір. Вона доручає посланцям Орди дати відсіч цим безрозсудним загарбникам і порадитися зі старими хранителями переказів, щоб угамувати біль землі."}},faq={{q="Хто така Сірет Стоунбрейк?",a="Сірет Стоунбрейк — орчиха-шаманка на службі Орди. Вона дає поради й завдання мандрівникам, що прямують до Гір Кам'яного Кігтя, і бореться з загрозами землі та присутності Орди в краї.",al={"сірет","хто така сірет","лор сірет стоунбрейк"}},{q="Чому Сірет непокоять Гори Кам'яного Кігтя?",a="Гори Кам'яного Кігтя страждають від безжальної вирубки лісів, агресивних гоблінських лісорубних машин і загострення сутичок. Як шаманка, Сірет відчуває неспокій місцевих духів і намагається зупинити спустошення.",al={"чому стоунталон","проблеми сірет","неспокій стоунталона"}},{q="Що сталося з її первісним постом?",a="Нічого з ним не сталося. Сірет послала до Гір Кам'яного Кігтя Орда, і вона й далі таборує біля Долини Великолісся, на межі Гір Кам'яного Кігтя й Пусток, куди веде дорога на захід від Перехрестя.",al={"минуле сірет","пост шани сірет","чому сірет переїхала"}},{q="Які доручення Сірет дає шукачам пригод?",a="Вона посилає шукачів пригод Орди в Гори Кам'яного Кігтя дати раду нахабним гоблінам Венчурної Компанії, розбирати руйнівні машини-потрощувачі, спілкуватися з неспокійними духами й радитися з шанованими старійшинами на кшталт Маґати Ґрімтотем.",al={"завдання сірет","чого хоче сірет","доручення сірет стоунбрейк"}},{q="Хто така Стара Відьма, про яку вона згадує?",a="Стара Відьма — це Маґата Ґрімтотем, могутня й впливова тауренська старійшина з Узвишшя Старійшин у Тандер Блафі, з якою Сірет радиться щодо глибоких духовних збурень.",al={"стара відьма","хто стара відьма","завдання старої відьми"}},{q="Чому її непокоять справи гоблінів?",a="Нестримна гоблінська лісозаготівля тримається на механічних потрощувачах, що продираються крізь священні ліси, забруднюють води й гніваять духів природи, яких Сірет присягнула заспокоювати.",al={"сірет гобліни","гоблінські загарбники","чому ненавидить гоблінів"}}},fp="18,300,17.432.0,21.415.0,26.199.0,56.226.0,35.215.0,45.224.0,36.203.0,44.180.0"}
P.entries["npc:senani-thunderheart"] = {n="Сенані Тандергарт",s="Сенані Тандергарт — тауренка-мисливиця із Застави Розщепленого Дерева в Ашенвалі, трохи на північ від Пусток. Служачи Орді, вона випробовує мандрівників, кидаючи їм виклик вистежити лютих хижаків давнього лісу. Її випробування дають мисливцям змогу довести свою майстерність і водночас прорідити смертоносних звірів, що нишпорять поблизу земель Орди.",h="Сенані Тандергарт — тауренка-мисливиця із Застави Розщепленого Дерева в Ашенвалі, трохи на північ від Пусток.",kw={"сенані тандергарт","мисливиця","застава розщепленого дерева","урсанґус","шадумбра","шарпталон"},ang={["class:Hunter"]="Сенані втілює справжній мисливський дух і випробовує ваші навички слідопита на невловимих звірах Ашенвалю: Урсанґусі, Шадумбрі та Шарпталоні.",["faction:Horde"]="Застава Розщепленого Дерева — опорний пункт Орди в Ашенвалі, де Сенані допомагає розвідникам Орди довести, чого вони варті, і втримати дикі землі.",["race:Tauren"]="Для тауренів зустріч із Сенані — нагадування про випробування Земної Матері, що вшановують давню рівновагу між мисливцем і здобиччю навіть далеко від Малгору."},sec={{t="Майстриня полювання",b="Сенані Тандергарт, що отаборилася на Заставі Розщепленого Дерева, уособлює мисливські традиції тауренів серед затінених гаїв Ашенвалю. Далеко від відкритих рівнин Малгору вона посилає шукачів пригод з Орди випробувати свої навички слідопитів і бійців на найгрізніших хижаках лісу. Полювання для неї — і почесне випробування, і необхідний ритуал виживання в дикому, спірному краї."},{t="Звірі Ашенвалю",b="Сенані наглядає за традиційними мисливськими випробуваннями Ашенвалю й спрямовує мисливців на трьох горезвісних хижаків: ведмедя Урсанґуса, кішку Шадумбру та гіпогрифа Шарпталона. Здобути їхні трофеї — лапу, голову й кіготь — це обряд посвяти, що засвідчує повагу мисливця до землі та його владу над її найлютішими мешканцями."}},faq={{q="Хто така Сенані Тандергарт?",a="Сенані Тандергарт — тауренка-мисливиця, що дає завдання на Заставі Розщепленого Дерева в Ашенвалі. Вона служить Орді, посилаючи шукачів пригод полювати на найнебезпечніших звірів, що нишпорять лісом.",al={"хто така сенані","лор сенані тандергарт","давець завдань притулку срібного вітру"}},{q="Де знайти Сенані Тандергарт?",a="Сенані на Заставі Розщепленого Дерева — заставі Орди в Ашенвалі, просто на північ від Пусток.",al={"місце сенані","де сенані","де притулок срібного вітру"}},{q="Що таке «Полювання в Ашенвалі»?",a="«Полювання в Ашенвалі» — низка мисливських випробувань від Сенані. Мисливцям доручають вистежити й убити трьох легендарних лісових хижаків: ведмедя Урсанґуса, нічного шаблезуба Шадумбру й гіпогрифа Шарпталона.",al={"полювання в ашенвалі","чого хоче сенані","завдання полювання в ашенвалі"}},{q="Які трофеї вимагає Сенані за полювання?",a="Вона просить мисливців повернутися з Лапою Урсанґуса, Головою Шадумбри й Кігтем Шарпталона як доказом, що всіх трьох грізних звірів переможено.",al={"трофеї полювання","предмети полювання в ашенвалі","що потрібно сенані"}},{q="Чи пов'язана Сенані з місцевими фурболгами?",a="У її власних завданнях — ні. Справа Сенані — «Полювання в Ашенвалі», а Гнилий Гай та інші племена фурболгів — лише одна з багатьох небезпек, з якими мисливець стикається в лісі.",al={"завдання фаулвілд","король фаулвілда","сенані фурболґи"}},{q="Чи пов'язана Сенані з Колом Кенарія?",a="Ні, Сенані служить безпосередньо Орді й тауренським племенам і дивиться на ліс очима традиційної мисливиці, а не друїда-охоронця Кола Кенарія.",al={"чи сенані друїдка","сенані коло ценарія"}}},fp="19,369,22.405.0,23.346.0,27.202.0,37.103.0,27.231.0,48.148.0,60.163.0,46.176.0"}
P.entries["npc:senator-mehr-stonehallow"] = {n="Сенатор Мер Стоунгаллов",s="Сенатор Мер Стоунгаллов — політик Айронфорджа й член Ліги Дослідників, що перебуває в Кар'єрі Гол'Болар у Дун Мороґу. Замість сперечатися про політику в столиці, він вирушив на передову, щоб особисто наглядати за стримуванням місцевої навали трогів. Він залучає завзятих шукачів пригод, щоб винищити тварюк, перш ніж ті остаточно захоплять кар'єр.",h="Сенатор Мер Стоунгаллов — політик Айронфорджа й член Ліги Дослідників, що перебуває в Кар'єрі Гол'Болар у Дун...",kw={"сенатор мер стоунгаллов","сенатор","ліга дослідників","кар'єр гол'болар","троги","сенат айронфорджа","дун мороґ"},ang={["faction:Alliance"]="Стоунгаллов дає ранню нагоду побачити, як діє дворфійське керівництво, пропонуючи молодим героям Альянсу прямий громадянський обов'язок: убивати чудовиськ, щоб захистити трудовий люд.",["race:Dwarf"]="Для дворфів бачити обраного сенатора по коліна в багні кар'єру, а не з кухлем елю у Високому Престолі Айронфорджа — приємний доказ справжньої дворфійської твердості."},sec={{t="Політик у ямах",b="Поки більшість членів Сенату Айронфорджа проводять дні в безпечному затишку великих кам'яних зал столиці, Сенатор Мер Стоунгаллов воліє діяти напряму. Як дворф, відданий і врядуванню, і історичним пошукам Ліги Дослідників, він розуміє практичні небезпеки, що загрожують королівству. Коли люті кам'янощелепі троги почали видиратися з глибокої скелі в Кар'єрі Гол'Болар, Стоунгаллов сам вирушив до копальні. Переконаний, що бюрократичне позерство не врятує робітників, він пропонує нагороду вправним мандрівникам, які винищать зухвалих трогів і повернуть кар'єр."}},faq={{q="Хто такий Сенатор Мер Стоунгаллов?",a="Сенатор Мер Стоунгаллов — дворфійський державний діяч, член Сенату Айронфорджа. На відміну від багатьох колег-законодавців, він особисто займається прикордонними справами й належить до Ліги Дослідників. Нині він стоїть на варті й організовує оборону в Кар'єрі Гол'Болар.",al={"роль стоунгаллова","хто сенатор","мер стоунгаллов"}},{q="Що сенатор робить у Кар'єрі Гол'Болар?",a="Стоунгаллов сам спустився до кар'єру, щоб особисто взяти в руки кризу, що там вибухнула. На копальню раптом напали троги Кам'янощелепих, що прокопалися з-під землі, загрожуючи і дворфам-робітникам, і цінним розкопкам, і Стоунгаллов не захотів чекати, поки далекі чиновники розкачаються.",al={"чому стоунгаллов тут","чому він у кар'єрі","сенатор у дун мороґу"}},{q="Про що Сенатор Стоунгаллов просить шукачів пригод?",a="Він наймає новоприбулих шукачів пригод, щоб прорідити трогів Кам'янощелепих в Кар'єрі Гол'Болар і довкола нього. Винищуючи трогів, що заполонили нижні рівні, новобранці допомагають убезпечити розкопки й уберегти гірників, що лишилися.",al={"завдання державного службовця","завдання стоунгаллова","завдання кар'єру"}},{q="До якої спілки, окрім Сенату, належить Стоунгаллов?",a="Окрім законодавчих обов'язків у Сенаті, Мер Стоунгаллов — член Ліги Дослідників. Саме звідси його інтерес до підземних розкопок і готовність вирушати далеко від столичних вигод.",al={"фракція стоунгаллова","чи стоунгаллов у лізі дослідників","приналежність стоунгаллова"}}},fp="24,376,24.624.0,32.293.0,47.335.0,53.237.0,64.245.0"}
P.entries["npc:senior-surveyor-fizzledowser"] = {n="Старший Землемір Фіззлдаузер",s="Старший Землемір Фіззлдаузер — гоблін-дослідник, що працює в Ґаджетзані, у Танарісі. Він розслідує негаразди з місцевим водопостачанням і посилає шукачів пригод з'ясувати, куди зник Скрімшенк.",h="Старший Землемір Фіззлдаузер — гоблін-дослідник, що працює в Ґаджетзані, у Танарісі.",kw={"старший землемір фіззлдаузер","ґаджетзан","вода","силітиди","скрімшенк","танаріс"},ang={["profession:Engineering"]="Фіззлдаузер покладається на власноруч сконструйовані гоблінські лозошукальні штуковини, щоб знаходити приховані джерела води під мінливими пісками."},sec={{t="Пошуки води, що пішли шкереберть",b="Старший Землемір Фіззлдаузер, що працює в Ґаджетзані, передусім зайнятий розв'язанням хронічної біди пустельного містечка — нестачі ресурсів. Місцеві колодязі й водопої раз у раз захоплюють ворожі бандити-Пустельні Блукачі, тож Водна компанія Ґаджетзана мусить шукати неторкані запаси води дедалі далі. Для цього Фіззлдаузер посилає розвідників із лозошукальними штуковинами по всіх дюнах — наприклад, до Чати Піщаної Скорботи. Проте замість чистих джерел його зонди раз у раз натрапляють на підземні гнізда комах, і одна господарська криза змінюється неминучою екологічною катастрофою."},{t="Викриття силітидів",b="Коли на його землемірні загони почали нищівно нападати броньовані комахи, що риють землю, Фіззлдаузер узявся разом з Алхіміком Пестлзуґґом вивчати зразки. Нові трагедії — зокрема загибель Молодшого Землеміра Скрімшенка в Роззявленій Прірві — довели, що це не звичайні пустельні шкідники, а злагоджені передові загони, відомі як силітиди. Стривожений знахідками, що вказують на загрозу, здатну захлиснути весь південний Калімдор, Фіззлдаузер відкладає гоблінський нейтралітет і б'є на сполох, звертаючись безпосередньо до проводу Орди й Альянсу."}},faq={{q="Хто такий Старший Землемір Фіззлдаузер?",a="Це інженер і польовий наглядач Водопостачальної Компанії Ґаджетзана. Його обов'язок — шукати придатні криниці по всій пустелі Танарісу, щоб Ґаджетзан не лишився без води.",al={"хто такий фіззлдаузер","фіззлдаузер танаріс","землемір ґаджетзана"}},{q="Що таке Водопостачальна Компанія Ґаджетзана?",a="Це комерційне підприємство з Ґаджетзана, що відповідає за видобуток, очищення й розподіл води в посушливій пустелі Танарісу, де волога — найцінніший товар.",al={"водопостачальна компанія ґаджетзана","на кого працює фіззлдаузер"}},{q="Що сталося з Молодшим Землеміром Скримшенком?",a="Скримшенк — зниклий розвідувач, і Фіззлдаузер просить шукачів пригод з'ясувати, куди він подівся.",al={"де скримшенк","спокута скримшенка","що сталося зі скримшенком"}},{q="Чому Фіззлдаузера непокоять пустельні комахи?",a="Його розслідування починається з тривожної поведінки комах і перебоїв із водопостачанням Ґаджетзана, тож він збирає докази для подальшого вивчення.",al={"чому розслідувати комах","розслідування лігва","загроза силітидів танаріс"}}},fp="28,212,29.591.1,23.560.1,36.168.0,36.195.0,44.100.1,55.152.0"}
P.entries["npc:senir-whitebeard"] = {n="Сенір Вайтбірдий",s="Сенір Вайтбірдий — дворфський сановник і польовий агент, що стоїть біля Ґуральні Тандербрю в Хараносі. Як особливий посланець Сенату Айронфорджа, він має стежити за загрозами, що дедалі тісніше оточують Дун Мороґ. Його головне завдання — оцінити наступ тролів Морозогривів і доповідати про їхні пересування безпосередньо дворфському проводу.",h="Сенір Вайтбірдий — дворфський сановник і польовий агент, що стоїть біля Ґуральні Тандербрю в Хараносі.",kw={"сенір вайтбірдий","посланець","сенат айронфорджа","харанос","морозогриви","розвідка"},ang={["faction:Alliance"]="Новобранці Альянсу, що проходять через Дун Мороґ, допомагають Сенірові вберегти серце земель Айронфорджа від того, щоб його відрізали повстання тутешніх тролів.",["race:Dwarf"]="Для дворфів Сенір уособлює бюрократичний, але необхідний зв'язок між захисниками порубіжжя та владою в Айронфорджі."},sec={{t="Посланець Сенату",b="Поки більшість мандрівників приходять до Хараноса заради гамірної корчми й славетного стауту, Сенір Вайтбірдий тут у службових справах. Його, представника, присланого самим Сенатом Айронфорджа, присутність показує, наскільки серйозно у високих залах ставляться до розхитування Дун Мороґу. Він — важлива ланка між місцевими розвідниками, що зустрічають небезпеку на засніженому порубіжжі, і законодавцями, які сперечаються про політику за кам'яною брамою міста."},{t="Око на Морозогривів",b="Найбільше Сеніра турбує дедалі зухваліша агресія тролів Морозогривів. Вигнані й доведені до відчаю серед морозних скель, тролі почали підступати небезпечно близько до дворфських поселень і доріг. Замість самому кидатися в бій, поважний посланець збирає відомості про позиції тролів, особливо навколо їхньої твердині, і складає ретельні звіти, щоб воєначальники Айронфорджа могли завдати рішучого удару."}},faq={{q="Хто такий Сенір Вайтбірдий?",a="Сенір Вайтбірдий — посланець, якого Сенат Айронфорджа відрядив до Дун Мороґу. Він стоїть біля Хараноса й збирає відомості про загрози краю, насамперед про місцеві племена тролів Морозогривів.",al={"хто цей дворф","лор сеніра вайтбірда","хто такий сенір"}},{q="Що Сенір робить у Хараносі?",a="Сенір служить у Хараносі, щоб стежити за тролями й зводити докупи донесення розвідників. Харанос — перехрестя Дун Мороґу, тож це ідеальне місце, щоб приймати польові відомості, перш ніж передати їх Сенату в Айронфорджі.",al={"чому сенір тут","роль сеніра в хараносі","що робить сенір"}},{q="Навіщо Сенату Айронфорджа тут посланець?",a="Сенатові Айронфорджа потрібні надійні дані з перших рук, щоб розподіляти сили й спрямовувати варту. Сенір — неупереджений посадовець, що оцінює, чи загроза від Морозогривів вимагає негайної воєнної відповіді зі столиці.",al={"навіщо посланець сенату","сенат айронфорджа харанос","справи сенату"}},{q="Що найбільше турбує Сеніра в Дун Мороґу?",a="Насамперед — набіги тролів Морозогривів. Тролі дедалі зухваліше виходять зі своїх таборів на землі дворфів і вже прямо загрожують сусіднім поселенням, як-от Хараносу.",al={"головна проблема сеніра","яку загрозу стежить сенір","сенір тролі"}},{q="Чи б'ється Сенір із тролями сам?",a="Ні, Сенір — урядовець і збирач відомостей. Він покладається на місцевих розвідників, горян і мандрівних шукачів пригод, які вирушають у ворожі місця на кшталт Твердині Морозогривів і приносять йому важливі розвідувальні дані.",al={"чи сенір б'ється","чи сенір воїн","бій сеніра"}},{q="Куди йдуть донесення Сеніра?",a="Коли Сенір зведе польові нотатки про позиції й сили тролів, готові донесення відправляють гірською дорогою просто до Сенату й очільників Айронфорджа.",al={"куди йдуть донесення","призначення звітів сеніра","хто отримує звіти"}}},fp="16,377,19.432.0,22.434.0,24.191.0,32.239.0,52.235.0,46.205.0,36.221.0,28.179.0"}
P.entries["npc:sentinel-arynia-cloudsbreak"] = {n="Вартова Аринія Клаудзбрейк",s="Вартова Аринія Клаудзбрейк — охоронниця, нічна ельфійка, що перебуває в тихих гаях Галявини Оракула на Тельдрассилі. Їй доручено стежити за священною рівновагою північного віття, і вона насторожено пильнує зачаровані води галявини й лісову звірину.",h="Вартова Аринія Клаудзбрейк — охоронниця, нічна ельфійка, що перебуває в тихих гаях Галявини Оракула на...",kw={"аринія клаудзбрейк","вартова","галявина оракула","тельдрассил","дарнасус","альянс","гарпії"},ang={["faction:Alliance"]="Аринія уособлює пильність калдорейських Вартових, що тримають оборону життєво важливої лісової твердині Альянсу в Калімдорі.",["race:NightElf"]="Для молодих нічних ельфів, що дорослішають на Тельдрассилі, допомога Вартовій Клаудзбрейк дає практичний досвід захисту дикої рівноваги їхньої нової батьківщини."},sec={{t="Сторожа Галявини Оракула",b="Аринія Клаудзбрейк служить у війську Вартових в одному з найвідлюдніших і наймістичніших закутків Тельдрассила — на Галявині Оракула. Серед прадавніх дерев і неземних джерел вона несе варту далеко від гамірних вулиць Дарнасуса, дбаючи, щоб святість дикого краю лишалася непорушеною."},{t="Негаразди на галявині",b="Попри священне народження Тельдрассила, повзуча незлагода почала збурювати його створінь. Аринія покладається на перехожих шукачів пригод і молодих нічних ельфів, щоб дослідити тутешні негаразди — дивну поведінку звірини галявини й містичні явища довкола зачарованих джерел."}},faq={{q="Хто така Вартова Аринія Клаудзбрейк?",a="Це нічна ельфійка з Вартових, що несе варту на Галявині Оракула глибоко на півночі Тельдрассила. Вона оберігає цю містичну галявину й залучає мандрівників допомагати зберігати її природну гармонію.",al={"аринія клаудзбрейк","хто така аринія","вартова аринія"}},{q="Де знайти Аринію Клаудзбрейк?",a="Аринія стоїть просто неба на Галявині Оракула, у північно-західній частині Тельдрассила, на північ від Доланаара.",al={"місце аринії","де аринія","карта аринії клаудзбрейк"}},{q="Які обов'язки вона виконує серед Вартових?",a="Як Вартова, що служить у нетрях, вона обходить дальні лісові гілки, стежачи за місцевими духами, тваринами й природними явищами, чи немає ознак скверни або порушення рівноваги.",al={"роль аринії","що робить аринія"}},{q="Чи вона родичка когось іще на Тельдрассилі?",a="Вона має те саме прізвище, що й Маворіс Клаудсбрейк, тож, певно, їх пов'язує родинний зв'язок серед нічних ельфів, що живуть на Світовому Дереві.",al={"родина аринії","маворіс клаудзбрейк"}},{q="Які доручення вона дає шукачам пригод?",a="Вона дає доручення дослідити зачаровану галявину, з'ясувати причини таємничих збурень і подбати про звірів, що блукають поблизу, зокрема допомогти створінням, які потрапили в біду.",al={"завдання аринії","завдання галявини оракула"}},{q="Чим Галявина Оракула важлива для нічних ельфів?",a="Галявина Оракула — священне святилище на Тельдрассилі, відоме тихими водоймами й духовною шаною; її оберігають друїди й Вартові, що шукають у природи порад і знамень.",al={"чому галявина оракула","лор галявини оракула"}}},fp="27,268,27.297.0,20.290.0,35.195.0,38.126.0,46.186.0,44.125.0,40.178.0,55.182.0"}
P.entries["npc:sentinel-aynasha"] = {n="Вартова Айнаша",s="Вартова Айнаша — розвідниця Вартових нічних ельфів, що служить на диких рубежах Темного Узбережжя. Їй доручено стежити за пересуваннями ворога й доставляти важливі донесення, тож вона раз у раз ризикує життям у сутичках із ворожими силами, що загрожують півночі Калімдору.",h="Вартова Айнаша — розвідниця Вартових нічних ельфів, що служить на диких рубежах Темного Узбережжя.",kw={"вартова айнаша","вартові","розвідниця","нічні ельфи","темне узбережжя","калімдор"},ang={["faction:Alliance"]="Для мандрівників Альянсу в Калімдорі розвідниці Вартових на кшталт Айнаші — важливі союзниці на небезпечних лісових дорогах.",["race:NightElf"]="Айнаша втілює пильний авангард війська калдореїв, що боронить давні ліси від чужинських сил і дикої порчі."},sec={{t="На передовій",b="Як розвідниця й лучниця Вартових, Айнаша служить на небезпечних рубежах, де землі нічних ельфів стикаються з ворожими вторгненнями. Виконуючи таємні завдання й доставляючи нагальні донесення пересіченою місцевістю, вона покладається на влучність і чуття виживання, щоб оминати ворожі дозори й уціліти глибоко на спірній території."}},faq={{q="Хто така Вартова Айнаша?",a="Айнаша — діяльна розвідниця й лучниця серед Вартових нічних ельфів — головної військової й оборонної сили, що захищає північний Калімдор і його кордони.",al={"хто така айнаша","роль айнаші","лор вартової айнаші"}},{q="За якими загрозами вона стежить на Темному Узбережжі?",a="Діючи на околицях Темного Узбережжя, вона стежить за ворожими таборами, свавільними племенами фурболгів і чужинцями, що вдираються в нетрі нічних ельфів.",al={"вороги айнаші","загрози темного узбережжя","з ким вона воює"}},{q="Чому вона часто сама на дорозі?",a="Вартові часто мандрують поодинці чи невеликими парами розвідників, щоб переносити термінові відомості між заставами, не привертаючи зайвої уваги ворогів.",al={"чому вона сама","місія айнаші наодинці","обов'язки розвідниці вартових"}}},fp="16,256,18.347.0,24.158.0,43.166.0,38.162.0"}
P.entries["npc:sentinel-elissa-starbreeze"] = {n="Вартова Елісса Старбріз",s="Вартова Елісса Старбріз — охоронниця з нічних ельфів, що служить в Обердайні на імлистих берегах Темного Узбережжя. З верхнього поверху будинку за мостом вона стежить за дедалі грізнішими загрозами краю й скеровує мандрівників до нагальних справ у нетрях.",h="Вартова Елісса Старбріз — охоронниця з нічних ельфів, що служить в Обердайні на імлистих берегах Темного...",kw={"вартова елісса старбріз","обердайн","вартові","вежа альталакса","нічні ельфи","темне узбережжя"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що прибувають із Тельдрассилу, Старбріз — одна з перших, хто скеровує допомогу вглиб примарних пусток Темного Узбережжя.",["race:NightElf"]="Вартова Старбріз втілює пильний і дисциплінований захист, який Вартові дають північним заставам Калімдору на кшталт Обердайна."},sec={{t="Пильне око Обердайна",b="Багато Вартових самі патрулюють туманне узбережжя й ліси, а Елісса Старбріз координує оборону з Обердайна. Розташувавшись на верхньому поверсі будівлі трохи на північний схід від заїзду, по той бік мосту, вона чуйно стежить за незвичними збуреннями на Темному Узбережжі. Її доручення часто ведуть шукачів пригод до віддалених місць, зокрема до таємничої Вежі Альталакса, що бовваніє далеко на півночі, — щоб тіньові вторгнення не застали прибережне поселення зненацька."}},faq={{q="Де знайти Вартову Еліссу Старбріз?",a="Вона в Обердайні на Темному Узбережжі. Перейдіть місточок на північний схід від корчми й підніміться на другий поверх будинку за ним — там вона несе службу.",al={"місце елісси старбріз","де елісса старбріз","оберін старбріз"}},{q="Які її обов'язки на Темному Узбережжі?",a="Як одна з Вартових нічних ельфів, вона допомагає берегти Обердайн, вистежуючи можливі небезпеки на Темному Узбережжі. Вона посилає вправних розвідників і шукачів пригод досліджувати далекі застави й дивні загрози, як-от Вежу Альталакса.",al={"що робить елісса","роль елісси старбріз"}},{q="Чи має вона родичів серед нічних ельфів?",a="Вона носить прізвище Старбріз, як і кілька відомих нічних ельфів у різних краях, зокрема жриці й військові, як-от Белісра Старбріз і Лейтенант Морра Старбріз.",al={"рід старбріз","чия родичка елісса"}}},fp="26,274,27.507.0,44.168.0,30.245.0,43.188.0"}
P.entries["npc:sentinel-farsong"] = {n="Вартова Фарсонг",s="Вартова Фарсонг — вартова нічних ельфів у Гаї Срібнокрилих в Ашенвалі. Вона відіграє ключову роль у зв'язку з Вартовими Срібнокрилих: збирає розвідку й керує бойовими зусиллями проти Дозорців Пісні Війни, що наступають в Ущелині Бойової Пісні.",h="Вартова Фарсонг — вартова нічних ельфів у Гаї Срібнокрилих в Ашенвалі.",kw={"вартова фарсонг","вартові срібнокрилих","гай срібнокрилих","ущелина бойової пісні","дозорці пісні війни","ашенваль"},ang={["faction:Alliance"]="Вартова Фарсонг уособлює мобілізацію Альянсу на передовій в Ашенвалі: вона спрямовує добровольців просто в боротьбу з кланом Бойової Пісні.",["race:NightElf"]="Як захисниця священних лісів Елуни, Фарсонг втілює рішучість калдореїв вигнати кожного, хто оскверняє прадавні гаї."},sec={{t="Охоронниця Гаю Срібнокрилих",b="Вартова Фарсонг, що несе варту в Гаї Срібнокрилих, глибоко залучена до оборони південного кордону Ашенвалю. Клан Бойової Пісні безупинно рубає ліс і просувається дедалі глибше на родові землі нічних ельфів, тож вона збирає звитяжців Альянсу для ударів по Дозорцях Пісні Війни й дбає, щоб донесення з поля бою доходили до командування Срібнокрилих. Головне її завдання — гуртувати добровольців, щоб стримати територіальне розширення Орди й уберегти священні ліси."}},faq={{q="Хто така Вартова Фарсонг?",a="Вартова Фарсонг — нічна ельфійка з Вартових Срібнокрилих в Ашенвалі. Вона служить у Гаю Срібнокрилих біля входу до Ущелини Бойової Пісні, набирає шукачів пригод Альянсу й збирає важливі бойові відомості.",al={"фарсонг","лор вартової фарсонг","хто така фарсонг"}},{q="Де її знайти?",a="Вона в Гаю Срібнокрилих на південному сході Ашенвалю — місці збору для воєнних дій Альянсу в Ущелині Бойової Пісні.",al={"місце вартової фарсонг","де фарсонг","карта фарсонг ясенлісся"}},{q="Чому вона воює з Дозорцями Пісні Війни?",a="Дозорці Пісні Війни рубають ліс і оскверняють священні гаї Ашенвалю. Фарсонг організовує оборону, щоб зупинити їхню справу й повернути землі, захоплені Ордою.",al={"чому воювати з дозорцями співу війни","мотивація фарсонг","конфлікт ясенлісся"}}},fp="16,251,28.463.0,24.238.0,23.142.0,42.197.0"}
P.entries["npc:sentinel-onaeya"] = {n="Вартова Онаея",s="Вартова Онаея — охоронниця з нічних ельфів на Посту Маестри на північному заході Ашенвалю, біля межі з Темним Узбережжям. Їй доручено тримати оборону від загроз, що підступають, і вона гуртує вправних шукачів пригод з Альянсу, щоб берегти ліс і допомагати іншим вартовим.",h="Вартова Онаея — охоронниця з нічних ельфів на Посту Маестри на північному заході Ашенвалю, біля межі з Темним...",kw={"вартова онаея","пост маестри","вартова айнаша","темне узбережжя","фурболги","ашенваль"},ang={["faction:Alliance"]="Онаея керує важливими оборонними справами для мандрівників Альянсу, що переходять із диких прибережних країв у спірні ліси Ашенвалю.",["faction:Horde"]="Як віддана вартова, що тримає Пост Маестри, Онаея — активний ворожий боєць, що стереже північні підступи до Ашенвалю.",["race:NightElf"]="Для нічних ельфів, що мандрують на південь із Темного Узбережжя, Онаея — передова оборони священних лісів Ашенвалю від зовнішніх загроз."},sec={{t="Вартова на прикордонні",b="Пост Маестри — важлива придорожня застава на шляху з Темного Узбережжя в густі, спірні хащі Ашенвалю. Вартова Онаея стоїть на варті біля головної оселі поселення: вона пильно стежить за мандрівниками й керує обороною. Ворожі звірі, сили порчі й прикордонна напруга — тож вартові на кшталт Онаеї стають першою лінією оборони поселень нічних ельфів у цьому краї."},{t="Утримати пост",b="До Онаеї доходять звістки про Вартову Айнашу, на яку напали фурболги, коли вона несла важливе донесення через Темне Узбережжя. Вона винагороджує шукачів пригод, які захищають отруєну вартову, поки не подіє протиотрута."}},faq={{q="Хто така Вартова Онаея?",a="Вартова Онаея — нічна ельфійка з Вартових на Посту Маестри на північному заході Ашенвалю. Вона дає завдання й обороняє передову, спрямовуючи мандрівників на допомогу заставі.",al={"онаея","вартова онаея","хто така онаея"}},{q="Де перебуває Вартова Онаея?",a="Вона стоїть просто біля головної будівлі на Посту Маестри, при північній дорозі в Ашенвалі, одразу під межею з Темним Узбережжям.",al={"місце онаеї","де вартова онаея","знайти онаею"}},{q="До якої фракції належить Вартова Онаея?",a="Вона з Вартових нічних ельфів і вірна Альянсу. Шукачі пригод Орди побачать, що вона ворожа до них з першого погляду.",al={"фракція онаеї","чи онаея альянсу","чи онаея дружня до орди"}},{q="Що пов'язує Онаею з Вартовою Айнашею?",a="Вартова Айнаша просить шукачів пригод доповісти Онаеї на Посту Маестри, після того як ті захистять її від нападу фурболгів. Онаея винагороджує їхню відвагу й радіє, що Айнаша вижила.",al={"онаея айнаша","нагорода вартової айнаші"}},{q="Які доручення дає Вартова Онаея?",a="Онаея винагороджує шукачів пригод, які захистили Вартову Айнашу від нападу фурболгів на Темному Узбережжі й принесли на Пост Маестри звістку, що та в безпеці.",al={"завдання онаеї","які завдання має онаея"}},{q="Чому Пост Маестри важливий для Вартових?",a="Пост Маестри — важливий пропускний пункт, що пов'язує шляхи постачання Темного Узбережжя із серцем Ашенвалю. Утримуючи його, Вартові не дають ворогам відрізати нічних ельфів, що мандрують на південь.",al={"чому пост маестри важливий","значення поста маестри"}}},fp="15,274,23.435.0,16.215.0,23.187.0,33.154.0,44.122.0,44.186.0,45.140.0,49.197.0"}
P.entries["npc:sentinel-selarin"] = {n="Вартова Селарін",s="Вартова Селарін — розвідниця нічних ельфів, яку послали до приморського поселення Обердайн. Як посланиця захисників Ашенвалю, вона шукає підкріплення, щоб стримати дедалі більші небезпеки, що загрожують прадавньому лісові.",h="Вартова Селарін — розвідниця нічних ельфів, яку послали до приморського поселення Обердайн.",kw={"вартова селарін","обердайн","терентіс","рейн вульфраннер","підкріплення","темне узбережжя"},ang={["faction:Alliance"]="Селарін — важливий місток для звитяжців Альянсу, що мандрують на південь із Темного Узбережжя в спірну глушину Ашенвалю.",["race:NightElf"]="Як одна з вартових, Селарін втілює пильність і єдність, без яких не захистити родових кордонів калдореїв."},sec={{t="Благання про підкріплення",b="Що більше по всьому Ашенвалю наростають напруга й темні загрози, то ближче тамтешній гарнізон до межі своїх сил. За наказом Рейн Вульфраннер Вартова Селарін вирушила лісовою дорогою на північ, у Темне Узбережжя. Її завдання було просте: знайти в Обердайні Терентіса й попросити допомоги у вартових і розвідників, що служать на узбережжі."},{t="Як згуртувати мандрівників",b="Прибувши до Обердайна, Селарін побачила, що Терентіс з головою поринув у місцеві справи й не може сам відгукнутися на заклик. Не бажаючи повертатися ні з чим, Селарін вирішила лишитися в містечку й наймати вправних мандрівників, що проходять Темним Узбережжям. Вона посилає досвідчених шукачів пригод на південь, до Астранаару, закликаючи їх віддати свої клинки й чари обложеним загонам Рейн Вульфраннер."}},faq={{q="Хто така Вартова Селарін?",a="Вартова Селарін — нічна ельфійка-воїн із Вартових. Вона гінець і зв'язкова, яку відрядили з Ашенвалю просити допомоги в поселення Обердайн на Темному Узбережжі.",al={"лор селарін","хто така селарін","вартова селарін"}},{q="Навіщо Селарін прибула до Обердайна?",a="Рейн Вульфраннер наказала їй знайти в Обердайні Терентіса й домогтися підкріплень для боротьби з дедалі більшими небезпеками, що загрожують нетрям Ашенвалю.",al={"чому селарін на темному узбережжі","місія селарін","що робить селарін"}},{q="Чому Терентіс не пішов із нею до Ашенвалю?",a="Терентіс був зайнятий важливими справами й розслідуванням загроз на самому Темному Узбережжі. Тож Селарін вирішила замість нього залучити до походу на південь незалежних мандрівників Альянсу.",al={"чому терентіс не допомагає","терентіс і селарін","терентіс зайнятий"}},{q="Куди вона посилає шукачів пригод?",a="Вона посилає шукачів пригод на південь, через кордон до Ашенвалю, щоб доповісти безпосередньо Рейн Вульфраннер в Астранаарі.",al={"куди селарін посилає","призначення завдання селарін","після селарін"}}},fp="16,230,25.381.0,22.397.0,24.182.0,34.162.0,46.196.0,32.119.0"}
P.entries["npc:sentinel-thenysil"] = {n="Вартова Тенісіль",s="Вартова Тара Тенісіль — вартова нічних ельфів, що служить в Астранаарі серед давнього лісу Ашенваль. Пильнуючи навколишню дику місцину, вона уважно стежить за військовими діями в краї й керує розвідниками, які наглядають за сусідніми землями. Особливо її цікавлять пересування союзників, що просуваються на південь, у спірні Гори Кам'яного Кігтя.",h="Вартова Тара Тенісіль — вартова нічних ельфів, що служить в Астранаарі серед давнього лісу Ашенваль.",kw={"вартова тенісіль","астранаар","ашенваль","каела шедовспір","храм місяця","тіранда віспервінд","вартові"},ang={["faction:Alliance"]="Ставши першим містком між Ашенвалем і Горами Кам'яного Кігтя, Тенісіль дає шукачам пригод з Альянсу нагоду здобути прихильність самої верхівки Дарнасуса.",["race:Gnome"]="Тенісіль вважає відрядження гнома-мага з Альянсу до Гір Кам'яного Кігтя незвичним і тривожним знаком — і це показує, наскільки дивними нічні ельфи досі вважають своїх маленьких союзників.",["race:NightElf"]="Тенісіль уособлює сумлінну варту вартових, що невтомно працюють, аби вберегти священні гаї Калімдору й захистити союзних агентів на прикордонних рубежах."},sec={{t="Наглядаючи за кордонами",b="Зі свого поста в укріпленому Астранаарі Вартова Тенісіль допомагає захищати Ашенваль від дедалі більшої ворожості. Володіння нічних ельфів по всьому краю зазнають невпинних зазіхань, тож зв'язок між віддаленими заставами вкрай важливий. Більшість місцевої залоги зосереджена на захисті лісової дороги, а Тенісіль посилає добровольців з Альянсу за межі Ашенвалю, щоб далекі союзники не лишилися без підтримки."},{t="Зв'язки з Горами Кам'яного Кігтя",b="Тенісіль пов'язує тісна особиста й бойова дружба з Каелою Шедовспір — агенткою, яку послали на південь, у скелі Гір Кам'яного Кігтя. Дізнавшись, що Каелу відрядили разом із дивакуватим гномом-магом, Тенісіль сприйняла цю незвичну пару як безпомилковий знак серйозної біди, що назріває у вершинах. Остерігаючись небезпек, які можуть чекати на подругу, вона наймає вправних шукачів пригод вирушити на південь, допомогти й доповісти про перебіг місії."},{t="Прийом серед крон",b="Коли розвідники повертаються з Гір Кам'яного Кігтя з вістю про вдалі удари по Венчурній Компанії, що плюндрує край, Тенісіль дбає, щоб їхні звитяги не лишилися непоміченими. Розуміючи, що відсіч механізованому визискуванню в горах захищає святість усієї сусідньої дикої природи, вона дає надійним героям офіційну подяку. Замість привласнювати заслуги в Астранаарі, вона спрямовує їх до Храму Місяця в Дарнасусі на особистий прийом у Верховної Жриці Тіранди Віспервінд."}},faq={{q="Де знайти Вартову Тенісіль?",a="Вартова Тенісіль служить в Астранаарі — головній твердині нічних ельфів при центральній дорозі Ашенвалю.",al={"місце тенісіль","де вартова тенісіль","тенісіль астранаар"}},{q="Чому Тенісіль посилає мандрівників до Гір Кам'яного Кігтя?",a="Її подругу, Каелу Шедовспір, відрядили до Гір Кам'яного Кігтя разом із гномом-магом. Вбачаючи в такому незвичному призначенні ознаку небезпечних негараздів, Тенісіль посилає надійних шукачів пригод підсилити місію Каели.",al={"чому стоунталон","завдання тенісіль стоунталон","чому на варті в стоунталоні"}},{q="Хто така Каела Шедовспір?",a="Каела Шедовспір — нічна ельфійка-розвідниця й близька подруга Вартової Тенісіль. Вона служить у Горах Кам'яного Кігтя, розслідуючи загрози для краю.",al={"хто така каела","каела шедовспір родичка","подруга тенісіль"}},{q="З якими загрозами борються в Горах Кам'яного Кігтя?",a="Окрім сутичок із місцевими ворогами, у Горах Кам'яного Кігтя закріпилася Венчурна Компанія зі своїми загарбницькими й руйнівними промислами: вона хижацьки видобуває руду й нищить ліси.",al={"загроза стоунталона","що відбувається в стоунталоні","венчурна компанія стоунталон"}},{q="Чому Тенісіль посилає шукачів пригод до Тіранди Віспервінд?",a="Коли шукачі пригод допоможуть Каелі Шедовспір зірвати задуми Венчурної Компанії в Горах Кам'яного Кігтя, Тенісіль посилає їх до Дарнасуса, щоб Верховна Жриця Тіранда Віспервінд особисто відзначила їхню службу нічним ельфам.",al={"прийом у тіранди","чому до тіранди","направлення тенісіль до дарнасу"}},{q="Яка роль Вартової Тенісіль в Астранаарі?",a="Вона координує Вартових в Астранаарі: допомагає збирати відомості в краї, стежить за кордонами й посилає надійних новобранців Альянсу підтримати далекі гарнізони.",al={"звання тенісіль","що робить тенісіль","обов'язки вартової тенісіль"}}},fp="17,379,20.435.0,18.480.0,22.489.1,37.122.0,57.214.0,25.159.0,44.194.0,58.248.1,46.177.0"}
P.entries["npc:sentinel-tysha-moonblade"] = {n="Вартова Тиша Мунблейд",s="Вартова Тиша Мунблейд — розвідниця з нічних ельфів, що стоїть на головній дорозі Темного Узбережжя трохи на захід від давніх руїн Амет'Арана. Патрулюючи тривожні прибережні нетрі, вона скеровує мандрівників і шукає допомоги, щоб розібратися з неспокійними духами, що блукають сусідніми зруйнованими ельфійськими поселеннями.",h="Вартова Тиша Мунблейд — розвідниця з нічних ельфів, що стоїть на головній дорозі Темного Узбережжя трохи на...",kw={"вартова тиша мунблейд","амет'аран","привиди","баньші","високородні","темне узбережжя"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що йдуть з Обердайна на південь до Ашенвалю, Тиша — один із небагатьох дружніх постів на загалом небезпечній дорозі, де кишать чудовиська.",["race:NightElf"]="Тиша втілює пильних Вартових, що намагаються зберегти мир на землях, досі поораних шрамами давнього Розколу, і просить родичів — нічних ельфів — упокоїти своїх проклятих предків."},sec={{t="Варта на дорозі",b="Стоячи на варті при зарослому тракті Темного Узбережжя, Тиша Мунблейд пильно наглядає за дедалі неспокійнішою землею. Просто на схід від неї лежать примарні руїни Амет'Арана, де серед давніх кам'яних колон блукають прокляті привиди Високородних і злісні баньші. Розуміючи, що невеликі сили оборони Обердайна розпорошені між загрозами по всьому узбережжю, Тиша залучає здібних шукачів пригод, що проходять повз, щоб з'ясувати історію трагічного падіння Амет'Арана й упокоїти неспокійних мерців."}},faq={{q="Хто така Вартова Тиша Мунблейд?",a="Вартова Тиша Мунблейд — нічна ельфійка-охоронниця, що обходить головну дорогу в центрі Темного Узбережжя трохи на захід від руїн Амет'Арану. Вона стереже шлях від мандрівних звірів і неспокійних примар.",al={"хто така тиша","лор тиші мунблейд","вартова тиша"}},{q="Де знайти Вартову Тишу Мунблейд?",a="Вона стоїть при дорозі з півночі на південь на Темному Узбережжі, просто на захід навпроти стародавніх руїн Амет'Арану.",al={"місце тиші мунблейд","де тиша","де вартова тиша"}},{q="Які доручення вона дає шукачам пригод?",a="Тиша посилає мандрівників до сусідніх руїн Амет'Арану розслідувати давню трагедію, що зруйнувала стародавнє поселення нічних ельфів, і допомогти втихомирити змучених привидів, що блукають серед повалених колон.",al={"завдання тиші мунблейд","давець завдань падіння аметарана","чого хоче тиша"}},{q="Чи вона родичка когось іще на Темному Узбережжі?",a="Вона має те саме прізвище, тож, певно, родичка Мореплавця Мунблейда, якого також можна зустріти на службі нічним ельфам на узбережжі Темного Узбережжя.",al={"мореплавець мунблейд родич","рід мунблейд тиші"}}},fp="24,315,19.509.0,32.213.0,42.126.0,40.207.0,43.143.0"}
P.entries["npc:sentinel-velene-starstrike"] = {n="Вартова Велене Старстрайк",s="Вартова Велене Старстрайк — охоронниця з нічних ельфів у Притулку Срібного Вітру в центральному Ашенвалі. Їй доручено захищати святилище й довколишні води, тож вона протистоїть протиприродним загрозам — свавільним елементалям і мерзенним чаклунам. Її пильність допомагає вберегти прадавній ліс від згубного магічного втручання.",h="Вартова Велене Старстрайк — охоронниця з нічних ельфів у Притулку Срібного Вітру в центральному Ашенвалі.",kw={"велене старстрайк","притулок срібного вітру","озеро містраль","водяні елементалі","вартова","ашенваль"},ang={["class:Mage"]="Велене не має терпцю до безвідповідальних чаклунів, чиї безрозсудні викликання збурюють місцевих елементалів і забруднюють природні води.",["faction:Alliance"]="Притулок Срібного Вітру дає безпеку на небезпечній дорозі, а Вартова Велене керує місцевими зусиллями, щоб центральний Ашенваль лишався в безпеці.",["race:NightElf"]="Вартова Велене втілює невтомну відданість вартових: вона стоїть заслоном від магічного безрозсуддя, щоб зберегти природну злагоду Ашенвалю."},sec={{t="Охоронниця Срібного Вітру",b="Вартова Велене Старстрайк несе пильну варту в Притулку Срібного Вітру, біля чистих вод Озера Містраль. Як і багато вартових нічних ельфів по всьому Ашенвалю, вона передусім береже рівновагу лісу й відбиває загрози ельфійським святилищам. Тихий гай — важлива зупинка для мандрівників, що йдуть центральними лісами, тож без неї тут не було б безпеки."},{t="Неспокій на Озері Містраль",b="Мир довкола Притулку Срібного Вітру крихкий. Велене пильно стежить за Озером Містраль, де непередбачувані духи стихій і безрозсудні маги-закликачі порушують природний ритм дикого краю. За її вказівками звитяжці вирушають приборкувати свавільних водяних елементалів і зупиняти недбалих чаклунів, що тривожать духів землі."}},faq={{q="Де перебуває Вартова Велене Старстрайк?",a="Вартова Велене Старстрайк служить у Притулку Срібного Вітру — заставі Альянсу в центрі Ашенвалю, неподалік від південно-східного берега Озера Містраль.",al={"місце велене старстрайк","де велене","давець завдань притулку срібного вітру"}},{q="Які доручення дає Вартова Велене?",a="Велене просить шукачів пригод упоратися з неспокійними духами й заклиначами довкола Озера Містраль: зібрати наручі з розбурханих елементалів і знешкодити свавільних заклиначів, що баламутять воду.",al={"завдання велене старстрайк","які завдання дає велене"}},{q="Що за загроза на Озері Містраль?",a="Води Озера Містраль баламутять агресивні водяні елементалі, яких розбурхують і використовують смертні маги-заклиначі, що займаються своїм ремеслом, не зважаючи на тендітну гармонію лісу.",al={"проблема озера містраль","чому елементалі на озері містраль"}},{q="Чи Велене родичка когось іще в Калімдорі?",a="Вона має прізвище Старстрайк, як і Лайо Старстрайк — нічний ельф, що служить далеко на півдні, у суворих пустищах Силітусу, тож вони, певно, з одного роду чи дому.",al={"рід старстрайк","лайо старстрайк родич"}},{q="Що таке Притулок Срібного Вітру?",a="Притулок Срібного Вітру — тихий прихисток нічних ельфів на березі Озера Містраль в Ашенвалі. Це і мирна гавань, і тактична застава для Вартових і союзних мандрівників, що пробираються дикою глибиною лісу.",al={"що таке притулок срібного вітру","лор притулку срібного вітру"}},{q="Чому Вартових турбують збурення стихій?",a="Нічні ельфи вважають дику природу священним живим цілим. Шалені чи зіпсовані елементалі порушують життя місцевих тварин і псують природні води, тож Вартовим доводиться втручатися й відновлювати рівновагу.",al={"чому нічні ельфи воюють зі стихіями","вартові й елементалі"}}},fp="26,346,22.440.0,28.360.0,44.156.0,39.211.0,35.212.0,45.180.0,26.232.0,51.213.0"}
P.entries["npc:serge-hinott"] = {n="Серж Гінотт",s="Серж Гінотт — алхімік-Відступник у Таррен Міллі в Передгір'ї Гілсбреда. Працюючи пліч-о-пліч з Аптекарем Лайдоном, він допомагає Королівському Аптекарському Товариству варити суміші, протиотрути й реагенти, вкрай потрібні Відступникам на війні.",h="Серж Гінотт — алхімік-Відступник у Таррен Міллі в Передгір'ї Гілсбреда.",kw={"серж гінотт","аптекар","таррен мілл","протиотрута","дотик занзіла","відступники"},ang={["class:Rogue"]="Гінотт допомагає розбійникам, що шукають ліків від згубного Дотику Занзіла, і готує рятівну протиотруту, коли звичайні засоби безсилі.",["race:Undead"]="Гінотт — практична рука Королівського Аптекарського Товариства в Гілсбреді: він постачає потрібні хімічні суміші й допомогу просто військам Відступників на передовій."},sec={{t="Права рука аптекаря в Таррен Міллі",b="Поряд з Аптекарем Лайдоном в укріпленому Таррен Міллі Серж Гінотт відіграє важливу допоміжну роль для Відступників у Передгір'ї Гілсбреда. Поки Лайдон зосереджується на ширших хімічних розробках і наступальних дослідженнях чуми проти сусідніх людських поселень на кшталт Саутшора, Гінотт береться за особливі варива. Він уміє готувати цілющі мазі й необхідні протиотрути, коли польові агенти й розвідники натрапляють на небезпечні отрути чи отруйні халепи."}},faq={{q="Де знайти Сержа Гінотта?",a="Серж Гінотт служить у Таррен Міллі, у центрально-північній частині Передгір'я Гілсбреда. Він стоїть надворі неподалік від Аптекаря Лайдона, серед своїх пивоварних припасів і алхімічного обладнання.",al={"місце сержа гінотта","де гінотт","знайти сержа гінотта"}},{q="Яку роль відіграє Серж Гінотт?",a="Він алхімік на службі Відступників у Таррен Міллі. Окрім того, що допомагає готувати місцеві напої й ліки, він варить особливі суміші на замовлення польових агентів і кур'єрів.",al={"що робить гінотт","роль сержа гінотта"}},{q="Що пов'язує Гінотта з Аптекарем Лайдоном?",a="Гінотт працює просто поруч з Аптекарем Лайдоном у Таррен Міллі, але приязні між ними мало: відвідувачам, що його відволікають, Гінотт радить піти й докучати краще «пану Зарозумільцю».",al={"гінотт і лайдон","з ким працює гінотт"}}},fp="12,261,32.511.0,32.212.0,34.211.0,48.187.0"}
P.entries["npc:shadow-priest-allister"] = {n="Жрець Тіні Аллістер",s="Жрець Тіні Аллістер — жрець-Відступник, що несе службу в Гробниці в Срібноліссі. Він керує розвідкою й тактичними діями в краї, організовуючи стеження за чарівниками Даларана й захист кордонів Лордерона для Темної Леді.",h="Жрець Тіні Аллістер — жрець-Відступник, що несе службу в Гробниці в Срібноліссі.",kw={"жрець тіні аллістер","гробниця","відступники","свята ковбаса","даларан","срібнолісся"},ang={["class:Priest"]="Як автор «Святої Ковбаси», Аллістер уособлює погляд Відступників на Культ Забутої Тіні та їхнє розчарування у Світлі.",["faction:Horde"]="Аллістер дбає про безпеку Срібнолісся, щоб союзники Орди могли безпечно проходити між Галявинами Тірісфалю й землями на півдні.",["race:Undead"]="Аллістер утілює безжальний прагматизм Відступників: він відвернувся від колишніх святих догм, щоб захистити свій народ від живих ворогів."},sec={{t="Вартовий у Гробниці",b="Жрець Тіні Аллістер, що діє з Гробниці, керує розвідкою Відступників по всьому Срібноліссю. З цього поселення-крипти він стежить за загрозами поблизу — від людей-ренегатів і навал звірів до таємних задумів, що розгортаються біля мерехтливого купола Даларана."},{t="Око на Амбермілл і Даларан",b="Найбільше Аллістера непокоять уцілілі маги Даларана, особливо ті, що засіли в Амберміллі й прощупують кордони. Не бажаючи дати Кірін-Тору закріпитися на землях Відступників, він посилає агентів перехоплювати даларанських гінців, розшифровувати таємні руни й з'ясовувати далекосяжні наміри чарівників."},{t="Єретичні роздуми",b="Окрім обов'язків польового стратега, Аллістер — цинічний філософ тіні. Він автор трактату «Свята Ковбаса: Чого Світло Вам Не Розповість» — нищівної критики традиційного святого вчення. У тексті йдеться про сувору правду нежиття і про те, як Святе Світло підводить тих, кого відкинуло життя, — і цей твір якимось чином дійшов аж до руїн Лютопаща на Калімдорі."}},faq={{q="Хто такий Жрець Тіні Аллістер?",a="Це жрець тіні з Відступників у Гробниці в Срібноліссі, що організовує стеження й удари по загрозах поблизу, насамперед по силах Даларану.",al={"аллістер","жрець тіні аллістер","хто такий аллістер сільверпайн"}},{q="Де знайти Жерця Тіні Аллістера?",a="Він у Гробниці — головному поселенні Відступників при головній дорозі через Срібнолісся.",al={"місце аллістера","де жрець тіні аллістер","знайти аллістера"}},{q="Чому Аллістер зосереджений на Даларані й Амбермілі?",a="Маги Кірін-Тору в Амбермілі — постійна загроза землям Відступників. Аллістер прагне розшифрувати їхні послання, з'ясувати їхні наміри й стримати їхній вплив.",al={"аллістер даларан","чому напад на амбермілл","загроза даларана сільверпайн"}},{q="Яку книгу написав Аллістер?",a="Аллістер написав «Свята Ковбаса: Чого Світло Вам Не Розповість» — зухвалу й нищівну критику Святого Світла, що дісталася аж за море, до стародавніх бібліотек Лютопаща.",al={"книга аллістера","свята болонья","чого світло не розповість"}},{q="Які завдання дає Аллістер?",a="Він дає кілька розвідувальних доручень у Срібноліссі, зокрема «Перетин кордону», «Мапи й руни», «Розслідування в Амбермілі», а також завдання проти агентів Даларану.",al={"завдання аллістера","завдання жерців тіні гробниці"}},{q="Чому Аллістер практикує магію Тіні, а не Святе Світло?",a="Як і багато жерців-Відступників, які після смерті відчули, що Святе Світло їх покинуло, Аллістер звернувся до тіней і знайшов силу й рішучість у науці, яка приймає їхнє існування в нежитті.",al={"чому жрець тіні","магія тіні відступників аллістер"}}},fp="22,262,24.298.0,29.332.0,17.407.0,30.172.0,40.123.0,49.198.0,29.191.0,32.183.0,66.194.0"}
P.entries["npc:shadow-priest-sarvis"] = {n="Жрець Тіні Сарвіс",s="Жрець Тіні Сарвіс стоїть у зруйнованій каплиці Похоронного Подзвону — один із головних провідників щойно пробуджених Відступників. Він знайомить свіжих мерців з їхньою похмурою дійсністю, посилаючи їх винищувати безтямну нежить і збирати відомості про місцеві загрози. Під прапором Леді Сильвани Сарвіс невтомно ліпить із розгублених мерців дисциплінованих слуг Відступників.",h="Жрець Тіні Сарвіс стоїть у зруйнованій каплиці Похоронного Подзвону — один із головних провідників щойно...",kw={"жрець тіні сарвіс","похоронний подзвін","каплиця","відступники","пробудження","погибель","тінь"},ang={["class:Priest"]="Сарвіс утілює те, як Відступники прийняли магію тіні: темний наставник у каплиці, позбавленій Святого Світла.",["race:Undead"]="Сарвіс — один із найперших голосів, які ви чуєте, прокинувшись у могилі; він ставить вас на шлях служіння Темній Леді."},sec={{t="Пастир щойно пробуджених",b="У тінистій каплиці Похоронного Подзвону Жрець Тіні Сарвіс чекає на тих, хто щойно вигрібся з могили. Пробудження душі Відступника — струс і жах: багато хто одразу втрачає розум у безтямному шалі чи відчаї. Сарвіс — опора, що дає мету щойно воскреслим. Він доручає новобранцям добивати шкутильгаючі безтямні трупи, які блукають цвинтарем, і посилає їх убезпечувати межі Похоронного Подзвону від Погибелі, що насувається."},{t="Убезпечення Похоронного Подзвону",b="Окрім того, що Сарвіс призвичаює новобранців, він наглядає за важливою місцевою обороною від невідступних загроз у Галявинах Тірісфалю. Він координує стримування сил Погибелі, що промацують околиці Похоронного Подзвону. Спрямовуючи новачків на здобуття важливих відомостей і бойові випробування, Сарвіс дбає, щоб містечко лишалося укріпленим бастіоном Відступників."}},faq={{q="Хто такий Жрець Тіні Сарвіс?",a="Сарвіс — жрець тіні з Відступників у Похоронному Подзвоні. Він наставляє щойно пробуджену нежить, дає перші накази й допомагає боронити селище від Погибелі.",al={"хто такий сарвіс","сарвіс","жрець похоронного подзвону"}},{q="Де знайти Жерця Тіні Сарвіса?",a="Він у зруйнованій церкві в центрі Похоронного Подзвону — стартового краю Відступників у Галявинах Тірісфалю.",al={"місце сарвіса","де сарвіс","знайти сарвіса"}},{q="Чому Сарвіс посилає гравців убивати безмозких зомбі?",a="Не кожен мрець, піднятий із могили, зберігає вільну волю й розум. Тих, хто збожеволів, вважають небезпекою для поселення, і їх треба знищити, перш ніж вони почнуть загрожувати живим мерцям.",al={"чому вбивати безмозких","безмозкі"}}},fp="20,390,30.491.0,19.340.0,28.176.0,38.114.0,51.201.0"}
P.entries["npc:shael-dryn"] = {n="Шаель'дрін",s="Шаель'дрін — допитлива дріада, що живе біля Місячного Колодязя Чистоти, на схід від Озера Ірисів в Ашенвалі. Вона — важлива помічниця розвідників нічних ельфів, які досліджують скверну в лісі. Саме вона допомагає вартовим Астранаару очищувальними реліквіями в боротьбі з демонічними й згубними силами, що ширяться дикими землями.",h="Шаель'дрін — допитлива дріада, що живе біля Місячного Колодязя Чистоти, на схід від Озера Ірисів в Ашенвалі.",kw={"шаель'дрін","дріада","місячний колодязь чистоти","ашенваль","астранаар","жезл дартола"},ang={["class:Druid"]="Друїди оцінять її природний зв'язок із духами Калімдору та знання про те, як зцілити рослини й тварин, спотворених темними силами.",["faction:Alliance"]="Місячний Колодязь Чистоти — святилище в Ашенвалі, де Шаель'дрін допомагає силам Альянсу, що опираються скверні та ворожому наступу.",["race:NightElf"]="Для калдореїв Шаель'дрін — бажана сестра лісу: природний зв'язок із Кенарієм робить її незамінною в очищенні осквернених лісових реліквій."},sec={{t="Охоронниця місячного колодязя",b="Шаель'дрін живе біля Місячного Колодязя Чистоти й разом із вартовими нічних ельфів стереже східні підступи до лісу. Коли серед місцевих звірів проступає скверна або осквернені реліквії загрожують гармонії краю, її глибоке чуття природи допомагає провести шукачів пригод через усі кроки, потрібні для відновлення духовної рівноваги."},{t="Очищення лісів",b="Шаель'дрін тісно співпрацює з Рейн Вульфраннер з Астранаару. Коли вартові знаходять осквернені артефакти — як-от заражені сяйливі самоцвіти чи загублені частини Жезла Дартола, — Шаель'дрін знає маловідомі ритуали, воду місячних колодязів і природні дари, потрібні, щоб їх очистити. Так темні дивовижі стають для Альянсу потужними знаряддями очищення."}},faq={{q="Хто така Шаель'дрін?",a="Шаель'дрін — дріада, яку можна знайти біля Місячного Колодязя Чистоти в Ашенвалі. Вона допомагає шукачам пригод Альянсу знаннями про ліс і магією природи, не забуваючи при цьому про свою любов до каламбурів і жартів.",al={"хто вона","лор шаель'дрін","особа шаель'дрін"}},{q="Де знайти Шаель'дрін?",a="Вона біля Місячного Колодязя Чистоти, на схід від Озера Ірисів в Ашенвалі.",al={"місце шаель'дрін","де шаель'дрін","дріада рейнвуд"}},{q="Що пов'язує Шаель'дрін із Рейн Вульфраннер?",a="Рейн Вульфраннер посилає шукачів пригод до Шаель'дрін, бо дріада має духовні знання, потрібні, щоб дослідити й очистити зіпсовані самоцвіти й реліквії, знайдені по всьому лісі.",al={"рейн і шаель'дрін","рейн жезл очищення дріада","чому до шаель'дрін"}},{q="Що незвичайного у вигляді Шаель'дрін?",a="Шаель'дрін і її сестра-дріада Ілліяна мають рідкісне забарвлення, яке вирізняє їх серед більшості інших дріад Калімдору.",al={"модель дріади","унікальний вигляд","колір шаель'дрін"}},{q="Чи Шаель'дрін дружня до Орди?",a="Ні. Шаель'дрін живе біля Місячного Колодязя Чистоти, тісно співпрацює з вартовими Астранаару й ворожа до членів Орди.",al={"чи може орда говорити з шаель'дрін","репутація орди","чи шаель'дрін лише для альянсу"}}},fp="10,340,24.361.0,25.358.1,18.192.0,28.79.0,52.198.0,45.150.0,36.144.0"}
P.entries["npc:shanda"] = {n="Шанда",s="Шанда — жриця й наставниця, нічна ельфійка, що перебуває в порожнистому стовбурі Алдрассила в Тінедолі. Служачи Сестринству Елуни, вона навчає жерців-новачків із нічних ельфів основних молитов, оберегів та обрядів Місячної Богині. Її провід допомагає молодим послушникам урівноважити світло Елуни з обов'язками захисту Тельдрассила.",h="Шанда — жриця й наставниця, нічна ельфійка, що перебуває в порожнистому стовбурі Алдрассила в Тінедолі.",kw={"шанда","жриця","наставниця","сестринство елуни","елуна","алдрассил","тінедол"},ang={["race:NightElf"]="Шанда уособлює тривку традицію Сестринства Елуни, дбаючи про духовне здоров'я калдорейської молоді, що робить перші кроки на Тельдрассилі."},sec={{t="Послушниця Місячної Матері",b="Стоячи в тихому святилищі Алдрассила, Шанда — одна з перших духовних провідниць молодих нічних ельфів, відданих Елуні. Поки друїди доглядають коріння й віття Тельдрассила наяву, жриці на кшталт Шанди дбають, щоб духовне серце калдореїв лишалося прив'язаним до Білої Леді. Вона навчає нових посвячених спрямовувати місячну ласку на зцілення й захисні обереги, готуючи їх до зустрічі зі скверною, що повзе у віття Світового Дерева."},{t="Провід для нових посвячених",b="Коли молоді жерці пробуджуються до свого покликання в Тінедолі, їх спрямовують до Шанди довести відданість і вивчити перші молитви. Обрядами на кшталт «В ім'я Елуни» вона випробовує їхню рішучість і дає їм благословенне вбрання та основні замовляння. Під її проводом учні дізнаються, що жриця калдореїв має бути і лагідною рукою для поранених, і непохитним щитом проти тіней."}},faq={{q="Хто така Шанда?",a="Шанда — нічна ельфійка, наставниця жерців в Алдрассилі, центральному поселенні в дуплі дерева в Тінедолі на Тельдрассилі. Вона навчає щойно пробуджених нічних ельфів-жерців учення Сестринства Елуни.",al={"хто цей нпс","лор шанди","тренер жерців алдрассіл"}},{q="Яку роль Шанда відіграє для нових жерців?",a="She introduces novice priests to basic prayers, curative spells, and protective magic gifted by Elune. New priests bring their Hallowed Sigil to her, and she sends them to the next stage of their training through In Favor of Elune.",al={"роль тренера жерців","чого навчає шанда","що робить шанда"}},{q="Де знайти Шанду?",a="Шанда — на першому рівні в дуплистому стовбурі Алдрассила, величезного дерева, що є стартовим осередком у Тінедолі на Тельдрассилі.",al={"де шанда","місце шанди","як знайти шанду"}},{q="До якої спільноти належить Шанда?",a="Шанда належить до Сестринства Елуни — стародавнього релігійного ордену жриць нічних ельфів, що тисячоліттями веде духовне й культурне життя калдореїв.",al={"фракція шанди","сестринство елуни","чи шанда жриця місяця"}}},fp="6,348,26.491.0,21.422.0,14.218.0,43.231.0,24.150.0,40.176.0"}
P.entries["npc:shandris-feathermoon"] = {n="Шандріс Фезермун",s="Шандріс Фезермун — Генерал Армії Вартових і названа донька Тіранди Віспервінд і Малфуріона Стормрейджа. Досвідчена лучниця, що воювала у Війні Прадавніх, нині вона командує військовими силами нічних ельфів по всьому Калімдору з Твердині Перистого Місяця на Острові Сардор біля узбережжя Фераласу.",h="Шандріс Фезермун — Генерал Армії Вартових і названа донька Тіранди Віспервінд і Малфуріона Стормрейджа.",kw={"шандріс фезермун","вартові","твердиня перистого місяця","тіранда віспервінд","нічні ельфи","фералас","війна прадавніх"},ang={["class:Hunter"]="Мисливці й рейнджери шанують Шандріс як одну з найвправніших лучниць в історії: один її влучний оперений постріл міг змінити перебіг давніх воєн.",["faction:Alliance"]="Для сил Альянсу, що вирушають на південь Калімдору, генерал Фезермун забезпечує важливу присутність флоту, стратегічне керівництво й добре укріплений прихисток на Острові Сардор.",["faction:Horde"]="Орда вважає генерала Фезермун небезпечною й хитрою воєначальницею, чия фортеця біля узбережжя Фераласу загрожує її поширенню в краї.",["race:NightElf"]="Для калдореїв генерал Фезермун — вершина дисципліни й обов'язку Вартових: вона береже свій народ від самого початку довгої варти."},sec={{t="Дитя Розколу",b="Десять тисяч років тому, під час Війни Прадавніх, демонічний Палаючий Легіон знищив село Ара-Гінам, розлучивши юну Шандріс з родиною. Утікаючи на південь, вона натрапила на військо Кур'талоса Рейвенкреста, яке її врятувало, і її вдочерила Жриця Місяця Тіранда Віспервінд. Спершу дівчині заборонили йти на поле бою, але Шандріс потай ходила слідом за Сестрами Елуни й показала себе неперевершеною стрільчинею. Коли сатир Ксавіус напав на Малфуріона Стормрейджа, Шандріс з узлісся влучила в лиходія стрілою — і цього було досить, щоб Малфуріон обплутав і знешкодив зрадника."},{t="Злет Вартових",b="Після Великого Розколу й заснування Вартових Шандріс стала незамінною командувачкою у війську нічних ельфів. Через століття, у Війні Сатирів, вона водила загони в жорстокі сутички з рештками демонічних сил і на власні очі побачила трагічну, нестримну лють перших воргенів. У Третю війну Шандріс разом із Тірандою вела вартових із загону Тіньолистих і стояла на схилах Гори Гіджал, захищаючи Світове Древо Нордрассіл від легіонів Архімонда."},{t="Бастіон Фераласу",b="Сьогодні генерал Фезермун — верховна польова командувачка армії Вартових. З Острова Сардор вона керує Твердинею Перистого Місяця — грізною ельфійською фортецею, що стереже первісну глушину Фераласу. Із цієї острівної застави вона стежить за загрозами, що наближаються: дикими гнолами, огрями Ґордунні, що досі тут лишаються, сатирами, сповненими ненависті, і дедалі більшою силою Орди на півдні Калімдору."}},faq={{q="Хто така Шандріс Фезермун?",a="Шандріс Фезермун — генерал Вартових, постійного війська нічних ельфів. Вона давня лучниця, ветеранка Війни Прадавніх і битви за Гору Гіджал, а також прийомна донька Верховної Жриці Тіранди Віспервінд.",al={"хто така шандріс","лор шандріс","хто нічна генералка у фераласі"}},{q="Де знайти Шандріс Фезермун?",a="Вона командує з Твердині Перистого Місяця на Острові Сардор біля західного узбережжя Фераласу на півдні Калімдору.",al={"місце шандріс","де шандріс фезермун","керівниця твердині фезермун"}},{q="Що пов'язує Шандріс із Тірандою Віспервінд?",a="Тіранда вдочерила Шандріс під час Війни Прадавніх, коли село дівчинки, Ара-Гінам, було зруйноване, а вона втратила батьків. Шандріс виховували Тіранда й Малфуріон Стормрейдж, і під їхнім проводом вона опанувала божественне зцілення й воєнне проводирство.",al={"чи шандріс дочка тіранди","тіранда й шандріс","прийомна дитина тіранди"}},{q="Чи билася Шандріс із Палаючим Легіоном?",a="Так. Вона воювала і під час давнього вторгнення десять тисяч років тому — її стріли вразили першого сатира, Ксавіуса, — і згодом, у Третю війну, вела Вартових-Тіньолистих у битві за Гору Гіджал, захищаючи Нордрассил.",al={"війна давніх шандріс","чи шандріс билась з арчімондом"}},{q="Яку роль Шандріс відіграла в появі воргенів?",a="Під час Війни Сатирів Шандріс вела Вартових у бій разом із союзниками-друїдами проти ватажка сатирів Ксалана. Коли друїди вивільнили некеровану подобу вовчої зграї, вона стала свідком появи перших воргенів і допомагала боротися з ними, доки Малфуріон не стримав їх Косою Елуни.",al={"шандріс воргени","коса елуни шандріс","війна сатирів воргени"}},{q="Чому вона у Фераласі, а не на Тельдрассилі?",a="Як генерал Вартових, Шандріс має керувати воєнними діями на передовій по всьому Калімдору. Твердиня Перистого Місяця — головне місце збору й оплот Альянсу в диких південних лісах, звідки стежать за ворожими ограми, сатирами й діями Орди.",al={"чому шандріс у фераласі","чому твердиня фезермун"}}},fp="20,306,22.621.0,21.511.0,22.413.0,28.260.0,40.120.0,55.264.0,46.234.0,58.305.0,54.269.0"}
P.entries["npc:shari-stilwell"] = {n="Шарі Стілвелл",s="Шарі Стілвелл — наставниця паладинів Відступників, що перебуває в поселенні Брілл на Галявинах Тірісфалю. Носячи прізвище, спільне з помітними постатями Східних Королівств, вона навчає тих Відступників, що беруть на себе мантію святих воїнів. Її присутність знаменує рідкісну й незвичну дисципліну серед нежиті під рукою Королеви Баньші.",h="Шарі Стілвелл — наставниця паладинів Відступників, що перебуває в поселенні Брілл на Галявинах Тірісфалю.",kw={"шарі стілвелл","паладин","наставниця","брілл","джордан стілвелл","світло"},ang={["class:Paladin"]="Для паладинів Відступників, що починають свій шлях на Галявинах Тірісфалю, Шарі Стілвелл — головна наставниця й провідниця у Бріллі.",["race:Undead"]="Шарі Стілвелл віддзеркалює трагічне розколювання родин, спричинене Третьою війною: вона стоїть наставницею-нежиттю, поки її можлива рідня живе далеко на півдні."},sec={{t="Маяк у Бріллі",b="Серед позначених пошестю будівель Брілла Шарі Стілвелл вирізняється як наставниця святих воїнів Відступників. Хоч святе Світло для нежиті нестерпно болісне, Шарі веде молодих Відступників, які витримують цей болісний шлях. Вона допомагає новачкам, що шукають опори на Галявинах Тірісфалю, у перших тренуваннях і звиканні, скеровуючи тих, хто хоче посісти своє місце в королівстві Відступників."},{t="Узи імені Стілвелл",b="Шарі носить те саме прізвище, що й кілька живих постатей, розсіяних по південних королівствах, — зокрема Дафна, Мерісса й уславлений коваль Джордан Стілвелл. Чи відірвало її від цієї рідні падіння Лордерону, чи їх пов'язує лише далеке споріднення — лишається невимовленою трагедією спустошення, яке принесла Погибель."}},faq={{q="Хто така Шарі Стілвелл?",a="Шарі Стілвелл — нежить, наставниця паладинів у Бріллі в Галявинах Тірісфалю. Вона дає паладинам-Відступникам перші бойові й святі уроки, поки ті вчаться виживати в Лордероні.",al={"хто така шарі стілвелл","лор шарі стілвелл","тренер паладинів брилла"}},{q="Де знайти Шарі Стілвелл?",a="Вона в містечку Брілл, трохи на північ від руїн Столиці й Андерсіті в Галявинах Тірісфалю.",al={"місце шарі стілвелл","де шарі стілвелл","знайти шарі стілвелл"}},{q="Чи Шарі родичка Джордана Стілвелла?",a="Вона має те саме прізвище, що й Джордан Стілвелл, знаменитий коваль-людина, а також Дафна й Мерісса Стілвелл. Точний родинний зв'язок не підтверджено, і, певно, його обірвала чума, що знищила Лордерон.",al={"шарі родичка джордана стілвелла","рід стілвелл зв'язки","родичі шарі стілвелл"}},{q="Чи можуть Відступники володіти Світлом як паладини?",a="Черпати Святе Світло для нежиті вкрай болісно: воно завдає жахливих мук і пече. Проте наставники на кшталт Шарі Стілвелл ведуть рішучих Відступників шляхом духовної стійкості й відданості, без яких не опанувати і бойової майстерності, і святої сили.",al={"відступники паладини","як нежить може бути паладином","лор нежиті-паладина"}}},fp="14,338,17.419.0,25.324.0,22.197.0,34.111.0,36.213.0,41.267.0"}
P.entries["npc:shelene-rhobart"] = {n="Шелін Робарт",s="Шелін Робарт — наставниця шкіряного ремесла Відступників, що працює при дорозі на Галявинах Тірісфалю. Облаштувавшись на заставі Вартових Смерті, вона постачає вичинені шкури й навчає шкіряного ремесла, підтримуючи військові й господарські зусилля Відступників по всіх уражених землях.",h="Шелін Робарт — наставниця шкіряного ремесла Відступників, що працює при дорозі на Галявинах Тірісфалю.",kw={"шелін робарт","шкіряне ремесло","наставниця","застава","виготовлення","тірісфаль"},ang={["race:Undead"]="Шелін утілює прагматичний підмурок ремесла Відступників: завдяки їй місцеві захисники належно споряджені попри розклад і спустошення Тірісфалю."},sec={{t="Ремесло для Відступників",b="Шелін Робарт провадить своє ремесло на заставі Вартових Смерті — форпості на південний схід від Брілла, при головній дорозі до руїн Лордерону. Навіть у нежитті практичні ремесла лишаються конче потрібними для виживання й війни. Шелін працює зі шкурами звірів, здобутими з хижаків, що никають Тірісфалем, і береться за виготовлення з грубих шкур броні, ременів і похідного спорядження для місцевих патрулів Відступників, які протистоять і Погибелі, і багряним хрестоносцям."}},faq={{q="Де знайти Шелін Робарт?",a="Шелін Робарт служить на невеликому посту Відступників на південний схід від Брілла в Галявинах Тірісфалю, при дорозі до Андерсіті.",al={"місце шелін робарт","де шелін робарт","карта шелін робарт"}},{q="Яку роль відіграє Шелін Робарт?",a="Вона вправна наставниця шкірників. Вона навчає новачків основ вичинки шкур, шиття одягу й виготовлення захисного шкіряного спорядження для Відступників.",al={"що робить шелін робарт","шелін тренер","професія шелін"}},{q="Навіщо їй шкури звірів?",a="Шкіра нежиті не гоїться, тож поранені Відступники мусять латати себе шкурами тварин. Запаси Шелін закінчуються, і їй потрібні перетинки крил сутінкових кажанів, шкури темних гончаків і шкіра мурлоків-темноплавців, бо різна товщина пасує до різних частин тіла.",al={"завдання шкур для відступників","навіщо збирати шкури тіріс"}}},fp="15,275,25.447.0,33.145.0,37.188.0,30.281.0"}
P.entries["npc:shenthul"] = {n="Шентул",s="Шентул — троль із джунглів, наставник розбійників у тінистих підземних закутках Тіньової Розколини в Оргріммарі. Як агент Розтрощеної Руки, він керує розвідувальними операціями по всьому Калімдору й посвячує молодих розбійників у таємні лави гільдії.",h="Шентул — троль із джунглів, наставник розбійників у тінистих підземних закутках Тіньової Розколини в...",kw={"шентул","розбійник","розтрощена рука","тіньова розколина","оргріммар","тролі","розвідка"},ang={["class:Rogue"]="Шентул — головний наставник і куратор розбійників Орди, що прибувають до Оргріммара: він навчає навичок, проводить випробування посвяти й дає таємні доручення.",["faction:Horde"]="Діючи під поверхнею столиці, Шентул керує таємною розвідкою, що захищає Орду від невидимих загроз ізсередини й ззовні.",["race:Troll"]="Як троль із джунглів, що глибоко вкорінився в традиційно орочій Розтрощеній Руці, Шентул показує, як розбійники Темного Списа увійшли до найвищих щаблів розвідки Орди."},sec={{t="Очі в безодні",b="Шентул, що ховається в каламутних глибинах Тіньової Розколини, — один із найкращих наставників розбійників Орди. Поки воїни й шамани нагорі відкрито крокують червоним пилом Дуротару, Шентул навчає тих, хто віддає перевагу скритності, засідкам і підступу. Під його проводом новачки опановують необхідні польові навички й смертоносні мистецтва та вчаться діяти серед безжальної політики й суворої дикої природи Калімдору."},{t="Розтрощена Рука",b="Шентул представляє Розтрощену Руку — орден, що з давнього орочого клану перетворився на розвідувальну мережу й таємну службу Орди. Він бачить свою організацію як вічну, пильну завісу над Калімдором, що водночас є слідчим, суддею, присяжними й катом. Запеклий прагматик, незалежний від мінливих політичних вітрів, Шентул любить нагадувати чужинцям, що Розтрощена Рука існувала задовго до того, як Вождь Тралл прийшов до влади, і житиме ще довго після нього."},{t="Таємна польова робота",b="Окрім базового вишколу, Шентул координує делікатні місії на спірних землях. Його доручення посилають агентів на небезпечні вилазки: таємні операції глибоко в тилу ворога, вправи у зламуванні замків на скринях із припасами Венчурної Компанії довкола Кручі Вітрорізу й суворі таємні випробування для новобранців. Коли його польових агентів уражає отрута, Шентул дбає, щоб вони роздобули протиотруту, перш ніж стане запізно."}},faq={{q="Хто такий Шентул?",a="Шентул — троль із джунглів, наставник розбійників і агент Розтрощеної Руки, що служить у Тіньовій Розколині під Оргріммаром.",al={"роль шентула","хто такий шентул","троль тренер розбійників оргріммар"}},{q="Де знайти Шентула?",a="Він у Тіньовій Розколині — системі підземних печер, куди ведуть темніші тунелі Оргріммара.",al={"місце шентула","де шентул","шентул тіньова розколина"}},{q="Що пов'язує Шентула з Розтрощеною Рукою?",a="Шентул — відданий агент і вербувальник Розтрощеної Руки, таємної розвідувальної гільдії вбивць, що діє в Орді.",al={"шентул розтрощена рука","чи шентул розтрощена рука","яка фракція шентула"}},{q="Що Шентул думає про Вождя Тралла?",a="Шентул вірний ремеслу й безпеці Орди, але наполягає, що Орден Розтрощеної Руки існував до Тралла й переживе його правління, і вважає свою гільдію вічною потребою.",al={"шентул про тралла","чи шентулу подобається тралл","вірність шентула"}},{q="Які доручення Шентул дає розбійникам?",a="Він проводить розбійників через випробування посвяти, посилає на таємні вилазки й вказує на замкнені скрині з припасами Венчурної Компанії в Горах Кам'яного Кігтя, щоб вони вдосконалили вміння відмикати замки.",al={"завдання шентула","завдання розбійників шентула"}},{q="Чи допомагає Шентул з отрутами розбійників?",a="Так, під час важливих польових операцій, коли розбійники стикаються зі смертельними отрутами, Шентул посилає агентів до Гінотта, щоб ті вижили й могли працювати далі.",al={"завдання отрути шентула","допомога гінотта шентулу"}}},fp="8,270,17.430.0,18.476.0,16.496.1,16.128.0,26.121.0,52.142.0,44.199.0,44.206.0,40.145.0"}
P.entries["npc:shindrell-swiftfire"] = {n="Шіндрелл Свіфтфайр",s="Шіндрелл Свіфтфайр — вартова й розвідниця нічних ельфів в Астранаарі, серці діяльності нічних ельфів в Ашенвалі. Вона добре знає, як змінюються небезпеки на західних околицях Калімдору, і скеровує вправних шукачів пригод з Альянсу проти загроз, що збираються на узбережжі та в довколишніх гірських перевалах. Завдяки цьому вона стала важливим осередком місцевої оборони від нових загроз із моря й дикої природи.",h="Шіндрелл Свіфтфайр — вартова й розвідниця нічних ельфів в Астранаарі, серці діяльності нічних ельфів в...",kw={"шіндрелл свіфтфайр","астранаар","вартова","наги","зорамське узмор'я","ашенваль"},ang={["class:Hunter"]="Її завдання — вистежувати гордокрилів і розвідувати дикі узбережжя — близькі серцю розвідників і слідопитів, що вміють виживати в дикій природі.",["faction:Alliance"]="Шіндрелл — дієва сполучна ланка в Астранаарі: вона веде новоприбулих з Альянсу глибше в спірні й небезпечні землі центрального Калімдору.",["race:NightElf"]="Для нічних ельфів Шіндрелл уособлює пильних вартових, що стережуть околиці Ашенвалю від давніх ворогів на кшталт наг, поки головні сили протистоять Орді."},sec={{t="Пильне око Астранаару",b="Із в'юнких переходів Астранаару Шіндрелл Свіфтфайр уважно стежить за ширшими рубежами Ашенвалю. Поки на вартових лісу безупинно тиснуть лісозаготівельні вторгнення Орди зі сходу й півдня, Шіндрелл не зводить очей з небезпек, що лежать за межами найближчого лісового фронту. Вона — важлива сполучна ланка для мандрівників, які прибувають із Темного Узбережжя чи рушають до зубчастих хребтів Кам'яного Кігтя, і дбає, щоб жодна раптова загроза не вдарила по Астранаару з незахищеного флангу."},{t="Загроза на узбережжі",b="Одна з головних турбот Шіндрелл — неспокійне Зорамське Узмор'я на північно-західному узбережжі Ашенвалю. Раптова поява ворожих наг, що виповзають із морських глибин, — і тяжка загадка, і пряма загроза поселенням калдореїв. Посилаючи досвідчених бійців дослідити узбережжя й діяти разом із розвідниками, що ближче до місця подій, Шіндрелл намагається стримати змієлюдей-загарбників, перш ніж ті назавжди закріпляться на прадавніх землях нічних ельфів."}},faq={{q="Де знайти Шіндрелл Свіфтфайр?",a="Шіндрелл Свіфтфайр служить в Астранаарі — головному містечку нічних ельфів в Ашенвалі. Її можна знайти на дерев'яних кладках поселення, де вона керує розвідкою й приймає мандрівників.",al={"місце шіндрелл свіфтфайр","де шіндрелл","знайти шіндрелл свіфтфайр"}},{q="Яка роль Шіндрелл в Астранаарі?",a="Вона керує розвідниками й дає завдання від Альянсу, спрямовуючи шукачів пригод проти зовнішніх загроз Ашенвалю — наг на західному узбережжі та диких звірів у сусідніх горах.",al={"що робить шіндрелл","хто така шіндрелл свіфтфайр","мета шіндрелл"}},{q="Чому вона посилає розвідників на Берег Зорам?",a="Ворожі наги хлинули на західні береги Ашенвалю, захопили руїни й загрожують кордонам нічних ельфів. Шіндрелл посилає шукачів пригод розвідати пляжі й допомогти польовим Вартовим приборкати зміїну загрозу.",al={"чому берег зорам","завдання наг шіндрелл","місія берега зорам"}},{q="Що пов'язує Шіндрелл із Горами Кам'яного Кігтя?",a="Коли Ашенвалю загрожують з усіх боків, утримати високі перевали — життєво важливо. Шіндрелл посилає розвідників розібратися з лютими вівернами Гордокрилими й підтримувати зв'язок із калдорейськими розвідниками, що стежать за межею Гір Кам'яного Кігтя.",al={"завдання стоунталона","завдання гордих крил","чому стоунталон"}},{q="Чи пов'язана Шіндрелл із Чорноглибинними Печерами?",a="Її турбота про Берег Зорам веде просто в тінь Чорноглибинних Печер. Досліджуючи наг на узбережжі, шукачі пригод, яких посилає Шіндрелл, виявляють темнішу водяну загрозу, що назріває під хвилями.",al={"шіндрелл чорноглибина","зв'язок із чорноглибинними печерами","шіндрелл чорноглибинні"}},{q="Хто такий Кейнет Стіллвінд і чому Шіндрелл про нього згадує?",a="Кейнет Стіллвінд — союзний розвідник, що служить у нетрях. Шіндрелл посилає шукачів пригод розшукати його, щоб важливими відомостями й підкріпленнями можна було обмінюватися між далекими заставами краю.",al={"хто такий кейнет","завдання кейнета стіллвінда","зв'язок із кейнетом"}}},fp="19,413,27.509.0,23.464.0,37.201.0,38.218.0,45.221.0,48.227.0,46.218.0,61.205.0"}
P.entries["npc:shoni-the-shilent"] = {n="Шоні Тихий",s="Шоні Тихий — працьовита гномська інженерка з гамірного Дворфійського Кварталу Стормвінда. Вона очолює гномреґанську бригаду підземного штурму й посилає шукачів пригод з Альянсу до Мертвих Копалень, щоб добути джерело живлення з гоблінського потрощувача — пальне для машин, які, як вона сподівається, проб'ють шлях назад до Гномреґана.",h="Шоні Тихий — працьовита гномська інженерка з гамірного Дворфійського Кварталу Стормвінда.",kw={"шоні тихий","гноми","гномреґан","дворфійський квартал","інженерія","мертві копальні"},ang={["profession:Engineering"]="Інженери оцінять неймовірну механічну складність гіросвердломатичних екскаваціонаторів, які Шоні хоче оживити серцем потрощувача, здобутим під Мунбруком.",["race:Gnome"]="Для гномських героїв допомога Шоні — ще один крок до того, щоб прорватися назад до Гномреґана й повернути загиблу домівку."},sec={{t="Командирка глибин",b="Працюючи в задимлених майстернях Дворфійського Кварталу, Шоні втілює гномську стратегічну винахідливість далеко від утрачених залів Гномреґана. Її інженерні плани амбітні. Гномреґан у руках трогів, тож Шоні готує підземний штурм, щоб його відвоювати, і посилає своїх посланців у тунелі під Вестфолом по деталі, яких бракує її бригаді."},{t="Повернення з-під землі",b="План Шоні тримається на власних гномських гіросвердломатичних екскаваціонаторах — важких бурильних машинах, що мають пробитися крізь скелясті підземні рубежі Гномреґана й відкрити шлях для гномського наступу. Потужності їм бракує, тож Шоні потрібне ціле джерело живлення — Ґноам Спрекльспрокет — із робочого гоблінського потрощувача глибоко в Мертвих Копальнях. Згодом вона посилає шукачів пригод і до самого Гномреґана — розбирати тамтешніх роботів на запчастини, щоб полагодити свій механічний парк."}},faq={{q="Хто така Шоні Тихий?",a="Шоні Тихий — гномка в Дворфійському Кварталі Стормвінда, що дає завдання. Вона командує гномреґанським підземним штурмовим загоном і організовує підземні вилазки, щоб повернути втрачене.",al={"хто така шоні","лор шоні","шоні тихий нпс"}},{q="Де знайти Шоні?",a="Вона серед ковадел і майстерень Дворфійського Кварталу в Стормвінді, неподалік від ковальських та інженерних майстерень.",al={"де шоні","місце шоні","знайти шоні"}},{q="Чому Шоні цікавлять Мертві Копальні?",a="Глибоко в Мертвих Копальнях працює справний гоблінський потрощувач. Шоні залучає шукачів пригод принести його неушкоджене джерело живлення — Ґноам Спрекльспрокет, — щоб її гіробуроматичні екскаваціонатори змогли пробитися крізь підземні кордони Гномреґана.",al={"шоні мертві копальні","чому посилає в мертві копальні","завдання джайродрилматика"}},{q="Чому її звуть «Тихий»?",a="Звідки взялося прізвисько Шоні, невідомо. Вона відома тим, що командує гномреґанським підземним штурмовим загоном.",al={"прізвисько шоні","чому тихий","тихий гном"}}},fp="17,338,21.385.0,24.469.0,25.201.0,23.136.0,41.245.0,32.110.0"}
P.entries["npc:sicco-thermaplugg"] = {n="Сікко Термаплаґ",kw={"сікко термаплаґ","термаплаґ","мехінженер","гномреґан","прокажені гноми","меккаторк","зрада"},ang={["faction:Alliance"]="Через зраду Термаплаґа Гномреґан не зміг відгукнутися на заклик до зброї в Третю війну, що підірвало шляхи постачання й інженерну підтримку Альянсу в найтемнішу годину людства.",["profession:Engineering"]="Термаплаґ — уособлення смертельної небезпеки недбалих формул і безпринципного конструювання: на кожного, хто ввійде до його майстерні, він обрушує небезпечні крокуючі бойові машини й отруйні бомбові роздавачі.",["race:Dwarf"]="Ваші родичі в Айронфорджі прихистили обідраних уцілілих, що тікали від отрути Термаплаґа, а вартові Айронфорджа пильно стережуть брами Дун Мороґу від його опромінених блукальців.",["race:Gnome"]="Термаплаґ — втілення всього, що ваш народ оплакує й зневажає: його марнославство й зрада коштували вам батьківщини, а ваших родичів перетворили на хворих потвор."},sec={{t="Отруйне честолюбство",b="Сікко Термаплаґ навчався разом із Ґелбіном Меккаторком в Університеті Ґіршафт, і вони разом працювали над багатьма ранніми механічними здобутками, зокрема першими облоговими машинами. Ґелбін вважав його блискучим другом, але Сікко роз'їдала гірка заздрість: він був переконаний, що інтуїтивний геній Ґелбіна затьмарює його власну працю. Коли Меккаторка обрали Великим Тінкером, образа Сікко переросла у відверту злобу. Вірячи, що лише він має безжальне бачення, потрібне, щоб обернути гномські технології на геополітичну силу, Сікко вичікував у Дворі Майстрів, шукаючи будь-якої нагоди зганьбити суперника."},{t="Отруєння Гномреґана",b="Коли під час Третьої війни підземні троги заполонили Гномреґан, гноми п'ять відчайдушних років билися самотою в підземній темряві. Шукаючи способу прорвати облогу, не обтяжуючи Альянс, Ґелбін звернувся по пораду до Термаплаґа. Сікко показав підроблені креслення щільного радіоактивного газу, запевнивши, що той безпечно осяде в нижніх тунелях і знищить трогів, а гномські очисники повітря захистять мирних мешканців нагорі. Насправді ж Термаплаґ навмисно хибно розрахував об'єм і отруйність газу. Він хотів завдати рівно стільки втрат, щоб скинути Меккаторка з влади й самому очолити місто."},{t="Король руїн",b="Thermaplugg's calculations proved catastrophically wrong. The radioactive fallout swept uncontrollably through all levels of the city, slaughtering eighty percent of the gnomish population and twisting many of the survivors into feral, diseased leper gnomes. Instead of ascending the throne of a thriving metropolis, Sicco himself was warped by the fallout. Driven utterly mad by the radiation, he crowned himself King of the Gnomes and now presides over a charnel house of irradiated machines and mutated thralls, fighting a perpetual war against trogg invaders and any surface gnomes seeking to reclaim their lost home."}},faq={{q="Хто такий Сікко Термаплаґ?",a="Це колишній головний радник Великого Тінкера Ґелбіна Меккаторка, що зрадив свій народ під час навали трогів. Прагнучи захопити владу, він переконав Меккаторка випустити в Гномреґан радіоактивний газ — це майже знищило гномів, а сам Термаплаґ лишився правити зараженими руїнами як божевільний король.",al={"хто такий термаплаґ","лор термаплаґа","бос гномреґана","минуле термаплаґа"}},{q="Чому Термаплаґ зрадив Ґелбіна Меккаторка?",a="Термаплаґ шалено заздрив Меккаторкові. Він вважав Ґелбіна переоціненим майстром, що не заслужив обрання Великим Тінкером. А ще Сікко зневажав Ґелбінову політику вільно ділитися винаходами з Альянсом: він вважав, що гномські технології треба обернути на зброю й створити могутню, грізну гномську імперію під своєю владою.",al={"чому він зрадив гномреґан","мотив термаплаґа","чому сікко ненавидить ґелбіна"}},{q="Чи Термаплаґ спричинив навалу трогів?",a="Спершу троги прорвалися на нижні рівні Гномреґана після того, як їх відкопали в стародавньому титанічному сховищі Ульдамана. Хоч і ходять чутки, ніби Термаплаґ заздалегідь знав про підземний прорив чи навіть посприяв йому, щоб спричинити кризу, Меккаторк так і не зміг з'ясувати, чи Сікко розпочав навалу, чи лише скористався нею.",al={"чи викликав він трогів","чи сікко привів трогів","походження навали трогів"}},{q="Що сталося з Термаплаґом після того, як випустили газ?",a="Як і тисячі інших гномів, що опинилися в епіцентрі лиха, Термаплаґ дістав смертельну дозу радіації. Зараження висушило його тіло, зробило шкіру хворобливо-зеленою й розщепило розум. Замість утекти разом з іншими біженцями до Айронфорджа, він лишився правити руїнами як самопроголошений Король Гномів.",al={"чи термаплаґ прокажений гном","як він став прокаженим","чому термаплаґ зелений"}},{q="Що таке Натовпотовкач 9-60?",a="Натовпотовкач 9-60 — велетенський охоронний механізм, якого винайшов Оґлторп Обнотікус. Термаплаґ украв креслення Обнотікуса, збудував велетенський прототип і випустив його на місто. Сікко звалив провину за погром на Обнотікуса, і винахідника вигнали, а Термаплаґ залишив автомат собі як особистого охоронця в Гномреґані.",al={"походження натовпотовкача","хто зробив натовпотовкача","вкрадені винаходи термаплаґа"}},{q="Що Великий Тінкер Меккаторк хоче зробити з Термаплаґом?",a="Меккаторк вважає Термаплаґа своєю найбільшою поразкою й найбільшим зрадником свого народу. Зі свого тимчасового двору в Містечку Майстрів в Айронфорджі Меккаторк доручає відважним шукачам пригод Альянсу спуститися в заражені глибини Гномреґана й стратити Сікко, щоб звершити правосуддя за загиблих.",al={"завдання ґелбіна про термаплаґа","вбити термаплаґа","чи меккаторк хоче його смерті"}}},fp="17,440,16.618.0,27.653.1,17.621.1,25.318.0,46.360.0,41.360.0,56.336.0,32.348.0,61.302.0"}
P.entries["npc:sida"] = {n="Сіда",s="Сіда — дворфійка, мешканка Гавані Менетіл у Багнокраї. Відома своїм розладнаним шлюбом з Ейнаром Стоунґріпом, вона проводить дні в портовому містечку, раз у раз потрапляючи в халепи на довколишніх болотах.",h="Сіда — дворфійка, мешканка Гавані Менетіл у Багнокраї.",kw={"сіда","ейнар стоунґріп","гавань менетіл","гробниця айронбірда","сумка сіди","багнокрай"},ang={["faction:Alliance"]="Для мандрівників з Альянсу, що сходять на причали Гавані Менетіл, Сіда має місцеві доручення, які ведуть углиб краю, до Гробниці Айронбірда.",["race:Dwarf"]="Сіда уособлює повсякденне життя дворфів у Гавані Менетіл — між родинними сварками й підступною глушиною одразу за міською брамою."},sec={{t="Мешканка гавані",b="Сіда живе в жвавому порту Альянсу, Гавані Менетіл, окремо від чоловіка, Ейнара Стоунґріпа. Їхні стосунки такі напружені, що Ейнар навідріз відмовляється ходити до Менетіла, доки Сіда в місті. Хоч вона й тримається прибережного поселення, Сіда часом вибирається в небезпечні краї Багнокраю — і нещодавно мала нещастя загубити свою торбу під час вилазки до Гробниці Айронбірда."}},faq={{q="Хто така Сіда?",a="Сіда — дворфійка, що живе в Гавані Менетіл у Багнокраї. Вона дає завдання шукачам пригод, які проходять через порт.",al={"хто така сіда","сіда нпс","сіда мокрі землі"}},{q="Що сталося з торбою Сіди?",a="Сіда загубила торбу, коли навідувалася до Гробниці Айронбірда — стародавнього поховання в Багнокраї. Відтоді там розплодилися мерзенні слизняки, що й поглинули її речі.",al={"де торба сіди","загублена торба","торба гробниці залізнобородих"}},{q="Чому Ейнар Стоунґріп не приходить до Гавані Менетіл?",a="Ейнар Стоунґріп — чоловік Сіди, з яким вони розійшлися. Через сварку між ними Ейнар оминає Гавань Менетіл, доки там живе Сіда.",al={"ейнар і сіда","чоловік сіди","ейнар стоунґріп драма"}},{q="Де знайти Сіду?",a="Сіда прогулюється пристанню й вулицями Гавані Менетіл на західному узбережжі Багнокраю.",al={"місце сіди","де сіда"}}},fp="4,226,17.454.0,12.124.0,28.178.0,48.152.0,24.108.0"}
P.entries["npc:sirra-von-indi"] = {n="Сірра Вон'Інді",s="Сірра Вон'Інді — історик Даркшира, що працює в ратуші серед стосів забутих записів. Знавець стародавніх мов і місцевої історії, він допомагає містечку розшифровувати загадкові документи й розкривати темне минуле Сутінколісся.",h="Сірра Вон'Інді — історик Даркшира, що працює в ратуші серед стосів забутих записів.",kw={"сірра вон'інді","даркшир","історик","ратуша даркшира","аберкромбі","морган ладімор"},ang={["class:Mage"]="Маги, що навідуються до Даркшира, часто цінують наукову дисципліну Сірри: його зосередженість на стародавніх мовах та історії нагадує архівні дослідження Кірін-Тору.",["faction:Alliance"]="Сірра уособлює вцілілі міські установи Даркшира й допомагає зберегти спадщину Королівства Стормвінд у краї, який інакше поглинула б темрява."},sec={{t="Міський Історик",b="Сірра Вон'Інді — найвидатніший учений Даркшира, що доглядає міський архів у Ратуші Даркшира. Поки міська варта зосереджена на безпосередніх загрозах із лісу, Сірра звертається до писаного слова: перекладає загадкові тексти й береже згасаючу історію Великого Селища — таким, яким воно було, доки на край не впала тінь."},{t="Розшифрувати слова відлюдника",b="Коли провід міста починає підозрювати відлюдника Аберкромбі, що живе на самотніх пагорбах Сутінколісся, Сіррі доручають перекласти загадкові записки самітника. Його мовознавчий хист дає раді змогу читати між рядків начебто невинних прохань і розплутувати дивні запити, що надходять із проклятого лісу."},{t="Трагедії минулого",b="Окрім звичайних перекладів, Сірра допомагає пролити світло на сумну історію Сутінколісся. Ті, хто хоче збагнути загадкову вивітрену могилу на міському цвинтарі, дізнаються, що Сірра — одна з небагатьох душ, які пам'ятають трагічне падіння паладина Моргана Ладімора, — і він дає мандрівникам знання, потрібні, щоб упокоїти неспокійних духів."}},faq={{q="Хто такий Сірра Вон'Інді?",a="Сірра Вон'Інді — учений і офіційний історик Даркшира. Він проводить дні в Ратуші Даркшира, вивчаючи давні мистецтва, перекладаючи маловідомі мови й ведучи історичні записи міста.",al={"хто такий сірра","лор сірри вон'інді","історик даркшира"}},{q="Де знайти Сірру Вон'Інді?",a="Він у Ратуші Даркшира, у поселенні Даркшир у центрі Сутінколісся. Зазвичай він стоїть серед столів і книжкових полиць, звіряючись з історичними текстами.",al={"місце сірри","де сірра вон'інді","знайти сірру в даркширі"}},{q="Яку роль він відіграє в історії із запискою Аберкромбі?",a="Коли мер Елло Ебонлок підозрює, що дивакуватий відлюдник Аберкромбі приховує справжні наміри, Сірра своїм знанням мов перекладає дивну записку відлюдника й допомагає раді зрозуміти химерні вимоги Аберкромбі.",al={"перекладач листа аберкромбі","переклад записки аберкромбі","сірра переклад записки"}},{q="Що Сірра знає про Моргана Ладімора?",a="Сірра — один із небагатьох мешканців Даркшира, хто знає всю історію Моргана Ладімора, полеглого паладина, похованого в Обвітреній Могилі. Він допомагає розповісти, як Ладімор після Третьої війни поринув у божевілля й трагедію.",al={"сірра вивітрена могила","морґан ладімор сірра","історія вивітреної могили"}},{q="Чому Сірра змушує мандрівників чекати, поки перекладає?",a="Розгадувати маловідомі говірки й старовинне письмо — копітка праця. Сірра часто просить мандрівників дати йому час, поки він звірить посилання й завершить надійний переклад.",al={"чому сірра змушує чекати","чекати сірру","переклад сірри"}}},fp="14,268,18.377.0,30.346.1,21.377.1,22.221.0,34.189.0,47.241.0,43.225.0,53.190.0"}
P.entries["npc:sister-aquinne"] = {n="Сестра Аквінн",s="Сестра Аквінн — послушниця Елуни, що живе в тихих Храмових Садах Дарнасуса. Ця жриця-новачка навчається у жрецтва Елуни при Храмі Місяця.",h="Сестра Аквінн — послушниця Елуни, що живе в тихих Храмових Садах Дарнасуса.",kw={"сестра аквінн","послушниця","храм місяця","храмові сади","жрецтво елуни","дарнасус"},ang={["class:Priest"]="Інші служителі Світла й Елуни можуть оцінити відданість Аквінн, яка проходить початкове навчання, обов'язкове для всіх послушниць Храму Місяця.",["race:NightElf"]="Для шукачів пригод із нічних ельфів, що прибувають до Дарнасуса, Сестра Аквінн — привітне обличчя в Храмових Садах і перша ниточка, що веде до величі храмового жрецтва."},sec={{t="Послушниця в Дарнасусі",b="Сестра Аквінн присвятила себе жрецтву Елуни в столиці нічних ельфів. У спокійних Храмових Садах, у затінку Храму Місяця, вона продовжує навчання під проводом Верховної Жриці та старших сестер. Коли колись велична лісова істота потребувала допомоги, саме Аквінн послала охочих мандрівників до Жриці А'мури в храмі, щоб дізнатися, що слід зробити."}},faq={{q="Де знайти Сестру Аквінн?",a="Сестра Аквінн стоїть у Храмових Садах Дарнасуса, просто біля величного Храму Місяця.",al={"місце аквінн","де сестра аквінн","координати аквінн"}},{q="Що відомо про Сестру Аквінн?",a="Вона послушниця-жриця Елуни, що навчається в Храмі Місяця в Дарнасусі. Про її життя до служіння в храмі відомо небагато.",al={"лор аквінн","хто сестра аквінн","минуле аквінн"}}},fp="14,186,20.435.0,34.115.0,36.153.0"}
P.entries["npc:skorn-whitecloud"] = {n="Скорн Вайтклауд",s="Скорн Вайтклауд — літній мисливець-таурен, що мешкає в Селі Бладгуф серед хвилястих рівнин Малгору. Він допомагає молодим мисливцям зрозуміти свій зв'язок із хижаками цієї землі й виручає мандрівників, що натрапляють на небезпеки, які чигають у Малгорі.",h="Скорн Вайтклауд — літній мисливець-таурен, що мешкає в Селі Бладгуф серед хвилястих рівнин Малгору.",kw={"скорн вайтклауд","мисливець","рівнинний бродяга","мелор стоунгуф","село бладгуф","малгор"},ang={["class:Hunter"]="Для молодих мисливців-тауренів Скорн Вайтклауд дає перші настанови у вистежуванні прудких хижаків на кшталт рівнинного бродяги, зміцнюючи духовну гармонію полювання.",["race:Tauren"]="Скорн — приклад відданості родини Вайтклаудів, яка дає прихисток, зброю й практичну мудрість розкиданим поселенням Малгору."},sec={{t="Провідник золотих рівнин",b="Скорн Вайтклауд, що живе в Селі Бладгуф у Малгорі, — старий мисливець, який тепер навчає мисливських звичаїв. Його головна роль — прищеплювати шану до диких створінь рівнин. Він випробовує майбутніх мисливців, посилаючи їх по кігті хитрих рівнинних бродяг Малгору, які потім показують Мелору Стоунгуфу в Тандер Блафі, — так ті, хто бере до рук лук чи спис, усвідомлюють рівновагу між хижаком і здобиччю."},{t="Пильність до неприродного",b="Окрім звичайних мисливських обов'язків, Скорн лишається пильним до дивних порушень у савані. Коли з'являються неприродні загрози — як-от сліди демонічної скверни на звірині рівнин, — Скорн допомагає відтворити, що сталося, і дбає, щоб племена Малгору не втрачали пильності перед злими силами, які прокрадаються в їхню прабатьківську домівку."}},faq={{q="Де знайти Скорна Вайтклауда?",a="Скорн Вайтклауд — у Селі Бладгуф, тауренському поселенні в південних степах Малгору.",al={"місце скорна","де скорн","карта скорна вайтклауда"}},{q="Яку роль Скорн відіграє для молодих мисливців?",a="Скорн навчає основ полювання через обряд, відомий як «Мисливський шлях». Він доручає майбутнім мисливцям довести свої вміння вистежувати й битися з хитрими рівнинними нишпорками, а потім посилає їх до Мелора Стоунгуфа в Тандер Блаф.",al={"що робить скорн","завдання мисливця скорна","шлях мисливця"}},{q="Що продає Скорн?",a="Скорн не торговець. Його мисливські дні минули, але він віддає одну зі своїх зброй — Молот Скорна чи Рушницю Скорна — мисливцеві, який принесе доказ, що великого вовка Примарне Виття вбито.",al={"торговець скорн","що продає скорн","зброя скорна"}},{q="Чи Скорн Вайтклауд родич інших тауренів Малгору?",a="Він має те саме прізвище, що й Постачальник Вайтклауд, тауренський торговець із Села Бладгуф, що натякає на спільну велику родину в племені.",al={"рід вайтклауд","родичі скорна","постачальник вайтклауд"}}},fp="16,259,28.453.0,31.364.1,36.110.0,44.260.0,27.197.0,59.149.0"}
P.entries["npc:skuerto"] = {n="Скуерто",s="Скуерто — дворф-розвідник, що несе службу в Притулку в Аратійському нагір'ї. Утративши домівку в Айронфорджі через наплив біженців, він тепер служить Альянсу далеко від міста й допомагає Архімагові Маліну здобувати прадавні магічні реліквії.",h="Скуерто — дворф-розвідник, що несе службу в Притулку в Аратійському нагір'ї.",kw={"скуерто","розвідник","притулок","аратійське нагір'я","архімаг малін","айронфордж","дворфи"},ang={["race:Dwarf"]="Скуерто — втілення завзяття дворфів, що мусили покинути Велику Кузню заради диких околиць, хоча його гордість розвідника дуже легко зачепити.",["race:Gnome"]="Гномів Скуерто може зустріти холодно: його вигнали з айронфорджського житла, коли після падіння Гномреґану столиця відчинила двері біженцям."},sec={{t="Розвідник без домівки",b="Скуерто колись жив в Айронфорджі, але мусив звільнити житло, коли міська влада розміщувала тисячі гномів-біженців, що рятувалися від радіоактивного падіння Гномреґану. Подавшись у мандри, Скуерто став розвідником у небезпечному Аратійському нагір'ї. Разом з Учнем Крайтеном він служить у Притулку під проводом Архімага Маліна: шукає тайні реагенти й могутні магічні артефакти, які колись належали давньому наставникові Маліна — Архімагові Трелейну."},{t="Гордість і небезпека",b="Попри суворі умови нагір'я, Скуерто неабияк пишається своїм умінням розвідника й погано сприймає будь-які сумніви у своїй вправності. Його робота раз у раз зіштовхує його з місцевими небезпеками — від ворожого Синдикату й огрів Каменекулаків до прадавніх сутностей, пов'язаних із цією землею. Завдяки далеким мандрам і широкому колу знайомств він підтримує зв'язки з найрізнішими людьми в краї, зокрема із Шейксом О'Бріном у Бухті Фалдіра та Ґерріґом Боунґріпом при кузнях Айронфорджа."}},faq={{q="Чому Скуерто служить в Аратійському нагір'ї, а не в Айронфорджі?",a="Колись Скуерто жив в Айронфорджі, але втратив житло, коли місто звільнило квартали для гномів-біженців, що тікали від лиха в Гномреґані. Лишившись без даху в гірській столиці, він найнявся в польову службу розвідником Альянсу.",al={"чому скуерто тут","минуле скуерто","біженець айронфорджа"}},{q="Яке завдання Скуерто в Притулку?",a="Архімаг Малін послав Скуерто й Учня Крайтена до Аратійського нагір'я зібрати тайні реагенти й повернути могутні магічні артефакти, що належали колишньому наставникові Маліна, Архімагу Трелейну.",al={"мета скуерто","що робить скуерто","скуерто малін"}},{q="Хто союзники Скуерто в цьому краї?",a="Окрім безпосередньої співпраці з Учнем Крайтеном і гарнізоном Альянсу в Притулку, Скуерто дружить із Шейксом О'Бріном, що ховається в Бухті Фалдіра, а також із Ґерріґом Боунґріпом в Айронфорджі.",al={"союзники скуерто","шейкс обрін друг"}},{q="Чи тримає Скуерто зло на гномів?",a="Він помітно гірко згадує, як утратив дім в Айронфорджі, щоб звільнити місце для гномів-вигнанців, але й далі сумлінно служить справі Альянсу в Аратійському нагір'ї.",al={"чи скуерто ненавидить гномів","скуерто гномреґан"}}},fp="7,248,34.481.0,15.524.0,56.256.0,43.194.0,39.199.0,42.178.0"}
P.entries["npc:smith-argus"] = {n="Коваль Арґус",s="Коваль Арґус — місцевий коваль і наставник у самому серці Ґолдширу в Лісі Елвінн. Біля своєї кузні просто неба поряд із Корчмою «Лев'яча Гордість» він лагодить спорядження подорожніх, навчає ковалів-новачків основ ремесла й домовляється з ремісниками по всьому південному Азероту. Його зв'язки поєднують місцеву торгівлю Ґолдширу з важливими осередками на кшталт Стормвінда й далекими рубежами, як-от Редрідж.",h="Коваль Арґус — місцевий коваль і наставник у самому серці Ґолдширу в Лісі Елвінн.",kw={"коваль арґус","ковальство","ґолдшир","ліс елвінн","лев'яча гордість","вернер осґуд"},ang={["profession:Blacksmithing"]="Для героїв Альянсу, що починають шлях в Елвінні, Арґус часто стає першим учителем ковальства: від нього ви отримуєте перші рецепти простого мідного спорядження й найпотрібніших речей.",["profession:Mining"]="Гірники приносять метал до кузні Ґолдширу, де Арґус навчає майбутніх ковалів перетворювати його на корисні речі.",["race:Human"]="Арґус уособлює працьовитих ремісників, на яких тримається Елвінн, попри байдужість влади й розгул розбійників."},sec={{t="Ковадло Ґолдширу",b="Неподалік від Корчми «Лев'яча Гордість» Коваль Арґус порається біля одного з найзавантаженіших ковадел Лісу Елвінн. Ґолдширу дедалі більше загрожують гноли, кобольди й розбійники Дефіас, а Арґус дбає, щоб місцеве ополчення й мандрівні шукачі пригод були як слід споряджені. Він не лише вирівнює пом'яті обладунки й кує міцне знаряддя, а й навчає ковальства, відкриваючи початківцям ази роботи з міддю та бронзою."},{t="Торгівля між містами",b="Арґус — не відлюдний сільський коваль: його майстерня — важлива ланка в мережі постачання королівства Стормвінд. Коли ремісникам у сусідніх поселеннях потрібне особливе спорядження чи сировина, вони звертаються до Ґолдширу, що лежить у самому центрі. Коваль-підковувач Вернер Осґуд у Редріджі розраховує на Арґуса, який постачає йому готові підкови, щоб в'ючні тварини й кіннота могли рухатися, а майстри-металурги з Дворфійського Кварталу Стормвінда регулярно домовляються через нього про поставки."}},faq={{q="Де знайти Коваля Арґуса?",a="Коваль Арґус — у Ґолдширі в центрі Лісу Елвінн. Ви знайдете його за роботою біля ковадла й горна просто неба за крамницею обладунків, неподалік від корчми «Лев'яча Гордість».",al={"місце арґуса","де коваль арґус","коваль арґус елвінн"}},{q="Які послуги надає Коваль Арґус?",a="Арґус навчає ковалів-новачків основ ремесла. У класичній версії гри його титул — «підмайстер-коваль».",al={"чого навчає арґус","тренер арґус","коваль ґолдшира тренер"}},{q="Чому коваль із Редріджу посилає мене до Коваля Арґуса?",a="Вернерові Осґуду, ремісникові з Лейкшира, потрібно чимало підків, щоб вози з припасами й верхові коні не зупинялися перед загрозою від орків Блекрок. Він замовляє Арґусові в Ґолдширі викувати й постачити потрібне залізне взуття.",al={"завдання ціна підков","підкови вернера","чому арґус підкови"}},{q="Що пов'язує Арґуса зі Стормвіндом?",a="Арґус узгоджує поставки з дворфами-ковалями в Стормвінді, як-от із Ґрімандом Елмором у Дворфійському Кварталі.",al={"завдання елмора","ґрифон стормвінда арґус"}},{q="Чи може Коваль Арґус навчити вищого чи майстерного ковальства?",a="Арґус навчає перших щаблів ковальства; вищих прийомів доведеться вчитися в досвідченіших майстрів у більших поселеннях.",al={"чи арґус навчає майстерного ковальства","яка вища майстерність у арґуса"}},{q="Чи належить Коваль Арґус до якоїсь гільдії?",a="Арґус — вірний підданий королівства Стормвінд і член місцевої громади ремісників, що служить Альянсу в Лісі Елвінн.",al={"фракція арґуса","гільдія арґуса"}}},fp="11,400,22.452.0,28.472.0,29.174.0,39.107.0,57.228.0,45.116.0,55.124.0,48.137.0"}
P.entries["npc:sneed"] = {n="Снід",s="Снід — гоблін, старший лісоруб Братства Дефіас, що працює глибоко в Мертвих Копальнях. З лісопильні, відомої як Щоглова Кімната, він керує важким потрощувачем власної конструкції й обробляє деревину для таємного броненосця Едвіна Венкліфа.",h="Снід — гоблін, старший лісоруб Братства Дефіас, що працює глибоко в Мертвих Копальнях.",kw={"снід","гоблін","лісоруб","потрощувач","щоглова кімната","мертві копальні"},ang={["faction:Alliance"]="Знищивши Сніда, ви перекриєте постачання деревини до Бухти Айронклад і завдасте відчутного удару по корабельних задумах Братства Дефіас.",["profession:Engineering"]="Потрощувач Сніда — класичний витвір гоблінських майстрів: надзвичайно продуктивний, добре озброєний і доведений далеко за межі будь-яких норм безпеки заради швидкості.",["race:Gnome"]="Гноми, що завітають до Щоглової Кімнати, побачать у машині Сніда типовий приклад гоблінської винахідливості: гучна, небезпечна й збудована без жодної думки про зручність водія чи довговічність."},sec={{t="Старший лісоруб Дефіас",b="Ядро Братства Дефіас — знедолені людські каменярі та прості робітники, але для будівництва броненосця потрібні фахівці особливих ремесел. Едвін Венкліф завербував Сніда саме заради його інженерних знань і безжальної гоблінської діловитості. У Щогловій Кімнаті, при підземній залізниці, Снід наглядає, як швидко валять, ріжуть і обтесують дерево для каркаса колосального броненосця Венкліфа."},{t="Промислова жорстокість",b="Головна турбота Сніда — урізати витрати й виконати план до строку, а наслідки хай летять під три чорти. Щоб пришвидшити роботу, він керує цехом із кабіни власного потрощувача, оснащеного величезними циркулярними пилками. Смертоносна машина за лічені секунди перетворює сирі стовбури на корабельний ліс. Якщо непрохані гості заженуть Сніда в кут, він покладається на броню своєї машини, щоб їх перемолоти, а коли механізм зламається — охоче вибереться з уламків і битиметься голіруч."}},faq={{q="Хто такий Снід?",a="Снід — гоблін-інженер і майстер-лісопильник на службі Едвіна Венкліфа. Він наглядає за обробкою деревини в Мертвих Копальнях, з якої будують броненосець Дефіас.",al={"хто такий снід","лор сніда","що таке снід"}},{q="Де знайти Сніда?",a="Снід — у Щогловій Кімнаті, лісопильному цеху при шахтних коліях у Мертвих Копальнях під Мунбруком.",al={"місце сніда","де снід","кімната сніда"}},{q="Чому гоблін працює на Братство Дефіас?",a="Едвінові Венкліфу потрібні були особливі промислові знання й швидкі результати, щоб збудувати свій таємний бойовий корабель. Він найняв гоблінів-найманців на кшталт Сніда, яким байдуже до політики чи моралі, аби добре платили.",al={"чому гоблін з дефіас","гоблін у мертвих копальнях","чому дефіас наймає гоблінів"}},{q="Чим Снід керує в бою?",a="Снід керує Потрощувачем Сніда — важкою двоногою механічною лісорубною машиною з пилками, яку він сам збудував, щоб із жахливою швидкістю валити й різати ліс.",al={"робот сніда","механізм сніда","потрощувач сніда"}},{q="Що стається, коли його потрощувач знищено?",a="Знищення потрощувача бою не завершує. Снід вистрибує з димних решток машини й далі б'ється з непроханими гостями вже пішки.",al={"друга фаза сніда","снід без потрощувача","чи снід гине разом із потрощувачем"}},{q="Для чого Снід заготовляє деревину?",a="Деревину, нарізану в цеху Сніда, сплавляють униз до Бухти Айронклад, де Братство збирає величезний бойовий корабель, щоб завдати удару у відповідь Стормвінду.",al={"навіщо снід рубає деревину","кімната щогли","деревина мертвих копалень"}}},fp="5,251,23.454.0,20.486.0,13.178.0,25.141.0,51.212.0,33.153.0,44.154.0,34.178.0"}
P.entries["npc:sneed-s-shredder"] = {n="Потрощувач Сніда",s="Потрощувач Сніда — грізна механічна лісозаготівельна машина глибоко в Мертвих Копальнях. Нею керує гоблін-наглядач Снід, і вона водночас служить важким промисловим механізмом для корабелів Едвіна Венкліфа та жахливим вартовим на підступах.",h="Потрощувач Сніда — грізна механічна лісозаготівельна машина глибоко в Мертвих Копальнях.",kw={"потрощувач сніда","снід","машина","лісопильня","мертві копальні"},ang={["faction:Alliance"]="Знищивши Сніда та його машину, ви зірвете роботу лісопильні, що забезпечує таємний воєнний флот Едвіна Венкліфа.",["profession:Engineering"]="Потрощувач — класичне диво гоблінської механіки, хоча й він піддається перехопленню керування Гномським Універсальним Пультом.",["race:Gnome"]="Шоні Тихий із підземного штурмового загону Гномреґану хоче забрати джерело живлення цього гоблінського чудовиська, щоб запустити бури, які могли б знову відкрити шлях до Гномреґану."},sec={{t="Промисловий жах",b="У ливарні Мертвих Копалень, де заправляють гобліни, механічні потрощувачі мають подвійне призначення: вони обробляють величезну кількість деревини для потаємного броненосця Едвіна Венкліфа й водночас слугують броньованими таранами проти непроханих гостей. Снід, наглядач лісопильні, сам керує цим переробленим механічним чудовиськом, перетворивши велетенську циркулярну пилку на знаряддя оборони."},{t="Смертоносна кабіна",b="Знищити машину ще не означає усунути загрозу. Снід сидить у відкритій кабіні над крутними лезами, покладаючись на важку залізну обшивку й моторошний гуркіт, щоб розігнати ворогів. Навіть коли механізм ламається й потрощувач валиться в зливі іскор, Снід вистрибує з димних уламків і б'ється до гіркого кінця."}},faq={{q="Для чого використовують Потрощувач Сніда в Мертвих Копальнях?",a="Братство Дефіас дуже покладається на гоблінські машини, щоб прорізати підземний камінь і обробляти величезну кількість деревини для свого таємного броненосця. Снід цим потрощувачем пиляє ліс і брутально тримає лад на підземних роботах.",al={"навіщо потрощувач у мертвих копальнях","потрощувач у мертвих копальнях"}},{q="Що стається, коли потрощувач знищено?",a="Коли потрощувач зазнає критичної поломки, сам Снід виживає серед уламків. Гоблін-пілот вилазить просто з розбитої машини, вимахуючи власною зброєю, і з лютою завзятістю нападає на непроханих гостей.",al={"чи снід гине з потрощувачем","друга фаза потрощувача"}},{q="Звідки в Братства Дефіас гоблінська техніка?",a="Едвін Венкліф найняв гоблінів-інженерів, ремісників і найманих робітників, щоб керувати складним механічним господарством під Вестфолом — паровими кузнями, гарматними ливарнями й лісопилками.",al={"гобліни дефіас","чому гобліни в мертвих копальнях"}},{q="Чи можуть інженери зламати потрощувач чи взяти його під контроль?",a="Кмітливі винахідники з Гномським Універсальним Пультом можуть ненадовго перехопити керування потрощувачем і на певний час відібрати машину в Сніда.",al={"контроль потрощувача сніда","гномський універсальний пульт снід"}},{q="Чи є в Потрощувачі Сніда щось цінне?",a="Так. Його неушкоджене джерело живлення — Ґноам Спрекльспрокет — шукає Шоні Тихий у Стормвінді: воно їй потрібне, щоб живити гномські гіробуроматичні екскаваціонатори для штурму Гномреґана.",al={"предмет завдання потрощувача","що падає з потрощувача сніда"}},{q="Хто керує потрощувачем?",a="Машиною командує Снід — досвідчений гоблін-наглядач, що керує лісозаготівлею й теслярськими роботами глибоко в Мертвих Копальнях.",al={"хто керує потрощувачем","пілот сніда"}}},fp="16,266,17.397.0,16.336.0,51.272.0,44.224.0,53.197.0,54.166.0,46.197.0,24.139.0"}
P.entries["npc:solm-hargrin"] = {n="Солм Гарґрін",s="Солм Гарґрін — наставник розбійників, що служить в Анвілмарі в Долині Холодного Хребта. Прагматичний дворф, який цінує честь серед злодіїв, він навчає дворфійських і гномських пройдисвітів-новачків мистецтва підступу. Він твердо вірить, що таємні оперативники стануть життєво важливими, коли геополітична напруга по всьому Азероту розпалиться.",h="Солм Гарґрін — наставник розбійників, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"солм гарґрін","розбійник","наставник","анвілмар","долина холодного хребта","підступ","честь серед злодіїв"},ang={["class:Rogue"]="Для дворфів і гномів, що роблять перші кроки в тіні, Солм Гарґрін дає базовий вишкіл і розшифровує ваші найперші накази гільдії.",["race:Dwarf"]="Солм утілює менш звичний дворфійський шлях, доводячи, що скраданню, хитрості й тихій сталі в Дун Мороґу є не менше місця, ніж важкій броні й сокирам."},sec={{t="Наставник у тінях",b="У дворфійській твердині Анвілмар Солм Гарґрін стежить за засніженими перевалами Долини Холодного Хребта гострим, розважливим оком. Поки Айронфордж здебільшого покладається на грубу силу своїх горян і воїнів, Гарґрін розуміє, що деякі загрози вимагають тихішого, гострішого дотику. Він вітає розбійників-початківців і дворфійського, і гномського роду, розшифровує для них закодовані послання й муштрує їх у ключових прийомах на кшталт Потрошіння. Понад усе Гарґрін обстоює кредо професійної вірності й честі серед злодіїв, готуючи учнів до дедалі хиткішого світу, де долю народів часто вирішують непомітні ножі."}},faq={{q="Хто такий Солм Гарґрін?",a="Солм Гарґрін — дворф, наставник розбійників в Анвілмарі, стартовій заставі в Долині Холодного Хребта в Дун Мороґу. Він посвячує молодих дворфів і гномів у таємні мистецтва злодійства, скритності й володіння клинком.",al={"хто такий солм","лор солма гарґріна","тренер розбійників ковадлограда"}},{q="Як Солм Гарґрін дивиться на розбійницьке ремесло?",a="Гарґрін твердо вірить у «злодійську честь». Він навчає новобранців, що хоч би якими підступними були їхні методи, вірність ремеслу й одне одному — понад усе, особливо тепер, коли хиткий мир між суперниками от-от розвалиться.",al={"погляди солма","честь серед злодіїв","ставлення солма"}},{q="Які завдання Солм Гарґрін дає чи приймає?",a="Дворфів-розбійників-новачків посилають до нього із Зашифрованою Руною, а нові гноми-розбійники приносять Зашифровану Записку. Розгадавши ці вступні накази, він доручає учням опанувати наступальні прийоми на практиці.",al={"завдання солма","зашифрована руна солм","зашифрований меморандум солм"}},{q="Чи навчає Солм Гарґрін інші народи, крім дворфів?",a="Так. Після падіння Гномреґана гноми-біженці ділять із дворфами стартові землі Долини Холодного Хребта. Солм охоче бере під своє крило гномів-агентів разом зі своїми родичами-дворфами.",al={"чи гноми навчаються в солма","тренер розбійників-гномів ковадлоград"}}},fp="12,316,23.652.0,20.211.0,48.247.0,49.235.0,49.194.0"}
P.entries["npc:sprite-darter"] = {n="Фея-стрілохвіст",s="Феї-стрілохвости — маленькі райдужні дракончики-феї, що живуть у пишних кронах Фераласу. Їх шанують за вроджені духовні й магічні властивості, і вони граційно пурхають серед давніх дерев. Останнім часом ці рідкісні створіння стали здобиччю місцевих тауренів Ґрімтотем, які прагнуть їх ловити й використовувати.",h="Феї-стрілохвости — маленькі райдужні дракончики-феї, що живуть у пишних кронах Фераласу.",kw={"фея-стрілохвіст","дракончики-феї","фералас","ґрімтотем","кіндал мунвівер","узер'і","муїсек"},ang={["class:Druid"]="Друїди високо шанують дракончиків-фей як родичів духів природи, тож вважають, що ловля їх грубими браконьєрами тяжко порушує лісову рівновагу.",["faction:Alliance"]="Союзники Кіндал Мунвівер приходять на поміч полоненим малятам у Фераласі й зупиняють загребущі руки ворожого племені Ґрімтотем.",["faction:Horde"]="Тролі-духовидці, як-от Чаклун-знахар Узер'і з Табору Моджаче, бачать у феях-стрілохвостах чудовий матеріал, щоб добувати духовний муїсек і опановувати давню сутність Фераласу.",["race:NightElf"]="Нічні ельфи шанують священних дракончиків-фей як природних охоронців лісу, тож визволити полонених фей-стрілохвостів із рук Ґрімтотем для них — справа дбайливого ставлення до природи."},sec={{t="Дракончики-феї дикої природи",b="Феї-стрілохвости — невловимі крилаті лісові створіння, що живуть у давніх лісах Фераласу. Сяйливі райдужні крила й таємнича духовна сутність роблять їх утіленням химерної, але грізної магічної природи глибоких лісів Калімдору. Хоч загалом вони миролюбні й полохливі, їхня вроджена стійкість до магії та природна сила роблять їх важливими для тих, хто відчуває глушину."},{t="Полон у Ґрімтотем",b="Останнім часом відлюдним феям-стрілохвостам загрожує небачена небезпека. Войовничий тауренський клан Ґрімтотем, що живе у Фераласі, почав відловлювати цих рідкісних створінь і десятками зачиняти їх у клітках з невідомою метою. Стривожені нічні ельфи, як-от Кіндал Мунвівер, шукають союзників, щоб розбити клітки й звільнити полонених малят, перш ніж Ґрімтотем підкорять їх своїй волі."},{t="Духовний інтерес",b="Окрім нічних ельфів, що прагнуть їх уберегти, феями-стрілохвостами зацікавилися й сторонні дослідники первісної сили. Чаклун-знахар Узер'і, троль-духовидець із Табору Моджаче, пильно вивчає природну енергію та муїсек у феях-стрілохвостах і прагне здобути їхню сутність, щоб розгадати унікальну магію, що буяє у Фераласі."}},faq={{q="Хто такі Феї-стрілохвости?",a="Феї-стрілохвости — крихітні фейські дракончики, що живуть у нетрях Фераласу. Вони відомі мерехтливими крилами, зв'язком із природою й невловною магічною поведінкою.",al={"хто такі феї-стрілохвости","що таке фея-стрілохвіст","чи феї-стрілохвости дракони"}},{q="Чому таурени Ґрімтотем їх ловлять?",a="Точні причини невідомі, але клан Ґрімтотем масово ловить сітками й замикає в клітки фей-стрілохвостів по всіх лісах — певно, щоб скористатися їхніми рідкісними духовними й магічними властивостями.",al={"чому ґрімтотеми ловлять їх","ґрімтотеми феї-стрілохвости","чому феї в клітках"}},{q="Хто намагається захистити Фей-стрілохвостів?",a="Кіндал Мунвівер, ельфійка з Фераласу, завзято їх захищає: посилає співчутливих шукачів пригод трощити клітки Ґрімтотемів і визволяти полонених стрілохвостів.",al={"хто захищає фей-стрілохвостів","кіндал мунвівер феї-стрілохвости","завдання альянсу про фей-стрілохвостів"}},{q="Чому Чаклуна-знахаря Узер'і цікавлять Феї-стрілохвости?",a="Чаклун-знахар Узер'і вивчає первісні духовні сили Фераласу. Він прагне здобути сутність, або муісек, Фей-стрілохвостів, щоб більше дізнатися про природну магію тварин цього краю.",al={"знахар узер'і феї","завдання узер'і про фей"}},{q="Чи можна виростити Фею-стрілохвоста?",a="Тим, хто допоможе Кіндал Мунвівер визволити полонених пташенят і захистити їхні гнізда, згодом можуть довірити рідкісне Яйце Феї-стрілохвоста, щоб виростити й оберігати малечу.",al={"яйце феї-стрілохвоста","улюбленець фея-стрілохвіст","чи можна отримати фею-стрілохвоста"}},{q="Чи ворожі Феї-стрілохвости?",a="Дикі феї-стрілохвости зазвичай полохливі й мирні до мандрівників, але, як і всі дикі створіння, у разі загрози чи зачіпки захищатимуться спалахами магії природи.",al={"чи небезпечні феї-стрілохвости","чи нападають феї-стрілохвости"}}},fp="13,309,26.410.0,19.404.0,18.365.0,24.182.0,44.209.0,44.169.0,56.188.0,30.170.1,27.185.0"}
P.entries["npc:sprite-jumpsprocket"] = {n="Спрайт Джампспрокет",s="Спрайт Джампспрокет — гномка, учениця інженера, що нині живе в гамірному Дворфійському Кварталі Стормвінда. Як і багато гномів, що шукали прихистку після падіння Гномреґану, вона займається технічним ремеслом і винахідництвом разом зі своїми колегами-майстрами. Її присутність свідчить про квітучу громаду дворфійських і гномських майстрів, що забезпечують столицю шестернями, пристроями й механічними знаннями.",h="Спрайт Джампспрокет — гномка, учениця інженера, що нині живе в гамірному Дворфійському Кварталі Стормвінда.",kw={"спрайт джампспрокет","гноми","інженерія","дворфійський квартал","гномреґан","стормвінд"},ang={["faction:Alliance"]="Її робота в Дворфійському Кварталі показує повсякденну співпрацю людей, дворфів і гномів, на якій тримається господарство столиці.",["profession:Engineering"]="Для майстрів-початківців Спрайт Джампспрокет — така сама учениця, що вивчає зубчасті колеса, мідні трубки й нестійкі суміші в найпромисловішому анклаві Стормвінда.",["race:Gnome"]="Спрайт — нагадування про незламність вигнанців Гномреґану, які й далеко від утраченої батьківщини не зраджують любові до ремесла й механічної майстерності."},sec={{t="Майстриня в Стормвінді",b="На закіптюжених вулицях і в гомінких майстернях Дворфійського Кварталу гноми й дворфи працюють пліч-о-пліч, кують метал і конструюють хитромудрі пристрої. Спрайт Джампспрокет — учениця інженера в цьому жвавому осередку. Освоївшись у столиці королівства, учні-майстри на кшталт Спрайт відточують ремесло під наглядом досвідчених наставників, вкладаючи свій винахідливий розум у повсякденні механізми й технічні дива Альянсу."},{t="Гномська винахідливість у вигнанні",b="Після нищівної втрати Гномреґану вигнані гноми розпорошилися землями Альянсу, принісши з собою неповторний хист до майстрування, хімії й механіки. У Стормвінді гноми знайшли гостинний прихисток у Дворфійському Кварталі, де вдосталь доменних печей і верстатів. Спрайт Джампспрокет уособлює цей стійкий, спрямований у майбутнє дух — вона сповнена рішучості опанувати складну інженерну науку попри всі негаразди, що спіткали її народ."}},faq={{q="Хто така Спрайт Джампспрокет?",a="Спрайт Джампспрокет — гномка, учениця інженера, що живе й працює в Дворфійському Кварталі Стормвінда.",al={"спрайт джампспрокет","хто така спрайт","лор спрайт джампспрокет"}},{q="Де знайти Спрайт Джампспрокет?",a="Вона в Дворфійському Кварталі Стормвінда, серед майстерень, ковадел і інших завзятих інженерів.",al={"місце спрайт джампспрокет","де спрайт","знайти спрайт джампспрокет"}},{q="Яку роль вона відіграє в Стормвінді?",a="Спрайт — учениця інженера. Вона уособлює постійну присутність гномів-майстрів, що вдосконалюють своє винахідницьке ремесло в столиці Альянсу.",al={"роль спрайт джампспрокет","що вона робить","мета спрайт джампспрокет"}},{q="Чому гноми на кшталт Спрайт живуть у Стормвінді?",a="Після катастрофічного падіння Гномреґана багато гномів знайшли притулок у своїх родичів-дворфів в Айронфорджі й по всіх людських землях, особливо в Стормвінді, де їхня промислова винахідливість дуже потрібна.",al={"чому гноми в стормвінді","гноми в дворфійському кварталі","гномі біженці"}},{q="Чи пов'язана Спрайт Джампспрокет з якимись відомими завданнями?",a="Спрайт відіграє невелику роль у житті Дворфійського Кварталу: здебільшого вона просто частина інженерної громади району.",al={"завдання спрайт джампспрокет","завдання для спрайт"}},{q="Чи пов'язана вона з Вестфолом?",a="Хоча інколи її згадують поряд із записами про сусідні південні королівства, Спрайт працює саме в Дворфійському Кварталі Стормвінда, хоча інженерні витвори по всьому краю часто мають гномську конструкцію.",al={"спрайт джампспрокет вестфол","інженер вестфола"}}},fp="19,421,21.472.0,26.482.0,27.123.0,37.128.0,38.145.0,47.218.0,50.141.0,32.219.0"}
P.entries["npc:sputtervalve"] = {n="Спаттервалв",s="Спаттервалв — знервований гоблін-інженер, що працює в портовому містечку Раджет. Служачи Спілці Винахідників під керівництвом директора Ріддлвокса, він відповідає за розробку подрібнювачів у краї і працює під тиском нещадних корпоративних строків. Щоб зберегти посаду, він часто наймає шукачів пригод для промислового шпигунства проти суперниці — Венчурної Компанії.",h="Спаттервалв — знервований гоблін-інженер, що працює в портовому містечку Раджет.",kw={"спаттервалв","гоблін","інженер","подрібнювачі","венчурна компанія","самофланж"},ang={["faction:Horde"]="Хоч Раджет і нейтральний, Спаттервалв дуже покладається на мандрівників Орди, що перетинають Пустки, — щоб зривати роботи Венчурної Компанії й таємно вивозити деталі машин.",["profession:Engineering"]="Спаттервалв утілює безжальний підхід гоблінської інженерії: коли винахідництво буксує — вкради креслення в найближчого конкурента."},sec={{t="Промисловий тиск",b="Спаттервалв, що працює в Раджеті, звітує директорові Ріддлвоксу зі Спілки Винахідників. Отримавши доручення розробляти подрібнювачі, він швидко з'ясував, що встигати за сучасною механізацією — жорстока праця. Під тиском запеклої конкуренції та невблаганного строку Спаттервалв опинився майже без власних робочих зразків. Замість визнати поразку перед Спілкою, він вдався до класичного гоблінського рішення: вкрасти кращі креслення в тих, хто збудував їх першим."},{t="Око на Венчурну Компанію",b="Головна ціль Спаттервалва — бурові роботи Венчурної Компанії в Багнистому Болоті на північному заході. Їхні новітні подрібнювачі можуть похвалитися змінними маніпуляторами, вдосконаленими важелями керування й складними внутрішніми механізмами на кшталт невловимого самофланжа. Прагнучи будь-що розкрити їхні секрети, Спаттервалв послав свого помічника Візлкренка на болото «на польові дослідження», та той потрапив у пастку, тож Спаттервалвові довелося наймати мандрівних найманців, щоб повернути викрадену техніку й урятувати напарника."},{t="Посередник у Раджеті",b="Окрім клопотів із подрібнювачами, Спаттервалв стає першою ланкою для всіляких дивовиж, що потрапляють до Пусток. Коли шукачі пригод виносять із Печер Стогонів химерні артефакти, просякнуті скверною, — як-от сяйливий уламок, — Спаттервалв достатньо знає місцевість, щоб порадити їм іти не до механіків, а до відлюдних друїдів, що отаборилися над печерами."}},faq={{q="Хто такий Спаттервалв?",a="Спаттервалв — гоблін-інженер зі Спілки Винахідників у Раджеті. Директор Ріддлвокс доручив йому розробку потрощувачів, і тепер він гарячково намагається видати результат, поки не минули суворі терміни компанії.",al={"хто такий спаттервалв","спаттервалв раджет","лор спаттервалва"}},{q="Чому Спаттервалв полює на Венчурну Компанію?",a="Венчурна Компанія розробила в Багнистому Болоті новітні потрощувачі зі змінними маніпуляторами й кращими ручками керування. Не здатний чесно перевершити їхні конструкції, Спаттервалв вдався до промислового шпигунства, щоб «позичити» їхні креслення й машини.",al={"чому полює на венчурну компанію","спаттервалв багнисте болото","спаттервалв венчурна компанія"}},{q="Що таке самофланж?",a="Самофланж — складна механічна деталь у потрощувачах і пультах керування Венчурної Компанії. Спаттервалв наймає шукачів пригод, щоб добути й дослідити її, сподіваючись опанувати їхню технологію.",al={"що таке самофланж","завдання самофланжа","що робить самофланж"}},{q="Хто такий Віззлкренк?",a="Віззлкренк — агент і соратник Спаттервалва, якого той послав у Багнисте Болото викрасти дослідні зразки потрощувачів. Його місія пішла шкереберть: він застряг усередині однієї з машин, і тепер його треба вивести звідти.",al={"хто такий віззлкренк","віззлкренк","напарник спаттервалва"}},{q="Чому Спаттервалва цікавить Сяйлива Скалка?",a="Сам він природні дивовижі не досліджує, але добре знає Пустки, тож до нього варто звернутися. Коли йому показують скалку, знайдену в Печерах Стогонів, він радить шукачам пригод піти до друїдів на пагорбах над печерами.",al={"сяйлива скалка спаттервалв","сяйлива скалка печери стогонів","завдання скалки раджет"}},{q="Хто такий Директор Ріддлвокс?",a="Директор Ріддлвокс — високопоставлений очільник Спілки Винахідників, що поставив Спаттервалва відповідати за нові потрощувачі й тримає його в суворих, безжальних термінах виробництва.",al={"рідлвокс","директор рідлвокс","бос спілки винахідників"}}},fp="12,348,19.475.0,27.515.0,18.389.0,20.244.0,50.265.0,22.208.0,19.214.1,51.246.0,26.185.0"}
P.entries["npc:sten-stoutarm"] = {n="Стен Стаутарм",s="Стен Стаутарм — практичний дворфський постачальник і кур'єр, що стоїть біля Анвілмара в Долині Холодного Хребта. Він відповідає за спорядження новобранців і місцеву пошту, дбаючи, щоб молоді горяни лишалися в теплі, ситими й поінформованими попри суворі гірські умови.",h="Стен Стаутарм — практичний дворфський постачальник і кур'єр, що стоїть біля Анвілмара в Долині Холодного...",kw={"стен стаутарм","постачальник","пошта","анвілмар","долина холодного хребта","спорядження"},ang={["faction:Alliance"]="Зв'язок через Перевал Холодного Кряжа вкрай важливий для тренувальних угідь Айронфорджа, і поштова мережа Стена тримає долину сполученою з усім Альянсом.",["race:Dwarf"]="Стен утілює просту й щиру гостинність Дун Мороґу: він дбає, щоб його родичі були вбрані в товсту шкіру й нагодовані, перш ніж вирушать у сніги.",["race:Gnome"]="Оскільки гномські біженці навчаються в Анвілмарі разом із дворфами, Стен ставиться до них із тими самими практичними вимогами: доручає доставити пошту й споряджає проти негоди."},sec={{t="Рука допомоги серед снігів",b="Стен Стаутарм стоїть майже в самому серці Долини Холодного Хребта — одне з перших привітних облич, яке дворфські та гномські новобранці бачать, вийшовши з корчми Анвілмара. Поки долина відрізана зимовими хуртовинами й оточена небезпеками, Стен бере на себе клопіт спорядити зелених учнів міцним одягом, перш ніж вони замерзнуть або непідготовленими заблукають у заметах."},{t="Тримати зв'язок",b="Окрім того, що шиє зимове вбрання з місцевих вовчих шкур, Стен виконує обов'язки неофіційного поштмейстера Долини Холодного Хребта. Він приймає листи, передані через небезпечний Перевал Холодного Кряжа, і розносить службові руни, записки та накази наставникам класів по всій улоговині, щоб воїни, жерці й маги-новачки отримували свої настанови попри ворожих трогів, які перекрили тунелі."}},faq={{q="Хто такий Стен Стаутарм?",a="Стен Стаутарм — дворф, постачальник одягу й посланець, що стоїть біля Анвілмара в Долині Холодного Хребта. Він допомагає новобранцям, забезпечуючи їх теплим одягом і розподіляючи місцеву пошту.",al={"стен стаутарм","хто такий стен","листоноша ковадлограда"}},{q="Яку роль він відіграє в Долині Холодного Хребта?",a="Стен для Анвілмара — і інтендант, і поштар. Він збирає місцеву сировину на кшталт вовчого м'яса й шкур, щоб шити захисне спорядження для учнів, а заодно розносить листи й навчальні записки по всій долині.",al={"робота стена","що робить стен","роль стена"}},{q="Навіщо Стенові доставляти пошту?",a="Через трогів і зимову негоду на Перевалі Холодного Кряжа пошта й припаси насилу доходять до долини. Коли послання таки прибувають, Стен покладається на надійних новачків, щоб ті рознесли пакунки й листи мешканцям, як-от Таліну Кінаю.",al={"навіщо доставляти пошту","пошта колдрідж","доставка пошти долини колдрідж"}},{q="Що Стен думає про трогів у долині?",a="Стен утомлено й без захвату ставиться до шкідників, що заполонили довколишні пагорби, і полюбляє казати: бачив одного трога — бачив їх усіх.",al={"стен про трогів","цитата про трогів","погляд стена на трогів"}},{q="Навіщо він просить вовче м'ясо?",a="Стен міняє мандрівним шукачам пригод міцні теплі рукавиці на жорстке вовче м'ясо: так він і годує захисників долини, і вдягає їх проти лютого холоду Дун Мороґу.",al={"дворфійські постачальники завдання","завдання вовчого м'яса","стен вовче м'ясо"}},{q="Що за руни й записки Стен дає новачкам?",a="Це запечатані листи й навчальні знаки від начальства з Айронфорджа й Дун Мороґу, які велять молодим учням з'явитися до наставників своїх класів в Анвілмарі.",al={"освячена руна","проста записка","записки стена"}}},fp="13,292,26.364.0,22.403.0,21.189.0,43.240.0,34.244.0,52.160.0,30.185.0,63.192.0"}
P.entries["npc:stitches"] = {n="Стітчес",s="Стітчес — велетенська зшита з частин потвора-нежить, що тероризує Сутінколісся. З'являючись на заході краю, чудовисько невпинно сунеться головним шляхом до Даркшира, вбиваючи необачних подорожніх і змітаючи застави Нічної Варти.",h="Стітчес — велетенська зшита з частин потвора-нежить, що тероризує Сутінколісся.",kw={"стітчес","аберкромбі","бальзамувальник","даркшир","нічна варта","сутінколісся"},ang={["class:Paladin"]="Потворне дітище некромантії й нечестивого ремесла плоті, Стітчес уособлює все, що Святе Світло покликане очистити.",["faction:Alliance"]="Стітчес — катастрофічна загроза для знесилених мешканців Даркшира: через нього головний тракт Сутінколісся стає смертельним випробуванням для новобранців Альянсу."},sec={{t="Жах головного шляху",b="Стітчес — потвора-нежить, зібрана з викопаних трупів і нечестивого чаклунства. З'явившись біля хижі Аберкромбі на північний схід від Цвинтаря Воронячого Пагорба, неповоротке чудовисько одразу рушає дорогою на схід, до Даркшира. Наділений неймовірною силою й невгамовною злобою, Стітчес проривається крізь усі застави Нічної Варти на тракті — зокрема крізь оборонний табір навпроти Огрського Кургану Вул'Ґол і заставу біля Гнилого Саду, — сіючи відверту різанину серед необачних подорожніх і міських захисників."},{t="Спотворена помста Бальзамувальника",b="Стітчес з'явився в Сутінколіссі не випадково: його навмисне створили як знаряддя відплати. Аберкромбі, якого перехожі знали лише як нешкідливого відлюдника, затаїв глибоку образу на Лорда Елло Ебонлока, мера Даркшира. Під невинними приводами він посилав нічого не підозрюваних шукачів пригод по окультні реагенти, інструменти й матеріали — і так завершив своє жахливе творіння. Стітчеса він надіслав до Даркшира як глумливий «подарунок», щоб зламати оборону міста й покарати Лорда Ебонлока."}},faq={{q="Хто створив Стітчеса?",a="Stitches is a product of necromancy assembled in Duskwood. Discovering who made him is part of the mystery surrounding the undead near Raven Hill.",al={"хто створив стітчеса","творець стітчеса","аберкромбі стітчес"}},{q="Чому Стітчес марширує на Даркшир?",a="Stitches advances along Duskwood's main road toward the town, attacking the Night Watch and anyone else in his path. The reason behind his attack emerges during the local investigation.",al={"чому стітчес іде на даркшир","мета нападу стітчеса","куди йде стітчес"}},{q="Чи може Нічна Варта сама зупинити Стітчеса?",a="Ні. Якщо його не спинити, Стітчес легко змітає й винищує застави Нічної Варти біля Огрського Кургану Вул'Ґол і Гнилого Саду, перш ніж дійти до воріт Даркшира. Здолати його можна лише спільними зусиллями ополчення й мандрівних шукачів пригод.",al={"чи нічна варта зупинить стітчеса","нічна варта проти стітчеса","чи вартові даркшира вб'ють стітчеса"}},{q="Де з'являється Стітчес?",a="Стітчес з'являється за хижею Аберкромбі при дорозі на північний схід від Цвинтаря Воронячого Пагорба, а потім вирушає у свій довгий смертоносний похід на схід через Сутінколісся.",al={"де з'являється стітчес","місце стітчеса","початкова точка стітчеса"}}},fp="8,273,27.569.0,30.523.1,21.146.2,42.185.2,47.258.0,26.167.1"}
P.entries["npc:strahad-farsan"] = {n="Страгад Фарсан",s="Страгад Фарсан — майстер-чорнокнижник із людей, що живе у відлюдній кам'яній вежі над Раджетом у Пустках. Знаний по обидва боки фронту, він діє поза звичною політикою Альянсу й Орди, навчаючи честолюбних заклиначів небезпечного мистецтва зв'язування вищих демонів. Адепти магії скверни і зі Стормвінда, і з Оргріммара, і з Андерсіті шукають його суворого наставництва.",h="Страгад Фарсан — майстер-чорнокнижник із людей, що живе у відлюдній кам'яній вежі над Раджетом у Пустках.",kw={"страгад фарсан","чорнокнижник","раджет","мисливець скверни","скакун скверни","ґакін"},ang={["class:Warlock"]="Страгад — ключовий наставник для заклиначів середнього рівня: він проводить вас крізь моторошні ритуали, потрібні, щоб підкорити мисливців Скверни й викликати скакунів із Нижнього Світу.",["faction:Alliance"]="Ґакін Зв'язувач Темряви з крипт «Зарізаного Ягняти» посилає чорнокнижників Альянсу на Калімдор саме для того, щоб вони навчалися у Страгада.",["faction:Horde"]="Хоч Страгад — людина, народжена в Альянсі, він охоче має справу з адептами Орди під нейтральним захистом Раджета.",["race:Human"]="Страгад показує, що люди — майстри темних мистецтв — у пошуках більшої сили діють далеко за межами королівства Стормвінд."},sec={{t="Вежа над Раджетом",b="Вежа Страгада Фарсана, що стоїть на кручах над гоблінським портом Раджет, височіє осторонь гамірних торгових доків унизу. Нейтральність Раджета дає Страгадові свободу проводити небезпечні демонічні виклики далеко від цікавих очей магістратів Альянсу чи шаманів Орди. В оточенні своїх послідовників він вивчає глибші таємниці Викривленого Нижнього Світу у відносній самоті, не зважаючи на дріб'язкові чвари за землю."},{t="Майстер зв'язування демонів",b="Свою грізну славу Страгад здобув безпосереднім і смертельно небезпечним досвідом. Коли він уперше підкоряв собі мисливця Скверни, то ледве врятувався, — і це випробування зробило його вкрай обережним і безкомпромісним у вимогах. Попри людське походження, він здобув повагу темних постатей по всьому Азероту, зокрема Ґакіна Зв'язувача Темряви в Стормвінді та знавців демонології в Андерсіті й Оргріммарі. Чорнокнижників під будь-якими прапорами, що хочуть командувати такими непередбачуваними створіннями, як мисливці Скверни чи вогняні скакуни, неодмінно посилають до його порога."}},faq={{q="Хто такий Страгад Фарсан?",a="Страгад Фарсан — вправний людина-чорнокнижник і майстер-наставник, що живе в кам'яній вежі над Раджетом. Він належить до близького кола відомого стормвіндського чорнокнижника Ґакіна Зв'язувача Темряви, але його величезна майстерність у виклику демонів робить його авторитетом, до якого звертаються чорнокнижники і з Альянсу, і з Орди.",al={"лор страгада","хто такий страгад","про страгада фарсана"}},{q="Чому людина-чорнокнижник живе в Пустках?",a="Раджет — нейтральний порт під орудою картелю Стімвідл, ідеальний прихисток для темних заклиначів. Живучи на кручах, Страгад може проводити небезпечні ритуали виклику далеко від суворих законів Альянсу й пильного ока Орди.",al={"чому чорнокнижник-людина в пустках","людина в пустках","місце страгада"}},{q="Чому чорнокнижники Орди приходять до Страгада?",a="Влада Страгада над демонічними сутностями стоїть понад вірністю фракціям. Наставники з Оргріммара й Андерсіті визнають його майстерність у підкоренні складних демонів, як-от мисливців Скверни, і посилають своїх найздібніших учнів за море вчитися просто в нього.",al={"чому чорнокнижники орди йдуть до страгада","орда відвідує страгада","чи орда може говорити зі страгадом"}},{q="Що сталося зі Страгадом, коли він уперше викликав мисливця Скверни?",a="Коли Страгад уперше спробував підкорити мисливця Скверни, ритуал мало не коштував йому життя. Він ледве пережив цю сутичку, і вона навчила його жорстокої точності, без якої не приборкати таких хижаків, що пожирають магію.",al={"страгад мисливець скверни","історія страгада з мисливцем скверни"}},{q="Чи Страгад родич Ґодріка Фарсана?",a="У них рідкісне спільне прізвище Фарсан, що переконливо свідчить про родинний зв'язок, хоча Страгад цілком поринув у своє темне ремесло й нічого не розповідає про рідню.",al={"ґодрік фарсан зв'язок","ґодрік фарсан родич","чи страгад родич ґодріка"}},{q="Хто ці послушники довкола його вежі?",a="Страгад наглядає за кількома відданими послушниками, серед яких Маґаз, Фенрік і Вайтула. Вони допомагають йому підтримувати захисні чари, готувати складні кола виклику й проводити вимогливі ритуали у вежі.",al={"послушники біля вежі","послушники у вежі раджета"}}},fp="14,386,23.432.0,25.558.0,22.316.0,45.274.0,36.264.0,62.229.0,37.187.0,38.235.0"}
P.entries["npc:supervisor-raelen"] = {n="Наглядачка Рейлен",s="Наглядачка Рейлен керує заготівлею деревини в Лісозаготівельному Таборі Східної Долини на східному краю Лісу Елвінн. Вона відповідає за тутешніх робітників, дотримання щоденних норм вирубки й за те, щоб заготовлена деревина безпечно потрапляла в ланцюги постачання Стормвінда.",h="Наглядачка Рейлен керує заготівлею деревини в Лісозаготівельному Таборі Східної Долини на східному краю Лісу...",kw={"наглядачка рейлен","лісозаготівля","східна долина","деревина","лісоруби","маршал паттерсон"},ang={["faction:Alliance"]="Підтримання запасів деревини королівства необхідне, щоб живити оборону й будівництво Стормвінда, тож норми Рейлен життєво важливі для військової справи."},sec={{t="Табір за графіком",b="У серці табору, біля Маршала Паттерсона й возів із деревиною, Наглядачка Рейлен керує робітниками, яким доручено заготовляти ліс для королівства. Лісозаготівельний Табір Східної Долини стоїть на кордоні з Горами Редріджу, і керувати ним — чималий клопіт: від узгодження роботи втомлених лісорубів до боротьби зі звіриною й бандитами, що загрожують нормам видобутку. Попри небезпеки довколишніх лісів, Рейлен зосереджена на одному — щоб деревину зібрали, обробили й зв'язали для перевезення."}},faq={{q="Хто така Наглядачка Рейлен?",a="Наглядачка Рейлен — наглядачка в Лісозаготівельному Таборі Східної Долини на сході Лісу Елвінн. Вона керує бригадами лісорубів і стежить, щоб норми заготівлі деревини неухильно виконувалися.",al={"хто така рейлен","рейлен елвінн","наглядачка іствейла"}},{q="Де знайти Наглядачку Рейлен?",a="Вона в центрі Лісозаготівельного Табору Східної Долини на сході Лісу Елвінн, біля навантажених деревиною возів, поруч із Маршалом Паттерсоном.",al={"де рейлен","місце наглядачки рейлен","знайти рейлен"}},{q="Навіщо Наглядачці Рейлен допомога шукачів пригод?",a="Заготовляти деревину на узліссі стало небезпечно, і нарізані в'язанки колод часто лишаються покинутими чи розкиданими між деревами, коли робітники натрапляють на місцевих звірів чи інші негаразди.",al={"завдання рейлен","завдання зв'язка клопотів","чому допомагати рейлен"}},{q="Яку роль Лісозаготівельний Табір Східної Долини відіграє в Лісі Елвінн?",a="Східна Долина — головна лісозаготівля на сході Лісу Елвінн, що постачає потрібну деревину для відбудови й утримання Стормвінда та сусідніх поселень.",al={"що таке іствейл","роль іствейла","чому іствейл важливий"}}},fp="17,285,28.547.0,25.201.0,35.147.0,54.200.0,63.194.0"}
P.entries["npc:suzetta-gallina"] = {n="Сюзетта Галліна",s="Сюзетта Галліна належить до родини Галліна, що постачає добірні вина в Стормвінді. Її можна знайти в родинній винарні на Каналах: вона допомагає вести справу й розносити звістку про їхній товар спраглим покупцям по всьому місту.",h="Сюзетта Галліна належить до родини Галліна, що постачає добірні вина в Стормвінді.",kw={"сюзетта галліна","виноробня галліна","вино","канали","стормвінд","торгівля"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що повертаються з небезпек Елвінна чи Вестфолу, зазирнути до крамниці Сюзетти — тепле нагадування про мирне, упорядковане життя столиці."},sec={{t="Смак Каналів",b="Виноробня Галліна, що стоїть над мальовничими водними шляхами Каналів Стормвінда, пропонує містянам добірні вина — і привізні, і зроблені в королівстві. Сюзетта Галліна допомагає наглядати за щоденним життям закладу й продовжує родинну справу: постачає вино шинкам, вельможам і простому люду. Вона не належить до постатей високої політики, проте саме вона уособлює буденний торговий пульс, завдяки якому столиця процвітає попри ширші негаразди."}},faq={{q="Хто така Сюзетта Галліна?",a="Сюзетта Галліна — мешканка Стормвінда з родини Галліна, що тримає Виноробню Галліни на міських Каналах.",al={"хто така сюзетта","сюзетта галліна","жінка з винарні галліни"}},{q="Де знайти Сюзетту Галліну?",a="Вона у Виноробні Галліни на каналах між Торговим Кварталом і Соборною Площею в Стормвінді.",al={"місце сюзетти галліни","де сюзетта","місце винарні галліни"}},{q="Чи пропонує Сюзетта якусь роботу мандрівникам?",a="Не напряму. Її брат Ренато роздає Винні квитки, і той, хто принесе такий квиток Сюзетті у Виноробню Галліни, отримає в подарунок пляшку особливого родинного піно нуар.",al={"завдання сюзетти","завдання вина галліни","реклама винної крамниці"}}},fp="15,263,21.478.0,23.143.0,33.134.0,42.171.0"}
P.entries["npc:sven-yorgen"] = {n="Свен Йорґен",s="Свен Йорґен — фермер у жалобі, що отаборився на Притихлому Березі на півночі Сутінколісся разом зі своїм товаришем Ларсом. Переживши жорстоку різанину своєї родини на Хуторі Йорґенів, Свен живе невідступним прагненням дізнатися, хто зруйнував його дім, і помститися.",h="Свен Йорґен — фермер у жалобі, що отаборився на Притихлому Березі на півночі Сутінколісся разом зі своїм...",kw={"свен йорґен","фермер","помста","темні вершники","притихлий берег","сутінколісся"},ang={["class:Paladin"]="Горе Свена й жага справедливості покладають на паладинів прямий обов'язок: помститися за невинну кров і знищити нежить, підняту з землі його родини.",["faction:Alliance"]="Свен — уособлення трагічного занепаду сільського життя на прикордонні королівства, де прості піддані лишилися беззахисними перед темною магією й зловісними жахами."},sec={{t="Зламане життя",b="Свен народився ще до Першої війни й пам'ятає часи, коли край ще не огорнула пітьма після падіння Медіва. Роками він обробляв землю на Хуторі Йорґенів на півдні Сутінколісся разом із дружиною й дітьми. Те тихе життя обірвалося раптовим насильством: коли Свена не було вдома, на хутір налетіли загадкові Темні Вершники, вирізали його родину й перетворили ферму на цвинтар."},{t="Помста з Притихлого Берега",b="Не в змозі повернутися на згарище рідного дому, Свен облаштував відлюдний притулок на Притихлому Березі разом із другом Ларсом. Він не довіряє чужинцям і вимагає від мандрівників доказів вірності, перш ніж поділитися своїм тягарем. Свен помітив постать, що скрадалася біля його сплюндрованого хутора, і переконався, що цей зайда або сам учинив різанину, або пов'язаний зі зловісними вершниками, які зруйнували його світ."},{t="Правда виходить на світло",b="Тінню, що никала довкола Свенової садиби, виявляється Тремтій — заблукалий волоцюга, чия незграбність ненавмисно привела Темних Вершників у Сутінколісся на пошуки Коси Елуни. Тремтій не завдавав смертельних ударів, але його вчинки випустили на волю кошмар, що стер з лиця землі родину Йорґенів, — і Свенова лють спрямовується на темні сили Воронячого Пагорба та некроманта Морбента Фела."}},faq={{q="Хто такий Свен Йорґен?",a="Свен Йорґен — фермер, що живе в невеликому таборі на північному краю Тихого Берега в Сутінколіссі. Після того як його родину вирізали на їхньому хуторі, він присвятив життя відплаті винним.",al={"свен йорґен","хто такий свен","лор свена"}},{q="Що сталося з родиною Свена?",a="Поки Свена не було вдома, на Хутір Йорґенів прибули страхітливі постаті в чорних плащах, відомі як Темні Вершники. Шукаючи могутній артефакт, вони безжально вбили Свенову дружину й дітей, а землю залишили отруєною нежиттю.",al={"доля родини йорґен","родина свена мертва","що сталося з фермою свена"}},{q="Чому Свен ховається на Тихому Березі?",a="Після різанини Свен покинув свій зруйнований хутір. Разом із Ларсом він облаштував тимчасовий табір на березі річки, щоб ховатися від нежиті, що блукає західним Сутінколіссям, і тим часом готувати помсту.",al={"де свен","табір свена","чому свен таборує"}},{q="Хто та тінь, яку бачив Свен?",a="Свен не знає. Він помітив біля руїн свого хутора постать, що нишпорила там, і просить надійних мандрівників допомогти з'ясувати, хто це був і чи не причетний він до загибелі його родини.",al={"темна постать свена","хто був на фермі йорґена","темна постать сутінколісся"}},{q="Чому Темні Вершники напали на хутір Свена?",a="Темні Вершники шукали в Сутінколіссі Косу Елуни — стародавній артефакт величезної сили. Гонитва за цією реліквією привела їх просто через Свенові землі, лишивши по собі смерть.",al={"чому темні вершники напали","що шукали темні вершники","коса елуни свен"}},{q="Як довго Свен живе в Сутінколіссі?",a="Свен досить старий, щоб пам'ятати Сутінколісся ще до того, як воно поринуло в темряву: тобто жив тут іще до Першої війни, коли край звався світлим і мирним Великим Селищем.",al={"вік свена","скільки років свену","свен до темряви"}}},fp="11,296,16.415.0,30.428.0,20.410.1,19.230.0,31.245.0,38.201.0,35.192.1,43.198.1,36.194.0"}
P.entries["npc:sylvanas-windrunner"] = {n="Сильвана Віндраннер",s="Леді Сильвана Віндраннер — Королева Баньші й верховна володарка Відступників, що править в Андерсіті під руїнами Лордерона. Колись відважна Генерал-Рейнджер Сілвермуну, вона загинула від руки Артаса Менетіла й була піднята ним у нежиття, а згодом вирвалася з-під влади Короля-Ліча. Нині, уклавши союз з Ордою Тралла заради спільного виживання, вона затято прагне забезпечити майбутнє своїй нежиті з вільною волею й помститися Погибелі.",h="Леді Сильвана Віндраннер — Королева Баньші й верховна володарка Відступників, що править в Андерсіті під...",kw={"сильвана віндраннер","королева баньші","відступники","андерсіті","темна леді","лордерон"},ang={["faction:Horde"]="Хоч Відступників прийняли до Орди завдяки заступництву Верховного Друїда Гамуула Рунтотема й співчуттю Тралла, чимало орків і тролів досі дивляться на Сильвану та її двір насторожено.",["race:Undead"]="Для Відступників Темна Леді — визволителька й захисниця, єдина причина того, що вони мають вільну волю й укріплений дім, а не служать бездумно Погибелі."},sec={{t="Загибель Генерал-Рейнджера",b="За життя Леді Сильвана була славетною Генерал-Рейнджером Сілвермуну й керувала обороною Кель'Таласу під час Третьої війни. Коли принц Артас Менетіл повів Погибель у королівство високих ельфів, щоб дістатися Сонячного Колодязя, Сильвана запекло билася, щоб затримати його наступ. Розлючений її опором, Артас убив її, але не дав їй спокійної смерті. Він вирвав її душу з тіла й перетворив на мстиву баньші, змусивши служити Погибелі й допомагати в різанині власного народу."},{t="Постання Відступників",b="Коли після Третьої війни магічна влада Короля-Ліча похитнулася, Сильвана вирвалася з-під його панування й повернула собі збережене тіло. Зібравши іншу нежить, що здобула вільну волю, вона скинула жахолордів, які засіли в руїнах Лордерона, назвала свій народ Відступниками й заснувала підземне королівство Андерсіті. Розуміючи, наскільки самотнім і вразливим є її народ — під загрозою решток Погибелі, фанатиків Багряного Хрестового Походу й підозріливих людських королівств, — вона уклала непевний союз із розрахунку з Вождем Траллом і Ордою."}},faq={{q="Хто така Сильвана Віндраннер?",a="Вона верховна володарка Відступників, що править із Королівського Кварталу Андерсіті. За життя вона була ельфійським Генералом-Рейнджером Кель'Таласу, але після того як Артас Менетіл убив її й підняв із мертвих, вона вирвалася з-під влади Погибелі й очолила нежить із вільною волею.",al={"королева баньші","хто така сильвана","темна пані","лідерка андерсіті"}},{q="Чому Сильвана приєднала Відступників до Орди?",a="Живі народи Альянсу зневажають Відступників і бачать у них лише чудовиськ. Оточена в Лордероні Погибеллю й Багряним Хрестовим Походом, Сильвана потребувала сильних союзників, щоб її молодий народ вижив, тож попросила Вождя Тралла прийняти її до Орди.",al={"чому нежить в орді","союз відступників з ордою","угода сильвани й тралла"}},{q="Як Сильвана вирвалася з-під влади Короля-Ліча?",a="Коли після Третьої війни психічна сила Короля-Ліча почала слабшати, його залізна хватка над Погибеллю ослабла. Сильвана була серед перших могутніх духів, що повернули собі волю: вона одразу заволоділа своїм смертним тілом і обернула свій гнів на Артаса.",al={"як сильвана втекла від артаса","воля сильвани","контроль короля-ліча"}},{q="Яка головна мета Сильвани?",a="Понад усе Сильвана прагне сповна помститися Артасові Менетілу й Погибелі за знищення її батьківщини й поневолення її душі. Водночас вона зміцнює Андерсіті й прагне вибороти для Відступників надійний постійний прихисток у Лордероні.",al={"чого хоче сильвана","мотивація сильвани","мета темної пані"}}},fp="19,463,26.512.0,20.567.0,27.271.0,51.301.0,47.285.0,32.262.0"}
P.entries["npc:syral-bladeleaf"] = {n="Сірал Блейдліф",s="Сірал Блейдліф — нічна ельфійка, мешканка Доланаара в Тельдрассилі, що слугує посередницею Ради Лісу. Вона спрямовує молодих шукачів пригод, які прибувають із Тінедолу, до тутешніх доглядачів, травників і старійшин, що пильнують крихке віття корони.",h="Сірал Блейдліф — нічна ельфійка, мешканка Доланаара в Тельдрассилі, що слугує посередницею Ради Лісу.",kw={"сірал блейдліф","доланаар","рада лісу","тельдрассил","деналан","озеро ал'амет"},ang={["profession:Herbalism"]="Сірал тісно працює з тутешніми природознавцями й постачальниками трав, спрямовуючи мандрівників допомагати ботанічним дослідженням біля Озера Ал'Амет і дбати, щоб свіжі еліксири доходили до старійшин.",["race:NightElf"]="Для молодих нічних ельфів, що виходять із відлюдних курганів Тінедолу, Сірал Блейдліф — один із перших голосів громадського й природного проводу Доланаара."},sec={{t="Голос у Доланаарі",b="Сірал Блейдліф, яку можна знайти біля серця Доланаара, допомагає порядкувати місцевими справами в затінку шатра Тельдрассила. Діючи від імені Ради Лісу, вона спрямовує новоприбулих нічних ельфів до провідників громади й травників по всьому селу та в поблизьких нетрях. Завдяки її проводу мандрівники знайомляться з ботаніком Деналаном біля Озера Ал'Амет і поповнюють запаси для сільських старійшин."},{t="Зв'язки із селом",b="Сірал працює від імені Ради Лісу в Доланаарі. Її обов'язки зосереджені на добробуті громади: вона дбає, щоб лікувальні еліксири доходили до тих, хто їх потребує, а будь-які негаразди в тутешньому живому світі діставали швидку увагу."}},faq={{q="Хто така Сірал Блейдліф?",a="Сірал Блейдліф — нічна ельфійка з Доланаара, що передає накази Ради Лісу й допомагає новоприбулим шукачам пригод підтримувати довколишні лісові громади.",al={"хто така сірал","лор сірал блейдліф","сірал доланаар"}},{q="Де знайти Сірал Блейдліф?",a="Вона в Доланаарі — головному поселенні Тельдрассила, трохи на південний захід від Тінедолу, при головній дорозі.",al={"місце сірал блейдліф","де сірал","карта сірал"}},{q="Які доручення вона дає шукачам пригод?",a="Сірал посилає мандрівників на допомогу ботанікові Деналану біля Озера Ал'Амет, допомагає влаштувати доставку трав'яних еліксирів для старійшин і скеровує шукачів пригод до справ, що підтримують природну рівновагу Тельдрассила.",al={"завдання сірал блейдліф","чого хоче сірал","доручення сірал"}}},fp="15,284,19.422.0,19.247.0,23.179.0,35.123.0,42.199.0"}
P.entries["npc:syurna"] = {n="Сюрна",s="Сюрна — наставниця розбійників нічних ельфів, що ховається серед зелені Ценаріонського Анклаву в Дарнасусі. Вона навчає майбутніх розвідників, шпигунів і таємних агентів калдореїв і посилає новоспечених розбійників на завдання, що випробовують їхню скритність і хитрість.",h="Сюрна — наставниця розбійників нічних ельфів, що ховається серед зелені Ценаріонського Анклаву в Дарнасусі.",kw={"сюрна","наставниця розбійників","ценаріонський анклав","дарнасус","скритність","калдореї"},ang={["class:Rogue"]="Для розбійників із нічних ельфів Сюрна — одна з ваших головних наставниць у Дарнасусі: що більше у вас досвіду, то глибше вона навчає вас прийомів скритності, отрут і бойової точності.",["race:NightElf"]="Сюрна втілює тиху, хижацьку традицію розвідників-калдореїв, які захищають свої лісові святилища з тіні, а не у відкритому бою."},sec={{t="Розвідниця серед гаю",b="Дарнасус славить відкриту бойову міць Вартових і духовну мудрість Сестринства Елуни, але калдореї завжди покладалися й на тіні та скритність. У Ценаріонському Анклаві Сюрна навчає й наставляє тих, хто йде невидимим шляхом. Вона вчить розбійників тонкого мистецтва ухилятися, відмикати замки й завдавати смертельних ударів, щоб Дарнасус мав пильні очі й безшумні клинки для захисту Тельдрассилу."},{t="Випробування хитрості",b="Сюрна не обмежується теоретичними порадами з безпечного анклаву — вона перевіряє, чи готові молоді агенти. Скеровуючи найздібніших новачків на серйознішу польову роботу, вона з'ясовує, чи має агент чуття, без якого не вижити поза гіллям Світового Древа й не послужити Альянсу на небезпечних прикордонних землях."}},faq={{q="Хто така Сюрна?",a="Сюрна — нічна ельфійка, наставниця розбійників у Ценаріонському Анклаві в Дарнасусі. Вона дає бойову науку, вміння й поради розбійникам-шукачам пригод, що служать Альянсу.",al={"сюрна дарнас","хто така сюрна","нічна ельфійка тренер розбійників"}},{q="Де саме в Дарнасусі знайти Сюрну?",a="She is located in the Cenarion Enclave in Darnassus, positioned among the trees and pavilions alongside other shadow-inclined mentors.",al={"де сюрна","місце сюрни","тренер розбійників дарнасу"}},{q="Чому наставниця розбійників — у Ценаріонському Анклаві?",a="Хоча Ценаріонський Анклав пов'язують насамперед із друїдством і природою, розвідники й потаємні слідопити нічних ельфів часто тихо тренуються на його лісистих околицях, далеко від людної пишноти Храму Елуни чи Тераси Воїна.",al={"чому тренер розбійників в анклаві","ценаріонський анклав розбійник"}},{q="Які завдання дає Сюрна?",a="Сюрна бере участь у перших кроках розбійника: посилає новачків, що вже довели себе в Тінедолі, відточувати свій хист у широкому світі, зокрема в завданнях на кшталт «Доля кличе».",al={"завдання сюрни","завдання доля кличе"}}},fp="6,258,23.448.0,16.357.0,14.182.0,45.134.0,47.244.0,30.202.0"}
P.entries["npc:tabetha"] = {n="Табета",s="Табета — відлюдна й могутня чарівниця-людина, що живе глибоко в Багні Пилоброду, на відокремленій фермі серед Трясовини. Далеко від політики Даларану чи Терамору, вона навчає початківців-заклинателів і допомагає тим, хто прагне опанувати могутні таємні й окультні реліквії.",h="Табета — відлюдна й могутня чарівниця-людина, що живе глибоко в Багні Пилоброду, на відокремленій фермі серед...",kw={"табета","багно пилоброду","трясовина","маги","чорнокнижники","сфера орагіла","наставниця"},ang={["class:Mage"]="Табета — важлива наставниця для магів середнього рівня: вона випробовує ваше розуміння таємних ритуалів і посилає вас у небезпечні краї, як-от до Ульдаману, щоб ви відточили свою майстерність.",["class:Warlock"]="Хоча Табета практикує таємну магію, її глибоке знання магічних реліквій робить її незамінною порадницею, коли справа стосується небезпечних артефактів — Пекельної Сфери та Сфери Орагіла."},sec={{t="Відлюдниця Трясовини",b="Табета живе в усамітненій хатині разом зі своїми учнями, захована серед мокрих просторів Багна Пилоброду на північ від Руїн Кам'яного Молота. Оточивши себе алхімічними флаконами й давніми фоліантами, вона свідомо обрала самотність замість академічної ієрархії Східних Королівств. Попри віддаленість, майстерність Табети в таємній магії така славетна, що заклинателі з усього Калімдору, долаючи і звірів, і трясовину, вирушають до неї по науку."},{t="Нейтральна наставниця",b="Табета помітно стоїть осторонь фракційної ворожнечі. Хоч вона й людина за походженням, вона не відмовляє ні новачкам з Альянсу, ні новачкам з Орди, якщо ті виявляють волю до навчання: наставляє магів і допомагає чорнокнижникам із небезпечними зв'язуваннями, як-от зі Сферою Орагіла. Її минуле пов'язане з такими постатями, як Менара Войдрендер, і це свідчить про довгу історію з езотеричною магією, що виходить за межі простої вірності фракції."}},faq={{q="Де знайти Табету?",a="Табета живе у відлюдній хижі на Фермі Табети, глибоко в Трясовині на заході Багна Пилоброду, трохи на північ від Руїн Кам'яного Молота.",al={"місце табети","де табета","ферма табети"}},{q="Чи ворожа Табета до гравців Орди?",a="Ні. Хоча вона людина, Табета нейтральна. Вона навчає учнів і допомагає заклиначам і з Орди, і з Альянсу без жодної різниці.",al={"чи табета лише для альянсу","чи орда може говорити з табетою","фракція табети"}},{q="Чому маги й чорнокнижники шукають її?",a="Табета має рідкісні знання про тайні ритуали, магічні фокуси й обряди підкорення. Маги звертаються до неї по майстерність і випробування сили, а чорнокнижники — по допомогу, щоб очистити чи підкорити могутні артефакти на кшталт Сфери Орагіла.",al={"чому маги й чорнокнижники шукають її","завдання класу табети","куля орахіла табета"}},{q="Що пов'язує її з Менарою Войдрендер?",a="Табету й Менару Войдрендер пов'язує давня спільна історія. Хоча їхні шляхи розійшлися, спільне розуміння могутніх реліквій і магії підкорення поєднує їх, хоч вони й живуть відлюдницями в різних краях.",al={"табета й менара","історія менари войдрендер"}}},fp="7,275,22.455.0,16.418.0,25.150.0,36.149.0,39.239.0,44.205.0"}
P.entries["npc:tai-jin"] = {n="Тай'джин",s="Тай'джин — тролиця з Темного Спису, наставниця жерців у казармах Гострого Пагорба в Дуротарі. Вона веде жерців-початківців Орди й знайомить посвячених Темного Спису з традиційними тролячими обрядами, як-от Вроки слабкості.",h="Тай'джин — тролиця з Темного Спису, наставниця жерців у казармах Гострого Пагорба в Дуротарі.",kw={"тай'джин","жриця","гострий пагорб","темний спис","вроки слабкості","лоа"},ang={["class:Priest"]="Для жерців Орди, що навчаються в Дуротарі, Тай'джин — ваша головна наставниця, перш ніж ви вирушите до величних залів Оргріммара.",["race:Troll"]="Тай'джин знайомить юних жерців Темного Спису з особливими закляттями їхньої культури, як-от Вроками слабкості."},sec={{t="Жриця Гострого Пагорба",b="У міцних казармах Гострого Пагорба Тай'джин наставляє молодих жерців, що вирушають у Дуротар. Орки здебільшого звертаються до шаманізму чи темного мистецтва чорнокнижників, а тролі Темного Спису приносять в Орду власне, самобутнє спілкування з духами й лоа. Тай'джин дає перші уроки жрецтва, щоб нові послушники розуміли і рівновагу світла й тіні, і духовну спадщину, притаманну тролячій культурі."}},faq={{q="Де знайти Тай'джин?",a="Тай'джин — на першому поверсі Казарми Гострого Пагорба в центрі Дуротару, просто поруч з іншими наставниками класів.",al={"місце тай'джин","де тай'джин","тай'джин гострий пагорб"}},{q="Чого навчає Тай'джин?",a="Як наставниця жерців, вона навчає персонажів Орди нових жрецьких заклинань, рангів і вмінь у міру того, як вони набираються досвіду, а також дає перші навчальні завдання послушникам-тролям.",al={"тренер тай'джин","чого навчає тай'джин","закляття жерців гострого пагорба"}},{q="Чому тролиця-жриця служить в орківському поселенні?",a="Гострий Пагорб — головний осередок навчання для всіх молодих шукачів пригод Орди, що виходять із Долини Випробувань і Села Сен'джин. Оскільки орки не практикують жрецьких мистецтв, Тай'джин представляє в поселенні духовні традиції племені Темного Спису.",al={"чому тролиця-жриця в орківському поселенні","тролі в казармі гострого пагорба"}},{q="Які особливі обряди Тай'джин проводить для тролів-жерців?",a="Тай'джин проводить жерців Темного Спису через перші духовні обряди, зокрема навчає їх спрямовувати прокляття предків через Наврочення Слабкості.",al={"завдання пристріту слабкості","завдання тай'джин"}}},fp="7,230,23.478.0,25.120.0,24.170.0,53.263.0,58.153.0"}
P.entries["npc:taiga-wisemane"] = {n="Тайга Вайзмейн",s="Тайга Вайзмейн — старійшина-таурен, що живе в Селі Тіньової Здобичі на скелястому західному узбережжі Пустограю. Він пильно стежить за демонічними підступами в безплідних землях і протидіє культу Палаючого Клинка, що окопався в цьому краї. Тайга посилає чемпіонів Орди зривати демонічні ритуали й запечатувати відчинені брами, доки Палаючий Легіон не здобув тут опори.",h="Тайга Вайзмейн — старійшина-таурен, що живе в Селі Тіньової Здобичі на скелястому західному узбережжі...",kw={"тайга вайзмейн","село тіньової здобичі","пустограй","рука іруксоса","шабаш маннорока","палаючий клинок","таурен"},ang={["class:Warlock"]="Чорнокнижників зацікавить, як Тайга розуміється на Руці Іруксоса: він не виганяє демонів святими обрядами, а обертає резонанс самої темної реліквії, щоб обвалити демонічні портали.",["faction:Horde"]="Тайга дає чемпіонам Орди, що мандрують Пустограєм, важливі настанови й дбає, щоб форпост у Селі Тіньової Здобичі лишався захищеним від демонічного вторгнення.",["race:Tauren"]="Для тауренів Тайга уособлює обов'язок зцілювати й захищати Калімдор від неприродної демонічної пошесті, протистоячи темній спадщині, що спотворила Пустограй."},sec={{t="Пильне око в Селі Тіньової Здобичі",b="Хоча Село Тіньової Здобичі — передусім рибальське поселення тролів Темного Списа, що тулиться до океану, Тайга Вайзмейн оселився тут, щоб стежити за темним чаклунством, яке ворушиться по всьому Пустограю. Він гостро відчуває духовну скверну, що просочується в землю, і не зводить погляду зі сходу, де серед давніх руїн нуртують тіньові культи й залишки демонів."},{t="Стримати демонічну навалу",b="Культ Палаючого Клинка діє з Фортеці Громової Сокири, де експериментує з темними артефактами, щоб розширити свій вплив. Розуміючи, яку загрозу це несе всім мешканцям Пустограю, Тайга доручає вправним шукачам пригод проникнути до фортеці й здобути Демонічну Скриню — окультне вмістилище, у якому зберігається Рука Іруксоса. Цим нищівним ударом він хоче позбавити культ головного фокуса, за допомогою якого той розриває завісу між світами."},{t="Запечатати портали Шабашу",b="Здобути Руку Іруксоса — лише перший крок Тайгиного задуму. На півдні, у Шабаші Маннорока, Палаючий Клинок уже розірвав діючі демонічні розломи. Обертаючи темний фокус проти його ж творців, Тайга доручає перевіреним чемпіонам спрямувати силу артефакту просто в брами й закрити ці канали, перш ніж Палаючий Легіон устигне кинути підкріплення в самісіньке серце Калімдору."}},faq={{q="Хто такий Тайга Вайзмейн?",a="Тайга Вайзмейн — тауренський старійшина, що перебуває в Селі Тіньової Здобичі на західному узбережжі Пустограю. Він радник і дає завдання, присвятивши себе вистежуванню й зриву демонічних ритуалів культу Палаючого Клинка по всьому краю.",al={"хто такий тайга","лор тайги вайзмейна","тайга шадовпрей"}},{q="Чому таурен живе в Селі Тіньової Здобичі?",a="Хоча Тіньова Здобич — здебільшого тролляче поселення, це головна застава Орди на узбережжі Пустограю. Тайга лишається там, щоб пильнувати безлюдні пустища й залучати мандрівників Орди знешкоджувати демонічні загрози поблизу.",al={"чому таурен у селі тіньової здобичі","тайга тролячий населений пункт","таурен у містечку тролів"}},{q="Що Палаючий Клинок робить у Пустограї?",a="Діючи з Фортеці Громової Сокири й Шабашу Маннорока, культ Палаючого Клинка відкриває демонічні брами, щоб викликати до Калімдору сили Палаючого Легіону. Тайга намагається звести нанівець їхні зусилля, поки пустища не заполонили зовсім.",al={"палаючий клинок пустограй","що роблять культисти","культисти фортеці громового сокири"}},{q="Що таке Рука Іруксоса?",a="Рука Іруксоса — демонічний артефакт, замкнений у Демонічній Скрині у Фортеці Громової Сокири. Палаючий Клинок збирається її мерзенною енергією відчиняти портали до Нижнього Світу, але Тайга знаходить спосіб обернути магію руки проти розломів і закрити їх.",al={"рука іруксоса","що таке демонічна скриня","реліквія демонічної скрині"}},{q="Що відбувається в Шабаші Маннорока?",a="Шабаш Маннорока — нечестиве місце на півдні Пустограю, де Палаючому Клинку вдалося відкрити демонічні портали. За настановами Тайги Вайзмейна шукачі пригод несуть туди Руку Іруксоса, щоб силою зачинити брами.",al={"шабаш маннорока","що таке шабаш маннорока","портали пустограю"}},{q="Чи належить Тайга до певного тауренського племені?",a="Тайга носить прізвище Вайзмейн, що відбиває його роль старійшини, глибоко стурбованого духовною рівновагою й демонічною скверною, хоча служить він усій Орді, згуртованій під знаменом об'єднаних племен.",al={"плем'я тайги","плем'я вайзмейн","чи тайга кривавого копита"}}},fp="14,347,28.386.0,25.447.1,27.401.1,22.244.0,45.236.0,44.238.0,27.261.0,31.241.0,45.212.0"}
P.entries["npc:takar-the-seer"] = {n="Такар Провидець",s="Такар Провидець — потайний людський самітник, що отаборився глибоко в Пустках, на схід від Табору Тауражо. Хоч він живе посеред земель, де панує Орда, він вірний Альянсові й допомагає деяким мандрівникам таємними окультними знаннями.",h="Такар Провидець — потайний людський самітник, що отаборився глибоко в Пустках, на схід від Табору Тауражо.",kw={"такар провидець","самітник","чорнокнижник","сукуб","альянс","табір тауражо"},ang={["class:Warlock"]="Для чорнокнижників Альянсу Такар — важливий контакт у Калімдорі: він проводить новачків крізь небезпечні обряди, щоб викликати сукуба й підкорити його своїй службі.",["faction:Alliance"]="Знайти привітне людське обличчя в самому серці земель Орди — рідкісна, хай і самотня, точка опори в центральному Калімдорі."},sec={{t="Відлюдник у савані",b="Такар Провидець живе сам у простому наметі на схід від Табору Тауражо й видається чужим серед сухих рівнин Пусток. Довколишні землі постійно пильнують тауренські воїни й оркські патрулі, проте Такара на його відлюдній галявині ніхто не чіпає. Він вороже ставиться до цікавих зайд з Орди, але рідко сам починає бійку; пильно стежить за обрієм і воліє самоту. Його відлюдне життя наводить на думку про свідому втечу — подалі від гамірної політики Стормвінда."},{t="Окультні поради",b="Хоч Такар і самітник, від світу він відрізаний не цілком. Учні темних мистецтв — особливо чорнокнижники Альянсу, яких посилають зі Східних Королівств, — шукають його загадкових порад, коли намагаються підкорити небезпечні потойбічні сутності. Глибоке розуміння незримих сил і мистецтва душ робить його віддалений табір важливим, хоч і небезпечним, місцем паломництва для тих, хто прагне підкоряти демонів і командувати ними."}},faq={{q="Чому людина-провидець живе сам у Пустках?",a="Такар ніколи не казав чому. Він таборує сам-один на схід від Табору Тауражо, де поблизу немає жодної застави Альянсу, а чорнокнижники, що його шукають, приходять по знання про демонів, а не по його історію.",al={"чому провидець у пустках","що робить такар тут","минуле такара"}},{q="Чи ворожий Такар до гравців Орди?",a="Так, Такар на боці Альянсу й вважається ворожим до шукачів пригод Орди. Проте він не надто агресивний і зазвичай не нападає, якщо його не зачіпати чи не підходити надто близько.",al={"чи такар дружній","чи орда може говорити з такаром","реакція такара на орду"}},{q="Що приводить шукачів пригод Альянсу до його табору?",a="До Такара посилають деяких шукачів з Альянсу, особливо чорнокнижників, що проходять ритуали підкорення могутніх демонів на кшталт Сукуба. Він дає загадкові настанови й підказки, як роздобути реагенти, потрібні, щоб викликати цих істот і підкорити їх.",al={"завдання такара","чому йти до такара","хто говорить із такаром"}}},fp="14,258,25.490.0,14.411.0,48.190.0,34.195.0,45.259.0"}
P.entries["npc:takata-steelblade"] = {n="Таката Стілблейд",s="Таката Стілблейд — орк-воїн, що несе службу на Заставі Духоходів у Пустограї. Келдран відрядив його з Оргріммара разом із Мауріном Боунспліттером, і тепер Таката очолює місцеву кампанію Орди проти демонічної скверни. Його головна мета — винищити тутешніх сатирів, пов'язаних зі зловісним Палаючим Клинком.",h="Таката Стілблейд — орк-воїн, що несе службу на Заставі Духоходів у Пустограї.",kw={"таката стілблейд","застава духоходів","пустограй","сатири","палаючий клинок","келдран","орк"},ang={["class:Warrior"]="Таката — майстер меча, і його кампанія робить ставку на рішучу бойову силу, щоб вирубувати демонічних лазутчиків.",["faction:Horde"]="Таката координує оборону Орди в Пустограї й, діючи із Застави Духоходів, винищує демонічних лазутчиків.",["race:Orc"]="Виконуючи накази керівництва Оргріммара, Таката втілює обов'язок орків викорінювати будь-які рештки демонічного рабства."},sec={{t="Посланий до Пустограю",b="Такату відправили зі столиці до Пустограю за прямим наказом Келдрана — впливової особи в Оргріммарі, що поклялася викривати й викорінювати демонічні підступи. Діючи із Застави Духоходів, відлюдного табору тауренів, Таката координує військові дії проти прислужників Легіону, що спустошують ці безплідні землі."},{t="Гроза сатирів",b="Поки його товариш Маурін Боунспліттер вистежує й розбиває таємних культистів Палаючого Клинка, Таката зосередився на їхніх демонічних союзниках — сатирах. Він організував низку рішучих нападів на осквернених сатирів Пустограю, проріджуючи їхні лави, щоб зламати місцеву владу культу й зупинити поширення скверни."}},faq={{q="Хто такий Таката Стілблейд?",a="Таката Стілблейд — бувалий орк-воїн на Заставі Духоходів у Пустограї. Він керує діями проти демонічних сил і сатирів, союзників Палаючого Клинка.",al={"таката","лор такати","хто такий таката"}},{q="Хто послав Такату до Пустограю?",a="Його послав з Оргріммара Келдран, щоб знищити загрозу від Палаючого Клинка та його демонічних союзників у цьому краї.",al={"хто послав такату","такату послав келдран","накази такати"}},{q="Що пов'язує Такату з Мауріном Боунспліттером?",a="Обох разом відрядив Келдран. Поки Маурін протидіє безпосередньо культистам Палаючого Клинка, Таката спрямовує свої удари на їхніх союзників-сатирів.",al={"таката й маурін","маурін боунспліттер"}},{q="Чому Таката полює на сатирів?",a="Сатири Пустограю — діяльні союзники культу Палаючого Клинка: вони ширять демонічну скверну й загрожують закріпленню Орди в краї.",al={"чому таката полює на сатирів","таката сатири","осквернено сатирами"}},{q="Де знайти Такату Стілблейда?",a="Він на Заставі Духоходів — таборі Орди в північно-центральній частині Пустограю.",al={"місце такати","де таката стілблейд"}}},fp="17,323,16.348.0,21.349.0,25.173.0,28.136.0,64.179.0,29.151.0,37.75.0"}
P.entries["npc:tal"] = {n="Тал",s="Тал — головний господар вітрокрилів Тандер Блафа, що доглядає повітряне гніздовище міста високо над рівнинами Малгору. Він дає досвідчених виверн мандрівникам Орди, які прагнуть перетнути широкі простори Калімдору.",h="Тал — головний господар вітрокрилів Тандер Блафа, що доглядає повітряне гніздовище міста високо над рівнинами...",kw={"тал","господар вітрокрилів","вітрокрили","виверни","тандер блаф","малгор","переліт"},ang={["faction:Horde"]="Тал утримує один із ключових транспортних вузлів Орди в Калімдорі, що безпосередньо пов'язує столицю тауренів із Перехрестям і Оргріммаром.",["race:Tauren"]="Для тауренів, що вирушають за межі прадавніх пасовищ, Тал — найшвидший і найбезпечніший шлях із високих круч у широкий світ."},sec={{t="Господар високого гніздовища",b="На центральній столовій горі Тандер Блафа Тал опікується важливим повітряним шляхом, що з'єднує столицю тауренів з рештою Орди. Зі свого місця він доглядає вірних вітрокрилів — виверн, — стежачи, щоб вони були здорові, ситі й готові до далеких перельотів над суворими краями Калімдору. Чи то відсилаючи гінців до Табору Тауражо, чи відряджаючи розвідників через Пустки до Оргріммара, Тал підтримує незамінну життєву нитку, завдяки якій місто на столовій горі завжди на зв'язку із союзниками."}},faq={{q="Яку роль Тал відіграє в Тандер Блафі?",a="Тал — наглядач вітряних вершників у Тандер Блафі. Він опікується гніздовищем на кручах, доглядає крилатих звірів і відправляє членів Орди в польоти по всьому Калімдору.",al={"хто такий тал","тал майстер польотів","що робить тал"}},{q="Куди Тал відправляє мандрівників?",a="Тал пов'язує Тандер Блаф із місцями по всьому центральному й південному Калімдору — Табором Тауражо, Перехрестям, Оргріммаром і далекими заставами в диких краях.",al={"куди тал відправляє","маршрути тала","польоти тандер блафа"}},{q="Чому літають на вітряних вершниках, а не їздять на звичайних тваринах?",a="Через стрімкі кручі й величезну висоту Тандер Блафа подорож суходолом тут повільна й звивиста. Летючі звірі на кшталт вітряних вершників дають змогу швидко й напряму дістатися височенного міста на плато й залишити його, не спускаючись підйомниками.",al={"чому віверни","літаючі звірі тандер блафа"}}},fp="3,218,24.534.0,41.174.0,30.158.0,55.237.0"}
P.entries["npc:talen"] = {n="Тален",s="Тален — археолог-аматор із нічних ельфів, що отаборився біля Зорамського Узмор'я на північному заході Ашенвалю. Попри постійну небезпеку від наг і застав Орди поблизу, він віддано шукає прадавні реліквії калдореїв, поховані на узбережжі.",h="Тален — археолог-аматор із нічних ельфів, що отаборився біля Зорамського Узмор'я на північному заході...",ang={["faction:Alliance"]="Тален — цінний польовий зв'язковий для мандрівників Альянсу в спірних північних краях Ашенвалю, неподалік від Посту Маестри.",["race:NightElf"]="Для калдореїв Зорамське Узмор'я — трагічне нагадування про Великий Розкол; Тален уособлює прагнення зберегти й повернути спадщину, втрачену, коли прадавні приморські маєтки зісунулися у Велике Море."},sec={{t="Учений на узбережжі",b="Perched at a small camp on the edge of the Zoram Strand, Talen spends his days pursuing historical curiosities rather than waging war. While the wilderness of Ashenvale is fraught with territorial skirmishes and hostile shoreline denizens, Talen remains focused on gathering long-lost treasures from the ruins submerged beneath the waves and sands. He relies heavily on passing adventurers to brave the savage Wrathtail naga and retrieve elusive artifacts—including pristine statuettes and the talismans of dangerous sea-dwelling matriarchs like Ruuzel."}},faq={{q="Хто такий Тален?",a="Тален — нічний ельф, учений і археолог-аматор, що живе в невеликому таборі біля Берега Зорам в Ашенвалі. Замість служити вартовим чи воїном, він вивчає стародавні реліквії, поховані на узбережжі.",al={"хто цей нічний ельф","тален ясенлісся","тален берег зорам"}},{q="Чому Тален таборує біля Берега Зорам?",a="Він досліджує затоплені руїни й береги Берега Зорам, щоб повернути стародавні калдорейські артефакти. Оскільки на пляжі кишать люті наги, а поруч застава Орди Зорам'гар, він живе в невеликому таборі осторонь від головного узбережжя.",al={"why is talen here","talen purpose"}},{q="Які артефакти шукає Тален?",a="Тален просить мандрівників шукати на узбережжі стародавні статуетки, викинуті на берег, і доручає їм вистежити могутню нагу Руузел на острові неподалік, щоб забрати Перстень Зорама — стародавній ключ до замків затопленого міста.",al={"завдання талена","що потрібно таленові","завдання рузел"}},{q="Чи ворожий Тален до Орди?",a="Хоча Тален — союзник нічних ельфів, він насамперед учений і не нападає на мандрівників Орди, якщо його не зачіпати чи не напасти першими.",al={"чи тален ворожий до орди","тален дружній до орди"}}},fp="5,247,20.555.0,13.218.0,43.270.0,31.243.0,30.153.0"}
P.entries["npc:tallonkai-swiftroot"] = {n="Таллонкай Свіфтрут",s="Таллонкай Свіфтрут — нічний ельф, мешканець Доланаара на Тельдрассилі. Стурбований скверною, що зароджується й отруює велике гілля, він залучає молодих шукачів пригод повертати зачаровані реліквії та стримувати нечисті сили, що мучать ліс.",h="Таллонкай Свіфтрут — нічний ельф, мешканець Доланаара на Тельдрассилі.",kw={"таллонкай свіфтрут","доланаар","тельдрассил","ловці снів","фурболги","фероцитас","скверна"},ang={["class:Druid"]="Турботи Таллонкая зосереджені на реліквіях, що безпечно прив'язують розум до Смарагдового Сну, тож його прохання глибоко стосуються духовних традицій друїдів.",["race:NightElf"]="Таллонкай Свіфтрут утілює пильність, потрібну, щоб захистити Тельдрассил у його вразливі перші роки; він просить молодих калдореїв викорінити скверну, що пускає коріння в їхній новій домівці."},sec={{t="Вартовий Доланаара",b="Живучи в кронах Доланаара, Таллонкай Свіфтрут пильно стежить за довколишніми лісами. Як і багатьох нічних ельфів під гіллям новорослого Світового Дерева, його тривожить неприродне збурення живності та лиховісні тіні, що збираються на околицях поселень."},{t="Загрози в кронах",b="Таллонкай спрямовує шукачів пригод проти нечистих сутностей, що порушують спокій Тельдрассила. Його турбують зіпсуті ловці снів, створені, щоб захищати сплячих друїдів; люті фурболги-Вузлошкіри, що піддаються темній недузі; і зіпсуті містики Вузлошкірів на чолі з Фероцитасом, Пожирачем Снів. Для Таллонкая очищення від цих збурень — ключ до захисту крихкої домівки калдореїв."}},faq={{q="Хто такий Таллонкай Свіфтрут?",a="Таллонкай Свіфтрут — нічний ельф у Доланаарі на гілках Тельдрассила, що дає завдання й присвятив себе захисту поселення від місцевих загроз.",al={"хто такий таллонкай","таллонкай свіфтрут","давець завдань доланаара"}},{q="Де знайти Таллонкая Свіфтрута?",a="Він у містечку Доланаар — головному селищі нічних ельфів одразу за межами Тінедолу на Тельдрассилі.",al={"місце таллонкая","де таллонкай","знайти таллонкая свіфтрута"}},{q="Які доручення дає Таллонкай?",a="Він просить мандрівників повернути Смарагдовий Ловець Снів у фурболгів-вузлошкірів, перемогти фурболга-вузлошкіра Фероцитаса, Пожирача Снів, і дати відсіч спотвореним вузлошкірам у завданнях на кшталт «Спотворена ненависть».",al={"завдання таллонкая","чого хоче таллонкай"}},{q="Чому його турбують ловці снів?",a="Ловці снів — священні обереги нічних ельфів, пов'язані зі Смарагдовим Сном, що захищають від кошмарів і темних видінь. Їхня крадіжка й осквернення ворожими створіннями становлять духовну загрозу для місцевих друїдів і мешканців Тельдрассила.",al={"лор смарагдових ловців снів","чому ловці снів"}},{q="Хто такий Фероцитас, Пожирач Снів?",a="Фероцитас, Пожирач Снів, — ватажок гурту зіпсованих містиків-вузлошкірів на північ від Старбріза. Він украв смарагд із ловця снів Таллонкая й носить його на намисті, що вночі світиться зеленим.",al={"хто такий фероцитас","лор фероцитаса"}},{q="Що спричиняє неспокій, з яким бореться Таллонкай?",a="У Тельдрассил дедалі глибше просочується хвороба й неприродна скверна, що доводить колись мирних створінь, як-от фурболгів-вузлошкірів, до лютого божевілля.",al={"чому фурболґи скажені","лор викривленої ненависті"}}},fp="19,238,22.323.0,21.396.0,27.158.0,37.113.0,31.211.0,44.242.0,33.210.0,52.159.0"}
P.entries["npc:tallow"] = {n="Таллов",s="Таллов — воїн-Відступник, що служить в укріпленому поселенні Таррен Мілл у Передгір'ї Гілсбреда. Служачи Темній Леді й Орді, він пильнує спірну передову й допомагає організовувати удари по місцевих загрозах з боку Альянсу.",h="Таллов — воїн-Відступник, що служить в укріпленому поселенні Таррен Мілл у Передгір'ї Гілсбреда.",kw={"таллов","таррен мілл","відступники","передгір'я гілсбреда","гаммерфолл","каменекулаки"},ang={["faction:Horde"]="Таллов дає поборникам Орди важливі доручення на передовій, щоб послабити присутність людей по всьому Передгір'ю Гілсбреда.",["race:Undead"]="Як і багато Відступників у Таррен Міллі, Таллов бореться за розширення володінь Андерсіті на південь від Гір Альтерак."},sec={{t="Клинок у Таррен Міллі",b="У серці Таррен Мілла Таллов стоїть серед сил Відступників і Орди, що тримають оборону в Передгір'ї Гілсбреда. Цей край — порохова діжка, затиснута між людьми сусіднього Саутшора, мандрівними розбійниками Синдикату й ворожими дикими звірами. Таллов допомагає скеровувати вправних шукачів пригод у поле, випробовуючи їхню силу проти огрів-Каменекулаків Аратійського нагір'я, а тоді посилає їх на допомогу обложеній заставі Гаммерфолл."}},faq={{q="Хто такий Таллов?",a="Таллов — воїн із Відступників у Таррен Міллі в Передгір'ї Гілсбреда, що організовує поборників Орди, які б'ються в цьому краї, і дає їм завдання.",al={"хто такий таллов","лор таллова","таллов таррен мілл"}},{q="Де знайти Таллова?",a="Він стоїть у містечку Таррен Мілл, яке тримають Відступники, у північній частині Передгір'я Гілсбреда.",al={"де таллов","місце таллова","знайти таллова"}},{q="Які завдання дає Таллов?",a="Таллов відомий тим, що посилає шукачів пригод Орди на завдання «Молот може впасти»: бійці мають довести себе в боях з ограми-Каменекулаками в Аратійському нагір'ї, а потім доповісти Драмові Фелу в обложеному Гаммерфоллі.",al={"завдання таллова","завдання молот може впасти"}},{q="Яку роль Таррен Мілл відіграє в цій війні?",a="Таррен Мілл — головна північна твердиня Орди в Передгір'ї Гілсбреда, що веде постійні сутички й відкриту війну з людським оплотом Саутшор на півдні.",al={"чому таррен мілл важливий","роль таррен мілла"}}},fp="6,250,22.463.0,14.158.0,24.123.0,30.241.0,43.185.0"}
P.entries["npc:talvash-del-kissel"] = {n="Талваш Дель Кіссель",s="Талваш Дель Кіссель — гном-ювелір, якому не щастить: він утік під час падіння Гномреґана й тепер живе в Кварталі містиків Айронфорджа. Обплутаний боргами й чутками, що переслідують його відтоді, як він утратив дім, він шукає вправних шукачів пригод, які допоможуть повернути втрачені скарби й відновити розбиті реліквії. Гостре око на коштовне каміння й давні прикраси робить його цінним знайомим для тих, хто досліджує глибини Ульдаману.",h="Талваш Дель Кіссель — гном-ювелір, якому не щастить: він утік під час падіння Гномреґана й тепер живе в...",kw={"талваш дель кіссель","ювелір","айронфордж","містичний квартал","ульдаман","намисто","гномреґан"},ang={["faction:Alliance"]="Шукачам пригод з Альянсу, що спускаються до Ульдаману чи руїн Гномреґана, Талваш стане незамінним знайомим, коли треба відновити давні прикраси чи повернути втрачені гномські родинні реліквії.",["race:Gnome"]="Талваш — разюче нагадування про те, як утрата Гномреґана зруйнувала звичайні цивільні життя, перетворивши майстрів на зубожілих вигнанців, що ледве зводять кінці з кінцями в Айронфорджі."},sec={{t="Від майстра до вигнанця-боржника",b="Колись шанований ювелір у технологічному серці Гномреґана, Талваш утратив і ремесло, і дім, коли троги заполонили підземне місто. Утікши з уцілілими біженцями до дворфійської столиці Айронфорджа, він облаштувався в Кварталі містиків. На жаль, переїзд не приніс йому добра. Чутки про сумнівні оборудки й несплачені борги швидко накопичилися й занурили майстра в глибоку фінансову скруту. Не маючи змоги відновити справу звичайними способами, Талваш покладається на вільних шукачів пригод, щоб повернути втрачене майно й урятувати свою зруйновану репутацію."},{t="Реліквії Ульдаману й гномське ремесло",b="Попри всі негаразди, Талваш не втратив ні точності в огранюванні самоцвітів, ні хисту оцінювача. Коли дослідники в Пустищах знаходять давнє розбите намисто глибоко в сховищі Титанів в Ульдамані, Талваш виявляється одним із небагатьох майстрів Східних Королівств, здатних збагнути його хитромудрі чари. Щоб повернути таку силу, потрібні рідкісні складники й копітка праця, але Талваш охоче береться за справу — і щоб розрахуватися з боргами, і щоб довести, що його майстерність нікуди не ділася."}},faq={{q="Хто такий Талваш Дель Кіссель?",a="Талваш — гном-ювелір у вигнанні, що живе в Кварталі містиків Айронфорджа. Утративши дім після падіння Гномреґана, він тепер потерпає від тяжких боргів і чуток, що ширяться довкола, і наймає шукачів пригод, щоб лагодити артефакти й залагоджувати свої рахунки.",al={"хто такий талваш","талваш дель кіссель","талваш"}},{q="Де знайти Талваша?",a="Талваш — у Кварталі містиків Айронфорджа, біля ставка й крамниць із магічним товаром у дворфійській столиці.",al={"місце талваша","де талваш","знайти талваша дель кісселя"}},{q="Що сталося з його справою в Гномреґані?",a="До падіння Гномреґана Талваш торгував коштовностями. Коли вдерлися троги й місто впало, він утратив усе, а згодом чутки й невдачі загнали його в Айронфорджі в глибокі борги.",al={"чому талваш збанкрутів","борг талваша","що сталося з талвашем"}},{q="Що пов'язує Талваша з Ульдаманом?",a="Дослідників, що знаходять розбите джерело сили на стародавніх розкопках Ульдамана, посилають до Талваша. Його знання самоцвітів і зачарування дозволяють йому відновити розбите намисто для шукачів пригод, які здатні зібрати відсутні частини.",al={"талваш ульдаман","намисто ульдаман","завдання розбитого намиста"}},{q="Чи пов'язаний Талваш із завданнями в Гномреґані?",a="Так. Він бере участь у пошуках особистих речей, загублених у зруйнованому місті, зокрема перснів і пристроїв, покинутих під час евакуації Гномреґана.",al={"талваш гномреґан","завдання повернення персня"}},{q="Звідки взялося його ім'я?",a="Талваш дель Кіссель — так звався гном-маг, за якого грав Шон Карнс, провідний дизайнер завдань у Blizzard, ще за часів гри в EverQuest, до роботи над World of Warcraft.",al={"цікавинка талваша","походження імені талваша","шон карнс"}}},fp="18,412,29.611.0,35.495.0,26.241.0,25.123.0,44.202.0,40.250.0,56.157.0,31.175.0"}
P.entries["npc:tammra-windfield"] = {n="Таммра Віндфілд",s="Таммра Віндфілд — тауренка, що живе в Притулку Сонячної Скелі серед висот Гір Кам'яного Кігтя. Глибоко чутлива до рівноваги землі, вона вчить мандрівників з Орди шанувати природне коло відродження й підтримує надію серед вершин. Її турботи — і здоров'я дикої природи, і безпека рідних.",h="Таммра Віндфілд — тауренка, що живе в Притулку Сонячної Скелі серед висот Гір Кам'яного Кігтя.",kw={"таммра віндфілд","притулок сонячної скелі","таурени","земна мати","відродження","гори кам'яного кігтя"},ang={["class:Druid"]="Її наголос на колі відродження й плеканні нового життя відбиває головні засади друїдства, тож її прохання глибоко відгукуються тим, хто дбає про дику природу.",["faction:Horde"]="На спірних землях Гір Кам'яного Кігтя Таммра допомагає втримувати Притулок Сонячної Скелі як надійну, незламну опору для мандрівників Орди.",["race:Tauren"]="Таммра втілює відданість тауренів Земній Матері й показує, як духовна шана обертається на справжнє відновлення навіть далеко від Малгору."},sec={{t="Охоронниця Сонячної Скелі",b="Притулок Сонячної Скелі — важливе святилище Орди серед скелястих вершин Гір Кам'яного Кігтя, оточене ворожими гарпіями, лісорубами Венчурної Компанії й хижаками, що чатують довкола. Таммра Віндфілд — серед тих, хто опікується поселенням: вона пильно наглядає і за гірською дикою місциною, і за мандрівниками, що переступають його поріг. Її лагідна вдача приховує рішучість, без якої не втримати домівку на такій суворій землі."},{t="Плекаючи землю",b="Як і багато її одноплемінників, Таммра шанує Земну Матір, дотримуючись безперервного ритму зростання й тління в природі. Через доручення, які вона дає мандрівникам, — дбати про коло відродження й давати нове життя, — вона протидіє руїні, яку несуть Горам Кам'яного Кігтя війни й визискування. Для Таммри захищати землю — значить дієво її зцілювати, щоб життя квітло навіть у пошрамованому гірському ґрунті."},{t="Рідня й пильність",b="Окрім духовних обов'язків перед навколишньою природою, Таммра глибоко дбає про товаришів і рідних, які наважуються йти підступними стежками Гір Кам'яного Кігтя. Коли розходиться звістка, що серед скель зникли мандрівники чи родичі, вона серед перших шукає надійної допомоги. Для Таммри виживання Притулку Сонячної Скелі тримається на взаємному захисті й вірності не менше, ніж на злагоді з природою."}},faq={{q="Хто така Таммра Віндфілд?",a="Таммра Віндфілд — тауренка, що дає завдання в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Вона дбає про добробут поселення, природний колообіг гірського краю й виживання своїх товаришів-мандрівників.",al={"хто така таммра","таммра віндфілд","таммра притулок сонячної скелі"}},{q="Де знайти Таммру Віндфілд?",a="Вона в Притулку Сонячної Скелі — таборі Орди, захованому на західних висотах Гір Кам'яного Кігтя, куди веде гірська стежка, що відгалужується від головної дороги долини.",al={"місце таммри віндфілд","де таммра","знайти таммру"}},{q="Які завдання дає Таммра?",a="Таммра пов'язана із завданнями про відродження й добробут своїх родичів, зокрема «Коло відродження» й «Нове життя», а ще приймає мандрівників, що приносять звістку про вцілілу родичку, у завданні «Кая жива».",al={"завдання таммри","список завдань таммри віндфілд"}},{q="Яка роль Таммри в Притулку Сонячної Скелі?",a="Таммра — опора громади й духовна опікунка: вона спрямовує шукачів пригод повертати життєву силу довколишнім нетрям і плекає ті зв'язки, що бережуть цю віддалену заставу.",al={"що робить таммра","роль таммри"}},{q="Чому Таммра дбає про природний колообіг?",a="У тауренській культурі берегти рівновагу означає плекати цикли смерті й відродження Земної Матері. Коли чужі сили й гірські звірі загрожують краю, Таммра прагне ростити нове життя, щоб зцілити поранені нетрі.",al={"лор циклу відродження","чому відродження стоунталон"}},{q="Чи привітна Таммра до гравців Альянсу?",a="Ні. Притулок Сонячної Скелі — застава Орди, а Таммра на боці Тандер Блафа й Орди, тож ворожа до непроханих гостей з Альянсу.",al={"чи таммра ворожа","чи альянс може говорити з таммрою"}}},fp="16,355,20.421.0,18.436.0,21.420.0,24.239.0,34.190.0,30.199.0,42.190.0,45.241.0,39.148.0"}
P.entries["npc:tannok-frosthammer"] = {n="Таннок Фростгаммер",s="Таннок Фростгаммер — дворфійський мешканець, якого можна знайти в Ґуральні Тандербрю біля Хараноса в Дун Мороґу. Він тривожно чекає на крам із Долини Холодного Хребта, глибоко стурбований тим, що напади трогів перерізали дороги до Анвілмара.",h="Таннок Фростгаммер — дворфійський мешканець, якого можна знайти в Ґуральні Тандербрю біля Хараноса в Дун...",kw={"таннок фростгаммер","дворф","ґуральня тандербрю","харанос","припаси","троги","гендс спрінґспрокет"},ang={["faction:Alliance"]="Затримані партії Таннока показують, як навіть поселення в серці краю, як-от Харанос, відчувають напругу від дедалі частіших набігів трогів.",["race:Dwarf"]="Для дворфів, що залишають Анвілмар заради широкого світу, доставити припаси Танноку до Ґуральні Тандербрю — один із найперших кроків у серце Дун Мороґу."},sec={{t="Перерізана лінія постачання",b="Перебуваючи при Ґуральні Тандербрю в Хараносі, Таннок Фростгаммер пильно стежить за прибуттям доставок і місцевими новинами. Раптовий наплив трогів, що заполонили Перевал Холодного Кряжа, перервав звичне сполучення з Долиною Холодного Хребта, і Таннок утратив регулярний зв'язок із поселенням в Анвілмарі. Покладаючись на кур'єрів на кшталт гнома-майстра Гендса Спрінґспрокета, щоб ті переправляли життєво важливі припаси й новини небезпечним засніженим перевалом, Таннок утілює тиху тривогу, яку поділяють багато Бронзбірдів, поки підземні загрози підповзають до їхніх порогів."}},faq={{q="Де перебуває Таннок Фростгаммер?",a="Таннок Фростгаммер стоїть біля Ґуральні Тандербрю, трохи на схід від головного перехрестя в Хараносі, у Дун Мороґу.",al={"місце таннока","де таннок","знайти таннока фростгаммера"}},{q="Чому Таннока тривожить Долина Холодного Хребта?",a="Таннока глибоко непокоїть навала трогів, що заполонила Перевал Холодного Кряжа. Захоплений прохід перерізав постійний зв'язок і торгівлю між поселенням Анвілмар у долині й рештою Дун Мороґу.",al={"турботи таннока","чому таннок стурбований","трогги перевалу колдрідж"}},{q="З ким Таннок співпрацює в Долині Холодного Хребта?",a="Таннок отримує вантажі від Гендса Спрінґспрокета — гнома-постачальника, що працює внизу, в Долині Холодного Хребта, і залучає мандрівників переносити товари через небезпечний перевал.",al={"постачальник таннока","доставка гендса спрінґспрокета","хто постачає таннока"}}},fp="18,250,21.582.0,36.138.0,45.209.0,46.180.0"}
P.entries["npc:taragaman-the-hungerer"] = {n="Тараґаман Голодний",s="Тараґаман Голодний — кремезний вартовий скверни, що чатує в розпечених печерах Провалля Лютого Вогню під Оргріммаром. Хоч його повсюдно бояться як демонічного володаря, що стоїть за культом Пекучого Клинка, його присутність у вогняних глибинах служить темнішій, підступнішій меті. Орда прагне його знищити, щоб позбутися демонічної скверни, що отруює нутрощі міста.",h="Тараґаман Голодний — кремезний вартовий скверни, що чатує в розпечених печерах Провалля Лютого Вогню під...",kw={"тараґаман голодний","вартовий скверни","пекучий клинок","провалля лютого вогню","оргріммар"},ang={["class:Warlock"]="Поки чорнокнижники практикують свої темні мистецтва в Тіньовій Розколині нагорі, дикий і ворожий вартовий скверни на кшталт Тараґамана — неприборкана загроза таємності й безпеці їхнього прихованого ремесла.",["class:Warrior"]="Бій із Тараґаманом вимагає твердо витримувати нищівні удари й не дати його жорстоким апперкотам скинути вас у лаву довкола.",["faction:Horde"]="Для молодих воїнів і заклиначів Орди знищення Тараґамана в глибинах під Оргріммаром — важливе випробування, щоб захистити свою столицю від демонічної скверни."},sec={{t="Звір унизу",b="Никаючи між озерами магми в Проваллі Лютого Вогню, Тараґаман Голодний становить пряму й жахливу загрозу безпеці Оргріммара. Багатьом розвідникам і молодим воїнам, яких посилають у темне провалля, цей демонічний вартовий скверни видається головним ватажком культистів Пекучого Клинка, що пекельною силою підкоряє слабодухих і оскверняє підземні ходи під фортецею Тралла."},{t="Смертоносна приманка",b="Попри владну поставу й нищівну жорстокість, Тараґаман — не той, хто направду керує Пекучим Клинком. Справжній провід культу криється в тіні — це сатир Баззалан і чорнокнижник Джерґош Призивач. Для цих розважливих інтриганів височенний вартовий скверни — не більше ніж принада, якою не шкода пожертвувати: жахливий відволікальний маневр, що має заманювати молодих захисників Орди в пекучі вулканічні глибини, де їх можна перебити."}},faq={{q="Що за демон Тараґаман Голодний?",a="Тараґаман — вартовий скверни, брутальний ударний воїн Палаючого Легіону. Важкими ударами й вогняною магією він трощить непроханих гостей у магмових печерах Провалля Лютого Вогню.",al={"яка раса тараґамана","тип демона тараґамана","чи тараґаман демон"}},{q="Чи Тараґаман Голодний — ватажок культу Пекучого Клинка?",a="Так здебільшого вважають. Тараґаман — найгрізніша демонічна сила в Проваллі Лютого Вогню, і молодих захисників Орди посилають убити його як володаря культу, хоча провалля, можливо, приховує більше таємниць, ніж одного вартового скверни.",al={"хто очолює пекучий клинок","чи тараґаман головний","вожак культу тараґаман"}},{q="Чому Орда хоче смерті Тараґамана?",a="Орда не може дозволити демонічній силі гноїтися просто під своєю столицею. Пекельна скверна Тараґамана загрожує отруїти Оргріммар зсередини, і знищити його необхідно, щоб убезпечити печерні ходи під вулицями.",al={"чому вбивати тараґамана","лор завдання знищити звіра","загроза тараґамана для оргріммара"}},{q="Де знайти Тараґамана?",a="Тараґаман — глибоко в Проваллі Лютого Вогню, у підземних вулканічних тунелях, куди можна потрапити з Тіньової Розколини в Оргріммарі.",al={"місце тараґамана","де тараґаман","тараґаман провалля лютого вогню"}},{q="Що стається із серцем Тараґамана?",a="Переможці вирізають Серце Тарагамана Голодаря як доказ загибелі чудовиська, щоб завершити завдання з очищення від демонічного авангарду, що гноїться під Оргріммаром.",al={"серце тараґамана","завдання серця тараґамана","нагорода за серце тараґамана"}},{q="Як Тараґаман б'ється в бою?",a="Тараґаман покладається на нищівні фізичні удари, потужний аперкот, що підкидає ворогів у повітря, і часом на спалахи Вогняної Нови, які обпікають усіх, хто стоїть поруч.",al={"здібності тараґамана","бій з тараґаманом","механіка тараґамана"}}},fp="22,358,15.413.0,12.450.1,45.187.0,63.230.0,39.244.0,29.144.0,34.179.0,35.180.0"}
P.entries["npc:targorr-the-dread"] = {n="Тарґорр Жахливий",s="Тарґорр Жахливий — сумнозвісний кат з орків Блекрок, ув'язнений глибоко у В'язниці Стормвінда. Відомий жорстокими катуваннями полонених солдатів Стормвінда, він уникнув страти, яку безкінечно відкладали через бюрократичну недолугість і корупцію. Коли під проводом Братства Дефіас у В'язниці спалахнув бунт, Тарґорр вирвався на волю й пристав до бунтівних каторжників.",h="Тарґорр Жахливий — сумнозвісний кат з орків Блекрок, ув'язнений глибоко у В'язниці Стормвінда.",kw={"тарґорр жахливий","кат","орки блекрок","в'язниця стормвінда","редрідж","бунт"},ang={["faction:Alliance"]="Покарання Тарґорра в охопленій бунтом В'язниці приносить давно очікувану справедливість полеглим захисникам Лейкшира й допомагає стримати хаос під столицею.",["race:Human"]="Для людей Стормвінда — особливо тих, хто пов'язаний із Редріджем, — Тарґорр уособлює страшну ціну бюрократичних провалів королівства й незмінну загрозу від орків Блекрок."},sec={{t="М'ясник Редріджу",b="До полону Тарґорр Жахливий був головним катом клану Блекрок під командою воєначальника Ґат'Ілзоґґа. Діючи з захоплених руїн у Редріджі, він вирізнявся жорстокістю навіть за кривавими мірками Темної Орди. Вартові й ополченці Стормвінда, що боронили прикордоння, зазнавали від його рук страшних мук і повільної смерті, і його ім'я стало одним із найненависніших у королівстві."},{t="Правосуддя, якого не сталося",b="Коли силам Альянсу нарешті вдалося схопити Тарґорра живим, його в кайданах привезли до столиці й замкнули в суворо охоронюваній В'язниці чекати страти. Проте гниль у судовій і політичній бюрократії Стормвінда загальмувала справу. Паралізовані хабарництвом, нескінченною паперовою тяганиною й недбалістю, суди так і не винесли смертного вироку, якого він заслужив, і кровожерливий воєнний злочинець досі сидить у камері під самим серцем міста."},{t="Бунт у камерах",b="Коли Братство Дефіас влаштувало криваву втечу з в'язниці, Тарґорр побачив свій шанс. Вирвавшись із камери, безжальний орк приєднався до бунтарів Дефіас і перетворив свій блок на бойню. В'язниця цілковито вийшла з-під контролю Наглядача Телвотера, тож містечка на кшталт Лейкшира, що досі зализують гіркі рани, завдані Тарґорром їхнім захисникам, наймають шукачів пригод, готових зануритися у вир бунту й принести голову м'ясника."}},faq={{q="Хто такий Тарґорр Жахливий?",a="Тарґорр Жахливий — орк Блекрок, що був верховним катом у Воєначальника Ґат'Ілзоґґа. Сумно відомого тим, що катував полонених солдатів Стормвінда, його спіймали й ув'язнили у В'язниці Стормвінда.",al={"хто такий тарґорр","лор тарґорра","орк бос в'язниці"}},{q="Чому Тарґорра не стратили, коли схопили?",a="Хоча Тарґорра схопили й мали судити, неповоротка, роздута й продажна судова машина Стормвінда затягла справу. Страту відкладали через нескінченну бюрократичну тяганину, аж поки у в'язниці не спалахнув бунт.",al={"чому його не стратили","чому тарґорр живий","корупція стормвінда"}},{q="Чому орк у спілці з Братством Дефіас?",a="Тарґорр не поділяє політичних образ Братства Дефіас, але в хаосі тюремного бунту в'язні всіх мастей об'єдналися проти наглядачів. Він приєднався до бунтівників лише для того, щоб вирватися на волю й різати будь-яких вартових чи шукачів пригод, що трапляться на його шляху.",al={"чому дефіас працюють із орками","тарґорр союзник дефіас","орки у в'язниці"}},{q="Хто тепер хоче смерті Тарґорра?",a="Вартовий Бертон, що служить у Лейкширі в Редріджі, оголосив винагороду за відрубану голову Тарґорра. Люди Лейкшира чимало натерпілися від жорстокості Тарґорра й хочуть побачити страту, якої так і не дочекалися від судів Стормвінда.",al={"хто дає завдання про тарґорра","вартовий бертон тарґорр","нагорода за тарґорра"}},{q="Де знайти Тарґорра?",a="Тарґорр — у підземеллі В'язниці Стормвінда: засів в одному з дальніх блоків камер разом з іншими бунтівними в'язнями.",al={"де тарґорр","місце тарґорра","кімната у в'язниці"}},{q="До якого клану належить Тарґорр?",a="Тарґорр — з орків Блекрок, решток свавільної Темної Орди, що діють із Гір Редріджу й Шпиля Блекрок, а не з Нової Орди Тралла.",al={"клан тарґорра","чи тарґорр з орди","тарґорр блекрок"}}},fp="17,376,23.455.0,14.463.0,21.464.0,25.214.0,49.243.0,49.284.0,27.230.0,27.130.0,33.178.0"}
P.entries["npc:tarindrella"] = {n="Тариндрелла",s="Тариндрелла — дріада, що пильнує затишні ліси Тінедолу в Тельдрассилі. Як Дочка Кенарія вона тісно працює із захисниками — нічними ельфами, досліджуючи неприродну скверну, що вражає звірину Світового Дерева.",h="Тариндрелла — дріада, що пильнує затишні ліси Тінедолу в Тельдрассилі.",kw={"тариндрелла","дріада","дочка кенарія","тінедол","мох скверни","ґрелли","вузлошкіри","тельдрассил"},ang={["class:Druid"]="Друїди високо шанують дріад як споріднених духів дикого краю, тож провід Тариндрелли щодо недуги Тельдрассила — нагальний заклик берегти рівновагу.",["race:NightElf"]="Для молодих нічних ельфів, що починають у Тінедолі, Тариндрелла — одна з перших дріад, яких вони зустрінуть; вона втілює прадавній союз між калдореями й дітьми Кенарія."},sec={{t="Дочка Кенарія в Тінедолі",b="Дріади — ревні доглядачки природи, народжені від напівбога Кенарія. Поки багато хто з них лишається в глибині прадавніх лісів Калімдору, як-от Ашенваль, Тариндрелла мешкає в захищеній долині Тінедолу на вітті Тельдрассила. Вона — важливий міст між дикими духами й молодими захисниками — нічними ельфами, що роблять перші кроки за межами Алдрассила. Її головна турбота — застаріла скверна, що повзе в ліс, тож вона доручає надійним шукачам пригод відганяти тутешніх шкідників і збирати підказки про корінь недуги."},{t="Дослідження недуги Тельдрассила",b="Попри велич Тельдрассила як нової корони народу нічних ельфів, його незаймані гаї ховають несподівану хворобу. Колись мирні фурболги покинули свої оселі, щоб згуртуватися в плем'я Вузлошкірів, а ґрелли й ґреллята, споганені лихим Мохом Скверни, заполонили пагорби довкола Тінедолу. Тариндрелла підозрює, що за цими змінами стоїть Мох Скверни, і велить посвяченим стати проти ґреллів і принести зразки, щоб спинити скверну, перш ніж та поглине святилище молодого гаю."}},faq={{q="Хто така Тариндрелла?",a="Тариндрелла — дріада, що живе в Тінедолі на Тельдрассилі. Вона допомагає місцевим нічним ельфам пильнувати дику природу й спрямовує молодих захисників на боротьбу з дивною хворобою, що загрожує гілкам Світового Дерева.",al={"лор тариндрелли","хто така тариндрелла","дріада тінеділа"}},{q="Хто такі дріади?",a="Дріади — зачаровані лісові створіння, доньки напівбога Кенарія. Мають верхню частину тіла нічної ельфійки, а нижню — оленяти, і віддано оберігають священні гаї й рівновагу Калімдору.",al={"лор дріад","що таке дріади","доньки ценарія"}},{q="Чому Тариндреллу тривожить Тінедол?",a="Навіть у безпечному серці Тельдрассила неприродна скверна почала спотворювати місцевих створінь: вона зганяє фурболгів у вороже плем'я Вузлошкірів і наповнює пагорби ґреллами, зараженими Мохом Скверни. Тариндрелла прагне очистити цю скверну й уберегти молодий гай від тління, що ширить.",al={"скверна тінеділа","завдання тариндрелли","що не так з тінеділом"}},{q="З якими загрозами вона посилає битися шукачів пригод?",a="Тариндрелла просить допомогти дати відсіч ґреллам і ґрелликам, що заполонили Тінедол, і зібрати мерзенний Мох Скверни, який вони носять, щоб з'ясувати, чи не він стоїть за скверною.",al={"павуки тариндрелли","завдання печери тіньової нитки"}}},fp="11,240,36.535.0,37.508.0,19.221.0,16.226.0,46.301.0,47.174.0"}
P.entries["npc:tarrel-rockweaver"] = {n="Таррел Роквівер",s="Таррел Роквівер — стривожений дворф, що чатує на мосту, який веде до Гавані Менетіл. Глибоко переймаючись долею дружини, Меррін, археологині, що вирушила вглиб краю з загоном Велґара, він не зводить очей із дороги, чекаючи звістки, що вона в безпеці.",h="Таррел Роквівер — стривожений дворф, що чатує на мосту, який веде до Гавані Менетіл.",kw={"таррел роквівер","меррін роквівер","гавань менетіл","шукач велґар","місце розкопок велґара","багнокрай"},ang={["faction:Alliance"]="Для мандрівників, що прибувають до порту Менетіла, Таррел — безпосередній зв'язок із негодами, які спіткали громадян Альянсу на диких болотах.",["race:Dwarf"]="Тривога Таррела підкреслює, якою небезпечною ціною обертається невтомне прагнення Ліги Дослідників відкопати витоки дворфів на диких рубежах Каз Модану."},sec={{t="Варта на мосту",b="Поки через Гавань Менетіл ідуть торгові й військові вантажі, Таррел Роквівер тривожно чатує на мосту на околиці містечка. Його дружина, Меррін Роквівер, приєдналася до престижної археологічної експедиції Шукача Велґара вглиб Багнокраю. Коли люті раптори заполонили розкоп і перервали звичний зв'язок, Таррел лишився в містечку сам і благає мандрівників розвідати шлях на схід, до Місця Розкопок Велґара, щоб переконатися, що вона пережила лихо."}},faq={{q="Хто такий Таррел Роквівер?",a="Таррел — дворф з Айронфорджа, що нині тиняється біля в'їзного мосту Гавані Менетіл. Він відчайдушно чекає звісток про свою дружину Меррін, яка вирушила на розкопки вглиб краю.",al={"таррел роквівер","хто цей дворф","дворф на мосту менетіл"}},{q="Чому Таррел просить мандрівників про допомогу?",a="Він утратив зв'язок із дружиною Меррін після того, як її археологічна команда натрапила на небезпеку на розкопках. Не маючи змоги покинути свій пост, він просить перехожих шукачів пригод вирушити на схід, до Місця Розкопок Велґара, і знайти її.",al={"завдання таррела","в пошуках експедиції","місія таррела роквівера"}},{q="Хто така Меррін Роквівер?",a="Меррін Роквівер — дружина Таррела й археологиня з команди розкопок Шукача Велґара. Вона пережила напад на їхній табір і сховалася з іншими вцілілими в печері над розкопками.",al={"меррін роквівер","дружина таррела","хто така меррін"}},{q="Куди поділася дружина Таррела?",a="Меррін вирушила на схід, у Багнокрай, вивчати стародавні реліквії титанів і дворфів. Після нападу на головні розкопки вона й уцілілі копачі сховалися в печері над зруйнованими розкопками.",al={"де меррін","місце експедиції","притулок велґара"}}},fp="17,257,21.489.0,25.183.0,40.217.0,25.214.1,27.209.1"}
P.entries["npc:tatternack-steelforge"] = {n="Таттернак Стілфордж",s="Таттернак Стілфордж — оркський коваль на суворій савані Пусток, що дає роботу мандрівникам, які вміють поводитися із сирим металом і небезпечною прикордонною звіриною. Знавець заліза й вогню, він прагне вивчити місцеві руди й озброїти сили Орди проти загроз на рівнинах.",h="Таттернак Стілфордж — оркський коваль на суворій савані Пусток, що дає роботу мандрівникам, які вміють...",kw={"таттернак стілфордж","коваль","руда","орки","пустки","зброя"},ang={["faction:Horde"]="Таттернак відіграє важливу роль, тримаючи сили Орди озброєними й забезпеченими проти місцевих загроз, як-от шипогривів і кентаврів.",["profession:Blacksmithing"]="Для ковалів, що мандрують Пустками, Таттернак — споріднена душа: він розуміє вічну потребу в добрій руді й якісній сталі в беззаконному прикордонні."},sec={{t="Орк біля горна",b="На посушливих просторах Пусток тримати застави Орди озброєними — непросте завдання. Таттернак Стілфордж приносить на рубіж давнє ковальське вміння свого народу й шукає і практичну зброю, і незвичні зразки гірських порід, щоб зміцнити позиції Орди проти диких звірів, кентаврів-нападників і ворожих шипогривів."}},faq={{q="Хто такий Таттернак Стілфордж?",a="Таттернак Стілфордж — орк-зброяр у Пустках. Він допомагає озброювати захисників Орди: перевіряє мінерали, вивчає місцеві руди й дає надійну зброю в руки воїнам поблизу.",al={"хто такий таттернак","лор таттернака стілфорджа","що робить таттернак"}},{q="Де знайти Таттернака Стілфорджа?",a="Таттернак працює в Пустках, серед таборів Орди вздовж центральних стежок савани.",al={"де таттернак","місце таттернака стілфорджа","координати таттернака"}},{q="Які доручення дає Таттернак?",a="Таттернак здебільшого просить шукачів пригод повертати зброю й приносити свіжі зразки руди з усіх Пусток, щоб допомогти йому в ковальській справі.",al={"завдання таттернака","давець завдань зброя на вибір","завдання зразка руди"}}},fp="21,291,19.336.0,29.210.0,41.113.0,41.142.0"}
P.entries["npc:tavernkeep-smitts"] = {n="Шинкар Смітс",s="Шинкар Смітс — господар Таверни «Багряний Крук» у Даркширі. Він тримає заклад у самому серці громадського життя Сутінколісся й знає геть усі міські плітки та нерозкриті місцеві трагедії. Довга пам'ять і гостре око роблять його безцінним співрозмовником для кожного, хто розслідує темну історію краю.",h="Шинкар Смітс — господар Таверни «Багряний Крук» у Даркширі.",kw={"шинкар смітс","таверна","багряний крук","даркшир","плітки","сталван"},ang={["class:Rogue"]="Розбійникам, що розслідують давні справи й тіньові постаті, Смітс — ідеальний інформатор: він помічає, що пишуть відвідувачі, коли вони панікують і що лишають по собі.",["faction:Alliance"]="Для мандрівників Альянсу, що виходять із темного лісу, Смітс пропонує не лише прихисток і напої, а й цінні місцеві відомості про загрози, що переслідують Сутінколісся."},sec={{t="Серце Даркшира",b="За шинквасом Таверни «Багряний Крук» Шинкар Смітс пропонує тепло вогнища й випивку втомленим мандрівникам, місцевим містянам і знервованим вартовим Нічної Варти, що щодня ризикують життям у Сутінколіссі. Як одне з найдавніших знайомих облич у місті, Смітс чує кожну чутку, що просочується крізь морок. Поки інші містяни ховаються за зачиненими віконницями, Смітс тверезо й уважно придивляється до кожного, хто переступає його поріг, — помічає дивну поведінку, квапливі від'їзди й химерних відвідувачів."},{t="Пам'ять про Сталвана",b="Смітс роками потай стежив за легендою про Сталвана Містмантла. Коли багато років тому вирізали родину стормвіндських вельмож, що гостювала в цих краях, Смітс разом із Маршалом Гаґґардом оглядав місце різанини. Серед кривавого безладу Смітс знайшов пошматовані, забрьохані сторінки щоденника, але слідчим тоді так і не вдалося офіційно довести, що почерк належить Сталванові. Смітс роками беріг ті вицвілі клаптики, переконаний, що похмура правда колись таки вийде на світло."},{t="Таємничий відвідувач",b="Пильність Смітса стосується й нинішніх загроз. Коли наляканий відлюдник Тремтій сховався в «Багряному Круку», Смітс бачив, як той гарячково строчив щось в особистому щоденнику, а потім у сліпій паніці втік із таверни. Коли слідчий знаходить покинутий щоденник, Смітс одразу впізнає книгу й спрямовує шукача до Воронячого Пагорба, допомагаючи розплутати прокляті події, що мучать ліс."}},faq={{q="Де знайти Шинкаря Смітса?",a="Смітс стоїть за шинквасом на першому поверсі Таверни «Багряний Крук» — головної корчми на міській площі Даркшира.",al={"місце смітса","де шинкар смітс","шинкар червоного ворона"}},{q="Що Смітс знає про Сталвана Містмантла?",a="Багато років тому Смітс разом із Маршалом Гаґґардом розслідував різанину шляхетних гостей. На місці злочину Смітс знайшов розірвані сторінки в багнюці й зберіг їх. Якщо принести йому нові докази, що пов'язують Сталвана зі злочином, Смітс віддасть заболочені сторінки щоденника, щоб їх доставили Командирові Алтеї Ебонлок.",al={"смітс сталван","легенда сталвана смітс","брудні сторінки сталвана"}},{q="Що Смітс знає про Тремтія?",a="Тремтій якийсь час жив у Таверні «Багряний Крук», де Смітс бачив, як той гарячково щось писав у щоденнику, а потім утік у нестямі від жаху. Коли ви приносите щоденник Тремтія до таверни, Смітс його впізнає й радить шукати Тремтія біля Цвинтаря Воронячого Пагорба.",al={"смітс тремтій","щоденник тремтія смітс","розпитайте в корчмі смітс"}},{q="Які напої варить чи замовляє Смітс?",a="Смітс добуває складники для місцевих сумішей: зокрема посилає шукачів пригод у прокляті нетрі по гнилоцвіт, щоб зварити міцну місцеву суміш, яку в народі звуть «Зомбі-сік».",al={"зомбі-сік","гнилі квіти смітса","напій смітса"}},{q="Хто такий Маршал Гаґґард і звідки Смітс його знає?",a="Маршал Гаґґард — старий ветеран Варти Стормвінда, що живе у відлюдній хаті серед пагорбів. Багато років тому вони зі Смітсом разом розслідували моторошні вбивства вельмож, і ця нерозкрита справа їх поріднила.",al={"смітс гаґґард","зв'язок із гаґґардом"}},{q="Чи має Смітс відому родину в Даркширі?",a="Ні про кого не відомо. Смітс сам тримає «Багряного Крука», і жодних його родичів у Даркширі не знають.",al={"родичі смітса","мері смітс"}}},fp="17,318,18.511.0,21.474.1,18.433.1,35.138.0,47.323.1,36.276.1,40.201.0,53.222.0,47.118.0"}
P.entries["npc:telf-joolam"] = {n="Телф Джулам",s="Телф Джулам — троль-шаман із джунглів, із племені Темного Списа, що наглядає за Святинею Приспаного Полум'я. Він проводить посвячуваних Орди крізь випробування, потрібні, щоб спілкуватися з мінливою стихією вогню й керувати нею.",h="Телф Джулам — троль-шаман із джунглів, із племені Темного Списа, що наглядає за Святинею Приспаного Полум'я.",kw={"телф джулам","шаман","троль","святиня приспаного полум'я","вогняний тотем","вогняна сапта","вогонь"},ang={["class:Shaman"]="Телф Джулам — ключова постать на вашому духовному шляху: він проведе вас крізь випробування Вогняної Сапти, щоб ви опанували свій Вогняний Тотем.",["faction:Horde"]="Оберігаючи священні стихійні святині по всьому порубіжжю, старійшини на кшталт Телфа зміцнюють духовний хребет нової Орди.",["race:Troll"]="Старійшина-хранитель із Темного Списа, що веде посвячуваних, показує, як глибоко троляча духовність сплелася з шаманським відродженням Орди."},sec={{t="Хранитель полум'я",b="Серед скель над порубіжжям Телф Джулам доглядає Святиню Приспаного Полум'я. На відміну від спокійної певності землі чи терплячої глибини води, духи вогню вимагають гострої дисципліни й непохитної зосередженості. Телф виступає розпорядником випробувань: він готує молодих шаманів довести свою гідність диким жаринам, перш ніж ті їх поглинуть."},{t="Шлях вогню",b="Під проводом Телфа посвячувані варять і п'ють обрядову Вогняну Сапту, що дарує смертним очам зір у незримі стихійні світи. Він посилає прохачів на скелясті вершини — просто до палаючих духів, — дбаючи, щоб кожен шаман, який здобуде полум'я, ніс у собі повагу до його ненаситного голоду, а не безоглядну гордість."}},faq={{q="Хто такий Телф Джулам?",a="Телф Джулам — троль-шаман Темного Спису, хранитель Святині Приспаного Полум'я. Він наставляє молодих шаманів, що прагнуть спілкуватися з вогнем.",al={"хто такий телф","телф джулам","троль святилища сплячого полум'я"}},{q="Де знайти Телфа Джулама?",a="Він живе біля Святині Приспаного Полум'я, високо на скелястому хребті між Дуротаром і Пустками.",al={"місце телфа джулама","де телф","як знайти телфа джулама"}},{q="Навіщо потрібна Вогняна Сапта, яку він просить?",a="Вогняна Сапта — особливо зварений напій, що відкриває послушникові духовний зір і дозволяє бачити духів вогню та говорити з ними, хоча для смертних чуттів вони інакше невидимі.",al={"що таке вогняна сапта","використання вогняної сапти","навіщо пити сапту"}},{q="Якої стихії навчає Телф Джулам?",a="Він спеціалізується на стихії вогню й випробовує шаманів, щоб переконатися, що їм вистачає сили й волі керувати полум'ям, не ставши жертвою його руйнівної природи.",al={"яку стихію навчає телф","стихія телфа джулама","чолов'яга вогняного тотема"}},{q="Чому обряди шаманів тут проводить троль?",a="Відколи тролі Темного Спису приєдналися до Орди Тралла, багато з них прийняли духовний шлях шаманства поруч з орками й тауренами, а досвідчені шамани на кшталт Телфа наставляють нове покоління.",al={"чому троль-шаман","шаманізм темних списів"}},{q="Що стається після виконання завдань Телфа Джулама?",a="Довівши свою владу над духами полум'я на сусідній вершині, послушники здобувають знання й благословення, потрібні, щоб створити свій постійний Вогняний Тотем.",al={"нагорода поклик вогню","що дає телф"}}},fp="11,212,19.360.0,16.337.0,19.152.0,31.114.0,50.198.0,36.166.0,46.198.0,50.154.0"}
P.entries["npc:tenaron-stormgrip"] = {n="Тенарон Стормґріп",s="Тенарон Стормґріп — провідник, нічний ельф, що перебуває високо в Алдрассилі, центральному дереві Тінедолу. Він навчає молодих калдореїв недавньої історії їхнього народу й просить їх набрати води з місячного колодязя.",h="Тенарон Стормґріп — провідник, нічний ельф, що перебуває високо в Алдрассилі, центральному дереві Тінедолу.",kw={"тенарон стормґріп","алдрассил","тінедол","корона землі","місячний колодязь","гора гіджал","дарнасус"},ang={["class:Druid"]="Доручення Тенарона підкреслюють друїдську опіку, потрібну, щоб стежити за небаченим зростанням Тельдрассила й стерегтися прихованої скверни.",["race:NightElf"]="Для молодих нічних ельфів Тенарон Стормґріп — одне з найперших знайомств із громадськими й духовними обов'язками, потрібними, щоб Тельдрассил лишався живим і чистим."},sec={{t="Сторож Алдрассила",b="Умостившись на звивистих дерев'яних помостах Алдрассила, Тенарон Стормґріп — ранній наставник молодих нічних ельфів, що виходять із віття Тінедолу. Зі свого спостережного місця він стежить за здоров'ям тутешніх лісів і життєво важливих місячних колодязів, що їх живлять. Його роль — навчати новачків розуміти їхній глибокий духовний зв'язок зі Світовим Деревом."},{t="Корона Землі",b="Тенарон розпочинає подорож, відому як Корона Землі. Він посилає посвячених набрати фіалу води з місячного колодязя на північ від Алдрассила й розповідає їм, що сталося після Битви за Гору Гіджал. Подорож триває через Тельдрассил і далі, до Дарнасуса."}},faq={{q="Де перебуває Тенарон Стормґріп?",a="Тенарон Стормґріп стоїть на дерев'яних пандусах Алдрассила — величезного центрального дерева в самому серці Тінедолу на Тельдрассилі.",al={"місце тенарона","де тенарон","точка тенарона стормґріпа"}},{q="Яка роль Тенарона Стормґріпа в Тінедолі?",a="Він наставляє молодих нічних ельфів, розповідаючи про наслідки битви за Гору Гіджал у мандрівці «Корона Землі».",al={"що робить тенарон","мета тенарона стормґріпа","хто такий тенарон"}},{q="Що за завдання «Корона Землі»?",a="Тенарон просить послушників набрати у фіал води з місячного колодязя й принести йому. Ця мандрівка знайомить із недавньою історією нічних ельфів і триває по всьому Тельдрассилу.",al={"лор корони землі","навіщо нести воду місячного колодязя"}},{q="Чому Тенарона непокоять води Тельдрассила?",a="Місячні колодязі — важливі вмістилища благодаті Елуни й природної чистоти. Оскільки Тельдрассил молодий і не має повного благословення Аспектів, доглядачі на кшталт Тенарона пильно стежать за кожним джерелом води, чи немає там ознак скверни чи зараження.",al={"чому дорогоцінні води","проблеми води тельдрассила"}},{q="Чи посилає Тенарон шукачів пригод за межі Тінедолу?",a="Так. Щойно послушник виявить шану й уміння поводитися зі священними водами, Тенарон посилає його далі, у широкий Тельдрассил, — униз до Доланаара, щоб і далі служити калдореям.",al={"наступне завдання тенарона","куди тенарон посилає"}},{q="Тенарон — друїд чи жрець?",a="Його клас у джерелах не встановлено. Він розповідає про недавню історію нічних ельфів і пояснює значення місячних колодязів.",al={"чи тенарон друїд","клас тенарона стормґріпа"}}},fp="17,198,20.379.0,18.255.0,35.137.0,47.123.0,37.171.0,51.237.0,48.208.0,31.124.0"}
P.entries["npc:terenthis"] = {n="Терентіс",s="Терентіс — друїд нічних ельфів, що несе службу в приморському поселенні Обердайн. Представник Кола Кенарія, він розслідує тривожну скверну, що шириться Темним Узбережжям і Тельдрассилом. Він залучає здібних мандрівників, щоб оцінити загрози на узбережжі й допомогти місцевим союзникам, яких оточили осквернені звірі.",h="Терентіс — друїд нічних ельфів, що несе службу в приморському поселенні Обердайн.",kw={"терентіс","друїд","коло кенарія","мох скверни","волкор","обердайн"},ang={["class:Druid"]="Як брат із Кола Кенарія, Терентіс стоїть на передовій боротьби з неприродною скверною, що перекидається з Тельдрассилу на материк.",["race:NightElf"]="Терентіс утілює відданість калдореїв справі очищення своїх священних земель від залишків скверни й захисту невинного лісового життя."},sec={{t="Розслідування скверни",b="Терентіс, якого Коло Кенарія прислало до Обердайна, стежить за поширенням Моху Скверни та інших згубних сил, що просочуються з Тельдрассилу на Темне Узбережжя. Нічні ельфи з великою тривогою дивляться на цю повзучу пошесть, боячись, що дика рівновага північного Калімдору може цілком розвалитися, якщо її не стримати. Терентіс намагається з'ясувати першопричини гниття й знайти спосіб зупинити його, перш ніж воно поглине ліси."},{t="Благання Похмурого кігтя",b="Терентіс також допомагає в нагальних випадках на місцях. Коли вірний ведмідь Похмурий кіготь прибуває до Обердайна пораненим і самотнім, Терентіс розуміє, що господар звіра, друїд Волкор, потрапив у тяжку біду. Не маючи змоги покинути пост, Терентіс посилає мандрівних шукачів пригод у нетрі на пошуки Волкора, якого підстерегли й оточили агресивні племена фурболгів."}},faq={{q="Хто такий Терентіс?",a="Терентіс — нічний ельф, друїд Кола Кенарія, що нині живе в портовому містечку Обердайн на Темному Узбережжі.",al={"лор терентіса","хто такий терентіс","терентіс оберін"}},{q="Чому Терентіс в Обердайні?",a="Його відрядили з'ясувати, наскільки широко Мох Скверни й магічна скверна поширилися з Тельдрассила на Темне Узбережжя, і знайти спосіб покласти край цій пошесті.",al={"що робить терентіс","мета терентіса","чому терентіс тут"}},{q="Що робить ведмідь поруч із Терентісом?",a="Ведмідь, Похмурий кіготь, прийшов шукати допомоги в Терентіса в Обердайні після того, як на його господаря, друїда Волкора, напали ворожі фурболги й поранили його.",al={"ведмідь терентіса","ґримклоу","чому в оберіні ведмідь"}},{q="До якої спільноти належить Терентіс?",a="Терентіс — член Кола Кенарія, друїдського ордену, що присвятив себе збереженню рівноваги й захисту природи по всьому Калімдору.",al={"фракція терентіса","чи терентіс коло ценарія"}},{q="Які загрози найбільше турбують Терентіса?",a="Насамперед його турбує скверна Моху Скверни, що вражає тварин краю, а також дедалі більша ворожість місцевих племен фурболгів, які загрожують і мандрівникам, і друїдам.",al={"скверна темного узбережжя","загроза скверного моху","турботи терентіса"}},{q="Чи дає Терентіс завдання шукачам пригод?",a="Так. Він посилає шукачів пригод оцінити загрози скверни на узбережжі, зв'язатися з іншими друїдами на кшталт Тундріса Віндвівера й урятувати Волкора.",al={"завдання терентіса","чого хоче терентіс"}}},fp="9,326,23.437.0,20.412.1,17.132.0,30.162.0,46.144.0,43.136.0,46.181.0,46.160.0"}
P.entries["npc:teronis-corpse"] = {n="Труп Тероніса",s="Труп Тероніса лежить на відлюдному острові посеред Озера Фалатім у західному Ашенвалі. До передчасної смерті цього розвідника нічних ельфів послали з Астранаару з важливим дорученням — знайти Жезл Дартола, щоб допомогти очистити ліс.",h="Труп Тероніса лежить на відлюдному острові посеред Озера Фалатім у західному Ашенвалі.",kw={"труп тероніса","тероніс","озеро фалатім","жезл дартола","мурлоки","астранаар"},ang={["faction:Alliance"]="Ушанувати жертву розвідників Астранаару — означає довести до кінця їхню незавершену справу й очистити землю від порчі, що нависла над нею.",["race:NightElf"]="Знайти Тероніса загиблим у глушині — тверезе нагадування про те, яким небезпечним став Ашенваль навіть для досвідчених вартових і розвідників."},sec={{t="Похмура доля розвідника",b="Рейн Вульфраннер відрядила Тероніса з поселення Астранаар, доручивши йому знайти втрачений жезл Дартола — прадавню реліквію нічних ельфів, здатну очищати зіпсовану лісову магію. Пошуки завели його далеко на води Озера Фалатім, але мандрівка обернулася смертю, коли острів обсіли ворожі мурлоки. Тероніс поліг у бою: його щоденник лишився лежати поряд, а сяйливий самоцвіт жезла забрали агресивні земноводні мешканці озера."}},faq={{q="Хто такий Тероніс?",a="Тероніс — нічний ельф-розвідник, якого послала з Астранаару Вартова Рейн Вульфраннер. Йому доручили роздобути Жезл Дартола — давній артефакт, потрібний, щоб очистити ґрунт і води Ашенвалю від демонічної скверни, що в них просочилася.",al={"хто такий тероніс","лор тероніса","особа тероніса"}},{q="Як загинув Тероніс?",a="Тероніса підстерегли й убили люті мурлоки, що кишать на берегах і у водах Озера Фалатім, коли він намагався роздобути частини жезла.",al={"хто вбив тероніса","причина смерті тероніса","як він загинув"}},{q="Де його загублений самоцвіт?",a="Після смерті Тероніса сяйливий самоцвіт, що вінчав Жезл Дартола, забрали місцеві мурлоки, які живуть довкола Озера Фалатім.",al={"де загублений самоцвіт","загублений самоцвіт","самоцвіт тероніса"}},{q="Чому завершити його місію так важливо для Астранаару?",a="Тварини й лісові водойми Ашенвалю дедалі тяжче потерпають від мерзенної демонічної скверни. Жезл Дартола має вроджену очисну магію, і Вартові сподіваються, що вона поверне назад чи хоча б стримає це невпинне гниття.",al={"чому допомагати рейн","призначення жезла дартола"}}},fp="15,240,19.458.0,16.221.0,20.156.0,27.138.0,56.212.0"}
P.entries["npc:thadius-grimshade"] = {n="Тадіус Ґрімшейд",s="Тадіус Ґрімшейд — дворф-віщун із Вайлдгаммерів, що живе в магічній вежі Замку Незерґард у Спустошених Землях. Хоча колись давно він покинув Орлиний Пік, щоб вивчати езотеричні й темніші магічні мистецтва, у серці він лишається відданим своєму народові.",h="Тадіус Ґрімшейд — дворф-віщун із Вайлдгаммерів, що живе в магічній вежі Замку Незерґард у Спустошених Землях.",kw={"тадіус","вайлдгаммери","незерґард","віщування","гостродзьоб","грифони","спустошені землі"},ang={["class:Mage"]="Маги, що відвідують Незерґард, упізнають у Тадіусі знавця рідкісних езотеричних методів віщування, готового вивчати тролівські реліквії, щоб опанувати магію довголіття.",["race:Dwarf"]="Для дворфів Тадіус — дивак серед Вайлдгаммерів: замість літати на грифонах він роками сидить над таємними студіями в людській фортеці."},sec={{t="Вайлдгаммер серед пустирів",b="На відміну від більшості дворфів-Вайлдгаммерів, які віддають перевагу відкритому небу й буйним вітрам Пригір'я, Тадіус Ґрімшейд облаштував собі дім у Замку Незерґард. Жадоба таємного віщування й темних містичних знань привела його на край осквернених Спустошених Земель, де він провадить свої езотеричні студії. Попри похмуру самодисципліну й відірваність від клану, він зберіг глибоку прихильність до батьківщини й до грифонів і пропонує свій рідкісний дар провидіння тим, хто приходить по допомогу від імені Орлиного Піку."},{t="Ціна віщування",b="Коли Майстер Грифонів Талонекс намагається розшукати полоненого грифона Гостродзьоба, Тадіуса просять провести ритуал віщування з одним із пер звіра. Та магічне прозріння має свою ціну: Тадіус вимагає медальйон, який носить троль-некромант Некрум Ґатчуер. Прагнучи розкрити таємницю його неприродного довголіття й уникнути його згубної скверни, він бере артефакт в обмін на те, що прозирне крізь завісу Джинта'Алора й покаже, де тримають Гостродзьоба."}},faq={{q="Хто такий Тадіус Ґрімшейд?",a="Це ексцентричний дворф із Вайлдгаммерів, маг і віщун, що служить у Замку Незерґард. Він покинув рідні гори, щоб займатися темнішими, нетрадиційними магічними мистецтвами далеко на півдні.",al={"тадіус ґрімшейд","хто такий тадіус","тадіус нпс"}},{q="Де знайти Тадіуса Ґрімшейда?",a="Він живе у високій чарівній вежі Замку Незерґард — твердині Альянсу на півночі Спустошених Земель.",al={"місце тадіуса","де тадіус ґрімшейд","тадіус спустошені землі"}},{q="Навіщо йому Медальйон Некрума?",a="Тадіус хоче дослідити медальйон, який носить Некрум Ґатчуер, щоб розгадати, як його магічна сила дає довге життя, і сподівається здобути це довголіття, не піддавшись його зловісним побічним діям.",al={"медальйон некрума тадіус","навіщо тадіусу медальйон","медальйон некрума гутчювера"}},{q="Як він допомагає знайти Гостродзьоба?",a="Узявши перо, що загубив зниклий грифон, і силу, яку живить Медальйон Некрума, Тадіус проводить ритуал споглядання й з'ясовує, що Гостродзьоба тримають у полоні на висотах Джинта'Алора в Пригір'ї.",al={"тадіус гостродзьоб","ворожіння гостродзьоба","завдання пошуку гостродзьоба"}}},fp="17,248,26.515.0,23.495.1,25.169.0,37.138.0,36.197.0,32.205.1"}
P.entries["npc:thalia-amberhide"] = {n="Талія Амбергайд",s="Талія Амбергайд — тауренка, що мешкає на Заставі Вільного Вітру серед зубчастих каньйонів Тисячі Голок. Вірна подруга своїх родичів, вона з дедалі більшою тривогою чекає, коли Лакоту Віндсонг безпечно визволять із лап клану Ґрімтотем.",h="Талія Амбергайд — тауренка, що мешкає на Заставі Вільного Вітру серед зубчастих каньйонів Тисячі Голок.",kw={"талія амбергайд","лакота віндсонг","арнак ґрімтотем","застава вільного вітру","ґрімтотем","порятунок"},ang={["faction:Horde"]="Застава Вільного Вітру — важливий перевалочний пункт Орди в Тисячі Голок, і допомога Талії Амбергайд захищає поселення від агресії Ґрімтотемів.",["race:Tauren"]="Для мандрівників-тауренів допомога Талії й порятунок Лакоти — прямий удар по зловісній підступності племені Ґрімтотем і захист родичів від міжкланових чвар."},sec={{t="Подруга на заставі",b="На високих кручах Застави Вільного Вітру Талія Амбергайд — тиха постать серед гамірного тауренського поселення. Її серце обтяжене тривогою за близьку подругу Лакоту Віндсонг, яку взяли в полон Арнак Ґрімтотем і його підступні родичі. Талія покладається на мандрівних шукачів пригод з Орди, які наважаться спуститися в глибини каньйону, знайти Лакоту, розірвати її пута й безпечно провести назад підйомниками до прихистку на столовій горі."}},faq={{q="Хто така Талія Амбергайд?",a="Талія Амбергайд — тауренка, що живе на Заставі Вільного Вітру в Тисячі Голок. Вона вірна подруга Лакоти Віндсонг — іншої тауренки, що потрапила в халепу з підступним кланом Ґрімтотем.",al={"талія амбергайд","хто така талія"}},{q="Де знайти Талію Амбергайд?",a="Вона на високому плато Застави Вільного Вітру посеред Тисячі Голок. Щоб дістатися поселення, мандрівникам треба піднятися з дна каньйону величезними дерев'яними підйомниками.",al={"місце талії","де талія амбергайд"}},{q="Що пов'язує Талію з Лакотою Віндсонг?",a="Талія — близька подруга Лакоти Віндсонг. Коли Лакоту захоплює Арнак Ґрімтотем, саме Талія радо зустрічає на Заставі Вільного Вітру шукача пригод, який допоміг Лакоті втекти від викрадачів.",al={"талія й лакота","хто така лакота віндсонг"}}},fp="16,235,20.432.0,24.183.0,36.193.0,47.209.0"}
P.entries["npc:tharek-blackstone"] = {n="Тарек Блекстоун",s="Тарек Блекстоун — працьовитий майстер інструментів, що мешкає в Хараносі, в засніженому серці Дун Мороґу. Відомий тим, що постачає важке знаряддя місцевим ремісникам, головним своїм замовником він має Белдіна Стілґрілла зі Складу Стілґрила. Хоч він і постійно зайнятий ремеслом, він також надійна людина, до якої звертаються мандрівники, що шукають роботи довкола поселення.",h="Тарек Блекстоун — працьовитий майстер інструментів, що мешкає в Хараносі, в засніженому серці Дун Мороґу.",kw={"тарек блекстоун","майстер інструментів","коваль","харанос","белдін стілґрілл","склад стілґрила","інструменти"},ang={["profession:Blacksmithing"]="Для ковалів, що проходять через Харанос, Тарек — зразок щоденної праці робочого майстра інструментів, який штампує зносостійкі гайкові ключі й залізне кріплення, щоб дворфійська техніка не стояла.",["race:Dwarf"]="Тарек утілює міцний, самодостатній дух робочого люду Дун Мороґу, що тримає місцеву промисловість на ходу суцільною наполегливістю біля ковадла."},sec={{t="Заклопотаний майстер інструментів у Хараносі",b="Серед холодних заметів Хараноса Тарек Блекстоун без упину виготовляє надійне дворфійське знаряддя. Між ремонтом спорядження для місцевих і постачанням більших підприємств йому рідко випадає мить перепочинку. Його найбільший головний біль — і найнадійніший замовник — Белдін Стілґрілл, чий склад механоступів просто за містечком вимагає сталого потоку важких гайкових ключів, шестерень і змінного знаряддя. Щоб кузня працювала й доставки не затримувалися, Тарек часто наймає мандрівників переносити щойно готові ящики з інструментами на склад."},{t="Громадський діяч",b="Окрім ремесла біля ковадла, Тарек тішиться чималою повагою серед люду Дун Мороґу. Хоч він не має офіційного військового звання, його становище в містечку робить його доступним посередником для дрібних доручень, постачання й координації місцевих зусиль."}},faq={{q="Хто такий Тарек Блекстоун?",a="Тарек Блекстоун — дворф-інструментар із містечка Харанос у Дун Мороґу. Він виготовляє й лагодить важкий інструмент для місцевих робітників і часто наймає мандрівних шукачів пригод розвозити припаси по долині.",al={"тарек блекстоун","хто такий тарек","блекстоун дун мороґ"}},{q="Що пов'язує його з Белдіном Стілґріллом?",a="Белдін Стілґрілл тримає Склад Стілґрила трохи на схід від Хараноса, де лагодять механоступів і облогові машини. Белдін — головний замовник Тарека й замовляє стільки залізних виробів, що Тарекові часто доводиться покладатися на шукачів пригод, щоб доставити готові партії на склад.",al={"тарек і белдін","інструменти стілґрилла","чому белдін"}},{q="Де знайти Тарека Блекстоуна?",a="Він стоїть надворі неподалік від центру Хараноса в Дун Мороґу, за кілька кроків від місцевої корчми й кузні.",al={"місце тарека","де тарек блекстоун","координати тарека блекстоуна"}},{q="Чи має Тарек якесь офіційне звання в Айронфорджі?",a="Ні військового звання, ні політичної посади він не має. Це заклопотаний, перевантажений роботою інструментар, що наймає новачків, яким потрібні гроші, щоб ті розносили його припаси.",al={"чи тарек лідер","влада тарека","звання блекстоуна"}}},fp="17,351,28.576.0,18.251.0,25.221.0,48.273.0,35.132.0,48.150.0"}
P.entries["npc:tharnariun-treetender"] = {n="Тарнаріун Трітендер",s="Тарнаріун Трітендер — натураліст із нічних ельфів, що живе в прибережному поселенні Обердайн на Темному Узбережжі. Відданий збереженню крихкої рівноваги дикої природи, він стежить за повзучою порчею, що вражає рослини й тварин краю. Мандрівники, що проходять через порт, часто чують, як він закликає союзників лікувати хворих звірів і рятувати природу від подальшого занепаду.",h="Тарнаріун Трітендер — натураліст із нічних ельфів, що живе в прибережному поселенні Обердайн на Темному...",kw={"тарнаріун трітендер","обердайн","натураліст","порча","звірі","темне узбережжя"},ang={["class:Druid"]="Друїди побачать, що турбота Тарнаріуна про уражених звірів тісно збігається з їхньою священною місією — повертати гармонію спотвореним землям.",["faction:Alliance"]="Обердайн — головні прибережні ворота Альянсу на півночі Калімдору, тож Тарнаріунів захист навколишніх лісів украй важливий для безпеки застави.",["race:NightElf"]="Для калдореїв пересторога Тарнаріуна глибоко перегукується з їхнім давнім обов'язком стерегти рівновагу природи на півночі Калімдору."},sec={{t="Охоронець в Обердайні",b="Портове містечко Обердайн, що примостилося на скелястому березі Темного Узбережжя, потерпає від загроз на кількох фронтах — від ворожих сатирів до мерзенних стоків, що виносить на берег. Тарнаріун Трітендер зосереджує зусилля саме на природі, що оточує селище. Твердо вірячи, що занедбана природа кличе лихо, він спостерігає за занепадом місцевих лісів і шукає способів відкинути хворобу, що шириться лісовою підстилкою."},{t="Зцілення уражених",b="Чимало звірів Темного Узбережжя стали жертвами дивних моровиць і пошестей порчі, що доводять істот до божевілля й обертають мирних тварин на скажену загрозу. Тарнаріун не хоче просто вбивати їх зі страху — він шукає ліки. Ретельно приготованими очищувальними засобами й цілеспрямованими зусиллями знищити найгірші осередки зарази він намагається врятувати те, що лишилося від дикої природи, доки ліс остаточно не зотлів."}},faq={{q="Хто такий Тарнаріун Трітендер?",a="Тарнаріун — нічний ельф, доглядач природи в Обердайні на узбережжі Темного Узбережжя. Він присвятив життя тому, щоб пильнувати ліс і з'ясовувати причини неприродних недуг, що вражають місцевих тварин.",al={"хто такий тарнаріун","лор тарнаріуна","тарнаріун трітендер"}},{q="Де знайти Тарнаріуна Трітендера?",a="Він у прибережному селищі нічних ельфів Обердайн, на західному краю нетрів Темного Узбережжя.",al={"де тарнаріун","місце тарнаріуна трітендера","карта тарнаріуна"}},{q="Які негаразди розслідує Тарнаріун на Темному Узбережжі?",a="Він розслідує скверну й мерзенні пошесті, що ширяться землею й вражають тварин, і посилає шукачів пригод очищати заражених звірів і зупиняти пошесть.",al={"чого хоче тарнаріун","мета тарнаріуна","чому допомагати тарнаріуну"}},{q="Чому Тарнаріун так переймається хворими тваринами?",a="Як захисник дикої природи, Тарнаріун вірить, що нічні ельфи не можуть нехтувати природою без наслідків. Він прагне зцілити хворих створінь, а не кинути ліс на поталу скверні.",al={"чому рятувати звірів","завдання тарнаріуна про тварин"}},{q="Які завдання дає Тарнаріун Трітендер?",a="Він проводить шукачів пригод через завдання про спаплюжені землі й тварин, зокрема «Чумні землі», «Очищення заражених» і «Надія Тарнаріуна».",al={"завдання тарнаріуна","завдання трітендера"}},{q="Чи Тарнаріун друїд?",a="Джерела прямо не називають його друїдом. Хоча він поділяє переконання Кола Кенарія щодо збереження звірів і рослин, насамперед він відданий доглядач і опікун дерев у нетрях Темного Узбережжя.",al={"чи тарнаріун друїд","клас тарнаріуна"}}},fp="21,382,23.443.0,21.436.1,29.209.0,39.118.0,55.166.0,56.211.0,45.158.0,22.249.0"}
P.entries["npc:the-defias-traitor"] = {n="Зрадник Дефіасу",s="Зрадник Дефіасу — схоплений розбійник, якого тримають біля підніжжя сторожової вежі Сентінел Гілла у Вестфолі. Спійманий на гарячому Народним ополченням, він виказав таємне розташування штабу Братства, щоб урятувати власну шию.",h="Зрадник Дефіасу — схоплений розбійник, якого тримають біля підніжжя сторожової вежі Сентінел Гілла у Вестфолі.",kw={"зрадник дефіасу","братство дефіас","мунбрук","сентінел гілл","ґраян стаутмантл","вестфол"},ang={["class:Rogue"]="Гірке нагадування про крихку вірність у злочинних угрупованнях: загнані законом у кут, злодії й кишенькові крадії рідко вагаються, перш ніж продати своїх.",["faction:Alliance"]="Для Народного ополчення й місцевих захисників цей полонений — довгоочікуваний перелом у боротьбі з розбійниками, що тероризують Вестфол."},sec={{t="Угода заради життя",b="Не кожен член Братства Дефіас фанатично відданий справі Едвіна Венкліфа. Коли цього дрібного злодюжку спіймали на спробі вкрасти віз у Фермера Салдіна, ополченці Ґраяна Стаутмантла взяли його з поличним. Опинившись перед шибеницею, злодій вибрав власну шкуру, а не братство, і виказав точне розташування їхньої схованої бази в обмін на своє життя."},{t="Шлях до Мунбрука",b="Під охороною біля сторожової вежі Сентінел Гілла перебіжчик має просте, але небезпечне завдання: провести героїв Альянсу ворожою землею просто до схованого входу під зруйнованим містечком Мунбрук. Хоч колишні спільники його ненавидять, а ті, хто його схопив, зневажають, його зрада дає Народному ополченню прорив, потрібний, щоб ударити в саме серце Братства."}},faq={{q="Хто такий Зрадник Дефіасу?",a="Це колишній член Братства Дефіас, якого Народне ополчення схопило, коли він намагався вкрасти віз у Фермера Салдіна. Щоб уникнути страти, він погодився відвести союзників Ополчення до таємного лігва Братства.",al={"хто цей чолов'яга","особа зрадника дефіас","хто зрадник біля сентінел гілла"}},{q="Чому він стоїть біля вежі в Сентінел Гіллі?",a="Його тримають під вартою Ґраян Стаутмантл і Народне ополчення просто біля своєї твердині. Він стоїть там під озброєною охороною, доки не знайдуться добровольці, щоб провести його до схованки Дефіас.",al={"місце зрадника","чому він біля вежі","де зрадник"}},{q="Куди він веде?",a="Він веде мандрівників на південний захід рівнинами Вестфолу до занедбаного містечка Мунбрук і показує прихований вхід до Схованки Дефіасу.",al={"куди веде зрадник","кінцева точка супроводу зрадника","де сховище дефіас"}},{q="Чому він обернувся проти Братства Дефіас?",a="Із простого інстинкту самозбереження. Спійманий на крадіжці у Фермера Салдіна й опинившись перед стратою, він виміняв найбільшу таємницю Братства Дефіас на власне життя.",al={"чому він зрадив дефіас","мотив зрадника","чому він переметнувся"}}},fp="18,230,22.396.0,28.392.1,26.219.0,54.201.0,23.155.0,47.174.0"}
P.entries["npc:theldurin-the-lost"] = {n="Телдурін Загублений",s="Телдурін Загублений — відлюдькуватий напівбожевільний дворф, що блукає випаленими просторами Пустищ. Колись він служив підступному культу Молота Присмерку, але, усвідомивши жах його задумів, утік із його лав, прихопивши священні реліквії.",h="Телдурін Загублений — відлюдькуватий напівбожевільний дворф, що блукає випаленими просторами Пустищ.",kw={"телдурін","молот присмерку","мізраель","культ","пустища","дворф","сувій"},ang={["profession:Engineering"]="Телдурін погрожує незнайомцям торбою, напханою вибуховим порохом, і виявляє непередбачувану прихильність до нестабільної вибухівки.",["race:Dwarf"]="Сумно бачити, як побратим з Айронфорджа скотився до шаленої параної посеред пустирів, та його відмова схилитися перед темними культами показує незламну дворфську впертість."},sec={{t="Розум, надламаний темрявою",b="Телдурін, що засів серед безплідних пагорбів Пустищ і в шаленій параної стискає мішки з вибухівкою, — далеко не просто божевільний відлюдник. Колись він був послушником культу Молота Присмерку. Коли зловісне братство задумало пробудити первісну стихійну силу, ув'язнену під землею, Телдурін відсахнувся в жаху, зрікся їхніх божевільних учень і втік у пустелю. Він забрав із собою Сувій Мізраель, відчайдушно прагнучи не дати колишнім господарям випустити в світ прадавній жах. Хоча втеча коштувала йому здорового глузду, його непокора завдала серйозного удару планам культу."},{t="Відчайдушний контрудар",b="Вижити в пустирях виявилося гірко. Розлючені земляні елементалі напали на Телдуріна із засідки й пошматували викрадений сувій, розкидавши уривки по пилюці. Тепер, охоплений параноєю й переслідуваний видіннями неминучої загибелі, що дрімає під поверхнею, божевільний дворф шукає прадавні тексти — Скрижаль Рюн'е та Збірник Ягіна, — сподіваючись розкрити давно поховані знання. Щоб культ не звільнив принцесу елементалів Мізраель у розпалі її люті, Телдурін задумує викликати її передчасно — тоді її можна буде здолати й знову ув'язнити."}},faq={{q="Хто такий Телдурін Загублений?",a="Телдурін — божевільний дворф-відлюдник, що ховається в Пустищах. Колись він належав до культу Молота Присмерку, але викрав їхні ритуальні таємниці й утік у нетрі, щоб не дати їм вивільнити небезпечну силу.",al={"хто такий телдурін","лор телдуріна","божевільний дворф пустищ"}},{q="Чому Телдурін ховається в Пустищах?",a="Він тікає від Молота Присмерку. Викравши в культу Сувій Мізраель, він сховався у віддалених, випалених сонцем каньйонах Пустищ, щоб випереджати культистів, які на нього полюють.",al={"чому телдурін у пустищах","чому телдурін ховається","телдурін пустища"}},{q="Що таке Сувій Мізраель?",a="Це магічний пергамент із ритуальними знаннями, потрібними, щоб вивільнити Мізраель — стародавню зіпсовану сутність стихій, ув'язнену глибоко під Аратійським нагір'ям. Телдурін викрав його, щоб Молот Присмерку не зміг завершити виклик, хоча згодом місцеві елементалі пошматували документ на клапті.",al={"сувій мізраель","який сувій украв телдурін"}},{q="Що Телдурін хоче зробити з Мізраель?",a="Знаючи, що пута цієї істоти слабшають, Телдурін прагне викликати Мізраель передчасно, поки вона не набралася повної сили. Виманивши її ослабленою, шукачі пригод можуть вигнати її й знову запечатати під земною корою, перш ніж Молот Присмерку опанує її силу.",al={"план телдуріна","навіщо викликати мізраель","виклик принцеси"}}},fp="18,249,28.604.0,26.568.1,26.217.0,40.208.0,30.296.1,44.274.1"}
P.entries["npc:theocritus"] = {n="Теокрітус",s="Архімаг Теокрітус — дивакуватий чародій з людей, що живе на вершині Вежі Азори на сході Лісу Елвінн. Колись пов'язаний із Кірін-Тором Даларану, нині він живе незалежно, в оточенні слуг і магічних пристроїв для прозирання. Зі свого високого святилища Теокрітус спрямовує свої таємні таланти на нагляд за королівством і боротьбу зі своїм темним суперником — магом-відступником Морґантом.",h="Архімаг Теокрітус — дивакуватий чародій з людей, що живе на вершині Вежі Азори на сході Лісу Елвінн.",kw={"теокрітус","архімаг","вежа азори","морґант","кірін-тор","прозирання","ліс елвінн"},ang={["class:Mage"]="Теокрітус утілює життя чародія поза суворою ієрархією Даларану, показуючи, як самотні майстри облаштовують святилища й провадять прозирання на відстані.",["faction:Alliance"]="Хоч і дивакуватий та відсторонений, Теокрітус використовує своє таємне бачення й ресурси, щоб діяльно боронити східний Елвінн і Редрідж від чаклунів-відступників.",["race:Human"]="Протистояння Теокрітуса й Морґанта віддзеркалює два шляхи людського чаклунства: дисципліновану науку на захисті проти скверніння й темних амбіцій."},sec={{t="Господар вежі",b="Колись член престижного Кірін-Тору Даларану, Архімаг Теокрітус вирішив заснувати незалежну твердиню далеко на півдні, у королівстві Стормвінд. Він оселився у примітній Вежі Азори біля східної дороги на Редрідж. Теокрітус відомий дивацькими звичками та вигідним способом життя: він тримає численну челядь, зокрема багатьох слуг-гномів і власного кравця Морлі Еберлейна. Хоч він і тримається осторонь буденних клопотів місцевих селян, його присутність — важливий магічний щит східного Елвінну."},{t="Війна з Морґантом",b="Найбільший постійний клопіт Теокрітуса — занепалий маг Морґант, небезпечний чорнокнижник, що діє з Вежі Ілґалара в сусідніх Горах Редріджу. Вбачаючи в Морґанті і особистого ворога, і серйозну загрозу Стормвінду, Теокрітус присвятив місяці таємних досліджень, щоб його підірвати. За допомогою артефактів прозирання на кшталт Ока Азори Теокрітус стежить за діями лиходія і проникає в його думки. Він також працює над тим, щоб обернути творіння Морґанта проти нього самого: вивчає магічні підвіски гнолів Тіньової Шкури, сподіваючись передати таємний імпульс, здатний знерухомити всю зграю."}},faq={{q="Хто такий Теокрітус?",a="Архімаг Теокрітус — колишній чарівник Кірін-Тору, що живе у Вежі Азори на сході Лісу Елвінн. Він веде ексцентричне, доволі відлюдне життя й спрямовує свою тайну майстерність на захист краю від темних магічних загроз.",al={"лор теокрітуса","хто маг у вежі","маг вежі азори"}},{q="Чому Теокрітус покинув Даларан?",a="Колись він працював у Кірін-Торі поруч із колегами на кшталт Архімага Карлейна, але вирішив стати незалежним чарівником. Він перебрався до Лісу Елвінн, щоб займатися власними дослідженнями й тримати своє особисте святилище у Вежі Азори.",al={"чи теокрітус кірін тор","чому теокрітус в елвінні","теокрітус даларан"}},{q="З ким воює Теокрітус?",a="Його головний суперник — Морґант, занепалий людина-маг, що вдався до темної магії у Вежі Ілґалара за кордоном, у Редріджі. Теокрітус бачить у Морґанті і нахабного особистого ворога, і грізну загрозу безпеці Стормвінда.",al={"ворог теокрітуса","хто такий морґант","суперник теокрітуса"}},{q="Що таке Око Азори?",a="Око Азори — могутній пристрій для споглядання, який Теокрітус створив і тримає на вершині своєї вежі. Він магічно зазирає ним у далекі землі, стежить за загрозами й навіть намагається читати думки свого суперника, Морґанта.",al={"лор ока азори","як теокрітус шпигує","кришталева куля теокрітуса"}},{q="Навіщо Теокрітусу кулони гнолів Тіньової Шкури?",a="Гноли Тіньової Шкури служать Морґантові й носять зачаровані кулони, пов'язані з їхнім господарем. Теокрітус вивчає ці дрібнички, щоб зрозуміти, як працює їхній магічний зв'язок, сподіваючись пустити цією мережею тайний удар і паралізувати гнолів у бою.",al={"кулони гнолів теокрітус","поновлення теокрітуса","навіщо збирати кулони гнолів"}},{q="Хто служить Теокрітусу в його вежі?",a="Теокрітуса оточує незвичайне господарство: цілий почет слуг-гномів, що дбають про його щоденні справи, і особистий кравець на ім'я Морлі Еберлейн, що доглядає його гардероб.",al={"персонал вежі азори","хто живе у вежі азори","слуги теокрітуса"}}},fp="10,405,19.606.0,24.626.0,18.242.0,33.251.0,35.236.0,25.225.0,51.253.0,35.213.0"}
P.entries["npc:therylune"] = {n="Терілун",s="Терілун — дріада, яку тримають у полоні біля Глефи Володаря на півдні Темного Узбережжя. Її схопили підступні сектанти Молота Присмерку, що захопили це прадавнє місце, і вона сподівається, що відважні мандрівники допоможуть їй вирватися з їхніх лап.",h="Терілун — дріада, яку тримають у полоні біля Глефи Володаря на півдні Темного Узбережжя.",kw={"терілун","дріада","молот присмерку","глефа володаря","темне узбережжя","супровід"},ang={["class:Druid"]="Як охоронці природи, близькі до Кенарія та його роду, друїди відчувають пряму спорідненість і нагальний обов'язок урятувати дріаду, яку схопили зловмисні сектанти.",["race:NightElf"]="Нічних ельфів пов'язують із доньками Кенарія священні прадавні узи, тож полон Терілун у руках Молота Присмерку — образа для рівноваги Калімдору."},sec={{t="Полонянка культу",b="Дріади — охоронниці природи й доньки Кенарія, що зазвичай блукають тихими лісами північного Калімдору. Та Терілун підійшла надто близько до зловісних розкопок біля Глефи Володаря на півдні Темного Узбережжя, де зібралися сектанти Молота Присмерку. Темний культ узяв її в засідку й полон, і вона не може сама прорватися крізь юрми сектантів — їй потрібен супровід, щоб утекти в безпечне місце."}},faq={{q="Хто така Терілун?",a="Терілун — дріада, одна з лісових дочок напівбога Кенарія. Її схопили культисти Молота Присмерку, що діють біля Глефи Володаря на півдні Темного Узбережжя.",al={"хто така терілун","лор терілун","що таке терілун"}},{q="Чому Терілун у пастці біля Глефи Володаря?",a="На Терілун напали з засідки й притиснули культисти Молота Присмерку, які облаштували свій темний табір довкола велетенських скам'янілих решток біля Глефи Володаря.",al={"чому вона в пастці","як терілун потрапила в полон","глефа майстра культисти"}},{q="Чи має Терілун родину?",a="Так, Терілун — сестра Терісіль, іншої дріади, що живе в лісах північного Калімдору.",al={"сестра терілун","терісіль терілун","родина терілун"}},{q="Що стається, коли допомагаєш їй утекти?",a="Коли шукачі пригод прокладають шлях крізь ворожих культистів, Терілун успішно тікає від Глефи Володаря й повертається до безпечних довколишніх нетрів.",al={"втеча терілун","завдання втечі терілун","що робить терілун"}}},fp="9,254,19.430.0,17.184.0,48.164.0,31.105.0,38.160.1"}
P.entries["npc:therysil"] = {n="Терісіль",s="Терісіль — дріада, що живе біля Святилища Аессіни в центральному Ашенвалі. Глибоко віддана збереженню природи, вона з тривогою чекає звісток про свою сестру Терілун, яка потрапила до рук зловісних сектантів.",h="Терісіль — дріада, що живе біля Святилища Аессіни в центральному Ашенвалі.",kw={"терісіль","дріада","святилище аессіни","терілун","молот присмерку","ашенваль"},ang={["class:Druid"]="Як донька Кенарія, Терісіль уособлює глибокий зв'язок між Колом Кенарія та духами природи Ашенвалю, тож її біда особливо зачіпає друїдів, які сюди приходять.",["race:NightElf"]="Дріади здавна були вірними союзницями калдореїв в обороні священних гаїв Ашенвалю, як-от Святилища Аессіни."},sec={{t="Чування охоронниці",b="Терісіль живе біля тихих вод Святилища Аессіни — священної галявини в прадавніх лісах Ашенвалю. Як і всі дріади, доньки Кенарія, вона присвячена захистові дикої природи й духів, що в ній живуть. Та замість тихої опіки над лісом її тепер гризе тривога. Її сестру Терілун схопив неподалік божевільний культ Молота Присмерку, і Терісіль у відчаї шукає бодай якогось мандрівного союзника, готового допомогти врятувати сестру."}},faq={{q="Хто така Терісіль?",a="Терісіль — дріада, що живе біля Святилища Аессіни в Ашенвалі. Вона донька Кенарія й сестра Терілун.",al={"хто така терісіль","лор терісіль","дріада в есіні"}},{q="Що турбує Терісіль?",a="Її сестру, Терілун, підстерегли й узяли в полон культисти Молота Присмерку біля Глефи Володаря на півдні Темного Узбережжя. Терісіль чекає біля святилища, сподіваючись, що якийсь шукач пригод безпечно проведе сестру додому.",al={"що робить терісіль","чому терісіль стурбована","завдання терісіль"}},{q="Хто така Терілун?",a="Терілун — сестра Терісіль, ще одна дріада Ашенвалю. Її схопив Молот Присмерку, і їй потрібен супровід, щоб вирватися з їхніх лап і возз'єднатися з Терісіль.",al={"терілун","сестра терісіль","хто така терілун"}},{q="Де знайти Терісіль?",a="Терісіль стоїть біля Святилища Аессіни — священного природного прихистку при дорозі в центрі Ашенвалю.",al={"місце терісіль","де терісіль","дріада святилища есіни"}}},fp="8,222,18.489.0,16.132.0,27.217.0,17.176.0,28.112.0"}
P.entries["npc:thor"] = {n="Тор",s="Тор — майстер польотів, що доглядає гніздо грифонів у Сентінел Гіллі у Вестфолі. Як життєво важлива повітряна ланка між знесиленим Народним ополченням і столицею, Стормвіндом, він відправляє гінців, розвідників і термінові послання королівськими небесами.",h="Тор — майстер польотів, що доглядає гніздо грифонів у Сентінел Гіллі у Вестфолі.",kw={"тор","майстер польотів","грифон","сентінел гілл","народне ополчення","вестфол"},ang={["faction:Alliance"]="Для героїв Альянсу, які допомагають Народному ополченню, Тор пропонує найшвидший шлях до столиці — щоб доставити польові донесення й поповнити припаси."},sec={{t="Гніздо Сентінел Гілла",b="Тор, що служить у гнізді грифонів Сентінел Гілла, керує пташником, який пов'язує захисників прикордоння Вестфолу із серцем королівства. Поки Народне ополчення на землі б'ється з мандрівними розбійниками, гнолами й несправними жнивними големами, Тор дбає, щоб важливі військові донесення й мандрівники могли взагалі оминути небезпечні шляхи. Завдяки його приборканим грифонам термінові прохання про допомогу й донесення Ґраяна Стаутмантла дістаються двору в Стормвінді значно швидше, ніж це вдалося б будь-якому пішому гінцеві."}},faq={{q="Хто такий Тор?",a="Тор — людина, наглядач грифонів у Сентінел Гіллі у Вестфолі. Він доглядає навчених грифонів, на яких перелітають між Вестфолом та іншими поселеннями Альянсу, насамперед Стормвіндом.",al={"хто цей чолов'яга","майстер польотів сентінел гілл","тор нпс"}},{q="Яку роль він відіграє у Вестфолі?",a="Він — повітряна рятівна нитка Сентінел Гілла. Тор організовує гінців, що переносять важливі військові донесення між Народним ополченням і верховним командуванням у Стормвінді, щоб командири були в курсі справ, попри Дефіас на дорогах.",al={"що робить тор","мета тора"}},{q="Чому польоти на грифонах тут такі важливі?",a="Дороги, що пов'язують Вестфол із Лісом Елвінн і Сутінколіссям, кишать розбійниками Дефіас, гнолами Річколапів і небезпечними звірами. Польоти на грифонах — безпечний і швидкий обхід, що зберігає лінії постачання й зв'язку.",al={"чому польоти на ґрифонах важливі","шлях польоту вестфолу"}}},fp="4,283,26.531.0,12.202.0,35.254.0,37.230.0"}
P.entries["npc:thorgas-grimson"] = {n="Торґас Ґрімсон",s="Торґас Ґрімсон — дворф, наставник мисливців, що служить в Анвілмарі в Долині Холодного Хребта. Загартований слідопит Дун Мороґу, він твердо вірить, що практичне виживання в крижаних пустищах — найкращий учитель для будь-якого стрільця-початківця.",h="Торґас Ґрімсон — дворф, наставник мисливців, що служить в Анвілмарі в Долині Холодного Хребта.",kw={"торґас ґрімсон","мисливець","наставник","анвілмар","долина холодного хребта","вистежування","виживання"},ang={["class:Hunter"]="Для дворфійських стрільців Торґас Ґрімсон часто найперший наставник, якого ви зустрічаєте: він дає ранні настанови з вистежування звірів і виживання в крижаній долині.",["race:Dwarf"]="Ґрімсон утілює витривалий, самодостатній дух горян Айронфорджа, які патрулюють замерзлі вершини Дун Мороґу."},sec={{t="Провідник на холоді",b="У кам'яних залах Анвілмара Торґас Ґрімсон вітає горян і розвідників-новачків, що роблять найперші кроки в суворих заметах Долини Холодного Хребта. Замість обтяжувати молодих мисливців сухими лекціями, Ґрімсон сповідує практичну філософію: справжня майстерність кується на крижаному вітрі, з луком чи рушницею в руці, вистежуючи суворих звірів Дун Мороґу на власні очі."}},faq={{q="Хто такий Торґас Ґрімсон?",a="Торґас Ґрімсон — дворф, наставник мисливців в Анвілмарі, головній заставі Долини Холодного Хребта в Дун Мороґу. Він дає перші поради й основні польові навички новим мисливцям Альянсу, що починають свої пригоди.",al={"хто такий торґас","торґас ґрімсон","тренер мисливців ковадлограда"}},{q="Чого навчає Торґас?",a="Він навчає мисливців-новачків основних прийомів виживання в дикій природі — вистежувати диких звірів на засніженій землі й відточувати основи стрільби, — ставлячи їх на шлях справжніх горян.",al={"чого навчає торґас","навички мисливця ковадлоград"}},{q="Як він дивиться на навчання?",a="Торґас переконаний, що теоретичні вправи — ніщо проти живого досвіду. Він вірить, що єдиний спосіб по-справжньому опанувати дику природу — вийти в морозні замети й зустрітися зі звірами Дун Мороґу віч-на-віч.",al={"характер торґаса","як торґас навчає"}},{q="Чи говоритиме Торґас Ґрімсон із тими, хто не мисливець?",a="Хоч і досить чемно, Торґас відверто скаже шукачам пригод іншого покликання, що не може допомогти їм у навчанні, і порадить пошукати наставника, який пасує до обраного ними шляху.",al={"чи торґас говоритиме з не мисливцями","плітки торґаса"}}},fp="15,256,19.390.0,23.226.0,33.214.0,32.213.0,44.195.0"}
P.entries["npc:thorgrum-borrelson"] = {n="Торґрум Боррелсон",s="Торґрум Боррелсон — дворфійський майстер грифонів, що працює над Телсамаром у Лох Модані. Зі свого сідала над поселенням він доглядає летючих верхових тварин, які з'єднують долину з Айронфорджем і навколишніми гірськими перевалами.",h="Торґрум Боррелсон — дворфійський майстер грифонів, що працює над Телсамаром у Лох Модані.",kw={"торґрум боррелсон","майстер грифонів","телсамар","лох модан","грифони","перельоти"},ang={["faction:Alliance"]="Сідало Торґрума — важливий вузол постачання, що з'єднує серце дворфійського королівства з передовими позиціями в Багнокраї та Аратійському нагір'ї.",["race:Dwarf"]="Для горян і оборонців Каз Модану Торґрум Боррелсон — надійна повітряна ниточка, що веде назад до високих залів Айронфорджа."},sec={{t="Сідало над Телсамаром",b="Торґрум Боррелсон, чиє сідало стоїть на кручі просто над Телсамаром, відповідає за повітряні перевезення Альянсу в Лох Модані. Наземні шляхи загрожують навали трогів і зграї гнолів, тож його навчені грифони — життєво важливий спосіб перелетіти через гострі кряжі. Він підтримує постійне сполучення через Прохід Південної Брами з Великою Кузнею в Дун Мороґу, а також шляхи далі, до Багнокраю й за його межі."}},faq={{q="Хто такий Торґрум Боррелсон?",a="Торґрум Боррелсон — наглядач грифонів Альянсу в Телсамарі. Він відає польотами до краю Лох Модан і з нього.",al={"торґрум","майстер польотів телсамара","хто майстер ґрифонів телсамара"}},{q="Куди Торґрум може відправити мандрівників?",a="Торґрум керує маршрутами, що пов'язують Телсамар із великими осередками — дворфійською столицею Айронфордж, Гаванню Менетіл у Багнокраї, Притулком в Аратійському нагір'ї — та кількома заставами в сусідніх землях.",al={"маршрути телсамара","куди можна летіти з лох модану"}},{q="Чому польоти на грифонах важливі в Лох Модані?",a="Подорож суходолом Лох Моданом часто небезпечна через ворожі нори трогів, гнолів і розвідників Темного Заліза, що змагаються за гірські перевали. Грифони дозволяють посланцям, розвідникам і шукачам пригод Альянсу швидко оминати ці небезпеки.",al={"чому польоти важливі в лох модані","транспорт лох модану"}}},fp="18,233,25.427.0,26.145.0,34.241.0,46.236.0"}
P.entries["npc:thork"] = {n="Торк",kw={"торк","перехрестя","оборона","орк","кадрак","пустки"},ang={["class:Warrior"]="Воїни оцінять практичний, прямий підхід Торка: стратегічні шляхи постачання, надійні патрулі й знищення загроз, перш ніж ті прорвуться за стіни.",["faction:Horde"]="Для шукачів пригод з Орди, що прибувають із Дуротара чи Малгору, служба в Торка — важливий крок до слави захисника Калімдору.",["race:Orc"]="Торк утілює непохитний військовий обов'язок, якого чекають від орків, що боронять нещодавно завойовані землі Калімдору від нездоланної ворожості краю."},sec={{t="Командир Перехрестя",b="Перехрестя — серце сполучення Орди на Калімдорі, що з'єднує Дуротар, Малгор і дикі землі за ними. Утримати його непросто. Торк несе відповідальність за оборону містечка від постійного зовнішнього тиску. Між набігами шипогривів, нападами кентаврів і розбоєм гарпій його сили розпорошені, тож він змушений покладатися на здібних мандрівників і молодих героїв у найважливіших справах безпеки."},{t="Захист кордонів",b="Обов'язки Торка сягають далеко за стіни самого Перехрестя. Він організовує оборону вздовж важливих шляхів постачання, посилаючи розвідників і зв'язкових на північ, до Валу Мор'шан, із донесеннями просто до Кадрака. Тримати відкритими ці північні й східні артерії конче потрібно, щоб Орда втрималася в суворих і безжальних чагарниках Пусток."},{t="Загрози ззовні й зсередини",b="Thork also rewards adventurers who uncover the leadership behind the Razormane raids. The captive quilboar Mangletooth betrays his own tribe by helping travelers strike against its leaders. When they bring Lok Orcbane's head to the Crossroads, Thork thanks them for weakening the attacks on Horde supply lines."}},faq={{q="Хто такий Торк?",a="Торк — орк-офіцер, що відповідає за військову оборону Перехрестя в Пустках. Він дбає про безпеку поселення, організовує відплату ворожим племенам і стежить, щоб каравани з припасами безпечно діставалися місця призначення.",al={"лор торка","хто такий торк","торк перехрестя"}},{q="Де перебуває Торк?",a="Він стоїть надворі неподалік від центру поселення Перехрестя в Пустках, керує вартовими й віддає накази щодо оборони.",al={"місце торка","знайти торка","де стоїть торк"}},{q="Чому Перехрестя таке вразливе до нападів?",a="Перехрестя стоїть на відкритому перетині головних торгових шляхів Пусток. Оскільки воно не має міцних кам'яних укріплень і межує із землями ворожих шипогривів-Гостроманів, кентаврів Колкар і розвідників Альянсу, його доводиться боронити, не втрачаючи пильності ні на мить.",al={"чому перехрестя вразливе","напади на перехрестя"}},{q="Які в Торка стосунки з Манкріком?",a="Коли Манкрік благав про військову допомогу, щоб вистежити шипогривів і знайти свою зниклу дружину, Торк відмовив: з обмеженими силами він мусить насамперед берегти заставу та її каравани з припасами.",al={"манкрік і торк","чи торк допоміг манкріку"}},{q="Як Торк підтримує зв'язок з іншими заставами Орди?",a="Торк постійно підтримує зв'язок із північним кордоном, посилаючи гінців і бійців доповідати Кадракові на Валу Мор'шан, що стежить за межею з Ашенвалем.",al={"торк і кадрак","торк вал мор'шан"}},{q="З якими загрозами має справу Торк?",a="Thork deals with marauding quillboar warbands disrupting trade and stealing supply crates. He also rewards adventurers who defeat the leaders behind these raids.",al={"вороги перехрестя","завдання торка"}}},fp="5,240,27.440.0,20.379.0,22.310.1,13.223.0,23.141.0,46.272.0,42.219.0,49.180.0,34.161.0"}
P.entries["npc:thorvald-deepforge"] = {n="Торвальд Діпфордж",s="Торвальд Діпфордж — дворфійський торговець зброєю, що стоїть біля прикордонного перевалу в Долині Королів. Він допомагає озброювати мандрівників і захисників, які стережуть важливий шлях між Дун Мороґом і Лох Моданом.",h="Торвальд Діпфордж — дворфійський торговець зброєю, що стоїть біля прикордонного перевалу в Долині Королів.",kw={"торвальд діпфордж","торговець зброєю","долина королів","лох модан","дун мороґ","зброя","перевал"},ang={["profession:Blacksmithing"]="Носячи уславлене родове ім'я Діпфордж, Торвальд торгує практичними, надійними залізними виробами, якими славляться дворфійські ковалі.",["race:Dwarf"]="Стоячи під моноліти предків у Долині Королів, Торвальд утілює незмінне ремесло й лінію постачання, що тримають кордони Каз Модану в безпеці."},sec={{t="Озброюючи східний перевал",b="Серед величних монументів Долини Королів Торвальд Діпфордж служить Альянсу як надійний торговець зброєю. Гірські перевали, що з'єднують серце Каз Модану з околишніми землями, потерпають від набігів трогів і блукаючої звірини, тож добре викувана сталь конче потрібна кожному горянину чи новобранцю в дорозі. Торвальд дбає, щоб ті, хто прибуває з Дун Мороґу чи прямує вглиб Лох Модану, мали клинки й сокири, потрібні для захисту дворфійських земель."}},faq={{q="Хто такий Торвальд Діпфордж?",a="Торвальд Діпфордж — дворф-торговець у Долині Королів, де дорога веде з Дун Мороґу до Лох Модану. Він постачає найпотрібнішу зброю мандрівникам і захисникам на кордоні.",al={"хто такий торвальд","торвальд діпфордж нпс","діпфордж лох модан"}},{q="Яку роль він відіграє в обороні краю?",a="Він передовий інтендант і торговець зброєю для мандрівників, що долають гірські перевали, і допомагає озброювати новобранців, яких посилають підсилити застави в Лох Модані.",al={"що робить торвальд","мета торвальда","постачання фронту"}},{q="Чи він родич інших Діпфорджів у Каз Модані?",a="Можливо. Кілька дворфів носять ім'я Діпфордж, зокрема Мурґот і Бенґус Діпфордж, але родинного зв'язку не підтверджено. Тормус Діпфордж із Великої Кузні називає Торвальда своїм колегою.",al={"рід діпфордж","родичі торвальда діпфорджа","мурґот діпфордж родич"}}},fp="18,204,23.487.0,26.202.0,47.175.0,52.195.0"}
P.entries["npc:thotar"] = {n="Тотар",s="Тотар — бувалий орк, наставник мисливців у поселенні Гострий Пагорб у Дуротарі. Він навчає майбутніх розвідників і стрільців Орди прадавніх традицій вистежування, стрільби з лука та єднання з дикими звірами. Молодим оркам і тролям, що роблять перші кроки за межами Долини Випробувань, він дає основоположні обряди, потрібні, щоб опанувати сувору звірину Калімдору.",h="Тотар — бувалий орк, наставник мисливців у поселенні Гострий Пагорб у Дуротарі.",kw={"тотар","мисливець","наставник","орк","гострий пагорб","приборкання звірів","дуротар"},ang={["class:Hunter"]="Тотар — важлива віха для молодих мисливців Орди: він навчає життєво важливих обрядів приборкання звірів і володіння дикою природою, щойно новачки виходять зі стартових долин.",["faction:Horde"]="Як передовий наставник на Гострому Пагорбі, Тотар дбає, щоб розвідники й стрільці, які патрулюють кордони Дуротару, були дисциплінованими, пильними й міцно зрідненими з бойовими звірами.",["race:Orc"]="Тотар зберігає й передає традиційні орківські мисливські звичаї, щоб життя на Калімдорі й далі трималося на глибокій прадавній повазі до вистежування та звірів-супутників.",["race:Troll"]="Для мисливців Темного Списа, що вирушають із Села Сен'джин, Тотар дає важливі настанови, поєднуючи прадавні навички виживання Орди з хижими викликами Дуротару."},sec={{t="Наставник на Гострому Пагорбі",b="В укріпленому осередку Гострого Пагорба Тотар служить бувалим наставником для стрільців Орди. Поки новобранці опановують найперші основи в Долині Випробувань, саме Тотарові випадає вести мисливців, коли ті зустрічають суворішу хижу глушину Дуротару. Спираючись на традиції, передані крізь незліченні покоління орків, він навчає не лише влучності, а й глибшої поваги, потрібної, щоб жити поруч із найсмертоноснішими створіннями Калімдору й керувати ними."},{t="Приборкання дикої природи",b="Тотар відіграє вирішальну роль у залученні молодих мисливців до прадавнього мистецтва приборкання звірів. Через низку випробувань він посилає новачків у посушливі каньйони, щоб угамувати тутешніх звірів і порозумітися з ними — отруйних скорпідів, панцирних прибійних повзунів і хитрих вепрів. Проводячи цих молодих розвідників крізь священні обряди приборкання, Тотар дбає, щоб слідопити Орди будували з природою вірний зв'язок, а не просто намагалися підкорити її силою."}},faq={{q="Хто такий Тотар?",a="Тотар — бувалий орк, наставник мисливців на Гострому Пагорбі в Дуротарі. Він навчає молодих мисливців традиційних знань про дику природу, стрільби й приручення тварин.",al={"хто такий тотар","лор тотара","що робить тотар"}},{q="Де знайти Тотара?",a="Він у поселенні Орди Гострий Пагорб, у центрі Дуротару, трохи на північ від Долини Випробувань.",al={"місце тотара","де тотар","знайти тотара"}},{q="Яких традицій навчає Тотар?",a="Тотар навчає давніх традицій виживання й вистежування, які орки передають із покоління в покоління. Він наголошує на майстерності володіння зброєю, виживанні в дикій природі й умінні здружитися зі звірами-супутниками через терпіння й обряд.",al={"чого навчає тотар","традиції мисливців","навчання тотара"}},{q="Чи Тотар навчає лише орків?",a="Хоч він і орк, глибоко вкорінений у звичаї свого народу, Тотар навчає кожного мисливця Орди, що прибуде на Гострий Пагорб, і постійно наставляє тролів Темного Спису й мандрівних тауренів, які проходять через Дуротар.",al={"чи тотар навчає лише орків","тролі навчаються в тотара","кого навчає тотар"}},{q="Які завдання Тотар дає молодим мисливцям?",a="Тотар проводить мисливців-новачків через обряди «Приборкання звіра», доручаючи їм вистежити місцевих тварин Дуротару — вепрів, прибійних повзунів і скорпідів — і жезлом приручення здобути їхню довіру й послух.",al={"завдання тотара","приборкання звіра тотар","куди тотар посилає"}},{q="Чому приручення звірів таке важливе в його навчанні?",a="Для мисливців Орди звір-супутник — незамінний товариш і на полі бою, і в диких краях. Тотар навчає, що справжня дружба зі звіром забезпечує виживання обом і перетворює дикого хижака на вірного захисника Орди.",al={"чому приручення звірів важливе","лор улюбленців мисливця","мета приборкання звірів"}}},fp="6,374,22.474.0,16.459.0,14.165.0,26.116.0,34.224.0,28.209.0,45.226.0,49.228.0"}
P.entries["npc:thrall"] = {n="Тралл",s="Тралл — Вождь Орди й володар Дуротару, що править із Долини Мудрості в Оргріммарі. Колись раб людей, вихований для гладіаторських боїв на арені, він розбив кайдани свого народу, заново відкрив його давні шаманські традиції й повів його через Велике Море, щоб збудувати нову батьківщину.",h="Тралл — Вождь Орди й володар Дуротару, що править із Долини Мудрості в Оргріммарі.",kw={"тралл","вождь","орда","оргріммар","шаман","дуротар","орки"},ang={["class:Shaman"]="Тралла шанують як першого орочого шамана нового покоління: після десятиліть демонічної скверни він відновив священне єднання свого народу зі стихійними духами.",["faction:Alliance"]="Провідники Альянсу вважають Тралла небезпечним, але прагматичним вождем, чия дисциплінована Орда значно краща за кровожерних завойовників Першої та Другої воєн.",["faction:Horde"]="Тралл — ваш верховний командувач і Вождь: він вивів Орду з рабства й руїни, щоб вибороти почесне майбутнє в Калімдорі.",["race:Orc"]="Для орків Тралл — живий рятівник, що вирвав їх із млявості людських таборів і повернув народові його давню честь."},sec={{t="Від раба до шамана",b="Народжений як Ґо'ел, син вождя клану Морозного Вовка Дуротана й Драки, Тралл осиротів ще немовлям, коли вбивці Ґул'дана вбили його батьків. Його знайшов людський командувач Еделас Блекмур, який назвав його Траллом, що означає «раб», і виховав у Твердині Дурнгольд як бійця арени, навчивши людської тактики. З допомогою названої сестри Тарети Фокстон Тралл зрештою втік від своїх кривдників. Під проводом вигнанця з клану Морозного Вовка Дрек'Тара він відкинув демонічну скверну, опанував стихійних духів і став першим із нового покоління орочих шаманів."},{t="Мантія Вождя",b="Тралл об'єднав сили з легендарним Оргрімом Думхаммером, щоб визволити млявих орків, які животіли в таборах інтернування Альянсу після Другої війни. Коли Думхаммер поліг у бою, він передав Траллові свої чорні лати й могутній бойовий молот і проголосив його новим Вождем. Ідучи за пророчими видіннями таємничого Пророка Медіва, Тралл повів свій народ: орки захопили людські кораблі й попливли через Велике Море до забутого континенту Калімдор, рятуючись від лиха, що впало на Східні Королівства."},{t="Кування Нової Орди",b="У Калімдорі Тралл перетворив Орду з машини війни на союз виживання й честі. Він урятував тролів Темного Списа на чолі з Вол'джином і уклав союз із тауренами Кайрна Бладгуфа, а потім разом із людьми й нічними ельфами повів об'єднані сили, щоб здолати Палаючий Легіон на вершині Гори Гіджал. Згодом Тралл заснував державу Дуротар і її столицю Оргріммар, назвавши їх на честь свого батька й наставника. Він підтримує хиткий мир із Терамором Джайни Праудмур, а водночас мусить поєднувати оборону своєї крихкої держави із суперечливими союзами — як-от прийняття Відступників Лордерона до Орди."}},faq={{q="Хто такий Тралл?",a="Тралл — Вождь Орди й провідник орківського народу. Народжений як Ґо'ел із клану Морозного Вовка, він виріс у людей рабом-гладіатором, а потім вирвався на волю, опанував шаманське мистецтво й повів орків до Калімдору, де вони заснували свою нову столицю — Оргріммар.",al={"хто вождь","минуле тралла","хто такий тралл"}},{q="Звідки походить ім'я Тралл?",a="Його справжнє ім'я — Ґо'ел, яке дали йому батьки, Дуротан і Драка. Його людський господар, Еделас Блекмур, назвав його «Траллом» — давнім людським словом, що означає «раб». Тралл зберіг це ім'я як нагадування про те, звідки він прийшов, і про гніт, якого його народ присягнув більше ніколи не терпіти.",al={"чому його звуть тралл","що означає тралл","справжнє ім'я тралла"}},{q="Чому Тралл носить чорні обладунки й молот?",a="Тралл носить чорні латні обладунки й володіє Думхаммером, які передав йому Оргрім Думхаммер, колишній Вождь. Смертельно поранений під час визволення таборів для інтернованих, Оргрім з останнім подихом передав Траллові і зброю, і мантію Вождя.",al={"думхаммер","зброя тралла","чорна броня"}},{q="Де знайти Тралла в грі?",a="Тралл перебуває в Долині Мудрості в Оргріммарі — столиці Орди в Дуротарі. Він стоїть у Фортеці Ґроммаш разом зі своїми охоронцями й радниками.",al={"де тралл","місце тралла","кімната тралла"}},{q="Які в Тралла стосунки з Джайною Праудмур?",a="Тралл і Леді Джайна Праудмур здобули взаємну повагу й уклали угоду про співпрацю, разом воюючи в Третю війну біля Гори Гіджал. Хоча їхні фракції досі глибоко не довіряють одна одній, обоє очільників прагнуть зберегти хиткий мир між Оргріммаром і Терамором.",al={"тралл і джайна","альянс джайни","мир із терамором"}},{q="Чому Тралл прийняв Відступників до Орди?",a="Хоча Тралл обережно ставиться до нежиті, він визнав відчайдушне становище Відступників Сильвани Віндраннер, які звільнилися з-під влади Короля-Ліча. Завдяки дипломатичним умовлянням тауренів, що вірять у можливість спокути для Відступників, Тралл прийняв їх до Орди, здобувши стратегічний плацдарм у Східних Королівствах.",al={"чому тралл прийняв відступників","союз відступників","вступ сильвани до орди"}}},fp="6,309,20.582.0,26.515.0,21.637.0,14.279.0,35.276.0,52.288.0,36.165.0,52.297.0,49.333.0"}
P.entries["npc:thran-khorman"] = {n="Тран Корман",s="Тран Корман — дворфійський наставник воїнів, що служить в Анвілмарі, у засніженій Долині Холодного Хребта. Він наглядає за базовою бойовою муштрою новоспечених воїнів, що виходять у Дун Мороґ.",h="Тран Корман — дворфійський наставник воїнів, що служить в Анвілмарі, у засніженій Долині Холодного Хребта.",kw={"тран корман","воїн","наставник","анвілмар","долина холодного хребта","муштра","вишкіл"},ang={["class:Warrior"]="Для дворфійських і гномських воїнів, що прокидаються біля Перевалу Холодного Кряжа, Тран — найперший майстер, який перевірить вашу витримку, вручить ваші початкові руни чи накази й навчить основ бойового виживання.",["race:Dwarf"]="Тран уособлює вперту, непохитну рішучість захисників Айронфорджа, що зберігають готовність навіть у мирний час, щоб королівство ніколи не було захоплене зненацька."},sec={{t="Муштрувальник Долини Холодного Хребта",b="Біля навчального майданчика Анвілмара Тран Корман має завдання перетворювати сирих дворфійських новобранців і гномів-гостей на дисциплінованих бійців. До кожного, кому бракує твердості для бою на передовій, він ставиться грубо й безкомпромісно. У його очах, хоч Третя війна й скінчилася, мир — лише ілюзія: троги наступають на Перевал Холодного Кряжа, а гори повні небезпек. Він вимагає невпинної практики з сокирою, булавою й щитом, щоб захисники Айронфорджа ніколи не притупилися."}},faq={{q="Хто такий Тран Корман?",a="Тран Корман — дворф, наставник воїнів в Анвілмарі в Дун Мороґу. Він дає перші бойові поради й науку воїнам-новачкам, що починають свій шлях у Долині Холодного Хребта.",al={"хто такий тран","роль трана кормана","тренер воїнів ковадлограда"}},{q="Чого він навчає?",a="Він навчає воїнів-новачків основ бойової дисципліни, допомагаючи їм відточити стійки, прийоми ближнього бою й бойовий гарт, перш ніж вони вирушать битися з трогами й дикими звірами на перевалі.",al={"чого навчає тран","навички воїна трана"}},{q="Чому він зневажливий чи різкий із деякими мандрівниками?",a="Тран живе й дихає бойовим мистецтвом і не має терпцю до тих, хто обрав тайну магію, тіні чи інші тонкі мистецтва. Якщо ви не воїн, він прямо скаже, що ви й дня не протримаєтеся під час його тренувань.",al={"чому тран грубий","плітки трана","текст трана для не воїнів"}}},fp="13,213,31.528.0,21.197.0,28.221.0,51.239.0"}
P.entries["npc:thunderaan"] = {n="Тандераан",s="Принц Тандераан — прадавній Принц Повітря, велетенський елементаль, якого зрадили й повалили в давніх війнах між вогнем і вітром. Рагнарос, Володар вогню, частково поглинув його, а рештки його сутності запечатав у розтрощених путах і довірив їх своїм поплічникам. Шукачі пригод, які відвоюють ці реліквії, можуть знайти Верховного Лорда Демітріана в Силітусі й знову вивільнити принца.",h="Принц Тандераан — прадавній Принц Повітря, велетенський елементаль, якого зрадили й повалили в давніх війнах...",kw={"тандераан","принц повітря","громолють","рагнарос","розплавлене ядро","елементаль"},ang={["class:Rogue"]="Розбійники, яким до смаку неперевершена швидкість і блискавичний бій, жадають полеглої сутності Принца Повітря, ув'язненої в славетному клинку Громолють.",["class:Shaman"]="Як духовні опікуни стихій, шамани вбачають у Тандераанові одне з найчистіших і найлютіших утілень повітря й блискавки в Азероті.",["class:Warrior"]="Воїни прагнуть легендарного меча Громолють — клинка, сповненого сили бурі й пов'язаного з Принцом Повітря."},sec={{t="Розкол Стихій",b="Колись давно, під час Розколу Стихій — п'ятитисячолітнього протистояння сил вогню й повітря глибоко в надрах Азероту, — Рагнарос прагнув знищити й поглинути Тандераана. Могутні поплічники Рагнароса, Барон Геддон і Ґарр, підстерегли й зрадили принца, а тоді Володар вогню повалив його своїм молотом Сульфурасом. Проте навіть переможений Тандераан мав надто могутню сутність, щоб Рагнарос зміг увібрати її цілком."},{t="Розбитий талісман",b="Не здужавши цілком поглинути Принца Повітря, Рагнарос запечатав рештки сутності Тандераана в талісмані стихійних пут. Щоб принц ніколи не відродився, Володар вогню розколов талісман на дві бездоганні половини. Одну він довірив Баронові Геддону, другу — Ґаррові, і заховав обидві у вулканічних глибинах Розплавленого Ядра під Горою Блекрок."},{t="Відродження в Силітусі",b="Ті, хто наважиться вдертися в Розплавлене Ядро, можуть вирвати обидві половини пут у поплічників Рагнароса. Коли ці уламки віддають Верховному Лордові Демітріану — дивакуватому відлюдникові, пов'язаному з Молотом Присмерку, що живе серед посушливих дюн Силітусу, — він розпочинає обряд, щоб явити Принца Повітря. Та новонароджений елементаль постає не з вдячністю, а в шаленій вихровій люті, тож закликачі мусять повалити його, щоб здобути легендарний клинок — Громолють, Благословенний Клинок Шукача Вітру."}},faq={{q="Хто такий Тандераан?",a="Тандераан — Принц Повітря, шляхетний і нищівний володар стихій, пов'язаний із вітром. Давним-давно його здолав Рагнарос, Володар Вогню, і замкнув у в'язниці стихій.",al={"хто такий принц тандераан","принц повітря","лор тандераана"}},{q="Як Тандераана здолали спочатку?",a="Під час Розколу Стихій Рагнарос змовився зі своїми поплічниками Бароном Геддоном і Ґарром, щоб зрадити Принца. Тандераана розтрощив Сульфурас, і хоча Рагнарос пожер його сутність, перетравити її цілком не зміг, тож мусив замкнути рештки в розщепленому талісмані.",al={"як здолали тандераана","раґнарос проти тандераана","розкол стихій"}},{q="Де зберігаються частини його пут?",a="Дві бездоганні половини пут Тандераана тримають Ґарр і Барон Геддон глибоко в Розплавленому Ядрі під Горою Блекрок.",al={"де частини пут","пута шукача вітрів","пута ґарра й геддона"}},{q="Чому до цього причетний Верховний Лорд Демітріан у Силітусі?",a="Верховний Лорд Демітріан — послідовник Молота Присмерку, що живе в Силітусі й має тайні знання та знання стихій, потрібні, щоб відновити розбитий талісман і викликати Принца Повітря до Азероту.",al={"хто такий демітріан","верховний лорд демітріан тандераан","як викликати тандераана"}},{q="Що стається, коли Тандераана викликають у Силітусі?",a="Демітріан може провести небезпечний ритуал за допомогою здобутих пут. Що з'явиться, стане відомо, коли ритуал буде завершено.",al={"бій з тандерааном","що буде після виклику"}},{q="Яка зброя пов'язана з Тандерааном?",a="Громолють, Благословенний Клинок Шукача Вітру, — легендарний меч, пов'язаний із Принцом Повітря. Його доля розкривається через ритуал Демітріана.",al={"громолють","меч шукач вітрів","меч тандераана"}}},fp="10,386,23.429.0,22.398.0,19.488.1,18.188.0,39.286.0,41.136.0,47.216.0,53.127.1,34.145.1"}
P.entries["npc:thyn-tel-bladeweaver"] = {n="Тин'тел Блейдвівер",s="Тин'тел Блейдвівер — вартова нічних ельфів, що несе службу на Терасі Воїна в Дарнасусі. Її глибоко непокоїть зникнення жриці Велінде Старсонг, тож вона посилає надійних шукачів пригод з Альянсу шукати її сліди. Своїми розпитуваннями вона намагається розплутати таємницю Коси Елуни.",h="Тин'тел Блейдвівер — вартова нічних ельфів, що несе службу на Терасі Воїна в Дарнасусі.",kw={"тин'тел блейдвівер","вартова","дарнасус","тераса воїна","велінде старсонг","коса елуни"},ang={["class:Warrior"]="Тин'тел стоїть просто серед наставників на Терасі Воїна, тож її обличчя добре знайоме воїнам Альянсу, що бувають у Дарнасусі.",["faction:Alliance"]="Героям Альянсу, які завітають на Терасу Воїна, Тин'тел доручає вирушити вглиб нейтральних і спірних земель, щоб дізнатися правду.",["race:NightElf"]="Для нічних ельфів доручення Тин'тел зачіпає за живе: воно відкриває приховану трагедію шанованої жриці, що стала жертвою сил, яким не могла протистояти."},sec={{t="Розслідування вартової",b="Тин'тел Блейдвівер, що з Тераси Воїна пильнує Дарнасус, представляє військову силу калдореїв. Коли жриця Велінде Старсонг таємниче зникла, не лишивши жодної звістки, Тин'тел не дала сліду охолонути. Відчуваючи, що тут замішані грізні сили, вона сама взялася наймати шукачів пригод, готових переглянути особисті речі жриці й з'ясувати, куди привела її дорога."},{t="Слідами Велінде",b="Тин'тел доручає слідчим оглянути речі, які Велінде лишила в столиці. Серед знахідок — щоденник, де описано спілкування Велінде з Елуною та жахливих воргенів, викликаних Косою Елуни. Під проводом Тин'тел мандрівники йдуть цим слідом на південь, до порту Раджет у Пустках, щоб дізнатися, куди відплила зневірена жриця, перш ніж зникнути безслідно."}},faq={{q="Хто така Тин'тел Блейдвівер?",a="Тин'тел Блейдвівер — нічна ельфійка з Вартових на Терасі Воїна в Дарнасусі. Вона дає завдання, з яких починається розслідування зникнення Жриці Велінде Старсонг.",al={"тин'тел блейдвівер","хто така тин'тел","інформація про тин'тел"}},{q="Де знайти Тин'тел Блейдвівер?",a="Вона в Дарнасусі, а точніше — на Терасі Воїна серед калдорейських воїнів і Вартових.",al={"місце тин'тел","де тин'тел блейдвівер","карта тин'тел"}},{q="Які завдання дає Тин'тел Блейдвівер?",a="Вона головна постать у ланцюжку завдань про Велінде Старсонг: дає завдання на кшталт «Речі Велінде», «Порт у Пустках» і завершальне «Відповіді на запитання».",al={"завдання тин'тел","яке завдання вона дає"}},{q="Чому її цікавить Велінде Старсонг?",a="Велінде Старсонг була жрицею, що служила в Ашенвалі, доки раптом не зникла, залишивши свою справу недовершеною. Тин'тел прагне з'ясувати її долю й розкрити темну таємницю її зникнення.",al={"чому розслідувати велінде","що сталося з велінде"}},{q="Куди веде її ланцюжок завдань?",a="Оглянувши речі Велінде в Дарнасусі, Тин'тел посилає слідчих на південь за море, до Раджета в Пустках, щоб відшукати корабельні записи про подорож Велінде.",al={"шлях завдання велінде","куди веде завдання"}},{q="Чи Тин'тел Блейдвівер дає завдання лише Альянсу?",a="Так. Служачи в столиці нічних ельфів Дарнасусі, Тин'тел Блейдвівер дає завдання лише членам Альянсу.",al={"чи орда може говорити з тин'тел","чи вона лише для альянсу"}}},fp="20,360,20.435.0,23.436.1,28.202.0,38.130.0,44.186.0,42.209.0,32.177.0,49.132.0"}
P.entries["npc:tiffin-ellerian-wrynn"] = {n="Тіффін Еллеріан Рінн",s="Королева Тіффін Еллеріан Рінн — кохана дружина короля Варіана Рінна й мати юного короля Андуїна. Її трагічна загибель під час заворушень каменярів розбила королівську родину й призвела до вигнання ремісників, які згодом стали Братством Дефіас.",h="Королева Тіффін Еллеріан Рінн — кохана дружина короля Варіана Рінна й мати юного короля Андуїна.",kw={"тіффін рінн","королева","варіан рінн","гільдія каменярів","едвін венкліф","дім вельмож"},ang={["faction:Alliance"]="Скорбота за королевою Тіффін досі тяжко нависає над королівським двором — вона пояснює запальність короля Варіана перед його зникненням і важкий тягар на плечах юного короля Андуїна.",["race:Human"]="Люди Стормвінда й Вестфолу пам'ятають королеву Тіффін як лагідну миротворицю, чий трагічний кінець зруйнував спокій королівства."},sec={{t="Улюблена королева",b="Тіффін народилася в незнатному Домі Еллеріанів, що мав скромні володіння у Вестфолі, і її заручини з принцом Варіаном Рінном домовили ще при її народженні, щоб забезпечити родині місце в Домі Вельмож Стормвінда. Хоч спершу обоє нарікали на цю домовленість, згодом їхній зв'язок став глибоким і міцним. Спокійна вдача Тіффін врівноважувала запальність Варіана, а її доброта здобула їй щиру любов і простолюду, і знаті."},{t="Трагедія в Стормвінді",b="Коли суперечки через плату за відбудову Стормвінда переросли в громадянські заворушення, королева Тіффін була одним із небагатьох впливових голосів, що закликали Дім Вельмож сповна розрахуватися з Гільдією Каменярів. Намагаючись угамувати розлючених робітників під час бунту на вулицях, вона загинула від кинутого каменя. Її раптова смерть поринула короля Варіана в глибоке горе й ожорсточила його гнів проти бунтівників, через що Едвін Венкліф і каменярі подалися у вигнання до Вестфолу."}},faq={{q="Ким була Королева Тіффін Рінн?",a="Королева Тіффін Еллеріан Рінн була королевою Стормвінда, дружиною Короля Варіана Рінна й матір'ю юного короля Андуїна. Вона походила з незнатного шляхетського роду Еллеріан, що мав землі у Вестфолі.",al={"хто така тіффін","мати андуїна","дружина варіана"}},{q="Як загинула Тіффін Рінн?",a="Вона загинула під час бунту каменярів у Стормвінді. Коли вона вийшла вперед, щоб заспокоїти розлючений натовп, кинутий камінь смертельно її поранив — нещасний випадок, що зламав королівський дух і спричинив жорстоку відплату корони.",al={"як померла тіффін","хто вбив тіффін","смерть королеви"}},{q="Що Королева Тіффін думала про каменярів?",a="На відміну від багатьох у Домі Вельмож, Королева Тіффін рішуче обстоювала інтереси Гільдії Каменярів і наполягала, щоб їм сповна заплатили обіцяне за відбудову Стормвінда.",al={"тіффін дефіас","чи тіффін підтримувала каменярів","оплата тіффін"}},{q="Як її смерть вплинула на Стормвінд?",a="Її смерть кинула Короля Варіана в тяжку зневіру й спонукала його жорстоко придушити бунт каменярів. Боячись страти, гільдія втекла зі Стормвінда в сільський Вестфол і зрештою перетворилася на розбійницьке Братство Дефіас.",al={"наслідки смерті тіффін","чому венкліф повстав","депресія варіана"}}},fp="21,264,15.412.0,20.499.0,27.202.0,25.239.0,47.181.0,35.259.0"}
P.entries["npc:tirion-fordring"] = {n="Тіріон Фордрінг",s="Тіріон Фордрінг — легендарний паладин і колишній володар Фортеці Марденгольд, що нині тихо живе у вигнанні у Східних Чумних землях. Один із перших п'яти паладинів, посвячених у Лицарі Срібної Длані, він утратив титул і землі, бо дотримав слова честі, даного ворогові-оркові. Зі своєї скромної хатини над Річкою Тондроріл він спостерігає за трагедією, що розгортається в Лордероні, і тривожиться за сина.",h="Тіріон Фордрінг — легендарний паладин і колишній володар Фортеці Марденгольд, що нині тихо живе у вигнанні у...",kw={"тіріон фордрінг","срібна длань","паладин","гартглен","ейтріґґ","таелан","вигнання"},ang={["class:Paladin"]="Стати перед Тіріоном — однаково що стати перед живим світанком вашого ордену. Він один із перших п'яти лицарів, посвячених Алонсусом Фаолом, і майстер Святого Світла, який довів: справжня праведність стоїть вище за закони смертних.",["faction:Alliance"]="Тіріон утілює ті ідеали, на яких постав Альянс, хоч ті самі королівства й затаврували його зрадником за те, що він поставив особисту честь вище за ненависть до інших рас.",["race:Human"]="Тіріон був незрівнянним героєм Альянсу Лордерону, що справедливо правив Гартгленом, — болісне нагадування про шляхетне королівство, яке скотилося в гниль і безумство.",["race:Orc"]="Тіріон — воїн Альянсу, який у Другій війні вбив чимало ворогів, — проте віддав усе: землю, родину й добре ім'я, аби не порушити клятви честі, даної оркові Ейтріґґу."},sec={{t="Один із перших п'яти",b="Ще до загибелі Лордерону Тіріон Фордрінг славився як один із найкращих лицарів королівства. Під час Другої війни архієпископ Алонсус Фаол обрав його разом з Утером Світлоносцем, Туральйоном, Саїданом Датроганом і Ґавінрадом Грізним, щоб заснувати Орден Лицарів Срібної Длані. Озброєний латами, святою відданістю й Книгою Відплати, Тіріон водив воїнів у жорстокі бої зі Старою Ордою, зокрема в кривавій облозі Шпиля Блекрок. Його шанували як непохитний взірець Святого Світла."},{t="Справа честі й вигнання",b="Після Другої війни Тіріон правив краєм Гартглен із Фортеці Марденгольд, а поруч були дружина Карандра й малий син Таелан. Його правлінню настав кінець, коли він натрапив на старого воїна-орка на ім'я Ейтріґґ, що жив самітником. Побачивши, яка глибока честь у ветерана, Тіріон дав слово захистити його. Коли влада Альянсу викрила Ейтріґґа, Тіріон став до бою проти власних земляків, щоб дотримати клятви. За цю зраду Альянсу Лордерону Тіріона позбавили шляхетства, відлучили від Срібної Длані й вигнали; Утер уберіг від вироку його дружину й сина."},{t="Батькова мука",b="Вигнання не торкнулося його родини, тож вона лишилася в Гартглені. Після того як у Третій війні Лордерон упав під натиском Погибелі, син Тіріона Таелан виріс, вступив до Багряного Хрестового Походу й зрештою став верховним лордом Гартглена. Тіріон здалеку дивиться, як Хрестовий Похід поринає в безумство, і впадає у відчай, бачачи сина маріонеткою фанатизму. Тримаючись за спогади про щасливіші часи — як-от родинні поїздки до Каер Дарроу, — самітник із берегів Тондрорілу шукає способу нагадати синові, що таке справжня честь."}},faq={{q="Хто такий Тіріон Фордрінг?",a="Тіріон Фордрінг був одним із п'яти паладинів-засновників Лицарів Срібної Длані й колишнім правителем Гартглена. Побратими вигнали його за те, що він з почуття честі став на захист орка, і тепер він живе відлюдником у затишній хижі на західному краю Східних Чумних Земель.",al={"лор тіріона","хто старий паладин","хто такий тіріон","паладин-відлюдник"}},{q="Чому Тіріона вигнали з Лордерону?",a="Тіріон натрапив на старого орка-ветерана на ім'я Ейтріґґ і дізнався, що їх поєднує спільне глибоке відчуття воїнської честі. Коли сили Альянсу схопили Ейтріґґа, Тіріон, дотримуючи обіцянки захистити відлюдника, напав на власних товаришів. Його визнали зрадником, позбавили титулів і вигнали з королівства.",al={"чому тіріона вигнали","зрада тіріона","чому тіріон вигнанець"}},{q="Що пов'язує Тіріона з Гартгленом?",a="Гартглен був колишньою вотчиною Тіріона. Він правив цим краєм із Фортеці Марденгольд аж до свого вигнання. Нині Гартглен тримає Багряний Хрестовий Похід під командуванням його сина, Верховного Лорда Телана Фордрінга.",al={"тіріон гартглен","замок мардена тіріон","лорд гартглена"}},{q="Чи зберіг Тіріон свою силу паладина?",a="Хоча Церква й Срібна Длань офіційно позбавили його звання й заявили, що відібрали в нього святу силу, щира віра Тіріона зберегла його зв'язок зі Святим Світлом непорушним. Світло відгукувалося на його волю так само сильно, як і завжди.",al={"чи тіріон зберіг світло","чи тіріон досі паладин","чи тіріон користується світлом"}},{q="Що Тіріон хоче від Багряного Хрестового Походу?",a="Тіріон не має жодної симпатії до фанатичного запалу Багряного Хрестового Походу, але його син Телан — один із найвищих їхніх командирів у Гартглені. Тіріон сподівається пробудити сумління Телана й вирвати його з продажних лап Хрестового Походу, поки його душа не загинула остаточно.",al={"тіріон багряний хрестовий похід","тіріон і телан","чому тіріона цікавить хрестовий похід"}},{q="Хто інші перші паладини?",a="Під час Другої війни Архієпископ Алонсус Фаол помазав п'ятьох поборників, які створили Лицарів Срібної Длані: Утера Світлоносця, Туральйона, Сайдана Датрогана, Ґавінрада Грізного й Тіріона Фордрінга.",al={"перші паладини","паладини срібної длані","паладини алонсуса фаола"}}},fp="15,424,21.517.0,27.595.0,18.522.1,23.285.0,37.308.0,42.199.0,42.256.0,47.259.0,36.201.0"}
P.entries["npc:tiza-battleforge"] = {n="Тіза Баттлфордж",s="Тіза Баттлфордж — досвідчена дворфійська паладинка з Лицарів Срібної Длані, що служить у Залі Таїнств в Айронфорджі. Вона славиться непохитною відданістю й проникливістю та веде молодих дворфійських паладинів шляхом чесноти, милосердя й самопожертви. Через вивчення священних текстів і випробування в поході вона перевіряє, чи справді новачки готові прийняти дар Світла — воскресіння.",h="Тіза Баттлфордж — досвідчена дворфійська паладинка з Лицарів Срібної Длані, що служить у Залі Таїнств в...",kw={"тіза","баттлфордж","паладин","срібна длань","воскресіння","зала таїнств","айронфордж"},ang={["class:Paladin"]="Для дворфійських паладинів Тіза Баттлфордж — ключова наставниця: вона перевіряє вашу гідність Фоліантом Божественності й довіряє вам силу воскрешати полеглих союзників.",["faction:Alliance"]="Тісно співпрацюючи з наставниками від Стормвінда до Хараноса, Тіза дбає, щоб Срібна Длань дотримувалася єдиних мірил чесноти й бойової готовності в усіх землях Альянсу.",["race:Dwarf"]="Тіза уособлює глибоке вкорінення Святого Світла в дворфійській культурі та в Срібній Длані й веде захисників Каз Модану проти таких загроз, як клан Темного Заліза."},sec={{t="Наставниця Кварталу містиків",b="У тихих покоях Зали Таїнств в Айронфорджі Тіза Баттлфордж — одна з найшанованіших дворфійських паладинок Лицарів Срібної Длані. Новачків з усього Альянсу посилають до неї наставники — Брандур Айронгаммер в Айронфорджі, Азар Стронгхаммер у Дун Мороґу та Лорд Ґрейсон Шедовбрейкер у Стормвінді, — щоб поглибити їхню духовну освіту. Тіза певна, що Святе Світло вимагає більшого, ніж бойова вправність: смиренного служіння, співчуття й непохитної стійкості перед темрявою Погибелі, що насувається, та іншими загрозами."},{t="Випробування Божественності",b="Коли молоді паладини приходять по глибші таїнства, Тіза вручає їм Фоліант Божественності. Коли текст вивчено, вона посилає їх чинити справжні діла безкорисливого милосердя — спершу допомогти тим, хто в скрутній потребі, як-от Джон Тернер. Потім вона кидає новачкам виклик: поставити на кін свою віру й вправність і допомогти її чоловікові, Муїредону Баттлфорджу, дати відсіч дворфам Темного Заліза. Тих, хто долає ці випробування й повертає до життя полеглих союзників Символом Життя, Тіза визнає гідними священного мистецтва воскресіння."}},faq={{q="Хто така Тіза Баттлфордж?",a="Тіза Баттлфордж — шанована дворфійка-паладинка з Лицарів Срібної Длані. У Залі Таїнств в Айронфорджі вона випробовує й наставляє дворфів-паладинів, що прагнуть поглибити свій зв'язок зі Святим Світлом.",al={"хто така тіза","лор тізи баттлфордж","тренер паладинів тіза"}},{q="Де знайти Тізу Баттлфордж?",a="Вона в Залі Таїнств — осередку духовної й тайної науки в Кварталі містиків Айронфорджа.",al={"місце тізи","де тіза баттлфордж","тренер паладинів зали таємниць"}},{q="Що за Фоліант Божественності вона дає паладинам?",a="Фоліант Божественності — священний повчальний текст із головними чеснотами й ученням Святого Світла. Тіза дає його паладинам, щоб вони вивчили його уроки, перш ніж вирушити на практичні випробування милосердя, мужності й милості.",al={"фоліант божественності тіза","завдання з книгою тізи","що таке фоліант божественності"}},{q="Чому Тіза посилає паладинів допомогти її чоловікові Муїредону?",a="Її чоловікові, Муїредону Баттлфорджу, загрожують ворожі дворфи Темного Заліза, поки він намагається допомогти своєму товаришеві Нармові Фолку. Тіза використовує цю скруту, щоб перевірити бойову відвагу послушника та його готовність Символом Життя повернути полеглих товаришів із межі смерті.",al={"завдання чоловіка тізи","муїредон баттлфордж","чому допомагати муїредону"}},{q="Якого вміння Тіза навчає гідних паладинів?",a="Коли послушник пройде її випробування милосердя й урятує полеглого товариша Муїредона, Тіза дарує йому силу Спокути — священного обряду воскресіння паладина.",al={"заклинання тізи для паладинів","чого навчає тіза","воскресіння тренер паладинів айронфордж"}},{q="Що пов'язує її з Брандуром Айронгаммером?",a="Брандур Айронгаммер — ще один дворф, наставник паладинів, що служить поруч із нею в Залі Таїнств Айронфорджа. Колись Тіза відверто сказала Брандурові, що його заздрість — духовна слабкість, і він присягнувся їй, що намагатиметься її подолати.",al={"тіза й брандур","брандур айронгаммер тіза","ревнощі брандура"}}},fp="16,411,25.594.0,22.569.1,24.240.0,34.126.0,51.237.0,57.292.0,45.170.0,45.265.0"}
P.entries["npc:tommy-joe-stonefield"] = {n="Томмі Джо Стоунфілд",s="Томмі Джо Стоунфілд — молодий фермер, затиснутий у гіркій родинній ворожнечі в серці Лісу Елвінн. Глибоко закоханий у Мейбелл Маклур, він мусить покладатися на тихі береги річки й таємні послання, щоб приховати їхній роман від ворожої рідні.",h="Томмі Джо Стоунфілд — молодий фермер, затиснутий у гіркій родинній ворожнечі в серці Лісу Елвінн.",kw={"томмі джо стоунфілд","мейбелл маклур","кохання","ферма стоунфілдів","ворожнеча","річка"},ang={["faction:Alliance"]="Для шукачів пригод Альянсу, що досліджують південний Елвінн, таємний роман Томмі Джо — скромне нагадування про тихе особисте життя, яке триває в тіні бандитства й політичних заворушень у краї."},sec={{t="Нещасливе кохання й ворожнеча",b="Стоячи на березі річки одразу на захід від Ферми Стоунфілдів, Томмі Джо Стоунфілд цілими днями дивиться через воду на садибу Маклурів. Стоунфілди й Маклури роками плекають ворожнечу, сварячись за землю, гордість і дрібні фермерські чвари. Та попри неприязнь, яку проповідують старші, Томмі Джо по вуха закохався в Мейбелл Маклур. Не маючи змоги зустрічатися відкрито, не викликавши обурення обох домів, він покладається на довірених посередників і співчутливу бабусю — Бабусю Стоунфілд, — щоб обмінюватися таємними записками й знаками прихильності."}},faq={{q="Хто такий Томмі Джо Стоунфілд?",a="Це юнак, що живе на Фермі Стоунфілдів у Лісі Елвінн. Він потай закоханий у Мейбелл Маклур, доньку запеклих суперників своєї родини.",al={"томмі джо","хто такий томмі джо","син стоунфілдів"}},{q="Де знайти Томмі Джо Стоунфілда?",a="Томмі Джо стоїть на березі річки на захід від Ферми Стоунфілдів і задивляється через воду на хутір Маклурів, де живе Мейбелл.",al={"місце томмі джо","де томмі джо","знайти томмі джо"}},{q="Чому Стоунфілди й Маклури ворогують?",a="Ніхто не каже, з чого все почалося. Дві фермерські родини просто довго й запекло ворогують, і жодна не хоче, щоб її молодь зналася з іншою.",al={"ворожнеча родин","чому вони ненавидять одне одного","ворожнеча стоунфілдів і маклурів"}},{q="Хто допомагає Томмі Джо й Мейбелл зустрічатися?",a="Бабуся Стоунфілд знає про їхні почуття й допомагає їхньому таємному коханню, доручаючи мандрівникам переносити потайні послання між Томмі Джо й Мейбелл.",al={"допомога бабусі стоунфілд","допомога таємним закоханим","хто допомагає закоханим"}}},fp="20,246,19.588.0,28.156.0,38.139.0,46.160.0,37.172.0"}
P.entries["npc:tonga-runetotem"] = {n="Тонга Рунтотем",s="Тонга Рунтотем — обізнаний таурен-друїд, що стоїть біля корчми на Перехресті в Пустках. Його прислали з Тандер Блафа розслідувати неприродну скверну, яка просочується в нечисленні оази краю й отруює місцевих звірів. Своїми дослідженнями він прагне простежити духовне збурення до самого джерела, поки крихка рівновага природи остаточно не зруйнувалася.",h="Тонга Рунтотем — обізнаний таурен-друїд, що стоїть біля корчми на Перехресті в Пустках.",kw={"тонга рунтотем","друїд","перехрестя","оази","печери стогонів","пустки"},ang={["class:Druid"]="Для тауренів-друїдів, що опановують своє ремесло, Тонга — приклад того, як кенарійські науки працюють на практиці: він показує, як розпізнати й очистити отруєну природу далеко від Місячного Гаю.",["faction:Horde"]="Орда покладається на дослідження Тонги, щоб головний шлях через Пустки лишався придатним для життя й захищеним від підземних магічних загроз.",["race:Tauren"]="Тонга втілює відданість тауренів Земній Матері: він невтомно береже крихкі джерела води, що підтримують життя на висохлих рівнинах."},sec={{t="Вартовий на Перехресті",b="Серед пилу й гамірної торгівлі Перехрестя Тонга Рунтотем тихо несе свою варту. Його прислали з високих плато Малгору старійшини Тандер Блафа, і він глибоко розуміє посушливу савану. Там, де інші бачать лише голі чагарники й хижих звірів, він читає тонкі ознаки здоров'я землі. Останнім часом ці ознаки різко погіршилися, і він наймає здібних мандрівників, щоб дослідити саме серце життя савани — її відокремлені оази."},{t="Отруєні води й спотворені звірі",b="Пустки цілком залежать від своїх розкиданих джерел води, але води Забутих ставків і Застояної оази стали небезпечними. На поверхню здіймаються дивні бульбашки магічної пари, а створіння, що п'ють цю воду, почали перетворюватися на потворних, агресивних мутантів. Тонга невтомно збирає зразки рослин і тварин, намагаючись зрозуміти, чи це звичайне гниття, чи справа рук чужої сили. Його висновки дедалі частіше вказують на глибокі підземні розломи, що з'єднують отруєні ставки просто з підземними лабіринтами Печер Стогонів."},{t="Рід Рунтотемів",b="Носячи горде ім'я клану Рунтотем, Тонга несе вагому друїдську спадщину, яку обстоює верховний друїд Гамуул Рунтотем. Поки верховний друїд Гамуул підтримує зв'язки з Колом Кенарія й навчається у священних лісах Місячного Гаю, розвідники на кшталт Тонги стають очима й руками на прикордонні. Тонга звертається до давньої ботанічної мудрості Місячного Гаю, щоб готувати цілющі мазі й протиотрути, — і так доводить, що молода друїдська традиція тауренів життєво потрібна юній Орді."}},faq={{q="Хто такий Тонга Рунтотем?",a="Тонга — таурен-друїд, що стоїть біля корчми на Перехресті в Пустках. Він дослідник, якого старійшини з Тандер Блафа послали вивчити дивну скверну, що ширить саваною.",al={"тонга рунтотем","хто такий тонга","друїд перехрестя"}},{q="Що Тонга досліджує в Пустках?",a="Він досліджує неприродну появу дивних випарів, звірів-мутантів і отруєної води в оазах Пусток, зокрема в Забутих ставках і Застояні.",al={"що робить тонга","мета тонга","чому досліджувати оази"}},{q="Звідки, на думку Тонги, береться скверна?",a="Вивчаючи змінених створінь і тріщини, з яких б'є вода, Тонга доходить висновку, що магічна скверна, яка вражає оази, бере початок глибоко під землею, у Печерах Стогонів.",al={"джерело скверни оази","звідки скверна","печери стогонів зв'язок"}},{q="Чи Тонга родич Гамуула Рунтотема?",a="У них спільне ім'я Рунтотем, і Тонга надсилає звістки про негаразди в Пустках Архідруїдові Гамуулу Рунтотему, старшому друїдові на Узвишші Старійшин у Тандер Блафі, але жодне джерело не каже, чи вони родичі.",al={"чи він родич гамуула","рід рунтотем","зв'язок із гамуулом"}},{q="Що Тонга робить для отруєних тварин?",a="Поєднуючи науку Місячного Гаю з місцевими реагентами, Тонга готує цілющі мазі, щоб лікувати отруєних газелей і протидіяти отрутам, що витікають із джерел на кшталт Піку Жахливої Імли.",al={"лікування газелей","тонга лікує хворих","отрута піку жаху"}},{q="Чому Тонга на Перехресті, а не в Таборі Тауражо чи Тандер Блафі?",a="Перехрестя — головний осередок північних Пусток: звідси Тонга близько до уражених оаз і має змогу звертатися до шукачів пригод, які можуть вирушати замість нього в небезпечні місця.",al={"чому перехрестя","чому тонга тут"}}},fp="15,374,25.507.0,32.602.1,21.498.0,23.213.0,43.177.0,55.167.1,37.199.0,45.178.0,82.214.0"}
P.entries["npc:tormus-deepforge"] = {n="Тормус Діпфордж",s="Тормус Діпфордж — дворфійський коваль, що працює в центрі Великої Кузні в Айронфорджі. Надійний ремісник, він координує постачання заліза й забезпечує озброєнням оборонні зусилля Альянсу по всьому Каз Модану й за його межами.",h="Тормус Діпфордж — дворфійський коваль, що працює в центрі Великої Кузні в Айронфорджі.",kw={"тормус діпфордж","коваль","велика кузня","айронфордж","залізо","лейкшир","поселення айронбенда"},ang={["profession:Blacksmithing"]="Для ковалів, що працюють біля Великої Кузні, Тормус — ключова ланка між сирими зливками й спорядженням війська на передовій.",["race:Dwarf"]="Гордий ремісник гірського королівства, Тормус показує готовність Айронфорджа плавити й доправляти зброю щоразу, коли союзники у Великому Альянсі кличуть на допомогу."},sec={{t="Майстер Великої Кузні",b="Просто біля ревучого вогню Великої Кузні Тормус Діпфордж наглядає за значними ковальськими роботами від імені клану Бронзбірдів. Окрім того, що сам кує сталь, Тормус — важливий контакт з постачання для ковалів і застав, яким потрібне сире залізо: він організовує припаси для обложених поселень на кшталт Лейкшира в Редріджі й координує дії з дворфійськими розкопками, як-от Поселенням Айронбенда в Лох Модані."}},faq={{q="Де знайти Тормуса Діпфорджа?",a="Тормус стоїть на кільцевому переході довкола лавового озера Великої Кузні — центрального осередку Айронфорджа.",al={"місце тормуса","де тормус","карта тормуса діпфорджа"}},{q="Яку роль Тормус відіграє у воєнних зусиллях Альянсу?",a="Тормус приймає замовлення на військове спорядження й сирий метал. Він посилає мандрівників доставляти зброю й знаряддя на застави, які відчайдушно їх потребують, зокрема в людські землі на кшталт Редріджу, де напади дедалі сильнішають.",al={"що робить тормус","мета тормуса","чому говорити з тормусом"}},{q="Хто інші Діпфорджі?",a="Ім'я Діпфордж носять кілька дворфів, зокрема Бенґус, Мурґот і Кайта Діпфордж, а також колега Тормуса Торвальд у Лох Модані, але чи вони родичі, так і не підтверджено.",al={"рід діпфордж","родина діпфордж","чи тормус родич мурґота"}}},fp="16,227,25.434.0,34.112.0,54.219.0,29.197.0"}
P.entries["npc:torwa-pathfinder"] = {n="Торва Патфайндер",s="Торва Патфайндер — самотній таурен-мисливець і слідопит, що отаборився біля входу до Кратера Ун'Ґоро, просто під схилом, який спускається з Танарісу. Він спостерігає за прадавньою живністю западини й вивчає небезпечних хижаків, що панують у джунглях. Шукачі пригод, які хочуть помірятися силами з легендарними звірами кратера, часто приходять до нього по пораду.",h="Торва Патфайндер — самотній таурен-мисливець і слідопит, що отаборився біля входу до Кратера Ун'Ґоро, просто...",kw={"торва патфайндер","таурен","мисливець","лар'корві","ун'ґоро","раптор","приманка"},ang={["class:Hunter"]="Торва — втілення терпіння й майстерності досвідченого слідопита: він доводить, що виманити верховного хижака можна, лише зрозумівши його харчування, нюх і звички на своїй території, а не покладаючись на грубу силу.",["race:Tauren"]="Для тауренів-мандрівників зустріч із Торвою на краю кратера — втішне нагадування про шану, яку їхній народ віддає природі, навіть серед доісторичного хаосу Ун'Ґоро."},sec={{t="Вартовий на порозі",b="Торва отаборився біля східного підніжжя кратера, де пустельні піски Танарісу поступаються вологим випарам джунглів, і став для новоприбулих чимось на кшталт неофіційного наглядача. Він шанує дикі сили Ун'Ґоро й знає, що необачні мандрівники швидко стають поживою для місцевої фауни. Його табір — рідкісна нагода перепочити, перш ніж поринути в задушливі глибини."},{t="Полювання на Лар'корві",b="Чимало уваги Торви поглинає Лар'корві — славетно хитрий і лютий раптор, що блукає північними околицями кратера. Торва розуміє: самою лише грубою силою такого верховного хижака не здолати. Тож він радить мисливцям вивчити його харчові звички й зробити зі свіжого м'яса туш і залоз приманку, достатньо сильну, щоб виманити звіра на відкрите місце."},{t="Первісні отрути й звірі",b="Окрім полювання на верховних хижаків-рапторів, Торва щиро цікавиться отруйними рослинами й войовничими колоніями мавп, що населяють западину. Він посилає мандрівників збирати отруту з непередбачуваних кровопелюсток і стежити за силою звірів-ватажків — таких, як могутній горила У'ча, — і невпинно розмірковує, як найсмертоносніші пристосування природи діють у відокремленому світі кратера."}},faq={{q="Де знайти Торву Патфайндера?",a="Торва таборує біля східного краю Кратера Ун'Ґоро, просто біля підніжжя звивистого схилу, що піднімається до пустелі Танаріс.",al={"місце торви","де торва","знайти торву патфайндера"}},{q="Хто такий Лар'корві?",a="Лар'корві — легендарний невловний ящер, що нишпорить Кратером Ун'Ґоро. Він славиться лютістю й хитрістю, і вистежити його звичайними способами важко: його треба виманювати особливою приманкою.",al={"лар'корві","хто такий лар'корві","що таке лар'корві"}},{q="Чи Торва дає завдання лише гравцям Орди?",a="Ні. Хоч він і таурен, Торва Патфайндер діє в нетрях незалежно. Він ділиться мисливською мудрістю й мисливськими випробуваннями з вправними шукачами пригод і з Альянсу, і з Орди.",al={"чи торва лише для орди","чи альянс може говорити з торвою","фракція торви"}},{q="Чому Торву цікавлять кровопелюстки?",a="Торву захоплює смертоносний захист місцевих рослин Ун'Ґоро. Він просить шукачів пригод зібрати виділення агресивних кровопелюсток, щоб зрозуміти й перевірити силу їхніх природних отрут.",al={"завдання кровопелюсток","навіщо кровопелюстки","отрута торви"}},{q="Хто такий У'ча?",a="У'ча — надзвичайно могутня горила, що живе в печерах і мавпячих володіннях Ун'Ґоро. Торва кидає мисливцям виклик: здолати У'чу, щоб довести свою вправність у боротьбі з найсильнішими звірами улоговини.",al={"могутній у'ча","бос горил унґоро","завдання у'чі"}},{q="Чи Торва Патфайндер родич Нури Патфайндер?",a="У них спільне прізвище Патфайндер, що натякає на спорідненість серед тауренських слідопитів, хоча Торва цілком поринув у небезпечні нетрі Ун'Ґоро.",al={"нура патфайндер","рід торви","рід патфайндер"}}},fp="16,349,24.386.0,22.382.0,25.370.0,34.139.0,18.197.0,46.194.0,39.200.0,13.198.0,47.155.0"}
P.entries["npc:treshala-fallowbrook"] = {n="Трешала Феллоубрук",s="Трешала Феллоубрук — нічна ельфійка, що тихо живе на верхньому ярусі Тераси Ремісників у Дарнасусі. Вона дружина Гералата Фелловбрука, чия праця завела його далеко від дому, у колючі глибини Рейзорфен Краулу в Пустках.",h="Трешала Феллоубрук — нічна ельфійка, що тихо живе на верхньому ярусі Тераси Ремісників у Дарнасусі.",kw={"трешала феллоубрук","дарнасус","тераса ремісників","гералат фелловбрук","нічні ельфи","амулет"},ang={["faction:Alliance"]="Трешала — зв'язкова Альянсу в Дарнасусі для поборників, що повертаються з тяжких походів проти колючих лігв шипогривів глибоко в Пустках.",["race:NightElf"]="Для нічних ельфів тихе чекання Трешали на чоловіка — нагадування про те, що від часів Гори Гіджал їхній народ уже не має вічності на очікування."},sec={{t="Та, що чекає на терасі",b="Трешала Феллоубрук скромно чекає на другому поверсі майстерні на Терасі Ремісників у Дарнасусі. Її чоловік Гералат вирушив у зарослі колючками глибини Рейзорфен Краулу в Пустках, а вона вдома чекає на звістку від нього. Їх поєднує амулет подружнього зв'язку — пам'ятка їхнього шлюбу, яку Гералат узяв із собою в нори шипогривів."}},faq={{q="Де знайти Трешалу Феллоубрук?",a="Вона на другому поверсі майстерні на Терасі Ремісників у Дарнасусі. До її кімнати можна дістатися дерев'яним пандусом усередині зброярської будівлі.",al={"місце трешали","де феллоубрук","як знайти трешалу"}},{q="Що досліджує Трешала?",a="Сама вона не дослідниця. Дослідження — справа її чоловіка, Гералата Фелловбрука, чия мандрівка завела його до Рейзорфен Краулу; Трешала ж чекає в Дарнасусі звісток про нього й про свій кулон єднання, який він узяв із собою.",al={"завдання трешали","лор смертність слабшає","чого хоче трешала"}},{q="Чому її непокоїть Рейзорфен Краул?",a="Її чоловік, Гералат, вирушив до Рейзорфен Краулу — тернистої твердині шипогривів у Пустках, — і відтоді від нього немає жодної звістки.",al={"чому рейзорфен краул","феллоубрук рейзорфен","зв'язок із краулом"}},{q="Вона крамарка чи ремісниця?",a="Ні, Трешала не торговка й не ремісниця. Вона просто живе над гамірними ятками майстрів на Терасі Ремісників.",al={"чи трешала торговець","що вона продає"}}},fp="20,249,24.373.0,38.180.0,29.230.0,41.137.0,37.133.0"}
P.entries["npc:tsunaman"] = {n="Цунаман",s="Цунаман — розумний водяний елементаль, що перебуває в Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Як посланець Трибуналу Припливів, він стежить за стихійними течіями Калімдору й закликає шукачів пригод з Орди протистояти силам скверни.",h="Цунаман — розумний водяний елементаль, що перебуває в Притулку Сонячної Скелі в Горах Кам'яного Кігтя.",kw={"цунаман","водяний елементаль","притулок сонячної скелі","трибунал припливів","нептулон","шаман"},ang={["class:Shaman"]="Для шаманів, що прагнуть зрозуміти стихії й єднатися з ними, Цунаман — рідкісна нагода поговорити просто з посланцем двору Мисливця Припливів.",["faction:Horde"]="Цунаман вважає Орду в Притулку Сонячної Скелі зручними союзниками проти стихійного безладу й вторгнення сектантів у води Калімдору."},sec={{t="Посланець припливів",b="Живучи біля стежки, що веде з Притулку Сонячної Скелі вниз, до Обвугленої Долини, Цунаман служить Трибуналу Припливів — високопоставленим слугам, вірним Мисливцеві Припливів Нептулону. Замість бездумної ворожості до смертних мандрівників він співпрацює з Ордою, стежачи за стихійними заворушеннями по всьому Калімдору, особливо за збуреннями, що розходяться із затоплених глибин Чорноглибинних Печер."},{t="Ненависть до полум'я",b="Вірний своїй стихійній природі, Цунаман відчуває інстинктивну, нутряну ненависть до вогню в будь-якій формі. Він постійно кипить через сусідні палаючі краєвиди Обвугленої Долини й вторгнення вогняних стихій. У таборі його ворожість така дріб'язкова й непримиренна, що він раз у раз підходить до кухонних вогнищ і багать лише для того, щоб загасити їх важким водяним кулаком."}},faq={{q="Хто такий Цунаман?",a="Цунаман — водяний елементаль у Притулку Сонячної Скелі в Горах Кам'яного Кігтя. Він посланець Трибуналу Припливів, що стежить за сутичками стихій у Калімдорі й шукає допомоги проти неприродних збурень.",al={"хто такий цунаман","лор цунамана","що таке цунаман"}},{q="Чому Цунаман нападає на вогнище?",a="Цунаман ненавидить вогняних елементалів і сам вогонь. Ведений суперництвом стихій, він раз у раз тупцює до вогнищ, які мандрівники розпалюють у Притулку Сонячної Скелі, і гасить їх водяним ударом.",al={"цунаман б'є вогнище","чому цунаман б'є вогонь","елементаль води біля вогнища"}},{q="Що таке Трибунал Припливів?",a="Трибунал Припливів — орден могутніх поплічників-стихій, що служать Нептулонові Мисливцеві Припливів, Володарю Стихії Води. Вони пильнують водні царства й відгукуються на збурення у водах світу.",al={"трибунал припливів","кому служить цунаман"}},{q="Чому Цунамана цікавлять Чорноглибинні Печери?",a="Чорноглибинні Печери забруднили сутінкові культисти й темні сили, що псують місцевих духів води. Цунаман залучає шукачів пригод Орди спуститися до затопленого храму й угамувати хаос, що баламутить води.",al={"цунаман чорноглибина","неспокій у глибинах"}}},fp="8,258,18.412.0,15.377.0,16.232.0,38.218.0,34.210.0,48.221.0"}
P.entries["npc:turak-runetotem"] = {n="Турак Рунтотем",s="Турак Рунтотем — шанований тауренський наставник друїдів, що живе в Залі Старійшин на Узвишші Старійшин у Тандер Блафі. Як довірений помічник Верховного Друїда Гамуула Рунтотема, він веде молодих тауренів священними шляхами природи й рівноваги. Під його проводом юні друїди проходять перші випробування, щоб єднатися з духами й опанувати звірині подоби.",h="Турак Рунтотем — шанований тауренський наставник друїдів, що живе в Залі Старійшин на Узвишші Старійшин у...",kw={"турак рунтотем","друїд","узвишшя старійшин","тандер блаф","земна мати","шлях пазура"},ang={["class:Druid"]="Для тауренських друїдів Турак Рунтотем — опора першого навчання: він дарує вміння телепортуватися до Місячного Гаю й випробовує новачків, доки ті не здобудуть ведмежу й водну подоби.",["faction:Horde"]="Турак відіграє важливу роль, укорінюючи магію природи в Орді: він виховує охоронців, здатних боротися з моровицею, скверною природи й давніми шрамами Калімдору.",["race:Tauren"]="Як член племені Рунтотем, Турак утілює відродження друїдських звичаїв серед тауренів після Третьої війни й допомагає своєму народові повернути давню гармонію із Земною Матір'ю."},sec={{t="Голос Земної Матері",b="У спокійних стінах Зали Старійшин Турак Рунтотем — один із провідних наставників друїдів в Орді. Відомий глибоким терпінням і врівноваженою вдачею, він допомагає Верховному Друїду Гамуулу Рунтотему відроджувати серед тауренів давні друїдські мистецтва. Турак дбає, щоб кожен молодий друїд шанував волю Земної Матері, і вчить, що фізична сила завжди мусить спиратися на духовну шану й гармонію з природою."},{t="Шлях Пазура",b="Коли молодий друїд готовий прийняти звірині подоби, Турак посилає його в широкий світ. Він започатковує його єднання з Колом Кенарія й навчає мистецтва телепортуватися через увесь Калімдор до священного прихистку — Місячного Гаю. Пам'ятаючи, якою приголомшливою й напруженою була його власна юнацька зустріч із Великим Духом Ведмедя, Турак випробовує відвагу учнів, посилаючи їх до Лунакло, щоб здобути силу тіла й серця, потрібну для Шляху Пазура."},{t="Охоронці рівноваги",b="Настанови Турака сягають далі за первісні бойові подоби — до опікування природою. Він посилає учнів назад до Дендрита Старблейза вивчати отрути, а той скеровує їх розібратися з навалою отруєнь тварин біля Перехрестя, що дивує навіть Турака. Через ці випробування, а також через виснажливі обряди під хвилями, що пробуджують водну подобу, Турак виховує з новачків стійких захисників, здатних зцілити найглибші рани Азерота."}},faq={{q="Де знайти Турака Рунтотема?",a="Турак Рунтотем — на Узвишші Старійшин у Тандер Блафі, у наметі Зали Старійшин, поруч з Архідруїдом Гамуулом Рунтотемом.",al={"місце турака","де турак","турак рунтотем тандер блафф"}},{q="Яку роль Турак відіграє для нових друїдів?",a="Він головний наставник молодих тауренів-друїдів, що дає їм завдання. Він навчає їх єднатися з Місячним Гаєм, через священні випробування відкриває їм Ведмежу й Водну подоби й навчає зцілювати природні отрути.",al={"чого навчає турак","тренер друїдів турак","роль турака"}},{q="Що пов'язує Турака з Місячним Гаєм?",a="Турак навчає друїдів-новачків заклинання, що переносить просто до священного гаю Місячний Гай, і посилає їх до представника Кола Кенарія, Дендрита Старблейза, по глибші духовні настанови.",al={"турак місячна поляна","звідки турак знає дендрита","телепорт місячна поляна турак"}},{q="Ким Турак доводиться Архідруїдові Гамуулу Рунтотему?",a="Обидва належать до шанованого племені Рунтотемів. Турак служить безпосередньо під проводом Архідруїда Гамуула як один із його найдовіреніших помічників і наставників у Залі Старійшин.",al={"чи турак родич гамуула","гамуул і турак"}},{q="Чому Турак посилає друїдів до Перехрестя?",a="Турак посилає учнів до Дендрита Старблейза в Місячний Гай вивчати отрути, а Дендрит відряджає їх допомогти з хвилею отруєнь тварин довкола Перехрестя. Коли вони повертаються, Турак винагороджує їх умінням назавжди зцілювати отруту.",al={"турак перехрестя","завдання отрути турака","влада над отрутою"}},{q="Що Турак особисто пережив із Великим Духом Ведмедя?",a="Турак відкрито розповідає, що коли він уперше ступив на шлях Друїда Пазура, його єднання з Великим Духом Ведмедя було спантеличливим, але надзвичайно сильним — і цей досвід поглибив його шану до ведмежої подоби.",al={"турак дух ведмедя","шлях пазура турака"}}},fp="15,354,24.449.0,20.481.0,20.464.0,33.144.0,41.225.0,40.201.0,51.164.0,45.251.0,64.222.0"}
P.entries["npc:twilight-lord-kelris"] = {n="Сутінковий Володар Келріс",s="Сутінковий Володар Келріс — орк-чорнокнижник і високий ватажок культу Молота Присмерку, що діє глибоко в Чорноглибинних Печерах. Зі свого місця у Святилищі Місячної Святині він керує темними ритуалами й доглядає первісну гідру Аку'май, прагнучи принести у світ царство космічного хаосу.",h="Сутінковий Володар Келріс — орк-чорнокнижник і високий ватажок культу Молота Присмерку, що діє глибоко в...",kw={"сутінковий володар келріс","молот присмерку","аку'май","чорнокнижник","чорноглибинні печери","древні боги"},ang={["class:Warlock"]="Звичайні чорнокнижники торгуються з демонами Палаючого Легіону, а Келріс показує темну тіньову магію трансу, народжену з покори шепоту Древніх Богів.",["faction:Alliance"]="Срібний світанок, що діє з Дарнасуса, прагне покласти край довгій кар'єрі невловимого Келріса, який роками розпалює темні культи й сіє жах на півночі Калімдору.",["faction:Horde"]="Старійшини й шамани вважають Келріса застережливим прикладом потворності — орком, що зрікся стихій і духів предків, аби плазувати перед давніми космічними жахами.",["race:NightElf"]="Блюзнірські ритуали Келріса оскверняють священне Святилище Місячної Святині — давній ельфійський храм, присвячений Елуні."},sec={{t="Провісник Порожнечі",b="Сутінковий Володар Келріс керує культистами Молота Присмерку, які захопили затонулі руїни Чорноглибинних Печер. Роками Келріс вислизав з-під пильного ока Дарнасуса, ухилявся від Срібного світанку й здобув похмуру славу: щойно десь на Калімдорі заворушувалося давнє зло, підозра падала на Келріса. Цей орк не служить ні воєначальникам, ні кланам — він цілком віддав себе Древнім Богам, прагнучи зруйнувати цивілізацію смертних і повернути Азерот до стану цілковитого первісного хаосу."},{t="Доглядач Звіра",b="У Святилищі Місячної Святині Келріс наглядає за поклонінням Аку'май і її вирощуванням — люту триголову гідру вважають провісницею й улюбленицею Древніх Богів. Переконаний, що, виростивши цю потвору, здобуде безсмертя й подасть знак до повернення своїх володарів, Келріс особисто стежить за її зростанням. Щоб угамувати її бездонний голод, він згодовує їй полонених і навіть неслухняних культистів зі своїх лав."},{t="Темний транс і сон",b="Келріс володіє могутньою тіньовою магією, здатною підкоряти розум і занурювати загарбників у глибокий неприродний сон. Він безперестанку молиться перед оскверненим вівтарем в оточенні свічок, що спрямовують темні сили. Тим, хто прагне здолати Келріса, доведеться не лише перемогти ватажка культу, а й упоратися з прихованими жахіттями, що прокидаються, щойно його ритуальне чування перервано."}},faq={{q="Хто такий Сутінковий Володар Келріс?",a="Сутінковий Володар Келріс — орк-чаклун, що командує силами Молота Присмерку в Чорноглибинних Печерах. Він керує діями культу в усьому затопленому храмі й глибоко відданий Древнім Богам.",al={"лор келріса","хто такий келріс","минуле келріса"}},{q="Чому Срібний світанок полює на Келріса?",a="Срібний світанок вважає Келріса невловним підбурювачем зла по всьому Калімдору. Хоча колись його вважали мертвим чи зниклим, його руку виявили за численними темними змовами на континенті, тож знищити його — першочергова справа.",al={"срібний світанок келріс","чому вбивати келріса","причина лиходійства чорноглибини"}},{q="Що Келріс робить із гідрою Аку'май?",a="Келріс вірить, що триголова гідра Аку'май — пряма провісниця Древніх Богів і його шлях до вічного життя. Він особисто плекає чудовисько, приносячи йому живі жертви, щоб воно росло.",al={"келріс і аку'май","чому келріс годує аку'май"}},{q="Що стається після перемоги над Келрісом?",a="За Келрісом стоїть вівтар із чотирма обрядовими свічками. Якщо їх запалити, захисні чари святилища спадають: прибувають хвилі прислужників Аку'май, а запечатана брама до лігва чудовиська відчиняється.",al={"свічки келріса","вівтар келріса","свічки місячного святилища"}},{q="Якими силами Келріс користується в бою?",a="Келріс володіє могутніми тіньовими заклинаннями, підкоренням розуму й магічним сном, що знешкоджує ворогів, поки тривають його темні обряди.",al={"здібності келріса","закляття келріса"}},{q="Хто така Башана Рунтотем?",a="Башана Рунтотем — союзниця, що розслідує скверну в Чорноглибинних Печерах і застерігає шукачів пригод про одержимість Келріса поклонінням Древнім Богам і його прагнення знову кинути світ у первісний хаос.",al={"башана рунтотем келріс","таурен мисливець келріс"}}},fp="20,288,18.530.0,19.441.0,23.377.1,28.202.0,38.237.0,44.195.0,38.207.1,38.141.0,25.204.0"}
P.entries["npc:tyrande-whisperwind"] = {n="Тіранда Віспервінд",s="Тіранда Віспервінд — Верховна Жриця Елуни й найвища провідниця нічних ельфів. Разом зі своїм коханим, Архідруїдом Малфуріоном Стормрейджем, вона провела свій народ крізь нищівну Війну Прадавніх і десять тисячоліть Довгої Варти. Нині вона править зі священних віт Тельдрассила, очолює Сестринство Елуни й командує військом Вартових, що боронять священну дику природу Калімдору.",h="Тіранда Віспервінд — Верховна Жриця Елуни й найвища провідниця нічних ельфів.",kw={"тіранда","віспервінд","верховна жриця","елуна","вартові","нічні ельфи","довга варта"},ang={["class:Druid"]="Поки Малфуріон спить у Смарагдовому Сні, Тіранда тісно співпрацює з Колом Кенарія, щоб захищати священні гаї й плекати Тельдрассил.",["class:Priest"]="Як живе вмістилище божественної ласки Елуни, Тіранда — вершина калдорейського жрецтва: вона кличе з небес місячні зорі й зціляє рани самою лише вірою.",["faction:Alliance"]="Нічні ельфи віддавна трималися осторонь і ревно берегли свою незалежність, та Тіранда веде їх у складі Альянсу, щоб разом протистояти дедалі більшим небезпекам Калімдору.",["faction:Horde"]="Для Орди Тіранда — грізна й непоступлива супротивниця: за її наказом Вартові силою дають відсіч кожній спробі рубати ліс і добувати ресурси в Ашенвалі.",["race:NightElf"]="Тіранда — ваша верховна провідниця й Верховна Жриця. Понад десять тисяч років вона стоїть на варті вашого народу, несучи світло Елуни крізь усі випробування."},sec={{t="Обраниця Місячної Богині",b="Тіранда народилася в давньому місті Сурамар і зростала разом із братами-близнюками Малфуріоном та Ілліданом Стормрейджами. Брати обрали друїдство й чародійство, а Тіранда вступила до сестринства Елуни послушницею. Коли під час Війни Прадавніх демонічний Палаючий Легіон уперше вдерся в Азерот, смертельно поранена Верховна Жриця Деджана обрала Тіранду своєю наступницею. Благословенна прямою ласкою Місячної Богині, Тіранда перетворила Сестринство на сяйливу бойову силу, що володіла і божественним зціленням, і палючим місячним гнівом, і вберегла свій народ на краю цілковитої загибелі."},{t="Довга Варта й Вартові",b="Після Великого Розколу й запечатання Колодязя Вічності Малфуріон і друїди поринули в Смарагдовий Сон, у довгу й глибоку сплячку. Тіранда взяла на себе самотній тягар захисту їхнього краю, що повільно оговтувався. Вона зібрала Вартових — добірний загін воїтельок, які десять тисяч років патрулювали ліси Калімдору. Упродовж усієї Довгої Варти вона пильно стерегла давнє зло й рештки демонів, не втрачаючи віри в Елуну, хоч між короткими зустрічами з Малфуріоном минали століття."},{t="Третя війна й новий прихисток",b="Коли в Третій війні Палаючий Легіон повернувся, Тіранда рішуче розбудила сплячих друїдів, щоб разом зустріти страшну загрозу. Подолавши глибоку недовіру до новоприбулих орків і людей, вона допомогла скласти відчайдушний союз на Горі Гіджал, і нічні ельфи пожертвували своїм безсмертям на вершині Нордрассила, щоб знищити Архімонда. Гора Гіджал зранена, Малфуріон знову береже Смарагдовий Сон, тож Тіранда править калдореями з величного Храму Місяця в Дарнасусі, пильно стежачи і за вилазками Орди, і за дедалі тіснішим союзом з Альянсом."}},faq={{q="Хто така Тіранда Віспервінд?",a="Тіранда Віспервінд — Верховна Жриця Елуни й верховна духовна та політична провідниця нічних ельфів. Понад десять тисяч років вона веде свій народ — від Війни Прадавніх до Третьої війни, — а нині очолює калдореїв із Храму Місяця в Дарнасусі.",al={"хто така тіранда","лор тіранди віспервінд","лідерка нічних ельфів"}},{q="Де зараз живе Тіранда?",a="Тіранда живе в столиці Дарнасус, високо в гіллі Світового Дерева Тельдрассил. Вона править із верхнього святилища Храму Місяця, оточена жрицями Елуни й вартою Вартових.",al={"де тіранда","місце тіранди","де знайти тіранду"}},{q="Які стосунки між Тірандою й Малфуріоном?",a="Тіранда й Малфуріон Стормрейдж — пара на все життя, що разом ведуть цивілізацію нічних ельфів уже десять тисячоліть. Хоча замолоду її кохання шукали і Малфуріон, і його брат-близнюк Іллідан, Тіранда обрала Малфуріона, чия глибока відданість рівновазі й природі перегукувалася з її вірою в Елуну.",al={"тіранда малфуріон","чи тіранда заміжня","тіранда й ілідан"}},{q="Що таке Сестринство Елуни?",a="Сестринство Елуни — стародавній релігійний орден жриць нічних ельфів, що шанують Богиню Місяця. Під проводом Тіранди як Верховної Жриці сестри не лише цілителі й духовні наставниці, а й запеклі воєначальниці та бійці.",al={"сестринство елуни","жриці елуни","жерці тіранди"}},{q="Яку роль Тіранда відіграла під час Довгої Варти?",a="Упродовж десяти тисяч років після Розколу, поки Малфуріон і друїди-чоловіки спали в Смарагдовому Сні, Тіранда заснувала Вартових і командувала ними. Вона обходила дикі краї Калімдору, полювала на сатирів і демонів, що лишилися, і берегла свій народ у відокремленні.",al={"що таке довга варта","тіранда довга варта","керівниця вартових"}},{q="Чому Тіранда насторожено ставиться до Орди?",a="Під час Третьої війни орки прийшли до Ашенвалю й почали вирубувати священні ліси, а під дією демонічної крові вбили напівбога Кенарія. Хоча біля Гори Гіджал уклали хитке перемир'я, триваюча лісозаготівля Орди в Ашенвалі змушує Тіранду тримати Вартових у постійній готовності.",al={"тіранда орда","чому тіранда ненавидить орків","нічні ельфи проти орди"}}},fp="19,417,26.614.0,32.561.0,29.602.0,27.298.0,36.234.0,55.303.0,32.281.0,45.279.0,33.304.0"}
P.entries["npc:tyrion"] = {n="Тиріон",s="Тиріон — таємний агент-гном, що перебуває у Фортеці Стормвінда. Діючи в тіні разом із близькими спільниками, як-от Еллінг Тріас, він допомагає шукачам пригод добувати делікатні відомості й зривати підступні змови проти королівства.",h="Тиріон — таємний агент-гном, що перебуває у Фортеці Стормвінда.",kw={"тиріон","гном","шпигунство","фортеця стормвінда","еллінг тріас","розвідка"},ang={["class:Rogue"]="Для розбійників, залучених до таємних операцій Еллінга Тріаса, Тиріон — незамінна своя людина у Фортеці Стормвінда.",["faction:Alliance"]="Розвідувальна робота Тиріона відіграє ключову роль у захисті корони від таємних загроз, що визрівають у столиці королівства.",["race:Gnome"]="Тиріон втілює тонкість і розум, які гноми вносять у ризиковане шпигунство Альянсу, — і діє просто під носом у пихатої людської знаті."},sec={{t="Тиха присутність у Фортеці",b="Серед пишноти Фортеці Стормвінда Тиріон тримається непомітно. Поки залами снують знатні придворні й королівські вартові, цей кмітливий гном діє нишком: стежить за тим, що відбувається в палаці, й підтримує зв'язок із людьми ззовні, які працюють далеко від офіційного нагляду."},{t="Тіні та шпигунство",b="Тиріон — довірена особа Еллінга Тріаса, знаного сироторговця з Торгового Кварталу, який тримає потайну мережу інформаторів. Коли постають делікатні справи, де треба оминути офіційну бюрократію Дому Вельмож, Тріас скеровує надійних агентів просто до Тиріона за мурами замку."},{t="Викриття загрози",b="Тиріон допомагає слідчим у найважливіших справах — потайному проникненні та збереженні делікатних вантажів у місті. Зрештою саме він розпізнає неминучу небезпеку в самому серці королівства й попереджає союзників, перш ніж задуманий удар встигне вразити верхівку Стормвінда."}},faq={{q="Хто такий Тиріон?",a="Тиріон — винахідливий гном-агент, що служить у Фортеці Стормвінда. Разом із таємними союзниками він виконує приховані доручення й збирає відомості в обхід звичних королівських каналів.",al={"хто цей гном","особа тиріона","що робить тиріон"}},{q="Де знайти Тиріона?",a="Тиріон перебуває у Фортеці Стормвінда в Стормвінді: стежить за всім і допомагає агентам, які приходять із вістями від його надійних знайомих.",al={"місце тиріона","де тиріон","знайти тиріона"}},{q="Що пов'язує його з Еллінгом Тріасом?",a="Тиріон і Еллінг Тріас — давні друзі й соратники. Тріас через свої торговельні зв'язки збирає чутки з усього королівства й посилає до Тиріона надійних шукачів пригод, коли у Фортеці треба діяти потай.",al={"тиріон і еллінг тріас","чи тиріон знає тріаса","зв'язок із тріасом"}},{q="Які завдання дає Тиріон?",a="Тиріон причетний до таємних операцій, серед яких завдання «Проникнення в замок», «Речі неабиякої ваги» і попередження союзників під час завдання «Напад!».",al={"завдання тиріона","які завдання він дає"}},{q="Чому таємними справами при людському дворі займається гном?",a="Гноми — важливі союзники Альянсу, а такі, як Тиріон, мають гострий розум, уміння діяти непомітно й технічну кмітливість, яких людська влада часто не помічає.",al={"чому гном у цитаделі стормвінда","гном-агент цитаделі"}},{q="Яку змову розслідує Тиріон?",a="Тиріон допомагає вистежити викрадені відомості й таємні змови, що плетуться просто під носом у королівського двору й зрештою ведуть до збройної засідки в самому місті.",al={"змова тиріона","що розслідує тиріон"}}},fp="6,248,28.275.0,21.321.0,21.283.1,14.198.0,24.141.0,39.226.0,30.146.0,61.169.0,55.168.1"}
P.entries["npc:ukor"] = {n="Укор",s="Укор — орк-пеон, що відпочиває біля східної стежки за межами Долини Випробувань у Дуроторі. Прагнучи допомогти своєму народові, він ніс припаси аж із Гострого Пагорба — і виявив, що на тренувальних землях провізії й так удосталь.",h="Укор — орк-пеон, що відпочиває біля східної стежки за межами Долини Випробувань у Дуроторі.",kw={"укор","пеон","робітник","припаси","долина випробувань","гострий пагорб","ґроск"},ang={["faction:Horde"]="Для нових новобранців, що виходять зі своїх випробувань, допомога Укору — одна з перших нагод підтримати повсякденну логістику Орди між поселеннями.",["race:Orc"]="Орки-пеони несуть важку фізичну працю, на якій будується нова Орда, і Укор показує, що навіть скромні робітники щиро прагнуть підтримати воїнів Дуротару."},sec={{t="Доручення пеона",b="Поки більшість орків-пеонів проводять життя під пильним оком суворих наглядачів, рубаючи ліс чи тягаючи каміння, Укор, простий робітник, спробував прислужитися з власної волі. Чи то з наказу, чи то з натхнення віднести харчі з Гострого Пагорба новобранцям у Долині Випробувань, він здійснив небезпечний перехід червоними рівнинами Дуротару повз скорпідів і вепрів, що нишпорять довкола. Прибувши, він з'ясував, що Долина вже добре забезпечена і його пакунок нікому не потрібен. Виснажений і трохи зневірений, він сидить при дорозі й покладається на молодих шукачів пригод, щоб ті повернули невикористані припаси на північ, Корчмарю Ґроску."}},faq={{q="Хто такий Укор?",a="Укор — старанний орк-пеон, що стоїть при дорозі, яка веде на схід із Долини Випробувань у південному Дуротарі.",al={"хто такий укор","лор укора","що робить укор"}},{q="Чому Укор стоїть при дорозі з мішком їжі?",a="Укор приніс із Гострого Пагорба важкий клунок харчів, щоб нагодувати молодих воїнів, які тренуються в Долині Випробувань. А коли дійшов, виявилося, що провізії в них досить, — і він застряг із непотрібною їжею.",al={"чому укор біля дороги","причина завдання укора","мішок їжі укора"}},{q="Про що Укор просить перехожих?",a="Укор надто боїться звірів при дорозі, щоб самому нести мішок назад, тож просить молодих шукачів пригод, які йдуть на північ до Гострого Пагорба, повернути клунок Корчмареві Ґроску.",al={"що просить укор","завдання укора","завдання тягар пеона"}}},fp="4,233,15.612.0,12.114.0,53.223.0,43.176.0"}
P.entries["npc:ula-elek"] = {n="Ула'елек",s="Ула'елек — троль-коваль із племені Темного Спису, що живе в Селі Сен'джин на південному узбережжі Дуротару. Разом з оркським воїном-ветераном Тун'ґрімом Файрґейзом він виготовляє особливі обладунки для воїнів Орди, які прагнуть довести свою гідність. Його робота поєднує традиційне тролівське ремесло з екзотичними трофеями з усього Калімдору.",h="Ула'елек — троль-коваль із племені Темного Спису, що живе в Селі Сен'джин на південному узбережжі Дуротару.",kw={"ула'елек","село сен'джин","темний спис","жорстокі латні рукавиці","тун'ґрім файрґейз","коваль"},ang={["class:Warrior"]="Ула'елек відіграє ключову роль у збиранні вашого жорстокого обладунку: за вказівками Тун'ґріма Файрґейза він перетворює важко здобуті копита сатирів на міцні рукавиці.",["race:Troll"]="Ула'елек уособлює важливу роль ковалів Темного Спису в молодій Орді: він кує спорядження для передової просто на відкритих берегах Села Сен'джин."},sec={{t="Коваль Темного Спису",b="Ула'елек працює серед хиж і жаровень Села Сен'джин, служачи племені Темного Спису вправним бронником. У прибережному поселенні, якому постійно загрожують ворожі шипогриви й морські повзуни, справні клинки й міцні обладунки — запорука виживання племені. Проте слава Ула'елека сягає далі за місцеву оборону й привертає увагу досвідчених воїнів по всій Орді."},{t="Кування жорстокого обладунку",b="Коли молоді воїни приходять до Тун'ґріма Файрґейза на його оглядову кручу в Пустках, старий ветеран відсилає їх на південь, до Села Сен'джин, шукати Ула'елека. Тун'ґрім довіряє тролеві-ковалеві виготовлення Жорстоких Латних Рукавиць — грізного бойового спорядження, гідного загартованих у боях бійців передової. Для цієї роботи Ула'елек вимагає рідкісних матеріалів, передусім розпухлих нероздвоєних копит сатирів, які висмоктують магію лісу на північному сході Ашенвалю."}},faq={{q="Хто такий Ула'елек?",a="Ула'елек — троль-зброяр із племені Темного Списа, що живе в Селі Сен'джин у Дуротарі. Ветерани Орди довіряють йому кувати міцні, особливі обладунки для молодих бійців передової.",al={"хто такий ула'елек","лор ула'елека","історія ула'елека"}},{q="Де знайти Ула'елека?",a="Він у Селі Сен'джин — поселенні Темного Списа на південно-східному узбережжі Дуротару, на південь від Гострого Пагорба.",al={"місце ула'елека","де ула'елек","знайти ула'елека"}},{q="Чому Тун'ґрім Файрґейз посилає воїнів до Ула'елека?",a="Тун'ґрім Файрґейз визнає винятковий хист Ула'елека-коваля й доручає йому виготовити Жорстокі Латні Рукавиці для воїнів Орди, які здобули повагу ветерана.",al={"тун'ґрім і ула'елек","чому йти до ула'елека"}},{q="Що потрібно Ула'елеку, щоб зробити рукавиці?",a="Щоб викувати Жорстокі Латні Рукавиці, Ула'елек вимагає від воїнів вполювати сатирів у північно-східному Ашенвалі й принести їхні набряклі нероздвоєні копита — головну складову виробу.",al={"матеріали ула'елека","складники жорстоких рукавиць"}},{q="Яке спорядження кує Ула'елек?",a="He specializes in heavy combat armor, specifically the Brutal Gauntlets, which form part of the traditional set of Brutal Armor forged for promising warriors of the Horde.",al={"що кує ула'елек","нагороди ула'елека"}},{q="Навіщо для рукавиць потрібні копита сатирів?",a="Сатири північно-східного Ашенвалю живляться чистотою лісу, і в тих, хто ввібрав найбільше магії, копита набрякають і перестають бути роздвоєними. Ула'елек витягує з копит цю силу й вкладає її в рукавиці.",al={"чому копита сатирів","копита для рукавиць"}}},fp="8,347,22.413.0,24.450.0,16.184.0,28.127.0,54.178.0,56.182.0,38.171.0,42.220.0"}
P.entries["npc:umpi"] = {n="Умпі",s="Умпі — жаба, що живе в Таррен Міллі як мимовільна лаборантка Аптекаря Лайдона. Її тримають у майстерні Королівського Аптекарського Товариства, і вона раз у раз стає піддослідною для експериментальних отрут і чумних варив.",h="Умпі — жаба, що живе в Таррен Міллі як мимовільна лаборантка Аптекаря Лайдона.",kw={"умпі","жаба","аптекар лайдон","таррен мілл","еліксир страждання","еліксир агонії"},ang={["race:Undead"]="Умпі — наочний приклад безжальних, прагматичних методів Королівського Аптекарського Товариства, де життя й смерть — лише змінні в удосконаленні арсеналу Відступників."},sec={{t="Життя вічних випробувань",b="У темних лабораторіях Таррен Мілла Відступники невтомно варять суміші смерті й муки. Для Аптекаря Лайдона наукова суворість вимагає живої плоті, щоб випробовувати формули, і Умпі приймає на себе головний тягар цих дослідів. Лайдон раз у раз випробовує на ній смертоносні варива — як-от Еліксир Страждання й Еліксир Агонії. Щойно отрута неминуче робить своє й убиває її, аптекар знову оживлює жабу, щоб вона була готова витримати наступну смертельну дозу на славу Королівського Аптекарського Товариства."}},faq={{q="Хто така Умпі?",a="Умпі — жаба, яку тримає Аптекар Лайдон у Таррен Міллі. Вона йому і помічниця, і головний піддослідний у його отруйних алхімічних дослідах.",al={"хто така умпі","що таке умпі","жаба таррен мілл"}},{q="Чому Аптекар Лайдон раз у раз убиває Умпі?",a="Аптекар Лайдон перевіряє на Умпі силу щойно зварених отрут. Згодувавши їй смертельне вариво на кшталт Еліксиру Страждання, він знову її оживлює, щоб у наступних дослідах отруїти ще раз.",al={"чому лайдон вбиває умпі","отруєна умпі","жаба лайдона"}},{q="Умпі жива чи нежить?",a="Біологічно вона балансує між тим і тим. Формально вона звичайна тварина, але Аптекар Лайдон відверто визнає, що після кожного смертельного досліду піднімає її з мертвих.",al={"чи умпі нежить","умпі зомбі","жаба нежить"}},{q="Де знайти Умпі?",a="Умпі сидить в аптекарській майстерні в Таррен Міллі, у Передгір'ї Гілсбреда, просто біля робочого столу Аптекаря Лайдона.",al={"де умпі","місце умпі"}}},fp="4,237,27.552.0,12.147.0,44.216.0,24.188.0,24.136.0"}
P.entries["npc:undertaker-mordo"] = {n="Гробар Мордо",s="Гробар Мордо — доглядач склепу Похоронного Подзвону, найперше обличчя, яке бачать щойно пробуджені Відступники, розплющивши очі. Тим, хто прокидається, він каже, що Король-Ліч більше не має над ними влади, і відсилає їх на службу справі Відступників; тіла, які так і не ворухнулися, йдуть у вогонь.",h="Гробар Мордо — доглядач склепу Похоронного Подзвону, найперше обличчя, яке бачать щойно пробуджені...",kw={"гробар мордо","склеп","похоронний подзвін","пробудження","жрець тіні сарвіс","відступники"},ang={["race:Undead"]="Гробар Мордо — найперший, з ким ви розмовляєте, розплющивши очі у смерті; він спрямовує ваші перші непевні кроки на службі королеві Сильвані."},sec={{t="Пробудження в Похоронному Подзвоні",b="Доглядаючи склеп Похоронного Подзвону на Галявинах Тірісфалю, Гробар Мордо наглядає за мертвими, поки трупи вириваються з розтрощених лабет Погибелі. Кожному щойно звільненому з Відступників, що прокидається в холоді склепу, Мордо дає перший орієнтир у невпізнанному другому житті. Він оцінює їхній здоровий глузд, знайомить із дійсністю їхнього стану й одразу скеровує до служби під рукою королеви Сильвани Віндраннер."},{t="Ті, хто не прокидається",b="Не кожне тіло, принесене до склепу, прокидається. Мордо довго не чекає: трупи, що лишаються нерухомими, летять у вогонь, а тих, хто ворухнувся, зустрічають із сухим нетерпінням і без жодних церемоній. Кожного, хто підводиться при здоровому глузді, відсилають сходами вгору й дорогою далі — до каплиці, де на них чекає Жрець Тіні Сарвіс, який пояснює їхнє нове існування. Безтямні зомбі, що заполонили північ села, — клопіт Сарвіса, а не Мордо: саме жрець тіні посилає щойно піднятих нищити їх."}},faq={{q="Хто такий Гробар Мордо?",a="Гробар Мордо — доглядач склепу в Похоронному Подзвоні на Галявинах Тірісфалю, один із Відступників. Він зустрічає щойно воскреслу нежить, коли та прокидається, і спрямовує її на службу.",al={"хто такий мордо","лор гробаря мордо","мордо похоронний подзвін"}},{q="Чому він стоїть на цвинтарі?",a="Мордо доглядає склеп Похоронного Подзвону, де прокидається нежить, щойно звільнена з-під влади Короля-Ліча. Він вартує там, щоб привітати кожного, хто ворухнеться.",al={"чому він на цвинтарі","що робить мордо","робота мордо"}},{q="Що буває з нежиттю, яка прокидається без розуму?",a="Тіла, що так і не прокинулися, кидають у вогонь. А безмозкі зомбі, що тиняються на півночі Похоронного Подзвону, — не Мордова турбота: Жрець Тіні Сарвіс посилає новоповсталих їх знищити, хай навіть то колишні брати й сестри.",al={"ті що не вдалося врятувати","безумна нежить похоронного подзвону","дика нежить похоронного подзвону"}},{q="Куди Мордо посилає новоповсталих Відступників?",a="Переконавшись, що новопробуджений при тямі, Мордо виряджає його зі склепу дорогою до каплиці — поговорити зі Жрецем Тіні Сарвісом, який пояснить, що означає стати до лав Відступників.",al={"куди йти після мордо","напрямок завдання мордо","наступний крок після мордо"}}},fp="16,304,27.440.0,21.504.0,24.164.0,34.182.0,60.238.0,43.227.0"}
P.entries["npc:ur-kyo"] = {n="Ур'кьо",s="Ур'кьо — шанований троль джунглів, наставник жерців у Долині Духів Оргріммара. Його знають як духовного провідника й найвидатнішого жерця племені Темного Спису: він веде початківців духовних мистецтв у столиці Орди. З його порадами жерці вчаться спілкуватися з духами й тримати рівновагу між могутніми силами тіні та світла.",h="Ур'кьо — шанований троль джунглів, наставник жерців у Долині Духів Оргріммара.",kw={"ур'кьо","жрець","темний спис","долина духів","острови відлуння","вуду"},ang={["class:Priest"]="Ур'кьо — важливий наставник для жерців Орди, що мандрують Дуротаром: він навчає шукачів пригод таїнств віри, обрядів тіні й священних оберегів.",["faction:Horde"]="У серці Долини Духів Оргріммара Ур'кьо дає духовну опору, потрібну, щоб готувати цілителів і заклиначів тіні до оборони Орди.",["race:Troll"]="Для тролів Темного Спису Ур'кьо — найголовніший духовний провідник в Оргріммарі, що зберігає традиційне вуду племені й давні магічні обряди після втрати Островів Відлуння."},sec={{t="Духовний наставник Темного Спису",b="Серед спокійних вод і хиж Долини Духів Ур'кьо — один із найвпливовіших духовних авторитетів Оргріммара. Для тролів Темного Спису, що втекли з Островів Відлуння й знайшли дім у Дуротарі разом з Ордою Тралла, зберегти священні традиції вкрай важливо. Ур'кьо оберігає ці прадавні звичаї й лишається опорою духовної дисципліни й настанов і для племінних містиків, і для заїжджих жерців."},{t="Настанови й давні обряди",b="Жерці, що йдуть шляхом віри, знаходять в Ур'кьо терплячого наставника. Він веде традиційне навчання й давні обряди, зокрема ті, що дарують Вроки слабкості й захисний оберіг, відомий як Тіньова варта. Ур'кьо також допомагає жерцям Орди зрозуміти різноманітні духовні практики союзу, перекидаючи місток між тролячим вуду, звичаями предків і чужоземними вченнями."}},faq={{q="Хто такий Ур'кьо?",a="Ур'кьо — троль джунглів і головний наставник жерців у Долині Духів в Оргріммарі. Його вважають духовним провідником жерців Темного Списа й найвправнішим жерцем свого племені.",al={"роль ур'кьо","особа ур'кьо","хто такий ур'кьо"}},{q="Де знайти Ур'кьо?",a="Ур'кьо живе в Долині Духів — тролівському кварталі в західній частині Оргріммара. Його можна знайти в навчальних хатинах біля води разом з іншими духовними наставниками.",al={"місце ур'кьо","карта ур'кьо","знайти ур'кьо"}},{q="Яких умінь навчає Ур'кьо?",a="Як наставник класу, Ур'кьо навчає жерців основних заклять тіні й світла. Крім того, він посвячує жерців Темного Списа в їхні особливі расові обряди й допомагає опанувати «Вроки слабкості» і «Тіньовий захист».",al={"закляття ур'кьо","вміння ур'кьо","закляття тролів-жерців"}},{q="Чому Ур'кьо навчає в Оргріммарі, а не на Островах Відлуння?",a="Після зради Залазана й втрати Островів Відлуння плем'я Темного Списа оселилося поруч з орками в Дуротарі. Ур'кьо облаштувався в Долині Духів, щоб зберігати містичні традиції племені й готувати нових захисників для Орди.",al={"чому ур'кьо в оргріммарі","ур'кьо оргріммар лор"}},{q="Чи навчає Ур'кьо жерців, які не є тролями?",a="Так. Ур'кьо навчає всіх жерців Орди, які до нього приходять, і стає містком знань між тролями Темного Списа та іншими членами Орди, зокрема Відступниками.",al={"чи нежить навчається в ур'кьо","ур'кьо тренер орди"}},{q="Яку роль Ур'кьо відіграє серед жерців Темного Списа?",a="Ур'кьо визнано найбільшим жерцем племені Темного Списа і його першим духовним провідником: він дбає, щоб звичаї предків, обряди й практики вуду переходили до наступного покоління.",al={"становище ур'кьо","найбільший жрець племені"}}},fp="6,376,33.451.0,26.436.0,14.218.0,24.190.0,33.220.0,65.262.0,44.174.0,50.211.0"}
P.entries["npc:uzzek"] = {n="Уззек",s="Уззек — загартований у боях оркський ветеран, що стоїть трохи на південний захід від Далекої Дозорної Застави в Пустках. Переживши безліч сутичок по всьому Калімдору, тепер він допомагає оцінювати й гартувати багатообіцяльних воїнів Орди, що мандрують посушливими рівнинами.",h="Уззек — загартований у боях оркський ветеран, що стоїть трохи на південний захід від Далекої Дозорної Застави...",kw={"уззек","далека дозорна застава","ветеран","воїн","дуротар","пустки"},ang={["class:Warrior"]="Уззек — важливий наставник на вашому шляху: він випробовує вашу витримку й оборонну майстерність, коли ви покидаєте перші тренувальні угіддя й виходите в широкі Пустки.",["faction:Horde"]="Уззек біля Далекої Дозорної Застави — один із ветеранів-оборонців, що пильнують вразливий кордон між Дуротаром і дикою саваною."},sec={{t="Ветеран рівнин",b="Розташувавшись на південний захід від Далекої Дозорної Застави на східному кордоні Пусток, Уззек уособлює незламну витримку бійців передової Орди. Пройшовши жорстокі бої недавніх воєн, він став наставником і суддею випробувань для молодших воїнів, які прагнуть опанувати мистецтво оборони. Щоб довести себе Уззекові, треба випробувати свою міць у сутичках із дикими звірами й нападниками, що дошкуляють цьому посушливому переходу."}},faq={{q="Хто такий Уззек?",a="Уззек — досвідчений орк-воїн, що стоїть у східних Пустках, трохи на південний захід від Далекої Дозорної Застави. Він наставляє молодих воїнів Орди, які опановують основи оборонного бою.",al={"хто такий уззек","лор уззека","уззек нпс"}},{q="Де знайти Уззека?",a="Він на кручах трохи на південний захід від Далекої Дозорної Застави, звідки видно дорогу з Дуротару в Пустки.",al={"місце уззека","де уззек","знайти уззека"}},{q="Яку роль Уззек відіграє для воїнів Орди?",a="Уззек перевіряє молодих воїнів на витривалість і вміння стояти на своєму, дає їм випробування на кшталт «Шляху оборони», а потім посилає до інших досвідчених майстрів, як-от Тун'ґрім Файрґейз.",al={"завдання воїна уззек","шлях захисту уззек"}}},fp="5,250,21.440.0,13.188.0,23.124.0,45.200.0"}
P.entries["npc:valstag-ironjaw"] = {n="Валстаґ Айронджо",s="Валстаґ Айронджо — дворфійський вояк з Айронфорджа, що служить у Фортеці Менетіл серед прибережних боліт Багнокраю. Стикаючись із нагальними небезпеками, які загрожують торговим шляхам між Лох Моданом і узбережжям, він допомагає захищати шляхи краю й повідомляє залогу гавані про місцеві загрози.",h="Валстаґ Айронджо — дворфійський вояк з Айронфорджа, що служить у Фортеці Менетіл серед прибережних боліт...",kw={"валстаґ айронджо","фортеця менетіл","гавань менетіл","багнокрай","дун алґаз","драконяча паща"},ang={["faction:Alliance"]="Валстаґ допомагає тримати відкритою важливу артерію постачання між Гаванню Менетіл і горами Каз Модану, без якої не обійтися торгівлі й подорожам Альянсу.",["race:Dwarf"]="Для дворфійських шукачів пригод, що спускаються з Айронфорджа чи Лох Модану, Валстаґ уособлює передову залогу, що тримає важливе, обмите дощами західне узбережжя."},sec={{t="Служба у фортеці",b="Валстаґ Айронджо, якого можна знайти у Фортеці Менетіл у Гавані Менетіл, належить до дворфійської залоги, що наглядає за низовинами. Навколишні болота сповнені небезпек — від ворожих орків Драконячої Пащі до ненажерливої звірини, — тож зв'язок і постачання тут підтримувати нелегко. Валстаґ допомагає налагоджувати оборону вздовж головних шляхів, надто підступного проходу крізь Дун Алґаз до Лох Модану."},{t="Захистити перевал",b="Підступну Алґазьку тіснину заполонили вороги, тож мандрівники й валки з припасами між Гаванню Менетіл і Лох Моданом постійно в небезпеці. Валстаґ посилає вправних шукачів пригод проти розбійників і орків, що засіли на перевалах, і передає важливі військові відомості між передовими розвідниками й командирами на кшталт Капітана Стаутфіста."}},faq={{q="Де знайти Валстаґа Айронджо?",a="Валстаґ Айронджо перебуває у Фортеці Менетіл — кам'яній твердині в Гавані Менетіл, у західному Багнокраї.",al={"місце валстаґа","де валстаґ айронджо","валстаґ айронджо нпс"}},{q="Яку роль Валстаґ відіграє в Багнокраї?",a="Він — дворф з Айронфорджа, що служить у фортеці й допомагає з обороною: стримує загрози на гірських шляхах, які ведуть назад у дворфійські землі.",al={"що робить валстаґ","роль валстаґа"}},{q="Чому перевал до Лох Модану так його турбує?",a="Ущелина Алґаз — життєво важливий сухопутний шлях, що з'єднує прибережну Гавань Менетіл з Лох Моданом і Айронфорджем. Вороги, що перекривають гірський перевал, загрожують відрізати постачання харчів, переміщення військ і припасів.",al={"чому перевал алґаз","валстаґ лох модан"}},{q="Хто такий Капітан Стаутфіст?",a="Капітан Стаутфіст — старший офіцер у Фортеці Менетіл. Валстаґ узгоджує з ним дії, щоб військові звіти й донесення про безпеку доходили до командування гарнізону.",al={"капітан стаутфіст зв'язок","хто такий стаутфіст"}}},fp="15,317,16.445.0,17.373.0,33.124.0,44.170.0,53.217.0,25.173.0"}
P.entries["npc:vanndar-stormpike"] = {n="Ванндар Стормпайк",s="Ванндар Стормпайк — лютий дворф, гірський король, що командує Експедицією Стормпайків із північної фортеці Дун Балдар. Шукаючи в крижаних вершинах Долини Альтерак давні реліквії й сировину, він очолює непримиренну війну Альянсу проти орків клану Морозного Вовка.",h="Ванндар Стормпайк — лютий дворф, гірський король, що командує Експедицією Стормпайків із північної фортеці...",kw={"ванндар стормпайк","дун балдар","долина альтерак","експедиція стормпайків","гірський король","клан морозного вовка"},ang={["faction:Alliance"]="Ванндар — головний командувач на альтерацькому фронті: він тримає північні вали й просуває землі Альянсу в дикі гори.",["race:Dwarf"]="Для дворфів Айронфорджа Ванндар уособлює незламний дух Гірських Королів, що борються за давню спадщину й шанують Гільдію Дослідників."},sec={{t="Володар Дун Балдара",b="Досвідчений гірський король Айронфорджа, Ванндар Стормпайк очолює дворфійські розкопки в Долині Альтерак. Після Третьої війни він повів Варту Стормпайків у північні гори на пошуки прихованих мінеральних багатств і давно втрачених артефактів титанів. Облаштувавшись в укріпленому редуті Дун Балдар, Ванндар вважає долину правом предків і законною землею Альянсу. Він керує військовими заставами, оборонними бункерами й наступами на передовій із похмурою дворфійською рішучістю, переконаний, що поки він тут, ніхто не засурмить відступу."},{t="Війна за крижаний перевал",b="Невтомні копання й розвідки Ванндара зачепили саму домівку клану Морозного Вовка й розпалили жорстоку гірську війну. Попри вимоги орків відступити, Ванндар не поступається ані п'яддю землі, присягаючись, що Долина Альтерак належатиме дворфам. Зі своєї тронної зали глибоко в Дун Балдарі, в оточенні маршалів і охоронців, він особисто керує обороною від набігів Морозного Вовка, посилаючи поборників Альянсу проривати ворожі лінії й раз і назавжди здобути долину."}},faq={{q="Хто такий Ванндар Стормпайк?",a="Ванндар Стормпайк — дворф, гірський король і верховний командувач Експедиції Стормпайків. З Дун Балдара він керує бойовими діями Альянсу в Долині Альтерак.",al={"хто такий ванндар","лор ванндара стормпайка","лідер стормпайків"}},{q="Чому Ванндар воює в Долині Альтерак?",a="Ванндар привів Експедицію Стормпайків у Долину Альтерак, щоб відшукати давні реліквії й добувати природні багатства. Його відмова зректися цих претензій втягнула дворфів у криваву війну з місцевими орками клану Морозного Вовка.",al={"чому дворфи в альтераку","мотив ванндара","мета стормпайків"}},{q="Де перебуває Ванндар?",a="Він командує військом із північної твердині Дун Балдар у Долині Альтерак, під захистом дворфійських бункерів, маршалів і добірної варти.",al={"де ванндар","місце ванндара","бос дун балдара"}},{q="Хто головний ворог Ванндара?",a="Його головний супротивник — Дрек'Тар, вождь і старійшина-шаман клану Морозного Вовка, який прагне вигнати дворфійських зайд із землі своїх предків.",al={"суперник ванндара","з ким воює ванндар","вожак крижаних вовків"}}},fp="17,279,18.548.0,23.519.0,25.174.0,42.222.0,24.142.0,28.163.0"}
P.entries["npc:varimathras"] = {n="Варіматрас",s="Варіматрас — жахолорд з раси натрезимів, головний поплічник і військовий радник Леді Сильвани Віндраннер. Зазнавши поразки в громадянській війні за Лордерон, він був змушений присягнути на вірність Королеві Баньші й тепер стоїть по праву руку від неї в Королівському Кварталі Андерсіті.",h="Варіматрас — жахолорд з раси натрезимів, головний поплічник і військовий радник Леді Сильвани Віндраннер.",kw={"варіматрас","жахолорд","натрезими","сильвана","андерсіті","королівський квартал"},ang={["class:Warlock"]="Для знавців демонічної магії вигляд високопоставленого натрезима, що служить королеві-нежиті, — вражаюча, хоч і тривожна, демонстрація підкореної волі.",["faction:Horde"]="Присутність жахолорда в Андерсіті — джерело гострої напруги з Оргріммаром, адже Орда десятиліттями виривалася з-під влади тих самих демонічних господарів, яким служив Варіматрас.",["race:Undead"]="Варіматрас уособлює прагматичну готовність Відступників обернути зброю гнобителів проти них самих: тепер він покірно стоїть біля Темної Леді, що вирвала Лордерон з його лап."},sec={{t="Тюремник Короля-Ліча",b="До Третьої війни Варіматрас та інші жахолорди працювали безпосередньо під началом Кіл'джедена, щоб зламати дух Нер'жула й перекувати його на Короля-Ліча. Разом зі своїми братами Детероком і Балназзаром він наглядав за Погибеллю в Лордероні, поки Архімонд вторгався в Калімдор. Коли Легіон зазнав поразки біля Гори Гіджал, тріумвірат лишався в руїнах Столиці Лордерона, нічого не знаючи про загибель свого господаря, аж поки принц Артас не повернувся й не змусив їх сховатися."},{t="Капітуляція демона",b="Коли влада Короля-Ліча над його нежиттю похитнулася, Варіматрас спробував змусити щойно звільнену баньші Сильвану Віндраннер служити новому режиму жахолордів. Сильвана відмовилася й, згуртувавши визволену нежить, розгромила заставу Варіматраса. Опинившись на порозі страти, жахолорд впав на коліна й почав торгуватися за життя, віддавши тактичні таємниці й відомості про укріплення своїх братів в обмін на порятунок. Сильвана погодилася й прив'язала його до служби як живу зброю проти власних родичів."},{t="Брат проти брата",b="To secure Sylvanas's trust, Varimathras was ordered to kill his fellow dreadlord Balnazzar after the conquest of the Capital City. He appeared to obey, but Balnazzar survived the deception. Varimathras then executed the human warlord Grand Marshal Garithos at Sylvanas's command. Now stationed beside Sylvanas's throne, he coordinates military excursions across Lordaeron, though many in the Horde look upon this demonic ally with deep unease."}},faq={{q="Чому демон служить Відступникам?",a="Коли Сильвана Віндраннер під час громадянської війни в Лордероні зібрала військо щойно звільненої нежиті, вона розбила сили Варіматраса. Перед лицем неминучої смерті жахолорд благав про милість і запропонував свою хитрість, військові знання й службу в обмін на життя. Сильвана помилувала його, щоб мати тактика й виконавця своєї волі.",al={"чому демон служить відступникам","чому варіматрас в андерсіті","жахолорд із сильваною"}},{q="Що за істота Варіматрас?",a="Варіматрас — натрезим, тобто жахолорд. Натрезими — розумна, підступна раса демонів, що служить Палаючому Легіону й майстерно підкорює чужий розум, володіє магією тіні та сіє чуму й розбрат.",al={"яка раса варіматраса","чи варіматрас вампір","вид варіматраса"}},{q="Де в Андерсіті стоїть Варіматрас?",a="Він стоїть на підвищенні в Королівському Кварталі Андерсіті, просто поруч із Леді Сильваною Віндраннер, в оточенні королівської варти Відступників.",al={"де варіматрас","місце варіматраса","знайти варіматраса"}},{q="Чи справді Варіматрас убив свого побратима-жахолорда Балназзара?",a="Sylvanas ordered Varimathras to kill Balnazzar as a test of loyalty, and he appeared to obey. The truth behind that encounter is tied to the dreadlords' hidden dealings in Lordaeron.",al={"чи варіматрас убив балназзара","брат варіматраса","табу жахолордів"}},{q="Яку роль Варіматрас відіграв у створенні Погибелі?",a="З наказу Кіл'джедена Варіматрас і його побратими-жахолорди катували полонений дух орка-шамана Нер'жула у Викривленому Нижньому Світі, зламали його розум і ув'язнили в Крижаному Троні, щоб створити Короля-Ліча, а тоді послали його на Азерот.",al={"варіматрас нерзул","як варіматрас створив погибель"}},{q="Чи довіряють Варіматрасу інші лідери Орди?",a="Аж ніяк. Орки, тролі й таурени носять глибокі шрами від демонічної скверни й вважають жахолордів потворними маніпуляторами. Навіть серед Відступників багато хто бачить у Варіматрасі ненадійну зброю на дуже короткому повідку, а не справжнього бойового побратима.",al={"чи орда довіряє варіматрасу","тралл варіматрас","чи варіматрасу довіряють"}}},fp="11,309,23.485.0,19.506.0,23.443.1,36.327.0,37.233.0,46.154.0,59.182.0,55.264.0,45.260.0"}
P.entries["npc:varok-saurfang"] = {n="Варок Саурфанг",s="Верховний Володар Варок Саурфанг — легендарний воїн-орк із клану Блекрок, ветеран Першої, Другої й Третьої воєн. Він — довірений воєначальник Вождя Тралла й гордий бойовий хребет сучасної Орди, хоча в душі несе тяжке каяття за давні звірства.",h="Верховний Володар Варок Саурфанг — легендарний воїн-орк із клану Блекрок, ветеран Першої, Другої й Третьої...",kw={"варок саурфанг","верховний володар","клан блекрок","тралл","орда","криваве прокляття","воїн"},ang={["class:Warrior"]="Воїни шанують Саурфанга як неперевершеного ветерана: його майстерність із сокирою, тактичний хист на полі бою й незламна воля — взірець ідеального солдата.",["race:Orc"]="Для орків Верховний Володар Саурфанг — і найвищий приклад бойової сили, і тверезе нагадування про духовну ціну, яку стягнуло демонічне Криваве Прокляття."},sec={{t="Жива легенда воєн",b="Мало хто з живих воїнів може похвалитися таким бойовим родоводом, як Варок Саурфанг. Член шанованого клану Блекрок, Саурфанг служив разом з Ейтріґґом під проводом Блекгенда, а згодом став довіреним заступником самого Вождя Оргріма Думхаммера. Під час лютих штурмів Стормвінда в Першій війні й жорстоких походів на північ через Передгір'я Гілсбреда та Пригір'я в Другій війні Саурфанга вважали нестримною силою на полі бою. Коли Тралл згуртував розпорошені клани орків, щоб перетнути Велике Море й заснувати Дуротар, Саурфанг знову взявся за зброю: він боронив Калімдор у Третій війні й став оплотом новонародженої Орди."},{t="Тягар крові",b="Хоч Саурфанг — неперевершений герой Орди, ним не керує безрозсудна жага битви. Як і багато хто з його покоління, він доброхіть скуштував демонічної крові Маннорота ще до відкриття Темного Порталу й глибоко шкодує про жорстокості, скоєні під владою Кривавого Прокляття. Після жертви Громмаша Хеллскріма, що звільнила орків, Саурфанг присвятив чимало життя тому, щоб допомагати іншим ветеранам долати провину. Він невтомно боронитиме Орду й утримуватиме владу Тралла перед будь-якою загрозою, але глибоко зневажає паліїв війни й б'ється лише заради честі та збереження свого народу."}},faq={{q="Хто такий Варок Саурфанг?",a="Варок Саурфанг — славетний орк-воїн із клану Блекрок, брат знаменитого Броксіґара і головний воєначальник Орди на службі Вождя Тралла.",al={"лор варока саурфанга","хто такий саурфанг","верховний володар саурфанг"}},{q="У яких війнах воював Саурфанг?",a="Саурфанг воював у Першій, Другій і Третій війнах. Він вів сили Блекрок під час розграбування Стормвінда, був заступником Оргріма Думхаммера в Лордероні й захищав Гору Гіджал разом із військами Тралла.",al={"історія воєн саурфанга","чи саурфанг воював у першій війні","битви саурфанга"}},{q="Як Саурфанг ставиться до минулого Орди?",a="Саурфанг гірко шкодує про звірства, скоєні під прокляттям демонічної крові, особливо про різанину безневинних дренеїв на Дренорі. Ці спогади досі його переслідують.",al={"прокляття крові саурфанга","провина саурфанга перед дренеями","чому саурфанг шкодує про минуле"}},{q="Яку роль Саурфанг відіграє в нинішній Орді?",a="Він — Верховний Володар військ Тралла: стежить за боєготовністю, втілює накази Вождя і як досвідчений наставник опікується молодшими воїнами Орди.",al={"що робить саурфанг тепер","роль саурфанга в оргріммарі"}}},fp="14,307,27.684.0,23.647.0,22.168.0,32.225.0,40.163.0,45.182.0"}
P.entries["npc:velarok"] = {n="Веларок",s="Веларок Віндблейд — самотній людський мечник, що отаборився серед попелу й жужелиці Палючої Ущелини, оточений спотвореними трупами дворфів Темного Заліза. Він прагне помститися місцевим дворфам Темного Заліза за жорстоке вбивство свого батька й вербує мандрівників, щоб викувати зброю відплати. Невгамовна жага помсти визначає все, про що він просить своїх помічників.",h="Веларок Віндблейд — самотній людський мечник, що отаборився серед попелу й жужелиці Палючої Ущелини, оточений...",kw={"веларок","веларок ошуканець","смолоскип відплати","палюча ущелина","чорні дракони","темне залізо"},ang={["race:Dwarf"]="Дворфи Темного Заліза — вороги Айронфорджа, тож клятва чужинця помститися їм легко знайде співчуття серед Бронзбірдів, хоча Палюча Ущелина плодить хитріше зло, ніж саме лише Темне Залізо.",["race:Human"]="Розповідь Веларока про вбитого батька й синову помсту грає на ідеалах синівського обов'язку й праведної відплати, які багато людей щиро шанують."},sec={{t="Синова помста",b="Веларок Віндблейд, якого можна знайти на південний схід від Торієвого Мису, видає себе за скорботного людського воїна, що застряг серед небезпечних безплідних земель Палючої Ущелини. Довкола його табору лежать закривавлені, понівечені трупи дворфів Темного Заліза, які стали на шляху його клинка. Як розповідає Веларок, ці дворфи з клану холоднокровно вбили його батька. Поглинутий ненавистю, він просить мандрівників зібрати матеріали для Смолоскипа Відплати — зачарованої зброї помсти проти Темного Заліза й посіпак Рагнароса."},{t="Ошуканця викрито",b="Історія про вбитого батька — суцільна вигадка. Щойно Смолоскип Відплати повністю зібрано й наснажено, людська ілюзія розсипається, і під нею постає Веларок Ошуканець — хитрий дракон із Чорного драконячого роду. Він маніпулював смертними, щоб ті підточували сили дворфів Темного Заліза на користь задумів його виводку, і тепер, розважившись, милує своїх корисних пішаків: лишає їм через слугу якісь дрібнички й відлітає до Гори Блекрок."}},faq={{q="Хто такий Веларок?",a="Спершу Веларок Віндблейд здається мстивим мечником-людиною, що отаборився на південний схід від Торієвого Мису в Палючій Ущелині й прагне помститися клану Темного Заліза за смерть батька.",al={"хто такий веларок","особа велароку","лор велароку"}},{q="Чому навколо Веларока мертві дворфи?",a="Понівечені останки дворфів Темного Заліза навколо його табору — похмурий доказ кровної помсти, яку він нібито веде проти клану за смерть батька.",al={"мертві дворфи біля веларока","мертві дворфи поруч","тіла у таборі веларока"}},{q="Що таке Смолоскип Відплати?",a="Це зачарований смолоскип, зібраний в ім'я помсти з рідкісних матеріалів зі всієї Палючої Ущелини. Веларок доручає помічникам зібрати частини, сам з'єднує й зачаровує їх, а тоді прив'язує готовий смолоскип до того, хто йому допоміг.",al={"завдання смолоскипа веларока","що таке смолоскип відплати"}},{q="Чому Веларок прикидається людиною?",a="Подоба людини дає йому змогу наймати шукачів пригод з Альянсу й Орди, не викликаючи підозр. Чорні дракони часто вдягають подобу смертних, щоб чужими руками бити по ворогах — як-от по дворфах Темного Заліза, слугах Рагнароса.",al={"чому веларок людина","навіщо обманювати гравців","личина веларока обманщика"}},{q="Куди вирушає Веларок, коли відкриває своє обличчя?",a="Показавши свою справжню драконячу подобу — Веларок Ошуканець, — він злітає й летить до Гори Блекрок, щоб повернутися до свого виводку, а нагородити шукачів пригод, які йому допомогли, лишає свого смертного слугу.",al={"куди полетів веларок","кінець веларока","що буде з веларком"}},{q="Чи нападає Веларок, коли скидає личину?",a="Ні. Веларок вважає мимовільну службу шукачів пригод кумедною і задовільною. Замість знищити їх, він дарує їм життя й дозволяє отримати від слуги дрібні цяцьки.",al={"чи я воюю з веларком","чи веларок стає ворожим"}}},fp="7,383,17.511.0,21.476.2,15.193.2,42.159.2,33.251.1,45.240.2,46.203.2,44.194.2"}
P.entries["npc:velora-nitely"] = {n="Велора Найтлі",s="Велора Найтлі — бронниця-нежить, що живе в Торговому Кварталі Андерсіті. Колись, до падіння королівства, вона славилася як одна з найкращих ковалів Лордерону, а тепер віддає свою холодну майстерність Відступникам і Орді. Попри похмуре існування, вона намагається жартувати — сухо й незворушно, але жарти рідко вдаються.",h="Велора Найтлі — бронниця-нежить, що живе в Торговому Кварталі Андерсіті.",kw={"велора найтлі","бронниця","андерсіті","жорстокі поножі","відступники","ковальство"},ang={["class:Warrior"]="Молодих воїнів Орди, що прагнуть легендарного жорстокого обладунку, відсилають на північ до Велори в Андерсіті — викувати міцні поножі з кісток орків Драконячої Пащі.",["profession:Blacksmithing"]="Велора уособлює живу спадщину легендарної бронницької традиції Лордерону: свою точну металургійну майстерність вона зберегла й у нежитті."},sec={{t="Ковалиця Лордерону",b="До того як Третя війна спустошила північ, Велору Найтлі прославляли по всьому Лордерону як неперевершену бронницю. Нежиття позбавило її життя й тепла, але не зачепило її вміння. Тепер вона працює біля ковадел Торгового Кварталу Андерсіті й співпрацює через континенти з майстрами Орди, як-от Тун'ґрімом Файрґейзом у Пустках. Її коник — посилення важких бойових лат, зокрема кування грізних Жорстоких Поножів із загартованих матеріалів на кшталт гомілкових кісток орків Драконячої Пащі."},{t="Незворушний гумор",b="На відміну від багатьох похмурих родичів-Відступників, які сушать голову над своєю проклятою долею, Велора досі не втратила смаку до жартів. На жаль, смерть, схоже, геть зіпсувала їй уміння вчасно вставити дотеп. Її жарти звучать пласко, моторошно й зовсім не смішно і для живих, і для мертвих, але вона незворушно сипле ними далі, працюючи біля горна."}},faq={{q="Хто така Велора Найтлі?",a="Велора Найтлі — зброярка з Відступників, яку можна знайти в Торговому Кварталі Андерсіті. За життя вона славилася на все королівство Лордерон своїм надзвичайним хистом у ковальстві.",al={"хто така велора","лор велори найтлі","велора найтлі нпс"}},{q="Де знайти Велору Найтлі?",a="Вона в Андерсіті, працює біля горнів і стійок з обладунками в гамірному Торговому Кварталі.",al={"місце велори найтлі","де велора","карта велори найтлі"}},{q="Що пов'язує її з Тун'ґрімом Файрґейзом?",a="Велора — одна з умілих ковалів Орди, яких залучили на допомогу орку-зброяреві Тун'ґріму Файрґейзу в Пустках. Вона кує Жорстокі Поножі для багатонадійних воїнів, які приносять їй гомілкові кістки орків Драконячої Пащі.",al={"велора й тун'ґрім","броня тун'ґрім файрґейз","ланцюжок завдань жорстокої броні"}},{q="Чому в неї такі погані жарти?",a="Велора любить пожартувати, але смерть зіпсувала їй подачу. Помираючи й повстаючи в нежитті, вона втратила справжнє почуття гумору, тож її жарти незграбні, сухі й рідко смішні.",al={"почуття гумору велори","жарти велори","чому велора жартує"}}},fp="13,314,20.520.0,13.346.0,21.188.0,33.108.0,45.205.0,25.196.0"}
P.entries["npc:ventaari-brightwish"] = {n="Вентаарі Брайтвіш",s="Вентаарі Брайтвіш — мешканка Села Тендаль на Острові Зефрас з народу Небороджених. Вона вітає мандрівників з усього Азероту й дає завдання «Дар Небозору».",h="Вентаарі Брайтвіш — мешканка Села Тендаль на Острові Зефрас з народу Небороджених.",kw={"вентаарі брайтвіш","село тендаль","дар небозору","небороджені","острів зефрас","гостинність"},ang={["race:Skyborne"]="Як одна з Небороджених у Селі Тендаль, Вентаарі Брайтвіш допомагає гостям зблизитися з культурою й звичаями Острова Зефрас."},sec={{t="Мешканка Села Тендаль",b="Вентаарі Брайтвіш живе в Селі Тендаль на високих кручах Острова Зефрас і належить до місцевих Небороджених. Хоч вона й має спільне прізвище з Белатааном Брайтвішем, її власні обов'язки — допомагати новоприбулим, що знаходять дорогу до села. Вона гостинна і до Альянсу, і до Орди й долучає гостей до традицій свого народу через завдання на кшталт «Дару Небозору»."}},faq={{q="Хто така Вентаарі Брайтвіш?",a="Вентаарі Брайтвіш — представниця Небороджених у Селі Тендаль на Острові Зефрас. Вона спілкується з гостями й дає завдання «Дар небесного зору».",al={"вентаарі","хто така вентаарі","вентаарі брайтвіш"}},{q="Де знайти Вентаарі Брайтвіш?",a="Її можна знайти в Селі Тендаль на Острові Зефрас.",al={"місце вентаарі","де вентаарі","село тендал вентаарі"}},{q="Чи ворожа Вентаарі до Орди чи Альянсу?",a="Ні. Вентаарі Брайтвіш нейтральна й розмовлятиме із шукачами пригод і з Альянсу, і з Орди.",al={"фракція вентаарі","чи вентаарі дружня","чи орда може говорити з вентаарі"}}},fp="19,162,28.411.0,27.154.0,37.75.0,45.104.0"}
P.entries["npc:verdan-the-everliving"] = {n="Вердан Вічноживий",s="Вердан Вічноживий — велетенський болотяний звір, що чатує глибоко в зелених тунелях Печер Стогонів. Колись він мирно оберігав підземні джерела й рослини, але його спотворило жахіття наяву, що струменіло від сплячого друїда Наралекса. Тепер Вердан служить зіпсованим Друїдам Ікла й люто нападає на всіх, хто забреде в його вологі нори.",h="Вердан Вічноживий — велетенський болотяний звір, що чатує глибоко в зелених тунелях Печер Стогонів.",kw={"вердан вічноживий","печери стогонів","елементаль","друїди ікла","жахіття","наралекс"},ang={["class:Druid"]="Падіння Вердана — трагічне нагадування про те, що буває, коли природних охоронців-елементалів отруює зіпсований Смарагдовий Сон.",["class:Shaman"]="Вердан — дух стихій землі й води, що спотворився й озлобився, тож здолати його означає повернути рівновагу розладнаним стихіям Пусток.",["faction:Horde"]="Печери Стогонів лежать у самому серці Пусток, тож перемогти небезпечних звірів на кшталт Вердана вкрай важливо, щоб захистити довколишні шляхи й поселення."},sec={{t="Охоронець буйних глибин",b="Задовго до того, як Наралекс прийшов сюди, щоб дістатися природних джерел Пусток, Вердан постав із буйного листя, мулу й вологи, що наповнювали печери. Його вважають споконвічним духом-охоронцем підземної оази: це був прадавній лагідний елементаль, що доглядав підземні рослини."},{t="Спотворений Жахіттям",b="Коли Наралекс спробував перетворити сухі Пустки на пишний рай, його обряд розколовся, обернувшись яскравим жахіттям у Смарагдовому Сні. Порча просочилася крізь підземні води й отруїла все живе в печері. Вердан не встояв перед всепроникною напастю: його лагідна вдача зникла, і лишився тільки велетенський ворожий громило, що присягнув захищати божевільних Друїдів Ікла."}},faq={{q="Що за істота Вердан?",a="Вердан — велетенське болотяне чудовисько, елементальна істота, оживлена з рослин, торфу й підземної трясовини. Він давним-давно сам собою постав із буйної флори печер.",al={"вид вердана","що таке вердан","раса вердана"}},{q="Чому Вердан ворожий до шукачів пригод?",a="Колись Вердан був мирним вартовим печер, але кошмар, що струменить від сплячого архідруїда Наралекса, затьмарив йому розум. Тепер, збожеволівши, він бачить у кожному чужинцеві порушника, якого треба розчавити.",al={"чому вердан нападає","вердан ворожий","чи вердан злий"}},{q="Що пов'язує Вердана з Друїдами Ікла?",a="І Вердан, і Друїди Ікла стали жертвами того самого згубного кошмару. Поділяючи це спотворене видіння, Вердан став союзником і охоронцем божевільних друїдів і стереже глибини печер.",al={"вердан друїди ікла","зв'язок вердана з іклом"}},{q="Де в Печерах Стогонів перебуває Вердан?",a="Вердан живе в просторій, порослій мохом залі глибоко в звивистих ходах Печер Стогонів, за кількома зіпсованими ватажками Ікла.",al={"де вердан","місце вердана","як знайти вердана"}},{q="Чи можна Вердана вилікувати чи очистити?",a="Жодного відомого способу очистити Вердана немає. Кошмар глибоко вкоренився в його елементальній подобі, тож шукачам пригод не лишається нічого іншого, як знищити здоровенне чудовисько, щоб безпечно пройти печерою.",al={"чи можна врятувати вердана","очистити вердана","врятувати вердана"}},{q="Чому Вердана звуть Вічноживим?",a="Звідки взялося це прізвисько, невідомо. Вердан — прадавнє болотяне чудовисько, що постало з буйної зелені Печер Стогонів.",al={"чому вічноживий","значення вічноживого","походження імені вердана"}}},fp="21,366,27.311.0,24.418.1,32.171.0,37.216.0,54.216.0,47.137.0,32.198.0,39.115.0"}
P.entries["npc:verna-furlbrow"] = {n="Верна Фурлброу",s="Верна Фурлброу — вигнана зі своєї землі фермерка, що застрягла біля зламаного воза неподалік від північного кордону Вестфолу. Після того як розбійники захопили гарбузове поле її родини, вони з чоловіком спробували втекти до Лісу Елвінн, але опинилися в пастці на небезпечній відкритій дорозі.",h="Верна Фурлброу — вигнана зі своєї землі фермерка, що застрягла біля зламаного воза неподалік від північного...",kw={"верна фурлброу","вестфоллське рагу","стара білявка","садиба дженсенів","кулінарія","вестфол"},ang={["faction:Alliance"]="Застряглі в дорозі Фурлброу — приклад людської ціни занедбаних кордонів Стормвінда, де звичайних городян виганяють із домівок, а королівських солдатів на захист ніхто не посилає.",["profession:Cooking"]="Верна — авторка знаменитого Вестфоллського Рагу: вона вчить кухарів-початківців на прикордонні перетворювати назбиране м'ясо й дикі рослини на поживну страву."},sec={{t="Низка негараздів",b="Колись Верна з чоловіком обробляли власну гарбузову ферму на півночі Вестфолу, але беззаконня, що дедалі більше охоплювало сільські землі, вигнало їх звідти. Коли розбійники заполонили їхню землю, подружжя склало на віз усе, що вдалося, запрягло вірну конячку Стару Білявку й вирушило до безпечного Лісу Елвінн. На лихо, віз зламався зовсім недалеко від покинутої Садиби Дженсенів. Не маючи чим полагодити вісь і як рушити далі, Верна змушена терпіти негоду, набіги розбійників і падальників, покладаючись на мандрівних шукачів пригод, щоб її родина мала що їсти й була під захистом."},{t="Серце домашнього вогнища",b="Хоч Верні тепер доводиться тулитися край дороги, вона зберігає гостинну й винахідливу вдачу. Відома в усьому краї як авторка Вестфоллського Рагу, вона часто ділиться їжею й теплом багаття з мандрівними бідолахами й біженцями, що спізнали таку саму долю. Вона просить перехожих пошукати в полях складники — кабанячі рила, очі мурлоків, окру й жилаве м'ясо стерв'ятників, — щоб наповнити свій казанок і перетворити все, що дає суворе прикордоння, на ситну їжу для знедолених."}},faq={{q="Чому Верна Фурлброу отаборилася при дорозі?",a="Верна з чоловіком утекли зі своєї гарбузової ферми, коли північ Вестфолу заполонили розбійники. Дорогою до Лісу Елвінн, де вони сподівалися знайти прихисток, біля хутора Дженсена в них зламався віз, і вони застрягли на узбіччі.",al={"чому верна на дорозі","місце верни фурлброу","що сталося з верною"}},{q="Ким їй доводиться Фермер Фурлброу?",a="Фермер Теодор Фурлброу — чоловік Верни. Удвох вони обробляли свою садибу у Вестфолі, доки бандити не прогнали їх із землі.",al={"чоловік верни фурлброу","чи фермер фурлброу її чоловік"}},{q="Що таке Вестфоллське Рагу?",a="Вестфоллське Рагу — місцева страва прикордоння, яку вигадала Верна. Вона варить його з рил диких кабанів, жилавого м'яса стерв'ятників, очей мурлоків і бамії з покинутих сусідніх ферм, щоб прогодувати біженців, які застрягли в дорозі.",al={"завдання вестфоллського рагу","рагу верни фурлброу","що готує верна"}},{q="Що сталося з фермою Фурлброу?",a="Фурлброу мали гарбузову ферму на півночі Вестфолу, але організовані бандити вигнали їх із землі, коли в королівстві останнім часом занепав порядок, і подружжю довелося покинути дім і поля.",al={"гарбузова ферма фурлброу","що сталося з фермою фурлброу"}}},fp="14,288,23.640.0,19.534.0,44.223.0,30.132.0,22.216.0,37.200.0"}
P.entries["npc:verner-osgood"] = {n="Вернер Осґуд",s="Вернер Осґуд — коваль Лейкшира, що працює просто біля міської кузні. Розриваючись між замовленнями місцевих жителів і нищівними вимогами військових Стормвінда, він невтомно працює, щоб коні були підковані, а захисники — озброєні, попри безупинні набіги гнолів.",h="Вернер Осґуд — коваль Лейкшира, що працює просто біля міської кузні.",kw={"вернер осґуд","коваль","лейкшир","гноли","йоулер","кузня"},ang={["faction:Alliance"]="Містечка на кшталт Лейкшира виживають завдяки місцевим ремісникам, як Вернер, поки воєнна допомога Стормвінда лишається небезпечно мізерною.",["profession:Blacksmithing"]="Вернер — утілення суворої правди сільського ковальства: він розривається між підковуванням для містян і жорсткими нормами, яких вимагає оборона гарнізону.",["race:Human"]="Осґуд — уособлення незламної стійкості простого люду Королівства Стормвінд, що встоює і проти гнолів, і проти нестатків."},sec={{t="Ковадло Лейкшира",b="Стоячи біля горна в центрі Лейкшира, Вернер Осґуд уособлює надірвану ремісничу основу Гір Редріджу. Його справа — найпростіше спорядження, як-от підкови для місцевих коней, та його запаси раз у раз забирають, щоб кувати зброю й обладунки для Вартових Стормвінда. Королівство розтягує свої кордони, місцевим гарнізонам бракує припасів, тож незалежні ковалі на кшталт Вернера змушені нести на своїх плечах тягар забезпечення оборони краю."},{t="Гнолівська напасть",b="Біди Вернера не обмежуються браком заліза. Гноли, що заполонили пагорби Редріджу, раз у раз нападають на худобу й забирають робочих коней, щойно ті вийдуть за межі міста. Доведений до розпачу руйнуванням свого ремесла, Вернер наполегливо наймає мандрівних шукачів пригод, щоб прорідити зграї грабіжників і вистежити їхнього лютого ватажка — Йоулера."}},faq={{q="Хто такий Вернер Осґуд?",a="Вернер Осґуд — місцевий коваль, що працює в кузні Лейкширу. Він виконує для міста ковальську роботу й кує коней, а заразом намагається встигнути з великими замовленнями спорядження для місцевого гарнізону.",al={"вернер осґуд","коваль лейкшира","хто такий вернер"}},{q="Чому Вернерові бракує підків і заліза?",a="Міські запаси заліза раз у раз реквізують, щоб кувати зброю й обладунки для Варти Стормвінда в Редріджі, і Вернерові ледве лишається металу, щоб доглядати місцевих коней.",al={"у вернера немає заліза","лор завдання ціна підков","чому немає підків"}},{q="Що за клопіт у Вернера з гнолами?",a="Ватаги гнолів-нападників никають довкола Лейкширу й крадуть Вернерових коней, щойно ті відійдуть від міста. Він прагне відплати й безпеки, тож наймає шукачів пригод, щоб знищити цих тварюк.",al={"проблема вернера з гнолами","чому вернер ненавидить гнолів"}},{q="Хто такий Йоулер і чому Вернер хоче його смерті?",a="Йоулер — грізний ватажок місцевих зграй гнолів у пагорбах. Вернер хоче, щоб його вбили, і тоді нападники, які тероризують містечко й ріжуть його коней, утратять злагодженість.",al={"хто такий йоулер","завдання вернера про йоулера"}},{q="Що пов'язує Вернера з Магістратом Соломоном?",a="Вернер працює під цивільною владою Магістрата Соломона в Лейкширі, поєднуючи мирне ремесло з цивільними й військовими потребами, яких вимагає знесилене врядування магістрата.",al={"вернер і магістрат соломон","вернер і керівництво міста"}},{q="Чи має Вернер родину в Стормвінді?",a="Він має спільне прізвище з кількома іншими ремісниками Королівства Стормвінд, як-от Донал і Базіл Осґуди, — це натякає на давній рід людей-ремісників по всьому краю.",al={"родичі вернера","рід осґуд"}}},fp="13,267,22.470.0,18.385.0,21.199.0,41.198.0,46.199.0,48.185.0,50.193.0,37.195.0"}
P.entries["npc:veron-amberstill"] = {n="Верон Амберстілл",s="Верон Амберстілл — дворфійський заводчик баранів, що мешкає на Ранчо Амберстілл на сході Дун Мороґу. Він доглядає витривалих гірських баранів, традиційних їздових тварин Айронфорджа, і пропонує їх умілим вершникам, які заслужили його довіру.",h="Верон Амберстілл — дворфійський заводчик баранів, що мешкає на Ранчо Амберстілл на сході Дун Мороґу.",kw={"верон амберстілл","барани","заводчик","ранчо амберстілл","їздові тварини","дун мороґ","айронфордж"},ang={["faction:Alliance"]="Союзники Айронфорджа, які хочуть опанувати їзду на гірському барані, мусять спершу довести відданість дворфійському королівству, щоб заслужити повагу Верона.",["race:Dwarf"]="Верон утілює глибоку спадщину вашого народу з гірськими звірами, надаючи звичайних і прудких баранів, на яких покладається кожен дворфійський шукач пригод, щоб долати Каз Модан."},sec={{t="Володар їздових тварин",b="Серед припорошених снігом пагорбів східного Дун Мороґу Верон Амберстілл наглядає за уславленим поголів'ям Ранчо Амберстілл. Гірські барани ідеально пасують до підступних схилів Каз Модану: твердо стоять на ногах і мають густу шерсть проти укусів гірських заметілей. Верон розводить і навчає цих звірів носити дворфійських розвідників, горян і мандрівних шукачів пригод. Поки своїм дворфам він охоче дає звичайних і прудких їздових тварин, чужинці мусять довести непохитну вірність престолу Айронфорджа, перш ніж він розлучиться з кимось зі свого дорогоцінного стада."}},faq={{q="Хто такий Верон Амберстілл?",a="Верон Амберстілл — дворф-заводчик і продавець їздових тварин на Ранчо Амберстілл у Дун Мороґу. Він вирощує витривалих гірських баранів для королівства Айронфордж і продає їх гідним вершникам.",al={"верон амберстілл","хто такий верон","торговець баранами амберстілл"}},{q="Чи можуть не-дворфи купити баранів у Верона?",a="Так, але лише якщо здобули звеличену репутацію в Айронфорджі. Дворфи можуть купувати його баранів без перешкод, а чужинці мають спершу довести, що вони вірні оборонці гірського королівства, — лише тоді Верон довірить їм своїх тварин.",al={"чи люди можуть купити баранів","баран-їздовий для не дворфів","репутація айронфорджа для барана"}},{q="Де перебуває Верон Амберстілл?",a="Ви знайдете його надворі на Ранчо Амберстілл, що сховалося серед пагорбів східного Дун Мороґу, трохи на північний схід від Кар'єру Гол'Болар.",al={"місце верона","де верон","де знайти верона амберстілла"}},{q="Чому дворфи їздять на баранах, а не на конях?",a="Гірські барани мають густе руно, міцну статуру й надзвичайне чуття рівноваги, тож вони куди краще за звичайних коней пристосовані до крижаних вітрів і стрімких скельних уступів Дун Мороґу й довколишніх вершин.",al={"чому дворфи їздять на баранах","лор дворфійських їздових","лор гірських баранів"}}},fp="16,241,20.563.0,24.193.0,41.228.0,34.143.0,43.213.0"}
P.entries["npc:veronica-nials"] = {n="Вероніка Найлс",s="Капітан Вероніка Найлс — офіцер армії Стромґарда, що служить у Притулку в Аратійському нагір'ї. Серед розвалу королівства вона керує обороною проти Синдикату й огрів, що заполонили загиблу столицю.",h="Капітан Вероніка Найлс — офіцер армії Стромґарда, що служить у Притулку в Аратійському нагір'ї.",kw={"вероніка найлс","стромґард","притулок","синдикат","аратійське нагір'я","огри"},ang={["faction:Alliance"]="Капітан Найлс уособлює трагічну дійсність північного Альянсу: розколоті, відрізані королівства борються за саме виживання й не можуть дати сусідам-союзникам справжньої допомоги.",["race:Human"]="Для людей Найлс — символ незламної бойової гордості Стромґарда, що не кидає прадідівського королівства Аратор попри нищівну перевагу ворога."},sec={{t="Захисниця розбитого королівства",b="Після Третьої війни людське королівство Стромґард розпалося, і його рештки ледве виживають, протистоячи навалі огрів-Каменекулаків і підступам Синдикату. Капітан Вероніка Найлс — одна з головних командирок уцілілих захисників Стромґарда в Притулку. Маючи наказ тримати рубіж, вона спрямовує героїв Альянсу проти ключових ватажків Синдикату, як-от Лорда Фалконкреста й чорнокнижника Мареза Каула, і водночас намагається повернути значки полеглих вояків, щоб їхні скорботні родини змогли попрощатися."},{t="Відхилене прохання",b="Капітан Найлс віддана лише своїй пошматованій батьківщині. Коли Раґ Ґармасон і дворфійські захисники Дун Модра благали Стромґард про допомогу після того, як диверсанти Темного Заліза сплюндрували Міст Тандол, Найлс мусила їм відмовити. Скуті честю й обов'язком, її вояки не можуть виділити жодного клинка поза Аратійським нагір'ям, доки їхнє власне прадідівське королівство під окупацією."}},faq={{q="Хто така Вероніка Найлс?",a="Вероніка Найлс — людина, капітан війська Стромґарда. Вона служить у Притулку й керує збройним опором проти лазутчиків Синдикату та огрів, що захопили Аратійське нагір'я.",al={"хто така вероніка найлс","капітан найлс","капітан притулку"}},{q="Чому Капітан Найлс не хоче допомогти Дун Модру й Мосту Тандол?",a="Хоча дворфи, що утримують Міст Тандол, відчайдушно потребують підкріплення проти клану Темного Заліза, Найлс не може виділити жодного вояка. Стромґард на межі цілковитої загибелі, і обов'язок велить її силам повністю зосередитися на відвоюванні власного занепалого королівства.",al={"прохання до альянсу про тандол","чому немає допомоги дворфам","завдання благання до альянсу"}},{q="Навіщо Найлс значки Стромґарда?",a="Синдикат платить винагороду за значки Стромґарда, зняті з убитих вояків. Найлс просить шукачів пригод з Альянсу забрати ці вкрадені значки в головорізів Синдикату, щоб вона могла підтвердити загибель і сповістити родини полеглих оборонців.",al={"значки стромґарда","навіщо збирати значки","завдання значків"}}},fp="14,246,26.543.0,13.396.0,22.199.0,59.284.0,42.247.0"}
P.entries["npc:vesprystus"] = {n="Веспристус",s="Веспристус — майстер польотів, нічний ельф, що перебуває на пристані Селища Рут'теран біля підніжжя Тельдрассила. Він наглядає за сідалом вишколених гіпогрифів, що переносять мандрівників між великим Світовим Деревом і материковим Калімдором.",h="Веспристус — майстер польотів, нічний ельф, що перебуває на пристані Селища Рут'теран біля підніжжя...",kw={"веспристус","майстер польотів","гіпогрифи","селище рут'теран","тельдрассил","темне узбережжя","обердайн"},ang={["faction:Alliance"]="Веспристус — життєво важлива ланка для будь-якого мандрівника Альянсу, що прибуває на пристань Тельдрассила й потребує швидкої переправи до прибережного Темного Узбережжя.",["race:NightElf"]="Для молодих нічних ельфів — шукачів пригод, що вперше покидають Тельдрассил, Веспристус часто той, хто відправляє їх у політ назустріч першому погляду на материковий Калімдор."},sec={{t="Доглядач сідала Рут'терана",b="Умостившись біля південного підніжжя Тельдрассила в Селищі Рут'теран, Веспристус доглядає гіпогрифів, що з'єднують відокремлене ельфійське віття з рештою світу. Хоч магічний портал веде з Рут'терана просто до міста Дарнасус у кронах угорі, польоти на гіпогрифах дають швидку переправу до Темного Узбережжя й материка. Веспристус працює в злагоді з майстром польотів в Обердайні по той бік протоки, забезпечуючи безпечний шлях вартовим, посланцям і шукачам пригод, що вирушають у Калімдор."}},faq={{q="Куди Веспристус переправляє мандрівників?",a="Веспристус сполучає Селище Рут'теран з портом Обердайн на узбережжі Темного Узбережжя, просто через воду. З Обердайна мандрівники можуть пересісти на інші гіпогрифові маршрути на південь, до Ашенвалю та інших осель нічних ельфів по всьому Калімдору.",al={"куди веспристус перевозить","маршрути веспристуса","шлях польоту рут'теран"}},{q="За якими істотами доглядає Веспристус?",a="Він опікується гніздовищем вірних гіпогрифів нічних ельфів — прадавніх крилатих звірів, що походять із півночі Калімдору. Нічні ельфи віддавна розводять гіпогрифів і товаришують із ними, щоб мандрувати над кронами лісів і скелястими узбережжями.",al={"які звірі у веспристуса","тварини веспристуса","на чому він літає"}},{q="Як дістатися до Дарнасуса від Веспристуса?",a="Щоб дістатися до Дарнасуса із Селища Рут'теран, летіти не треба. Трохи вище стежкою від гніздовища Веспристуса стоїть мерехтливий рожевуватий портал, який миттю переносить мандрівників нагору, до міста в кронах.",al={"як дістатися дарнасу від веспристуса","веспристус до дарнасу","шлях до дарнасу"}}},fp="10,231,30.511.0,36.250.0,36.220.0,56.205.0"}
P.entries["npc:vidra-hearthstove"] = {n="Відра Гартстоув",s="Відра Гартстоув — дворфійська куховарка з Корчми «Міцний Лагер» у Телсамарі. Вона славиться місцевими стравами й часто просить мандрівних шукачів пригод назбирати тутешніх складників для своїх знаменитих кров'янок.",h="Відра Гартстоув — дворфійська куховарка з Корчми «Міцний Лагер» у Телсамарі.",kw={"відра гартстоув","корчма міцний лагер","телсамар","куховарка","кров'янки","кулінарія"},ang={["profession:Cooking"]="Відра уособлює ситні, сільські кулінарні традиції Каз Модану: із суворих місцевих складників вона готує поживні страви для голодних шукачів пригод і гірських патрулів.",["race:Dwarf"]="Для дворфів, що проходять Телсамаром, кухня Відри — затишний смак домівки, а сама вона чимало робить, щоб у містечку не падав дух."},sec={{t="Кухня «Міцного Лагера»",b="У гамірному теплі Корчми «Міцний Лагер» Відра Гартстоув порядкує на кухні й годує місцевих та мандрівників, що проходять Лох Моданом. Вона має одне прізвище з корчмарем і дбає, щоб Телсамар ніколи не сидів голодним. Її коронна страва — телсамарські кров'янки, ситна дворфійська їжа, для якої потрібне свіже м'ясо дичини з навколишніх нетрів: кабанячі тельбухи, павучий іхор і ведмежатина."}},faq={{q="Хто така Відра Гартстоув?",a="Відра Гартстоув — дворфійка, що живе в Корчмі «Міцний Лагер» у Телсамарі. Вона славиться своєю кухнею, а надто ситними телсамарськими кров'яними ковбасками, якими пригощає відвідувачів і горян, що боронять Лох Модан.",al={"лор відри гартстоув","хто така відра","кухарка стаутлаґера"}},{q="Де знайти Відру Гартстоув?",a="Її можна знайти в Корчмі «Міцний Лагер» у центрі Телсамара, в Лох Модані.",al={"місце відри","де відра гартстоув","корчма стаутлаґер відра"}},{q="Що Відра кладе в телсамарські кров'яні ковбаски?",a="Її знаменитий рецепт вимагає грубого набору частин місцевих звірів: ведмежого м'яса, кабанячих кишок і павучої сукровиці зі звірів, що блукають Лох Моданом.",al={"що в телсамарських ковбасках","складники кров'яної ковбаски","рецепт відри"}}},fp="17,228,25.429.0,25.212.0,37.93.0,59.176.0"}
P.entries["npc:viktori-prism-antras"] = {n="Вікторі Призм'Антрас",s="Вікторі Призм'Антрас — дивакуватий звіздар, що живе в маленькій хатині на схилі над Даркширом. Поки місто довкола поринає в страх і чекання нових жахів, Вікторі всією душею віддається будівництву телескопа, щоб ясно бачити небо. Аби втілити свою мрію, він покладається на відважних мандрівників, які добувають складні деталі за гномськими кресленнями.",h="Вікторі Призм'Антрас — дивакуватий звіздар, що живе в маленькій хатині на схилі над Даркширом.",kw={"вікторі призм'антрас","телескоп","зорі","гномські креслення","даркшир","сутінколісся"},ang={["faction:Alliance"]="Допомога Вікторі — рідкісна мирна справа в Даркширі: ви допомагаєте містянинові Альянсу шукати диво серед суцільної трагедії.",["profession:Engineering"]="Майстри-винахідники оцінять задум Вікторі: його точний оглядовий прилад цілком спирається на витончені гномські креслення.",["race:Gnome"]="Увесь задум Вікторі тримається на винахідливості гнома Коґа Ґлітцспіннера — і це показує, як далеко сягає гномська інженерія навіть у найзанедбаніших людських містечках."},sec={{t="Очі, звернені до неба",b="Оселившись на схилі одразу за сідалом грифонів, Вікторі Призм'Антрас цілими днями вдивляється вдалину з мороку Сутінколісся. Серед набігів нежиті, ненажерливих павуків і повзучих тіней його пристрасть лежить далеко за задушливими кронами. Він мріє збудувати чудовий оптичний телескоп, який чітко наблизить зорі й подарує тиху втечу від страху, що поглинає містечко."},{t="Гномські креслення й розкидані деталі",b="Зібрати такий тонкий прилад у проклятому лісі — справа непроста. Вікторі працює за кресленнями свого друга-гнома Коґа Ґлітцспіннера. Щоб завершити пристрій, він просить перехожих розшукати рідкісні матеріали для лінз і механічні корпуси — від тонко шліфованого скла до металевих лінз, розкиданих небезпечними землями."}},faq={{q="Хто такий Вікторі Призм'Антрас?",a="Вікторі — ексцентричний звіздар-людина, що живе в Даркширі. Нагальні політичні й надприродні загрози містечку його не обходять: він одержимий лише тим, щоб збудувати потужний телескоп і вивчати зорі.",al={"хто такий вікторі","лор вікторі призм'антраса","вікторі сутінколісся"}},{q="Де в Даркширі знайти Вікторі?",a="Він живе в невеликій дерев'яній хатині на пагорбі, одразу за майстром грифонів Даркширу, — праворуч, як підніматися стежкою.",al={"місце вікторі призм'антраса","де вікторі","знайти вікторі в даркширі"}},{q="Що намагається збудувати Вікторі?",a="Вікторі намагається збудувати астрономічний телескоп за кресленнями свого колеги-гнома Коґа Ґлітцспіннера, і для цього потрібні кілька особливих лінз і деталей.",al={"телескоп вікторі","пристрій поглянь на зірки","що робить вікторі"}},{q="Чому він вивчає зорі із Сутінколісся?",a="Попри темряву й постійний жах, що просякли Сутінколісся, Вікторі поглинула зоряна цікавість. Незаплямована велич нічного неба дає йому розумовий прихисток від занепаду довкола.",al={"чому телескоп даркширу","чому вивчати зорі в сутінколіссі"}},{q="Хто розробив креслення телескопа Вікторі?",a="Креслення розробив Коґ Ґлітцспіннер, винахідливий знайомий гном Вікторі, який надав схеми, потрібні, щоб зібрати оглядовий прилад.",al={"ког ґліцспінер","хто склав креслення телескопа"}},{q="Чи допомагає Вікторі боронити Даркшир?",a="Ні. Вікторі — цивільний учений, а не воїн. Оборону містечка він лишає Командирові Алтеї Ебонлок і Нічній Варті, а сам віддає всі сили астрономії.",al={"чи вікторі нічний вартовий","чи вікторі б'ється"}}},fp="20,359,21.420.0,38.354.0,28.239.0,38.127.0,32.195.0,43.227.0,47.167.0,35.207.0"}
P.entries["npc:viscous-fallout"] = {n="В'язкий Осад",s="В'язкий Осад — осквернений водяний елементаль, що блукає опроміненими коридорами Гномреґана. Колись чистий дух, що жив у прозорих підземних водах міста, він перетворився на отруйну потвору через згубний радіоактивний викид, який влаштував Мехінженер Термаплаґ.",h="В'язкий Осад — осквернений водяний елементаль, що блукає опроміненими коридорами Гномреґана.",kw={"в'язкий осад","водяний елементаль","радіація","термаплаґ","гномреґан"},ang={["class:Druid"]="Друїди бачать у цій істоті живу рану на тілі природи — жахливий наслідок безрозсудного промислового забруднення, що просочується в природні підземні води.",["class:Shaman"]="Шаман упізнає спотворення стихійного світу: у В'язкому Осаді він побачить чистого духа води, доведеного до божевілля й оскверненого штучними отруйними відходами.",["race:Gnome"]="Для гномів В'язкий Осад — трагічне нагадування про шкоду, якої Мехінженер Термаплаґ завдав їхній домівці, отруївши навіть чисті підземні джерела, що колись живили Гномреґан."},sec={{t="Забруднений дух",b="До падіння Гномреґана столиця гномів покладалася на складні, витончені водні системи й чисті підземні водоносні шари, які живили й рухали її механічні дива. У цих чистих водах мирно жив самотній водяний елементаль. Коли за підступною порадою Мехінженера Термаплаґа відкрили радіаційні клапани, щоб знищити трогів-загарбників, хімічне зараження просочилося глибоко в міські резервуари, затиснуло елементаля в пастку й зіпсувало саму його суть."},{t="Агонія в стоках",b="Тепер ця істота — не більше ніж жива калюжа отруйного мулу, що безцільно дрейфує опроміненими нижніми проходами. Ставши втіленням зради Термаплаґа, В'язкий Осад кидається на все, що трапляється на шляху, поглинутий безперервним болем і люттю. Знищити його — похмура необхідність для тих, хто спускається в Гномреґан, щоб очистити отруєні глибини."}},faq={{q="Що таке В'язкий Осад?",a="В'язкий Осад — водяний елементаль, проміжний бос у зруйнованому місті Гномреґан. Колись він був чистим духом води з глибоких водоносних шарів міста, але його вщент отруїли токсичний мул і радіоактивні опади.",al={"хто такий в'язкий осад","лор в'язкого осаду","що за моб в'язкий осад"}},{q="Як він став зіпсованим?",a="Коли Гномреґан за підступною порадою Мехінженера Термаплаґа залили радіацією, щоб відбити навалу трогів, заражені стоки проникли в міський водогін і водоносні шари. Ув'язнений водяний елементаль увібрав смертоносну хімічну юшку й перетворився на їдке, опромінене страхіття.",al={"чому він зелений","чому елементаль отруйний","як створили в'язкий осад"}},{q="Де в Гномреґані він блукає?",a="В'язкий Осад патрулює нижні опромінені переходи й стічні канали під головними вхідними шляхами Гномреґану, часто гублячись серед звичайних слизів-мутантів і токсичних відходів, що заполонили ці місця.",al={"місце в'язкого осаду","де знайти в'язкий осад","як знайти в'язкий осад"}},{q="Чому він ворожий?",a="Елементаля довели до божевілля безупинні муки й отруйна скверна. Позбавлений природної чистоти, він люто кидається на кожну живу істоту, що вдереться в заражені водойми.",al={"чому він нападає","чи можна його врятувати"}},{q="Чи пов'язаний він якось з Айронфорджем?",a="Гноми-біженці в Містечку Майстрів в Айронфорджі пам'ятають складну систему водогонів, що колись живила Гномреґан. Предмети, пов'язані з водогоном, як-от Гідротростина, тісно пов'язані з цими зіпсованими залами, і їх прагнуть повернути.",al={"гідрокейн айронфордж","зв'язок із гномами"}},{q="Чи можна елементаля очистити чи вилікувати?",a="Ні, ліків для елементаля немає. Радіація й отруйна хімія так глибоко просякли його тіло, що лише знищення може покласти край його мукам.",al={"чи можна вилікувати в'язкий осад","очистити в'язкий осад"}}},fp="15,254,17.502.0,19.377.0,24.227.0,28.293.0,35.202.0,18.186.0,41.240.0,39.160.0"}
P.entries["npc:vol-jin"] = {n="Вол'джин",s="Вол'джин — вождь тролів Темного Списа і майстерний мисливець тіней. Мешкаючи у Фортеці Ґроммаш поруч із Вождем Траллом, він є довіреним радником Орди й водночас працює над тим, щоб забезпечити своєму вигнаному народові постійний дім у Дуротарі.",h="Вол'джин — вождь тролів Темного Списа і майстерний мисливець тіней.",kw={"вол'джин","вождь","темний спис","тролі","мисливець тіней","фортеця ґроммаш","оргріммар"},ang={["faction:Horde"]="Поруч із Траллом Вол'джин — опора Нової Орди: він дає їй хитромудрі поради та люту відданість тролів із джунглів.",["race:Troll"]="Вол'джин — ваш вождь, що веде Темний Спис крізь вигнання й злигодні з духовною мудрістю та тактичною рішучістю."},sec={{t="Вождь Темного Списа",b="Вол'джин очолив плем'я Темного Списа після трагічної смерті свого батька Сен'джина на прадавньому острівному домі племені. Коли мурлоки, що поклонялися морській відьмі, та людські війська ледь не знищили відлюдне плем'я, втрутилися орки Тралла, і між двома народами зав'язався міцний зв'язок. Залишивши руїни своїх островів, Вол'джин присягнув своїми тролями Новій Орді й повів їх через Велике Море на Калімдор."},{t="Рада в Долині Мудрості",b="Хоч Темний Спис і заснував поселення в Дуротарі, внутрішні зради — насамперед віроломство Залазана на Островах Відлуння — змусили багатьох біженців перебратися на материк, у Село Сен'джин. Більшість часу Вол'джин проводить у Фортеці Ґроммаш в Оргріммарі, безпосередньо надаючи Траллу свою гостру стратегічну пораду та майстерність мисливця тіней. Із серця орківської столиці він наглядає за молодою Ордою, водночас прагнучи повернути своєму народові його законні землі."}},faq={{q="Хто такий Вол'джин?",a="Вол'джин — ватажок і вождь племені тролів Темного Списа. Він вправний мисливець тіней, що представляє свій народ серед провідників Орди, і один із найближчих порадників Вождя Тралла в Оргріммарі.",al={"хто лідер тролів","лор вол'джина","вожак темних списів"}},{q="Де живе Вол'джин?",a="Вол'джин перебуває у Фортеці Ґроммаш, у Долині Мудрості в Оргріммарі, поруч із Вождем Траллом.",al={"де вол'джин","місце вол'джина","знайти вол'джина"}},{q="Чому Темний Спис приєднався до Орди?",a="During the Third War, Thrall's fleet washed ashore on the Darkspear Islands. The orcs allied with the trolls against hostile humans and a fanatical murloc army. After Sen'jin's death, Vol'jin pledged his tribe to Thrall. He stayed behind with the remaining Darkspear and brought them to Durotar a year after the orcs departed.",al={"чому тролі в орді","історія темних списів і орди","тралл і вол'джин"}},{q="Чому Темний Спис не живе на власних островах?",a="Коли плем'я оселилося на Островах Відлуння біля узбережжя Дуротару, друг дитинства Вол'джина, знахар Залазан, збожеволів від темної магії. Залазан поневолив своїх одноплемінників, і Вол'джину з уцілілими тролями Темного Списа довелося тікати на суходіл, до Села Сен'джин.",al={"що сталося з островами відлуння","чому тролі в селі сен'джин","зрада залазана"}}},fp="7,245,26.432.0,31.465.0,15.219.0,24.117.0,37.326.0,53.269.0"}
P.entries["npc:volcor"] = {n="Волкор",s="Волкор — поранений розвідник із нічних ельфів, що опинився в пастці глибоко в Лігві Чорнолісся на півночі Темного Узбережжя. Затиснутий ворожими фурболгами Чорнолісся, він покладається на свого вірного товариша Похмурого кігтя й на допомогу захисників Обердайна, щоб вибратися.",h="Волкор — поранений розвідник із нічних ельфів, що опинився в пастці глибоко в Лігві Чорнолісся на півночі...",kw={"волкор","похмурий кіготь","лігво чорнолісся","фурболги","терентіс","темне узбережжя"},ang={["class:Druid"]="Зв'язок між Волкором і Похмурим кігтем віддзеркалює глибоку спорідненість друїдів зі звірами природи, тож його порятунок — справа природної рівноваги.",["class:Rogue"]="Волкор цінує тактичну майстерність і дає розбійникам змогу тихо оминути вартових Чорнолісся замість покладатися на грубу силу.",["race:NightElf"]="Халепа Волкора показує, яка дедалі більша небезпека загрожує калдореям на Темному Узбережжі, коли колись мирні союзники-фурболги піддаються порчі."},sec={{t="У пастці лігва",b="Вистежуючи зіпсоване плем'я Чорнолісся в їхньому підземному лігві, Волкор потрапив у засідку й зазнав тяжких поранень. Не здатний самотужки пробитися крізь ворожих фурболгів, він послав свого вірного ведмедя-товариша Похмурого кігтя в нетрі Темного Узбережжя, щоб той пошукав допомоги в поселенні Обердайн."},{t="Шлях до волі",b="Коли до Волкора дістаються розвідники, яких підняв на ноги Терентіс, він пропонує два шляхи втечі — залежно від того, у чому сильний рятівник. Прихильники рішучих дій можуть прорубати кривавий шлях крізь захисників печери, а ті, хто вправний у хитрощах, — непомітно прослизнути повз вартових, покладаючись на кмітливість і тиху ходу."}},faq={{q="Де перебуває Волкор?",a="Волкор переховується глибоко в Лігві Чорнолісся — печері фурболгів на півночі Темного Узбережжя, трохи на схід від головної дороги, що веде на північ з Обердайна.",al={"місце волкора","де волкор","знайти волкора"}},{q="Чому Волкор застряг у Лігві Чорнолісся?",a="Він розвідував фурболгів Чорнолісся, коли на нього напали й поранили. Відрізаний від виходу з печери, він не міг без допомоги прослизнути повз ворожих вартових.",al={"чому волкор у печері","що сталося з волкором"}},{q="Хто такий Похмурий кіготь?",a="Похмурий кіготь — вірний ведмідь-супутник Волкора. Опинившись у пастці, Волкор послав Похмурого кігтя шукати допомоги в Обердайні, і зрештою про біду дізнався друїд Терентіс.",al={"хто ведмідь","ведмідь волкора","лор похмурого кігтя"}},{q="Як допомогти Волкору втекти?",a="Волкор дає вам самим обрати спосіб порятунку: можна з боєм пробитися крізь охорону фурболгів у печері або непомітно прокрастися повз неї.",al={"втеча силою чи скритністю","завдання супроводу волкора","врятувати волкора"}},{q="Хто посилає шукати Волкора?",a="Терентіс, друїд нічних ельфів з Обердайна, посилає шукачів пригод на пошуки Волкора, після того як Похмурого кігтя знаходять самого, без господаря.",al={"хто послав шукати волкора","зв'язок із терентісом"}},{q="Яке плем'я фурболгів на нього напало?",a="Плем'я Чорнолісся — зіпсовані фурболги з півночі Темного Узбережжя, що піддалися божевіллю й ворожнечі.",al={"які фурболґи","фурболґи чорнолісся"}}},fp="6,226,18.299.0,16.307.1,24.146.0,39.158.0,16.161.0,31.174.0,28.145.0,36.124.0"}
P.entries["npc:vorn-skyseer"] = {n="Ворн Скайсір",s="Ворн Скайсір — мирний таурен, мешканець Табору Нарачі на Плато Червоної Хмари в Малгорі. Відпочиваючи серед наметів табору, він вітає молодих шукачів пригод, що починають свій шлях, і знайомить їх із місцевим життям.",h="Ворн Скайсір — мирний таурен, мешканець Табору Нарачі на Плато Червоної Хмари в Малгорі.",kw={"ворн скайсір","табір нарачі","гостинність","плато червоної хмари","таурени","малгор"},ang={["faction:Horde"]="Ворн — приклад спокійної та сталої вдачі рівнинних племен, що зібралися під проводом Кайрна Бладгуфа, аби збудувати постійний дім.",["race:Tauren"]="Для молодих тауренів на Плато Червоної Хмари Ворн Скайсір часто стає одним із перших знайомих, заспокійливих облич, що вітають їх перед кроком у ширше життя Малгору."},sec={{t="Привітне обличчя в Таборі Нарачі",b="Табір Нарачі на Плато Червоної Хмари має у Ворні Скайсірі неформального привітного господаря для молодих тауренів. Поки ті проходять обряди посвяти, перш ніж вирушити в ширші долини Малгору, Ворн дарує добре слово й гостинність і допомагає новоприбулим освоїтися в таборі."},{t="Відсторонений спостерігач",b="Ворн не воїн. Оборону табору він лишає його сміливцям, а сам веде тихе, неквапливе життя, задоволений тим, що пильнує мирні рівнини своєї батьківщини."}},faq={{q="Хто такий Ворн Скайсір?",a="Ворн Скайсір — старійшина з Табору Нарачі в Малгорі. Передусім він вітає молодих тауренів-воїнів, які починають свої перші обряди на Плато Червоної Хмари.",al={"лор ворна скайсіра","хто такий ворн","ворн малгор"}},{q="Де знайти Ворна Скайсіра?",a="Він відпочиває просто неба серед наметів Табору Нарачі, на Плато Червоної Хмари в південно-західному Малгорі.",al={"місце ворна скайсіра","де ворн","ворн табір нараче"}},{q="Які завдання дає Ворн?",a="У завданні «Вітаємо!» він приймає Подарунковий купон Села Бладгуф, вітає того, хто його приніс, і пропонує маленького супутника для мандрів.",al={"завдання ворна","привітальне завдання ворна"}}},fp="12,210,31.291.0,19.159.0,20.166.0,30.110.0,28.154.0"}
P.entries["npc:warcaller-gorlach"] = {n="Воєзвісник Ґорлах",s="Воєзвісник Ґорлах — орк-оповісник, що ходить запорошеними вулицями Оргріммара й скликає поборників Орди на далекі фронти. Як і належить за званням, він збирає мандрівників і бувалих воїнів, щоб ті виконували накази на небезпечних заставах Калімдору й поза ним.",h="Воєзвісник Ґорлах — орк-оповісник, що ходить запорошеними вулицями Оргріммара й скликає поборників Орди на...",kw={"воєзвісник ґорлах","оргріммар","підкріплення","ашенваль","фералас","чумні землі"},ang={["faction:Horde"]="Для поборників Орди, що прагнуть довести свою силу чи шукають настанов за межами Дуротару, Ґорлах чітко вказує дорогу до застав, яким відчайдушно бракує підкріплення."},sec={{t="Голос поклику Вождя",b="Обходячи вулиці Оргріммара, Воєзвісник Ґорлах служить головним оповісником походів і стратегічної оборони Орди. Замість сидіти за столом у гарнізоні, він ходить серед городян і віддає накази просто добровольцям, готовим випробувати себе. Посилає він мисливців у спірні хащі Ашенвалю, скеровує розвідників у дикі нетрі Табору Моджаче у Фераласі чи кидає відчайдушний клич до зброї для далеких походів, як-от у Чумні Землі, — Ґорлах дбає, щоб жоден воїн, що барився в столиці, не сидів склавши руки, поки Орді загрожують вороги на чужині."}},faq={{q="Хто такий Воєзвісник Ґорлах?",a="Ґорлах — мандрівний орк-оповісник в Оргріммарі, який оголошує накази й спрямовує заповзятливих воїнів Орди до важливих бойових зон і далеких рубежів.",al={"ґорлах","хто такий ґорлах","воєзвісник"}},{q="Куди Воєзвісник Ґорлах посилає шукачів пригод?",a="Він спрямовує поборників Орди до різних застав, що потребують допомоги: у ліси Ашенвалю, до Табору Моджаче у Фераласі й на далекі фронти, як-от Чумні Землі.",al={"куди ґорлах посилає","напрямки ґорлаха","завдання ґорлаха"}},{q="Де знайти Воєзвісника Ґорлаха?",a="Він блукає вулицями й долинами Оргріммара, обходить столицю й закликає до зброї.",al={"місце ґорлаха","де ґорлах","знайти ґорлаха"}}},fp="17,260,28.606.0,25.153.0,46.171.0,37.124.0"}
P.entries["npc:warden-thelwater"] = {n="Наглядач Телвотер",s="Наглядач Телвотер — обложений начальник В'язниці, підземного каземату суворого режиму в Стормвінді. Заскочений зненацька, коли серед в'язнів Дефіас спалахнув жорстокий бунт, він тепер відчайдушно наймає вправних шукачів пригод, щоб придушити заколот, доки чутки не дісталися міста нагорі.",h="Наглядач Телвотер — обложений начальник В'язниці, підземного каземату суворого режиму в Стормвінді.",kw={"наглядач телвотер","в'язниця","стормвінд","бунт","базіл тредд","дефіас"},ang={["class:Paladin"]="Для святих воїнів, відданих порядку й справедливості, відчайдушна боротьба Телвотера за відновлення контролю — прямий заклик навести праведну дисципліну серед жорстоких злочинців.",["class:Rogue"]="Розбійники, що заходять до В'язниці на прохання Телвотера, опиняються посеред заплутаних наслідків інтриг Дефіас і підземної тюремної політики.",["faction:Alliance"]="Наглядач Телвотер уособлює хиткий порядок у Стормвінді: він покладається на вірних поборників Альянсу, щоб придушити тюремний бунт, доки той не загрожує мешканцям столиці."},sec={{t="Криза в Каналах",b="Захована під каналами Стормвінда, В'язниця тримає найнебезпечніших покидьків королівства, дрібних злодіїв і політичних змовників. Наглядачеві Телвотеру доручили тримати їх під надійним замком, але організований бунт застав вартових цілком зненацька. В'язні подолали охорону й захопили камери, і Телвотер опинився забарикадованим біля самого входу, ледве стримуючи збройний заколот просто під вулицями столиці."},{t="Правда під замком",b="Щоб паніка не вихлюпнулася на вулиці Стормвінда, Телвотер вирішив упоратися з бунтом якомога тихіше. Організатор утечі, Базіл Тредд, має величезний вплив серед ув'язнених членів Братства Дефіас. Щоб бунт не виказав ширших вад у правлінні Стормвінда, Телвотер покладається на сторонніх найманців: вони мають пробратися в блоки камер, знищити ватажків і непомітно повернути в'язницю під контроль."}},faq={{q="Хто такий Наглядач Телвотер?",a="Наглядач Телвотер — урядовець-людина, що стоїть біля входу до В'язниці в Стормвінді. Він відповідає за цю в'язницю суворого режиму.",al={"телвотер","наглядач в'язниці","хто такий телвотер"}},{q="Що сталося у В'язниці?",a="Серед в'язнів спалахнув злагоджений бунт, який розпалили передусім ув'язнені члени Братства Дефіас. В'язні здолали охорону й захопили корпуси з камерами, і Телвотер із рештою людей опинився притиснутим біля входу.",al={"бунт у в'язниці","що сталося у в'язниці","чому в'язницю зламано"}},{q="Хто очолює бунт у в'язниці?",a="Бунт із глибини в'язниці направляє Базіл Тредд. Він командує в'язнями з Дефіас і наказав раптово вдарити по охоронцях.",al={"хто очолює бунт","лідер в'язниці","хто такий базил тредд"}},{q="Чому Міська варта Стормвінда не втрутилася великими силами?",a="Телвотер хоче владнати лихо без розголосу. Звістка, що найнадійніша в'язниця Стормвінда впала під натиском власних в'язнів, посіяла б паніку по всьому місту, тож він наймає мовчазних шукачів пригод, щоб навели лад усередині.",al={"чому немає вартових","чому наймають шукачів пригод","таємний бунт"}},{q="Кого тут тримають?",a="Тут сидять дрібні шахраї, злодії, убивці й небезпечні політичні бунтівники, передусім високопоставлені члени Братства Дефіас.",al={"в'язні в'язниці","хто у в'язниці","типи злочинців"}},{q="Де знайти Наглядача Телвотера?",a="Він стоїть одразу біля входу до В'язниці, неподалік каналів між Кварталом магів і Соборною Площею в Стормвінді.",al={"місце телвотера","де наглядач","знайти телвотера"}}},fp="16,296,22.486.0,20.477.1,24.164.0,30.250.0,31.166.0,56.235.0,37.149.0,36.147.0"}
P.entries["npc:warlord-goretooth"] = {n="Воєначальник Ґортут",s="Воєначальник Ґортут — орк-командир, що очолює Карґат серед курних пустирів Пустищ. Зі своєї сторожової вежі він керує прикордонними походами Орди проти сусідніх дворфів Темного Заліза й стежить за вулканічною загрозою з Гори Блекрок. У військових справах він суворий, та іноді його можна побачити біля табірного вогнища, де він відпочиває.",h="Воєначальник Ґортут — орк-командир, що очолює Карґат серед курних пустирів Пустищ.",kw={"ґортут","карґат","орда","пустища","темне залізо","гора блекрок","воєначальник"},ang={["class:Warrior"]="Брутальні й прямолінійні накази Ґортута щодо Гори Блекрок дають бойовим звитяжцям нагоду помірятися силами з досвідченими дворфськими легіонерами.",["faction:Horde"]="Воєначальник Ґортут — наріжний камінь присутності Орди в Пустищах: він керує вирішальними операціями проти дворфів Темного Заліза."},sec={{t="Командир Карґата",b="З вершини сторожової вежі Карґата Воєначальник Ланк Ґортут керує діями Орди на ворожому східному кордоні. Карґат — головний плацдарм Оргріммара проти загроз, що чигають у надрах Гори Блекрок і довколишніх ярах. Ґортут наглядає за патрулями, координує розвідницькі загони на кшталт Експедиційного Корпусу Карґата й віддає прямі накази винищувати бійців і ватажків клану Темного Заліза. Коли ж суворий командир спускається зі своєї вежі, він показує легшу вдачу: часто гріється біля табірного вогнища й перекидається жартами з чаклунами-Відступниками, а тоді повертається до служби."},{t="Удар по Темному Залізу",b="Ґортут вважає дворфів Темного Заліза явною й нагальною загрозою інтересам Орди у Східних Королівствах. Замість того щоб займати оборонну позицію, він виношує наступальні плани проти військ Генерала Анґерфорджа й Імператора Даґрана Тауріссана, що окопалися в Глибинах Блекрок. Розуміючи, наскільки серйозна справа — штурм такої прадавньої підземної твердині, він часто радиться у стратегічних питаннях із досвідченими орками на кшталт Ейтріґґа в Оргріммарі, перш ніж дозволити новий наступ на гору."}},faq={{q="Хто такий Воєначальник Ґортут?",a="Воєначальник Ґортут — старший воєначальник Орди в Карґаті, у Пустищах. Він організовує патрулі Орди й керує вилазками проти дворфів Темного Заліза.",al={"воєначальник ґортут","хто такий ґортут","ґортут пустища","командир карґату"}},{q="Яка його роль у Карґаті?",a="Він командує заставою, регулярно посилає в поле Експедиційний Корпус Карґата й віддає накази про операції проти клану Темного Заліза в Глибинах Блекрок.",al={"що робить ґортут","обов'язки ґортута","пост ґортута"}},{q="Чому Ґортут посилає вояків проти Глибин Блекрок?",a="Дворфи Темного Заліза загрожують довколишнім землям і завзято протидіють присутності Орди в цьому краї. Ґортут оголошує винагороди за голови їхніх вояків, високих офіцерів і Генерала Анґерфорджа, щоб послабити їхню владу над горою.",al={"чому вбивати темне залізо","завдання смерть анґерфорджу","ґортут темне залізо"}},{q="Чому Ґортут радиться з Ейтріґґом?",a="Ейтріґґ — досвідчений орк-ветеран, який жив у Горі Блекрок і знає її внутрішні чвари й оборону краще за будь-кого. Перш ніж посилити наступ на твердині Блекрок, Ґортут посилає шукачів пригод по пораду до Ейтріґґа.",al={"ґортут і ейтріґґ","мудрість ейтріґґа","чому говорити з ейтріґґом"}}},fp="17,370,20.631.0,23.528.0,25.175.0,28.187.0,59.248.0,35.254.0"}
P.entries["npc:warmaster-laggrond"] = {n="Воєвода Лаґґронд",s="Воєвода Лаґґронд — досвідчений орк-командир, що стоїть біля входу Орди до Долини Альтерак у Горах Альтерак. Він опікується вербуванням і відзначенням на передовій воїнів, що відгукуються на заклик допомогти клану Морозного Вовка. Його випробування дають бійцям змогу довести свою силу й здобути повагу авангарду Орди.",h="Воєвода Лаґґронд — досвідчений орк-командир, що стоїть біля входу Орди до Долини Альтерак у Горах Альтерак.",kw={"воєвода лаґґронд","долина альтерак","клан морозного вовка","орда","випробування","передова"},ang={["class:Warrior"]="Лаґґронд цінує неприкриту відвагу на передовій і випробовує поборників-новачків, щоб переконатися, що вони встоять проти важких дворфійських обладунків і атак авангарду.",["faction:Horde"]="Воєвода Лаґґронд — ваш перший зв'язковий у війні за Долину Альтерак: він визнає ваші бойові звершення від імені клану Морозного Вовка.",["race:Orc"]="Для орків відгукнутися на заклик Лаґґронда — справа спадщини: обороняти родовий прихисток шанованого клану Морозного Вовка від дворфійського вторгнення."},sec={{t="Командир передової",b="Стоячи на варті серед лютого холоду на порозі Долини Альтерак, Воєвода Лаґґронд організовує війну Орди проти Експедиції Стормпайків. Він дбає, щоб до долини, представляючи клан Морозного Вовка й усю Орду, входили лише вправні бійці."},{t="Шлях честі",b="Лаґґронд випробовує бійців, що прибувають, завданням «Випробування», а тоді посилає їх у саму гущу бою. Поки воїни проливають кров на крижаних вершинах, саме Лаґґронд оцінює їхнє становище й нагороджує тих, хто здобуде славу серед Морозних Вовків."}},faq={{q="Де перебуває Воєвода Лаґґронд?",a="Воєвода Лаґґронд стоїть біля табору Орди коло порталу до Долини Альтерак, високо на засніжених перевалах Гір Альтерак, на північ від Передгір'я Гілсбреда.",al={"місце лаґґронда","де лаґґронд","воєвода біля входу в долину альтерак"}},{q="Яка роль Воєводи Лаґґронда?",a="Він вербує новобранців для війни Орди в Долині Альтерак: перевіряє рекрутів першими бойовими випробуваннями й нагороджує тих, хто здобув визнання клану Морозного Вовка.",al={"що робить лаґґронд","мета лаґґронда","чому говорити з лаґґрондом"}},{q="Що за завдання «Місце випробувань»?",a="Лаґґронд просить охочих приєднатися принести стяг Морозного Вовка з Лігва Диколапів у Долині Альтерак. Так вони доводять свою винахідливість, перш ніж долучитися до походу.",al={"місце випробувань орди","початкове завдання лаґґронда"}},{q="Чому Орда воює в Долині Альтерак?",a="Клан Морозного Вовка, вигнаний під час Першої війни, віддавна вважає долину своїм домом. Варта Стормпайків, дворфійська експедиція Альянсу, вдерлася в цей край у пошуках реліквій і земель, і це розпалило запеклу війну за територію.",al={"чому долина альтерак","війна крижаних вовків","конфлікт долини альтерак"}},{q="Чи можуть гравці Альянсу спілкуватися з Воєводою Лаґґрондом?",a="Ні. Воєвода Лаґґронд — відданий поборник Орди й нападе на будь-якого чужинця з Альянсу, що підійде до його гірської застави.",al={"чи може альянс говорити з лаґґрондом","лаґґронд ворожий"}}},fp="18,328,19.263.0,17.270.0,36.176.0,34.192.0,34.168.0,44.252.0,54.141.0"}
P.entries["npc:warsong-outrider"] = {n="Передовий Вершник Бойової Пісні",s="Передовий вершник Бойової Пісні вартує на спірній дорозі, що веде з Ашенвалю на схід, до Азшари, і пильнує прикордоння Орди. Вона — передова розвідниця клану Бойової Пісні: стежить за мандрівниками й передає важливі відомості до передових таборів. Хоч вона озброєна й пильнує проти вилазок нічних ельфів, першою не нападає, якщо її не зачепити.",h="Передовий вершник Бойової Пісні вартує на спірній дорозі, що веде з Ашенвалю на схід, до Азшари, і пильнує...",kw={"передовий вершник","бойова пісня","розвідниця","азшара","прикордоння","ашенваль"},ang={["faction:Alliance"]="Хоч ця розвідниця — ворожий боєць, вона не стріляє в мандрівників Альянсу, якщо її не зачепити, тож обережні шукачі пригод можуть пройти повз неї неушкодженими.",["faction:Horde"]="Такі передові вершники, як вона, підтримують хиткі шляхи постачання й розвідки, що з'єднують спірні лісозаготівлі Ашенвалю з дикими узбережжями Азшари."},sec={{t="Очі на східному прикордонні",b="Прикордонні землі між Ашенвалем і зруйнованими краями Азшари сповнені небезпек. Діючи далеко від укріпленої безпеки Застави Розщепленого Дерева чи лісозаготівельних таборів, передовий вершник Бойової Пісні стежить за пересуванням військ і патрулює цей шлях. Озброєна луком і отруйними жалами, вона готова боронити права Орди на цей край, хоча береже сили й стріляє лише в тих зайд з Альянсу, які самі на неї нападають."}},faq={{q="Де знайти Передового Вершника Бойової Пісні?",a="Вона стоїть на головній дорозі у східному Ашенвалі, що веде просто в сусідню Азшару.",al={"місце передового вершника","де передовий вершник співу війни","карта вершника співу війни"}},{q="Чи нападає Передовий Вершник Бойової Пісні на гравців Альянсу, щойно побачить?",a="Ні. Хоча вона позначена для PvP-боїв за Орду, до перехожих гравців Альянсу вона ставиться нейтрально й відбиватиметься, лише якщо її вдарять першою.",al={"чи вона агресивна","чи вершник нападає на альянс","агресія вершника співу війни"}},{q="Яку роль вона відіграє в діях клану Бойової Пісні?",a="Вона — прикордонна розвідниця, що стежить за кордоном між Ашенвалем і Азшарою, помічає загрози й надсилає звіти з місця через гінців, які доставляють новини проводу клану.",al={"що робить вершник","мета вершника співу війни","чому вона тут"}},{q="Чи дає перемога над Передовим Вершником Бойової Пісні якісь скарби?",a="Ні, перемога над нею не дає ні здобичі, ні особливого спорядження — лише звільняє дорогу чи зриває розвідку Орди в цьому краї.",al={"здобич вершника співу війни","чи падає здобич","що падає з вершника"}}},fp="16,394,28.454.0,40.120.0,59.172.0,50.185.0,55.134.0"}
P.entries["npc:watch-captain-parker"] = {n="Капітан Варти Паркер",s="Вартовий Паркер — пильний міський вартовий, що несе службу на заставі Три Кути в Горах Редріджу. Йому доручено патрулювати дороги й стежити за агресивними зграями гнолів, тож він — перший рубіж оборони для подорожніх, що прямують до Лейкширу.",h="Вартовий Паркер — пильний міський вартовий, що несе службу на заставі Три Кути в Горах Редріджу.",kw={"вартовий паркер","капітан варти паркер","три кути","гноли","дарсі","лейкшир"},ang={["faction:Alliance"]="Паркер уособлює напружену, самотню оборону прикордоння Альянсу, який не може виділити війська навіть для захисту власних кордонів.",["profession:Herbalism"]="Пошуки свіжих квітів для Дарсі нагадують про тиху цінність рослин, що цвітуть на схилах Редріджу.",["race:Human"]="Для людей королівства Паркер — нагадування про звичайних вартових, які в час загальної кризи з усіх сил утримують віддалені села королівства."},sec={{t="На варті біля Трьох Кутів",b="Стоячи на важливому роздоріжжі, відомому як Три Кути, Паркер пильнує дороги, що з'єднують Ліс Елвінн, Сутінколісся й Редрідж. Військо Стормвінда розпорошене, офіційного підкріплення до краю майже не надходить, тож вартові-одинаки на кшталт Паркера мусять самі тримати перехрестя вільним від розбійників, хижих звірів і гнолів-грабіжників."},{t="Оцінка загрози гнолів",b="Найбільше Паркера турбують табори гнолів, що збираються на північ і схід від його посту. Зграї підбираються дедалі ближче до дороги, тож він посилає дужих подорожніх до Помічника Фелдона в Лейкширі з вісткою про гнолівські сили, що збираються. Дедалі більша зухвалість зграй Редріджу — пряма загроза для валок із припасами й біженців, які шукають прихистку в Лейкширі."},{t="Крихта тепла",b="Життя на самотньому придорожньому посту буває похмурим, та дрібні прояви доброти все ж знаходять шлях до Трьох Кутів. Дарсі, офіціантка з Корчми Лейкшира, надсилає Паркерові гарячий обід, поки той у патрулі. Зворушений, Паркер просить шукача пригод, який приніс обід, узяти букет у травниці Лейкширу й віднести його Дарсі на знак вдячності, — тільки травниці не казати, від кого й для кого ці квіти."}},faq={{q="Де перебуває Вартовий Паркер?",a="Паркер стоїть на Трьох Кутах — перехресті доріг у південно-західній частині Гір Редріджу, біля переходів до Сутінколісся й Лісу Елвінн.",al={"місце паркера","де паркер","знайти вартового паркера"}},{q="Чому Паркер стоїть аж на Трьох Кутах?",a="Йому доручено патрулювати південні дороги й пильнувати зграї гнолів, що підбираються ближче, щоб шляхи подорожніх і постачання до Лейкширу лишалися відкритими.",al={"обов'язки паркера","чому паркер сам","вартовий трьох кутів"}},{q="Які загрози в Редріджі відстежує Паркер?",a="Паркер стежить за зграєю гнолів Редріджу, що загрожує дорозі, і не забуває про ширші небезпеки краю — орків Блекрок у Кам'яній Варті й гнолів Тіньової Шкури біля Вежі Ілґалара.",al={"загрози редріджу","які вороги біля паркера","загроза гнолів редріджу"}},{q="Які стосунки в Паркера з Дарсі?",a="Дарсі працює в Корчмі Лейкшира й посилає Паркерові гарячий обід на його далекий пост. А Паркер у відповідь просить мандрівника, що приніс обід, купити для неї квітів у міського травника, щоб висловити їй вдячність і прихильність.",al={"дарсі й паркер","хто така дарсі","лор завдання безкоштовний обід"}},{q="Чому Стормвінд не шле Паркерові підкріплення?",a="Відколи Король Варіан Рінн зник, а столиця загрузла у внутрішньому політичному безладі, Стормвінд здебільшого лишив Редрідж напризволяще, і місцевим вартовим і магістратам доводиться покладатися на мандрівних шукачів пригод.",al={"чому немає армії стормвінда","допомога стормвінда редріджу","підкріплення паркера"}},{q="Які завдання дає Вартовий Паркер?",a="Паркер просить шукачів пригод доповісти Помічникові Фелдону в Лейкширі про табори гнолів, що збираються біля дороги, і допомагає влаштувати доставку свіжих квітів Дарсі в Корчму Лейкшира.",al={"завдання паркера","завдання від паркера"}}},fp="20,255,25.373.0,26.370.0,17.433.0,30.161.0,57.164.0,46.229.0,41.227.0,57.214.0,36.192.0"}
P.entries["npc:watcher-backus"] = {n="Вартовий Бакус",s="Вартовий Бакус — член Нічної Варти, якому доручено патрулювати похмурі дороги Сутінколісся. Він несе службу на шляху між Даркширом і Маєтком Містмантл і втомленим оком виглядає нежить, що чатує в засідці, та підозрілих подорожніх. Через свій пост він також стає цінним зв'язковим для тих, хто розслідує підозрілі пересування, пов'язані з політичними інтригами Стормвінда.",h="Вартовий Бакус — член Нічної Варти, якому доручено патрулювати похмурі дороги Сутінколісся.",kw={"вартовий бакус","нічна варта","сутінколісся","даркшир","маєток містмантл","зниклий дипломат"},ang={["faction:Alliance"]="Для агентів Альянсу, що шукають зниклого дипломата, Бакус — цінний зв'язковий, який дає відомості просто з прикордоння.",["race:Human"]="Бакус втілює завзяття людей-захисників Сутінколісся: покинуті столицею, вони все одно сповнені рішучості втримати дороги."},sec={{t="Патруль у тіні",b="Як і решта Нічної Варти, Вартовий Бакус веде виснажливу боротьбу з проклятим лісом. Сутінколісся майже не отримує підтримки від гарнізону Стормвінда, тож місцеві добровольці самі стережуть оповиті туманом стежки. Бакус самотньо обходить дорогу, що веде з Даркширу на північ, минає моторошний Маєток Містмантл і відганяє звірів та ходячих мерців."},{t="Очі на дорозі",b="Через відлюдний маршрут Бакус бачить чимало тих, хто оминає Даркшир околицями. Коли королівські слідчі йдуть по сліду високопоставленого дипломата, що зник на півдні, Бакус стає важливим свідком: він пригадує дивну метушню Дефіас довкола Хутора Аддла."}},faq={{q="Хто такий Вартовий Бакус?",a="Вартовий Бакус — людина, вартовий Нічної Варти, знесиленого міського ополчення, яке боронить Даркшир і дороги Сутінколісся.",al={"хто такий бакус","роль вартового бакуса","бакус сутінколісся"}},{q="Де знайти Вартового Бакуса?",a="Він патрулює головну дорогу, що веде на північ від Даркширу до Маєтку Містмантл у Сутінколіссі.",al={"де бакус","місце бакуса","маршрут патруля бакуса"}},{q="Що таке Нічна Варта?",a="Нічна Варта — місцеве добровольче ополчення, яке створили мешканці Сутінколісся для захисту від нежиті, воргенів і диких звірів, коли Стормвінд вивів звідти свої війська.",al={"що таке нічна варта","нічна варта сутінколісся","вартові даркшира"}},{q="Як Бакус пов'язаний із завданням «Зниклий дипломат»?",a="Розслідуючи зникнення дипломата зі Стормвінда, шукачі пригод натрапляють на сліди, що ведуть у Сутінколісся. Бакус пригадує, що останнім часом Дефіас крутилися біля Хутора Аддла, і допомагає переглянути документи, знайдені в їхньому сховку там.",al={"бакус зниклий дипломат","завдання зниклого дипломата бакус"}},{q="Чи пліткують у містечку про Вартового Бакуса?",a="У Даркширі відомо, що його колега, Вартовий Браунелл, потай закоханий у Бакуса, — рідкісна нагода для легких міських пліток серед загального мороку.",al={"бакус браунелл","симпатія вартового браунелла"}},{q="Чому Бакус патрулює сам біля Маєтку Містмантл?",a="Сил Нічної Варти ледве вистачає на весь край. Боєздатних захисників обмаль, тож вартовим доводиться самотужки обходити довгі й небезпечні маршрути.",al={"чому бакус сам","небезпека бакуса"}}},fp="14,365,23.382.0,16.278.1,22.153.0,34.90.0,24.187.0,49.224.1,57.162.0,51.178.0"}
P.entries["npc:watcher-dodds"] = {n="Спостерігач Доддс",s="Спостерігач Доддс — розвідник Нічної Варти, що несе службу на центральному перехресті Сутінколісся. Він тримає самотню придорожню заставу далеко від мурів Даркшира, стежить за жахіттями, що підступають, і доручає мандрівникам проріджувати місцевих велетенських павуків.",h="Спостерігач Доддс — розвідник Нічної Варти, що несе службу на центральному перехресті Сутінколісся.",kw={"спостерігач доддс","нічна варта","перехрестя","павуки","даркшир","сутінколісся"},ang={["faction:Alliance"]="Для мандрівників Альянсу в Сутінколіссі вогнище Доддса — один із небагатьох безпечних прихистків і дружня підтримка на темних шляхах між Даркширом і західними землями."},sec={{t="Варта на перехресті",b="Спостерігач Доддс служить у Нічній Варті під проводом Командира Алтеї Ебонлок і тримає відкритий пост на перехресті, що з'єднує Даркшир з Воронячим Пагорбом і Перевалом Мертвого Вітру. Поки Даркшир тулиться за своїм частоколом, передові вартові на кшталт Доддса живуть на лезі ножа між вовчими зграями, ненажерливими гулями й велетенськими павуками. Зі свого придорожнього табору він стежить за загрозами, що наближаються, і наймає мандрівних найманців проріджувати павуків, які виповзають із підліску, доки ті остаточно не заполонили зарослі шляхи."}},faq={{q="Хто такий Спостерігач Доддс?",a="Він — людина з Нічної Варти, ополчення, створеного, щоб боронити Сутінколісся від нежиті й звірів, які поневіряють край. Він стоїть на центральному перехресті, а не в безпеці Даркширу.",al={"спостерігач доддс","хто такий доддс","доддс сутінколісся"}},{q="Де знайти Спостерігача Доддса?",a="Доддс тримає невеликий табір при дорозі на головному перехресті в центрі Сутінколісся, де розходяться шляхи до Даркширу, Воронячого Пагорба й південних перевалів.",al={"місце спостерігача доддса","де доддс","координати доддса"}},{q="Чому він хоче, щоб убивали павуків?",a="Велетенські отруйні павуки заполонили довколишні ліси й полюють на мандрівників і гінців із припасами на дорозі. Доддс покладається на перехожих шукачів пригод, щоб ті винищували отруйних павуків-тенетників і стежки не стали зовсім непрохідними.",al={"вісьмилапі загрози","завдання павуків доддса","чому вбивати павуків"}},{q="Кому підзвітний Спостерігач Доддс?",a="Він підкоряється Командирові Алтеї Ебонлок, очільниці Нічної Варти, чий штаб у ратуші Даркширу.",al={"командир доддса","хто керує нічною вартою"}}},fp="13,269,23.549.0,21.215.0,31.161.0,32.233.0,33.116.0"}
P.entries["npc:wilder-thistlenettle"] = {n="Вайлдер Тістлнетл",s="Вайлдер Тістлнетл — дворф-шахтар, що похмуро сидить у таверні Дворфійського Кварталу Стормвінда. Він єдиний уцілів після трагічного обвалу глибоко в Мертвих Копальнях, і його досі переслідує жахлива доля бригади та брата.",h="Вайлдер Тістлнетл — дворф-шахтар, що похмуро сидить у таверні Дворфійського Кварталу Стормвінда.",kw={"вайлдер тістлнетл","дворфи","шахтар","мертві копальні","обвал","дворфійський квартал"},ang={["profession:Mining"]="Шахтарі добре знають небезпеки глибоких підземних жил, де нестійка порода й забута темна магія можуть поховати навіть досвідчену бригаду.",["race:Dwarf"]="Горе Вайлдера зачіпає в дворфах знайому струну: воно нагадує про вічні небезпеки підземних розкопок і святий обов'язок шанувати полеглих побратимів із гільдії."},sec={{t="Гірка доля вцілілого",b="Вайлдера Тістлнетла можна знайти в пивниці біля південно-східної брами Дворфійського Кварталу, де він топить горе в кухлі. Багато років тому він разом із братом і товаришами вирушив у глибокі рудні жили Мертвих Копалень Мунбрука. Страшний обвал замурував решту бригади в темряві, а Вайлдер ледве живим вибрався на поверхню."},{t="Привиди глибин",b="Лихо в тунелях не скінчилося вічним спокоєм. Згодом Вайлдер дізнався, що його брат і вся зникла бригада не просто загинули під завалами: чи то темна магія, чи то незавершені справи підняли їх неспокійною нежиттю, і тепер вони без кінця блукають підземними руїнами. Пригнічений горем і провиною того, хто вцілів, Вайлдер шукає сміливців, готових спуститися в Мертві Копальні, повернути пам'ятні речі загиблих і дати його братові останній спокій."}},faq={{q="Де знайти Вайлдера Тістлнетла?",a="Він сидить у тихому пабі в Дворфійському Кварталі Стормвінда, одразу праворуч, як увійти до кварталу з південно-східного входу.",al={"місце вайлдера","де вайлдер","тістлнетл стормвінд"}},{q="Що сталося з його братом у Мертвих Копальнях?",a="Брата Вайлдера разом з іншими шахтарями завалило в штольні, що раптово обвалилася. Вайлдер вибрався й шукає звісток про тих, хто лишився внизу.",al={"брат вайлдера мертві копальні","що сталося з братом","лор брата тістлнетла"}},{q="Навіщо Вайлдерові шукачі пригод?",a="Вайлдер просить мандрівників, що йдуть у Мертві Копальні, забрати в зниклих робітників їхні значки профспілки шахтарів і з'ясувати, що сталося з його братом.",al={"завдання вайлдера","чого хоче вайлдер","завдання збирання спогадів"}}},fp="20,236,17.359.0,18.452.1,38.140.0,46.138.0,33.156.0"}
P.entries["npc:wiley-the-black"] = {n="Вайлі Чорний",s="Вайлі Чорний — невловимий пройдисвіт, що нині переховується в Корчмі Лейкшира в Редріджі. Хоч він темна й мовчазна особа, він завдячує життям Ґраянові Стаутмантлу й слугує важливим джерелом відомостей із підпілля щодо Братства Дефіас.",h="Вайлі Чорний — невловимий пройдисвіт, що нині переховується в Корчмі Лейкшира в Редріджі.",kw={"вайлі чорний","корчма лейкшира","ґраян стаутмантл","братство дефіас","редрідж","інформатор"},ang={["class:Rogue"]="Вайлі показує тонке мистецтво виживання завдяки ремеслу й відомостям. Для розбійників він — класичний приклад агента, який тримається на плаву, бо знає, коли торгувати відомостями й кому віддавати борги.",["faction:Alliance"]="Поки військо Стормвінда далеко, Альянс покладається на неофіційних помічників на кшталт Вайлі, щоб скласти докупи картину повстання, що назріває у Вестфолі."},sec={{t="Борг негідника",b="Заховавшись у Корчмі Лейкшира, Вайлі Чорний тримається осторонь відкритих заворушень Вестфолу й заполонених гнолами кордонів Редріджу. Попри свою розбійницьку вдачу й сумнівне минуле, Вайлі зв'язаний словом честі з Ґраяном Стаутмантлом, ватажком Народного ополчення. Колись Стаутмантл урятував Вайлі життя — хоч і бурчить, що слід було дати тому негідникові згнити, поки була нагода. Коли Народне ополчення відчайдушно потребує знати, як влаштована змова Дефіасу зсередини, воно звертається саме до Вайлі, і той неохоче ділиться таємними відомостями, щоб сплатити свій борг."}},faq={{q="Де знайти Вайлі Чорного?",a="Вайлі Чорний сидить у Корчмі Лейкшира, у містечку Лейкшир, що притулилося серед Гір Редріджу.",al={"місце вайлі","де вайлі чорний","вайлі редрідж","корчма лейкшира вайлі"}},{q="Чому Вайлі допомагає Ґраянові Стаутмантлу?",a="Колись Ґраян Стаутмантл урятував Вайлі життя. Хоч Ґраян і вважає його нестерпним пройдисвітом, а сам Вайлі не надто охочий підставляти шию, він сплачує борг, передаючи важливі відомості про Братство Дефіас.",al={"чому вайлі допомагає ґраяну","стосунки вайлі й ґраяна","борг вайлі ґраяну"}},{q="Звідки Вайлі знає про Братство Дефіас?",a="Вайлі близько знайомий із тим, що коїться в підпіллі, і з діями Дефіас. Він розкриває відомості про Братство, щоб віддячити Ґраянові Стаутмантлу, але чи був він колись його членом, не підтверджено.",al={"чи вайлі дефіас","звідки вайлі знає про дефіас","зв'язок вайлі з дефіас"}},{q="Яку роль він відіграє в розслідуванні щодо Дефіас?",a="Коли Народне ополчення натрапляє на загадкові докази ширшої змови, Стаутмантл посилає шукачів пригод у Лейкшир із листом до Вайлі. Вайлі розбирається в ситуації й пише записку, яка вказує ополченню на ватажків, що стоять за заколотом.",al={"завдання вайлі","що робить вайлі","вайлі братство дефіас"}}},fp="15,232,18.622.0,33.116.0,39.233.0,49.194.0,51.280.0"}
P.entries["npc:willem"] = {n="Віллем",s="Помічник Віллем — людський солдат війська Стормвінда, що стоїть просто перед Абатством Нортшира. Служачи під проводом Маршала Макбрайда, він — головний польовий зв'язковий, що скеровує новобранців на боротьбу з місцевими загрозами в Долині Нортширу. Його нагальна турбота — придушити дедалі більше вторгнення Братства Дефіас.",h="Помічник Віллем — людський солдат війська Стормвінда, що стоїть просто перед Абатством Нортшира.",kw={"помічник віллем","нортшир","абатство нортшира","дефіас","маршал макбрайд","новобранці"},ang={["class:Warrior"]="Новобранці-воїни знаходять у Помічникові Віллемі практичного польового зв'язкового, що спрямовує їхню воїнську силу на очищення від бандитів і відновлення ладу в королівстві.",["faction:Alliance"]="Віллем — перша точка дотику з внутрішньою безпекою Альянсу: він показує, як глибоко заворушення Дефіас загрожують навіть мирному серцю Елвінну.",["race:Human"]="Для людей, що виходять з Абатства Нортшира у світ, Помічник Віллем — часто найперший військовий офіцер, що вітає їх на службі королівству Стормвінд."},sec={{t="Вартовий біля абатства",b="Стоячи за кілька кроків від воріт Абатства Нортшира, Помічник Віллем утілює передову присутність війська Стормвінда в долині. Військо королівства розтягнуте по багатьох землях, тож місцева безпека тяжко лягає на маленькі загони на кшталт гарнізону Макбрайда. Віллем оцінює добровольців, що прибувають, і одразу дає їм завдання: допомагати тутешнім мешканцям і берегти околиці долини."},{t="Протистояння Дефіас",b="Найнагальніша турбота Віллема — зухвала діяльність Братства Дефіас. Бандити в червоних банданах вдерлися просто в Нортшир: крадуть припаси, залякують тутешніх фермерів на кшталт Міллі Осворт і закріплюються на довколишніх виноградниках і пагорбах. Віллем призначає винагороди за відомих горлорізів, як-от Ґаррик Педфут, щоб зламати їхнє керівництво, перш ніж вони захоплять землі абатства."}},faq={{q="Хто такий Помічник Віллем?",a="Помічник Віллем — офіцер армії Стормвінда, що служить в Абатстві Нортшира в Лісі Елвінн. Він підпорядкований Маршалові Макбрайду й скеровує новобранців на захист долини від місцевих загроз.",al={"хто такий віллем","роль помічника віллема","віллем нортшир"}},{q="Кому підзвітний Помічник Віллем?",a="Він звітує безпосередньо Маршалові Макбрайду — старшому командирові, що відповідає за оборону й військові дії в Долині Нортширу.",al={"командир віллема","хто бос віллема","лідер віллема"}},{q="Чому Віллем призначає винагороди за Дефіас?",a="Братство Дефіас проникло в Долину Нортширу, загрожує абатству й тероризує місцевих робітників. Віллем залучає шукачів пригод, щоб зменшити їхню кількість і знищити ватажків на кшталт Ґаррика Педфута, і так навести лад.",al={"чому нагорода за дефіас","віллем червоні пов'язки","віллем дефіас"}},{q="Де знайти Помічника Віллема?",a="Віллем стоїть біля головного входу до Абатства Нортшира в північній частині Лісу Елвінн і вітає мандрівників і новобранців, що виходять на подвір'я.",al={"місце віллема","де помічник віллем","знайти віллема"}},{q="Як Віллем допомагає місцевим робітникам?",a="Віллем посилає здатних до бою на допомогу мешканцям, чиєму прожитку загрожує небезпека, — зокрема садівниці Міллі Осворт і шкуродерові Іґану.",al={"віллем міллі освортт","віллем іґан","завдання віллема"}},{q="Чому вояки на кшталт Віллема насилу дають раду самі?",a="Стормвінд потерпає від внутрішньої напруги, політичних чвар і далеких військових зобов'язань. Відколи Король Варіан зник, гарнізонам на кшталт Нортширу доводиться покладатися на необстріляних новобранців і добровольців, щоб упоратися із заворушеннями вдома.",al={"чому армія стормвінда слабка","чому нортшир незахищений","людей нортшира не вистачає"}}},fp="6,323,23.420.0,22.420.0,21.200.0,33.138.0,45.225.0,33.155.0,41.185.0,62.222.0"}
P.entries["npc:william-pestle"] = {n="Вільям Пестл",s="Вільям Пестл — алхімік з людей, що зупинився в корчмі «Лев'яча Гордість» у Ґолдширі. Разом із братом Морґаном він тримає аптеку в Торговому Кварталі Стормвінда. Він часто наймає мандрівних шукачів пригод збирати дивні реагенти — свічки кобольдів, водорості мурлоків і трави.",h="Вільям Пестл — алхімік з людей, що зупинився в корчмі «Лев'яча Гордість» у Ґолдширі.",kw={"вільям пестл","алхімік","аптека","ґолдшир","реагенти","лікер невидимості","ліс елвінн"},ang={["faction:Alliance"]="Вільям допомагає постачати Торговий Квартал Стормвінда життєво важливими ліками й дрібницями, покладаючись на новобранців Альянсу, що проходять через Ґолдшир, аби добути матеріали з навколишнього лісу.",["profession:Herbalism"]="Для травників, що мандрують через Ґолдшир, Вільям Пестл утілює практичний, торговий бік збирання рослин: він невпинно перетворює дике зілля й дивні водорості на корисні суміші."},sec={{t="Аптекар на виїзді",b="Поки його брат Морґан Пестл стоїть за прилавком аптеки Пестлів у Торговому Кварталі Стормвінда, Вільям працює з корчми «Лев'яча Гордість» у Ґолдширі. Перебування в Лісі Елвінн дозволяє йому тісно співпрацювати з місцевими збирачами й добувати сировину, якої повсякчас потребують міські крамниці. Він регулярно відправляє вантажі до столиці, щоб мешканці Стормвінда мали сталий доступ до цілющих мазей, настоянок і порошків."},{t="Дивовижні реагенти",b="Ремесло Вільяма часто вимагає незвичних складників, що виходять далеко за межі простих городніх трав. Він часто доручає новачкам збирати воскові свічки, які носять кобольди, що заполонили Елвінн, а також кришталеві водорості, відібрані в мурлоків Кришталевого Озера, просто на схід від Ґолдшира. Хоч такі суміші здаються непосвяченим химерними, Вільям наполягає, що ці дивні інгредієнти мають потужні алхімічні властивості."},{t="Зілля для юного кохання",b="Окрім звичного ремесла, Вільям — давній друг Мілдред Стоунфілд. Коли юні закохані Мейбелл Маклур і Томмі Джо Стоунфілд опиняються між своїми запекло ворогуючими фермерськими родинами, Вільям погоджується зварити Лікер Невидимості. Його напій на водоростях із місцевих вод дозволяє Мейбелл непомітно вислизнути й зустрітися з Томмі Джо."}},faq={{q="Хто такий Вільям Пестл?",a="Вільям Пестл — алхімік і аптекар, що живе в Корчмі «Лев'яча Гордість» у Ґолдширі. Разом зі своїм братом Морґаном зі Стормвінда він збирає й готує алхімічні припаси для королівства.",al={"вільям пестл","алхімік ґолдшира","хто такий пестл"}},{q="Де знайти Вільяма Пестла?",a="Він у Корчмі «Лев'яча Гордість» у Ґолдширі, в Лісі Елвінн.",al={"місце пестла","де вільям пестл","вільям пестл ґолдшир"}},{q="Що Вільям робить зі свічками кобольдів?",a="Вільям збирає воскові свічки, які носять кобольди в копальнях Елвінна, переплавляє їх і очищує лій для своїх алхімічних сумішей та загальних аптекарських запасів.",al={"навіщо свічки кобольдів","використання свічок кобольдів"}},{q="Навіщо Вільямові кришталева ламінарія?",a="З кришталевої ламінарії, зібраної в озерах Елвінна, Вільям готує Лікер Невидимості, який допомагає Мейбелл Маклур непомітно прослизнути повз рідню на побачення з Томмі Джо Стоунфілдом.",al={"навіщо збирати ламінарію","використання ламінарії мурлоків"}},{q="Що пов'язує Вільяма Пестла зі Стормвіндом?",a="Вільям і його брат Морґан тримають аптеку в Торговому Кварталі Стормвінда. Вільям збирає складники в Ґолдширі й налагоджує їх доставку до міської крамниці.",al={"пестл стормвінд","аптека вільяма пестла"}},{q="Як Вільям пов'язаний зі Стоунфілдами й Маклурами?",a="Вільям — давній друг Мілдред Стоунфілд. Він допомагає Томмі Джо Стоунфілду й Мейбелл Маклур, зваривши таємне зілля, щоб вони могли обійти запеклу ворожнечу своїх родин.",al={"стоунфілди маклури пестл","завдання кохання вільяма пестла"}}},fp="14,300,17.463.0,16.405.0,27.380.1,22.199.0,34.82.0,41.174.0,35.175.1,54.180.0,58.173.1"}
P.entries["npc:williden-marshal"] = {n="Вілліден Маршал",s="Вілліден Маршал — амбітний очільник-людина Експедиції Маршала, що базується в Притулку Маршала на півночі Кратера Ун'Ґоро. Його вабили рідкісні рослини, загадкові кристали й прибуткові наукові дослідження, тож він привів свою команду в кратер — і став свідком того, як велетенські звірі западини розгромили їхні нижні табори.",h="Вілліден Маршал — амбітний очільник-людина Експедиції Маршала, що базується в Притулку Маршала на півночі...",kw={"вілліден маршал","притулок маршала","експедиція","ун'ґоро","кристали","людина"},ang={["faction:Alliance"]="Хоча в дикому кратері Вілліден із необхідності тримає нейтралітет, він і його найближча команда міцно пов'язані культурою й торгівлею із серцевими землями Альянсу.",["profession:Herbalism"]="Експедицію Віллідена значною мірою привабила до Ун'Ґоро унікальна доісторична рослинність кратера, яка більше ніде в Азероті не росте.",["race:Human"]="Вілліден уособлює невгамовну цікавість і торговельні амбіції людства: він подолав увесь шлях від Східних Королівств до неприборканих глибин південного Калімдору."},sec={{t="Хиткий плацдарм",b="Вілліден Маршал привів цілу наукову експедицію в самі глибини Кратера Ун'Ґоро в пошуках статків і відкриттів. Заінтригований розповідями про чужинські кристали, неописані рослини й неторкані ресурси, він заклав кілька передових таборів по всьому дну долини. Та первісна глушина швидко обернулася проти них. Люті звірі кратера розтрощили їхні дослідницькі пости, і Вілліден із тими, хто вцілів, мусив відступити вгору, на північні скелі, де й постав Притулок Маршала."},{t="Порятунок мрії",b="Хоча його відтіснили аж на гірський край кратера, Вілліден не збирається пакувати речі й кидати свої вкладення. Із відносно безпечного притулку він наймає мандрівних шукачів пригод, щоб ті знову спускалися в дикі низини й повертали загублені ящики з харчами, дорогі наукові прилади та його особистий журнал експедиції. Близькі товариші, як-от Спарк Нілмайнер, часто звуть його просто «Віл», та до справи він ставиться серйозно — і наполягає, щоб плоди їхньої праці таки врятували, навіть коли в долині під ними нишпорять велетенські хижаки."},{t="Родинні зв'язки",b="Вілліден — не єдиний Маршал у кратері: Гол'аньї Маршал носить те саме прізвище й працює пліч-о-пліч із ним у Притулку Маршала. Разом вони обрали неприборканий первісний кратер на півдні Калімдору, а Вілліден досі твердо переконаний, що справжній скарб — це кристалічні поклади й прадавні таємниці Ун'Ґоро."}},faq={{q="Хто такий Вілліден Маршал?",a="Вілліден Маршал — дослідник-людина й командир Експедиції Маршала. Він привів загін учених і шукачів пригод у Кратер Ун'Ґоро, щоб вивчати його дивні кристали й рослини, прагнучи знань і зиску.",al={"хто такий вілліден маршал","лор віллідена маршала","хто керує притулком маршала"}},{q="Чому експедиція засіла в печері?",a="Спершу експедиція заклала кілька дослідницьких баз у низинах Ун'Ґоро. Проте вона недооцінила дикість Ун'Ґоро: велетенські хижаки кратера сплюндрували табори, і вцілілі мусили втекти на північні скельні уступи Притулку Маршала.",al={"чому притулок у печері","що сталося з таборами експедиції","чому маршал відступив"}},{q="Про що Вілліден просить шукачів пригод?",a="Вілліден просить відважних дослідників спуститися в небезпечну улоговину кратера й повернути припаси зі зруйнованих таборів: покинуті запаси їжі, тендітне дослідницьке обладнання і його загублений журнал експедиції.",al={"завдання віллідена","порятунок експедиції","чого хоче вілліден"}},{q="Що взагалі привело Віллідена в Кратер Ун'Ґоро?",a="Він прибув по унікальні багатства кратера: рідкісні рослини, загадкові кольорові кристали сили, давні геологічні таємниці й чималі прибутки, які наукові відкриття принесли б удома.",al={"чому вілліден в ун'ґоро","мотивація віллідена маршала","що досліджує маршал"}},{q="Чи має Вілліден родину?",a="Єдина інша відома в кратері Маршал — Гол'аньї Маршал, що має те саме прізвище й працює разом із ним у Притулку Маршала.",al={"брат віллідена","лівінґстон маршал","родина маршала"}},{q="За кого Вілліден Маршал — за Альянс чи Орду?",a="Хоч Вілліден і людина, він очолює нейтральну наукову експедицію в Притулку Маршала. Він охоче приймає допомогу шукачів пригод і з Альянсу, і з Орди, якщо ті готові повернути його припаси й очистити кратер від загроз.",al={"чи вілліден альянсу","чи орда може говорити з віллідена","фракція притулку маршала"}}},fp="16,328,21.492.0,19.517.0,11.313.0,24.215.0,41.292.0,42.207.0,59.215.0,30.129.0,55.224.0"}
P.entries["npc:winna-hazzard"] = {n="Вінна Газзард",s="Вінна Газзард — дивакувата дослідниця з Відступників, що працює на Заставі Кривавої Отрути в Скверноліссі. Її супроводжує кошеня, а сама вона відома нападами шаленого сміху. Вінна вивчає зачумлену природу краю й ставить моторошні досліди над тутешньою оскверненою звіриною.",h="Вінна Газзард — дивакувата дослідниця з Відступників, що працює на Заставі Кривавої Отрути в Скверноліссі.",kw={"вінна газзард","відступники","дослідниця","кошеня","застава кривавої отрути","сквернолісся"},ang={["faction:Horde"]="З безпечної Застави Кривавої Отрути Вінна залучає мандрівників Орди, щоб ті збирали осквернені реагенти для її химерних досліджень.",["race:Undead"]="Вінна втілює темніші дивацтва Відступників: безоглядну цікавість до скверни без жодної поваги до природної гармонії."},sec={{t="Дивна дослідниця",b="Вінна Газзард уособлює інтерес Відступників до неприродного тління Сквернолісся. Перебуваючи в анклаві Орди на Заставі Кривавої Отрути, вона спостерігає за місцевою звіриною й вигадує досліди із зараженою водою та отруйними зразками. Її весела, маніакальна вдача часто приховує безсердечні наміри. Це видно, коли вона бере заражену рідину з тутешньої землі, щоб осквернити маленьке кошеня, яке не відходить від неї."}},faq={{q="Хто така Вінна Газзард?",a="Вінна Газзард — Відступниця, що дає завдання на Заставі Кривавої Отрути в центрально-північному Скверноліссі. Вона досліджує згубний вплив Сквернолісся й доручає шукачам пригод збирати зразки в дикому краю.",al={"вінна газзард","хто така вінна","кішкарка скверноліссі"}},{q="Що стається з її кошеням?",a="Коли шукачі пригод приносять Вінні наповнений флакончик зіпсованої рідини з довколишніх лісів, вона напуває нею своє кошеня, і те перетворюється на Оскверненого Кота, а Вінна заходиться божевільним сміхом.",al={"кошеня вінни","зіпсована кішка","досліди вінни з кішкою"}},{q="Яка мета Вінни Газзард у Скверноліссі?",a="Як і багато аптекарів і вчених серед Відступників, Вінна прагне зрозуміти біологічну пошесть і приборкати її, вивчаючи на всепроникній скверні Сквернолісся, як вона змінює й спотворює живих звірів.",al={"мотив вінни газзард","чому вінна у скверноліссі"}}},fp="13,270,21.417.0,21.207.0,27.205.1,40.189.0"}
P.entries["npc:winstone-wolfe"] = {n="Вінстоун Вульф",s="Вінстоун Вульф — людина-агент, пов'язаний із таємною організацією Рейвенголдт, що служить у її відлюдному маєтку між Гілсбредом і Горами Альтерак. Він наглядає за угіддями маєтку та його доглядачами й належить до довірених людей потаємної ліги злодіїв і вбивць.",h="Вінстоун Вульф — людина-агент, пов'язаний із таємною організацією Рейвенголдт, що служить у її відлюдному...",kw={"вінстоун вульф","рейвенголдт","маєток рейвенголдт","розбійники","гори альтерак","ліга вбивць"},ang={["class:Rogue"]="Як агент Маєтку Рейвенголдт, Вульф — знайоме обличчя для розбійників, що приходять у гори вдосконалювати своє ремесло в лізі."},sec={{t="Посередник у горах",b="У прихованій долині Маєтку Рейвенголдт Вінстоун Вульф діє в лавах організації Лорда Джораха Рейвенголдта. Тихий, пильний і практичний, Вульф — одна з умілих рук, що вирішують справи довкола маєтку й дбають, щоб угіддями вільно ходили лише ті, хто має належну стриманість і хист."}},faq={{q="Хто такий Вінстоун Вульф?",a="Вінстоун Вульф — розбійник-людина, що діє в Маєтку Рейвенголдт, відлюдному осідку Ліги Убивць, захованому високо над Передгір'ям Гілсбреда й Горами Альтерак.",al={"хто такий вульф","лор вінстоуна вульфа","вульф рейвенголдт"}},{q="Де знайти Вінстоуна Вульфа?",a="Він у Маєтку Рейвенголдт, до якого веде прихована стежка, що в'ється на північ крізь гори від околиць Твердині Дурнгольд у Передгір'ї Гілсбреда.",al={"місце вульфа","де вінстоун вульф","знайти вінстоуна вульфа"}},{q="Яка його роль у Рейвенголдті?",a="Вульф — агент і вартовий маєтку: пильнує територію й допомагає в темних справах постачання цього таємного союзу.",al={"що робить вульф","мета вульфа"}}},fp="14,329,24.326.0,22.184.0,32.162.0,31.146.0"}
P.entries["npc:witch-doctor-jin-zil"] = {n="Знахар Джин'Зіл",s="Знахар Джин'Зіл — троль-містик із Темного Списа, що живе в печері в Малака'джині на півдні Гір Кам'яного Кігтя. Давній бойовий товариш Дарсока Свіфтдаґґера й тіньового мисливця Рокхана, він обертає темне вуду й обрядове чаклунство проти місцевих ворогів Орди.",h="Знахар Джин'Зіл — троль-містик із Темного Списа, що живе в печері в Малака'джині на півдні Гір Кам'яного...",kw={"знахар джин'зіл","малака'джин","темний спис","вуду","дарсок свіфтдаґґер","рокхан","тролі"},ang={["faction:Horde"]="Поки Орда вбезпечує південні шляхи Гір Кам'яного Кігтя, Джин'Зіл разом із розвідниками застави забезпечує важливий окультний захист і розвідку.",["race:Troll"]="Джин'Зіл уособлює традиційне ремесло знахарів Темного Списа, перенесене в суворі нетрі Калімдору, і підтримує тісні зв'язки з такими видатними постатями, як Рокхан."},sec={{t="Самітник Малака'джина",b="Усамітнившись у східній печері над табором Малака'джин, Джин'Зіл практикує давні мистецтва тролів джунглів далеко від приморської домівки свого племені. Серед булькотливих казанів і полонених бранців він збирає серед скель Гір Кам'яного Кігтя екзотичні реагенти, щоб плести могутні благословення й прокляття на захист гірського табору Орди."},{t="Перевірений ветеран",b="Джин'Зіл — не звичайний сільський чаклун: його пов'язує славна історія з бувалими розвідниками Орди, і серед його давніх друзів — і Дарсок Свіфтдаґґер, і знаменитий тіньовий мисливець Рокхан. Поки Дарсок керує сутичками на передовій проти нічних ельфів і гарпій, Джин'Зіл веде війну духом і алхімією: своєю лісовою магією й мінливим вуду він підточує загрози ще до того, як ті дістануться воріт табору."}},faq={{q="Де знайти Знахаря Джин'Зіла?",a="Він живе в печері на східному боці Малака'джина — поселення Орди, що притулилося в південному перевалі Гір Кам'яного Кігтя.",al={"місце джин'зіла","де джин'зіл","печера джин'зіла"}},{q="Що пов'язує Джин'Зіла з Рокханом і Дарсоком Свіфтдаґґером?",a="Джин'Зіл — давній надійний друг і Дарсока Свіфтдаґґера, і мисливця тіней Рокхана. Завдяки цим давнім зв'язкам розвідники по всіх Горах Кам'яного Кігтя покладаються на його магічне знання, коли стикаються з незвичними загрозами.",al={"друзі джин'зіла","дарсок і джин'зіл","зв'язок із рокханом"}},{q="Чому в печері Джин'Зіла сидять в'язні?",a="Джин'Зіл тримає полонених ворогів у клітках у своїй печерній майстерні. Як справжній знахар, він використовує полонених і сирі реагенти, щоб випробовувати прокляття, віщувати прикмети й творити захисне вуду для поселення.",al={"в'язні джин'зіла","клітки джин'зіла","чому в джин'зіла полонені"}},{q="Які завдання він дає шукачам пригод з Орди?",a="Він посилає мандрівників по всіх Горах Кам'яного Кігтя по містичні складники для своєї лісової магії, щоб живити ними свої обряди вуду.",al={"завдання джин'зіла","чого хоче джин'зіл"}}},fp="20,265,24.358.0,17.419.0,38.136.0,62.221.0,44.211.0,53.128.0"}
P.entries["npc:witch-doctor-uzer-i"] = {n="Чаклун-знахар Узер'і",s="Чаклун-знахар Узер'і — містик із тролів джунглів, що живе в Таборі Моджаче серед прадавніх лісів Фераласу. Він прагне примножити магічну силу Орди й шукає способів упіймати та приборкати муїсек — духовну сутність могутніх істот природи. Ловлячи прадавніх лісових духів, Узер'і хоче вливати в зачаровану зброю ту первісну силу, яку здавна шанують нічні ельфи.",h="Чаклун-знахар Узер'і — містик із тролів джунглів, що живе в Таборі Моджаче серед прадавніх лісів Фераласу.",kw={"узер'і","чаклун-знахар","муїсек","табір моджаче","фералас","тролі","духи","зброя"},ang={["class:Shaman"]="Шамани впізнають у ньому незмінне прагнення спілкуватися з духами, проте те, як силоміць він ув'язнює стихійні й дикі сутності, — це радше брутальне чаклунство, ніж шанобливий пошук рівноваги.",["faction:Horde"]="Узер'і відкриває Орді шлях до опанування первісної магії диких земель Калімдора — і обертає духовну силу краю проти союзників Альянсу, як-от нічних ельфів.",["race:NightElf"]="Нічні ельфи вважають практики Узер'і блюзнірством і з жахом дивляться, як священних істот — древенів, гіпогрифів, гірських велетнів — убивають і вковують у зброю.",["race:Troll"]="Узер'і втілює класичні духовні практики тролів: традиційні обряди чаклунів-знахарів, зменшувальні посудини й вуду, щоб уловлювати сиру життєву сутність."},sec={{t="Приборкання муїсеку",b="Вихований на давніх тролячих віруваннях у духів, чаклун-знахар Узер'і чимало часу присвятив вивченню природної магії диких нетрів Фераласу. Він переконаний, що нічні ельфи тисячоліттями черпали силу з духів лісових звірів, — і що настав час Орді заволодіти тими самими первісними силами. В основі його досліджень лежить муїсек: жива духовна сутність, яка ще лишається в істоті. Щоб її вловити, Узер'і виготовляє особливі посудини, які блискавично зменшують тіло полеглої істоти, перш ніж дух устигне розвіятися, — так сутність можна зберегти й дослідити."},{t="Моторошні оборудки й ритуальні посудини",b="Щоб довершити посудини, Узер'і знадобилися темні й сильнодійні реагенти, яких у нетрях самотужки не здобудеш. Убивши дворфа з Альянсу, що блукав лісами Фераласу, Узер'і відтяв зайді голову й домовився передати її Ніру Файрблейду — чорнокнижникові, що мешкає в похмурій Тіньовій Розколині Оргріммара. В обмін на цей моторошний трофей Ніру дав йому рідкісні трави, без яких не завершити сковувальних чарів. Із цими складниками Узер'і нарешті виготовив перші посудини — і відкрив собі шлях до ловлі духів місцевих диких місячників, гіпогрифів, дракончиків-фей, древенів і гірських велетнів."},{t="Кування зброї Духу",b="Видобути муїсек — це лише перший крок у задумах Узер'і. Збираючи міцні сухожилля, зачаровані мінерали та скам'янілі уламки колод із тих самих істот, чиї духи він ув'язнив, чаклун-знахар поєднував речовину зі скутим муїсеком. Через ці обряди він навчився назавжди вкладати прадавніх лісових духів у зброю та обладунки й давати Орді зброю, наснажену магією. Окрім ритуального ремесла, Узер'і глибоко цікавиться прихованими місцями сили по всьому Азероту й уважно стежить за чутками про прадавній затоплений Затонулий Храм."}},faq={{q="Що таке муісек?",a="Муісек — духовна сутність живих істот, що лишається після них. Чаклун-знахар Узер'і за допомогою особливих зачарованих посудин зменшує тіла вбитих звірів і природних вартових, ловлячи їхні духи, перш ніж ті розчиняться в довкіллі.",al={"що таке муісек","значення муісека","визначення муісека"}},{q="Чому Узер'і передає голови дворфів до Оргріммара?",a="Узер'і потребував особливих реагентів, щоб підготувати свої обрядові посудини. Убивши у Фераласі дворфа з Альянсу, він відправив відтяту голову Ніру Файрблейду в Оргріммар в обмін на рідкісні трави, потрібні, щоб зв'язати духи муісек.",al={"голова дворфа завдання","чому надсилати голову до неру","неру файрблейд торгівля"}},{q="На яких істот полює Узер'і?",a="Він полює на істот, глибоко пов'язаних зі світом природи й віддавна союзних нічним ельфам: на диких місячників у Пригір'ї, а також на гіпогрифів, драконів-фей, древенів і гірських велетнів у Фераласі.",al={"яких звірів полює узер'і","цілі духів узер'і","які тварини для муісека"}},{q="Що Узер'і робить із упійманими духами?",a="Зібравши муісек разом із сирими природними складниками — розколотими колодами, сухожиллями й мінералами, — Узер'і назавжди вкладає його у зброю, наснажуючи звичайну зброю первісною містичною силою прадавніх вартових лісу.",al={"зброя духу","навіщо збирати муісек","нагороди зброї муісека"}},{q="Де перебуває Чаклун-знахар Узер'і?",a="Чаклун-знахар Узер'і живе в Таборі Моджаче — головному поселенні Орди серед буйних і небезпечних хащ центрального Фераласу.",al={"місце узер'і","де узер'і","де чаклун-знахар узер'і"}},{q="Що Узер'і знає про Затонулий Храм?",a="Як знавець духів і містичних місць Азероту, Узер'і прочув про затоплене святилище Атал'аї, відоме як Затонулий Храм, і посилає зацікавлених шукачів пригод до гобліна-дослідника Марвона Рівітсікера, щоб розвідати більше.",al={"узер'і затонулий храм","завдання затонулого храму","храм атал'хаккара узер'і"}}},fp="19,441,21.620.0,34.624.1,25.600.0,15.262.0,47.239.0,42.219.0,46.218.0,37.136.0,46.245.0"}
P.entries["npc:wizbang-cranktoggle"] = {n="Візбанґ Кранктоґґл",s="Візбанґ Кранктоґґл — ексцентричний гном-інженер, що живе на верхньому поверсі корчми в Обердайні. Попри те, що він далеко від повних зубчастих коліс залів Гномреґана чи Айронфорджа, він спрямував свою механічну винахідливість на встановлення й обслуговування автоматичних пристроїв зв'язку — дзижчалок — по всьому дикому Темному Узбережжю.",h="Візбанґ Кранктоґґл — ексцентричний гном-інженер, що живе на верхньому поверсі корчми в Обердайні.",kw={"візбанґ кранктоґґл","гном","інженер","дзижчалки","обердайн","темне узбережжя"},ang={["profession:Engineering"]="Те, як Візбанґ покладається на власні інструменти на кшталт електромуфт і електропеллерів, показує класичний гномський підхід: механічні відповіді на логістичні задачі в незвіданих краях.",["race:Gnome"]="Бачити співвітчизника-гнома, що керує експериментальною мережею зв'язку на суворому узбережжі Калімдору, — приємне нагадування про невгамовну винахідливість Гномреґана.",["race:NightElf"]="Поки ельфійські вартові й друїди покладаються на вогників, гінців і природні зв'язки, Візбанґ приносить у священні ліси Темного Узбережжя гучні, дзижчливі шестерні й металеві скриньки."},sec={{t="Інженер в Обердайні",b="Нічні ельфи Обердайна воліють жити в злагоді з природою й триматися давніх звичаїв, а Візбанґ Кранктоґґл уособлює допитливу, майструвальну присутність Альянсу. Влаштувавшись на горішньому поверсі корчми Обердайна серед інструментів і запчастин, Візбанґ мало зважає на урочисті друїдські традиції Калімдору й зосереджується на практичних механічних задачах."},{t="Мережа дзижчалок",b="Головний задум Візбанґа на Темному Узбережжі — розставити й підтримувати в робочому стані свій дивний винахід: дзижчалку. Ці пристрої мали забезпечити автоматичні звіти й зв'язок на великі відстані вздовж порізаного, розлогого берега, але часто страждають від прибережної негоди й ворожості місцевих звірів. Візбанґ постійно наймає мандрівників збирати деталі, рятувати інструменти на кшталт електромуфт і повертати електропеллери, щоб його механічне спостереження й далі працювало."}},faq={{q="Де знайти Візбанґа Кранктоґґла?",a="Візбанґ перебуває на горішньому поверсі корчми в приморському поселенні нічних ельфів Обердайн, на Темному Узбережжі.",al={"місце візбанґа","де візбанґ","місце гнома в оберіні"}},{q="Що Візбанґ Кранктоґґл робить на Темному Узбережжі?",a="Він інженер Альянсу, що налагоджує й обслуговує мережу автоматичних машин зв'язку, які звуться дзижчалками, по всіх диких закутках Темного Узбережжя.",al={"чому візбанґ в оберіні","мета візбанґа","що робить візбанґ"}},{q="Що таке дзижчалки?",a="Дзижчалки — механічні пристрої зв'язку й спостереження, які винайшов Візбанґ Кранктоґґл, щоб передавати відомості по всьому Темному Узбережжю, хоча вони раз у раз ламаються через напади звірів і негоду.",al={"що таке дзижчалка","лор дзижчалки","призначення дзижчалки"}},{q="Чи має Візбанґ родичів серед інших гномів?",a="Він має спільне прізвище з Делбером Кранктоґґлом — отже, вони, можливо, з одного роду майстрів.",al={"рід кранктоґґл","хто такий делбер кранктоґґл","родичі візбанґа"}},{q="Чому нічні ельфи терплять його майстрування в Обердайні?",a="Як члени Великого Альянсу, нічні ельфи дають у Обердайні житло й прихисток союзним расам, хоч гномські механізми й різко контрастують із традиційною ельфійською гармонією.",al={"нічні ельфи і гноми","чому дозволяють інженерію в оберіні"}},{q="Які завдання Візбанґ дає шукачам пригод?",a="Візбанґ просить шукачів пригод допомогти полагодити й налаштувати його дзижчалки, а для цього треба нишпорити узбережжям у пошуках особливих деталей на кшталт електропеллерів і електромуфт.",al={"завдання візбанґа","які завдання пропонує візбанґ"}}},fp="19,332,24.396.0,19.483.0,37.112.0,47.166.0,19.209.0,39.104.0,59.191.0,44.173.0"}
P.entries["npc:wizlo-bearingshiner"] = {n="Візло Берінґшайнер",kw={"візло берінґшайнер","застава білого рубежу","гіперконденсаторна штукенція","гобліни","місячні колодязі","інженерія"},ang={["faction:Horde"]="Отаборившись разом із місцевими тауренами на Заставі Білого Рубежу, мандрівники з Орди легко можуть скористатися механічною вправністю Візло, щоб роздобути корисні пристрої."},sec={{t="Інженер на заставі",b="Staying alongside the tauren at Whitereach Post along the canyon road, Wizlo Bearingshiner faces an unwelcome delay. Centaur attacked his caravan, leaving him as its only survivor. His clients are waiting for their wares, and he worries that he will not deliver them in time."},{t="A Stranded Shipment",b="Wizlo's best gizmo hangs around the neck of a fierce panther caged beside his ruined caravan north of Whitereach Post. Even the centaur avoid the beast. Wizlo offers travelers the cage key and a reward for recovering the hypercapacitor, though he admits he has yet to work out what the device actually does."}},faq={{q="Хто такий Візло Берінґшайнер?",a="Wizlo Bearingshiner is a goblin tinkerer stranded at Whitereach Post in Thousand Needles after centaur attacked his caravan. He seeks help recovering a Hypercapacitor Gizmo from a caged panther.",al={"хто такий візло","візло берінґшайнер","гоблін білого рубежу"}},{q="Де знайти Візло Берінґшайнера?",a="He is located at Whitereach Post, a Horde camp along the road near Camp E'thok in Thousand Needles.",al={"місце візло","де візло","знайти візло"}},{q="Які досліди він проводить?",a="Wizlo is trying to recover his Hypercapacitor Gizmo. He admits that he still needs to figure out what it does; the device's exact function is unknown.",al={"завдання візло","що робить візло","витвори візло"}},{q="Чому гоблін працює з Ордою на Заставі Білого Рубежу?",a="Whitereach Post is an unintended stop for Wizlo. Centaur attacked his caravan nearby, and he is stranded while his clients await their shipments.",al={"чому візло тут","чи візло з орди","гоблін на білому рубежі"}},{q="Чи належить Візло до картелю Стімвідл?",a="No Steamwheedle affiliation is established for Wizlo. He is stationed with the Horde at Whitereach Post and is concerned with recovering his goods and delivering them to his clients.",al={"фракція візло","візло стімвідл","картель візло"}},{q="Що таке Гіперконденсаторна Штукенція?",a="The Hypercapacitor Gizmo is a valuable device carried by a caged panther beside Wizlo's wrecked caravan. Its exact purpose is unknown—even Wizlo says he has yet to figure out what it does.",al={"гіперконденсаторна штукенція","пристрій візло","завдання штукенції"}}},fp="19,227,23.275.0,19.307.0,27.194.0,37.99.0,37.150.0,58.145.0,45.182.0,33.190.0"}
P.entries["npc:wizzle-brassbolts"] = {n="Віззл Брассболтс",s="Віззл Брассболтс — гном-інженер, що разом із колегами-майстрами отаборився на солончаках Тисячі Голок. Працюючи в гномській гоночній команді на Перегонах Міражу, він шукає міцні місцеві матеріали, щоб зміцнити їхні експериментальні ракетні автомобілі.",h="Віззл Брассболтс — гном-інженер, що разом із колегами-майстрами отаборився на солончаках Тисячі Голок.",kw={"віззл брассболтс","перегони міражу","черепахові панцирі","пілот лонґбірд","мерехтливі низини","ракетне пальне"},ang={["profession:Engineering"]="Віззл — утілення гномської інженерної філософії: гнати швидкісні машини до межі й покладатися на незвичні способи зміцнення конструкції, коли металеві листи не витримують.",["race:Gnome"]="Гноми, що завітають до Мерехтливих Низин, знайдуть у Віззлі споріднену душу, уперто налаштовану перемогти безрозсудні вигадки гоблінів зі Стімвідла кращою майстерністю."},sec={{t="Майстрування на солончаках",b="У тремтливому жарі Мерехтливих Низин суперництво гномської та гоблінської інженерії набуває вигляду швидкісних перегонів ракетних автомобілів. Віззл Брассболтс працює в гномській команді механіків і намагається вберегти їхні машини цілими попри шалені швидкості й абразивну сіль. Щоб зміцнити машини, він наймає шукачів пригод полювати на місцеву звірину — як-от на міцних черепах, що блукають улоговиною, — і збирати їхні тверді панцирі, з яких роблять нові паливні баки, досить міцні, щоб утримати нове їдке ракетне пальне його брата."},{t="Друзі в далеких краях",b="Віззл підтримує тісні зв'язки з друзями на інших континентах, зокрема з Пілотом Лонґбірдом, який відправляє гінців із гоночними шоломами для братів. З такою допомогою Віззл забезпечує гномську команду всім потрібним, попри віддалений і негостинний випробувальний полігон у Мерехтливих Низинах."}},faq={{q="Де знайти Віззла Брассболтса?",a="Віззл Брассболтс перебуває на Перегонах Міражу на Мерехтливих Низинах, у південно-східній частині Тисячі Голок. Він стоїть серед гномської ремонтної бригади та її машин.",al={"місце віззла","де віззл брассболтс","карта віззла брассболтса"}},{q="Навіщо Віззл збирає черепашачі панцирі?",a="Його брат розробляє нове ракетне паливо — таке сильне, що могло б проїсти раму машини. З твердих, як камінь, панцирів черепах Мерехтливих Низин Віззл робить нові паливні баки, які його витримають.",al={"завдання зміцнених панцирів","навіщо віззлу панцирі","панцирі черепах траса"}},{q="Хто такі брати Брассболтси?",a="Брати Брассболтси — це Віззл і його брати Фіззл і Різзл, гноми-майстри, що мають команду гномського ракетного болида на Перегонах Міражу й змагаються з гоблінами. Пілот Лонґбірд — їхній друг.",al={"рід брассболтс","брати брассболтси","брати віззла"}},{q="Чи привітний Віззл до гравців Орди?",a="Так. Перегони Міражу — нейтральна територія, і завдання самого Віззла, як-от збирання твердих черепашачих панцирів, відкриті для шукачів пригод і з Орди, і з Альянсу.",al={"чи віззл дружній до орди","віззл брассболтс орда"}}},fp="17,259,27.539.0,25.286.0,35.182.0,39.214.0,32.212.0,36.160.0"}
P.entries["npc:wizzlecrank-s-shredder"] = {n="Подрібнювач Візлкренка",s="Подрібнювач Візлкренка — подрібнювач Венчурної Компанії, що застряг у смердючих глибинах Багнистого Болота на півночі Пусток. Гоблін Пілот Візлкренк заліз усередину, щоб викрасти його, але без ключа машина не рушить з місця, а довкола — ворожі оператори Венчурної Компанії. Допомогти завести двигун — єдиний спосіб для пілота, що опинився в пастці, відчайдушно вирватися на волю.",h="Подрібнювач Візлкренка — подрібнювач Венчурної Компанії, що застряг у смердючих глибинах Багнистого Болота на...",kw={"подрібнювач візлкренка","пілот візлкренк","венчурна компанія","багниста драговина","втеча","гобліни"},ang={["faction:Horde"]="Орда зазвичай зневажає Венчурну Компанію за вирубування лісів і отруйне виснаження Пусток, тож допомога заблукалому пілотові — зручний привід розтрощити її бурові ділянки.",["profession:Engineering"]="Гоблінський подрібнювач — диво грубої парово-поршневої техніки, хоча халепа Пілота Візлкренка доводить, як легко фірмові системи запалювання можуть підвести в польових умовах."},sec={{t="У пастці в багні",b="Глибоко в залитій нафтою, страшенно забрудненій улоговині Багнистого Болота стоїть нерухомий Подрібнювач Візлкренка, оточений ворожими найманцями Венчурної Компанії. Гоблін усередині, Візлкренк, заскочив у машину Венчурної Компанії, щоб її поцупити, — і лише тоді виявив, що без ключа не розблокувати рульову колонку. Коли інший оператор подрібнювача спитав, чи все гаразд, він запанікував і зіслався на технічну несправність. Тепер він сидить, замкнений усередині, серед ворожих вартових і наглядачів, і сподівається, що хтось принесе ключ, перш ніж Венчурна Компанія щось запідозрить."},{t="Брязкітлива втеча",b="Щойно отримавши ключ запалювання, відібраний у наглядача з диспетчерської на вершині бурової вежі, подрібнювач із гуркотом і брязкотом оживає. Обертові леза й важка металева обшивка дають Пілотові Візлкренку змогу на цій незграбній машині проламатися крізь заслони найманців — але вибратися з улоговини в безпеку вразлива машина зможе лише під охороною співчутливих перехожих."}},faq={{q="Хто сидить у Подрібнювачі Візлкренка?",a="Цим механічним ходаком керує Пілот Візлкренк — гоблін, який заліз у машину Венчурної Компанії, щоб її вкрасти, і застряг посеред земель Венчурної Компанії без ключа.",al={"хто в подрібнювачі","пілот віззлкренк","хто сидить у подрібнювачі візлкренка"}},{q="Чому подрібнювач застряг у Багнистому Болоті?",a="Візлкренк заскочив у подрібнювач, не знаючи, що для руху потрібен ключ. Довкола — ворожі робітники, бурильники й охоронці Венчурної Компанії; підозріливому операторові він сказав, що машина зламалася, і тепер чекає всередині, поки хтось принесе ключ від наглядача з бурової вежі.",al={"чому подрібнювач застряг","віззлкренк застряг","що сталося з подрібнювачем"}},{q="Чому подрібнювача іноді немає на місці?",a="Якщо подрібнювача немає в північній низині Багнистого Болота, значить, інший мандрівник щойно його запустив і супроводжує Візлкренка в безпечне місце. Подрібнювач знову з'явиться на початковому місці невдовзі після завершення супроводу.",al={"подрібнювач зник","де подрібнювач візлкренка","подрібнювача немає"}},{q="Що Венчурна Компанія робить у Багнистому Болоті?",a="Венчурна Компанія нещадно видобуває в північних Пустках нафту, смолу й деревину, перетворивши колишнє природне джерело води на отруйну масну трясовину, де аж кишить найнятими громилами й наглядачами.",al={"багнисте болото","венчурна компанія в багнистому болоті"}}},fp="22,377,21.553.0,21.397.1,37.206.0,43.317.0,38.258.0,48.210.0"}
P.entries["npc:wrenix-the-wretched"] = {n="Вреникс Жалюгідний",s="Вреникс Жалюгідний — гоблінський майстер-механік у гамірному портовому містечку Раджет. Він працює біля свого дивного гізмотронного апарата й пропонує особливу допомогу тим, хто хоче зламати тугі замки й пограбувати надійні схованки.",h="Вреникс Жалюгідний — гоблінський майстер-механік у гамірному портовому містечку Раджет.",kw={"вреникс жалюгідний","гізмотронний апарат","раджет","відмички","розбійник","картель стімвідл"},ang={["class:Rogue"]="Вреникс — важливий наставник молодих розбійників у мистецтві зламування замків: він дає знаряддя й доручення, щоб відпрацювати прийоми на скриньках піратів Південних морів.",["profession:Engineering"]="Чудернацький гізмотронний апарат Вреникса — довершений зразок штукенцій Стімвідлу: галасливий, норовливий, але напрочуд дієвий у точній роботі."},sec={{t="Майстер із Раджета",b="Вреникс Жалюгідний, що вилежується біля своїх чудернацьких машин у гоблінському порту Раджет, уособлює заповзятливий, практичний дух картелю Стімвідл. Попри похмуре прізвисько, він має особливі знання про механізми, пристрої й тонке мистецтво обходу захисту та порятунку цінностей, тож він — безцінний контакт для молодих пройдисвітів і розвідників, що працюють на узбережжі."},{t="Гізмотронний апарат",b="Просто поруч із Врениксом стоїть його улюблений гізмотронний апарат — гудуче свідчення гоблінської винахідливості. Цей пристрій і власний механічний хист Вреникс пускає в діло, постачаючи особливі знаряддя — злодійський інструмент і відмички — тим, хто береться повертати вкрадену контрабанду піратів Південних морів на Узбережжі Крамарів."}},faq={{q="Хто такий Вреникс Жалюгідний?",a="Вреникс — гоблін-майстер, що живе в Раджеті в Пустках. Він працює біля свого гізмотронного апарата й торгує особливими пристосуваннями та відмичками.",al={"вреникс","хто такий вреникс","вреникс жалюгідний"}},{q="Де знайти Вреникса?",a="Вреникс у портовому містечку Раджет на східному узбережжі Пусток, біля свого великого механічного пристрою.",al={"місце вреникса","де вреникс","вреникс раджет"}},{q="Що за гізмотронний апарат стоїть біля нього?",a="Це власний апарат Вреникса гоблінської конструкції: на ньому він майструє, проводить діагностику й виготовляє особливі інструменти, як-от точні злодійські відмички.",al={"гізмотронний апарат","машина вреникса","що це за машина"}},{q="Чому він допомагає шукачам пригод проти Флібустьєрів Південних морів?",a="Пірати Південних морів на узбережжі Пусток ховають цінну здобич у замкнених скриньках. Вреникс своїм механічним знаряддям допомагає вправним розбійникам зламувати ці скрині — на взаємну вигоду.",al={"чому південні моря","лор завдання пограбувати грабіжників","пірати вреникса"}}},fp="19,236,19.405.0,25.354.0,27.167.0,26.131.0,46.156.0,63.191.0"}
P.entries["npc:wynne-larson"] = {n="Вінн Ларсон",s="Вінн Ларсон — кравчиня, людина, що торгує мантіями в Кварталі магів Стормвінда. Відтоді як у Третій війні загинули давні осередки чарівного ткацтва — Даларан і Кель'Талас, — вона покладається на місцевих майстрів, щоб забезпечувати магів королівства. Вона раз у раз скеровує мандрівних чарівників до рідкісних матеріалів, потрібних для виготовлення могутнього зачарованого вбрання.",h="Вінн Ларсон — кравчиня, людина, що торгує мантіями в Кварталі магів Стормвінда.",kw={"вінн ларсон","мантії","квартал магів","кравецтво","маги","стормвінд"},ang={["class:Mage"]="Вінн — важлива зв'язкова на початку вашої магічної кар'єри: вона допоможе пошити ваші знамениті Маноткану Робу та Вбрання Астрального Вузла.",["faction:Alliance"]="Її крамниця показує, як Стормвінд узяв на себе забезпечення вцілілих рас Альянсу власним чарівним ремеслом.",["profession:Tailoring"]="Вінн уособлює ту важливу роль, яку відіграють у Стормвінді кравці після занепаду північних ткацьких осередків."},sec={{t="Новий ринок тайної магії",b="До Третьої війни найкращі тканини й зачароване вбрання надходили з магічних майстерень Даларана та з високоельфійського королівства Кель'Талас. Загибель обох північних держав підірвала давні торгові шляхи й знищила виробництво чарівних тканин. Торговцям на кшталт Вінн Ларсон із Кварталу магів Стормвінда довелося пристосовуватися: тепер вони співпрацюють безпосередньо з місцевими кравцями й зачарувальниками, як-от Лукан Корделл, щоб задовольнити дедалі більший попит міста на мантії та спорядження, витканого з чарами."},{t="Виготовлення чарівницьких мантій",b="Маги-новачки й підмайстри, що шукають вбрання, напоєне тайною силою, рано чи пізно потрапляють до крамниці Вінн. Вона точно знає, які матеріали потрібні, щоб пошити Маноткану Робу чи Вбрання Астрального Вузла, й нерідко відсилає адептів тайної магії в небезпечні краї по екзотичні реагенти — наприклад, Бездоганний Павучий Шовк. Завдяки їй маги Стормвінда лишаються гідно вбраними попри нестачу з півночі."}},faq={{q="Де знайти Вінн Ларсон?",a="Вінн Ларсон перебуває в Кварталі магів у Стормвінді й продає магічні тканинні нагрудники й вбрання молодим чарівникам.",al={"місце вінн ларсон","де вінн ларсон","торговець мантіями магів стормвінд"}},{q="Чому Вінн згадує Даларан і Кель'Талас?",a="Історично Даларан і Кель'Талас були головними виробниками зачарованих тканин у Східних Королівствах. Їхнє знищення під час Третьої війни обірвало постачання, тож торговцям у Стормвінді доводиться покладатися на місцевих майстрів і рідкісні привізні матеріали.",al={"вінн даларан діалог","мантії кель'таласу","чому мантії важко знайти"}},{q="Які завдання пов'язані з Вінн Ларсон?",a="Вінн допомагає магам здобути зшите на замовлення магічне вбрання й бере участь у ланцюжках завдань «Збирання матеріалів», «Маноткана Роба», «Бездоганний Павучий Шовк» і «Вбрання з астральним вузлом».",al={"завдання вінн ларсон","завдання мантій стормвінда","завдання мантії мановеб"}},{q="Що продає Вінн Ларсон?",a="Вона продає добірку простих і поліпшених тканинних роб, зокрема Палаючу Робу, Хроматичну Робу, Подвійно Прошиту Робу та Срібну Парадну Робу.",al={"товари вінн ларсон","які мантії продає вінн"}},{q="На кого Вінн покладається в Стормвінді, щоб мати матеріали?",a="Вінн згадує, що товар, який вона продає, тчуть і зачаровують місцеві майстри, передусім зачаровувач Лукан Корделл та інші міські ремісники.",al={"хто робить мантії вінн","зв'язок із лукан корделл"}},{q="Чи Вінн Ларсон родичка інших Ларсонів у Стормвінді?",a="Вона має спільне прізвище з Еваном Ларсоном, кравцем зі Стормвінда, і Дженні Ларсон — це натякає на родину ремісників, що працюють у міському кравецькому ремеслі.",al={"рід ларсон стормвінд","ейван ларсон","дженні ларсон"}}},fp="12,373,19.485.0,24.453.0,30.134.0,47.258.0,33.182.0,28.149.0,58.154.0,54.159.0"}
P.entries["npc:xavathras"] = {n="Ксаватрас",s="Ксаватрас — лютий ватажок сатирів, що отаборився серед наметів у Руїнах Констелласа в Скверноліссі. На чолі загону сатирів Нефритового Вогню він наглядає за оскверненням давнього місячного колодязя на службі своєму володареві Ксаварікові.",h="Ксаватрас — лютий ватажок сатирів, що отаборився серед наметів у Руїнах Констелласа в Скверноліссі.",kw={"ксаватрас","сатири","нефритовий вогонь","руїни констелласа","сквернолісся","місячний колодязь"},ang={["class:Druid"]="Друїди, що прагнуть зцілити Сквернолісся від демонічної зарази, бачать у навмисному отруєнні чистих вод Ксаватрасом зневагу до природи, яку треба зупинити.",["race:NightElf"]="Для нічних ельфів Ксаватрас — трагедія їхніх давніх родичів, що стали демонічними звірами, і водночас відвертий осквернитель їхніх священних місячних колодязів."},sec={{t="Осквернитель Констелласа",b="Серед заражених галявин Сквернолісся Руїни Констелласа потрапили в пазурі сатирів Нефритового Вогню. Розташувавшись у таборі серед ельфійської кам'яної кладки, Ксаватрас керує оскверненням сусіднього місячного колодязя на користь іншого жорстокого сатира — Ксаваріка. Отруюючи чисту воду демонічною енергією, Ксаватрас поглиблює скверну, що тримає ліс у своїх лещатах. Сама його присутність — пряма загроза будь-яким спробам відродити ліс, тож нічні ельфи, як-от Ерідан Блувінд, прирекли його на смерть."}},faq={{q="Хто такий Ксаватрас?",a="Ксаватрас — жорстокий ватажок сатирів, що командує сатирами Нефритового Вогню, які окопалися в Руїнах Констелласа в Скверноліссі. Він служить Ксаварікові й має осквернити давній ельфійський місячний колодязь серед руїн.",al={"хто такий ксаватрас","лор ксаватраса","бос сатир констеллас"}},{q="Де знайти Ксаватраса?",a="Ксаватрас отаборився серед наметів сатирів у Руїнах Констелласа — давньому місці нічних ельфів у південно-центральній частині Сквернолісся.",al={"місце ксаватраса","де ксаватрас","руїни констеллас сатир"}},{q="Чому Ерідан Блувінд хоче смерті Ксаватраса?",a="Ерідан Блувінд прагне захистити Сквернолісся й зупинити нестримне поширення демонічної скверни. Ксаватрас старанно плекає осквернений місячний колодязь, тож його знищення — першочергове завдання для тих, хто намагається очистити край.",al={"чому вбивати ксаватраса"}},{q="На кого працює Ксаватрас?",a="Ксаватрас діє від імені Ксаваріка — ще одного жорстокого й могутнього сатира в Скверноліссі, який допомагає Легіонові втримувати осквернений ліс у своїх пазурах.",al={"хто господар ксаватраса","ксаварик ксаватрас"}}},fp="9,222,23.533.0,17.220.0,29.137.0,45.226.0,29.160.0"}
P.entries["npc:yaw-sharpmane"] = {n="Яв Шарпмейн",s="Яв Шарпмейн — досвідчений тауренський наставник мисливців у Селі Бладгуф у Малгорі. Він веде молодих мисливців, що виходять із Табору Нарачі, й допомагає їм опанувати диких звірів прабатьківських рівнин.",h="Яв Шарпмейн — досвідчений тауренський наставник мисливців у Селі Бладгуф у Малгорі.",kw={"яв шарпмейн","мисливець","наставник","приборкання","звір","село бладгуф","малгор"},ang={["class:Hunter"]="Для тауренських мисливців, що залишають безпечне Плато Червоної Хмари, Яв Шарпмейн — незамінний наставник, який допоможе вам заприязнитися з вашим найпершим диким супутником.",["race:Tauren"]="Яв утілює шановану традицію Шу'хало — жити в злагоді з природою й шанувати духів диких звірів Малгору."},sec={{t="Провідник на рівнинах",b="Серед наметів і вогнищ Села Бладгуф Яв Шарпмейн служить Шу'хало як наставник у влучній стрільбі, вистежуванні та виживанні. Молодих мисливців, які довели свою вправність на Плато Червоної Хмари, посилають до Ява відточувати ремесло, щойно вони ступають на широкі рівнини Малгору."},{t="Опанування зв'язку",b="Найважливіша роль Ява — провести мисливців-новачків через прадавній обряд приборкання диких звірів. Він доручає посвячуваним заприязнитися з тутешньою живністю Малгору, перевіряючи їхнє терпіння й повагу до природної рівноваги, і лише тоді навчає, як доглядати й виховувати постійного супутника."}},faq={{q="Хто такий Яв Шарпмейн?",a="Яв Шарпмейн — місцевий наставник мисливців у Селі Бладгуф. Він навчає молодих тауренів-мисливців влучної стрільби, виживання в дикій природі й мистецтва приручати звірів-супутників.",al={"хто такий яв","яв шарпмейн","тренер мисливців бладгуфа"}},{q="Де знайти Ява Шарпмейна?",a="Яв перебуває в Селі Бладгуф у центральному Малгорі, на березі Озера Кам'яного Бика.",al={"місце ява шарпмейна","де яв","координати ява"}},{q="Чого Яв Шарпмейн навчає мисливців?",a="Він дає звичайне навчання мисливців — нові ранги основних умінь — і веде багатонадійних мисливців крізь обряди, потрібні, щоб приручати звірів і командувати ними.",al={"чого навчає яв","навички мисливця ява","вміння ява"}},{q="Які завдання дає Яв?",a="Яв дає тауренську версію ланцюжка завдань про приручення звіра: він починається із завдання «Шлях мисливця» й веде через «Приборкання звіра» і «Навчання звіра».",al={"завдання ява","завдання ява шарпмейна"}},{q="Чому мисливцям треба поговорити з ним приблизно на 10-му рівні?",a="Досягнувши своєї десятої весни, мисливці приходять до Ява, щоб навчитися священних способів ловити, годувати й приборкувати постійних звірів-супутників із диких просторів Малгору.",al={"чому говорити з явом на 10 рівні","приборкання звіра бладгуф"}},{q="Чи спілкується Яв Шарпмейн з тими, хто не мисливець?",a="Він чемно розмовлятиме з мандрівниками інших покликань, але його фахові знання й особливі випробування призначені лише для мисливців.",al={"чи яв говорить з не мисливцями","чи інші класи можуть говорити з явом"}}},fp="13,216,21.311.0,18.309.0,21.179.0,31.100.0,38.159.0,27.165.0,52.178.0,45.148.0"}
P.entries["npc:yeh-kinya"] = {n="Єх'кінья",s="Єх'кінья — учений із тролів джунглів, що мешкає в Порту Стімвідла на пустельному узбережжі Танарісу. Він запевняє, що шукає давні знання й артефакти, аби збагнути темні сили, і посилає охочих шукачів пригод по всьому Азероту збирати загублені тролячі реліквії.",h="Єх'кінья — учений із тролів джунглів, що мешкає в Порту Стімвідла на пустельному узбережжі Танарісу.",kw={"єх'кінья","гаккар","порт стімвідла","тролі","вітряний змій","зандаларі"},ang={["class:Priest"]="Жерців, чутливих до духовної сутності, може глибоко занепокоїти те, як буденно Єх'кінья збирає ув'язнених духів верескунів.",["race:Troll"]="Тролі Темного Списа розуміють, яку смертельну небезпеку несе повернення Гаккара."},sec={{t="Учений із Порту Стімвідла",b="Єх'кінья, що байдикує серед гоблінів і портових вантажників Порту Стімвідла, видає себе за тихого дослідника історії й духів. Він наймає мандрівників, щоб ті розшукували маловідомі магічні предмети по всьому Калімдору й Східних Королівствах — від прадавніх яєць у Пригір'ї до кам'яних скрижалей із пророцтвами, похованих у руїнах Зул'Фаррака. Він запевняє, що ці доручення служать мирним науковим пошукам у прадавній історії тролів, але його особлива увага до бога крові Гаккара викликає підозру в пильних спостерігачів."},{t="Зміїна підступність",b="Під личиною вченого ховається фанатичний шанувальник Гаккара Душолупа. Кожен артефакт і кожну есенцію душі, які він збирає, Єх'кінья хитро використовує, щоб підготувати фізичне відродження страхітливого Бога Крові в Азероті. Щойно Шукач Айронбут складає докупи всі шматки його задуму й викриває змову, Єх'кінья скидає маску дружелюбності. Замість того щоб відповісти за зраду, він перетворюється на зеленого вітряного змія й тікає через відкрите море на південь, у Південні Моря, лишаючи одурених героїв шукати допомоги в зандаларі на Острові Йоджамба."}},faq={{q="Хто такий Єх'кінья?",a="Єх'кінья — троль джунглів, що стоїть біля води в Порту Стімвідла в Танарісі. Він видає себе за вченого, який шукає історичні реліквії й духів і особливо цікавиться тролівським богом Гаккаром.",al={"лор єх'кінья","хто такий єх'кінья","єх'кінья нпс"}},{q="Навіщо Єх'кіньї Пророцтво Мош'ару й Прадавнє Яйце?",a="Єх'кінья каже, що ці артефакти потрібні йому для вивчення давньої історії тролів і їхніх духів. Таблички Мош'ару лежать у руїнах Зул'Фаррака, а Прадавнє Яйце — у Пригір'ї, і обидва пов'язані з його цікавістю до Гаккара.",al={"навіщо прадавнє яйце","пророцтво мош'ару","мета єх'кіньї"}}},fp="9,258,32.506.0,20.540.2,17.214.2,69.225.2"}
P.entries["npc:yvette-farthing"] = {n="Іветт Фартінґ",s="Іветт Фартінґ — мешканка Брілла з Відступників на Галявинах Тірісфалю, що живе в Таверні «Шибеничний Кінець» разом зі своїм батьком Коулменом. Хоч вона здається такою ж загартованою й відстороненою, як будь-хто з підданих Сильвани, у ній досі жевріє привид смертного кохання, яке обірвала Погибель.",h="Іветт Фартінґ — мешканка Брілла з Відступників на Галявинах Тірісфалю, що живе в Таверні «Шибеничний Кінець»...",kw={"іветт фартінґ","турман аґаманд","кохання","лист","таверна шибеничний кінець","млини аґаманда"},ang={["race:Undead"]="Іветт утілює глибокий душевний конфлікт, який переживають багато Відступників: боротьбу між невідступними людськими спогадами про кохання й гіркою, загартованою дійсністю нежиття."},sec={{t="Відлуння млинів",b="До того як Третя війна обернула Лордерон на руїну, Іветт кохала Турмана Аґаманда, одного зі спадкоємців квітучих Млинів Аґаманда. Коли чума Погибелі підступила, Іветт і її батько Коулмен благали Турмана покинути маєток і тікати разом із ними. Турман відмовився з відданості спадщині своєї родини. Зрештою обоє загинули й повстали в нежитті, та якщо Іветт знайшла місце серед вільних Відступників у Бріллі, то трагічна остаточна доля Турмана лишалася їй невідомою."},{t="Останнє прощання",b="Перш ніж млини захопили, Турман написав Іветт поспішного любовного листа, у якому розповів про зраду свого брата Девліна й оплакав свій вибір лишитися. Погибель перехопила послання, і воно загубилося серед руїн Млинів Аґаманда, доки його не знайшли шукачі пригод. Прочитавши передсмертне зізнання Турмана, Іветт на мить виявляє справжній смертний розпач, а тоді змушує себе повернутися до холодної відстороненості — з гіркотою, що таким давнім прив'язаностям немає місця в похмурій дійсності Відступників."}},faq={{q="Хто така Іветт Фартінґ?",a="Іветт Фартінґ — Відступниця, що живе в Таверні «Шибеничний Кінець» у Бріллі. Вона донька Коулмена Фартінґа, а до того, як Третя війна знищила королівство, жила серед ферм Галявин Тірісфалю.",al={"лор іветт фартінґ","хто така іветт","іветт брилл"}},{q="Що пов'язує Іветт із Млинами Аґаманда?",a="За життя Іветт кохалася з Турманом Аґамандом. Коли край опинився під загрозою чуми, вона вмовляла його тікати разом, але він вирішив лишитися й боронити родинний маєток.",al={"іветт аґамонд","турман аґамонд і іветт","коханець іветт"}},{q="Що стається, коли приносиш їй лист Турмана?",a="Коли шукач пригод приносить давно загублений лист Турмана, Іветт, прочитавши його останні слова кохання й зради, на мить ламається від горя. Та вона швидко черствіє й заявляє, що тепер вона Відступниця, а почуття смертних нічого не варті.",al={"здача листа непереданого","нагорода за лист турмана","реакція іветт на лист"}},{q="Хто батько Іветт?",a="Її батько — Коулмен Фартінґ, Відступник, що теж живе в Таверні «Шибеничний Кінець» у Бріллі. Спершу вони обоє протрималися досить довго, щоб утекти разом, але зрештою обох здолала чума, і вони стали Відступниками.",al={"батько іветт","коулмен і іветт","хто такий коулмен фартінґ"}}},fp="15,285,19.496.0,16.499.1,23.213.0,45.201.0,54.262.1,23.230.0"}
P.entries["npc:zaldimar-wefhellt"] = {n="Залдімар Вефгеллт",s="Залдімар Вефгеллт — людський наставник магів на верхньому поверсі корчми «Лев'яча Гордість» у Ґолдширі. Він навчає чарівників-початківців, що проходять Лісом Елвінн, перш ніж відправити їх до вищих практиків у Стормвінді.",h="Залдімар Вефгеллт — людський наставник магів на верхньому поверсі корчми «Лев'яча Гордість» у Ґолдширі.",kw={"залдімар вефгеллт","маг","наставник","ґолдшир","лев'яча гордість","таємна магія"},ang={["class:Mage"]="Для молодих людей-магів, що покидають Абатство Нортшира, Залдімар — перший наставник, якого ви зустрічаєте в ширшому світі: він навчає перших заклинань, перш ніж скерувати вас до Святилища Чародія в Стормвінді.",["faction:Alliance"]="Розташувавшись у гамірній корчмі «Лев'яча Гордість», Залдімар дбає, щоб чарівники Альянсу, які патрулюють Ліс Елвінн, мали доступ до магічного навчання без потреби одразу вирушати до Стормвінда."},sec={{t="Маг у Ґолдширі",b="Хоч корчма «Лев'яча Гордість» у Ґолдширі найбільше відома втомленими подорожніми, галасливими шукачами пригод і місцевими плітками, у її верхніх кімнатах живуть наставники різних ремесел. В одній із кімнат другого поверху Залдімар Вефгеллт навчає магів-новачків основ таємної магії, вогню й морозу. Щойно учень переростає його ранню науку, він посилає його на північ до Кварталу магів у Стормвінді — вчитися в Дженнеї Кеннон."}},faq={{q="Хто такий Залдімар Вефгеллт?",a="Залдімар Вефгеллт — наставник таємної магії в Корчмі «Лев'яча Гордість» у Ґолдширі. Він допомагає новачкам-магам Альянсу вивчити перші закляття й спрямовує їх на подальше навчання в Стормвінд.",al={"хто такий залдімар","роль залдімара вефгеллта","тренер магів ґолдшира"}},{q="Де знайти Залдімара Вефгеллта?",a="Він на другому поверсі Корчми «Лев'яча Гордість» у Ґолдширі, у крайній лівій кімнаті нагорі сходів.",al={"місце залдімара","де залдімар","як знайти залдімара"}},{q="Куди Залдімар посилає магів-новачків?",a="Коли маг здобуде основні навички, Залдімар посилає його до Кварталу магів у Стормвінді — до Дженнеї Кеннон у Святилищі Чародія, де навчання триває.",al={"завдання залдімара","до кого залдімар посилає","поговоріть із дженнеєю"}},{q="Чи має Залдімар родичів серед інших магів?",a="Про його родичів нічого не відомо; він зосереджений на навчанні в Корчмі «Лев'яча Гордість».",al={"рід вефгеллт","зална вефгеллт","родичі залдімара"}}},fp="17,261,21.436.0,25.207.0,35.122.0,38.167.0,39.80.0"}
P.entries["npc:zamja"] = {n="Замджа",s="Замджа — тролиця з Темного Спису, наставниця кулінарії, що працює в гамірному Проході в Оргріммарі. Відома певною рукою з тесаком, вона вчить шукачів пригод Орди готувати ситні страви з калімдорської дичини.",h="Замджа — тролиця з Темного Спису, наставниця кулінарії, що працює в гамірному Проході в Оргріммарі.",kw={"замджа","кулінарія","волок","оргріммар","тесак","ґаджетзан"},ang={["profession:Cooking"]="Замджа — одна з головних наставниць кулінарії для героїв Орди в Оргріммарі: вона навчає основних рецептів, а згодом посилає досвідчених кухарів на південь, до Танаріса, по поглиблену науку.",["race:Troll"]="Як і багато тролів Темного Спису, що оселилися в Оргріммарі під стягом Вождя Тралла, Замджа приносить у серце столиці Орди тролячу кмітливість і кулінарне вміння."},sec={{t="Тесак на Проході",b="На звивистій каньйонній стежці Проходу Замджа днями розбирає м'ясо й учить голодних мандрівників Орди дбати про себе. Практичне куховарство — важливе вміння для виживання на суворих теренах Дуротару й Пусток, і Замджа дбає, щоб кожен, хто готовий узяти сковороду, засвоїв, як перетворити сиру дичину на поживний харч. Кухарів, які опанували основні рецепти й шукають подальшої науки, вона посилає на південь, до Ґаджетзана."}},faq={{q="Хто така Замджа?",a="Замджа — тролиця з Темного Списа, наставниця кулінарії в Рові в Оргріммарі. Вона навчає мистецтва куховарства членів Орди й допомагає початківцям-кухарям удосконалювати ремесло.",al={"замджа нпс","хто така замджа","замджа оргріммар"}},{q="Де знайти Замджу?",a="Її можна знайти в Рові — затіненому звивистому проході, що з'єднує Долину Сили з Долиною Честі в Оргріммарі.",al={"місце замджі","де замджа","точка тренера замджі"}},{q="Чого навчає Замджа?",a="Замджа навчає кулінарії й рецептів, за якими шукачі пригод можуть готувати їжу зі звірів і дичини, вполюваних по всьому Калімдору. Коли кухар досягає певного рівня, вона спрямовує його до досвідченіших наставників.",al={"чого навчає замджа","рецепти замджі","тренер кулінарії оргріммар"}},{q="Куди Замджа посилає досвідчених кухарів?",a="Коли вміння кухаря переростають те, чого можна навчитися в Оргріммарі, Замджа посилає його в Ґаджетзан у Танарісі із завданням «До Ґаджетзана, вперед!» — шукати Дірджа Квіккліва.",al={"завдання замджі","до ґаджетзана вирушайте","майстерна кулінарія орда"}}},fp="5,241,21.487.0,13.171.0,23.131.0,31.236.0,37.181.0"}
P.entries["npc:zangen-stonehoof"] = {n="Занген Стоунгуф",s="Занген Стоунгуф — таурен-хранитель вогнища на Високому Узвишші в самому серці Тандер Блафа. Сумлінний і шанований серед своїх, він щовечора вірно доглядає центральне полум'я й водночас організовує допомогу своїм далеким родичам по всьому Калімдору.",h="Занген Стоунгуф — таурен-хранитель вогнища на Високому Узвишші в самому серці Тандер Блафа.",kw={"занген стоунгуф","високе узвишшя","вогнище","тандер блаф","рау кліффраннер","ашенваль","місячний колодязь"},ang={["faction:Horde"]="Для мандрівників, що відвідують велику столову гору Тандер Блафа, Занген — той, через кого можна вирушити далі, у спірні краї на кшталт Ашенвалю.",["race:Tauren"]="Занген утілює єдність племен, безпосередньо пов'язуючи громадське серце Малгору з далекими родичами, як-от Кліффраннери в Тисячі Голок."},sec={{t="Хранитель вогню Високого Узвишшя",b="На Високому Узвишші Тандер Блафа Занген Стоунгуф доглядає центральне громадське вогнище, звідки видно найвищі кручі міста. Коли над Малгором западають сутінки, Занген розпалює вогонь, даруючи тепло й незгасний маяк племенам, що зібралися під проводом Верховного Вождя Кайрна Бладгуфа. Крім того, він підтримує зв'язки із союзниками за межами столової гори Малгору й допомагає в духовних та обрядових справах, що відбуваються по всьому континенту."},{t="Допомога Кліффраннерам",b="Занген — посередник для Рау Кліффраннера, свого товариша, що служить на півдні, у Тисячі Голок. Коли Рау знадобилася містична вода з місячного колодязя нічних ельфів для священних обрядів, Занген залучив надійних шукачів пригод Орди, щоб ті вирушили до спірних лісів Ашенвалю. Здобувши наповнену фіалу з прадавніх гаїв і відіславши її на південь, до Застави Вільного Вітру, Занген відіграє непомітну, але вирішальну роль у збереженні прадавніх обрядів і підтримці розкиданих застав тауренів."}},faq={{q="Хто такий Занген Стоунгуф?",a="Занген Стоунгуф — таурен із Тандер Блафу, якого можна знайти біля великого центрального вогнища на Високому Узвишші. Щовечора він підтримує вогонь і допомагає далеким родичам, організовуючи допомогу й доручення гінців по всьому Калімдору.",al={"хто такий занген","занген стоунгуф","що робить занген"}},{q="Що Занген робить із вогнищем?",a="Щовечора, коли западає ніч, Занген розпалює велике вогнище перед собою на Високому Узвишші, даруючи світло й тепло горішньому ярусу кручі.",al={"чому занген біля вогнища","багаття зангена","розпалювання вогню"}},{q="Навіщо Зангенові вода з місячного колодязя в Ашенвалі?",a="Занген діє від імені Рау Кліффраннера, що служить на Заставі Вільного Вітру в Тисячі Голок. Рау потрібна вода з місячного колодязя Ашенвалю для священного обряду, і Занген доручає вправним мандрівникам здобути її й донести на південь.",al={"завдання місячного колодязя зангена","священне полум'я","навіщо вода колодязя"}},{q="Де знайти Зангена Стоунгуфа?",a="Він стоїть посеред Високого Узвишшя в Тандер Блафі, просто біля спільного вогнища на горішньому плато.",al={"місце зангена","знайти зангена стоунгуфа","де занген"}}},fp="16,259,29.480.0,23.473.0,24.219.0,37.168.0,51.243.0,36.113.0"}
P.entries["npc:zankaja"] = {n="Занкаджа",s="Занкаджа — молода орчиха з Оргріммара, що живе на шляху між Долиною Сили й Долиною Мудрості. Вона з тривогою чекає звісток від свого коханого, Доґрана, якого відрядили служити на Перехрестя, на небезпечне прикордоння Пусток.",h="Занкаджа — молода орчиха з Оргріммара, що живе на шляху між Долиною Сили й Долиною Мудрості.",kw={"занкаджа","доґран","перехрестя","пустки","оргріммар","чекання"},ang={["faction:Horde"]="Її благання нагадує шукачам пригод Орди, що утримання таких застав, як Перехрестя, коштує піхотинцям справжньої крові й жертв.",["race:Orc"]="Занкаджа втілює особисту ціну, яку платять звичайні родини Дуротару, де обов'язок перед новою державою Вождя раз у раз посилає рідних на дикі, смертельно небезпечні кордони."},sec={{t="Серце, що чекає",b="Життя в молодій столиці Орди нелегке, але для Занкаджі справжнє випробування — чекання. Її коханий Доґран отримав підвищення, і його послали на південь, у Пустки, посилити заставу на Перехресті. Для воїна це честь, але Пустки — жорстокий край, що кишить шипогривами, кентаврами й лютими звірами. Коли Доґран не надіслав звістки й не повернувся додому, як обіцяв, Занкаджа почала шукати мандрівників, готових дізнатися про його долю."},{t="Сумні вісті",b="Найгірші страхи Занкаджі справджуються: розпитування в Пустках з'ясовують, що Доґран потрапив до лап шипогривів. Хоч у стінах оргріммарського каньйону вона ще тримається надії, прикордоння безжальне, і вісті, які приносять шукачі пригод, малюють похмуру картину жертви на небезпечних кордонах Орди."}},faq={{q="Де знайти Занкаджу?",a="Занкаджа стоїть при стежці, що з'єднує Долину Сили з Долиною Мудрості в Оргріммарі.",al={"місце занкаджі","де занкаджа","знайти занкаджу"}},{q="Хто такий Доґран?",a="Доґран — чоловік Занкаджі. Він орк-воїн, якого нещодавно підвищили й призначили на Перехрестя в Пустках.",al={"хто такий доґран","доґран","партнер занкаджі"}},{q="Чому Занкаджа турбується?",a="Доґрана послали в суворі нетрі Пусток служити на Перехресті, а він не повернувся й не подав звістки додому, тож Занкаджа боїться, що на рубежі з ним сталася біда.",al={"чого хоче занкаджа","біда занкаджі","чому занкаджа сумна"}},{q="Про що Занкаджа просить шукачів пригод?",a="Вона просить шукачів пригод, які вирушають з Оргріммара, навідатися до Капітана Ґазроґа на Перехресті й розпитати, де Доґран і чи все з ним гаразд.",al={"завдання занкаджі","завдання новини про доґрана"}},{q="Що сталося з Доґраном у Пустках?",a="Занкаджа не знає напевно, де Доґран. Вона просить мандрівників поговорити з Ґазроґом на Перехресті й далі йти слідом уже звідти.",al={"чи доґран мертвий","доля доґрана","що сталося з доґраном"}}},fp="7,262,16.460.0,14.325.1,25.114.0,14.124.0,23.180.0,40.150.0,39.137.1"}
P.entries["npc:zardeth-of-the-black-claw"] = {n="Зардет із Чорного Кігтя",s="Зардет із Чорного Кігтя — чорнокнижник, що мешкає в тьмяних підземних покоях під шинком «Зарізане Ягня» в Кварталі магів Стормвінда. Під личиною непримітного відвідувача він потай вживає заходів, щоб уберегти таємне коло чорнокнижників міста від сторонніх очей. А коли допитливі вельможі починають надто пильно придивлятися до їхніх справ, Зардет дбає, щоб ці розпити припинилися назавжди.",h="Зардет із Чорного Кігтя — чорнокнижник, що мешкає в тьмяних підземних покоях під шинком «Зарізане Ягня» в...",kw={"зардет","чорний кіготь","чорнокнижники","зарізане ягня","квартал магів","отрута","вішок"},ang={["class:Warlock"]="Зардет утілює холодний прагматизм, потрібний чорнокнижникам-людям, щоб вижити в самому серці Альянсу, — і доводить, що виживання нерідко залежить від випереджальних убивств.",["faction:Alliance"]="Для вірних Альянсу Зардет — суворе нагадування про розтлінне підчерев'я, що гниє просто під сяйливими вулицями Стормвінда.",["profession:Herbalism"]="Задум Зардета тримається на отруйних рослинах на кшталт Сльози Тіллоа й Мускусного Кореня — це показує, яку смертельну силу може мати рідкісна дика флора."},sec={{t="Тінь під «Ягням»",b="Поки у височенних шпилях Кварталу магів відкрито вивчають тайну науку, підземні тунелі під «Зарізаним Ягням» дають прихисток тим, хто знається на темніших мистецтвах. Зардет із Чорного Кігтя діє з цих склепів як пильний охоронець чаклунів, що ховаються просто під носом у міської варти. Альянс офіційно засуджує магію скверни, тож виживання вимагає залізної таємниці й готовності знищити будь-яку загрозу, перш ніж у двері постукають королівські слідчі."},{t="Як змусити знать мовчати",b="Коли Лорд Баурлес К. Вішок прочув про прихований ковен чорнокнижників, вельможа почав домагатися від Дому Вельмож негайного й повного розслідування. Розуміючи, що таке пильне око знищить їхній підземний прихисток, Зардет підготував таємну відповідь. Скориставшись відомою слабкістю лорда до вишуканих трунків, він відрядив посланця через Східні Королівства зібрати рідкісні смертоносні рослини — Сльозу Тіллоа із Сутінколісся та Мускусний Корінь з-під Каменетесної Греблі."},{t="Шляхетний трунок",b="Змішавши зібрані реагенти з міцним темним елем, Зардет зварив Темне Пиво Чорного Пазура — смертельний напій, що мав здаватися звичайним розкішним подарунком. Щойно трунок доставили до маєтку Вішока, отрута подіяла швидко й тихо. Вішок загинув, його кампанія згасла, перш ніж корона встигла втрутитися, — і Зардет зі спільниками-чорнокнижниками вберегли свій підземний осередок під «Зарізаним Ягням»."}},faq={{q="Хто такий Зардет із Чорного Кігтя?",a="Зардет — чорнокнижник-людина, що перебуває в підземних склепах під таверною «Зарізане Ягня» в Кварталі магів Стормвінда. Він діє від імені прихованого братства чорнокнижників: відводить підозри й усуває загрози їхній таємній присутності в місті.",al={"зардет","хто такий зардет","зардет стормвінд"}},{q="Де знайти Зардета?",a="Він під «Зарізаним Ягням» — корчмою в південній частині Кварталу магів у Стормвінді. Увійдіть до таверни, знайдіть у глибині прохід униз і йдіть звивистими катакомбами до осередку чорнокнижників.",al={"місце зардета","де зардет","зардет зарізаний ягня"}},{q="Чому Зардет хоче смерті Лорда Вішока?",a="Лорд Баурлес К. Вішок знайшов докази, що під містом діють чорнокнижники, і почав домагатися від знаті Стормвінда офіційного розслідування. Якби воно відбулося, міська влада викоренила б ковен «Зарізаного Ягняти» і стратила б його членів.",al={"чому вбивати вішока","ціль лорд вішок","причина благородного варева"}},{q="Що таке Темне Пиво Чорного Пазура?",a="Темне Пиво Чорного Пазура — смертоносне вариво Зардета. Він змішує звичайне темне пиво з двома рідкісними отруйними рослинами: Сльозою Тіллоа з Даркширу і Мускусним Коренем із Багнокраю. Напій мав удавати дорогий трунок і тихо вбити Лорда Вішока.",al={"чорне пиво пазура","що таке варево","отрута вішока"}},{q="Що таке Чорний Кіготь?",a="Чорний Кіготь — це тіньове угруповання чи звання, яке Зардет має в таємній мережі чорнокнижників Стормвінда. Вони діють поза увагою варти Стормвінда й Кірін-Тору, захищаючи своїх членів смертоносною потайністю.",al={"значення чорного кігтя","хто чорний кіготь","чорнокнижник чорного кігтя"}},{q="Чому чорнокнижникам узагалі дозволено бути в Стормвінді?",a="Відкрито їх не терплять. Темні заклиначі ховаються в місті, але мусять сидіти глибоко в підвалах під «Зарізаним Ягням». Влада або заплющує очі, бо вони бувають корисні, або нічого не знає, бо агенти на кшталт Зардета усувають кожного, хто збирається їх викрити.",al={"чи чорнокнижники легальні","лор чорнокнижників стормвінда","чому чорнокнижник у місті"}}},fp="25,408,25.498.0,22.517.1,12.434.2,33.257.0,25.245.0,40.280.0,25.274.0,23.259.0,45.305.0"}
P.entries["npc:zargh"] = {n="Зарг",s="Зарг — оркський торговець м'ясом на Перехресті в Пустках. Окрім того, що продає харчі мандрівникам, він часто постачає добірні шматки місцевої дичини Корчмарці Гришці в Оргріммар.",h="Зарг — оркський торговець м'ясом на Перехресті в Пустках.",kw={"зарг","різник","корчмарка гришка","перехрестя","гострі лев'ячі котлети","оргріммар"},ang={["faction:Horde"]="Його торговий шлях між Перехрестям і Оргріммаром учить молодих гінців Орди користуватися мережею перельотів на вітрокрилах між Дуротаром і Пустками.",["profession:Cooking"]="Зарг — один із небагатьох торговців у Пустках, що продає рецепт Гострих Лев'ячих Котлет, цінний для кухарів, які хочуть пустити в діло м'ясо місцевих хижаків."},sec={{t="Різник Перехрестя",b="Серед метушні Перехрестя Зарг тримає крамницю, де продає в'ялене м'ясо, гомілки й дичину з навколишніх рівнин. Для шукачів пригод, що вирушають углиб суворої дикої місцевості, його запаси — життєво важлива пожива. Окрім звичайної торгівлі, він підтримує тісні зв'язки зі столицею Орди й регулярно відсилає через Дуротар ретельно дібране м'ясо Гришці, корчмарці з Долини Сили."},{t="Доручення гінця",b="Зарг часто просить мандрівних гінців доправити свіжі партії м'яса Корчмарці Гришці в Оргріммар на вітрокрилі, щоб припаси дісталися, поки не зіпсувалися. Схоже, їх пов'язує не лише робота: у листі Гришка згадує прикру пригоду, коли Зарг утратив палець, а отримавши від неї відповідь, Зарг натякає, що мандрівникові, можливо, ще доведеться погуляти на весіллі."}},faq={{q="Де знайти Зарга?",a="Зарг перебуває на Перехресті — головному поселенні Орди в Пустках. Він торгує м'ясом серед інших крамарів табору.",al={"місце зарга","де зарг","зарг нпс"}},{q="Що пов'язує Зарга з Корчмаркою Гришкою?",a="Зарг постачає Корчмарці Гришці в Оргріммар добірне м'ясо з Пусток. Їхнє листування свідчить про теплі, близькі стосунки: отримавши від неї лист, Зарг навіть натякає, що незабаром може надійти запрошення на весілля.",al={"зарг гришка","стосунки зарга","кого одружує зарг"}},{q="Що сталося з пальцем Зарга?",a="Як пише Гришка в листі, колись Зарг, розбираючи тушу, втратив палець. Відтоді між ними ходить жарт про те, що ж потрапляє в його м'ясні вирізки.",al={"загублений палець зарга","нещасний випадок зарга"}},{q="Що продає Зарг?",a="Він продає різні харчі: окости, в'ялені шинкові стейки, гомілки дикого кабана, а також рецепт Гострих Лев'ячих Котлет.",al={"крам зарга","товари зарга"}}},fp="5,203,25.416.0,18.411.1,23.138.0,48.234.0,32.188.0,21.129.0"}
P.entries["npc:zarlman-two-moons"] = {n="Зарлман Ту-Мунс",s="Зарлман Ту-Мунс — шанований містик тауренів, що мешкає в Селі Бладгуф у центрі Малгору. Поки Бейн Бладгуф наглядає за щоденними земними справами селища, Зарлман веде його духовне життя й спілкування з духами. Він відіграє ключову роль у посвяті молодих тауренів у доросле життя через священний Обряд Видіння.",h="Зарлман Ту-Мунс — шанований містик тауренів, що мешкає в Селі Бладгуф у центрі Малгору.",kw={"зарлман ту-мунс","містик","обряд видіння","духи","село бладгуф","бейн бладгуф","малгор"},ang={["class:Shaman"]="Зарлман — зразок класичної шаманської традиції тауренів, що врівноважує єднання з духами й практичний провід племенем.",["faction:Horde"]="Перебуваючи в центральному осередку Малгору, Зарлман знайомить новоприбулих союзників Орди з глибокими духовними звичаями, що формують культуру тауренів.",["race:Tauren"]="Для шукачів пригод із тауренів Зарлман — неодмінний провідник, який допомагає вам завершити священні обряди юності й пробудити духовний зір."},sec={{t="Хранитель Незримого",b="У Селі Бладгуф провід поділений між тілесним і містичним. Бейн Бладгуф керує обороною та земними потребами поселення, але саме Зарлман Ту-Мунс підтримує гармонію світу духів. У культурі, глибоко вкоріненій у шані до Матері-Землі й мудрості предків, Зарлман слугує провідником між щоденними клопотами рівнин і позачасовими голосами минулого."},{t="Обряд Видіння",b="Найважливіший обов'язок Зарлмана перед народом — проводити Обряд Видіння, традиційне випробування, яке має пройти кожен таурен, що дорослішає. Навчаючи посвячених готувати священні напої й уважно слухати знамення предків, він допомагає молодим мисливцям, шаманам і воїнам відкрити свій призначений шлях і духів-провідників. Під його проводом посвячені засвоюють: тілесна сила на рівнинах мало важить без духовної ясності."}},faq={{q="Хто такий Зарлман Ту-Мунс?",a="Зарлман Ту-Мунс — знаний таурен-містик у Селі Бладгуф. Поки Бейн Бладгуф відає мирськими справами й обороною села, Зарлман пильнує духовний добробут поселення й веде молодих шукачів пригод крізь прадавні звичаї племені.",al={"хто такий зарлман","лор зарлмана ту-мунса","хто шаман бладгуфа"}},{q="Яка роль Зарлмана в Селі Бладгуф?",a="Зарлман опікується духовними справами, спілкуванням із предками й культурними обрядами мешканців Села Бладгуф. Він доповнює мирське проводирство Бейна Бладгуфа, дбаючи, щоб плем'я жило в рівновазі з духами природи й предками.",al={"робота зарлмана","мета зарлмана","містик села бладгуф"}},{q="Що таке Обряд Видіння?",a="Обряд Видіння — традиційний обряд посвяти для молодих тауренів, що мандрують Малгором. Під проводом Зарлмана посвячувані п'ють обрядовий напій, що відкриває їм духовний зір, і можуть іти за видіннями й отримувати настанови від духів природи.",al={"обряд видіння","що за обряд видіння","тауренський обряд видіння"}},{q="Де знайти Зарлмана Ту-Мунса?",a="Зарлман Ту-Мунс перебуває в Селі Бладгуф у центрі Малгору, у вигині Озера Кам'яного Бика.",al={"де зарлман","місце зарлмана","як знайти зарлмана"}},{q="Як Зарлман пов'язаний із Бейном Бладгуфом?",a="Зарлман працює пліч-о-пліч із Бейном Бладгуфом як його духовний відповідник. Поки Бейн керує селом у мирських і військових справах, Зарлман дає містичну мудрість і пильнує духовну рівновагу племені.",al={"бейн і зарлман","зв'язок зарлмана з бейном"}},{q="Чому Обряд Видіння такий важливий для молодих тауренів?",a="Обряд Видіння обов'язковий для кожного таурена, що досягає повноліття. Він знаменує перехід від неперевіреної юності до визнаного члена племені, відкриває внутрішнього духа-провідника й скріплює зв'язок із Земною Матір'ю.",al={"чому обряд видіння важливий","значення обряду видіння"}}},fp="17,328,20.424.0,18.436.0,25.285.0,44.250.0,27.256.0,37.120.0,43.211.0,52.230.0"}
P.entries["npc:zarrin"] = {n="Заррін",s="Заррін — кулінарний наставник, нічний ельф, що перебуває в Доланаарі на вітті Тельдрассила. Доглядаючи відкрите вогнище за сільською корчмою, він навчає молодих нічних ельфів і гостей традиційних калдорейських способів куховарства.",h="Заррін — кулінарний наставник, нічний ельф, що перебуває в Доланаарі на вітті Тельдрассила.",kw={"заррін","кулінарія","наставник","вогнище","доланаар","корчма","тельдрассил"},ang={["profession:Cooking"]="Для шукачів пригод, що починають подорож у Тельдрассилі, Заррін — головний наставник, який учить обертати м'ясо диких звірів і зібрані дари лісу на поживні страви.",["race:NightElf"]="Заррін береже повсякденні калдорейські харчові звичаї, дбаючи, щоб традиційні смаки й способи жили далі під шатром Світового Дерева."},sec={{t="Хранитель вогнища Доланаара",b="Облаштувавшись за корчмою Доланаара, осторонь головної вулиці, Заррін доглядає відкритий вогонь, біля якого ділиться кулінарним мистецтвом калдореїв. Виживання в Тельдрассилі вимагає користуватися корінною рослинністю й звіриною велетенського дерева, і Заррін навчає тих, хто хоче прогодувати себе збиральництвом і домашніми стравами."}},faq={{q="Де знайти Зарріна?",a="Заррін стоїть за корчмою в Доланаарі на Тельдрассилі й куховарить над вогнищем на відкритому подвір'ї навпроти дороги.",al={"місце заррін","де заррін","тренер кулінарії доланаара"}},{q="Чого навчає Заррін?",a="Він наставник Кулінарії, що навчає новачків основ куховарства й традиційних рецептів нічних ельфів.",al={"тренер заррін","чого навчає заррін"}},{q="Які завдання дає Заррін?",a="Заррін просить мандрівників допомогти йому готувати традиційні страви й дає завдання «Рецепт калдореїв», щоб навчити новоприбулих місцевих кулінарних звичаїв.",al={"завдання заррін","завдання рецепт калдореї"}}},fp="6,221,24.345.0,24.119.0,23.116.0,29.150.0"}
P.entries["npc:zenn-foulhoof"] = {n="Зенн Фаулгуф",s="Зенн Фаулгуф — сатир, що тиняється одразу на схід від Доланаара в Тельдрассилі. Він підходить до перехожих із проханнями про лісові складники, а тутешні нічні ельфи пильно за ним стежать.",h="Зенн Фаулгуф — сатир, що тиняється одразу на схід від Доланаара в Тельдрассилі.",kw={"зенн фаулгуф","сатир","доланаар","складники","жаба","тельдрассил","шахрай"},ang={["class:Druid"]="Втручання Зенна в дикі складники й свідоме поширення споганення прямо суперечить науці Кола Кенарія, яка прагне зберегти Тельдрассил незайманим.",["race:NightElf"]="Сатири — найбільша зрада калдорейського спадку. Бачити, як один із них розсівся на священному вітті Тельдрассила, — образа Елуні й духам дикого краю."},sec={{t="Інтриган у лісі",b="На відміну від більшості сатирів — відвертих ворогів на службі демонічних володарів, — Зенн Фаулгуф якось добився хисткого терпіння до себе одразу за Доланааром. Він підтримує дружню личину, запевняючи, що змінився або хоче торгувати нешкідливими лісовими складниками — іклами нічних шаблезубів, перами стригідних сов і павутинним шовком Вебвуда. Насправді ж він маніпулює довірливою молоддю, щоб добути складники для огидних обрядів. Рада Доланаара не дозволяє йому діяти безкарно: замість стратити його негайно, вона велить шукачам пригод принизити його, нагодувавши споганеним лісовим плодом, що на якийсь час обертає підступного сатира на нешкідливу жабу."}},faq={{q="Чому нічні ельфи одразу не нападають на Зенна Фаулгуфа?",a="Зенн тримає приязну личину й поки що відкрито не вчинив звірств на Світовому Древі, тож рада Доланаару карає його прилюдним приниженням і наглядом, а не смертним вироком.",al={"чому нічні ельфи не нападають на зенна","чому зенн дружній","чи зенн фаулгуф злий"}},{q="Що стається, коли згодовуєш Зеннові зіпсовані шишки й ягоди?",a="Старійшини Доланаару наказують це як покуту за Зеннові провини. Чим обертається ця кара, видно, коли він з'їдає зіпсовані плоди.",al={"завдання спокути зенна","завдання шукай спокути","зенн жаба"}},{q="Хто такі сатири?",a="Сатири — нічні ельфи, яких під час Війни Прадавніх, після того як вони присягнули служити Палаючому Легіону, спотворило на рогатих, ратицевих чортів. Більшість із них украй зіпсовані й люто ворожі до своїх незіпсованих родичів.",al={"що таке сатири","лор сатирів"}}},fp="13,183,22.640.1,64.230.0,64.140.1,16.224.0"}
P.entries["npc:zevrost"] = {n="Зеврост",s="Зеврост — орк, наставник чорнокнижників, що усамітнився в підземній Тіньовій Розколині під Оргріммаром. Він наставляє чорнокнижників Орди, ведучи їх крізь небезпечні науки магії Скверни, ритуалів прикликання й прив'язування темних артефактів.",h="Зеврост — орк, наставник чорнокнижників, що усамітнився в підземній Тіньовій Розколині під Оргріммаром.",kw={"зеврост","чорнокнижник","тіньова розколина","кінь скверни","сфера орагіла","менара войдрендер"},ang={["class:Warlock"]="Для чорнокнижників Орди Зеврост — важливий наставник: він відкриває поглиблені закляття й посилає посвячених по особливу зброю, речі для другої руки й вогняного коня.",["race:Orc"]="Живучи серед оркського суспільства, що здебільшого цурається демонічної магії, Зеврост представляє тих адептів, які й досі вдаються до темних мистецтв під пильним наглядом Вождя."},sec={{t="Майстер темних мистецтв",b="Захований глибоко в печерах Тіньової Розколини, Зеврост — один із головних наставників чорнокнижників Орди в столиці Тралла. Оркське суспільство загалом сторожко ставиться до енергії Скверни, пам'ятаючи демонічне зіпсуття свого минулого, проте таких адептів, як Зеврост, терплять під суворим наглядом. Він прищеплює учням сувору дисципліну, без якої не повелівати демонічними силами, не піддавшись їхній руйнівній природі, і наголошує: Скверна губить лише тих, кому бракує внутрішньої сили."},{t="Провідник для честолюбних",b="Окрім основ заклять і прокльонів, Зеврост — провідник до сміливіших темних звершень. Посвячені, що шукають особливих знарядь — як-от Сфери Орагіла чи способу прикликати вогняного скакуна Скверни, — часто проходять через його руки. Він скеровує честолюбних адептів до інших майстрів ремесла, як-от до Менари Войдрендер у Пустках, щоб ті, хто володіє магією тіні, сягали межі своїх можливостей."}},faq={{q="Хто такий Зеврост?",a="Зеврост — орк, наставник чорнокнижників у Тіньовій Розколині під Оргріммаром. Він навчає новачків і досвідчених чорнокнижників Орди нових заклинань і веде їх крізь ключові обряди класу.",al={"роль зевроста","хто такий зеврост","зеврост нпс"}},{q="Де знайти Зевроста?",a="Він живе в підземній печері, відомій як Тіньова Розколина, під головними кварталами Оргріммара.",al={"місце зевроста","де зеврост","знайти зевроста"}},{q="Чому чорнокнижникам на кшталт Зевроста дозволено бути в Оргріммарі?",a="Хоча Орда Тралла суворо обмежує й пильнує темне чаклунство через історію орків із демонічною кров'ю, чорнокнижникам дозволено практикувати у відлюдних глибинах Тіньової Розколини, бо їхня безжальна сила цінна проти численних ворогів Орди.",al={"чому чорнокнижникам дозволено в оргріммарі","чорнокнижники в тіньовій розколині"}},{q="Що Зеврост думає про демонічну магію?",a="Зеврост переконаний, що темна й таємна сила розбещує лише слабких духом. Він закликає учнів тримати в навчанні залізну дисципліну, щоб не скоритися руйнівним силам, якими вони керують.",al={"цитата зевроста","переконання зевроста"}}},fp="7,254,23.508.0,21.457.0,15.193.0,27.116.0,53.259.0,46.213.0"}
P.entries["npc:zjolnir"] = {n="Зйолнір",s="Зйолнір — троль Темного Списа, заводчик їздових тварин у Селі Сен'джин на південному узбережжі Дуротару. Він постачає навчених їздових рапторів Темному Спису та надійним чемпіонам Орди. Для тролів-вершників його стайня лютих, відданих звірів — предмет глибокої культурної гордості.",h="Зйолнір — троль Темного Списа, заводчик їздових тварин у Селі Сен'джин на південному узбережжі Дуротару.",kw={"зйолнір","раптори","їздові тварини","сен'джин","темний спис","заводчик","дуротар"},ang={["faction:Horde"]="Кожен воїн Орди, що доведе непохитну відданість племені Темного Списа, може заслужити привілей їхати в бій на одному з рапторів Зйолніра.",["race:Troll"]="Для тролів Темного Списа Зйолнір постачає прудких кігтистих звірів, що є осердям їхньої спадщини та бойових традицій."},sec={{t="Заводчик рапторів Темного Списа",b="Зйолнір, що порається біля загонів Села Сен'джин, доглядає лютих рапторів, яких тролі Темного Списа полюбляють як їздових тварин. Раптори норовливі й хижі від природи, тож вирощувати їх і сідлати для війни може лише досвідчена рука. Зйолнір охоче дає цих цінних звірів, слухняних свистку, тролям-побратимам, які опанували потрібне мистецтво верхової їзди. Чужинці з ширшої Орди спершу мають заслужити найвищу довіру племені Темного Списа, перш ніж Зйолнір подумає довірити їм когось зі своєї зграї."}},faq={{q="Де знайти Зйолніра?",a="Зйолнір перебуває в Селі Сен'джин — прибережному поселенні Темного Списа на півдні Дуротару, біля загонів для ящерів.",al={"місце зйолніра","де зйолнір","торговець раптором"}},{q="Що продає Зйолнір?",a="Зйолнір продає ящерів, яких викликають свистком, — характерних расових їздових тварин Тролів Темного Списа. У нього є різні породи й масті як для щойно навчених вершників, так і для досвідчених ветеранів.",al={"торговець зйолнір","що він продає","торговець тролячими їздовими"}},{q="Чи можуть не-тролі купити в нього ящерів?",a="Так, але не-тролі мають спершу здобути звеличену репутацію в Тролів Темного Списа, і лише тоді Зйолнір їм продаватиме. Тролі можуть купувати в нього одразу, щойно мають потрібну навичку верхової їзди.",al={"чи орки можуть купити раптора","хто купує їздових у зйолніра","раптор орди"}}},fp="7,289,32.501.0,25.154.0,23.200.0,36.192.0"}
P.entries["npc:zor-lonetree"] = {n="Зор Лоунтрі",s="Зор Лоунтрі — обізнаний орк-радник у Фортеці Ґроммаш в Оргріммарі. Добре знаючись на зовнішніх справах і політиці Альянсу, він допомагає Орді, досліджуючи ворожі артефакти й скеровуючи мандрівників у неспокійні краї Калімдору.",h="Зор Лоунтрі — обізнаний орк-радник у Фортеці Ґроммаш в Оргріммарі.",kw={"зор лоунтрі","радник","фортеця ґроммаш","альянс","гори кам'яного кігтя","оргріммар"},ang={["class:Shaman"]="Шамани, що відгукуються на поклик стривожених стихій, знайдуть спільну мову із Зором, який уважно стежить за стражданнями духів Гір Кам'яного Кігтя.",["faction:Horde"]="Для розвідників Орди, що діють поблизу людських анклавів чи спірних прикордонь, Зор Лоунтрі — важливий знайомий в Оргріммарі, що допоможе розгадати наміри ворога й значення його реліквій."},sec={{t="Радник у Фортеці Ґроммаш",b="Перебуваючи у Фортеці Ґроммаш поряд із верховним проводом Орди, Зор Лоунтрі — проникливий радник, що пильно стежить за подіями за межами Дуротару. Він на диво добре розуміється на політиці людей і Альянсу, тож стає неоціненним порадником, коли до столиці доходять чужоземні дивовижі чи політичні загрози. Чи то оглядаючи шляхетні прикраси, здобуті в людських поселеннях, чи то стежачи за неспокоєм духів землі в Горах Кам'яного Кігтя, Лоунтрі дбає, щоб двір вождя знав про справи і буденні, і містичні."}},faq={{q="Хто такий Зор Лоунтрі?",a="Зор Лоунтрі — орк-порадник у Фортеці Ґроммаш в Оргріммарі. Він відомий своїм розумом, розумінням політичного устрою Альянсу й цікавістю до духовних справ Калімдору.",al={"хто такий зор","зор лоунтрі","зор оргріммар"}},{q="Де знайти Зора Лоунтрі?",a="Ви знайдете його у Фортеці Ґроммаш, у Долині Мудрості, в самому серці Оргріммара.",al={"місце зора лоунтрі","де зор лоунтрі","зор в оргріммарі"}},{q="Які завдання Зор Лоунтрі дає шукачам пригод?",a="Зор Лоунтрі посилає поборників Орди на допомогу духам Піку Кам'яного Кігтя — вгамувати неспокій стихій у Горах Кам'яного Кігтя. Крім того, він вивчає дивні людські реліквії, які розвідники приносять до столиці.",al={"завдання зора лоунтрі","духи стоунталона зор"}},{q="Чому Зор Лоунтрі так добре знає Альянс?",a="На відміну від багатьох воїнів передової, Зор спеціалізується на зовнішніх справах і державних питаннях. Він вивчає звичаї людської знаті й пересування Альянсу, тож уміє розгадати шляхетські печатки, регалії й тактичні задуми, яких інші орки не помітили б.",al={"чому зор знає альянс","політика альянсу зора"}}},fp="12,247,24.574.0,20.200.0,30.106.0,46.232.0,53.246.0"}
P.entries["npc:zureetha-fargaze"] = {n="Зуріта Фарґейз",s="Зуріта Фарґейз — орчиня-наставниця в Долині Випробувань у Дуроторі, що стоїть поряд із Наглядачем Тазз'рілом. Пильна до скверни, вона спрямовує молодих новобранців Орди розслідувати й викорінювати темний вплив культу Палаючого Клинка, що ховається в долині.",h="Зуріта Фарґейз — орчиня-наставниця в Долині Випробувань у Дуроторі, що стоїть поряд із Наглядачем Тазз'рілом.",kw={"зуріта фарґейз","палаючий клинок","культ","долина випробувань","медальйон","скверна","дуротар"},ang={["class:Warlock"]="Чорнокнижники в Долині Випробувань рано стикаються з дорученнями Зуріти, маючи справу з дикими, оскверненими мерзенними фамільярами, пов'язаними з темними прикликаннями Палаючого Клинка.",["race:Orc"]="Для молодих орків, що роблять перші кроки у світ, Зуріта втілює невсипущу пильність, потрібну, щоб демонічна скверна минулого не отруїла їхню нову батьківщину."},sec={{t="Очі в долині",b="Поки Наглядач Тазз'ріл наглядає за працею й дисципліною молодих орків і тролів Темного Списа, Зуріта Фарґейз пильнує тонші, підступніші загрози. Культ Палаючого Клинка таємно проник у Долину Випробувань: він спотворює менших демонів і набирає сили в сусідній печері — Ковені Палаючого Клинка. Зуріта доручає неперевіреним шукачам пригод відібрати в культистів медальйони, щоб підтвердити їхню присутність і зруйнувати їхні перші задуми, перш ніж відправити загартованих новобранців далі, у Дуротар."}},faq={{q="Хто така Зуріта Фарґейз?",a="Зуріта Фарґейз — орчиха, що дає завдання в Долині Випробувань у Дуротарі. Вона стоїть біля Наглядача Тазз'ріла й стежить за прихованими загрозами, що прокрадаються на тренувальні угіддя.",al={"лор зуріти фарґейз","хто така зуріта","фарґейз долина випробувань"}},{q="Чому її турбує Палаючий Клинок?",a="Демонічний культ Палаючого Клинка вкоренився в печері неподалік, приманює мерзенних поплічників і псує мирні угіддя випробувань. Зуріта шукає доказів їхньої присутності — медальйонів культистів — і посилає новобранців прорідити їхні лави.",al={"палаючий клинок долина випробувань","навіщо зуріті медальйони","культ палаючого клинка дуротар"}},{q="Куди вона посилає новобранців після перших випробувань?",a="Коли молоді орки й тролі доведуть свою вправність проти місцевих загроз, Зуріта посилає їх на південний схід через гребінь до Села Сен'джин — допомагати племені Темного Списа.",al={"де після зуріти","наступне завдання зуріти","доповісти сен'джину"}}},fp="16,268,18.523.0,24.185.0,45.247.0,56.175.0"}
P.entries["quest:100"] = {n="Поклик води",s="Цей обрядовий крок увінчує випробування шамана біля Жаровні Вічного Джерела на узбережжі Срібнолісся. Розбивши спалахом стихійного сяйва зіпсованих духів, що загрожували джерелу, шаман стає перед видінням чистої води, щоб прийняти його причастя.",h="Цей обрядовий крок увінчує випробування шамана біля Жаровні Вічного Джерела на узбережжі Срібнолісся.",kw={"поклик води","малий прояв води","шамани","жаровня вічного джерела","срібнолісся","стихії"},ang={["class:Shaman"]="Це причастя прямо випробовує рішучість шамана зцілювати страждаючі води далеко від рідних країв — і дарує йому єднання з самим духом води.",["faction:Horde"]="Духовні проводирі Орди мусять очищати зіпсовані водойми навіть на землях під владою Відступників, як-от у Срібноліссі, щоб берегти стихійну рівновагу."},sec={{t="Спалах очисного світла",b="Коли біля Жаровні Вічного Джерела промовлено останнє заклинання, спалах світла випалює навколишню скверну. Сичання отруєних крапель води, що випаровуються над стихійним полум'ям, стихає, і берег поблизу замовкає, а злісні малі духи розсіюються."},{t="Вдячність води",b="Щойно духів знищено, біля жаровні з'являється Малий Прояв Води. Вдячний за обрядове втручання, дух визнає, який тягар дедалі більше лягає на шаманів Орди: хоч місцева скверна відступила, життя в занепалих землях Срібнолісся й далі згасає, і щоб його вберегти, потрібна пильність."}},faq={{q="Що стається, коли обряд біля жаровні завершується?",a="Коли закляття біля Жаровні Вічного Джерела завершено, вибухає сліпуче світло. Воно знищує довколишніх зіпсованих духів і очищує місцевий плин стихії.",al={"світло біля жаровні","вибух вічного джерела"}},{q="Хто такий Малий Прояв Води?",a="Це невелика елементальна істота з чистої води, яка з'являється після того, як знищено зіпсованих елементалів біля Жаровні Вічного Джерела.",al={"дух води сільверпайн","прояв води"}},{q="Що дух води каже про Срібнолісся?",a="Дух дякує шаманам і зауважує: хоч цю скверну й відкинуто, життя по всьому краю й далі згасає, і щоб його вберегти, потрібна постійна опіка.",al={"застереження духа води","скверна сільверпайну"}},{q="Де відбувається цей обряд?",a="Обряд відбувається біля Жаровні Вічного Джерела на узбережжі Срібнолісся.",al={"місце жаровні","місце поклику води"}},{q="Чому шамани мусять втрутитися в Срібноліссі?",a="У межах випробувань стихій, щоб здобути Тотем Води, шамани мають довести відданість рівновазі, захищаючи далекі, обложені природні води від пошесті й залишків скверни.",al={"чому шамани мусять втрутитися","обов'язок шамана сільверпайн"}},{q="Що далі у випробуваннях?",a="Порадившись із Малим Проявом Води, шаман отримує рештки стихії чи настанову, щоб завершити шлях і викувати свій Тотем Води.",al={"наступний крок поклику води","після прояву води"}}},fp="13,307,26.284.0,21.343.0,46.187.0,40.135.0,48.184.0,34.102.0,41.190.0,30.160.0"}
P.entries["quest:1001"] = {n="Дзижчалка 411",s="«Дзижчалка 411» — завдання Альянсу на продуваному вітрами березі Темного Узбережжя. Через химерну мережу механічних ретрансляторів підпилий гном-винахідник Візбанґ Кранктоґґл просить мандрівників зібрати очі прибережних молотильників, щоб знову запустити свою другу дослідницьку машину.",h="«Дзижчалка 411» — завдання Альянсу на продуваному вітрами березі Темного Узбережжя.",kw={"дзижчалка 411","візбанґ кранктоґґл","молотильники","око молотильника","обердайн","темне узбережжя"},ang={["profession:Engineering"]="Калібрувати механічний передавач органічними очима молотильників — це ексцентричні методи на межі можливого, які так полюбляють нестандартні майстри.",["race:Gnome"]="Візбанґ Кранктоґґл втілює класичний гномський підхід до польової роботи: сміливі винаходи, дивний вибір деталей і доручення небезпечних запливів першому-ліпшому перехожому.",["race:NightElf"]="Вартові Обердайна пильно стежать за водами Темного Узбережжя, хоча дивні гномські пристрої на березі зазвичай полишають напризволяще."},sec={{t="Голос крізь перешкоди",b="Коли мандрівники допомогли полагодити Дзижчалку 827 південніше, голос гнома-винахідника Візбанґа Кранктоґґла знову тріщить у механічному передавачі. Сховавшись десь у безпечному місці, Візбанґ посилає шукачів пригод далі на північ імлистим пляжем Темного Узбережжя, щоб знайти ще один пошкоджений термінал — Дзижчалку 411. Між передачами, які раз у раз перериває гикавка й бурмотіння на хвалу вину з повзунів, він повідомляє, що потрібні для його прибережного апарата деталі мають місцеві водяні хижаки."},{t="Очі під прибоєм",b="Щоб відновити Дзижчалку 411, доведеться пірнути в холодні, бурхливі води біля берегів Обердайна. На мілинах полюють молотильники Темного Узбережжя — агресивні морські звірі, чиї очі, за словами Візбанґа, мають саме ті властивості, що потрібні для переналаштування пристрою. Щойно потрібні очі молотильників опиняються в люку машини, апарат здригається й оживає, винагороджує кур'єра й відкриває лінію для чергового, дедалі невиразнішого доручення."}},faq={{q="Що таке Дзижчалка 411?",a="Дзижчалка 411 — механічний передавач на березі Темного Узбережжя, на північ від Обердайна. Вона входить до дослідної мережі прослуховування й досліджень, яку обслуговує гном-інженер Візбанґ Кранктоґґл.",al={"дзижчалка 411","що таке дзижчалка 411","призначення дзижчалки 411"}},{q="Хто такий Візбанґ Кранктоґґл?",a="Візбанґ Кранктоґґл — дивакуватий гном-майстер, що спілкується на відстані через мережу дзижчалок. Свої польові дослідження він проводить, щедро налягаючи на вино з повзунів, а небезпечну роботу — збирати частини звірів — перекладає на перехожих шукачів пригод.",al={"візбанґ","хто такий візбанґ","хто зробив дзижчалку"}},{q="Навіщо машині очі молотильників?",a="Гномська інженерія часто поєднує дивну органіку з механічними деталями для незвичних завдань. Чи справді Візбанґові потрібні очі для оптичних датчиків, чи він напідпитку використовує їх у біологічних дослідах, — він наполягає, що без них Дзижчалку 411 не полагодити.",al={"навіщо очі молотильників","очі молотильників для машини","очі дзижчалки"}},{q="Де стоїть Дзижчалка 411?",a="Дзижчалка 411 стоїть просто на пляжі Темного Узбережжя, на північ від поселення нічних ельфів Обердайн.",al={"де дзижчалка 411","місце дзижчалки 411","знайти дзижчалку 411"}},{q="Де знайти молотильників Темного Узбережжя?",a="Молотильники Темного Узбережжя плавають у прибережних водах біля Обердайна й уздовж сусідніх берегів — їх легко знайти, відпливши за смугу прибою.",al={"де молотильники","джерело очей молотильників","місце молотильників"}},{q="Що буде, коли Дзижчалку 411 полагоджено?",a="Щойно Дзижчалка 411 знову загуде, Візбанґ Кранктоґґл крізь тріск дякує вам, перехиляє ще чарку й одразу питає, чи не полагодите ви наступну його машину — Дзижчалку 323.",al={"наступна дзижчалка","що після дзижчалки 411","ланцюжок дзижчалок"}}},fp="11,290,24.527.0,21.473.0,20.227.0,27.259.0,38.285.0,29.111.0,36.138.0,40.182.0"}
P.entries["quest:1002"] = {n="Дзижчалка 323",s="«Дзижчалка 323» — третє завдання в низці польових досліджень на берегах Темного Узбережжя, яке через гучномовець доручає ексцентричний гном-інженер Візбанґ Кранктоґґл. Шукачі пригод мають зібрати ікла місячних скрадачів у місцевих хижаків і вкинути їх до гудучого пристрою на північ від Обердайна.",h="«Дзижчалка 323» — третє завдання в низці польових досліджень на берегах Темного Узбережжя, яке через...",kw={"дзижчалка 323","візбанґ кранктоґґл","ікло місячного скрадайла","місячні скрадачі","обердайн","темне узбережжя"},ang={["profession:Engineering"]="Серія дзижчалок поєднує автоматичну переробку матеріалів із далеким голосовим зв'язком — вражаюча технічна конструкція, попри грубу роботу.",["race:Gnome"]="Віддалена звукова мережа зв'язку Візбанґа — типовий гномський інженерний розмах, хоч особиста дисципліна винахідника лишає бажати кращого.",["race:NightElf"]="Нічні ельфи ставляться до лютих місячних скрадачів із шанобливою обережністю, а гномська наука перетирає їхні смертоносні ікла на паливо для машини."},sec={{t="Невиразна передача",b="Коли Дзижчалка 411 запрацювала південніше, з гучномовця знову лунає тріскучий голос гнома-винахідника Візбанґа Кранктоґґла. Перемежовуючи невиразні вказівки звуками рясного пиятикування, Візбанґ посилає шукачів пригод на північ, до Обердайна, — до Дзижчалки 323 біля дорожнього мосту. Для його досліджень потрібно шість Іклів Місячного Скрадайла, здобутих у лютих котів-мисливців, що нишпорять оповитими імлою лісами Темного Узбережжя."},{t="Гномська польова техніка",b="Дзижчалка 323 ще до ремонту тріщить перешкодами й ледь чутно бурмоче. Щойно потрібні ікла опиняються в її приймальному бункері, машина несамовито здригається й оживає, з гуркотом перетираючи зуби на порох. П'яний голос Візбанґа одразу ж лунає з передавача — він радіє доставці й підганяє мандрівника до наступної машини своєї розкиданої мережі."}},faq={{q="Де стоїть Дзижчалка 323?",a="Дзижчалка 323 стоїть при головній дорозі на північ від Обердайна, біля мосту через місцеву річку на Темному Узбережжі.",al={"місце дзижчалки 323","де дзижчалка 323","знайти дзижчалку 323"}},{q="Хто говорить через дзижчалку?",a="Це голос Візбанґа Кранктоґґла — гнома-винахідника, що сидить деінде на Темному Узбережжі й спілкується через віддалені передавачі, щедро налягаючи на ель.",al={"хто говорить у дзижчалці","гном із дзижчалки","візбанґ кранктоґґл"}},{q="Що Дзижчалка 323 робить з іклами?",a="Щойно ікла Місячних скрадачів потрапляють досередини, шестерні одразу перемелюють їх на дрібний порошок — так працює автоматичний механізм Візбанґа для збору біологічних зразків.",al={"що буде з іклами","навіщо ікла місячних скрадачів","дзижчалка меле"}},{q="Де на Темному Узбережжі знайти Місячних скрадачів?",a="Місячні скрадачі та їхні малюки никають затіненими лісами й пагорбами обабіч дороги на північ і на південь від Обердайна.",al={"де місячні скрадачі","ферма ікл місячних скрадачів","місце місячних скрадачів"}},{q="Яке завдання йде до і після «Дзижчалки 323»?",a="Це завдання йде після «Дзижчалки 411», де потрібні були очі молотильників, і просто перед «Дзижчалкою 525», яка посилає вас далеко на південь уздовж дороги по сиві скальпи будякових ведмедів.",al={"ланцюжок завдань дзижчалки","що після дзижчалки 323","порядок дзижчалок"}},{q="Чому Візбанґ говорить так безладно?",a="Даючи настанови, Візбанґ геть п'яний: він раз у раз змовкає, шукаючи свій ель, і між реченнями гучно сьорбає.",al={"чому візбанґ п'яний","голос дзижчалки невиразний"}}},fp="11,309,22.432.0,23.419.0,29.122.0,36.168.0,40.165.0,43.119.0,46.189.0,37.131.0"}
P.entries["quest:1003"] = {n="Дзижчалка 525",s="«Дзижчалка 525» — останній етап у низці машин зв'язку, розкиданих уздовж берегів Темного Узбережжя. Створений ексцентричним гномом-майстром Візбанґом Кранктоґґлом, пристрій вимагає для роботи рештки тварин і просить у мандрівників дедалі незвичніших матеріалів для ремонту.",h="«Дзижчалка 525» — останній етап у низці машин зв'язку, розкиданих уздовж берегів Темного Узбережжя.",kw={"дзижчалка 525","візбанґ кранктоґґл","темне узбережжя","будякові ведмеді","обердайн","пиво"},ang={["race:Gnome"]="Багатофункціональні передавачі Візбанґа — типова гномська амбіція, що поєднує складну інженерію з вельми сумнівними практичними пріоритетами.",["race:NightElf"]="Сувора опіка над Темним Узбережжям не лишає терпіння для безрозсудних гномських забавок із механізмами."},sec={{t="Невиразна передача",b="Обслуживши Дзижчалку 323, мандрівники отримують плутані вказівки просто з торохтливих гучномовців машини. Мова Візбанґа Кранктоґґла стає дедалі невиразнішою: п'яні смішки й безладні пояснення ведуть далеко на південь головною дорогою Темного Узбережжя. Він велить своїм помічникам вполювати місцевих сивих будякових ведмедів і вкласти чотири їхні густі скальпи у відсік Дзижчалки 525, ретельно схованої за парканом у придорожніх кущах."},{t="Секрет винокура",b="Коли мандрівники дістаються захованої машини, цікаве гудіння механізмів заглушає галасливий спів, що лунає з-під залізної обшивки. Щойно скальпи ведмедів опиняються у приймачі, Візбанґ нарешті зізнається, що насправді являє собою його мережа. Ці пристрої — не просто обладнання зв'язку: вони водночас автоматичні мініпивоварні й винокурні. Зневажаючи суворі й тверезі звичаї нічних ельфів Обердайна, гном збудував свої машини, щоб гнати заборонені лісові наливки, — і з тваринної сировини на кшталт ведмежих скальпів варить міцні партії «будякового ведмежого пива»."}},faq={{q="Де стоїть Дзижчалка 525?",a="Дзижчалка 525 стоїть далеко на південь від Обердайна, при головній дорозі. Візбанґ сховав її трохи осторонь стежки, біля простого дерев'яного тину, і її частково затуляють кущі.",al={"місце дзижчалки 525","де дзижчалка 525","знайти дзижчалку 525"}},{q="Навіщо Візбанґові сиві скальпи?",a="Візбанґ запевняє, що скальпи потрібні для ремонту Дзижчалки 525, так само як попереднім машинам потрібні були ноги повзунів, очі молотильників та ікла місячних скрадачів. Проте п'яна пісенька про будякове ведмеже пиво, що лунає з дзижчалки, натякає на іншу мету.",al={"навіщо сиві скальпи","скальпи ведмедів для дзижчалки","для чого скальпи"}},{q="Чому Візбанґ ховає дзижчалки в нетрях?",a="Візбанґ поставив машини за межами Обердайна й покладається на те, що до них дійдуть мандрівники. Чому він обрав ці відлюдні місця, з'ясовується біля останньої дзижчалки.",al={"чому дзижчалки сховані","навіщо ховати дзижчалку","таємниця візбанґа"}},{q="Хто говорить через дзижчалку?",a="Це голос Візбанґа Кранктоґґла — заповзятливого гнома-майстра, який вмонтував передавачі голосу у свої дзижчалки по всьому Темному Узбережжю.",al={"хто говорить у дзижчалці","голос дзижчалки","хто такий візбанґ"}},{q="Чи може Візбанґ говорити через машину без скальпів?",a="Так. Візбанґ може говорити через машину ще до того, як у неї покладуть скальпи. А пояснення, навіщо йому ці матеріали, він дає, коли завдання виконано.",al={"чи дзижчалка зламана","чи візбанґ збрехав"}},{q="Яку пісню співає дзижчалка?",a="Поки ви не поклали скальпи, гучномовець раз у раз виспівує п'яний віршик: «Хоч вино з повзунів — і солодке, й п'янке, і ель з молотильника — смак неабиякий, і місячний самогон зі скрадачів — хоч куди, та нема миліш за будякове ведмеже пиво — і скоро я матиму кухоль, гляди!»",al={"дзижчалка співає","пісня про чортополохового ведмедя"}}},fp="11,287,22.492.0,22.604.1,29.164.0,38.233.1,58.145.1,36.144.0,57.148.1,32.255.0"}
P.entries["quest:1007"] = {n="Стародавня статуетка",s="Тален, ельф, що отаборився біля небезпечного Зорамського Узмор'я на північному заході Ашенвалю, шукає втрачену реліквію. Коли люті наги напали на нього й викинули на берег, він загубив у прибої свою дорогоцінну прадавню статуетку, і тепер йому потрібен шукач пригод, який забере її з руїн.",h="Тален, ельф, що отаборився біля небезпечного Зорамського Узмор'я на північному заході Ашенвалю, шукає...",kw={"стародавня статуетка","тален","зорамське узмор'я","наги","зорам","завдання"},ang={["faction:Alliance"]="Сили Альянсу, що просуваються Ашенвалем, стикаються із загрозами не лише від застав Орди на сході, а й від ворожих наг, які зазіхають на західне узбережжя.",["race:NightElf"]="Руїни Зорама — це втрачена цивілізація калдореїв із часів до Великого Розколу, тож збереження таких артефактів, як ця статуетка, — справа пам'яті предків."},sec={{t="Засідка на узбережжі",b="Затонулі руїни Зорама вздовж північно-західного берега Ашенвалю здавна вабили тих, кого цікавить прадавнє минуле нічних ельфів. Тален плив мілиною на невеликому човні, коли з води виринули ворожі наги й накинулися на нього з пазурами й тризубами. Йому вдалося видертися на берег із мізерними припасами й нашвидкуруч розбити табір, але у відчайдушній утечі він загубив у пісках свою найціннішу знахідку."},{t="Таємниці давнього Зорама",b="Прадавня статуетка, що лишилася напівзасипаною на пляжі, — не просто пам'ятна дрібничка. Тален вважає її єдиним виправданням того, що він наважився прийти на Зорамське Узмор'я, де кишать чудовиська. Коли статуетку повертають, він розповідає, що затоплене місто зберігає століття забутих таємниць, а ця тендітна різьба — важливий ключ до розуміння того, що досі ховається під хвилями."}},faq={{q="Хто такий Тален і чому він сам на Узмор'ї?",a="Тален — ельф-дослідник, що отаборився на південному краю Зорамського Узмор'я. Ведений цікавістю до історії, він вирушив досліджувати затонулі руїни Зорама, але люті наги напали на його човен, і його викинуло на берег.",al={"хто такий тален","лор талена","тален ясенлісся"}},{q="Де Тален загубив статуетку?",a="Тален загубив різьблену статуетку біля берега на північ від свого табору. Вона лежить напівзасипана піском біля перекинутого човна й поваленого дерева в смузі прибою, де напали на його судно.",al={"де статуетка","місце статуетки","знайти стародавню статуетку"}},{q="Що таке стародавня статуетка?",a="Це стародавня реліквія нічних ельфів, врятована із затонулих руїн Зорама. За словами Талена, різьблена статуетка має історичну й містичну вагу і є важливим ключем до таємниць, які досі зберігає затоплене місто.",al={"що таке статуетка","значення статуетки"}},{q="Звідки на Зорамському Узмор'ї наги?",a="На узбережжі Ашенвалю лежать руїни ельфійських споруд, давніших за Розкол, що десять тисяч років тому пішли під воду. Наги оголосили затонулі будівлі Зорама своєю територією й завзято патрулюють пляжі, відганяючи чужинців.",al={"чому тут наги","наги зорамського узмор'я","наги в ясенлісі"}},{q="Що буде, коли повернеш статуетку?",a="Повернута статуетка допомагає Таленові розгадати ще кілька таємниць краю. Але щоб упоратися із загрозою наг на узмор'ї, потрібні подальші дії, і Тален спрямовує вас до їхньої ватажки Руузел.",al={"що після статуетки","продовження завдання"}},{q="Чи хтось стереже статуетку?",a="Статуетка лежить біля самої води на землях, де аж кишить ворожими воїнами-нагами й хижаками, що чатують на березі, тож самотньому мандрівникові дістати її небезпечно.",al={"чи статуетку стережуть","вороги біля статуетки"}}},fp="21,275,19.422.0,20.368.0,47.222.0,35.181.0,30.229.0,39.241.0,43.204.1,25.167.0"}
